/* Original verse-by-verse Oneness study notes. Commentary is distinct from the KJV text. */
window.verseCommentary = {
  "Genesis 1:1": {
    "title": "God the Creator",
    "text": "The opening verse presents God as the source of the heavens and the earth. The text does not introduce a rival creator or explain God as one member of a group of gods. In a Oneness reading, this is the foundation: all creation depends on the one sovereign God. Later Scripture identifies Jesus in relation to creation, so compare those passages carefully without making Genesis say more than it states directly.",
    "refs": [
      "Deuteronomy 6:4",
      "Isaiah 44:24",
      "John 1:1–3",
      "Colossians 1:16–17"
    ]
  },
  "Genesis 1:2": {
    "title": "The Spirit of God",
    "text": "The earth is described as unformed and dark, while the Spirit of God moves over the waters. The verse shows God's active presence at creation. Oneness theology understands God's Spirit as God's own Spirit and presence, not a separate God. The wording here should be read alongside passages describing God's Spirit giving life and working in creation.",
    "refs": [
      "Psalm 104:30",
      "Job 33:4",
      "John 4:24",
      "Romans 8:11"
    ]
  },
  "Genesis 1:3": {
    "title": "God speaks light into being",
    "text": "God commands light to exist, and light appears. God's word is effective: creation responds to His command. A Oneness reading of John 1 often connects God's word with His self-expression and creative action; this verse is part of that biblical background, though it does not by itself explain every detail of John's prologue.",
    "refs": [
      "Psalm 33:6–9",
      "Psalm 119:105",
      "John 1:1–5",
      "2 Corinthians 4:6"
    ]
  },
  "Genesis 1:4": {
    "title": "God distinguishes light from darkness",
    "text": "God sees that the light is good and separates it from darkness. The passage describes order and distinction established by God's judgment. The verse does not identify light here as a separate divine person; it describes God's creative work. Later biblical uses of light may carry moral or spiritual meanings, but the creation setting should remain primary.",
    "refs": [
      "Genesis 1:3–5",
      "John 1:4–9",
      "1 John 1:5–7"
    ]
  },
  "Genesis 1:5": {
    "title": "The first day",
    "text": "God names the light Day and the darkness Night, and the first day is marked. Naming demonstrates God's authority over creation. The repeated pattern of evening and morning structures the account and emphasizes that the world is ordered by God's command, not by competing powers.",
    "refs": [
      "Psalm 74:16–17",
      "Isaiah 45:7",
      "Genesis 1:14–18"
    ]
  },
  "Genesis 1:6": {
    "title": "The firmament",
    "text": "God commands an expanse to divide the waters. The account presents the world as ordered by God's word. The theological emphasis is God's authority over the created realm, rather than a detailed modern scientific description. Read the whole creation sequence to see the repeated pattern of command, fulfillment, and divine evaluation.",
    "refs": [
      "Psalm 19:1",
      "Psalm 148:4–5",
      "Genesis 1:9"
    ]
  },
  "Genesis 1:7": {
    "title": "God makes the separation",
    "text": "The text says it happened as God commanded. The repeated fulfillment formula stresses that creation obeys its Creator. Oneness doctrine begins here with the uniqueness and sovereignty of God; this verse does not directly discuss the incarnation, but it establishes the Creator to whom the rest of Scripture bears witness.",
    "refs": [
      "Psalm 33:9",
      "Isaiah 40:25–26",
      "Acts 17:24–25"
    ]
  },
  "Genesis 1:8": {
    "title": "Heaven named",
    "text": "God names the expanse Heaven. As in the naming of Day and Night, the act signifies God's rule over the created order. The passage continues its measured sequence and invites the reader to see the world as dependent on God's will.",
    "refs": [
      "Psalm 115:15–16",
      "Nehemiah 9:6",
      "Genesis 1:14"
    ]
  },
  "Genesis 1:9": {
    "title": "Dry land appears",
    "text": "God gathers the waters so that dry land appears. The land and seas are not independent deities; they are parts of creation under God's authority. This supports the Bible's repeated rejection of worshipping created things instead of the Creator.",
    "refs": [
      "Psalm 95:5",
      "Psalm 104:5–9",
      "Romans 1:25"
    ]
  },
  "Genesis 1:10": {
    "title": "Earth and seas named",
    "text": "God names the dry land Earth and the gathered waters Seas, then declares the result good. Naming and evaluation show divine authority and purposeful order. The verse contributes to the creation account's central claim that the world belongs to God.",
    "refs": [
      "Psalm 24:1–2",
      "Psalm 95:5",
      "Revelation 10:6"
    ]
  },
  "Genesis 1:11": {
    "title": "Vegetation by God's command",
    "text": "God commands the earth to bring forth plants and fruit-bearing trees. The life-producing earth acts within the order God establishes; it is not itself the ultimate source of life. The verse shows provision and fruitfulness as gifts of the Creator.",
    "refs": [
      "Psalm 104:14",
      "Acts 14:17",
      "Matthew 6:28–30"
    ]
  },
  "Genesis 1:12": {
    "title": "Creation brings forth as commanded",
    "text": "The earth produces vegetation according to its kinds, and God sees that it is good. The repeated phrase according to its kind emphasizes the ordered character of creation in this account. The theological point is the faithfulness and wisdom of God's creative command.",
    "refs": [
      "Genesis 1:11",
      "Psalm 136:25",
      "James 1:17"
    ]
  },
  "Genesis 1:13": {
    "title": "The third day",
    "text": "The third day closes with the recurring evening-and-morning formula. The structure reminds the reader that creation unfolds under God's direction. Observe the pattern across the chapter rather than isolating one day from the whole account.",
    "refs": [
      "Genesis 1:5",
      "Genesis 1:31",
      "Exodus 20:11"
    ]
  },
  "Genesis 1:14": {
    "title": "Lights for signs and seasons",
    "text": "God appoints the heavenly lights to mark days, years, and seasons. They serve the Creator's purposes; they are not gods to be worshipped or feared as sovereign powers. This is an important biblical contrast with cultures that deified the sun, moon, and stars.",
    "refs": [
      "Deuteronomy 4:19",
      "Psalm 74:16–17",
      "Jeremiah 10:2"
    ]
  },
  "Genesis 1:15": {
    "title": "Lights in the heavens",
    "text": "The lights give light upon the earth, and the text says it was so. The account continues to stress that the created lights obey God's command. The verse supports the distinction between the Creator and the things He made.",
    "refs": [
      "Psalm 19:1",
      "Psalm 136:7–9",
      "Acts 17:24"
    ]
  },
  "Genesis 1:16": {
    "title": "The greater and lesser lights",
    "text": "The sun and moon are described by their functions rather than named as deities. The account demotes them from objects of worship to created servants within God's order. This fits the Bible's consistent call to worship the LORD alone.",
    "refs": [
      "Deuteronomy 4:19",
      "Psalm 8:3",
      "Isaiah 40:26"
    ]
  },
  "Genesis 1:17": {
    "title": "Placed in the heavens",
    "text": "God sets the lights in the firmament to shine on the earth. Their placement and function are assigned by God. The emphasis is not on independent cosmic powers but on a creation ordered and sustained by the one Creator.",
    "refs": [
      "Genesis 1:14–18",
      "Psalm 104:19",
      "Nehemiah 9:6"
    ]
  },
  "Genesis 1:18": {
    "title": "To rule day and night",
    "text": "The lights govern the rhythms of day and night and divide light from darkness. Their rule is limited and delegated within creation; God remains the sovereign Creator. The text should not be used to give heavenly bodies spiritual authority over human destiny.",
    "refs": [
      "Psalm 136:7–9",
      "Isaiah 47:13–14",
      "Jeremiah 10:2"
    ]
  },
  "Genesis 1:19": {
    "title": "The fourth day",
    "text": "The fourth day completes the creation of the lights and follows the same day-ending pattern. The structure reinforces the intentional order of the chapter. Compare the parallel movement from forming realms to filling them as you read the whole account.",
    "refs": [
      "Genesis 1:3–5",
      "Genesis 1:14–19",
      "Exodus 20:11"
    ]
  },
  "Genesis 1:20": {
    "title": "Living creatures in the waters and air",
    "text": "God commands the waters to teem with life and birds to fly. Life appears by God's command and blessing, not as an independent force outside His rule. The verse introduces the abundance of living creatures that fills the created environments.",
    "refs": [
      "Psalm 104:24–25",
      "Psalm 146:6",
      "Acts 17:25"
    ]
  },
  "Genesis 1:21": {
    "title": "Sea creatures and birds created",
    "text": "The text names great sea creatures and living things according to their kinds, then says God saw that it was good. Even creatures that may inspire fear remain part of God's creation. None is a rival to the Creator.",
    "refs": [
      "Job 12:7–10",
      "Psalm 104:25–26",
      "Psalm 148:7"
    ]
  },
  "Genesis 1:22": {
    "title": "God blesses living creatures",
    "text": "God blesses the creatures with fruitfulness and multiplication. Blessing is God's gift and command, showing that abundance and life depend on Him. The verse portrays God's care for creation before the narrative turns to humanity.",
    "refs": [
      "Genesis 8:17",
      "Psalm 104:27–30",
      "Matthew 6:26"
    ]
  },
  "Genesis 1:23": {
    "title": "The fifth day",
    "text": "The fifth day concludes the account of the creatures of the sea and air. The repeated formula gives the chapter a deliberate rhythm and emphasizes completion of each stage according to God's command.",
    "refs": [
      "Genesis 1:20–23",
      "Genesis 1:31",
      "Exodus 20:11"
    ]
  },
  "Genesis 1:24": {
    "title": "Land animals",
    "text": "God commands the earth to bring forth living creatures according to their kinds. As with vegetation, the earth produces life within the order established by God. The verse places land animals under the Creator's authority rather than treating them as divine beings.",
    "refs": [
      "Psalm 50:10–11",
      "Psalm 104:24",
      "Acts 14:15"
    ]
  },
  "Genesis 1:25": {
    "title": "God sees that the animals are good",
    "text": "God makes the animals and declares them good. The repeated evaluation indicates that creation has value because it comes from God's wise purpose. The verse also cautions against treating animals as either gods or worthless things; they belong to God's created order.",
    "refs": [
      "Genesis 1:31",
      "Psalm 104:24",
      "Proverbs 12:10"
    ]
  },
  "Genesis 1:26": {
    "title": "Let us make man",
    "text": "God says, “Let us make man in our image.” This plural wording has been interpreted in different ways. A Oneness reading compares it with verse 27, which immediately says God created humanity in His own image, and with the Bible's repeated confession that God is one. The text alone does not explicitly identify the “us”; avoid claiming that the grammar by itself settles every later theological debate. The image of God gives humanity dignity and responsibility.",
    "refs": [
      "Genesis 1:27",
      "Genesis 5:1–2",
      "Deuteronomy 6:4",
      "Isaiah 44:24"
    ]
  },
  "Genesis 1:27": {
    "title": "God created humanity in His image",
    "text": "The verse repeats that God created humanity in His own image and states that He created male and female. The singular emphasis on God as Creator is important when reading verse 26. In a Oneness study, this is a key control on interpretation: whatever the plural expression means, the narrative explicitly attributes creation to God. The image language concerns humanity's God-given status and calling; it should not be reduced to a claim that God has a physical body.",
    "refs": [
      "Genesis 5:1–2",
      "Genesis 9:6",
      "Deuteronomy 6:4",
      "James 3:9"
    ]
  },
  "Genesis 1:28": {
    "title": "Humanity blessed and commissioned",
    "text": "God blesses humanity and gives the command to be fruitful, multiply, fill the earth, and exercise stewardship over other creatures. Dominion is a responsibility under God, not permission for careless destruction. The verse shows that human authority is delegated and accountable to the Creator.",
    "refs": [
      "Genesis 2:15",
      "Psalm 8:4–8",
      "Psalm 115:16"
    ]
  },
  "Genesis 1:29": {
    "title": "Food provided by God",
    "text": "God provides plants and fruit for food. The verse presents provision as part of the goodness of creation and humanity's dependence on God. Read it within the original creation setting; later biblical passages address food practices in other covenantal and historical contexts.",
    "refs": [
      "Genesis 9:3",
      "Psalm 104:14–15",
      "Acts 14:17"
    ]
  },
  "Genesis 1:30": {
    "title": "Provision for living creatures",
    "text": "God provides green plants for the animals and birds. The verse extends the picture of divine provision beyond humanity to other living creatures. God's care for creation is part of the chapter's account of a world made and sustained by Him.",
    "refs": [
      "Psalm 104:27–30",
      "Psalm 145:15–16",
      "Matthew 6:26"
    ]
  },
  "Genesis 1:31": {
    "title": "Creation declared very good",
    "text": "God sees everything He has made and calls it very good. The chapter closes with the Creator's approval of the ordered whole. This is the foundation for a biblical view of creation as God's work, humanity as accountable to Him, and life as a gift. Christian teaching about redemption should be connected to this creation account without confusing the Creator with the created order.",
    "refs": [
      "Genesis 2:1–3",
      "Psalm 19:1",
      "1 Timothy 4:4",
      "Revelation 4:11"
    ]
  },
  "Genesis 2:1": {
    "title": "The heavens and earth finished",
    "text": "The account declares the ordered work of creation complete. The verse presents the world as God's work, not the product of competing divine powers. In a Oneness study, this establishes the identity of the one Creator before later passages explain God's saving self-revelation in Christ.",
    "refs": [
      "Genesis 1:31",
      "Exodus 20:11",
      "Nehemiah 9:6"
    ]
  },
  "Genesis 2:2": {
    "title": "God rests on the seventh day",
    "text": "God ceases from the work of creation, not because He is weak, but because the work is complete. The Sabbath pattern later becomes a sign of covenant rest and a reminder that life is ordered by God. Read the creation account first, then consider how later Scripture develops the theme of rest.",
    "refs": [
      "Exodus 20:8–11",
      "Hebrews 4:4–10"
    ]
  },
  "Genesis 2:3": {
    "title": "The seventh day blessed and sanctified",
    "text": "God blesses and sets apart the seventh day. The verse gives the Sabbath its creation foundation. The emphasis is God's authority to bless and sanctify; later instructions about Sabbath observance should be read in their covenant setting.",
    "refs": [
      "Exodus 31:13–17",
      "Mark 2:27–28",
      "Hebrews 4:9–10"
    ]
  },
  "Genesis 2:4": {
    "title": "The generations of the heavens and earth",
    "text": "This verse introduces a focused account of humanity and the garden. Genesis 1 and 2 should be read together: chapter 1 gives the broad sequence of creation, while chapter 2 focuses on the human setting and relationships. The passage continues to present one LORD God as Creator.",
    "refs": [
      "Genesis 1:1–31",
      "Genesis 5:1"
    ]
  },
  "Genesis 2:5": {
    "title": "The land before cultivation",
    "text": "The verse describes the setting before rain and human cultivation. It prepares for the account of God's forming the man and providing a garden. The details should be read as part of the narrative's movement toward humanity's vocation, rather than as a separate doctrine about God.",
    "refs": [
      "Genesis 2:7–8",
      "Genesis 3:23"
    ]
  },
  "Genesis 2:6": {
    "title": "Water rises from the earth",
    "text": "A mist or stream waters the ground before the man is placed in the garden. The verse contributes to the picture of God's provision in the created environment. The narrative is about God's preparation of a place for human life and responsibility.",
    "refs": [
      "Genesis 1:9–13",
      "Genesis 2:8–10"
    ]
  },
  "Genesis 2:7": {
    "title": "God forms the man and gives life",
    "text": "The LORD God forms the man from the dust and breathes into him the breath of life. Humanity is both earth-formed and dependent on God's life-giving action. This does not say that humans are pieces of God's substance; it says life is received from Him. Compare other passages where God's Spirit gives life and where human life remains dependent on the Creator.",
    "refs": [
      "Job 33:4",
      "Psalm 104:29–30",
      "Isaiah 42:5",
      "Acts 17:25"
    ]
  },
  "Genesis 2:8": {
    "title": "God plants a garden in Eden",
    "text": "God prepares a garden and places the man there. The garden is a gift, and human life begins in a place of provision and fellowship with God. The narrative later contrasts this provision with the consequences of disobedience.",
    "refs": [
      "Genesis 2:15–17",
      "Genesis 3:23–24",
      "Revelation 22:1–3"
    ]
  },
  "Genesis 2:9": {
    "title": "Trees pleasing and the tree of life",
    "text": "The garden contains trees that are good for food, including the tree of life and the tree of the knowledge of good and evil. The narrative distinguishes God's generous provision from the one boundary He sets. The symbolism of these trees should be interpreted through the story and later Scripture, not by speculation alone.",
    "refs": [
      "Genesis 3:22–24",
      "Proverbs 3:18",
      "Revelation 2:7",
      "Revelation 22:2"
    ]
  },
  "Genesis 2:10": {
    "title": "A river waters the garden",
    "text": "The river emphasizes the garden's abundance and provision. The description locates the garden in the narrative's world; the theological emphasis is that God prepares a fruitful home for humanity. Later biblical imagery also uses life-giving water, but this verse first describes the garden itself.",
    "refs": [
      "Psalm 46:4",
      "Ezekiel 47:1–12",
      "Revelation 22:1"
    ]
  },
  "Genesis 2:11": {
    "title": "The river and Havilah",
    "text": "The text names a region associated with one branch of the river. These geographical details help ground the story in the world as the narrator describes it. The verse does not directly teach the nature of the Godhead; its role is to describe the setting God provided.",
    "refs": [
      "Genesis 2:10–14"
    ]
  },
  "Genesis 2:12": {
    "title": "The land's resources",
    "text": "The mention of gold and other resources depicts the land as rich and provisioned. Material things are part of creation and are not inherently divine. Scripture later warns against loving wealth or worshipping created things instead of God.",
    "refs": [
      "Genesis 1:31",
      "Deuteronomy 8:7–18",
      "1 Timothy 6:17"
    ]
  },
  "Genesis 2:13": {
    "title": "The river Gihon",
    "text": "The second river is named and associated with a region. The geographical references form part of the account's setting. Avoid turning uncertain identifications of ancient locations into firm doctrine; focus on what the text actually states.",
    "refs": [
      "Genesis 2:10–14"
    ]
  },
  "Genesis 2:14": {
    "title": "The river Euphrates",
    "text": "The Euphrates is named as one of the rivers. The reference connects the narrative to a recognizable ancient geographical world. It does not alter the chapter's main message: the LORD God made humanity and provided a place for it.",
    "refs": [
      "Genesis 15:18",
      "Deuteronomy 1:7"
    ]
  },
  "Genesis 2:15": {
    "title": "The man placed in the garden to tend and keep it",
    "text": "The man receives work before the fall: he is to cultivate and guard the garden. Work is therefore not itself a curse; painful toil enters later in Genesis 3. Human responsibility is delegated by God and should be exercised as stewardship, not ownership without accountability.",
    "refs": [
      "Genesis 1:28",
      "Genesis 3:17–19",
      "Colossians 3:23"
    ]
  },
  "Genesis 2:16": {
    "title": "God generously permits the trees",
    "text": "God's command begins with broad permission: the man may freely eat from the trees. The boundary that follows should be read against this generosity. Biblical obedience is not presented here as God withholding every good thing, but as a relationship in which the Creator has authority to command.",
    "refs": [
      "Genesis 2:9",
      "Deuteronomy 30:15–20"
    ]
  },
  "Genesis 2:17": {
    "title": "The command and warning about death",
    "text": "God forbids eating from the tree of the knowledge of good and evil and warns of death. The command establishes moral accountability and the seriousness of disobedience. Later Scripture describes sin and death as connected; this verse should be read with Genesis 3's account of the consequence and with the New Testament's teaching about sin and death.",
    "refs": [
      "Genesis 3:1–7",
      "Romans 5:12",
      "Romans 6:23"
    ]
  },
  "Genesis 2:18": {
    "title": "It is not good for the man to be alone",
    "text": "For the first time in the creation account, something is declared not good: the man's isolation. God determines to make a suitable helper for him. The verse presents companionship as God's provision and does not imply that the woman is lesser in worth; the following verses describe shared humanity and the creation of the woman.",
    "refs": [
      "Genesis 1:27–28",
      "Genesis 2:21–24",
      "Ecclesiastes 4:9–10"
    ]
  },
  "Genesis 2:19": {
    "title": "The animals brought to the man",
    "text": "The animals are formed and brought to the man for naming. The scene shows human responsibility within creation, while also preparing to show that no animal is a fitting counterpart for him. The verse should not be used to set animals against humanity as rivals; both are God's creatures, with different roles in the narrative.",
    "refs": [
      "Genesis 1:24–28",
      "Psalm 8:6–8"
    ]
  },
  "Genesis 2:20": {
    "title": "No suitable helper found among the animals",
    "text": "The man names the animals, but no suitable companion is found. This prepares for the creation of the woman and highlights the distinctive human relationship described next. Naming reflects delegated responsibility, while the lack of a counterpart shows that humanity's relational needs are not met by the animal world.",
    "refs": [
      "Genesis 2:18–23"
    ]
  },
  "Genesis 2:21": {
    "title": "God causes the man to sleep",
    "text": "God acts to form the woman while the man is in a deep sleep. The story emphasizes that the woman is God's work and gift, not the man's invention or possession. The narrative presents God's initiative in establishing human companionship.",
    "refs": [
      "Genesis 2:18",
      "Genesis 2:22"
    ]
  },
  "Genesis 2:22": {
    "title": "God makes the woman and brings her to the man",
    "text": "God forms the woman and brings her to the man. She shares the same human nature and dignity, and the relationship is established by God's action. A Oneness reading should keep the focus on the Creator's provision here; this verse does not directly describe the Father, Son, or Holy Spirit.",
    "refs": [
      "Genesis 1:27–28",
      "Genesis 2:23–24",
      "Matthew 19:4–6"
    ]
  },
  "Genesis 2:23": {
    "title": "Bone of my bones and flesh of my flesh",
    "text": "The man's words recognize the woman as sharing his humanity. The poetic declaration expresses kinship and closeness, not inferiority. The verse lays the groundwork for the marriage teaching that follows and is later quoted by Jesus when He discusses marriage.",
    "refs": [
      "Genesis 2:24",
      "Matthew 19:4–6",
      "Ephesians 5:28–31"
    ]
  },
  "Genesis 2:24": {
    "title": "One flesh in marriage",
    "text": "The narrative states the pattern of leaving parents, cleaving to one's wife, and becoming one flesh. Jesus later appeals to this creation account as foundational for marriage. The phrase describes a covenantal bodily and relational union; it should not be confused with the biblical confession that God is one, since the contexts and subjects differ.",
    "refs": [
      "Matthew 19:4–6",
      "Mark 10:6–9",
      "Ephesians 5:31"
    ]
  },
  "Genesis 2:25": {
    "title": "Naked and not ashamed",
    "text": "The man and woman are unashamed before the fall. The verse closes the chapter with innocence and openness before the account of temptation and shame in chapter 3. The contrast helps readers see the relational damage caused by disobedience.",
    "refs": [
      "Genesis 3:7–10",
      "Revelation 3:18"
    ]
  },
  "Genesis 3:1": {
    "title": "The serpent questions God's word",
    "text": "The serpent is described as subtle and begins by distorting God's command. Temptation often starts by misrepresenting what God said. Read the serpent's question alongside God's actual words in Genesis 2:16–17, and notice how the conversation shifts attention from God's generosity to a forbidden boundary.",
    "refs": [
      "Genesis 2:16–17",
      "John 8:44",
      "2 Corinthians 11:3"
    ]
  },
  "Genesis 3:2": {
    "title": "The woman recalls God's permission",
    "text": "The woman acknowledges that they may eat from the garden's trees. The conversation begins with the provision God gave, but the next verse shows how the command is altered in the retelling. The account warns readers to know God's word accurately and not let temptation redefine it.",
    "refs": [
      "Genesis 2:16",
      "Psalm 119:11"
    ]
  },
  "Genesis 3:3": {
    "title": "The forbidden tree and the command",
    "text": "The woman identifies the forbidden tree and repeats the warning, adding wording about not touching it that was not included in Genesis 2:17. The narrative does not explain why she says this, so avoid speculation. The central issue is whether God's clear command will be trusted and obeyed.",
    "refs": [
      "Genesis 2:17",
      "Deuteronomy 4:2",
      "Proverbs 30:5–6"
    ]
  },
  "Genesis 3:4": {
    "title": "The serpent denies the warning",
    "text": "The serpent directly contradicts God's warning about death. Temptation now presents God's word as false. The story exposes the conflict between trusting God's command and accepting a rival interpretation that promises freedom from consequences.",
    "refs": [
      "Genesis 2:17",
      "John 8:44",
      "Romans 6:23"
    ]
  },
  "Genesis 3:5": {
    "title": "The promise of being as gods",
    "text": "The serpent suggests that eating will open their eyes and make them like gods, knowing good and evil. The temptation appeals to independence and the desire to define good and evil apart from God's authority. In a Oneness study, this verse is not evidence for multiple true Gods; it records the serpent's claim, which the narrative portrays as deceptive.",
    "refs": [
      "Isaiah 14:12–15",
      "Ezekiel 28:2",
      "Romans 1:21–25"
    ]
  },
  "Genesis 3:6": {
    "title": "The woman eats and gives to her husband",
    "text": "The woman sees the tree as desirable, eats, and gives fruit to her husband, who also eats. The verse traces how desire, judgment, and action join in disobedience. The text explicitly says the man was with her and ate; it does not excuse either person's choice. Sin is presented as a human act of disobedience to God's command.",
    "refs": [
      "Romans 5:12–19",
      "1 Timothy 2:14"
    ]
  },
  "Genesis 3:7": {
    "title": "Their eyes open and shame begins",
    "text": "They recognize their nakedness and sew fig leaves together. The promised opening of their eyes does not bring the freedom the serpent implied; it brings shame and an attempt to cover themselves. The story begins to show the relational consequences of sin, including fear and hiding from God.",
    "refs": [
      "Genesis 3:10–11",
      "Romans 3:23",
      "Hebrews 4:13"
    ]
  },
  "Genesis 3:8": {
    "title": "They hide from the presence of the LORD",
    "text": "The man and woman hear the LORD God and hide among the trees. The language depicts a personal encounter in the garden; it should not be used to claim that God's divine nature is limited to a physical body. Scripture elsewhere teaches that God is Spirit, while also describing His appearances and actions in ways humans can understand.",
    "refs": [
      "Genesis 16:13",
      "Exodus 33:20",
      "John 4:24",
      "1 Timothy 1:17"
    ]
  },
  "Genesis 3:9": {
    "title": "God calls to the man",
    "text": "God asks, “Where art thou?” The question does not imply that God lacks knowledge; it draws the man into accountability and exposes the broken relationship. God takes the initiative to address the sinner, a pattern that can be compared with later biblical calls to repentance.",
    "refs": [
      "Genesis 4:9–10",
      "Isaiah 1:18",
      "Luke 19:10"
    ]
  },
  "Genesis 3:10": {
    "title": "Fear and hiding",
    "text": "The man says he was afraid because he was naked, so he hid. Sin has altered his response to God's presence: instead of openness, there is fear. The verse shows the personal consequence of disobedience and the human impulse to conceal guilt rather than confess it.",
    "refs": [
      "Psalm 32:3–5",
      "Proverbs 28:13",
      "1 John 1:8–9"
    ]
  },
  "Genesis 3:11": {
    "title": "God questions the man about his knowledge",
    "text": "God asks who told the man he was naked and whether he ate from the forbidden tree. The questions confront the act and invite an honest answer. The verse demonstrates that moral accountability is tied to God's command, not merely to human feelings of shame.",
    "refs": [
      "Genesis 2:16–17",
      "Romans 14:12"
    ]
  },
  "Genesis 3:12": {
    "title": "The man blames the woman and indirectly God",
    "text": "The man says the woman gave him the fruit and adds that God gave her to him. Rather than accepting responsibility, he shifts blame. The text exposes how sin damages trust and produces self-protection. The narrative records his words without endorsing his excuse.",
    "refs": [
      "Proverbs 19:3",
      "James 1:13–15"
    ]
  },
  "Genesis 3:13": {
    "title": "The woman blames the serpent",
    "text": "The woman says the serpent beguiled her. The serpent's deception is real in the story, but the account has already shown that both humans chose to disobey. Explanation does not erase accountability. Scripture calls people to confess sin rather than use another person's wrongdoing to deny their own.",
    "refs": [
      "2 Corinthians 11:3",
      "James 1:14–15",
      "1 John 1:9"
    ]
  },
  "Genesis 3:14": {
    "title": "The serpent is cursed",
    "text": "God pronounces judgment on the serpent and describes humiliation. The verse begins the judgment section after the disobedience. The passage should be read in its narrative order: the consequences are not arbitrary, but follow the rebellion against God's command.",
    "refs": [
      "Genesis 3:1–5",
      "Revelation 20:2"
    ]
  },
  "Genesis 3:15": {
    "title": "Enmity and the promised seed",
    "text": "God declares enmity between the serpent and the woman, and between their seed, and speaks of the woman's seed bruising the serpent's head while the serpent bruises his heel. Many Christians understand this as an early promise pointing ultimately to the Messiah's victory over Satan, developed through later Scripture. That messianic reading should be explained as a canonical interpretation rather than pretending every detail is fully explained in Genesis alone.",
    "refs": [
      "Romans 16:20",
      "Galatians 4:4",
      "Hebrews 2:14",
      "1 John 3:8"
    ]
  },
  "Genesis 3:16": {
    "title": "Pain and conflict in the fallen condition",
    "text": "God describes increased pain in childbearing and a damaged dynamic between the woman and her husband. The verse reports consequences of the fall; it should not be used to justify cruelty or to claim that domination is God's ideal for human relationships. Compare the creation account with Jesus' appeal to God's original purpose for marriage.",
    "refs": [
      "Genesis 1:27–28",
      "Genesis 2:24",
      "Matthew 19:4–8",
      "Ephesians 5:25"
    ]
  },
  "Genesis 3:17": {
    "title": "The ground is cursed because of Adam",
    "text": "God addresses the man and connects the curse on the ground with his disobedience. Work continues, but it will be marked by frustration and toil. The verse places human sin within a wider creation-wide consequence, a theme later Scripture connects with the hope of restoration.",
    "refs": [
      "Romans 8:20–22",
      "1 Corinthians 15:21–22"
    ]
  },
  "Genesis 3:18": {
    "title": "Thorns and thistles",
    "text": "The ground will produce thorns and thistles, making cultivation difficult. The verse is part of the description of toil after the fall. It shows that human rebellion has consequences beyond private feelings and affects the ordinary conditions of life.",
    "refs": [
      "Genesis 3:17–19",
      "Romans 8:20–22"
    ]
  },
  "Genesis 3:19": {
    "title": "Dust and death",
    "text": "The man will eat by the sweat of his face until he returns to the ground from which he was taken. The verse recalls Genesis 2:7 and declares mortality as a consequence of disobedience. The New Testament develops the contrast between Adam's death and the life God gives through Jesus Christ.",
    "refs": [
      "Genesis 2:7",
      "Romans 5:12–21",
      "1 Corinthians 15:21–22"
    ]
  },
  "Genesis 3:20": {
    "title": "Eve named as mother of all living",
    "text": "The man names his wife Eve because she is the mother of all living. The name is linked to life even in the middle of judgment. The verse moves the story toward God's provision and the continuing human family outside Eden.",
    "refs": [
      "Genesis 4:1–2",
      "Genesis 5:1–2"
    ]
  },
  "Genesis 3:21": {
    "title": "God clothes the man and woman",
    "text": "God makes coats of skins and clothes them. The text shows divine provision for the shame that followed sin. Some Christian interpretations see a pattern of sacrifice or atonement here, but the verse itself does not explicitly describe a sacrifice; present that connection as an inference, not as a direct statement of the text.",
    "refs": [
      "Genesis 3:7",
      "Exodus 28:42",
      "Isaiah 61:10"
    ]
  },
  "Genesis 3:22": {
    "title": "Knowing good and evil",
    "text": "God speaks of the man becoming like one of “us” in knowing good and evil and prevents him from taking from the tree of life. The plural wording has prompted different interpretations; this verse alone does not specify a doctrine of multiple divine persons. In the story, the central issue is that fallen humanity must not seize eternal life in its disobedient condition.",
    "refs": [
      "Genesis 1:26–27",
      "Genesis 3:5",
      "Deuteronomy 6:4"
    ]
  },
  "Genesis 3:23": {
    "title": "Sent out to cultivate the ground",
    "text": "God sends the man out of Eden to work the ground from which he was taken. Exile from the garden is a consequence of disobedience, but human life and responsibility continue. The verse prepares for the guarded way to the tree of life in the next verse.",
    "refs": [
      "Genesis 2:15",
      "Genesis 3:19",
      "Genesis 4:1–2"
    ]
  },
  "Genesis 3:24": {
    "title": "The way to the tree of life guarded",
    "text": "God drives the man out and places cherubim and a flaming sword to guard the way to the tree of life. Access to the garden is closed because of the fall. Later biblical hope of restored life should be read against this loss, including Revelation's final picture of the tree of life. The text depicts God's judgment and the boundary He establishes; it does not say that God has abandoned His purpose for humanity.",
    "refs": [
      "Genesis 2:9",
      "Ezekiel 47:12",
      "Revelation 22:1–3"
    ]
  },
  "Genesis 4:1": {
    "title": "Cain is born",
    "text": "Eve bears Cain and recognizes that she has received a man from the LORD. The verse continues the human story outside Eden and shows life continuing despite judgment. The wording expresses dependence on God, though it does not mean every human act that follows is approved by Him.",
    "refs": [
      "Genesis 3:20",
      "Psalm 127:3"
    ]
  },
  "Genesis 4:2": {
    "title": "Abel and Cain's work",
    "text": "Cain works the ground and Abel keeps sheep. Their different occupations are both ordinary human work. The narrative soon focuses not on the occupations themselves but on their offerings, hearts, and response to God's correction.",
    "refs": [
      "Genesis 3:17–19",
      "Proverbs 12:11"
    ]
  },
  "Genesis 4:3": {
    "title": "Cain brings an offering",
    "text": "Cain brings fruit from the ground as an offering to the LORD. The text does not yet explain why the offering is rejected; the following verses and later Scripture help readers consider faith, obedience, and the heart. Avoid claiming that the mere fact of a plant offering is the stated reason for rejection.",
    "refs": [
      "Hebrews 11:4",
      "1 John 3:12"
    ]
  },
  "Genesis 4:4": {
    "title": "Abel's offering accepted",
    "text": "Abel brings the firstlings of his flock and their fat portions, and the LORD has respect to Abel and his offering. Hebrews later emphasizes Abel's faith. The contrast invites attention to the worshipper as well as the gift; outward religious acts are not a substitute for faith and obedience.",
    "refs": [
      "Hebrews 11:4",
      "Matthew 23:35"
    ]
  },
  "Genesis 4:5": {
    "title": "Cain becomes angry",
    "text": "Cain's offering is not regarded, and he becomes very angry and downcast. Instead of receiving correction humbly, he turns inward with resentment. The story shows that worship and character cannot be separated from the response one makes when corrected.",
    "refs": [
      "Proverbs 14:30",
      "James 1:19–20"
    ]
  },
  "Genesis 4:6": {
    "title": "God questions Cain's anger",
    "text": "The LORD asks Cain why he is angry and why his countenance has fallen. The question confronts Cain before the violence occurs and offers an opportunity to consider his response. God's warning shows moral responsibility rather than fatalism: Cain is accountable for what he chooses next.",
    "refs": [
      "Proverbs 16:32",
      "James 1:19–20"
    ]
  },
  "Genesis 4:7": {
    "title": "Sin crouches at the door",
    "text": "God warns that sin lies at the door and that Cain must rule over it. The verse personifies sin as a threat waiting to master him. The wording emphasizes the seriousness of temptation and Cain's responsibility to resist it. Compare the New Testament's calls to resist sin and not let it reign.",
    "refs": [
      "Romans 6:12–14",
      "James 1:14–15",
      "1 Peter 5:8–9"
    ]
  },
  "Genesis 4:8": {
    "title": "Cain kills Abel",
    "text": "Cain speaks with Abel and then rises against him and kills him. The first murder in Scripture follows anger and refusal to heed God's warning. The narrative exposes how cherished resentment can become violence; it does not present Cain's action as justified by the earlier offering scene.",
    "refs": [
      "Matthew 5:21–22",
      "1 John 3:11–12"
    ]
  },
  "Genesis 4:9": {
    "title": "Cain denies responsibility",
    "text": "When God asks where Abel is, Cain answers that he does not know and asks whether he is his brother's keeper. His reply evades responsibility for his brother's life. The narrative's answer is implied by the judgment that follows: human beings are accountable for violence and cannot hide it from God.",
    "refs": [
      "Genesis 3:9",
      "Leviticus 19:16",
      "1 John 3:15–18"
    ]
  },
  "Genesis 4:10": {
    "title": "Abel's blood cries from the ground",
    "text": "God says Abel's blood cries from the ground. This is poetic language for the crime's witness and the demand for justice; it does not mean God was unaware until the blood spoke. The verse affirms that hidden violence is known to God and matters to Him.",
    "refs": [
      "Hebrews 11:4",
      "Hebrews 12:24",
      "Revelation 6:9–10"
    ]
  },
  "Genesis 4:11": {
    "title": "Cain is cursed from the ground",
    "text": "Cain is cursed in relation to the ground that received Abel's blood. The ground, which Cain worked, will no longer yield its strength to him in the same way. The judgment is connected to his violence and to the earlier theme of humanity's relationship with the land.",
    "refs": [
      "Genesis 3:17–19",
      "Numbers 35:33"
    ]
  },
  "Genesis 4:12": {
    "title": "Cain becomes a wanderer",
    "text": "The ground will not give Cain its strength, and he will be a fugitive and wanderer. His violence disrupts his relationship with the land and community. The verse shows judgment as a real consequence, though the following passage also records God's protection from immediate vengeance.",
    "refs": [
      "Genesis 4:14–16"
    ]
  },
  "Genesis 4:13": {
    "title": "Cain speaks of his punishment",
    "text": "Cain says his punishment is greater than he can bear. The text records his response but does not explicitly show repentance for Abel's murder. He focuses on the severity of his own consequence. This is a warning that fear of punishment is not the same as confession of wrongdoing.",
    "refs": [
      "Psalm 51:3–4",
      "Proverbs 28:13"
    ]
  },
  "Genesis 4:14": {
    "title": "Cain fears being killed",
    "text": "Cain fears that others will kill him after he is driven from the land and from God's presence. The verse describes the social consequences and fear that follow his crime. The story distinguishes God's judgment from permission for uncontrolled private vengeance.",
    "refs": [
      "Genesis 9:5–6",
      "Romans 12:19"
    ]
  },
  "Genesis 4:15": {
    "title": "God marks Cain for protection",
    "text": "God declares that whoever kills Cain will face vengeance and sets a sign or mark to protect him. The text does not describe the mark's appearance, so its physical nature should not be invented. The passage restrains retaliation and shows that divine judgment does not authorize people to take vengeance into their own hands.",
    "refs": [
      "Genesis 4:24",
      "Romans 12:19"
    ]
  },
  "Genesis 4:16": {
    "title": "Cain leaves the LORD's presence",
    "text": "Cain goes out from the presence of the LORD and dwells in the land of Nod. The departure symbolizes alienation and begins the account of Cain's line. God's presence is not geographically limited; the phrase describes Cain's removal from the place of divine encounter and favor in the narrative.",
    "refs": [
      "Psalm 139:7–10",
      "Jonah 1:3"
    ]
  },
  "Genesis 4:17": {
    "title": "Cain builds a city",
    "text": "Cain has a son, names him Enoch, and builds a city. The account records the growth of human society even in Cain's line. Cultural development does not by itself prove moral faithfulness; later verses show both human creativity and continuing violence.",
    "refs": [
      "Genesis 4:18–24",
      "Genesis 11:1–9"
    ]
  },
  "Genesis 4:18": {
    "title": "Cain's descendants",
    "text": "The genealogy lists descendants of Cain. It preserves the family line as the story moves toward the contrast with Seth's line. Names and generations help establish the narrative's history; the passage does not ask readers to infer a separate divine lineage from these names.",
    "refs": [
      "Genesis 5:1–32"
    ]
  },
  "Genesis 4:19": {
    "title": "Lamech takes two wives",
    "text": "Lamech's two wives are recorded, marking a departure from the one-man, one-woman marriage pattern described in Genesis 2:24. The text reports the practice rather than praising it. In reading narrative passages, distinguish what Scripture records from what it commands or commends.",
    "refs": [
      "Genesis 2:24",
      "Matthew 19:4–8"
    ]
  },
  "Genesis 4:20": {
    "title": "Jabal and tent-dwelling",
    "text": "Jabal is associated with those who dwell in tents and raise livestock. The verse records practical and cultural development among Cain's descendants. Such skills can be part of human creativity, but the genealogy's later violence warns that technical progress alone does not heal the human heart.",
    "refs": [
      "Genesis 4:17–22"
    ]
  },
  "Genesis 4:21": {
    "title": "Jubal and music",
    "text": "Jubal is described as the ancestor of those who play the harp and organ or pipe. Music appears as an early human art. Scripture elsewhere uses music in worship and ordinary life; its moral character depends on its use and purpose, not simply on the existence of instruments.",
    "refs": [
      "Psalm 150:3–5",
      "Ephesians 5:19"
    ]
  },
  "Genesis 4:22": {
    "title": "Tubal-cain and metalworking",
    "text": "Tubal-cain works with brass and iron, and his sister is named. The passage records the development of crafts and tools. The Bible does not teach that all technology is evil; it shows that human skill can coexist with a sinful heart and must be directed responsibly.",
    "refs": [
      "Genesis 4:23–24",
      "Isaiah 2:4"
    ]
  },
  "Genesis 4:23": {
    "title": "Lamech boasts of violence",
    "text": "Lamech tells his wives that he has killed a man for wounding him and a young man for bruising him. His speech sounds like a boast and escalates Cain's pattern of violence. The narrative exposes revenge that exceeds injury rather than endorsing Lamech's actions.",
    "refs": [
      "Exodus 21:23–25",
      "Matthew 5:38–44",
      "Romans 12:17–21"
    ]
  },
  "Genesis 4:24": {
    "title": "Lamech's exaggerated vengeance",
    "text": "Lamech claims that if Cain is avenged sevenfold, he will be avenged seventy and sevenfold. The statement magnifies personal retaliation. Jesus later uses a similar number in teaching repeated forgiveness, a striking reversal of revenge into mercy; the contexts should be compared carefully.",
    "refs": [
      "Genesis 4:15",
      "Matthew 18:21–22"
    ]
  },
  "Genesis 4:25": {
    "title": "Seth is born",
    "text": "Eve names Seth as another seed appointed in place of Abel. The family line continues after Abel's death, and the narrative turns toward the line that will be traced in Genesis 5. The verse expresses hope for continuity, though it does not imply that every descendant is automatically righteous.",
    "refs": [
      "Genesis 5:3–8"
    ]
  },
  "Genesis 4:26": {
    "title": "People begin to call on the LORD",
    "text": "Seth's son is named Enos, and the text says people began to call upon the name of the LORD. This introduces public invocation or worship of the LORD in the narrative. It provides a foundation for later biblical emphasis on calling on the LORD's name; New Testament applications should be read in their own contexts and alongside the Old Testament wording.",
    "refs": [
      "Genesis 12:8",
      "Joel 2:32",
      "Acts 2:21",
      "Romans 10:13"
    ]
  },
  "Genesis 6:1": {
    "title": "Humanity multiplies",
    "text": "The growth of humanity sets the scene for the corruption described in this chapter. The passage begins with the human family, not with a second divine person or a change in who God is. Read the following verses for the text’s own explanation of the crisis.",
    "refs": "Genesis 1:28; Genesis 6:5"
  },
  "Genesis 6:2": {
    "title": "Sons of God and daughters of men",
    "text": "The identity of the “sons of God” has been interpreted in different ways, including heavenly beings, rulers, or the godly line of Seth. The verse itself does not define the phrase, so a careful study should distinguish the wording from a proposed interpretation. This verse does not by itself establish a doctrine about multiple divine persons.",
    "refs": "Job 1:6; Luke 3:38"
  },
  "Genesis 6:3": {
    "title": "God’s Spirit and human life",
    "text": "God declares a limit in response to human wickedness. The verse speaks of God’s Spirit and the human condition; it does not describe the Spirit as a separate God. In Oneness understanding, God’s Spirit is God present and active, while the verse’s precise meaning of “strive” and “an hundred and twenty years” is debated.",
    "refs": "Genesis 1:2; Psalm 104:30"
  },
  "Genesis 6:4": {
    "title": "Mighty men of old",
    "text": "The text briefly mentions the Nephilim and famous warriors. It gives little detail about their nature, so conclusions beyond the verse should be held cautiously. The main narrative focus remains humanity’s increasing corruption and God’s judgment.",
    "refs": "Numbers 13:33"
  },
  "Genesis 6:5": {
    "title": "The depth of human wickedness",
    "text": "God sees that human wickedness has become widespread and that the thoughts of the heart are continually evil. The flood narrative presents judgment as a response to pervasive violence and corruption, not as an arbitrary act. This also explains why Scripture calls people to repentance and a changed heart.",
    "refs": "Psalm 14:1–3; Matthew 15:19"
  },
  "Genesis 6:6": {
    "title": "The LORD grieved",
    "text": "The language of God being grieved communicates His real opposition to evil and the tragedy of human rebellion. It should not be used to suggest that God is one divine person grieving another divine person. Scripture uses human language to communicate God’s response in terms people can understand.",
    "refs": "1 Samuel 15:11; Ephesians 4:30"
  },
  "Genesis 6:7": {
    "title": "Judgment upon the earth",
    "text": "God announces judgment on humanity and land animals within the story’s scope. The verse stresses the seriousness of sin and the consequences of a world filled with corruption. Later biblical passages also use the flood as a warning about judgment and accountability.",
    "refs": "Matthew 24:37–39; 2 Peter 2:5"
  },
  "Genesis 6:8": {
    "title": "Noah finds grace",
    "text": "Noah finds favor with the LORD in the midst of a corrupt generation. The story joins divine grace with Noah’s faithful response; grace is not presented as approval of the surrounding evil. This verse gives an early picture of God preserving a way forward when judgment comes.",
    "refs": "Genesis 6:9; Ephesians 2:8–10"
  },
  "Genesis 6:9": {
    "title": "Noah walked with God",
    "text": "Noah is described as righteous in his generation and as one who walked with God. The expression describes a life oriented toward God, not a claim that Noah was sinless in every possible sense. The chapter contrasts Noah’s way with the corruption around him.",
    "refs": "Genesis 5:24; Micah 6:8"
  },
  "Genesis 6:10": {
    "title": "Noah’s three sons",
    "text": "The names Shem, Ham, and Japheth establish the family through which the next stage of the story unfolds. The genealogical details matter to the biblical narrative and should not be turned into unsupported claims about later peoples or races.",
    "refs": "Genesis 9:18–19; Genesis 10:1"
  },
  "Genesis 6:11": {
    "title": "The earth was corrupt",
    "text": "The earth is described as corrupt before God and filled with violence. The crisis is social and moral, not merely private wrongdoing. The story’s judgment is connected directly to the violence that has overtaken human society.",
    "refs": "Genesis 6:5; Psalm 11:5"
  },
  "Genesis 6:12": {
    "title": "All flesh had corrupted its way",
    "text": "God observes that all flesh has corrupted its way on the earth. The phrase summarizes the widespread breakdown of the created order. The verse does not mean every individual had exactly the same conduct; it emphasizes the pervasive character of the corruption.",
    "refs": "Genesis 1:31; Romans 3:23"
  },
  "Genesis 6:13": {
    "title": "The end of all flesh",
    "text": "God tells Noah that the earth is filled with violence and announces its destruction. The explanation is given in the text itself: violence has filled the earth. God’s judgment is portrayed as a response to a world that has become ruinous.",
    "refs": "Genesis 6:11; Ezekiel 7:23"
  },
  "Genesis 6:14": {
    "title": "Make thee an ark",
    "text": "God gives Noah a concrete command to build an ark. Faith in this account takes practical form through obedience to the instruction received. The named material and construction details belong to the narrative and should be preserved when teaching the passage.",
    "refs": "Hebrews 11:7"
  },
  "Genesis 6:15": {
    "title": "The ark’s dimensions",
    "text": "The dimensions show that the ark is described as a specific vessel, not merely a vague symbol. Ancient measurements and proposed modern equivalents can vary, so conversions should be identified as estimates. The central point is Noah’s preparation according to God’s command.",
    "refs": "Genesis 6:14; Genesis 7:5"
  },
  "Genesis 6:16": {
    "title": "The door and compartments",
    "text": "God provides further instructions for the ark’s construction, including its opening and levels. The details underline that Noah is to follow the revealed plan rather than improvise his own. Some translation details differ, but the construction purpose is clear.",
    "refs": "Genesis 6:14–15"
  },
  "Genesis 6:17": {
    "title": "The flood announced",
    "text": "God announces the coming flood and the destruction of life that breathes on the earth. The story presents God as sovereign over creation and judgment. Later Scripture refers to this event as a warning, while readers may discuss the scope and chronology of the flood separately from the verse’s explicit claim.",
    "refs": "Genesis 7:17–23; 2 Peter 3:5–7"
  },
  "Genesis 6:18": {
    "title": "God’s covenant with Noah",
    "text": "God promises to establish His covenant with Noah and brings Noah’s family into the ark. The covenant is God’s initiative and provides preservation through the coming judgment. The verse does not name a second divine person; it speaks of the LORD making His covenant.",
    "refs": "Genesis 9:8–17; Hebrews 11:7"
  },
  "Genesis 6:19": {
    "title": "Preserving animal life",
    "text": "Noah is instructed to bring living creatures into the ark to preserve their life. The passage’s emphasis is preservation amid judgment. The verse gives a broad instruction; the following verses add details about the animals and provisions.",
    "refs": "Genesis 7:2–3"
  },
  "Genesis 6:20": {
    "title": "Animals come to Noah",
    "text": "The text says the creatures will come to Noah to be kept alive. Noah’s role is to receive and preserve them as commanded. The verse presents preservation as part of God’s plan, not as Noah’s independent achievement.",
    "refs": "Genesis 7:8–9"
  },
  "Genesis 6:21": {
    "title": "Food for the ark",
    "text": "Noah must gather food for his family and the animals. The command includes ordinary preparation alongside extraordinary events. Biblical faith in this narrative involves trusting God and doing the work that obedience requires.",
    "refs": "Genesis 7:5; Genesis 8:20"
  },
  "Genesis 6:22": {
    "title": "Noah obeys",
    "text": "Noah does according to all that God commanded him. This summary highlights obedience as the response to God’s warning and instructions. Hebrews later uses Noah as an example of faith that acts upon what God has said.",
    "refs": "Genesis 7:5; Hebrews 11:7"
  },
  "Genesis 7:1": {
    "title": "Enter the ark",
    "text": "God tells Noah to enter the ark because He has seen Noah as righteous in that generation. The statement belongs to the narrative’s contrast between Noah and the corrupt world. Righteousness here should be read with the whole account, including Noah’s trust and obedience.",
    "refs": "Genesis 6:9; Hebrews 11:7"
  },
  "Genesis 7:2": {
    "title": "Clean and unclean animals",
    "text": "The distinction between clean and unclean animals appears before the later detailed law given through Moses. The verse does not explain every later dietary rule, but it shows that the categories are already present in the narrative.",
    "refs": "Leviticus 11:1–8"
  },
  "Genesis 7:3": {
    "title": "Birds preserved",
    "text": "Noah is told to preserve birds as well, so their kinds may continue on the earth. The repeated concern is survival and continuity after the flood. The wording gives a narrative purpose rather than a complete modern biological classification.",
    "refs": "Genesis 6:19–20"
  },
  "Genesis 7:4": {
    "title": "Seven days before the rain",
    "text": "God announces a seven-day interval before the rain and a forty-day period of rain. These time markers organize the narrative and show that the event is announced in advance. Later interpretations of the flood’s chronology should be distinguished from the wording of this verse.",
    "refs": "Genesis 7:10–12"
  },
  "Genesis 7:5": {
    "title": "Noah did as commanded",
    "text": "Noah obeys everything the LORD commanded him. The repeated emphasis on obedience reinforces the description of Noah as one who trusts God’s warning. The story does not praise mere hearing but acting on God’s word.",
    "refs": "Genesis 6:22; James 1:22"
  },
  "Genesis 7:6": {
    "title": "Noah’s age",
    "text": "The verse gives Noah’s age when the flood came. Biblical narrative uses such chronological markers to situate events within a family history. The age should be reported as the text states it, without forcing it into a chronology the passage does not provide.",
    "refs": "Genesis 5:32; Genesis 7:11"
  },
  "Genesis 7:7": {
    "title": "Noah’s family enters",
    "text": "Noah, his sons, his wife, and his sons’ wives enter the ark to escape the flood. Preservation includes the family that will continue the human story after judgment. The verse emphasizes a household responding to the warning given through Noah.",
    "refs": "Genesis 6:18; 1 Peter 3:20"
  },
  "Genesis 7:8": {
    "title": "Clean and unclean creatures",
    "text": "The narrative specifies that clean and unclean animals enter the ark. This repeats the distinction introduced earlier and prepares for the more exact account of animal numbers. The text’s focus remains preservation before the flood.",
    "refs": "Genesis 7:2"
  },
  "Genesis 7:9": {
    "title": "They came two and two",
    "text": "The animals come to Noah in pairs, as God had commanded. The wording stresses the fulfillment of the instruction. It should be read together with the additional detail about clean animals in verses 2–3, not as if every animal category had identical numbers.",
    "refs": "Genesis 6:19–20; Genesis 7:2–3"
  },
  "Genesis 7:10": {
    "title": "The flood begins",
    "text": "After the seven days, the waters of the flood come upon the earth. The sequence connects the announced warning with its fulfillment. In the narrative, God’s word proves reliable and the time of judgment arrives as declared.",
    "refs": "Genesis 7:4; Genesis 7:17"
  },
  "Genesis 7:11": {
    "title": "The fountains and windows",
    "text": "The verse dates the flood and describes waters coming from the great deep and the windows of heaven. These are the text’s own images for the overwhelming waters. Interpretations of the physical mechanism vary, so a study should not claim scientific details that the verse does not specify.",
    "refs": "Genesis 1:6–7; Genesis 8:2"
  },
  "Genesis 7:12": {
    "title": "Rain for forty days and nights",
    "text": "The rain continues forty days and forty nights. The duration is repeated to stress the scale and persistence of the flood. The verse itself does not settle every question about how long the waters remained on the earth; later verses continue the chronology.",
    "refs": "Genesis 7:17; Genesis 8:3–4"
  },
  "Genesis 7:13": {
    "title": "The family enters on that day",
    "text": "The verse names Noah’s sons and wife and the wives of his sons as entering the ark on the day described. The list identifies the preserved family and connects the event to the genealogies that follow. No additional doctrine about divine identity is stated here.",
    "refs": "Genesis 6:18; Genesis 7:7"
  },
  "Genesis 7:14": {
    "title": "Living creatures of every kind",
    "text": "The list of animals emphasizes the breadth of life preserved aboard the ark. The wording groups creatures by kinds known to the narrative, not by modern taxonomic terminology. The central theme is preservation through the judgment.",
    "refs": "Genesis 6:19–20"
  },
  "Genesis 7:15": {
    "title": "Breath of life",
    "text": "Creatures with the breath of life come to Noah in pairs. This echoes Genesis’s language about living creatures and life from God. The passage distinguishes living creation from the waters that bring judgment.",
    "refs": "Genesis 2:7; Genesis 6:17"
  },
  "Genesis 7:16": {
    "title": "The LORD shut him in",
    "text": "After those entering have come, the LORD shuts Noah in. The detail highlights that Noah’s safety ultimately depends on God, not merely on the structure he built. The verse portrays God’s protection without requiring an allegory beyond the narrative.",
    "refs": "Genesis 6:18; Psalm 27:5"
  },
  "Genesis 7:17": {
    "title": "The waters increase",
    "text": "The flood lasts forty days, and the waters rise until the ark is lifted above the earth. The story moves from rainfall to the growing force of the waters. The ark is the means of preservation within the account.",
    "refs": "Genesis 7:12; Genesis 7:18"
  },
  "Genesis 7:18": {
    "title": "The ark floats",
    "text": "The waters prevail and the ark moves upon the surface. The repetition emphasizes the scale of the flood and the ark’s role in keeping its occupants afloat. The narrative’s focus is the survival of those God instructed Noah to preserve.",
    "refs": "Genesis 7:17; Genesis 7:24"
  },
  "Genesis 7:19": {
    "title": "The mountains covered",
    "text": "The text describes the waters prevailing over the high mountains under heaven. Readers differ on how to understand the flood’s geographical scope; the verse’s own description should be stated accurately, while broader conclusions should be identified as interpretations.",
    "refs": "Genesis 7:20; Genesis 8:4"
  },
  "Genesis 7:20": {
    "title": "The waters rise above the mountains",
    "text": "The verse gives the depth of the waters above the mountains. It reinforces the account’s portrayal of an overwhelming flood. It should not be reduced to a casual local rainstorm, though debates about global geography and ancient language should be handled openly rather than hidden.",
    "refs": "Genesis 7:19; Genesis 8:5"
  },
  "Genesis 7:21": {
    "title": "Life perishes",
    "text": "The narrative reports the death of creatures on the land, including humans and animals. This is the severe judgment announced earlier. The verse should be read soberly, not triumphantly; it depicts the tragic result of the corruption described in Genesis 6.",
    "refs": "Genesis 6:5–7; 2 Peter 2:5"
  },
  "Genesis 7:22": {
    "title": "Breath of life on dry land",
    "text": "The verse summarizes the death of beings with the breath of life on dry land. The wording echoes earlier creation language, showing how the flood reverses the ordered life of the land. The passage emphasizes the seriousness of judgment.",
    "refs": "Genesis 2:7; Genesis 7:21"
  },
  "Genesis 7:23": {
    "title": "Only Noah and those with him remain",
    "text": "The text summarizes the destruction of life outside the ark and the preservation of Noah and those with him. Preservation is linked to God’s warning and Noah’s obedience. Later Scripture uses Noah’s experience as a warning and example, not as permission for speculation beyond the text.",
    "refs": "Genesis 6:18; Matthew 24:37–39; 2 Peter 2:5"
  },
  "Genesis 7:24": {
    "title": "The waters prevail one hundred and fifty days",
    "text": "The waters prevail for one hundred and fifty days. This duration is distinct from the forty days of rain mentioned earlier: the rain period and the period the waters prevailed are not identical descriptions. The chronology continues into Genesis 8.",
    "refs": "Genesis 7:12; Genesis 8:3–4"
  },
  "Genesis 8:1": {
    "title": "God remembers Noah",
    "text": "“Remembered” describes God turning to act on behalf of Noah and the creatures; it does not mean God had literally forgotten them. God sends a wind over the earth and the waters begin to recede. The verse emphasizes divine care after judgment.",
    "refs": "Genesis 19:29; Exodus 2:24"
  },
  "Genesis 8:2": {
    "title": "The waters are restrained",
    "text": "The sources of the floodwaters are stopped and the rain ceases. The account portrays the same God who brought judgment as bringing it to an end. The language echoes the earlier description of the waters in Genesis 7.",
    "refs": "Genesis 7:11–12; Genesis 7:17"
  },
  "Genesis 8:3": {
    "title": "The waters return",
    "text": "The waters gradually recede after the one hundred and fifty days described earlier. The narrative distinguishes the flood’s rise from the lengthy process of its retreat. The text asks the reader to follow the sequence rather than collapse all time markers into one period.",
    "refs": "Genesis 7:24; Genesis 8:4"
  },
  "Genesis 8:4": {
    "title": "The ark rests",
    "text": "The ark rests on the mountains of Ararat in the seventh month. The verse supplies a location and date within the story; it does not identify a precise modern landing site. God’s preservation of Noah’s household continues through this stage.",
    "refs": "Genesis 7:17–18"
  },
  "Genesis 8:5": {
    "title": "Mountain tops appear",
    "text": "The waters continue to decrease until mountain tops become visible. The gradual change reinforces the long process of returning land to view. The following verses describe Noah’s attempts to learn whether the land is ready.",
    "refs": "Genesis 8:4; Genesis 8:6"
  },
  "Genesis 8:6": {
    "title": "Noah opens the window",
    "text": "After forty days, Noah opens the window he had made in the ark. The detail shows Noah observing conditions and acting patiently within the situation. The verse does not specify that the forty days are counted from the beginning of the flood.",
    "refs": "Genesis 6:16; Genesis 8:10"
  },
  "Genesis 8:7": {
    "title": "The raven",
    "text": "Noah sends a raven, which goes to and fro until the waters dry up. The verse gives the first of two bird tests; the next verses explain the dove’s returns in more detail. Avoid assigning symbolic meanings to the raven as if the text explicitly gives them.",
    "refs": "Genesis 8:8–12"
  },
  "Genesis 8:8": {
    "title": "The dove is sent",
    "text": "Noah sends a dove to find out whether the waters have abated. The action is a practical test of the condition of the land. The passage emphasizes observation and patience rather than a hidden doctrinal message in the bird itself.",
    "refs": "Genesis 8:9–12"
  },
  "Genesis 8:9": {
    "title": "The dove returns",
    "text": "The dove finds no resting place and returns to Noah because water still covers the earth. Noah reaches out and brings it back into the ark. The detail shows that the land is not yet ready, so Noah waits rather than leaving prematurely.",
    "refs": "Genesis 8:8; Genesis 8:10"
  },
  "Genesis 8:10": {
    "title": "Noah waits seven more days",
    "text": "Noah waits another seven days before sending the dove again. The repeated interval highlights patience and the step-by-step process of checking the land. The passage does not portray Noah as acting without regard to conditions.",
    "refs": "Genesis 8:12"
  },
  "Genesis 8:11": {
    "title": "An olive leaf",
    "text": "The dove returns with a freshly plucked olive leaf, evidence that vegetation is visible again. Noah understands that the waters have decreased. Later readers may see hope in this image, but the direct narrative point is evidence that the land is recovering.",
    "refs": "Genesis 8:8–10"
  },
  "Genesis 8:12": {
    "title": "The dove does not return",
    "text": "After another seven days, the dove does not return. The sequence indicates a change in the conditions outside the ark. The text does not say Noah immediately exits; he continues to wait for God’s instruction.",
    "refs": "Genesis 8:13–16"
  },
  "Genesis 8:13": {
    "title": "The earth dries",
    "text": "Noah removes the covering of the ark and sees that the surface of the ground is dry. The date is recorded carefully, but dry ground does not yet mean Noah has been told to leave. The next verses distinguish seeing the condition from receiving God’s command.",
    "refs": "Genesis 8:14–16"
  },
  "Genesis 8:14": {
    "title": "The earth is dry",
    "text": "The earth is fully dry by the date stated in the verse. The narrative tracks the passage of months and days to mark the end of the flood period. Noah remains in the ark until God speaks to him.",
    "refs": "Genesis 8:13; Genesis 8:15"
  },
  "Genesis 8:15": {
    "title": "God speaks to Noah",
    "text": "God speaks directly to Noah after the earth is dry. The narrative shows Noah’s next step comes from God’s instruction, not merely his own assessment. This is consistent with the repeated pattern of God directing Noah throughout the account.",
    "refs": "Genesis 6:13–22; Genesis 7:1"
  },
  "Genesis 8:16": {
    "title": "Leave the ark",
    "text": "God commands Noah, his family, and those with him to leave the ark. Preservation was not the final purpose; life is to continue on the renewed land. Noah waits for the command even after seeing that the ground is dry.",
    "refs": "Genesis 8:13–15"
  },
  "Genesis 8:17": {
    "title": "Life multiplies again",
    "text": "The animals are to go out and multiply on the earth. The command echoes the creation blessing for living creatures. The flood has brought judgment, but the story now turns toward renewed life and continuity.",
    "refs": "Genesis 1:22; Genesis 1:28"
  },
  "Genesis 8:18": {
    "title": "Noah’s family leaves",
    "text": "Noah and his family obey the instruction and leave the ark. The narrative records their departure simply, closing the period of confinement. God’s preservation makes a new beginning possible.",
    "refs": "Genesis 8:15–17"
  },
  "Genesis 8:19": {
    "title": "The animals leave",
    "text": "Every kind of creature leaves the ark. The repeated mention of kinds recalls the creation account and emphasizes the continuation of living creatures. The verse does not provide a modern species count.",
    "refs": "Genesis 1:24–25; Genesis 6:19–20"
  },
  "Genesis 8:20": {
    "title": "Noah builds an altar",
    "text": "Noah builds an altar and offers burnt offerings from clean animals and birds. His first recorded action after leaving the ark is worship. The offerings are described in the text; later sacrificial theology develops further across Scripture.",
    "refs": "Genesis 4:3–4; Leviticus 1:1–9"
  },
  "Genesis 8:21": {
    "title": "The LORD smells a sweet savour",
    "text": "The language of smelling a pleasing aroma describes God’s acceptance of the offering in human terms. God declares that He will not again curse the ground in this manner, despite humanity’s continuing inclination toward evil. This is a promise about the order of life, not a declaration that sin no longer matters.",
    "refs": "Genesis 6:5–7; Genesis 9:11"
  },
  "Genesis 8:22": {
    "title": "The seasons continue",
    "text": "God promises the continuing cycles of seedtime and harvest, cold and heat, summer and winter, day and night while the earth remains. The verse emphasizes stability after the flood. It is not a promise that every season or local weather pattern will always be uniform.",
    "refs": "Jeremiah 33:20–21; Psalm 74:17"
  },
  "Genesis 9:1": {
    "title": "Be fruitful and multiply",
    "text": "God blesses Noah and his sons and commands them to multiply and fill the earth. This echoes the blessing given to humanity at creation. The flood has not cancelled God’s purpose for human life and the earth.",
    "refs": "Genesis 1:28; Genesis 8:17"
  },
  "Genesis 9:2": {
    "title": "Humanity and the animals",
    "text": "God describes a changed relationship in which animals fear and dread humans. The verse gives humanity authority in a world affected by the flood. Dominion should not be confused with permission for needless cruelty.",
    "refs": "Genesis 1:26–28; Psalm 8:6–8"
  },
  "Genesis 9:3": {
    "title": "Food from living creatures",
    "text": "God permits living creatures as food, as He had given green herbs. The wording marks a development from the food provision stated in Genesis 1:29–30. Read this alongside the blood restriction in the next verse.",
    "refs": "Genesis 1:29–30; Genesis 9:4"
  },
  "Genesis 9:4": {
    "title": "Do not eat flesh with its blood",
    "text": "God prohibits eating flesh with its life, its blood. Blood is treated as significant because it represents life. Later biblical instructions repeat the importance of abstaining from blood; this is more than a casual dietary preference.",
    "refs": "Leviticus 17:10–14; Acts 15:20"
  },
  "Genesis 9:5": {
    "title": "An accounting for life",
    "text": "God says He will require an accounting for the shedding of human blood. Human life is morally serious and answerable to God. The verse establishes accountability, not a license for personal vengeance outside lawful justice.",
    "refs": "Genesis 4:10; Psalm 9:12"
  },
  "Genesis 9:6": {
    "title": "Humanity bears God’s image",
    "text": "The verse grounds the seriousness of murder in humanity’s being made in God’s image. Human beings have dignity because of their relation to their Creator. Interpret this alongside the wider biblical teaching about justice and lawful authority.",
    "refs": "Genesis 1:26–27; James 3:9"
  },
  "Genesis 9:7": {
    "title": "Multiply on the earth",
    "text": "God repeats the command to be fruitful and multiply. The repetition emphasizes the continuation of humanity after the flood. The command looks beyond Noah’s immediate household to future generations.",
    "refs": "Genesis 9:1; Genesis 1:28"
  },
  "Genesis 9:8": {
    "title": "God speaks to Noah and his sons",
    "text": "God addresses Noah and his sons as the covenant announcement begins. The covenant concerns the family and generations after them. The passage speaks of the LORD making a covenant, without introducing a separate divine person.",
    "refs": "Genesis 9:9–11"
  },
  "Genesis 9:9": {
    "title": "The covenant is established",
    "text": "God declares that He establishes His covenant with Noah and his descendants. The initiative belongs to God, who gives a promise extending beyond the immediate survivors. The covenant’s scope is explained in the following verses.",
    "refs": "Genesis 6:18; Genesis 9:11–17"
  },
  "Genesis 9:10": {
    "title": "Every living creature included",
    "text": "The covenant includes birds, livestock, and the animals of the earth. The promise is not limited to Noah’s family; it includes creatures preserved through the flood. This broad scope underlines God’s concern for creation.",
    "refs": "Genesis 8:17; Genesis 9:12"
  },
  "Genesis 9:11": {
    "title": "No more flood to destroy all flesh",
    "text": "God promises that all flesh will not again be cut off by floodwaters and that a flood will not again destroy the earth in this way. The promise concerns the flood judgment described here; it does not mean Scripture denies every future judgment.",
    "refs": "Isaiah 54:9; 2 Peter 3:6–7"
  },
  "Genesis 9:12": {
    "title": "The covenant sign",
    "text": "God identifies a sign of the covenant between Himself and every living creature for future generations. The sign makes the promise visible and memorable. The covenant is God’s declaration, not a bargain in which Noah controls the outcome.",
    "refs": "Genesis 9:13–17"
  },
  "Genesis 9:13": {
    "title": "The bow in the cloud",
    "text": "God places His bow in the cloud as the sign of the covenant. The verse itself identifies its meaning through the promise that follows. Additional symbolic meanings should not replace the meaning God explicitly gives in the passage.",
    "refs": "Genesis 9:14–16"
  },
  "Genesis 9:14": {
    "title": "Clouds over the earth",
    "text": "When clouds come over the earth, the bow will be seen in them. The sign is connected to the created world and points back to God’s promise. Its meaning is established by God’s words, not by speculation about its colors.",
    "refs": "Genesis 9:13; Genesis 9:16"
  },
  "Genesis 9:15": {
    "title": "God remembers His covenant",
    "text": "God says He will remember His covenant and the waters will not again become a flood to destroy all flesh. “Remember” describes faithful action toward a promise, not God recovering a forgotten fact. The verse stresses the reliability of God’s word.",
    "refs": "Genesis 8:1; Exodus 2:24"
  },
  "Genesis 9:16": {
    "title": "An everlasting covenant",
    "text": "The bow is to remind God of the everlasting covenant between God and every living creature. The text presents the covenant as enduring across generations. The verse gives the covenant’s scope and purpose directly.",
    "refs": "Genesis 9:12–15"
  },
  "Genesis 9:17": {
    "title": "The covenant confirmed",
    "text": "God repeats that the bow is the sign of His covenant with all flesh. Repetition underscores the certainty of the promise. The passage reveals God’s faithfulness in preserving the world after the flood.",
    "refs": "Genesis 9:8–16"
  },
  "Genesis 9:18": {
    "title": "Noah’s sons named",
    "text": "The narrative returns to Shem, Ham, and Japheth and notes Ham’s relationship to Canaan. These details prepare for the family episode and later genealogies. This verse alone should not be used to justify racial prejudice or unsupported claims about modern peoples.",
    "refs": "Genesis 10:1; Genesis 10:6"
  },
  "Genesis 9:19": {
    "title": "The earth’s population",
    "text": "The verse says the earth’s population spread from Noah’s three sons. It is a foundational statement in the biblical genealogy. It does not give modern racial categories or authorize assigning moral character to entire peoples.",
    "refs": "Genesis 10:32; Acts 17:26"
  },
  "Genesis 9:20": {
    "title": "Noah plants a vineyard",
    "text": "Noah becomes a man of the soil and plants a vineyard. The narrative turns from the flood to the vulnerability of life afterward. Noah’s earlier righteousness does not mean every later action of his life is without fault.",
    "refs": "Genesis 6:9; Genesis 9:21"
  },
  "Genesis 9:21": {
    "title": "Noah becomes drunk",
    "text": "Noah drinks wine, becomes drunk, and lies uncovered in his tent. Scripture records the event plainly rather than concealing the failure of a major biblical figure. The passage gives no approval of drunkenness.",
    "refs": "Proverbs 20:1; Ephesians 5:18"
  },
  "Genesis 9:22": {
    "title": "Ham sees his father’s nakedness",
    "text": "Ham sees his father’s nakedness and tells his brothers outside. The exact nature of Ham’s offense has been debated, but the verse explicitly reports seeing and telling. A responsible reading should not present a more elaborate explanation as if the verse directly states it.",
    "refs": "Genesis 9:23–25"
  },
  "Genesis 9:23": {
    "title": "Shem and Japheth cover Noah",
    "text": "Shem and Japheth take a garment, walk backward, and cover their father without looking at him. Their action contrasts with Ham’s report and shows an effort to preserve Noah’s dignity. The emphasis is on their deliberate, respectful conduct.",
    "refs": "Exodus 20:12; 1 Peter 4:8"
  },
  "Genesis 9:24": {
    "title": "Noah learns what happened",
    "text": "When Noah awakens and learns what his younger son had done, the narrative prepares for his pronouncement. The text does not provide every detail of how he learned of the event. The next verse must be read carefully because Noah’s words name Canaan.",
    "refs": "Genesis 9:25"
  },
  "Genesis 9:25": {
    "title": "Canaan is named in the curse",
    "text": "Noah pronounces a curse on Canaan, not directly on Ham in the wording of this verse. The passage has been misused to justify racial slavery, but it does not identify the curse with Black people or any modern race. Such claims go beyond the text and have caused grave harm.",
    "refs": "Genesis 10:6; Genesis 10:15–19"
  },
  "Genesis 9:26": {
    "title": "The LORD, God of Shem",
    "text": "Noah blesses the LORD, identifying Him as the God of Shem, and speaks of Canaan’s service. The verse places family lines within the biblical narrative. It names the LORD as God; it does not teach that Shem is divine or that there are multiple Gods.",
    "refs": "Genesis 12:1–3; Genesis 14:18–20"
  },
  "Genesis 9:27": {
    "title": "Japheth and the tents of Shem",
    "text": "Noah speaks of Japheth’s enlargement and dwelling in the tents of Shem, while Canaan is again described as serving. The exact historical fulfillment has been interpreted in different ways. The verse should not be forced into modern ethnic theories without textual support.",
    "refs": "Genesis 10:1–5; Genesis 10:21–31"
  },
  "Genesis 9:28": {
    "title": "Noah lives after the flood",
    "text": "The verse records that Noah lived three hundred and fifty years after the flood. This chronological note links the flood account to the continuing genealogy. It supplies a stated lifespan, not a separate doctrinal claim.",
    "refs": "Genesis 5:32; Genesis 9:29"
  },
  "Genesis 9:29": {
    "title": "Noah’s death",
    "text": "Noah’s total lifespan is given as nine hundred and fifty years, and the chapter ends with his death. The narrative records his role in the flood account while also recording the end of his life. Biblical figures remain human beings under God, not objects of worship.",
    "refs": "Genesis 6:9; Hebrews 11:7"
  },
  "Genesis 10:1": {
    "title": "The generations of Noah’s sons",
    "text": "Genesis 10 records the descendants of Shem, Ham, and Japheth after the flood. The genealogy explains how the nations are represented in the biblical story. Names and family relationships should be read from the text rather than mapped carelessly onto modern racial categories.",
    "refs": "Genesis 9:18–19; 1 Chronicles 1:4–7"
  },
  "Genesis 10:2": {
    "title": "The sons of Japheth",
    "text": "The verse names Japheth’s sons and begins one branch of the post-flood genealogy. These names establish family relationships in the ancient narrative. The verse itself does not provide enough information to make every proposed identification with a modern nation certain.",
    "refs": "Genesis 10:5; 1 Chronicles 1:5"
  },
  "Genesis 10:3": {
    "title": "The sons of Gomer",
    "text": "The verse lists descendants of Gomer within Japheth’s line. Such names help organize the genealogy and its later references to peoples. Where historical identifications are uncertain, the uncertainty should be acknowledged instead of presented as settled Scripture.",
    "refs": "Genesis 10:2; 1 Chronicles 1:6"
  },
  "Genesis 10:4": {
    "title": "The sons of Javan",
    "text": "The verse names descendants of Javan in Japheth’s family line. The list provides the biblical framework for the spread of peoples in the chapter. It is genealogical information rather than a direct teaching about the nature of God.",
    "refs": "Genesis 10:5; 1 Chronicles 1:7"
  },
  "Genesis 10:5": {
    "title": "The isles of the Gentiles",
    "text": "The text describes the descendants of Japheth spreading into lands and coastlands, each according to language, family, and nation. The verse introduces the chapter’s concern with peoples and languages. All nations remain part of the human family under the one Creator.",
    "refs": "Genesis 11:8–9; Acts 17:26"
  },
  "Genesis 10:6": {
    "title": "The sons of Ham",
    "text": "The verse lists Cush, Mizraim, Phut, and Canaan as sons of Ham. The genealogy names ancient family lines; it does not make a moral judgment about every later person associated with these names. It must not be used to support racial hierarchy.",
    "refs": "Genesis 9:25–27; 1 Chronicles 1:8"
  },
  "Genesis 10:7": {
    "title": "The sons of Cush",
    "text": "The descendants of Cush are listed as part of the genealogy. The names preserve the ancient account of family and people groups. The verse does not authorize certainty about every modern geographical identification without further evidence.",
    "refs": "Genesis 10:8–12; 1 Chronicles 1:9"
  },
  "Genesis 10:8": {
    "title": "Nimrod begins to be mighty",
    "text": "Nimrod is described as beginning to be a mighty one in the earth. The next verses expand on his kingdom and cities. The word “mighty” here is a narrative description; this verse alone does not settle every later tradition about Nimrod.",
    "refs": "Genesis 10:9–12"
  },
  "Genesis 10:9": {
    "title": "A mighty hunter before the LORD",
    "text": "Nimrod is described as a mighty hunter before the LORD. The phrase can be understood in more than one way and has generated later interpretations. A careful study should separate the wording from traditions that the verse itself does not explain.",
    "refs": "Genesis 10:8; Micah 5:6"
  },
  "Genesis 10:10": {
    "title": "The beginning of Nimrod’s kingdom",
    "text": "The verse names Babel, Erech, Accad, and Calneh as part of Nimrod’s kingdom in Shinar. Babel will become important in the next chapter. The text presents the rise of a kingdom, not a second divine authority alongside the LORD.",
    "refs": "Genesis 11:1–9"
  },
  "Genesis 10:11": {
    "title": "Asshur and the cities",
    "text": "The wording describes Asshur’s connection with the building of Nineveh and other cities; translations and interpretations differ on the subject of the action. The important point is the genealogy’s connection with ancient city centers. Avoid building a doctrine on an uncertain grammatical detail.",
    "refs": "Genesis 10:12; Jonah 1:2"
  },
  "Genesis 10:12": {
    "title": "Resen and the great city",
    "text": "The verse names Resen and describes the scale of the city grouping. Ancient city locations and the exact identification of the phrase have been debated. The verse records the prominence of these settlements without providing a modern archaeological map.",
    "refs": "Genesis 10:11"
  },
  "Genesis 10:13": {
    "title": "The sons of Mizraim",
    "text": "The genealogy lists descendants of Mizraim. The names represent ancient peoples in the biblical account. Their precise later identifications may require historical research, but the verse itself is a family list rather than a theological definition.",
    "refs": "Genesis 10:6; 1 Chronicles 1:11"
  },
  "Genesis 10:14": {
    "title": "The descendants associated with Pathrusim",
    "text": "The verse continues the descendants of Mizraim and mentions Philistim. The genealogy links peoples in the biblical story, although the exact relationships among some groups are discussed by historians. The wording should be reported without pretending every detail is beyond debate.",
    "refs": "Genesis 10:13; Jeremiah 47:4"
  },
  "Genesis 10:15": {
    "title": "Canaan’s descendants",
    "text": "Canaan’s descendants are listed, including Sidon and Heth. These names become important in later biblical history. The genealogy records ancestry; it does not give permission to treat present-day people as morally defined by an ancient family line.",
    "refs": "Genesis 15:18–21; Genesis 23:3–20"
  },
  "Genesis 10:16": {
    "title": "The Jebusites and other peoples",
    "text": "The verse lists peoples associated with Canaan. Later books refer to several of these groups in the history of Israel. Their place in the narrative should be understood in its historical and literary context, not used to make claims about modern ethnic worth.",
    "refs": "Exodus 3:8; Deuteronomy 7:1"
  },
  "Genesis 10:17": {
    "title": "The Hivites and other peoples",
    "text": "The list of Canaan’s descendants continues with additional people groups. The verse’s purpose is genealogical and geographic. It does not describe the individual character of every person in those populations.",
    "refs": "Genesis 10:15–18"
  },
  "Genesis 10:18": {
    "title": "The families of Canaan spread",
    "text": "The verse reports the spread of Canaan’s families and introduces the geographical description that follows. The genealogy portrays nations developing through family lines. This is narrative history, not a basis for racial superiority or inferiority.",
    "refs": "Genesis 10:19; Genesis 9:19"
  },
  "Genesis 10:19": {
    "title": "The borders of Canaan",
    "text": "The text gives a broad description of Canaan’s territory. The place names help orient the reader to the land that becomes important in the patriarchal narratives. Ancient boundaries do not always map neatly onto modern borders.",
    "refs": "Genesis 15:18–21; Numbers 34:2–12"
  },
  "Genesis 10:20": {
    "title": "The descendants of Ham summarized",
    "text": "The verse summarizes Ham’s descendants according to families, languages, lands, and nations. The repeated categories prepare for the chapter’s final summary. All are part of the same human story after the flood.",
    "refs": "Genesis 10:5; Genesis 10:31–32"
  },
  "Genesis 10:21": {
    "title": "Shem, father of Eber",
    "text": "Shem’s line is introduced, with Eber specifically mentioned. The name Eber is associated by many interpreters with the term “Hebrew,” though the exact etymological relationship should not be overstated. This genealogy leads toward Abram later in Genesis.",
    "refs": "Genesis 11:10–26; Genesis 14:13"
  },
  "Genesis 10:22": {
    "title": "The sons of Shem",
    "text": "The verse names Elam, Asshur, Arphaxad, Lud, and Aram. These names establish the branch of the genealogy that will eventually lead to Abram through Arphaxad. The passage records family descent and does not describe separate divine beings.",
    "refs": "Genesis 11:10–26; 1 Chronicles 1:17"
  },
  "Genesis 10:23": {
    "title": "The sons of Aram",
    "text": "The descendants of Aram are listed. The genealogy preserves connections among ancient peoples and families. Specific modern identifications should be made cautiously when the biblical text itself gives no further explanation.",
    "refs": "Genesis 10:22; 1 Chronicles 1:17"
  },
  "Genesis 10:24": {
    "title": "Arphaxad, Salah, and Eber",
    "text": "The verse traces a line from Arphaxad through Salah to Eber. This is part of the genealogy leading toward Abram. The line is important to the story’s structure, but the verse itself does not yet narrate the covenant with Abram.",
    "refs": "Genesis 11:10–26; Luke 3:35–36"
  },
  "Genesis 10:25": {
    "title": "Peleg and the division of the earth",
    "text": "Peleg’s name is associated with a division of the earth in his days. The verse does not specify exactly what event “division” means; interpretations include a division of peoples or lands. Genesis 11 follows with the story of Babel, but the precise relation should be stated as interpretation.",
    "refs": "Genesis 11:1–9"
  },
  "Genesis 10:26": {
    "title": "The sons of Joktan",
    "text": "The genealogy lists Joktan’s descendants. These names contribute to the account of peoples and territories in the ancient world. The verse does not directly establish modern national borders or the identity of every later population.",
    "refs": "Genesis 10:27–30"
  },
  "Genesis 10:27": {
    "title": "More descendants of Joktan",
    "text": "The verse continues the list of Joktan’s sons. The repeated names and family connections show how the chapter organizes the nations by ancestry. Where a name’s later location is uncertain, that uncertainty should be kept clear.",
    "refs": "Genesis 10:26; Genesis 10:30"
  },
  "Genesis 10:28": {
    "title": "The sons of Joktan continued",
    "text": "The genealogy adds more names to Joktan’s line. These records are part of the Bible’s account of the spread of peoples after the flood. They are not in themselves doctrinal statements about God’s nature.",
    "refs": "Genesis 10:26–29"
  },
  "Genesis 10:29": {
    "title": "The descendants of Joktan listed",
    "text": "The final names in this segment complete the list of Joktan’s sons. The genealogy emphasizes the breadth of human descent from the post-flood family lines. The chapter’s repeated structure helps readers follow the families and lands.",
    "refs": "Genesis 10:26–30"
  },
  "Genesis 10:30": {
    "title": "The dwelling place of Joktan’s descendants",
    "text": "The verse describes the region associated with Joktan’s descendants. The exact borders of ancient locations can be difficult to reconstruct, so modern identifications should be offered with appropriate caution. The verse’s direct role is geographical within the genealogy.",
    "refs": "Genesis 10:26–29"
  },
  "Genesis 10:31": {
    "title": "The descendants of Shem summarized",
    "text": "Shem’s descendants are summarized by families, languages, lands, and nations. This formula parallels the summaries of other branches in the chapter. The text presents all these groups as parts of the same post-flood human family.",
    "refs": "Genesis 10:20; Genesis 10:32"
  },
  "Genesis 10:32": {
    "title": "The nations spread after the flood",
    "text": "The chapter concludes that the nations spread from Noah’s sons after the flood. Genesis 10 organizes the nations by genealogy, while Genesis 11 will explain the Babel episode. The passage supports the unity of humanity’s descent, not racial ranking.",
    "refs": "Genesis 9:19; Acts 17:26"
  },
  "Genesis 11:1": {
    "title": "One language and common speech",
    "text": "The chapter begins with humanity sharing one language. The narrative sets the scene for a collective project that will be judged in the verses that follow. The unity of speech is not condemned by itself; the issue is what humanity chooses to do with its common purpose.",
    "refs": "Genesis 10:5; Genesis 11:6"
  },
  "Genesis 11:2": {
    "title": "The plain in Shinar",
    "text": "The people settle in the plain of Shinar. The location connects this account with Babel and the kingdom associated with Nimrod in Genesis 10. The verse provides the setting before the people explain their plan.",
    "refs": "Genesis 10:10; Genesis 11:4"
  },
  "Genesis 11:3": {
    "title": "Brick and mortar",
    "text": "The people make brick and use bitumen as mortar. These practical construction details show the means by which they intend to build. The narrative focuses not on technology itself but on the purpose revealed in the next verse.",
    "refs": "Genesis 11:4"
  },
  "Genesis 11:4": {
    "title": "A city and a tower",
    "text": "The people want a city and a tower reaching to heaven, to make a name for themselves and avoid being scattered. Their stated purpose places self-exaltation and resistance to spreading across the earth at the center of the project. The verse should not be turned into a claim that all tall buildings are sinful.",
    "refs": "Genesis 9:1; Genesis 11:8"
  },
  "Genesis 11:5": {
    "title": "The LORD comes down to see",
    "text": "The LORD comes down to see the city and tower built by humanity. This is vivid narrative language communicating God's attention to human action; it does not imply that God lacked knowledge until He physically arrived. Scripture often describes God's acts in language accessible to human readers.",
    "refs": "Genesis 18:21; Psalm 113:5–6"
  },
  "Genesis 11:6": {
    "title": "One people with one language",
    "text": "God observes that the people are united and that their project is only beginning. The concern is not that human cooperation is always evil, but that unified power directed by pride can magnify rebellion. The verse does not say that human beings can literally become equal to God.",
    "refs": "Genesis 11:4; Proverbs 16:18"
  },
  "Genesis 11:7": {
    "title": "Let us go down",
    "text": "God speaks in the plural, “Let us go down,” before confusing their language. Oneness readers should acknowledge the plural wording rather than pretend it is absent. The verse itself does not explain the referent of “us”; it should be read with the wider biblical context and not used alone as conclusive proof of multiple divine persons.",
    "refs": "Genesis 1:26; Isaiah 44:24"
  },
  "Genesis 11:8": {
    "title": "The people are scattered",
    "text": "The LORD scatters the people over the earth and the building stops. This reverses their stated aim of staying together in one place. The narrative presents God's action as preventing the completion of a proud, disobedient project.",
    "refs": "Genesis 9:1; Genesis 11:4"
  },
  "Genesis 11:9": {
    "title": "Babel and confused language",
    "text": "The place is called Babel because the LORD confounded the language and scattered the people. The name is explained within the biblical story through the confusion of speech. The verse emphasizes that human schemes do not override God's purpose for the earth.",
    "refs": "Genesis 10:10; Acts 2:5–11"
  },
  "Genesis 11:10": {
    "title": "The generations of Shem",
    "text": "The genealogy of Shem begins a line leading toward Abram. The chapter moves from the spread of nations back to a particular family line through which the story of the patriarchs will continue. The ages are stated as the biblical text presents them.",
    "refs": "Genesis 10:21–31; Luke 3:35–36"
  },
  "Genesis 11:11": {
    "title": "Shem’s years after Arphaxad",
    "text": "The verse records Shem’s lifespan and descendants after the birth of Arphaxad. These details preserve the genealogy’s chronology. The verse does not itself explain every chronological question readers may raise when comparing genealogies.",
    "refs": "Genesis 11:10; Genesis 11:12"
  },
  "Genesis 11:12": {
    "title": "Arphaxad and Salah",
    "text": "Arphaxad fathers Salah at the age stated in the text. This is one link in the family line leading to Abram. Later genealogies repeat this line, making it important to the biblical account of ancestry.",
    "refs": "Genesis 10:24; Luke 3:36"
  },
  "Genesis 11:13": {
    "title": "Arphaxad’s later years",
    "text": "The verse records Arphaxad’s years after Salah’s birth and the continuation of his family. It functions as a chronological link rather than a separate theological teaching. Read the numbers as given in the translation being studied.",
    "refs": "Genesis 11:12"
  },
  "Genesis 11:14": {
    "title": "Salah fathers Eber",
    "text": "Salah fathers Eber at the age recorded. Eber’s name appears in the earlier genealogy and the line continues toward Abram. The repeated pattern emphasizes descent through successive generations.",
    "refs": "Genesis 10:24; Genesis 11:16"
  },
  "Genesis 11:15": {
    "title": "Salah’s later years",
    "text": "The verse records Salah’s remaining years and descendants. It continues the structured genealogy that links Shem’s family to Terah and Abram. Its main function is to preserve the family line.",
    "refs": "Genesis 11:14"
  },
  "Genesis 11:16": {
    "title": "Eber fathers Peleg",
    "text": "Eber fathers Peleg at the age stated. Peleg was mentioned in Genesis 10:25, where the division of the earth is noted. The genealogy connects that earlier statement with the line leading to Abram.",
    "refs": "Genesis 10:25; Genesis 11:18"
  },
  "Genesis 11:17": {
    "title": "Eber’s later years",
    "text": "The verse records Eber’s remaining lifespan and descendants. The genealogical formula repeats to show the continuity of the family line. It does not require an additional doctrinal interpretation beyond the record it provides.",
    "refs": "Genesis 11:16"
  },
  "Genesis 11:18": {
    "title": "Peleg fathers Reu",
    "text": "Peleg fathers Reu, continuing the genealogy. The list narrows the reader’s attention toward Abram’s immediate ancestors. The verse is a link in the narrative’s family record.",
    "refs": "Genesis 11:16–20"
  },
  "Genesis 11:19": {
    "title": "Peleg’s later years",
    "text": "The verse records Peleg’s remaining years and descendants. These repeated dates help structure the genealogy. Where readers compare ancient chronological systems, the translation and textual tradition being used should be made clear.",
    "refs": "Genesis 11:18"
  },
  "Genesis 11:20": {
    "title": "Reu fathers Serug",
    "text": "Reu fathers Serug at the age stated. The genealogy continues toward Nahor, Terah, and Abram. The verse does not yet describe the covenant promises that will later be given to Abram.",
    "refs": "Genesis 11:22–26"
  },
  "Genesis 11:21": {
    "title": "Reu’s later years",
    "text": "The verse records Reu’s remaining years and descendants. The repetition gives continuity to the family record and leads to the next generation. Its role is genealogical.",
    "refs": "Genesis 11:20"
  },
  "Genesis 11:22": {
    "title": "Serug fathers Nahor",
    "text": "Serug fathers Nahor at the age stated. Nahor will be part of the family background of Terah and Abram. The narrative is preparing for the transition from a list of generations to the story of a particular household.",
    "refs": "Genesis 11:24–26"
  },
  "Genesis 11:23": {
    "title": "Serug’s later years",
    "text": "The verse records Serug’s remaining years and descendants. It continues the chronology toward Abram’s family. As with the other entries, the text provides a record rather than an independent doctrinal claim.",
    "refs": "Genesis 11:22"
  },
  "Genesis 11:24": {
    "title": "Nahor fathers Terah",
    "text": "Nahor fathers Terah at the stated age. Terah becomes the father of Abram, Nahor, and Haran in the following verses. The genealogy is now approaching the family at the center of the next major biblical section.",
    "refs": "Genesis 11:26"
  },
  "Genesis 11:25": {
    "title": "Nahor’s later years",
    "text": "The verse records Nahor’s remaining lifespan and descendants. The formula links one generation to another and preserves the narrative’s chronology. The next verse identifies Terah’s sons.",
    "refs": "Genesis 11:24–26"
  },
  "Genesis 11:26": {
    "title": "Terah’s sons",
    "text": "Terah fathers Abram, Nahor, and Haran. The order of names does not necessarily establish the exact birth order of all three, so conclusions about age should be drawn cautiously. Abram now becomes the central figure in the narrative.",
    "refs": "Genesis 11:27; Joshua 24:2"
  },
  "Genesis 11:27": {
    "title": "The family of Terah",
    "text": "The verse introduces Terah’s family and names Abram, Nahor, and Haran, including Lot as Haran’s son. This family record sets up the journey and promises in the next chapter. Lot’s relationship to Abram will matter in later events.",
    "refs": "Genesis 12:4–5; Genesis 13:1"
  },
  "Genesis 11:28": {
    "title": "Haran dies in Ur",
    "text": "Haran dies in the land of his birth, Ur of the Chaldees, while his father Terah is alive. The detail explains part of the family situation before Abram’s journey. The verse gives a place name but does not settle every question about the precise archaeological location.",
    "refs": "Genesis 11:31; Genesis 15:7"
  },
  "Genesis 11:29": {
    "title": "Abram and Nahor marry",
    "text": "The verse records the marriages of Abram and Nahor and identifies their wives. These family details lead into the later story of Sarah and Rebekah. The verse itself does not provide a doctrinal teaching about marriage beyond recording the relationships.",
    "refs": "Genesis 17:15; Genesis 24:15"
  },
  "Genesis 11:30": {
    "title": "Sarai is barren",
    "text": "Sarai has no child. This detail establishes an obstacle that will make God’s later promise of offspring especially significant. The story repeatedly shows that the promised future depends on God's action rather than ordinary human expectation.",
    "refs": "Genesis 15:2–5; Genesis 18:10–14"
  },
  "Genesis 11:31": {
    "title": "Terah leaves Ur",
    "text": "Terah takes Abram, Sarai, and Lot toward Canaan but settles in Haran. The journey begins before Abram’s later call is narrated in Genesis 12. The verse records the family’s movement and partial journey without yet giving all the details of God’s command.",
    "refs": "Genesis 12:1–5; Acts 7:2–4"
  },
  "Genesis 11:32": {
    "title": "Terah dies in Haran",
    "text": "Terah’s lifespan and death in Haran close the genealogy section. The next chapter focuses on God’s call to Abram. The narrative moves from the broader history of nations to God’s dealings with one family.",
    "refs": "Genesis 12:1; Joshua 24:2"
  },
  "Genesis 12:1": {
    "title": "The LORD calls Abram",
    "text": "The LORD tells Abram to leave his country, kindred, and father’s house for a land God will show him. The call begins a major covenant story. The verse presents the LORD as the one who speaks and directs Abram; it does not describe a separate divine person.",
    "refs": "Acts 7:2–4; Hebrews 11:8"
  },
  "Genesis 12:2": {
    "title": "A great nation and a blessing",
    "text": "God promises to make Abram a great nation, bless him, and make his name great so that he will be a blessing. The promise is not merely personal success; it has a purpose beyond Abram himself. Later Scripture connects the blessing to the nations through Abram’s seed.",
    "refs": "Genesis 18:18; Galatians 3:8"
  },
  "Genesis 12:3": {
    "title": "Blessing for all families",
    "text": "God promises blessing for those who bless Abram and speaks of all families of the earth being blessed through him. The New Testament connects this promise with the gospel going to the nations. In Oneness study, this shows the one God working through His promised plan of redemption, ultimately fulfilled in Christ.",
    "refs": "Genesis 22:18; Acts 3:25–26; Galatians 3:16"
  },
  "Genesis 12:4": {
    "title": "Abram obeys the call",
    "text": "Abram departs as the LORD had spoken, and Lot goes with him. Hebrews later describes Abram’s departure as an act of faith. Faith here is shown through trusting God’s word enough to obey, even when the destination is not fully known.",
    "refs": "Hebrews 11:8; Genesis 12:1"
  },
  "Genesis 12:5": {
    "title": "Abram’s household travels",
    "text": "Abram takes Sarai, Lot, their possessions, and the people they had gathered, and they travel toward Canaan. The verse shows that obedience affects a household and involves practical movement and preparation. God’s call unfolds within ordinary family life.",
    "refs": "Genesis 11:31; Genesis 12:6"
  },
  "Genesis 12:6": {
    "title": "Abram comes to Canaan",
    "text": "Abram travels through the land to the place of Sichem and the plain of Moreh, where the Canaanite was then in the land. The verse situates Abram’s arrival in a land already inhabited. The promise of the land develops through later covenant passages.",
    "refs": "Genesis 13:14–17; Genesis 15:18–21"
  },
  "Genesis 12:7": {
    "title": "The LORD appears and promises the land",
    "text": "The LORD appears to Abram and promises the land to his seed; Abram builds an altar. The text explicitly says the LORD appeared, but does not specify a visible form here. The altar marks Abram’s worshipful response to God’s promise.",
    "refs": "Genesis 13:14–17; Acts 7:5"
  },
  "Genesis 12:8": {
    "title": "Abram calls on the name of the LORD",
    "text": "Abram builds an altar and calls on the name of the LORD. The phrase describes worship and public invocation of the LORD’s name. Later Scripture connects calling on the Lord’s name with salvation; interpretation of that connection should consider the context of each passage.",
    "refs": "Genesis 4:26; Joel 2:32; Acts 2:21; Romans 10:13"
  },
  "Genesis 12:9": {
    "title": "Abram journeys south",
    "text": "Abram continues his journey toward the south. The verse is a brief geographical transition between episodes. It shows the movement of Abram’s household through the land God has promised.",
    "refs": "Genesis 12:6–8"
  },
  "Genesis 12:10": {
    "title": "A famine in the land",
    "text": "A famine comes upon the land, and Abram goes down to Egypt to sojourn there. The promise of God does not mean the path will be free of hardship. The narrative records Abram’s response to a practical crisis, which leads to a morally complicated episode.",
    "refs": "Genesis 26:1; Hebrews 11:8–10"
  },
  "Genesis 12:11": {
    "title": "Abram fears for Sarai",
    "text": "As Abram approaches Egypt, he tells Sarai that he knows she is beautiful. The next verses reveal that fear influences his decisions. Scripture reports the patriarch’s actions honestly; reporting them is not the same as approving them.",
    "refs": "Genesis 12:12–13"
  },
  "Genesis 12:12": {
    "title": "Abram anticipates danger",
    "text": "Abram fears the Egyptians may kill him because of Sarai. The verse shows his concern for his own life and sets up his request that follows. The narrative invites readers to notice how fear can shape a believer’s choices.",
    "refs": "Genesis 12:13; Proverbs 29:25"
  },
  "Genesis 12:13": {
    "title": "Call Sarai his sister",
    "text": "Abram asks Sarai to say she is his sister so that he may be treated well and remain alive. Although Sarai is his half-sister according to Genesis 20:12, the request conceals the marital relationship and places her at risk. Scripture’s account should not be mistaken for a moral endorsement of deception.",
    "refs": "Genesis 20:12; Proverbs 12:22"
  },
  "Genesis 12:14": {
    "title": "The Egyptians see Sarai",
    "text": "When Abram and Sarai enter Egypt, the Egyptians notice Sarai’s beauty. This is the situation Abram feared. The narrative moves quickly to the consequences of his plan.",
    "refs": "Genesis 12:11–13"
  },
  "Genesis 12:15": {
    "title": "Sarai is taken to Pharaoh’s house",
    "text": "Pharaoh’s officials praise Sarai and she is taken into Pharaoh’s house. The verse shows the danger created by Abram’s concealment. The text does not say that Sarai consented to this outcome, and her vulnerability should not be overlooked.",
    "refs": "Genesis 12:13; Genesis 12:17"
  },
  "Genesis 12:16": {
    "title": "Abram receives possessions",
    "text": "Pharaoh treats Abram well because of Sarai and Abram acquires livestock and servants. The material benefit comes through a deceptive situation and should not be read as proof that God approves Abram’s conduct. The next verse shows God intervening.",
    "refs": "Genesis 12:17; Genesis 13:1–2"
  },
  "Genesis 12:17": {
    "title": "The LORD plagues Pharaoh’s house",
    "text": "The LORD afflicts Pharaoh and his household because of Sarai. God acts to protect the promise and prevent the situation from continuing. The text attributes the intervention to the LORD, the one God who acts in the narrative.",
    "refs": "Genesis 20:3–7; Genesis 12:3"
  },
  "Genesis 12:18": {
    "title": "Pharaoh confronts Abram",
    "text": "Pharaoh calls Abram and asks why he concealed that Sarai was his wife. The rebuke exposes Abram’s dishonesty, even from a foreign ruler. Scripture does not hide the failure of its central figures.",
    "refs": "Genesis 12:13; Genesis 20:9–10"
  },
  "Genesis 12:19": {
    "title": "Sarai returned",
    "text": "Pharaoh asks why Abram said Sarai was his sister and returns her to him. The episode ends with the deception exposed. The text does not praise Abram’s strategy; it records the consequences and God’s protection of Sarai.",
    "refs": "Genesis 12:17–20"
  },
  "Genesis 12:20": {
    "title": "Abram leaves Egypt",
    "text": "Pharaoh orders men to send Abram away with Sarai and all he has. The chapter ends with Abram leaving Egypt, carrying the possessions acquired during the episode. The story continues to show a real believer whose faith journey includes failures as well as obedience.",
    "refs": "Genesis 13:1–4; Genesis 15:6"
  },
  "Genesis 13:1": {
    "title": "Abram returns from Egypt",
    "text": "Abram returns from Egypt with Sarai, Lot, and his possessions. The earlier deception has ended, but the story continues with the household God has called. The narrative records the journey without claiming Abram’s earlier actions were right.",
    "refs": "Genesis 12:10–20; Genesis 13:3–4"
  },
  "Genesis 13:2": {
    "title": "Abram is very rich",
    "text": "Abram has livestock, silver, and gold. The verse reports his possessions but does not teach that wealth alone proves a person is righteous or favored in every circumstance. The story soon shows that possessions can also create practical difficulties.",
    "refs": "Genesis 12:16; Proverbs 30:8–9"
  },
  "Genesis 13:3": {
    "title": "Back to Bethel",
    "text": "Abram travels back to the place between Bethel and Hai where he had previously pitched his tent. The return links this chapter to his earlier journey and worship. The account emphasizes continuity in Abram’s life of pilgrimage.",
    "refs": "Genesis 12:8; Genesis 13:4"
  },
  "Genesis 13:4": {
    "title": "Abram calls on the LORD",
    "text": "Abram returns to the altar and calls on the name of the LORD. The verse describes worship of the one LORD who has called and guided him. It does not introduce multiple divine beings; the focus is Abram’s invocation of God’s name.",
    "refs": "Genesis 12:8; Joel 2:32"
  },
  "Genesis 13:5": {
    "title": "Lot also has flocks",
    "text": "Lot, who travels with Abram, also has flocks, herds, and tents. Their combined households now possess substantial resources. The next verses show that prosperity brings a conflict over land and grazing space.",
    "refs": "Genesis 12:5; Genesis 13:6"
  },
  "Genesis 13:6": {
    "title": "The land cannot support both households",
    "text": "The land cannot support Abram and Lot living together because their possessions are so great. The conflict is presented as a practical resource problem, not simply as evidence that either man is wicked. The story now tests how they will handle disagreement.",
    "refs": "Genesis 13:5; Proverbs 15:1"
  },
  "Genesis 13:7": {
    "title": "Strife between the herdsmen",
    "text": "Conflict arises between Abram’s herdsmen and Lot’s, while Canaanites and Perizzites live in the land. The narrative notes the wider setting and the danger of ongoing strife. Abram’s response will seek peace rather than escalate the dispute.",
    "refs": "Genesis 13:8–9; Romans 12:18"
  },
  "Genesis 13:8": {
    "title": "Let there be no strife",
    "text": "Abram asks that there be no strife between him and Lot because they are brethren. He prioritizes peace within the family relationship. The passage gives a practical example of seeking reconciliation instead of insisting on winning every dispute.",
    "refs": "Psalm 133:1; Romans 12:18"
  },
  "Genesis 13:9": {
    "title": "Choose the land",
    "text": "Abram offers Lot the choice of land and agrees to separate if Lot goes one way and he the other. Abram does not cling to first choice, showing a willingness to make room for peace. The verse is a narrative example, not a universal rule that one must always surrender every right.",
    "refs": "Matthew 5:9; Philippians 2:3–4"
  },
  "Genesis 13:10": {
    "title": "Lot sees the plain of Jordan",
    "text": "Lot looks toward the well-watered plain of Jordan, which appears like the garden of the LORD and the land of Egypt. The text describes its appearance before explaining the moral danger of the nearby cities. Attractive appearances do not reveal every consequence of a choice.",
    "refs": "Genesis 2:10; Genesis 19:24–25"
  },
  "Genesis 13:11": {
    "title": "Lot chooses the plain",
    "text": "Lot chooses the plain of Jordan and separates from Abram. The choice is based on what he sees as a good land, while the following verses identify the wickedness of Sodom. The narrative invites readers to consider more than immediate material advantage.",
    "refs": "Genesis 13:12–13; Proverbs 14:12"
  },
  "Genesis 13:12": {
    "title": "Lot pitches toward Sodom",
    "text": "Abram dwells in Canaan, while Lot settles among the cities of the plain and pitches his tent toward Sodom. The direction of Lot’s movement sets up his deeper involvement with the city. The verse itself describes location; the next verse gives Sodom’s moral condition.",
    "refs": "Genesis 13:13; Genesis 14:12"
  },
  "Genesis 13:13": {
    "title": "The men of Sodom are wicked",
    "text": "The text directly describes the men of Sodom as exceedingly wicked and sinful before the LORD. This is the narrator’s moral assessment, not merely Abram’s opinion. The next chapters show the consequences of the city’s corruption.",
    "refs": "Genesis 18:20; Genesis 19:4–9"
  },
  "Genesis 13:14": {
    "title": "God tells Abram to look",
    "text": "After Lot separates, the LORD tells Abram to lift his eyes and look in every direction. God’s promise comes after the separation, reassuring Abram about the land. The narrative portrays the LORD as the one speaking and promising, the one God of Abram.",
    "refs": "Genesis 12:7; Genesis 15:18"
  },
  "Genesis 13:15": {
    "title": "The land promised to Abram’s seed",
    "text": "God promises the land to Abram and his seed forever. The verse is part of the covenant promise developed throughout Genesis. Later biblical interpretation connects God’s promises to the larger story of redemption, but the immediate wording concerns Abram’s descendants and land.",
    "refs": "Genesis 15:18; Genesis 17:8"
  },
  "Genesis 13:16": {
    "title": "Descendants like the dust",
    "text": "God compares Abram’s seed with the dust of the earth, emphasizing a vast number of descendants. At this point Abram has no child by Sarai, making the promise humanly difficult to imagine. The narrative invites trust in God’s word despite present circumstances.",
    "refs": "Genesis 15:5; Romans 4:18–21"
  },
  "Genesis 13:17": {
    "title": "Walk through the land",
    "text": "God tells Abram to walk through the land in its length and breadth. The action connects the promise with the actual land and Abram’s life there. It is an instruction within this covenant narrative, not a general command to claim any territory for oneself.",
    "refs": "Genesis 12:7; Genesis 15:18"
  },
  "Genesis 13:18": {
    "title": "Abram builds an altar at Hebron",
    "text": "Abram moves his tent and builds an altar to the LORD. As in earlier episodes, movement through the land is paired with worship. The altar marks Abram’s response to God’s promise and his continuing dependence on the LORD.",
    "refs": "Genesis 12:7–8; Genesis 13:4"
  },
  "Genesis 14:1": {
    "title": "Kings go to war",
    "text": "The chapter names kings involved in a regional conflict. The historical names and locations situate the episode in the ancient world, though identifying every ruler with certainty can be difficult. The narrative uses the conflict to explain Lot’s capture and Abram’s rescue mission.",
    "refs": "Genesis 14:2–4"
  },
  "Genesis 14:2": {
    "title": "The kings of the plain",
    "text": "The verse lists the rulers of Sodom, Gomorrah, Admah, Zeboiim, and Bela. These cities will matter in the story of Lot and the judgment of Sodom. The list is historical narrative and does not itself make a claim about the Godhead.",
    "refs": "Genesis 13:10; Genesis 19:24–25"
  },
  "Genesis 14:3": {
    "title": "The valley of Siddim",
    "text": "The kings gather in the valley of Siddim, identified with the Salt Sea. The verse provides the setting for the battle. Ancient geographical identifications can be debated, so modern location claims should be made cautiously.",
    "refs": "Genesis 14:8–10"
  },
  "Genesis 14:4": {
    "title": "Twelve years of service",
    "text": "The kings had served Chedorlaomer for twelve years and rebelled in the thirteenth. This establishes the political background to the conflict. The verse records a change in allegiance and the cause of the campaign that follows.",
    "refs": "Genesis 14:1; Genesis 14:5"
  },
  "Genesis 14:5": {
    "title": "The campaign against the Rephaim",
    "text": "Chedorlaomer and allied kings defeat several peoples in a campaign. The names and places provide the route and scale of the conflict. The narrative reports military events without requiring every ancient location to be identified with certainty today.",
    "refs": "Genesis 14:6–7"
  },
  "Genesis 14:6": {
    "title": "The Horites in Seir",
    "text": "The campaign reaches the Horites in the hill country of Seir. The verse is part of the account of the kings’ advance through the region. Its primary purpose is geographical and historical within the story.",
    "refs": "Deuteronomy 2:12; Genesis 14:5"
  },
  "Genesis 14:7": {
    "title": "The return to En-mishpat",
    "text": "The kings return to En-mishpat and strike the Amalekites and Amorites. The passage records peoples and places before the battle in the valley. Later biblical references to these groups should be read in their own historical contexts.",
    "refs": "Genesis 14:8; Genesis 15:16"
  },
  "Genesis 14:8": {
    "title": "The kings prepare for battle",
    "text": "The kings of the plain go out to battle in the valley of Siddim. The conflict that follows leads to the capture of Lot and his goods. The text sets out the battle’s immediate setting without suggesting that military power determines righteousness.",
    "refs": "Genesis 14:9–12"
  },
  "Genesis 14:9": {
    "title": "Four kings against five",
    "text": "The opposing coalition is listed as four kings against five. The numbers establish the imbalance and scale of the conflict. The outcome is described in the following verses, including the flight of the kings of Sodom and Gomorrah.",
    "refs": "Genesis 14:10–11"
  },
  "Genesis 14:10": {
    "title": "The valley’s slime pits",
    "text": "The valley contains pits of bitumen, and the kings of Sodom and Gomorrah flee. The verse describes the terrain and the defeat of the local kings. The narrative now explains how the defeated cities’ people and possessions are taken.",
    "refs": "Genesis 14:11"
  },
  "Genesis 14:11": {
    "title": "Goods and provisions taken",
    "text": "The victorious kings take the goods and provisions of Sodom and Gomorrah and depart. This includes the possessions that will bring Lot into the story of the conflict. The verse describes the consequences of war for the people living in the cities.",
    "refs": "Genesis 14:12"
  },
  "Genesis 14:12": {
    "title": "Lot is captured",
    "text": "Lot, Abram’s nephew, is taken with his goods because he lives in Sodom. The choice to settle near Sodom now has direct consequences for Lot. The verse does not say Lot deserved capture; it reports what happened in the invasion.",
    "refs": "Genesis 13:12–13; Genesis 14:14"
  },
  "Genesis 14:13": {
    "title": "Abram the Hebrew",
    "text": "A survivor tells Abram the Hebrew about the capture. The verse identifies Abram by a term associated with his people and reports that he is living near the Amorites. The story turns from the kings’ war to Abram’s response to news of Lot.",
    "refs": "Genesis 11:26–28; Genesis 14:14"
  },
  "Genesis 14:14": {
    "title": "Abram gathers trained men",
    "text": "Abram hears that his brother is taken and gathers trained men from his household to pursue the captors. Here “brother” is used broadly for a close relative, since Lot is his nephew. Abram’s response is active and practical, not merely verbal concern.",
    "refs": "Genesis 12:5; Genesis 14:15"
  },
  "Genesis 14:15": {
    "title": "Abram divides his forces",
    "text": "Abram divides his men by night and attacks the opposing force, pursuing them beyond Damascus. The narrative presents a tactical rescue effort. The text does not claim Abram acted alone or that the battle was won by supernatural means explicitly stated in this verse.",
    "refs": "Genesis 14:14; Genesis 14:16"
  },
  "Genesis 14:16": {
    "title": "Lot and the goods recovered",
    "text": "Abram brings back Lot, the goods, the women, and the people. The rescue reverses the outcome of the raid. The following meeting with Melchizedek introduces a priest-king who blesses Abram in the name of the most high God.",
    "refs": "Genesis 14:17–20"
  },
  "Genesis 14:17": {
    "title": "The king of Sodom meets Abram",
    "text": "The king of Sodom comes out to meet Abram after his victory. The scene prepares for Abram’s conversation with both the king of Sodom and Melchizedek. The contrast between their offers and words is important to the chapter’s conclusion.",
    "refs": "Genesis 14:18–24"
  },
  "Genesis 14:18": {
    "title": "Melchizedek, priest of the most high God",
    "text": "Melchizedek, king of Salem and priest of the most high God, brings bread and wine. The text presents him as a priest of God and a king. Hebrews later uses Melchizedek in a theological comparison with Christ, but Genesis itself does not explicitly say Melchizedek is Jesus incarnate.",
    "refs": "Psalm 110:4; Hebrews 7:1–17"
  },
  "Genesis 14:19": {
    "title": "The most high God, possessor of heaven and earth",
    "text": "Melchizedek blesses Abram in the name of the most high God, possessor of heaven and earth. The verse declares God’s sovereignty over all creation. Oneness readers can emphasize the one God who owns heaven and earth without needing to multiply divine persons.",
    "refs": "Deuteronomy 6:4; Isaiah 44:24"
  },
  "Genesis 14:20": {
    "title": "God delivers the enemies",
    "text": "Melchizedek blesses the most high God who delivered Abram’s enemies into his hand, and Abram gives him a tenth. The verse attributes the victory ultimately to God. The tithe here is an act in the narrative; later legal instructions about tithes should be studied in their own contexts.",
    "refs": "Genesis 14:18–19; Hebrews 7:4–10"
  },
  "Genesis 14:21": {
    "title": "The king offers the goods",
    "text": "The king of Sodom tells Abram to give him the people and keep the goods. This offer sets up Abram’s refusal to become indebted to the king. The chapter contrasts the king’s offer with Abram’s desire that the LORD alone be recognized as the source of his prosperity.",
    "refs": "Genesis 14:22–24"
  },
  "Genesis 14:22": {
    "title": "Abram lifts his hand to the LORD",
    "text": "Abram swears by the LORD, the most high God, possessor of heaven and earth. The verse identifies the LORD as the God Abram worships and invokes. This is consistent with the biblical confession of one sovereign God over all creation.",
    "refs": "Genesis 14:19; Deuteronomy 6:4"
  },
  "Genesis 14:23": {
    "title": "Abram refuses the king’s riches",
    "text": "Abram refuses to take even a thread or a shoe-latchet from the king, lest the king claim to have made Abram rich. Abram wants no ambiguity about the source of his blessing. The verse teaches integrity in this situation, not a universal ban on receiving any material payment.",
    "refs": "Genesis 14:22; Proverbs 10:9"
  },
  "Genesis 14:24": {
    "title": "The allies receive their share",
    "text": "Abram allows his allies to take their share while declining the goods for himself. His refusal does not deny the legitimate participation of those who helped in the rescue. The chapter ends with fairness toward allies and loyalty to the LORD.",
    "refs": "Genesis 14:13; Genesis 14:23"
  },
  "Genesis 15:1": {
    "title": "Fear not, Abram",
    "text": "After these events, the word of the LORD comes to Abram in a vision: God tells him not to fear and calls Himself Abram’s shield and great reward. The passage presents God as the speaker and protector. It does not describe a second divine being speaking alongside the LORD.",
    "refs": "Psalm 3:3; Isaiah 41:10"
  },
  "Genesis 15:2": {
    "title": "Abram asks about an heir",
    "text": "Abram asks what God will give him while he remains childless and names Eliezer of Damascus. The question is honest distress in the face of a promise that has not yet come to pass. Scripture records the question rather than condemning Abram for bringing his concern before God.",
    "refs": "Genesis 12:2; Genesis 11:30"
  },
  "Genesis 15:3": {
    "title": "A servant as heir",
    "text": "Abram repeats that he has no child and that a household servant may inherit his estate. His concern shows the gap between the promise and his present circumstances. The next verse answers the specific question of who will be his heir.",
    "refs": "Genesis 15:4–5"
  },
  "Genesis 15:4": {
    "title": "Abram’s own son",
    "text": "The word of the LORD tells Abram that the servant will not be his heir; one coming from Abram’s own body will be his heir. God’s promise becomes more specific. The passage emphasizes the reliability of God’s word despite Abram’s age and circumstances.",
    "refs": "Genesis 17:16–19; Romans 4:18–21"
  },
  "Genesis 15:5": {
    "title": "Count the stars",
    "text": "God brings Abram outside and compares his descendants to the stars. The image communicates a multitude beyond Abram’s ability to count. The promise is grounded in God’s word, not in what Abram can presently see.",
    "refs": "Genesis 22:17; Romans 4:18"
  },
  "Genesis 15:6": {
    "title": "Abram believed the LORD",
    "text": "Abram believes the LORD, and it is counted to him for righteousness. This verse becomes foundational in later teaching about faith and righteousness. Faith is trust in the God who speaks; it is not a claim that Abram has earned the promise by flawless conduct.",
    "refs": "Romans 4:3; Galatians 3:6; James 2:23"
  },
  "Genesis 15:7": {
    "title": "The LORD brought Abram from Ur",
    "text": "The LORD identifies Himself as the one who brought Abram from Ur of the Chaldees to give him the land. God reminds Abram of His past action as assurance of the promise. The verse directly names the LORD as the deliverer and giver.",
    "refs": "Genesis 12:1; Nehemiah 9:7"
  },
  "Genesis 15:8": {
    "title": "Abram asks for assurance",
    "text": "Abram asks how he may know that he will inherit the land. The question leads to the covenant ceremony that follows. The text presents a request for assurance within the relationship God has initiated, not a rejection of God’s identity.",
    "refs": "Genesis 15:9–18"
  },
  "Genesis 15:9": {
    "title": "Animals for the covenant",
    "text": "God instructs Abram to bring specified animals and birds. The animals are part of the covenant ceremony that follows. Their precise symbolic meanings should not be asserted beyond what the text and later Scripture support.",
    "refs": "Jeremiah 34:18–19"
  },
  "Genesis 15:10": {
    "title": "The animals are divided",
    "text": "Abram divides the animals and lays the pieces opposite each other, while the birds are not divided. This prepares for the covenant sign in which God’s presence passes between the pieces. The action belongs to an ancient covenant ceremony, not a ritual Christians are commanded to repeat.",
    "refs": "Genesis 15:17; Jeremiah 34:18"
  },
  "Genesis 15:11": {
    "title": "Abram drives away the birds",
    "text": "Birds of prey come down on the carcasses, and Abram drives them away. The verse describes what happens during the waiting period. Later symbolic interpretations are possible, but the text itself does not explicitly identify the birds with a particular enemy or spiritual power.",
    "refs": "Genesis 15:12"
  },
  "Genesis 15:12": {
    "title": "A deep sleep and great darkness",
    "text": "As the sun goes down, a deep sleep and great darkness fall on Abram. The scene prepares for God’s revelation about Abram’s descendants. The passage uses solemn imagery to introduce the future hardship and deliverance God will describe.",
    "refs": "Genesis 2:21; Job 4:13"
  },
  "Genesis 15:13": {
    "title": "Strangers and affliction",
    "text": "God tells Abram that his descendants will be strangers in a land not theirs and will be afflicted for four hundred years. The prophecy anticipates Israel’s experience in Egypt, though biblical passages express the time periods in different ways that require careful comparison. The verse shows that God knows the hardship before it happens.",
    "refs": "Exodus 12:40–41; Acts 7:6"
  },
  "Genesis 15:14": {
    "title": "God judges the oppressing nation",
    "text": "God says He will judge the nation that enslaves Abram’s descendants and that they will leave with great substance. This anticipates the exodus from Egypt. The promise presents God as judge and deliverer, not as a passive observer of oppression.",
    "refs": "Exodus 3:7–8; Exodus 12:35–36"
  },
  "Genesis 15:15": {
    "title": "Abram’s peaceful death",
    "text": "God tells Abram he will go to his fathers in peace and be buried at a good old age. The prophecy distinguishes Abram’s own lifespan from the later hardship of his descendants. The verse offers a personal promise within the larger covenant plan.",
    "refs": "Genesis 25:7–10"
  },
  "Genesis 15:16": {
    "title": "The fourth generation",
    "text": "God says Abram’s descendants will return in the fourth generation because the iniquity of the Amorites is not yet full. The verse presents judgment as delayed rather than arbitrary. The text connects the timing of the land promise with moral accountability in history.",
    "refs": "Leviticus 18:24–28; Deuteronomy 9:4–5"
  },
  "Genesis 15:17": {
    "title": "The smoking furnace and burning lamp",
    "text": "A smoking furnace and burning lamp pass between the pieces as the sun sets. The scene marks God’s covenant commitment. The verse does not explicitly identify these signs as separate divine persons; the narrative portrays God ratifying the covenant with Abram.",
    "refs": "Genesis 15:18; Exodus 13:21"
  },
  "Genesis 15:18": {
    "title": "The LORD makes a covenant",
    "text": "The LORD makes a covenant with Abram and describes the land’s boundaries. The promise is specific to Abram’s descendants in the covenant narrative. Later biblical interpretation should preserve the original context while also tracing how Scripture develops the promise.",
    "refs": "Genesis 12:7; Genesis 17:8"
  },
  "Genesis 15:19": {
    "title": "The land’s peoples named",
    "text": "The verse names peoples whose lands are included in the promise. These are ancient groups in the narrative, and identifying each with modern populations requires caution. The list situates the covenant in a real geographical and historical setting.",
    "refs": "Genesis 15:18; Exodus 3:8"
  },
  "Genesis 15:20": {
    "title": "More peoples named",
    "text": "The list of peoples continues. The names help define the land described in the covenant. The verse is geographical and historical in function, not a separate teaching about the Godhead.",
    "refs": "Genesis 15:18–21"
  },
  "Genesis 15:21": {
    "title": "The final peoples in the list",
    "text": "The verse completes the list of peoples whose land is described in the covenant. The passage closes the vision by tying God’s promise to a stated inheritance. The next chapter turns to Abram and Sarai’s attempt to resolve the delay in having a child.",
    "refs": "Genesis 16:1–4"
  },
  "Genesis 16:1": {
    "title": "Sarai has no child",
    "text": "Sarai has borne Abram no child, and she has an Egyptian handmaid named Hagar. This repeats the human difficulty at the heart of the promise. The narrative introduces Hagar as a person within the household, not merely as a plot device.",
    "refs": "Genesis 11:30; Genesis 15:4"
  },
  "Genesis 16:2": {
    "title": "Sarai proposes Hagar",
    "text": "Sarai suggests that Abram go in to Hagar, hoping to obtain children through her. Abram listens to Sarai. The text records their plan but does not say God commanded it; later conflict shows the painful consequences of their decision.",
    "refs": "Genesis 16:3–6"
  },
  "Genesis 16:3": {
    "title": "Hagar is given to Abram",
    "text": "After Abram has lived ten years in Canaan, Sarai gives Hagar to him as a wife. The verse reports a household custom in the ancient narrative. Recording the action does not mean every aspect of the arrangement is presented as God’s ideal or command.",
    "refs": "Genesis 16:1–2; Genesis 21:10–12"
  },
  "Genesis 16:4": {
    "title": "Hagar conceives and Sarai is despised",
    "text": "After Hagar conceives, she looks on Sarai with contempt. The attempt to secure the promised child through human arrangement creates rivalry and pain. The narrative shows the relational consequences rather than presenting the plan as a simple success.",
    "refs": "Genesis 16:5–6; Galatians 4:22–23"
  },
  "Genesis 16:5": {
    "title": "Sarai appeals to Abram",
    "text": "Sarai tells Abram that the wrong she experiences is connected with him and places the matter before the LORD as judge. The verse reveals the household conflict from Sarai’s perspective. The text does not excuse cruelty by either party; it records the dispute honestly.",
    "refs": "Genesis 16:4; Genesis 16:6"
  },
  "Genesis 16:6": {
    "title": "Hagar flees",
    "text": "Abram tells Sarai that Hagar is in her hand, and Sarai deals harshly with Hagar so that Hagar flees. The verse records harsh treatment and a vulnerable woman’s flight. It should not be read as blanket approval of Sarai’s conduct simply because Abram allows it.",
    "refs": "Exodus 22:21; Genesis 16:7"
  },
  "Genesis 16:7": {
    "title": "The angel of the LORD finds Hagar",
    "text": "The angel of the LORD finds Hagar by a spring in the wilderness. The phrase “angel of the LORD” has been interpreted in different ways across Scripture. This verse itself says the messenger finds Hagar; it should not be treated as an automatic proof of a separate divine person or of a particular incarnation without considering the full context.",
    "refs": "Genesis 22:11–18; Exodus 3:2–6"
  },
  "Genesis 16:8": {
    "title": "Hagar is asked where she came from",
    "text": "The angel asks Hagar where she came from and where she is going. The question invites her to speak about her situation. God’s attention reaches a person who has fled mistreatment, and the narrative gives Hagar a voice in the account.",
    "refs": "Genesis 16:7; Psalm 34:18"
  },
  "Genesis 16:9": {
    "title": "Return and submit",
    "text": "The messenger tells Hagar to return to Sarai and submit to her. This is a specific instruction within the ancient narrative and should not be used to tell every abused person today to return to danger. Scripture’s broader teaching on justice, oppression, and protection must be considered when applying difficult passages.",
    "refs": "Genesis 16:6; Psalm 9:9"
  },
  "Genesis 16:10": {
    "title": "Hagar’s seed multiplied",
    "text": "The messenger promises that Hagar’s descendants will be multiplied greatly. God sees Hagar and speaks of a future for her child and descendants. The promise demonstrates that Hagar is not invisible to God even though she is socially vulnerable.",
    "refs": "Genesis 17:20; Genesis 25:12–18"
  },
  "Genesis 16:11": {
    "title": "Ishmael’s name and affliction",
    "text": "Hagar is told she will bear a son named Ishmael because the LORD has heard her affliction. The name is connected in the text with God hearing. God’s response does not erase the household’s wrongdoing, but it shows His attention to the suffering of Hagar.",
    "refs": "Exodus 3:7; Psalm 34:17"
  },
  "Genesis 16:12": {
    "title": "Ishmael’s future described",
    "text": "The verse describes Ishmael’s future as a wild man and speaks of conflict with others. The wording is an ancient characterization of his life and descendants; it should not be used to stigmatize modern peoples or claim every descendant has the same character. The verse’s specific historical context matters.",
    "refs": "Genesis 25:12–18"
  },
  "Genesis 16:13": {
    "title": "Thou God seest me",
    "text": "Hagar calls the name of the LORD who spoke to her “Thou God seest me,” because she recognizes that God has seen her. This is a powerful testimony to God’s awareness of a person in distress. The passage identifies the LORD as the God who sees and responds.",
    "refs": "Psalm 139:1–12; Genesis 21:17"
  },
  "Genesis 16:14": {
    "title": "The well of the living one who sees me",
    "text": "The well receives a name associated with the living God who sees Hagar. The place-name preserves her encounter and testimony. The verse does not establish a separate divine being; it points to the LORD’s attention to Hagar in the wilderness.",
    "refs": "Genesis 16:13; Genesis 24:62"
  },
  "Genesis 16:15": {
    "title": "Hagar bears Ishmael",
    "text": "Hagar bears Abram’s son, and Abram names him Ishmael as the messenger had instructed. The narrative shows the prophecy fulfilled. Ishmael’s birth does not replace the later covenant promise concerning Isaac, which the following chapters clarify.",
    "refs": "Genesis 16:11; Genesis 17:18–21"
  },
  "Genesis 16:16": {
    "title": "Abram’s age at Ishmael’s birth",
    "text": "Abram is eighty-six when Hagar bears Ishmael. The age marker links this episode to the later covenant events. It shows the passage of time while the promised son through Sarai has not yet been born.",
    "refs": "Genesis 17:1; Genesis 21:5"
  },
  "Genesis 17:1": {
    "title": "The Almighty God speaks to Abram",
    "text": "When Abram is ninety-nine, the LORD appears and identifies Himself as the Almighty God, commanding Abram to walk before Him and be perfect. The verse presents one God speaking and calling Abram to covenant faithfulness. “Perfect” here conveys integrity and wholehearted devotion, not a claim that Abram could never make a mistake.",
    "refs": "Genesis 15:6; Deuteronomy 18:13"
  },
  "Genesis 17:2": {
    "title": "God’s covenant promise",
    "text": "God promises to establish His covenant and multiply Abram exceedingly. The covenant originates in God’s purpose and promise. Abram is called to respond faithfully, but the promise rests on God’s initiative.",
    "refs": "Genesis 12:2; Genesis 15:5"
  },
  "Genesis 17:3": {
    "title": "Abram falls on his face",
    "text": "Abram falls on his face as God speaks to him. The posture expresses reverence in the encounter. The verse does not itself describe God’s bodily form; it reports Abram’s response to God’s presence and speech.",
    "refs": "Numbers 16:22; Joshua 5:14"
  },
  "Genesis 17:4": {
    "title": "Father of many nations",
    "text": "God declares that Abram will be a father of many nations. The promise expands beyond the birth of one son and anticipates a broad family history. Later Scripture draws on this promise when discussing faith among the nations.",
    "refs": "Romans 4:16–18; Galatians 3:8"
  },
  "Genesis 17:5": {
    "title": "Abram becomes Abraham",
    "text": "God changes Abram’s name to Abraham and explains it in relation to many nations. The new name marks the covenant promise and a new identity in the story. The significance comes from God’s declaration, not from the name as a magical formula.",
    "refs": "Genesis 17:4; Romans 4:17"
  },
  "Genesis 17:6": {
    "title": "Nations and kings from Abraham",
    "text": "God promises that nations and kings will come from Abraham. The promise looks beyond Abraham’s immediate household toward future peoples and rulers. The verse does not mean every later ruler in these lines will be righteous.",
    "refs": "Genesis 35:11; Matthew 1:1"
  },
  "Genesis 17:7": {
    "title": "An everlasting covenant",
    "text": "God establishes His covenant with Abraham and his seed throughout their generations. The covenant language emphasizes continuity and God’s faithfulness. The meaning of “seed” should be considered in its immediate family context and in later biblical passages that develop the promise.",
    "refs": "Genesis 12:7; Galatians 3:16"
  },
  "Genesis 17:8": {
    "title": "The land for an everlasting possession",
    "text": "God promises Canaan to Abraham and his seed and declares Himself their God. The verse connects land, descendants, and relationship with God in the covenant. It should be read in its original context and alongside later biblical developments rather than isolated from them.",
    "refs": "Genesis 15:18; Exodus 6:7–8"
  },
  "Genesis 17:9": {
    "title": "Keep the covenant",
    "text": "God tells Abraham to keep His covenant, including his descendants after him. The passage pairs God’s promise with a covenant obligation. Scripture often holds divine grace and human responsibility together without suggesting that human performance makes God cease to be one.",
    "refs": "Genesis 17:10; Deuteronomy 7:9"
  },
  "Genesis 17:10": {
    "title": "Circumcision as the covenant sign",
    "text": "God commands circumcision for the males of Abraham’s household as the sign of the covenant. This is a specific covenant instruction to Abraham’s family. Later New Testament teaching discusses circumcision in relation to the new covenant, so the command should be studied within the whole biblical storyline.",
    "refs": "Leviticus 12:3; Romans 4:9–12"
  },
  "Genesis 17:11": {
    "title": "The sign in the flesh",
    "text": "Circumcision is called a token of the covenant between God and Abraham’s family. The visible sign marks participation in the covenant community. The verse describes the sign’s function; it does not say that the outward mark alone guarantees inward faithfulness.",
    "refs": "Deuteronomy 10:16; Romans 2:28–29"
  },
  "Genesis 17:12": {
    "title": "Circumcision on the eighth day",
    "text": "Every male child is to be circumcised at eight days old, including those born in the household and those acquired. The verse specifies the covenant practice for Abraham’s household. Later Christian teaching should distinguish this covenant sign from the requirements given to the church in the New Testament.",
    "refs": "Leviticus 12:3; Acts 15:1–11"
  },
  "Genesis 17:13": {
    "title": "The covenant in the flesh",
    "text": "God repeats that circumcision will mark the covenant as everlasting in the flesh. The repetition emphasizes the seriousness of the sign within this covenant. The verse should be read with later Scripture that explains how the covenant promise reaches its fulfillment.",
    "refs": "Genesis 17:11; Galatians 5:2–6"
  },
  "Genesis 17:14": {
    "title": "The uncircumcised male",
    "text": "The verse warns that an uncircumcised male will be cut off from his people for breaking the covenant. This is the consequence stated for the covenant sign in Abraham’s household. It is not a standalone rule for determining a person’s salvation under every biblical covenant.",
    "refs": "Genesis 17:10–13; Acts 15:5–11"
  },
  "Genesis 17:15": {
    "title": "Sarai becomes Sarah",
    "text": "God changes Sarai’s name to Sarah and announces a new stage in the promise. The name change accompanies God’s declaration about her future. The passage shows that the promised child is not merely a result of Abram’s household arrangement with Hagar.",
    "refs": "Genesis 17:16; Genesis 18:10"
  },
  "Genesis 17:16": {
    "title": "Sarah will bear a son",
    "text": "God blesses Sarah and promises that she will bear Abraham a son, from whom nations and kings will come. The promise addresses the earlier barrenness directly. The birth is attributed to God’s promise and action, not simply to human planning.",
    "refs": "Genesis 18:10–14; Genesis 21:1–3"
  },
  "Genesis 17:17": {
    "title": "Abraham laughs",
    "text": "Abraham falls on his face and laughs at the thought of a child being born to a hundred-year-old man and a ninety-year-old Sarah. The verse records his astonishment. Later passages show that faith can coexist with moments of bewilderment while God remains faithful to His word.",
    "refs": "Romans 4:19–21; Genesis 18:12"
  },
  "Genesis 17:18": {
    "title": "Abraham asks about Ishmael",
    "text": "Abraham asks that Ishmael might live before God. He cares about the son he already has, even as God’s covenant promise specifies another son through Sarah. God’s response in the following verses distinguishes His blessing on Ishmael from the covenant line through Isaac.",
    "refs": "Genesis 16:10–11; Genesis 17:19–21"
  },
  "Genesis 17:19": {
    "title": "Isaac named in the covenant",
    "text": "God says Sarah will bear Isaac and establishes the covenant with him and his seed. The text names the promised son and clarifies the covenant line. The name and promise are grounded in God’s own word.",
    "refs": "Genesis 21:1–3; Romans 9:7–9"
  },
  "Genesis 17:20": {
    "title": "Ishmael will be blessed",
    "text": "God hears Abraham concerning Ishmael and promises to bless him, make him fruitful, and multiply his descendants. Ishmael is not ignored or cursed in this passage. The text distinguishes his promised blessing from the covenant established through Isaac.",
    "refs": "Genesis 16:10; Genesis 25:12–18"
  },
  "Genesis 17:21": {
    "title": "The covenant through Isaac",
    "text": "God states that the covenant will be established with Isaac, whom Sarah will bear at the appointed time. The verse clearly distinguishes the covenant line while still allowing God to bless Ishmael. God’s purpose is stated by God, not inferred from human preference.",
    "refs": "Genesis 17:19–20; Romans 9:7–9"
  },
  "Genesis 17:22": {
    "title": "God finishes speaking",
    "text": "God finishes speaking with Abraham and goes up from him. This is narrative language describing the close of the encounter. It should not be forced into a claim about God’s physical location or a plurality of divine persons beyond what the passage states.",
    "refs": "Genesis 17:1–3"
  },
  "Genesis 17:23": {
    "title": "Abraham obeys that day",
    "text": "Abraham takes Ishmael and the males of his household and circumcises them on the same day as God commanded. The immediate obedience emphasizes the seriousness with which Abraham receives the covenant instruction. The verse records the action without saying the outward sign replaces trust in God.",
    "refs": "Genesis 17:10–14; Genesis 15:6"
  },
  "Genesis 17:24": {
    "title": "Abraham’s age",
    "text": "Abraham is ninety-nine when he is circumcised. The age marker anchors the covenant sign in the chronology of Abraham’s life. It also contrasts with the promised birth of Isaac, which is still future.",
    "refs": "Genesis 17:1; Genesis 21:5"
  },
  "Genesis 17:25": {
    "title": "Ishmael’s age",
    "text": "Ishmael is thirteen when he is circumcised. The verse records his age as part of the household’s obedience to the covenant command. It does not make Ishmael the son through whom the covenant promise in this chapter is established.",
    "refs": "Genesis 17:20–21"
  },
  "Genesis 17:26": {
    "title": "Abraham and Ishmael circumcised",
    "text": "Abraham and Ishmael are circumcised on the same day. The summary underscores the household’s compliance with God’s command. The passage distinguishes participation in the sign from the specific covenant promise concerning Isaac.",
    "refs": "Genesis 17:23–25"
  },
  "Genesis 17:27": {
    "title": "The household included",
    "text": "All the males of Abraham’s household, whether born in the house or bought with money, are circumcised with him. The verse concludes the chapter by emphasizing the breadth of the household’s participation in the covenant sign. The command was carried out as stated.",
    "refs": "Genesis 17:10–14"
  },
  "Genesis 18:1": {
    "title": "The LORD appears to Abraham",
    "text": "The LORD appears to Abraham by the oaks of Mamre while Abraham sits at his tent door. The following verses describe three men appearing, and the narrative later distinguishes the LORD’s speech. Oneness interpretation should carefully follow the story’s wording rather than assume that every appearance is automatically a separate divine person.",
    "refs": "Genesis 18:2; Genesis 18:13"
  },
  "Genesis 18:2": {
    "title": "Three men appear",
    "text": "Abraham sees three men and runs to meet them. The text first describes the visitors as men; the conversation then reveals the LORD’s involvement. The passage has been interpreted in different ways, but Genesis 18 alone does not explicitly say that the three men are three divine persons.",
    "refs": "Genesis 18:1; Genesis 18:9–10"
  },
  "Genesis 18:3": {
    "title": "Abraham addresses his visitor",
    "text": "Abraham asks for favor in the visitor’s sight and offers hospitality. The wording of the address has been understood differently by translators and interpreters. The safest reading is to follow the unfolding narrative, where the LORD’s speech becomes clear in the following verses.",
    "refs": "Genesis 18:1–2; Hebrews 13:2"
  },
  "Genesis 18:4": {
    "title": "Water for the visitors",
    "text": "Abraham offers water so the visitors may wash their feet and rest under the tree. Hospitality is a central action in the scene. The verse does not itself establish the visitors’ precise identity; that becomes clearer as the story continues.",
    "refs": "Genesis 19:2; Hebrews 13:2"
  },
  "Genesis 18:5": {
    "title": "Food and refreshment",
    "text": "Abraham offers food to refresh the visitors before they continue their journey. The scene shows generous hospitality and a willingness to serve. The visitors accept the hospitality in the next verse.",
    "refs": "Genesis 18:6–8"
  },
  "Genesis 18:6": {
    "title": "Sarah prepares cakes",
    "text": "Abraham hurries to Sarah and asks her to prepare cakes from fine meal. The repeated urgency communicates the care with which Abraham welcomes the visitors. The text presents ordinary household work as part of the hospitality offered in this encounter.",
    "refs": "Genesis 18:5; Genesis 18:8"
  },
  "Genesis 18:7": {
    "title": "A tender calf prepared",
    "text": "Abraham runs to the herd, chooses a tender calf, and gives it to a servant to prepare. The detail continues the picture of generous hospitality. It should not be turned into an unsupported symbolic claim; the narrative emphasizes the meal and welcome.",
    "refs": "Genesis 18:8"
  },
  "Genesis 18:8": {
    "title": "The visitors eat",
    "text": "Abraham serves curds, milk, and the prepared calf, and the visitors eat. The account describes them in human terms during the visit. This detail is important when interpreting the scene: readers should not ignore the narrative’s presentation in order to force a predetermined theory onto it.",
    "refs": "Genesis 18:1–2; Genesis 18:9"
  },
  "Genesis 18:9": {
    "title": "Where is Sarah?",
    "text": "The visitors ask where Sarah is, and Abraham answers that she is in the tent. The question leads directly to the promise of a son. The narrative presents knowledge of Sarah and her future as part of the LORD’s message.",
    "refs": "Genesis 18:10; Genesis 17:16"
  },
  "Genesis 18:10": {
    "title": "A son at the appointed time",
    "text": "The speaker promises to return at the time of life and says Sarah will have a son. Sarah listens at the tent door. The promise repeats what God had already told Abraham, reinforcing that Isaac’s birth depends on God’s word.",
    "refs": "Genesis 17:19; Genesis 21:1–2"
  },
  "Genesis 18:11": {
    "title": "Abraham and Sarah are old",
    "text": "Abraham and Sarah are advanced in age, and Sarah is past the age of childbearing. The verse establishes the human impossibility that makes the promise remarkable. The narrative does not hide the physical reality confronting the couple.",
    "refs": "Romans 4:19; Hebrews 11:11"
  },
  "Genesis 18:12": {
    "title": "Sarah laughs inwardly",
    "text": "Sarah laughs within herself because the promise seems impossible given her age and Abraham’s. Her reaction mirrors Abraham’s earlier laughter. The passage records their human response honestly while preparing for God’s answer.",
    "refs": "Genesis 17:17; Genesis 18:13–14"
  },
  "Genesis 18:13": {
    "title": "The LORD asks about Sarah’s laughter",
    "text": "The LORD asks why Sarah laughed and questioned whether she could bear a child at her age. The narrator identifies the speaker as the LORD. This direct identification matters for Oneness study: the passage says the LORD is speaking through the encounter, not that a second God is introduced.",
    "refs": "Genesis 18:1; Genesis 18:14"
  },
  "Genesis 18:14": {
    "title": "Is anything too hard for the LORD?",
    "text": "The LORD asks whether anything is too hard for Him and repeats the promise of Sarah’s son. The verse is a declaration of God’s power and faithfulness. It supports confidence in the one LORD who fulfills His word despite human limitations.",
    "refs": "Jeremiah 32:17; Luke 1:37"
  },
  "Genesis 18:15": {
    "title": "Sarah denies laughing",
    "text": "Sarah is afraid and denies laughing, but the LORD says that she did laugh. The text exposes her response without ending the promise. God’s knowledge and faithfulness remain greater than the couple’s hesitation.",
    "refs": "Genesis 18:12–14; Psalm 139:1–4"
  },
  "Genesis 18:16": {
    "title": "The visitors look toward Sodom",
    "text": "The men rise and look toward Sodom, and Abraham walks with them to send them on their way. The narrative transitions from the promise of Isaac to the coming judgment on Sodom. The two episodes are linked by the LORD’s conversation with Abraham.",
    "refs": "Genesis 18:17–22"
  },
  "Genesis 18:17": {
    "title": "Shall I hide from Abraham?",
    "text": "The LORD considers whether to hide from Abraham what He is about to do. The passage depicts God revealing His purpose to the man chosen to become a great nation. The wording is narrative and relational; it does not mean God needs to discover information.",
    "refs": "Amos 3:7; Genesis 18:18"
  },
  "Genesis 18:18": {
    "title": "Abraham’s seed and the nations",
    "text": "The LORD says Abraham will become a great and mighty nation and that all nations will be blessed in him. This echoes the covenant promise and connects Abraham’s calling with a purpose for all peoples. The New Testament relates this promise to the blessing of the gospel through Christ.",
    "refs": "Genesis 12:3; Galatians 3:8"
  },
  "Genesis 18:19": {
    "title": "Abraham to command his household",
    "text": "God says He has known Abraham so that he will command his children and household to keep the way of the LORD by doing righteousness and justice. The verse links covenant calling with ethical responsibility. Knowing God’s promise is not detached from living according to God’s ways.",
    "refs": "Deuteronomy 6:6–7; Micah 6:8"
  },
  "Genesis 18:20": {
    "title": "The cry of Sodom and Gomorrah",
    "text": "The LORD says the outcry against Sodom and Gomorrah is great and their sin is very grievous. The language presents the cities’ wrongdoing as serious and deserving of investigation and judgment. The next verse uses courtroom-like language to describe the LORD’s action.",
    "refs": "Genesis 13:13; Genesis 19:4–9"
  },
  "Genesis 18:21": {
    "title": "I will go down and see",
    "text": "The LORD says He will go down and see whether the cities have acted according to the outcry. This is vivid narrative language presenting God’s judgment as deliberate rather than careless. It should not be used to imply that God is ignorant or must physically travel to gain knowledge.",
    "refs": "Genesis 11:5; Psalm 139:1–4"
  },
  "Genesis 18:22": {
    "title": "Abraham stands before the LORD",
    "text": "The men turn toward Sodom while Abraham remains standing before the LORD. The narrative distinguishes the visitors’ movement from the LORD’s conversation with Abraham. It does not state that there are three divine persons; the text identifies the LORD as the one before whom Abraham speaks.",
    "refs": "Genesis 18:1–2; Genesis 18:23"
  },
  "Genesis 18:23": {
    "title": "Will the righteous perish with the wicked?",
    "text": "Abraham approaches and asks whether God will destroy the righteous with the wicked. His question appeals to God’s justice. The passage models reverent intercession, asking God to act consistently with righteousness rather than treating judgment as indiscriminate.",
    "refs": "Genesis 18:25; Ezekiel 18:23"
  },
  "Genesis 18:24": {
    "title": "Fifty righteous people",
    "text": "Abraham asks whether the city might be spared if fifty righteous people are found there. He is appealing for mercy on behalf of the city. The passage shows that prayer can include bold requests while acknowledging God’s authority to judge.",
    "refs": "Exodus 32:11–14; Genesis 18:26"
  },
  "Genesis 18:25": {
    "title": "The Judge of all the earth",
    "text": "Abraham declares that the Judge of all the earth will do right. This is a clear confession of God’s universal authority and justice. Oneness theology affirms the one God as the righteous Judge; the verse does not divide that authority among multiple Gods.",
    "refs": "Deuteronomy 32:4; Psalm 9:7–8"
  },
  "Genesis 18:26": {
    "title": "The LORD agrees to spare the city",
    "text": "The LORD says He will spare the whole place for fifty righteous people. The answer reveals a willingness to show mercy for the sake of the righteous. The negotiation continues as Abraham asks whether fewer righteous people might be found.",
    "refs": "Genesis 18:24; Genesis 18:27–28"
  },
  "Genesis 18:27": {
    "title": "Dust and ashes",
    "text": "Abraham acknowledges that he is dust and ashes while continuing to speak. His humility does not prevent earnest intercession. The verse shows reverence and boldness together in prayer.",
    "refs": "Genesis 3:19; Job 42:6"
  },
  "Genesis 18:28": {
    "title": "Forty-five righteous people",
    "text": "Abraham asks whether the city will be spared if five fewer than fifty righteous people are found. The LORD agrees to spare it for forty-five. The repeated exchange emphasizes Abraham’s concern and the LORD’s willingness to answer.",
    "refs": "Genesis 18:26; Genesis 18:29"
  },
  "Genesis 18:29": {
    "title": "Forty righteous people",
    "text": "Abraham asks about forty righteous people, and the LORD agrees not to destroy the city for their sake. The exchange continues the appeal to divine justice and mercy. The text does not portray Abraham as controlling God; he is petitioning the Judge.",
    "refs": "Genesis 18:25; Genesis 18:30"
  },
  "Genesis 18:30": {
    "title": "Thirty righteous people",
    "text": "Abraham asks about thirty righteous people and requests that the LORD not be angry with his speaking. The request shows humility as he continues interceding. The LORD agrees to spare the city if thirty are found.",
    "refs": "Genesis 18:29; Genesis 18:31"
  },
  "Genesis 18:31": {
    "title": "Twenty righteous people",
    "text": "Abraham asks whether the city will be spared for twenty righteous people. The LORD agrees. The dialogue highlights the value of the righteous and the seriousness with which Abraham seeks mercy for others.",
    "refs": "Genesis 18:30; Genesis 18:32"
  },
  "Genesis 18:32": {
    "title": "Ten righteous people",
    "text": "Abraham asks one final time about ten righteous people, and the LORD agrees not to destroy the city for their sake if ten are found. The dialogue ends with this assurance. The next chapter shows the outcome and should be read alongside this appeal for justice and mercy.",
    "refs": "Genesis 19:1–29"
  },
  "Genesis 18:33": {
    "title": "The LORD departs",
    "text": "The LORD goes His way after finishing the conversation, and Abraham returns to his place. This closes the intercession scene. The narrative uses human movement language to describe the end of the encounter, without requiring a doctrine of multiple divine persons.",
    "refs": "Genesis 18:22–32"
  },
  "Genesis 19:1": {
    "title": "Two angels arrive at Sodom",
    "text": "Two angels arrive at Sodom in the evening, and Lot receives them at the gate. The narrative identifies them as angels and describes Lot’s hospitality. This verse should be read with the chapter’s account of violence and judgment, without assuming every visitor in Genesis has the same identity.",
    "refs": "Genesis 18:1–2; Hebrews 13:2"
  },
  "Genesis 19:2": {
    "title": "Lot offers hospitality",
    "text": "Lot invites the visitors to stay in his house, wash their feet, and rise early to continue their journey. The offer echoes the hospitality Abraham showed in Genesis 18. The visitors initially say they will stay in the street, setting up the events that follow.",
    "refs": "Genesis 18:4–5; Genesis 19:3"
  },
  "Genesis 19:3": {
    "title": "The visitors enter Lot’s house",
    "text": "Lot presses them strongly, and they enter his house. He prepares a meal and unleavened bread. The scene shows hospitality amid a city whose conduct will soon be exposed as violent and corrupt.",
    "refs": "Genesis 18:6–8; Judges 19:15–21"
  },
  "Genesis 19:4": {
    "title": "The men of Sodom surround the house",
    "text": "Men from Sodom, both young and old, surround Lot’s house. The narrative depicts collective intimidation and a threat against the visitors. The following verses clarify the intended violence, so the scene should not be reduced to a harmless social dispute.",
    "refs": "Genesis 13:13; Ezekiel 16:49–50"
  },
  "Genesis 19:5": {
    "title": "Bring the visitors out",
    "text": "The men demand that Lot bring the visitors out so they can know them. In this context, the demand is a threat of sexual violence. The text condemns the mob’s coercion and disregard for the visitors’ safety; it does not portray the demand as consensual conduct.",
    "refs": "Genesis 19:4–9; Jude 7"
  },
  "Genesis 19:6": {
    "title": "Lot goes out to the crowd",
    "text": "Lot goes out and shuts the door behind him, placing himself between the crowd and his guests. His action attempts to protect those inside, though his subsequent offer in verse 8 is deeply troubling and must not be excused.",
    "refs": "Genesis 19:7–8"
  },
  "Genesis 19:7": {
    "title": "Do not act wickedly",
    "text": "Lot pleads with the men not to do wickedly. The narrator’s framing and Lot’s words make clear that the crowd’s intended conduct is evil. The plea does not mean Lot handles the crisis perfectly in the next verse.",
    "refs": "Genesis 19:5; Isaiah 1:17"
  },
  "Genesis 19:8": {
    "title": "Lot offers his daughters",
    "text": "Lot offers his daughters to the crowd, a deeply disturbing act recorded by Scripture. The narrative reports his proposal but does not command or approve it. Protecting guests cannot justify offering vulnerable people to sexual violence; this verse should be discussed honestly and in the context of the crowd’s wickedness.",
    "refs": "Judges 19:24–26; Micah 6:8"
  },
  "Genesis 19:9": {
    "title": "The crowd threatens Lot",
    "text": "The men reject Lot’s appeal, threaten him, and press forward to break the door. Their behavior demonstrates that the city’s corruption includes violence and contempt for restraint. Lot’s status as a resident does not protect him from the mob.",
    "refs": "Genesis 19:4–8"
  },
  "Genesis 19:10": {
    "title": "The visitors pull Lot inside",
    "text": "The men inside reach out, pull Lot into the house, and shut the door. The visitors protect Lot from the crowd. The following verse explains that the attackers are struck with blindness, ending the immediate assault.",
    "refs": "Genesis 19:11"
  },
  "Genesis 19:11": {
    "title": "The attackers are struck blind",
    "text": "The visitors strike the men at the door with blindness, so they cannot find the entrance. The action protects the household and exposes the severity of the crowd’s conduct. The text attributes the event to the visitors; it does not require unsupported speculation about the medical nature of the blindness.",
    "refs": "2 Kings 6:18; Genesis 19:10"
  },
  "Genesis 19:12": {
    "title": "Lot’s family must leave",
    "text": "The visitors ask Lot whether he has anyone else in the city and tell him to bring them out because judgment is coming. The warning gives Lot an opportunity to protect his family. The account shows mercy through warning before destruction.",
    "refs": "Genesis 19:13–14; 2 Peter 2:7"
  },
  "Genesis 19:13": {
    "title": "The cry is great before the LORD",
    "text": "The visitors explain that they will destroy the place because the outcry against it is great before the LORD. The judgment is connected to the city’s wrongdoing. The narrative presents God’s judgment as a response to serious evil, not as an unexplained act.",
    "refs": "Genesis 18:20–21; Ezekiel 16:49–50"
  },
  "Genesis 19:14": {
    "title": "Lot warns his sons-in-law",
    "text": "Lot tells his sons-in-law to leave because the LORD will destroy the city, but they think he is joking. The verse shows how a warning can be dismissed even when danger is imminent. The text does not say that Lot’s warning was unclear; it records their failure to take it seriously.",
    "refs": "Luke 17:28–30; 2 Peter 3:3–7"
  },
  "Genesis 19:15": {
    "title": "The angels urge Lot to leave",
    "text": "At dawn, the angels urge Lot to take his wife and daughters and escape the city. The urgency reflects the coming judgment. Lot’s rescue is portrayed as an act of mercy, not as proof that his family has earned deliverance through perfect conduct.",
    "refs": "Genesis 19:16; 2 Peter 2:7"
  },
  "Genesis 19:16": {
    "title": "The LORD is merciful",
    "text": "Lot lingers, and the men take his hand, his wife’s hand, and his daughters’ hands because the LORD is merciful to him. The text explicitly attributes their rescue to the LORD’s mercy. Divine mercy here is active help in a moment of danger.",
    "refs": "Psalm 103:8; Titus 3:5"
  },
  "Genesis 19:17": {
    "title": "Escape for your life",
    "text": "The visitors tell Lot to escape, not look behind him, and not remain in the plain. The command is specific to the imminent judgment in this story. It should not be turned into a universal rule that every backward glance is sinful.",
    "refs": "Genesis 19:26; Luke 17:31–32"
  },
  "Genesis 19:18": {
    "title": "Lot asks to speak",
    "text": "Lot responds to the instruction with a request. The passage continues to show his fear and hesitation as the danger approaches. The next verses record the specific request he makes.",
    "refs": "Genesis 19:19–20"
  },
  "Genesis 19:19": {
    "title": "Lot acknowledges mercy",
    "text": "Lot acknowledges that he has found favor and that the visitors have shown great mercy in saving his life. He fears he will not reach the mountain in time. The verse reveals gratitude mixed with anxiety, not a rejection of the deliverance offered.",
    "refs": "Genesis 19:16–17; Psalm 34:4"
  },
  "Genesis 19:20": {
    "title": "A nearby little city",
    "text": "Lot asks to flee to a nearby small city, believing he can reach it and survive. The request leads to the city being spared for his sake. The passage shows God’s willingness to respond to Lot’s fear while still carrying out judgment on Sodom.",
    "refs": "Genesis 19:21–22"
  },
  "Genesis 19:21": {
    "title": "The request is granted",
    "text": "The visitor says Lot’s request is granted and the city will not be overthrown. The verse shows a measure of accommodation within the rescue. The text does not portray Lot as controlling God; he makes a request and receives an answer.",
    "refs": "Genesis 19:20; Genesis 19:22"
  },
  "Genesis 19:22": {
    "title": "Zoar is spared for Lot",
    "text": "Lot is told to hurry because judgment cannot proceed until he reaches the city, which is called Zoar. The detail emphasizes the connection between Lot’s rescue and the timing of the destruction. The city’s name is explained within the story.",
    "refs": "Genesis 19:20–21"
  },
  "Genesis 19:23": {
    "title": "The sun rises",
    "text": "The sun rises as Lot enters Zoar. The time marker leads into the account of the LORD’s judgment on Sodom and Gomorrah. The narrative contrasts the ordinary beginning of the day with the extraordinary destruction that follows.",
    "refs": "Genesis 19:24"
  },
  "Genesis 19:24": {
    "title": "The LORD rains judgment",
    "text": "The LORD rains brimstone and fire upon Sodom and Gomorrah from the LORD out of heaven. The wording has been discussed in theological debates. A Oneness reading should acknowledge the phrase as written and interpret it in the broader biblical use of divine agency and heavenly language, rather than claiming the verse alone settles every question about divine persons.",
    "refs": "Deuteronomy 29:23; Luke 17:29"
  },
  "Genesis 19:25": {
    "title": "The cities and plain are overthrown",
    "text": "The destruction includes the cities, the plain, the inhabitants, and the vegetation. The text depicts comprehensive judgment on the region described. The event later becomes a warning example of the seriousness of persistent wickedness.",
    "refs": "Deuteronomy 29:23; 2 Peter 2:6"
  },
  "Genesis 19:26": {
    "title": "Lot’s wife looks back",
    "text": "Lot’s wife looks back and becomes a pillar of salt. The text records the consequence without giving every detail of her motive. Jesus later uses the event as a warning not to turn back when decisive action is required; applications should stay grounded in that warning.",
    "refs": "Luke 17:31–33"
  },
  "Genesis 19:27": {
    "title": "Abraham returns to the place of intercession",
    "text": "Abraham rises early and returns to the place where he had stood before the LORD. The detail connects the destruction with Abraham’s earlier intercession. The narrative invites the reader to remember the conversation about justice and the righteous.",
    "refs": "Genesis 18:22–33"
  },
  "Genesis 19:28": {
    "title": "Abraham sees the smoke",
    "text": "Abraham looks toward Sodom and Gomorrah and sees smoke rising like the smoke of a furnace. The image confirms the scale of the destruction. The verse does not say Abraham knew every detail of Lot’s condition at that moment.",
    "refs": "Genesis 19:24–25"
  },
  "Genesis 19:29": {
    "title": "God remembers Abraham and rescues Lot",
    "text": "When God destroys the cities, He remembers Abraham and sends Lot out of the overthrow. “Remembered” describes God acting in keeping with His relationship and purpose, not recovering a forgotten fact. The verse explicitly connects Lot’s rescue with God’s mercy and Abraham’s intercession.",
    "refs": "Genesis 18:23–33; Genesis 19:16"
  },
  "Genesis 19:30": {
    "title": "Lot leaves Zoar",
    "text": "Lot leaves Zoar and settles in a mountain cave with his two daughters because he is afraid to remain in Zoar. The narrative continues to describe the consequences of the catastrophe. His fear shapes his next decision.",
    "refs": "Genesis 19:17–22"
  },
  "Genesis 19:31": {
    "title": "The daughters’ concern",
    "text": "Lot’s older daughter says their father is old and there is no man in the land to come in to them in the usual way. The statement explains their stated concern, but does not justify the scheme they devise. The next verses describe an act that Scripture records without approving.",
    "refs": "Genesis 19:32–36"
  },
  "Genesis 19:32": {
    "title": "A plan to preserve offspring",
    "text": "The daughters propose making their father drink wine and lying with him to preserve offspring. Their plan involves deception and incest. The text’s report of the act is not divine approval; the broader biblical law later explicitly prohibits incestuous relations.",
    "refs": "Leviticus 18:6–18; Genesis 19:33–36"
  },
  "Genesis 19:33": {
    "title": "The older daughter lies with Lot",
    "text": "Lot drinks wine, and his older daughter lies with him; the text says he did not know when she lay down or rose. The narrative presents intoxication and deception surrounding the act. This is not offered as a moral example to imitate.",
    "refs": "Genesis 19:32; Ephesians 5:18"
  },
  "Genesis 19:34": {
    "title": "The younger daughter follows the plan",
    "text": "The older daughter tells the younger what happened and urges her to do the same the next night. The plan continues through deception. The verse reports the family’s actions without presenting them as righteous or commanded by God.",
    "refs": "Genesis 19:32–33"
  },
  "Genesis 19:35": {
    "title": "The younger daughter lies with Lot",
    "text": "Lot is made drunk again, and the younger daughter lies with him. As with the prior night, the text describes a morally tragic episode. The account’s honesty about the actions of biblical figures is not an endorsement of them.",
    "refs": "Genesis 19:33; Leviticus 18:6"
  },
  "Genesis 19:36": {
    "title": "Both daughters conceive",
    "text": "Both of Lot’s daughters become pregnant by their father. The verse summarizes the consequence of their scheme. The narrative does not praise the method; it records the origins of the two sons named in the next verses.",
    "refs": "Genesis 19:37–38"
  },
  "Genesis 19:37": {
    "title": "Moab is born",
    "text": "The older daughter bears a son and names him Moab, identified as the father of the Moabites. The genealogy explains the origin of a people who appear repeatedly in later biblical history. The account of their ancestry does not make every later Moabite morally identical.",
    "refs": "Ruth 1:4; Deuteronomy 23:3"
  },
  "Genesis 19:38": {
    "title": "Ben-ammi and the Ammonites",
    "text": "The younger daughter bears Ben-ammi, identified as the father of the Ammonites. The chapter closes with a genealogy arising from the family’s tragic decisions. The Bible records these origins candidly and later treats Moab and Ammon within their historical contexts.",
    "refs": "Deuteronomy 2:19; Judges 10:6"
  },
  "Genesis 20:1": {
    "title": "Abraham journeys to Gerar",
    "text": "Abraham travels toward the south and settles between Kadesh and Shur, sojourning in Gerar. The move sets the scene for another episode involving Sarah’s identity. The narrative shows that Abraham’s earlier failures with fear and concealment recur rather than presenting him as flawless.",
    "refs": "Genesis 12:10–20; Genesis 26:1"
  },
  "Genesis 20:2": {
    "title": "Sarah called Abraham’s sister",
    "text": "Abraham says Sarah is his sister, and Abimelech king of Gerar sends for her. This repeats the concealment from Egypt. The text reports Abraham’s claim and its consequences; it does not endorse deception as a righteous way to protect oneself.",
    "refs": "Genesis 12:13–15; Genesis 20:12"
  },
  "Genesis 20:3": {
    "title": "God warns Abimelech in a dream",
    "text": "God comes to Abimelech in a dream and warns that he is a dead man because the woman he has taken is married. The verse directly identifies God as the speaker. God intervenes to protect Sarah and preserve the promised line.",
    "refs": "Genesis 12:17; Genesis 20:6–7"
  },
  "Genesis 20:4": {
    "title": "Abimelech has not approached Sarah",
    "text": "Abimelech has not come near Sarah and asks whether God will destroy a righteous nation. The narrative distinguishes his taking Sarah into his household from actually having relations with her. His question appeals to the justice of God.",
    "refs": "Genesis 20:5; Genesis 20:6"
  },
  "Genesis 20:5": {
    "title": "Abimelech claims innocence",
    "text": "Abimelech says Abraham described Sarah as his sister and Sarah confirmed the relationship. He claims he acted with integrity and clean hands. The passage presents his defense and leaves God to answer the matter.",
    "refs": "Genesis 20:2; Genesis 20:6"
  },
  "Genesis 20:6": {
    "title": "God restrains Abimelech",
    "text": "God tells Abimelech that He prevented him from sinning against Him and did not allow him to touch Sarah. The verse emphasizes God’s active protection. God’s intervention does not excuse Abraham’s deception, which the chapter also exposes.",
    "refs": "Genesis 20:3; Psalm 121:7"
  },
  "Genesis 20:7": {
    "title": "Return the man’s wife",
    "text": "God commands Abimelech to return Sarah because Abraham is a prophet who will pray for him. The verse identifies Abraham as a prophet and makes restoration necessary. It does not mean prophets are morally perfect; Abraham’s conduct is corrected in the same episode.",
    "refs": "Genesis 20:17; Psalm 105:14–15"
  },
  "Genesis 20:8": {
    "title": "Abimelech tells his servants",
    "text": "Abimelech rises early, tells his servants what happened, and they become afraid. The dream is treated seriously and leads to immediate action. The narrative shows that God’s warning changes the king’s behavior.",
    "refs": "Genesis 20:3–7"
  },
  "Genesis 20:9": {
    "title": "Abimelech confronts Abraham",
    "text": "Abimelech asks Abraham what he has done and what wrong he has committed. The foreign king directly challenges Abraham’s conduct. Scripture does not conceal the fact that Abraham’s deception brought danger and reproach.",
    "refs": "Genesis 12:18–19; Genesis 20:10"
  },
  "Genesis 20:10": {
    "title": "Why did Abraham do this?",
    "text": "Abimelech asks Abraham what he saw that led him to act this way. The question invites Abraham to explain his fear and motive. The episode shows that a person of faith must still be accountable for actions that harm others.",
    "refs": "Genesis 20:11–13"
  },
  "Genesis 20:11": {
    "title": "Abraham explains his fear",
    "text": "Abraham says he thought the fear of God was not in the place and that he might be killed for Sarah’s sake. His explanation reveals fear rather than trust. The narrative does not confirm that all the people of Gerar were godless; Abimelech’s response complicates Abraham’s assumption.",
    "refs": "Genesis 12:12; Proverbs 29:25"
  },
  "Genesis 20:12": {
    "title": "Sarah is Abraham’s half-sister",
    "text": "Abraham explains that Sarah is his half-sister as well as his wife. This detail explains the partial truth behind his statement, but it does not erase the deception about their marriage. A statement can be technically true and still mislead someone.",
    "refs": "Genesis 11:29; Genesis 20:2"
  },
  "Genesis 20:13": {
    "title": "Abraham describes their agreement",
    "text": "Abraham says that when God caused him to wander from his father’s house, he asked Sarah to show him this kindness by saying he was her brother. The verse explains the arrangement as a long-standing strategy born of fear. It records Abraham’s explanation, not a divine command to deceive.",
    "refs": "Genesis 12:1; Genesis 12:13"
  },
  "Genesis 20:14": {
    "title": "Abimelech gives gifts",
    "text": "Abimelech gives Abraham sheep, oxen, servants, and returns Sarah. The gifts accompany the restoration of Sarah and an attempt to resolve the crisis. The narrative does not say the gifts make Abraham’s earlier conduct right.",
    "refs": "Genesis 12:16; Genesis 20:16"
  },
  "Genesis 20:15": {
    "title": "Abimelech offers the land",
    "text": "Abimelech tells Abraham that the land is before him and that he may dwell where he pleases. The king responds generously after the confrontation. This contrasts with Abraham’s assumption that the people would kill him without fear of God.",
    "refs": "Genesis 20:11; Genesis 21:23"
  },
  "Genesis 20:16": {
    "title": "Sarah is vindicated",
    "text": "Abimelech gives Sarah silver and says it is a covering or vindication in the eyes of those with her. The exact nuance of the phrase is debated, but the verse shows Sarah being publicly restored after the incident. The narrative should not place all blame on Sarah for Abraham’s concealment.",
    "refs": "Genesis 20:2; Genesis 20:14"
  },
  "Genesis 20:17": {
    "title": "Abraham prays and healing comes",
    "text": "Abraham prays to God, and God heals Abimelech, his wife, and his maidservants so they can bear children. The verse shows God answering prayer and restoring the household. It also shows Abraham fulfilling the role God named in verse 7 despite his earlier failure.",
    "refs": "Genesis 20:7; James 5:16"
  },
  "Genesis 20:18": {
    "title": "The wombs had been closed",
    "text": "The LORD had closed the wombs of Abimelech’s household because of Sarah. The verse explains the household’s affliction and connects it to the taking of Sarah. God’s action protects the covenant promise; the chapter ends with healing after Sarah is returned.",
    "refs": "Genesis 20:3; Genesis 21:1–2"
  },
  "Genesis 21:1": {
    "title": "The LORD visits Sarah",
    "text": "The LORD visits Sarah as He had said and does for her as He had spoken. The repetition stresses that God fulfills His promise. The promised birth is the result of the LORD’s faithfulness, not an accidental event.",
    "refs": "Genesis 17:16; Genesis 18:10–14"
  },
  "Genesis 21:2": {
    "title": "Isaac is born at the appointed time",
    "text": "Sarah conceives and bears Abraham a son in his old age, at the set time God had spoken. The birth fulfills the promise that seemed impossible. The verse repeatedly ties the event to God’s word and appointed time.",
    "refs": "Genesis 17:19; Genesis 18:14"
  },
  "Genesis 21:3": {
    "title": "The child is named Isaac",
    "text": "Abraham names the son Isaac, as God had commanded. The name follows the earlier promise and the couple’s laughter at the seemingly impossible announcement. God’s promise is fulfilled despite their earlier uncertainty.",
    "refs": "Genesis 17:19; Genesis 17:17"
  },
  "Genesis 21:4": {
    "title": "Isaac is circumcised",
    "text": "Abraham circumcises Isaac on the eighth day as God commanded. The verse records Abraham’s obedience to the covenant instruction given in Genesis 17. The act belongs to that covenant setting and should be distinguished from later New Testament teaching about circumcision.",
    "refs": "Genesis 17:10–12; Luke 2:21"
  },
  "Genesis 21:5": {
    "title": "Abraham’s age at Isaac’s birth",
    "text": "Abraham is one hundred years old when Isaac is born. The age emphasizes how far beyond ordinary expectation the promise was fulfilled. Paul later points to Abraham’s faith in God’s power to bring life from an apparently impossible situation.",
    "refs": "Genesis 17:17; Romans 4:19–21"
  },
  "Genesis 21:6": {
    "title": "Sarah laughs with joy",
    "text": "Sarah says God has made her laugh and that others who hear will laugh with her. The earlier laughter of disbelief has become laughter associated with joy and fulfillment. The verse shows the change brought by God’s faithfulness.",
    "refs": "Genesis 18:12–14; Psalm 126:2–3"
  },
  "Genesis 21:7": {
    "title": "Sarah marvels at nursing a child",
    "text": "Sarah speaks of who would have said Abraham and Sarah would nurse a child in their old age. Her words express wonder at the fulfillment. The story highlights the contrast between human limitation and God’s promise.",
    "refs": "Genesis 18:11–14"
  },
  "Genesis 21:8": {
    "title": "Isaac is weaned",
    "text": "Isaac grows and is weaned, and Abraham holds a great feast on that day. The narrative moves forward in the child’s life. The feast celebrates the child’s growth and the continuation of the promised line.",
    "refs": "Genesis 21:1–7"
  },
  "Genesis 21:9": {
    "title": "Ishmael mocks",
    "text": "Sarah sees Hagar’s son Ishmael mocking. The precise force of the Hebrew term is discussed, but the episode clearly marks a conflict surrounding Isaac’s place in the household. The next verses show Sarah’s response and God’s instruction to Abraham.",
    "refs": "Genesis 16:4; Galatians 4:29"
  },
  "Genesis 21:10": {
    "title": "Cast out the bondwoman and her son",
    "text": "Sarah tells Abraham to cast out Hagar and Ishmael, saying Ishmael will not inherit with Isaac. This is a painful demand involving a mother and child. Paul later uses the episode allegorically, but that later application does not erase the human distress in the Genesis account.",
    "refs": "Genesis 21:11–14; Galatians 4:30"
  },
  "Genesis 21:11": {
    "title": "Abraham is grieved",
    "text": "Abraham is distressed because Ishmael is his son. The verse makes clear that the separation is emotionally painful. The covenant distinction does not mean Abraham has no love or concern for Ishmael.",
    "refs": "Genesis 17:18–20"
  },
  "Genesis 21:12": {
    "title": "God tells Abraham to heed Sarah",
    "text": "God tells Abraham not to be distressed and to heed Sarah concerning the covenant line, which will be called through Isaac. The verse distinguishes the covenant line while preserving God’s promise to make Ishmael a nation as well. God’s plan and His care for Ishmael are both present in the chapter.",
    "refs": "Genesis 17:19–21; Romans 9:7"
  },
  "Genesis 21:13": {
    "title": "Ishmael will become a nation",
    "text": "God promises to make a nation of Ishmael because he is Abraham’s seed. The promise confirms that Ishmael is not abandoned by God, even though Isaac carries the covenant line described here. The distinction should be read exactly as the text gives it.",
    "refs": "Genesis 17:20; Genesis 25:12–18"
  },
  "Genesis 21:14": {
    "title": "Hagar and Ishmael depart",
    "text": "Abraham gives Hagar bread and water and sends her away with the boy. Hagar wanders in the wilderness of Beersheba. The scene is painful, and the text should be read with attention to the vulnerability of mother and child, as well as God’s subsequent intervention.",
    "refs": "Genesis 21:15–19"
  },
  "Genesis 21:15": {
    "title": "The water is spent",
    "text": "The water in the bottle is used up, and Hagar places the boy under a shrub. The family’s crisis becomes immediate and life-threatening. The narrative prepares for God’s hearing and provision in the next verses.",
    "refs": "Genesis 21:16–19"
  },
  "Genesis 21:16": {
    "title": "Hagar weeps",
    "text": "Hagar sits at a distance because she cannot bear to watch the child die, and she lifts up her voice and weeps. The verse portrays a mother’s anguish. God’s response shows that her distress is seen and heard.",
    "refs": "Genesis 16:11; Genesis 21:17"
  },
  "Genesis 21:17": {
    "title": "God hears the boy",
    "text": "God hears the voice of the lad, and the angel of God calls to Hagar from heaven. The text explicitly says God hears and responds. The expression “angel of God” should be interpreted in context and not automatically equated with a separate divine person.",
    "refs": "Genesis 16:7–11; Exodus 3:2–6"
  },
  "Genesis 21:18": {
    "title": "Lift up the lad",
    "text": "Hagar is told to arise, lift up the boy, and hold him, because God will make him a great nation. The command combines practical action with renewed promise. God does not leave Hagar in despair but directs her toward the child’s future.",
    "refs": "Genesis 21:13; Genesis 17:20"
  },
  "Genesis 21:19": {
    "title": "God opens Hagar’s eyes",
    "text": "God opens Hagar’s eyes and she sees a well of water, from which she gives the boy a drink. The provision is near, but Hagar needs help to see it. The verse illustrates God’s care in crisis without requiring a symbolic meaning beyond the narrative.",
    "refs": "Genesis 16:13; Psalm 146:9"
  },
  "Genesis 21:20": {
    "title": "God is with Ishmael",
    "text": "God is with the boy as he grows in the wilderness and becomes an archer. The verse affirms God’s care for Ishmael outside the covenant line through Isaac. God’s presence and blessing are not limited to the particular role assigned to Isaac in the covenant story.",
    "refs": "Genesis 17:20; Genesis 25:12–18"
  },
  "Genesis 21:21": {
    "title": "Ishmael dwells in Paran",
    "text": "Ishmael lives in the wilderness of Paran, and his mother takes a wife for him from Egypt. The verse closes the account of Hagar and Ishmael’s settlement. It provides family and geographical details without authorizing sweeping claims about modern peoples.",
    "refs": "Genesis 16:1; Genesis 25:12–18"
  },
  "Genesis 21:22": {
    "title": "Abimelech recognizes God’s help",
    "text": "Abimelech and Phichol tell Abraham that God is with him in all that he does. The statement recognizes God’s evident help in Abraham’s life. It names God as the one acting with Abraham and does not introduce multiple Gods.",
    "refs": "Genesis 20:7; Genesis 26:28"
  },
  "Genesis 21:23": {
    "title": "A covenant of honesty",
    "text": "Abimelech asks Abraham to swear that he will not deal falsely with him, his descendants, or his posterity. The request follows their earlier conflict and seeks reliable conduct. The verse highlights integrity in dealings between neighbors and rulers.",
    "refs": "Genesis 20:9–16; Proverbs 12:22"
  },
  "Genesis 21:24": {
    "title": "Abraham agrees",
    "text": "Abraham says he will swear. The agreement opens a discussion about a well and a dispute over water rights. The verse records Abraham’s commitment to the covenant requested by Abimelech.",
    "refs": "Genesis 21:25–27"
  },
  "Genesis 21:25": {
    "title": "Abraham complains about a well",
    "text": "Abraham reproves Abimelech because his servants have violently taken a well. The episode shows that peaceful relations require addressing injustice directly. Abraham does not ignore the wrong simply because he has agreed to a covenant.",
    "refs": "Genesis 26:18–22; Proverbs 31:8–9"
  },
  "Genesis 21:26": {
    "title": "Abimelech says he did not know",
    "text": "Abimelech says he does not know who did the deed and that Abraham had not told him before. The verse records Abimelech’s response rather than proving whether his servants acted without his knowledge. The dispute is addressed through the covenant ceremony that follows.",
    "refs": "Genesis 21:25–27"
  },
  "Genesis 21:27": {
    "title": "Abraham and Abimelech make a covenant",
    "text": "Abraham gives sheep and oxen to Abimelech, and the two make a covenant. The exchange formalizes their agreement. The narrative shows that peace between them involves both a spoken commitment and concrete actions.",
    "refs": "Genesis 21:28–32"
  },
  "Genesis 21:28": {
    "title": "Seven ewe lambs set apart",
    "text": "Abraham sets seven ewe lambs apart from the flock. Their purpose is explained in the next verses as testimony concerning the well. The details belong to the ancient covenant practice described in the story.",
    "refs": "Genesis 21:29–30"
  },
  "Genesis 21:29": {
    "title": "Abimelech asks about the lambs",
    "text": "Abimelech asks why Abraham has set the seven lambs apart. Abraham explains their significance in the following verse. The conversation clarifies the meaning of the symbolic action rather than leaving the reader to guess.",
    "refs": "Genesis 21:30"
  },
  "Genesis 21:30": {
    "title": "The lambs witness to the well",
    "text": "Abraham says Abimelech is to receive the lambs as a witness that Abraham dug the well. The transaction publicly marks the well as connected with Abraham’s claim. The verse demonstrates the use of testimony and agreed signs to settle a dispute.",
    "refs": "Genesis 21:25–27"
  },
  "Genesis 21:31": {
    "title": "Beersheba is named",
    "text": "The place is called Beersheba because the two men swore there. The narrative explains the place-name through the covenant and oath. Such explanations preserve the story’s memory of agreements and events.",
    "refs": "Genesis 26:33"
  },
  "Genesis 21:32": {
    "title": "The covenant is concluded",
    "text": "Abimelech and Phichol return to the land of the Philistines after making the covenant. The agreement concludes the immediate dispute and establishes peace between the parties. The text describes the historical arrangement without making every later political relationship identical.",
    "refs": "Genesis 21:22–31"
  },
  "Genesis 21:33": {
    "title": "Abraham plants a grove",
    "text": "Abraham plants a grove in Beersheba and calls there on the name of the LORD, the everlasting God. The verse explicitly identifies the LORD as everlasting and records Abraham’s worship. The one God whom Abraham invokes is the enduring Creator and covenant Lord.",
    "refs": "Deuteronomy 6:4; Isaiah 40:28"
  },
  "Genesis 21:34": {
    "title": "Abraham sojourns among the Philistines",
    "text": "Abraham lives for many days in the land of the Philistines. The verse closes the chapter by describing his continued residence in the region. The covenant story continues with God’s testing of Abraham in Genesis 22.",
    "refs": "Genesis 22:1–2"
  },
  "Genesis 22:1": {
    "title": "God tests Abraham",
    "text": "God tests Abraham and calls his name; Abraham answers, “Behold, here I am.” The verse introduces a test of Abraham’s faith, not a temptation to evil. The following command must be read with the conclusion of the story, where God stops Abraham and provides a substitute.",
    "refs": "Hebrews 11:17–19; James 1:13"
  },
  "Genesis 22:2": {
    "title": "Take Isaac to Moriah",
    "text": "God tells Abraham to take Isaac, his beloved son, to the land of Moriah and offer him there. This is a severe test within the narrative and should not be generalized into permission for human sacrifice. The chapter itself shows God stopping the act and providing an offering.",
    "refs": "Genesis 22:11–14; Deuteronomy 12:31"
  },
  "Genesis 22:3": {
    "title": "Abraham rises early",
    "text": "Abraham rises early, prepares the donkey, takes two young men and Isaac, and cuts wood for the offering. The narrative emphasizes his prompt response. The verse records his obedience before revealing the outcome of the test.",
    "refs": "Hebrews 11:17; Genesis 22:7"
  },
  "Genesis 22:4": {
    "title": "The place seen from afar",
    "text": "On the third day Abraham sees the place from a distance. The delay gives the test a long and deliberate course. The text does not disclose Abraham’s inner thoughts here, though Hebrews later interprets his faith in light of God’s promise.",
    "refs": "Hebrews 11:17–19"
  },
  "Genesis 22:5": {
    "title": "We will come again",
    "text": "Abraham tells the young men that he and Isaac will worship and return. Hebrews explains that Abraham reasoned God could raise Isaac from the dead. Genesis itself records the words without narrating all Abraham’s private reasoning.",
    "refs": "Hebrews 11:17–19"
  },
  "Genesis 22:6": {
    "title": "Isaac carries the wood",
    "text": "Abraham lays the wood on Isaac, while Abraham carries the fire and knife. The details make the scene concrete and underscore Isaac’s participation. Christian readers often see a later pattern in this scene, but typological connections should be distinguished from the direct wording of Genesis.",
    "refs": "John 19:17; Genesis 22:8"
  },
  "Genesis 22:7": {
    "title": "Where is the lamb?",
    "text": "Isaac asks his father where the lamb for the burnt offering is. The question brings the central tension of the story into focus. Abraham’s answer points to God’s provision, which the next verses reveal.",
    "refs": "Genesis 22:8; John 1:29"
  },
  "Genesis 22:8": {
    "title": "God will provide Himself a lamb",
    "text": "Abraham says God will provide Himself a lamb for the burnt offering. In context, this expresses trust that God will provide what is needed. Christians may connect the theme of divine provision with Christ, but the immediate narrative fulfillment is the ram provided later in the chapter.",
    "refs": "Genesis 22:13–14; John 1:29"
  },
  "Genesis 22:9": {
    "title": "The altar is prepared",
    "text": "Abraham builds the altar, arranges the wood, binds Isaac, and lays him on the altar. The text records the frightening climax of the test. It does not commend child sacrifice; the following verses explicitly stop Abraham from harming Isaac.",
    "refs": "Genesis 22:10–12; Deuteronomy 12:31"
  },
  "Genesis 22:10": {
    "title": "Abraham takes the knife",
    "text": "Abraham reaches for the knife to slay his son. The verse heightens the crisis, but it must not be isolated from God’s immediate intervention. The narrative’s final message includes God’s prohibition of the act and His provision of a substitute.",
    "refs": "Genesis 22:11–13"
  },
  "Genesis 22:11": {
    "title": "The angel of the LORD calls",
    "text": "The angel of the LORD calls from heaven and stops Abraham. The messenger’s intervention prevents Isaac’s death. The phrase “angel of the LORD” should be interpreted in the context of the whole passage rather than automatically treated as proof of a separate divine person.",
    "refs": "Genesis 16:7–13; Genesis 22:15–18"
  },
  "Genesis 22:12": {
    "title": "Now I know thou fearest God",
    "text": "Abraham is told not to harm Isaac, and the statement recognizes that he has not withheld his son. The test reveals Abraham’s reverence and trust. The passage does not teach that God ultimately desires child sacrifice; He explicitly stops it.",
    "refs": "Deuteronomy 12:31; Hebrews 11:17–19"
  },
  "Genesis 22:13": {
    "title": "A ram instead of Isaac",
    "text": "Abraham sees a ram caught in a thicket and offers it instead of his son. The substitute is the immediate provision in the story. Christian interpretation may see a pattern pointing toward substitutionary sacrifice, while recognizing that Genesis directly describes the ram.",
    "refs": "Exodus 12:5–13; John 1:29"
  },
  "Genesis 22:14": {
    "title": "The LORD will provide",
    "text": "Abraham names the place “The LORD will provide,” and the phrase becomes a saying. The name commemorates God’s provision at the moment of crisis. The verse supports trust in the LORD who provides, without promising that every desired outcome will occur in exactly the same way.",
    "refs": "Genesis 22:8; Philippians 4:19"
  },
  "Genesis 22:15": {
    "title": "The angel calls a second time",
    "text": "The angel of the LORD calls Abraham from heaven again. The second call introduces the covenant confirmation that follows. The passage repeats the messenger language while continuing to attribute the promise to the LORD’s authority.",
    "refs": "Genesis 22:16–18"
  },
  "Genesis 22:16": {
    "title": "By myself have I sworn",
    "text": "The LORD declares by Himself that because Abraham has done this and not withheld his son, He will bless him. God swears by Himself because there is no greater authority by whom to swear. The passage emphasizes the certainty of God’s covenant promise.",
    "refs": "Hebrews 6:13–18"
  },
  "Genesis 22:17": {
    "title": "Seed as the stars and sand",
    "text": "God promises to multiply Abraham’s seed like the stars and sand and says his seed will possess the gate of enemies. The promise repeats and expands earlier covenant words. Later Scripture connects Abraham’s seed with the blessing reaching the nations through Christ.",
    "refs": "Genesis 15:5; Galatians 3:16"
  },
  "Genesis 22:18": {
    "title": "All nations blessed through the seed",
    "text": "God promises that all nations of the earth will be blessed in Abraham’s seed because Abraham obeyed His voice. The New Testament explicitly connects this promise with the gospel blessing among the nations. In Oneness understanding, the one God fulfills His saving purpose through Jesus Christ.",
    "refs": "Genesis 12:3; Acts 3:25–26; Galatians 3:8, 16"
  },
  "Genesis 22:19": {
    "title": "Abraham returns to the young men",
    "text": "Abraham returns to the young men, and they travel together to Beersheba. Isaac is not separately mentioned in this summary, which has prompted questions, but the verse alone does not explain the omission. The text reports Abraham’s return and continued residence.",
    "refs": "Genesis 22:5; Genesis 21:31"
  },
  "Genesis 22:20": {
    "title": "News of Nahor’s family",
    "text": "Abraham is told that Milcah has borne children to Nahor. The genealogy prepares for the introduction of Rebekah, who will become Isaac’s wife. The narrative returns to the wider family line after the test on Moriah.",
    "refs": "Genesis 11:29; Genesis 24:15"
  },
  "Genesis 22:21": {
    "title": "The sons of Nahor",
    "text": "The verse names Huz, Buz, Kemuel, and other sons of Nahor. These names establish the family connections relevant to the following genealogy. The list is genealogical rather than a direct theological statement.",
    "refs": "Genesis 22:20–23"
  },
  "Genesis 22:22": {
    "title": "More descendants named",
    "text": "The genealogy continues with additional sons of Nahor. The names preserve the family record that will lead toward Rebekah. Historical identifications of these names should be treated cautiously when the text gives no further details.",
    "refs": "Genesis 22:20–23"
  },
  "Genesis 22:23": {
    "title": "Bethuel fathers Rebekah",
    "text": "Bethuel is named as the father of Rebekah, and the genealogy concludes. Rebekah’s introduction prepares for the next major family transition in Genesis. The verse links Abraham’s extended family with Isaac’s future marriage.",
    "refs": "Genesis 24:15; Genesis 24:67"
  },
  "Genesis 22:24": {
    "title": "Nahor’s concubine and descendants",
    "text": "The verse names descendants of Nahor’s concubine Reumah. It completes the family notice attached to Nahor. The genealogy provides background for later family relationships and should not be turned into claims about the spiritual worth of the named people.",
    "refs": "Genesis 22:20–23"
  },
  "Genesis 23:1": {
    "title": "Sarah’s lifespan",
    "text": "Sarah lives one hundred and twenty-seven years. The verse records her age at death and gives the first explicit account of her death in Genesis. The story now turns toward Abraham’s arrangements for her burial.",
    "refs": "Genesis 17:17; Genesis 23:2"
  },
  "Genesis 23:2": {
    "title": "Sarah dies at Hebron",
    "text": "Sarah dies at Kirjath-arba, identified as Hebron, and Abraham mourns and weeps for her. Scripture presents grief as a fitting human response to death. Faith in God does not require pretending loss causes no sorrow.",
    "refs": "John 11:35; 1 Thessalonians 4:13"
  },
  "Genesis 23:3": {
    "title": "Abraham rises from mourning",
    "text": "Abraham rises from before his dead and speaks to the sons of Heth. The narrative moves from grief to the practical need for a burial place. The verse shows mourning and necessary action together.",
    "refs": "Genesis 23:4"
  },
  "Genesis 23:4": {
    "title": "A stranger seeking a burial place",
    "text": "Abraham describes himself as a stranger and sojourner and asks for a burial possession. Despite God’s land promise, Abraham does not yet own a burial field and must negotiate with the local inhabitants. The verse shows the promise unfolding over time rather than being instantly possessed.",
    "refs": "Hebrews 11:9–10; Acts 7:5"
  },
  "Genesis 23:5": {
    "title": "The sons of Heth answer",
    "text": "The sons of Heth respond to Abraham. Their answer is developed in the next verse, where they offer him a choice of burial place. The exchange shows public negotiation within the local community.",
    "refs": "Genesis 23:6"
  },
  "Genesis 23:6": {
    "title": "A mighty prince among them",
    "text": "The sons of Heth call Abraham a mighty prince and offer him the choice of their sepulchres. Their respect contrasts with Abraham’s description of himself as a stranger. The verse shows that Abraham has a recognized standing even though he does not own the promised land.",
    "refs": "Genesis 14:13; Hebrews 11:9"
  },
  "Genesis 23:7": {
    "title": "Abraham bows to the people",
    "text": "Abraham rises and bows to the people of the land. His response shows courtesy and respect during the negotiation. The text does not portray the act as worship of the people; it is a gesture of honor in a public exchange.",
    "refs": "Genesis 23:12"
  },
  "Genesis 23:8": {
    "title": "Abraham asks for Ephron’s field",
    "text": "Abraham asks the people to intercede with Ephron so he may purchase the cave of Machpelah. He seeks a specific burial place and a clear transaction. The request begins the negotiation that follows.",
    "refs": "Genesis 23:9–11"
  },
  "Genesis 23:9": {
    "title": "The cave of Machpelah",
    "text": "Abraham asks to purchase the cave at the end of Ephron’s field for its full price as a burial possession. His insistence on paying establishes a clear claim rather than relying on a gift that might later be disputed. The transaction is recorded in detail because the burial property becomes significant in the patriarchal story.",
    "refs": "Genesis 25:9–10; Genesis 49:29–32"
  },
  "Genesis 23:10": {
    "title": "Ephron sits among the people",
    "text": "Ephron is present among the sons of Heth and answers publicly at the city gate. The public setting matters because the transaction will be witnessed and recognized. The passage emphasizes a formal property exchange rather than an informal private promise.",
    "refs": "Genesis 23:16–18"
  },
  "Genesis 23:11": {
    "title": "Ephron offers the field",
    "text": "Ephron says he gives Abraham the field and cave in the presence of his people. The language sounds generous, but the conversation continues with the price and payment. Abraham does not treat the offer as the end of the matter; he seeks a definite purchase.",
    "refs": "Genesis 23:13–16"
  },
  "Genesis 23:12": {
    "title": "Abraham bows again",
    "text": "Abraham bows before the people of the land. The gesture continues his respectful conduct in the negotiation. The narrative shows him acting courteously while still pursuing a clear and lasting burial possession.",
    "refs": "Genesis 23:7"
  },
  "Genesis 23:13": {
    "title": "Abraham insists on payment",
    "text": "Abraham tells Ephron that he will pay the price of the field and asks him to accept it. This establishes the transaction as a purchase. The verse reflects the importance of transparent agreements and recognized ownership.",
    "refs": "Genesis 23:16–18"
  },
  "Genesis 23:14": {
    "title": "Ephron replies",
    "text": "Ephron answers Abraham. The following verse gives the amount he names for the field, and the negotiation moves toward completion.",
    "refs": "Genesis 23:15"
  },
  "Genesis 23:15": {
    "title": "Four hundred shekels of silver",
    "text": "Ephron names a price of four hundred shekels of silver and downplays the amount between them. Abraham nevertheless pays the sum. The verse records the stated price and should not be converted into a modern monetary value without explaining the uncertainty of such comparisons.",
    "refs": "Genesis 23:16"
  },
  "Genesis 23:16": {
    "title": "Abraham weighs the silver",
    "text": "Abraham agrees to Ephron’s price and weighs out the silver in the hearing of the sons of Heth. The payment is public and measured, giving the purchase a clear basis. The text emphasizes that Abraham actually pays for the property.",
    "refs": "Genesis 23:9; Genesis 23:18"
  },
  "Genesis 23:17": {
    "title": "The property is identified",
    "text": "The field, cave, trees, and surrounding boundaries are identified as the property being purchased. The careful description helps establish exactly what changed hands. The burial place later becomes a family tomb and a marker of the patriarchs’ connection to the land.",
    "refs": "Genesis 25:9–10; Genesis 49:29–32"
  },
  "Genesis 23:18": {
    "title": "The purchase is witnessed",
    "text": "The property becomes Abraham’s possession in the presence of the people at the city gate. The witnesses and location make the transaction public. The verse records a legally recognized purchase rather than a mere verbal assurance.",
    "refs": "Genesis 23:16–17"
  },
  "Genesis 23:19": {
    "title": "Sarah is buried",
    "text": "Abraham buries Sarah in the cave of Machpelah in the field of Ephron near Mamre, which is Hebron. The verse closes the immediate mourning and burial narrative. The place will be associated with other patriarchal burials in later chapters.",
    "refs": "Genesis 25:9–10; Genesis 49:29–32"
  },
  "Genesis 23:20": {
    "title": "The field and cave secured",
    "text": "The field and cave are confirmed to Abraham as a burial possession by the sons of Heth. The chapter closes by emphasizing the legitimacy and permanence of the purchase. Abraham’s family still waits for the larger land promise, but now has a recognized burial place there.",
    "refs": "Genesis 23:16–19; Acts 7:16"
  },
  "Genesis 24:1": {
    "title": "Abraham is old and blessed",
    "text": "Abraham is old and well advanced in age, and the LORD has blessed him in all things. The statement summarizes God’s faithfulness over Abraham’s life before the search for Isaac’s wife begins. The blessing does not mean Abraham’s life was free of hardship.",
    "refs": "Genesis 12:2; Genesis 21:5"
  },
  "Genesis 24:2": {
    "title": "The eldest servant is commissioned",
    "text": "Abraham asks his eldest servant to swear an oath concerning Isaac’s wife. The request shows that Abraham treats the covenant family’s future as important. The oath is a specific act in the patriarchal narrative, not a general command for all believers to use the same procedure.",
    "refs": "Genesis 24:3–4"
  },
  "Genesis 24:3": {
    "title": "Do not take a wife from Canaan",
    "text": "Abraham asks the servant to swear by the LORD, the God of heaven and earth, that Isaac will not marry a daughter of the Canaanites. The concern is the covenant family’s direction and allegiance to the LORD. The verse should be read in its historical covenant setting, not as permission for ethnic contempt.",
    "refs": "Deuteronomy 7:3–4; 1 Kings 11:2"
  },
  "Genesis 24:4": {
    "title": "Go to Abraham’s kindred",
    "text": "The servant is instructed to travel to Abraham’s country and kindred to find a wife for Isaac. The instruction connects Isaac’s marriage with Abraham’s extended family. The narrative will show the servant relying on God’s guidance during the journey.",
    "refs": "Genesis 22:20–23; Genesis 24:12"
  },
  "Genesis 24:5": {
    "title": "What if the woman will not come?",
    "text": "The servant asks what he should do if the woman refuses to return to Canaan. The question anticipates a practical difficulty rather than expressing a denial of God’s promise. Abraham answers with confidence in God’s direction in the next verses.",
    "refs": "Genesis 24:6–8"
  },
  "Genesis 24:6": {
    "title": "Do not take Isaac back",
    "text": "Abraham firmly tells the servant not to take Isaac back to the land from which he came. The promise concerns the land God has given Abraham’s descendants. The instruction keeps Isaac’s future tied to God’s covenant rather than reversing the call.",
    "refs": "Genesis 12:1; Hebrews 11:8–9"
  },
  "Genesis 24:7": {
    "title": "The LORD will send His angel",
    "text": "Abraham recalls that the LORD took him from his father’s house and promised the land to his seed; he trusts that God will send His angel ahead. The verse expresses confidence in divine guidance. The mention of an angel describes God’s messenger and does not by itself define a separate divine person.",
    "refs": "Exodus 23:20; Hebrews 1:14"
  },
  "Genesis 24:8": {
    "title": "The servant released from the oath",
    "text": "If the woman will not come, the servant is released from the oath, but he must not take Isaac back there. The instructions include a contingency while preserving the main boundary. The passage shows that faith can plan for practical uncertainty.",
    "refs": "Genesis 24:5–6"
  },
  "Genesis 24:9": {
    "title": "The servant swears",
    "text": "The servant places his hand under Abraham’s thigh and swears concerning the matter. This is an ancient oath custom within the narrative. The verse records the practice but does not prescribe it for later believers.",
    "refs": "Genesis 24:2–4"
  },
  "Genesis 24:10": {
    "title": "The journey to Mesopotamia",
    "text": "The servant takes camels and gifts and travels to Mesopotamia, to the city of Nahor. The preparations show that the mission is both practical and purposeful. The next verses describe his prayer for guidance at the well.",
    "refs": "Genesis 22:20–23; Genesis 24:11–14"
  },
  "Genesis 24:11": {
    "title": "The camels kneel at the well",
    "text": "The servant makes the camels kneel by a well at evening, when women come to draw water. The ordinary setting becomes the place where he seeks God’s guidance. The narrative links divine providence with everyday circumstances.",
    "refs": "Genesis 24:12–15"
  },
  "Genesis 24:12": {
    "title": "The servant prays to the LORD",
    "text": "The servant asks the LORD, the God of his master Abraham, to show kindness and guide his mission. His prayer identifies the LORD as the one who can direct events. It models seeking God’s help while carrying out a responsibility.",
    "refs": "Proverbs 3:5–6; Psalm 32:8"
  },
  "Genesis 24:13": {
    "title": "The servant waits by the well",
    "text": "The servant describes where he is standing and the women who will come to draw water. His prayer is specific to the task at hand. The verse shows that he is looking for guidance in the circumstances of the journey.",
    "refs": "Genesis 24:11–12"
  },
  "Genesis 24:14": {
    "title": "A sign of kindness",
    "text": "The servant asks that the chosen woman offer him water and volunteer to water the camels. He asks that this identify a person whose conduct shows kindness and willingness to serve. The sign is part of this particular narrative and should not be turned into a formula that every decision must be made by testing people.",
    "refs": "Judges 6:36–40; Proverbs 31:26"
  },
  "Genesis 24:15": {
    "title": "Rebekah arrives",
    "text": "Before the servant finishes speaking, Rebekah arrives with a pitcher. The narrative presents the timing as an answer to prayer. Rebekah’s family line was introduced in Genesis 22, connecting the events through the wider genealogy.",
    "refs": "Genesis 22:23; Genesis 24:45"
  },
  "Genesis 24:16": {
    "title": "Rebekah’s appearance and purity",
    "text": "Rebekah is described as fair to look upon, a virgin, and not known by man. The details identify her in the narrative before the servant speaks with her. The passage’s focus is her suitability within the marriage arrangement, not a universal measure of a person’s worth based only on appearance.",
    "refs": "Genesis 24:43; Proverbs 31:30"
  },
  "Genesis 24:17": {
    "title": "The servant asks for water",
    "text": "The servant runs to meet Rebekah and asks for a little water from her pitcher. The action begins the test he prayed about. The story’s focus is the interaction and Rebekah’s response, not the servant’s status or power.",
    "refs": "Genesis 24:14; Genesis 24:18"
  },
  "Genesis 24:18": {
    "title": "Rebekah offers water",
    "text": "Rebekah promptly lowers her pitcher and gives the servant a drink. Her response shows willingness and courtesy. The following verses expand her offer to water the camels as well.",
    "refs": "Genesis 24:14; Genesis 24:19"
  },
  "Genesis 24:19": {
    "title": "Rebekah waters the camels",
    "text": "After the servant drinks, Rebekah offers to draw water for the camels until they have finished drinking. This is substantial labor and demonstrates generosity in the scene. Her actions match the sign the servant had prayed about.",
    "refs": "Genesis 24:14; Genesis 24:20"
  },
  "Genesis 24:20": {
    "title": "Rebekah hurries to draw water",
    "text": "Rebekah quickly empties her pitcher into the trough and returns to draw more water for the camels. The repetition stresses her energy and willingness to help. The narrative portrays her character through action rather than merely through description.",
    "refs": "Genesis 24:18–19"
  },
  "Genesis 24:21": {
    "title": "The servant watches in silence",
    "text": "The servant watches Rebekah, wondering whether the LORD has made his journey successful. He does not immediately assume he knows the answer; he observes and waits. This careful pause distinguishes prayerful expectation from hasty certainty.",
    "refs": "Proverbs 18:13; Genesis 24:26"
  },
  "Genesis 24:22": {
    "title": "Gifts are given to Rebekah",
    "text": "After the camels finish drinking, the servant gives Rebekah jewelry. The gifts begin a formal exchange, but he still needs to learn her family identity and whether hospitality is available. The story combines practical arrangements with the servant’s belief that God has guided him.",
    "refs": "Genesis 24:23–27"
  },
  "Genesis 24:23": {
    "title": "The servant asks her family",
    "text": "The servant asks whose daughter Rebekah is and whether there is room for lodging. These are sensible questions that verify her family connection and practical circumstances. The narrative shows that perceived guidance is followed by careful inquiry.",
    "refs": "Genesis 24:24–25"
  },
  "Genesis 24:24": {
    "title": "Rebekah names her family",
    "text": "Rebekah identifies herself as the daughter of Bethuel, son of Milcah and Nahor. Her answer confirms the family connection sought by Abraham. The genealogy introduced earlier now becomes directly relevant to the mission.",
    "refs": "Genesis 22:20–23; Genesis 24:15"
  },
  "Genesis 24:25": {
    "title": "There is room and food",
    "text": "Rebekah says there is both straw and provender for the camels and room for lodging. Her answer extends hospitality beyond the initial drink. The servant’s journey now has a practical path forward.",
    "refs": "Genesis 24:23; Genesis 24:31"
  },
  "Genesis 24:26": {
    "title": "The servant worships the LORD",
    "text": "The servant bows his head and worships the LORD after hearing Rebekah’s answer. He attributes the apparent success of the journey to God’s guidance. This is worship of the LORD, the God of Abraham, rather than praise of the servant’s own cleverness.",
    "refs": "Genesis 24:12; Genesis 24:48"
  },
  "Genesis 24:27": {
    "title": "God has led him to Abraham’s kin",
    "text": "The servant blesses the LORD, who has not left His mercy and truth toward Abraham and has led him to the house of his master’s relatives. The verse explicitly attributes guidance to the LORD. It presents God’s faithfulness as continuous with the covenant promises.",
    "refs": "Genesis 12:1–3; Genesis 24:48"
  },
  "Genesis 24:28": {
    "title": "Rebekah tells her household",
    "text": "Rebekah runs to tell her mother’s household what has happened. The family now becomes involved in the visitor’s mission. The narrative continues through ordinary communication and hospitality.",
    "refs": "Genesis 24:29–31"
  },
  "Genesis 24:29": {
    "title": "Laban runs to the servant",
    "text": "Rebekah’s brother Laban runs out to the man at the well. The next verse explains that he has seen the jewelry and heard Rebekah’s report. The verse begins Laban’s role in the negotiations.",
    "refs": "Genesis 24:30"
  },
  "Genesis 24:30": {
    "title": "Laban sees the jewelry",
    "text": "Laban sees the jewelry on Rebekah and hears her account, then goes to the servant. The detail helps explain his eagerness to welcome the visitor. The text does not explicitly state every motive Laban has, so interpretations about greed should be identified as inference.",
    "refs": "Genesis 24:29; Genesis 24:31"
  },
  "Genesis 24:31": {
    "title": "Come in, blessed of the LORD",
    "text": "Laban invites the servant into the house and calls him blessed of the LORD. The greeting recognizes the LORD in the events surrounding the visitor. The servant’s mission is received with hospitality.",
    "refs": "Genesis 24:26–27"
  },
  "Genesis 24:32": {
    "title": "The camels are cared for",
    "text": "The servant enters, the camels are unloaded and given straw and provender, and water is provided for washing feet. The narrative emphasizes hospitality and practical care. The servant’s mission is not complete until he explains why he has come.",
    "refs": "Genesis 18:4; Genesis 24:33"
  },
  "Genesis 24:33": {
    "title": "The servant will not eat until he speaks",
    "text": "Food is set before the servant, but he says he will not eat until he has delivered his message. His sense of mission takes priority over the meal. The family agrees to hear him, and he begins by explaining Abraham’s circumstances.",
    "refs": "Genesis 24:34–36"
  },
  "Genesis 24:34": {
    "title": "I am Abraham’s servant",
    "text": "The servant identifies himself and begins his account. His role is to carry out Abraham’s commission, not to seek a wife for himself. The first-person report gives the family the background needed to evaluate the request.",
    "refs": "Genesis 24:2–4"
  },
  "Genesis 24:35": {
    "title": "The LORD has blessed Abraham greatly",
    "text": "The servant describes Abraham’s wealth in livestock, silver, gold, servants, and camels. The point is to explain Abraham’s household and standing. The wealth is reported as a fact of the story, not as proof that riches alone establish righteousness.",
    "refs": "Genesis 13:2; Genesis 24:1"
  },
  "Genesis 24:36": {
    "title": "Isaac is Abraham’s heir",
    "text": "The servant says Sarah bore Abraham a son in her old age and that Abraham gave him all he had. This confirms Isaac’s place as the promised heir. The detail connects the marriage mission to the covenant promise fulfilled in Isaac’s birth.",
    "refs": "Genesis 21:1–7; Genesis 25:5"
  },
  "Genesis 24:37": {
    "title": "The oath not to take a Canaanite wife",
    "text": "The servant recounts Abraham’s oath that Isaac should not marry a daughter of the Canaanites. The concern reflects the covenant family’s religious direction and future. It should be understood in that ancient setting, not generalized into contempt for people of other ethnicities.",
    "refs": "Genesis 24:3–4; Deuteronomy 7:3–4"
  },
  "Genesis 24:38": {
    "title": "Go to Abraham’s kindred",
    "text": "The servant repeats the instruction to go to Abraham’s father’s house and kindred to find a wife for Isaac. The retelling underscores the family connection as a central condition of the mission. The next verses recount Abraham’s confidence that God would guide the journey.",
    "refs": "Genesis 24:4; Genesis 24:39"
  },
  "Genesis 24:39": {
    "title": "The servant asks what if she will not come",
    "text": "The servant recounts his question about the woman’s willingness to return. The account shows that the journey involved uncertainty and required trust. Abraham’s answer, repeated next, gave the servant a clear boundary and confidence in God’s help.",
    "refs": "Genesis 24:5–8"
  },
  "Genesis 24:40": {
    "title": "The LORD will send His angel",
    "text": "The servant repeats Abraham’s assurance that the LORD, before whom Abraham walks, would send His angel and prosper the journey. The messenger is presented as God’s agent. The verse does not itself define the angel as a separate divine person.",
    "refs": "Genesis 24:7; Exodus 23:20"
  },
  "Genesis 24:41": {
    "title": "The servant is released if refused",
    "text": "The servant recounts that he would be released from the oath if the family refused, provided he did not take Isaac back there. The condition preserves the central instruction while acknowledging the woman’s family may decline. The narrative is not presented as coercion of Rebekah.",
    "refs": "Genesis 24:8"
  },
  "Genesis 24:42": {
    "title": "The servant prays at the well",
    "text": "The servant explains that when he reached the well, he prayed to the LORD, the God of Abraham, for guidance. The retelling emphasizes prayer as part of the mission. God’s name and relationship to Abraham remain central in the servant’s account.",
    "refs": "Genesis 24:12–14"
  },
  "Genesis 24:43": {
    "title": "The sign repeated",
    "text": "The servant recounts the request that the young woman who came to draw water offer him a drink. He is explaining how Rebekah’s arrival fit the prayer he had made. The narrative presents this as guidance in a particular situation, not as a universal method that guarantees every decision.",
    "refs": "Genesis 24:14–15"
  },
  "Genesis 24:44": {
    "title": "The woman who waters the camels",
    "text": "The servant repeats that the woman who offered him water and watered the camels would be the one he saw as provided by the LORD. The action demonstrates hospitality and diligence. The servant is now giving the family his reasoning rather than simply demanding agreement.",
    "refs": "Genesis 24:18–20"
  },
  "Genesis 24:45": {
    "title": "Rebekah arrives before he finishes praying",
    "text": "The servant says Rebekah arrived while he was still speaking in his heart, carrying her pitcher. The timing is presented as providential. The verse highlights the servant’s perception that the LORD answered his prayer.",
    "refs": "Genesis 24:15; Genesis 24:26"
  },
  "Genesis 24:46": {
    "title": "Rebekah waters him and the camels",
    "text": "The servant recounts Rebekah’s offer of water and her work watering the camels. These actions correspond to the request he had made. The repetition reinforces why he believes the LORD has guided him to Abraham’s relatives.",
    "refs": "Genesis 24:18–20"
  },
  "Genesis 24:47": {
    "title": "The servant asks her family identity",
    "text": "The servant recounts asking whose daughter she was and hearing that she was Bethuel’s daughter. He also mentions giving her the jewelry. The answer confirms the family relationship central to Abraham’s commission.",
    "refs": "Genesis 24:23–24"
  },
  "Genesis 24:48": {
    "title": "The servant worships the LORD",
    "text": "The servant says he bowed his head and worshipped the LORD, who led him to the right family. The verse explicitly attributes the successful search to the LORD’s guidance. This is worship directed to the one God, not to the servant or the family.",
    "refs": "Genesis 24:26–27; Deuteronomy 6:4"
  },
  "Genesis 24:49": {
    "title": "Choose kindness or tell him no",
    "text": "The servant asks the family to show kindness and truth to Abraham, or else tell him plainly so he can turn elsewhere. He does not pretend the family has no choice. The request seeks an honest answer to complete the mission.",
    "refs": "Genesis 24:8; Joshua 2:14"
  },
  "Genesis 24:50": {
    "title": "The matter is from the LORD",
    "text": "Laban and Bethuel answer that the matter comes from the LORD and that they cannot speak against it. Their response recognizes God’s providence in the events. The statement is their judgment about this particular marriage proposal, not a blanket claim that every human plan is God’s will.",
    "refs": "Proverbs 16:9; Genesis 24:51"
  },
  "Genesis 24:51": {
    "title": "Rebekah may go with the servant",
    "text": "The family gives Rebekah to the servant to become Isaac’s wife, as the LORD has spoken. The next verses show that the family will still speak with Rebekah herself. The account combines family consent and the woman’s own answer.",
    "refs": "Genesis 24:57–58"
  },
  "Genesis 24:52": {
    "title": "The servant worships again",
    "text": "When the servant hears their words, he bows himself to the earth before the LORD. His repeated worship shows gratitude and recognition that the journey has been guided. The success is attributed to God, not merely to human planning.",
    "refs": "Genesis 24:26–27"
  },
  "Genesis 24:53": {
    "title": "Gifts for Rebekah and her family",
    "text": "The servant brings out silver, gold, clothing, and gifts for Rebekah’s brother and mother. The gifts accompany the marriage arrangement in the culture of the narrative. The text reports the custom without requiring modern readers to reproduce every ancient practice.",
    "refs": "Genesis 24:22; Genesis 24:30"
  },
  "Genesis 24:54": {
    "title": "The servant asks to depart",
    "text": "After eating and resting, the servant asks to be sent away to his master. He remains focused on completing the commission rather than prolonging the visit. The family’s request to delay is recorded next.",
    "refs": "Genesis 24:55"
  },
  "Genesis 24:55": {
    "title": "The family asks for a delay",
    "text": "Rebekah’s brother and mother ask that she remain for a time before departing. Their request shows the emotional and practical cost of her leaving. The next verses bring Rebekah’s own decision into the conversation.",
    "refs": "Genesis 24:56–58"
  },
  "Genesis 24:56": {
    "title": "The servant asks not to delay",
    "text": "The servant asks them not to delay him, since the LORD has prospered his way. He believes the time has come to return to Abraham. The verse highlights the servant’s sense of duty and gratitude for divine guidance.",
    "refs": "Genesis 24:40; Genesis 24:52"
  },
  "Genesis 24:57": {
    "title": "Ask Rebekah herself",
    "text": "The family proposes calling Rebekah and asking her directly. This is an important detail: the narrative does not end with the family deciding without her voice. Her response follows immediately.",
    "refs": "Genesis 24:58"
  },
  "Genesis 24:58": {
    "title": "Rebekah agrees to go",
    "text": "Rebekah is asked whether she will go with the servant, and she answers, “I will go.” Her willingness is explicitly recorded. The journey proceeds with her own assent rather than only through arrangements made by others.",
    "refs": "Genesis 24:51; Genesis 24:61"
  },
  "Genesis 24:59": {
    "title": "Rebekah departs with her nurse",
    "text": "The family sends Rebekah away with her nurse and the servant and his men. The departure marks a major transition in her life. The story has traced the journey from prayer to family agreement and Rebekah’s own decision.",
    "refs": "Genesis 24:61"
  },
  "Genesis 24:60": {
    "title": "A blessing for Rebekah",
    "text": "Rebekah’s family blesses her, wishing that she become the mother of thousands and that her seed possess the gate of those who hate them. The words echo covenant language given to Abraham. The blessing links Rebekah’s future with the promised family line.",
    "refs": "Genesis 22:17; Genesis 24:4"
  },
  "Genesis 24:61": {
    "title": "Rebekah travels toward Isaac",
    "text": "Rebekah and her attendants rise, mount the camels, and follow the servant. The journey carries the answer to Abraham’s commission back to Canaan. The narrative emphasizes the completion of the servant’s task through God’s guidance and Rebekah’s willingness.",
    "refs": "Genesis 24:58–60"
  },
  "Genesis 24:62": {
    "title": "Isaac comes from the way of the well",
    "text": "Isaac has come from the way of the well Lahai-roi and is dwelling in the south country. The place name recalls God’s seeing and hearing of Hagar. The verse sets the scene for Isaac’s meeting with Rebekah.",
    "refs": "Genesis 16:13–14; Genesis 24:63"
  },
  "Genesis 24:63": {
    "title": "Isaac meditates in the field",
    "text": "Isaac goes out into the field at evening to meditate and looks up to see the camels coming. The verse gives a quiet moment before the meeting. The exact Hebrew word translated “meditate” has been discussed, but the scene conveys Isaac’s solitary reflection.",
    "refs": "Psalm 1:2; Genesis 24:64"
  },
  "Genesis 24:64": {
    "title": "Rebekah sees Isaac",
    "text": "Rebekah looks up and sees Isaac, then dismounts from her camel. The narrative shifts from the long search to the meeting itself. Her response signals that she recognizes the man she is approaching.",
    "refs": "Genesis 24:65"
  },
  "Genesis 24:65": {
    "title": "Rebekah asks about Isaac",
    "text": "Rebekah asks the servant who the man is walking in the field, and the servant says he is his master. She covers herself with a veil. The verse reflects the customs of the narrative’s setting; the veil should be interpreted in context rather than made into an unqualified rule for every culture.",
    "refs": "1 Corinthians 11:5–6"
  },
  "Genesis 24:66": {
    "title": "The servant reports the journey",
    "text": "The servant tells Isaac everything he has done. The report closes the mission narrative and explains how Rebekah came to be there. The servant’s account has consistently attributed the outcome to the LORD’s guidance.",
    "refs": "Genesis 24:12–27; Genesis 24:48"
  },
  "Genesis 24:67": {
    "title": "Isaac takes Rebekah as his wife",
    "text": "Isaac brings Rebekah into Sarah’s tent, takes her as his wife, and loves her; he is comforted after his mother’s death. The verse joins marriage with grief and consolation. It records the continuation of the covenant family through Isaac and Rebekah.",
    "refs": "Genesis 23:1–2; Genesis 25:20"
  },
  "Genesis 25:1": {
    "title": "Abraham takes another wife",
    "text": "Abraham takes Keturah as a wife after Sarah’s death. The verse introduces another family line in Abraham’s later life. The text records the relationship without suggesting that every family arrangement described in Genesis is a universal command.",
    "refs": "Genesis 23:1–2; 1 Chronicles 1:32"
  },
  "Genesis 25:2": {
    "title": "Keturah’s sons",
    "text": "The verse lists the sons born to Keturah. These names extend the account of Abraham’s descendants beyond Isaac and Ishmael. The next verses continue the genealogy and describe Abraham’s arrangements for inheritance.",
    "refs": "Genesis 25:5–6"
  },
  "Genesis 25:3": {
    "title": "The sons of Dedan",
    "text": "The genealogy names descendants of Dedan. The list helps record family lines associated with Abraham’s wider household. Precise identification of every ancient group with modern populations requires evidence beyond the names alone.",
    "refs": "Genesis 10:7; 1 Chronicles 1:32"
  },
  "Genesis 25:4": {
    "title": "The sons of Midian",
    "text": "The verse names the sons of Midian and other descendants. Midian becomes important in later biblical narratives. The genealogy preserves ancestry but does not define the moral character of every later person associated with these names.",
    "refs": "Exodus 2:15–21; Numbers 22:4"
  },
  "Genesis 25:5": {
    "title": "Isaac receives Abraham’s possessions",
    "text": "Abraham gives all that he has to Isaac. This confirms Isaac’s place as the covenant heir. The earlier promise of a multitude of nations does not erase the specific inheritance assigned to Isaac in the family narrative.",
    "refs": "Genesis 17:19–21; Genesis 24:36"
  },
  "Genesis 25:6": {
    "title": "Gifts to other sons and separation",
    "text": "Abraham gives gifts to the sons of his concubines and sends them eastward, away from Isaac. The arrangement distinguishes Isaac’s inheritance while acknowledging the other sons. The verse reports the patriarch’s household decision, not a rule for every family inheritance.",
    "refs": "Genesis 25:5; Genesis 21:12–13"
  },
  "Genesis 25:7": {
    "title": "Abraham’s lifespan",
    "text": "Abraham lives one hundred and seventy-five years. The verse records the end of a life shaped by God’s call and covenant. His story includes faith and failure, yet the narrative repeatedly emphasizes God’s faithfulness to His promise.",
    "refs": "Genesis 12:1–3; Hebrews 11:8–10"
  },
  "Genesis 25:8": {
    "title": "Abraham dies in a good old age",
    "text": "Abraham dies at a good old age, old and full of years, and is gathered to his people. The expression describes the completion of his life. The verse does not give a full doctrine of the afterlife by itself; its language belongs to the patriarchal burial narrative.",
    "refs": "Genesis 15:15; Genesis 25:9"
  },
  "Genesis 25:9": {
    "title": "Isaac and Ishmael bury Abraham",
    "text": "Isaac and Ishmael bury Abraham in the cave of Machpelah with Sarah. Their cooperation at the burial is notable given the earlier separation of their households. The verse records both sons participating in honoring their father.",
    "refs": "Genesis 23:19; Genesis 21:13–14"
  },
  "Genesis 25:10": {
    "title": "The family burial place",
    "text": "The field Abraham purchased from the sons of Heth is identified as the burial place of Abraham and Sarah. The property purchase in Genesis 23 now becomes the family tomb. The narrative carefully connects the patriarchs with the promised land through this burial possession.",
    "refs": "Genesis 23:16–20; Genesis 49:29–32"
  },
  "Genesis 25:11": {
    "title": "God blesses Isaac",
    "text": "After Abraham’s death, God blesses Isaac, who dwells by the well Lahai-roi. The verse shows the covenant story continuing through Isaac. The one God who called Abraham remains active in the next generation.",
    "refs": "Genesis 17:19; Genesis 26:2–5"
  },
  "Genesis 25:12": {
    "title": "The generations of Ishmael",
    "text": "The text introduces Ishmael’s descendants, identifying him as Abraham’s son through Hagar. This genealogy fulfills the promise that Ishmael would become a great nation. The record should not be used to stereotype modern peoples descended from or associated with these ancient names.",
    "refs": "Genesis 16:10; Genesis 17:20"
  },
  "Genesis 25:13": {
    "title": "Ishmael’s sons named",
    "text": "The verse lists Ishmael’s sons in the order of their birth. These names preserve the genealogy promised earlier. The list is historical and familial rather than a doctrinal statement about God’s identity.",
    "refs": "Genesis 17:20; Genesis 25:16"
  },
  "Genesis 25:14": {
    "title": "Mishma and Dumah",
    "text": "The genealogy continues with Mishma, Dumah, and Massa. These names help identify the descendants of Ishmael in the biblical record. Modern geographical associations may be discussed, but should not be presented as certain where evidence is limited.",
    "refs": "Genesis 25:13–16"
  },
  "Genesis 25:15": {
    "title": "Hadar and other sons",
    "text": "The verse continues the list of Ishmael’s sons. The genealogy records the breadth of the family line and sets up the summary of their settlements. Its purpose is to show the fulfillment of God’s promise concerning Ishmael’s descendants.",
    "refs": "Genesis 17:20; Genesis 25:16"
  },
  "Genesis 25:16": {
    "title": "Twelve princes by their nations",
    "text": "Ishmael’s sons are identified as twelve princes according to their settlements and encampments. This corresponds to God’s promise that Ishmael would become a great nation. The verse shows that God’s word concerning Ishmael was fulfilled even though Isaac carries the covenant line.",
    "refs": "Genesis 17:20; Genesis 21:13"
  },
  "Genesis 25:17": {
    "title": "Ishmael’s lifespan and death",
    "text": "Ishmael lives one hundred and thirty-seven years and is gathered to his people. The verse records his death and closes his genealogy. The narrative acknowledges his place in Abraham’s family and God’s promise to him.",
    "refs": "Genesis 16:10–12; Genesis 17:20"
  },
  "Genesis 25:18": {
    "title": "Ishmael’s descendants settle",
    "text": "Ishmael’s descendants settle from Havilah to Shur, toward Egypt and Assyria, and are described in relation to their brethren. The verse gives a broad geographical picture of the family’s spread. It should not be used to assign a fixed character to modern populations.",
    "refs": "Genesis 10:7; Genesis 25:16"
  },
  "Genesis 25:19": {
    "title": "The generations of Isaac",
    "text": "The text begins Isaac’s family account and identifies him as Abraham’s son. The repeated genealogy formula connects Isaac to the covenant promises already given. The next verses describe the long-awaited birth of his children.",
    "refs": "Genesis 17:19; Genesis 21:1–3"
  },
  "Genesis 25:20": {
    "title": "Isaac marries Rebekah",
    "text": "Isaac is forty years old when he marries Rebekah, daughter of Bethuel and sister of Laban. This connects the marriage narrative of Genesis 24 with the next generation. The family connection is stated directly in the verse.",
    "refs": "Genesis 24:15; Genesis 24:67"
  },
  "Genesis 25:21": {
    "title": "Isaac prays for Rebekah",
    "text": "Isaac entreats the LORD for Rebekah because she is barren, and the LORD answers his prayer so she conceives. The verse presents God as the one who hears and acts. The covenant promise continues through divine faithfulness, not human control over fertility.",
    "refs": "Genesis 11:30; 1 Samuel 1:10–20"
  },
  "Genesis 25:22": {
    "title": "The children struggle within Rebekah",
    "text": "The children struggle inside Rebekah, and she asks why this is happening. She goes to inquire of the LORD. The verse portrays a troubling pregnancy and Rebekah’s search for understanding from God.",
    "refs": "Genesis 25:23; Jeremiah 1:5"
  },
  "Genesis 25:23": {
    "title": "Two nations in the womb",
    "text": "The LORD tells Rebekah that two nations are in her womb and that the elder will serve the younger. The oracle explains the struggle as connected to the future of the two lines. Paul later discusses this passage in relation to God’s purpose; the immediate text concerns Jacob and Esau and their descendants.",
    "refs": "Romans 9:10–13; Malachi 1:2–3"
  },
  "Genesis 25:24": {
    "title": "The twins are born",
    "text": "When the days of delivery arrive, Rebekah bears twins. The birth fulfills the announcement that two children and two lines are involved. The following verses describe their distinct appearances and names.",
    "refs": "Genesis 25:23"
  },
  "Genesis 25:25": {
    "title": "Esau is born",
    "text": "The first child is red and hairy, and he is named Esau. The description explains the name and contrasts with the second child’s appearance. The text is setting up the different paths the brothers will take.",
    "refs": "Genesis 25:26; Genesis 27:11"
  },
  "Genesis 25:26": {
    "title": "Jacob is born holding Esau’s heel",
    "text": "The second child comes out holding Esau’s heel and is named Jacob. The name is connected in the narrative with the heel, and later events develop its associations. Isaac is sixty years old at the twins’ birth, a marker of the long wait for children.",
    "refs": "Genesis 25:23; Genesis 27:36"
  },
  "Genesis 25:27": {
    "title": "The brothers’ different ways",
    "text": "Esau becomes a skilled hunter and man of the field, while Jacob is a quiet man dwelling in tents. The description sets up their differing interests and family dynamics. Neither occupation alone determines moral character; the following story reveals their choices.",
    "refs": "Genesis 27:3–5"
  },
  "Genesis 25:28": {
    "title": "Isaac and Rebekah have preferences",
    "text": "Isaac loves Esau because he eats of his venison, while Rebekah loves Jacob. The divided parental affection contributes to the family tension that follows. The text reports the favoritism without endorsing it as a wise way to raise children.",
    "refs": "Genesis 27:1–13; Ephesians 6:4"
  },
  "Genesis 25:29": {
    "title": "Jacob cooks pottage",
    "text": "Jacob cooks pottage when Esau comes in from the field faint. The ordinary meal becomes the setting for a consequential exchange. The verse prepares for Esau’s request and Jacob’s demand.",
    "refs": "Genesis 25:30–34"
  },
  "Genesis 25:30": {
    "title": "Esau asks for the red pottage",
    "text": "Esau asks Jacob to feed him the red stew and is called Edom in connection with the episode. The name becomes associated with Esau’s descendants. The verse connects a brief family event with a later people’s name.",
    "refs": "Genesis 36:1; Genesis 36:8"
  },
  "Genesis 25:31": {
    "title": "Jacob asks for the birthright",
    "text": "Jacob tells Esau to sell him his birthright first. Jacob seeks an advantage from Esau’s hunger, and the narrative presents a morally complicated transaction. The later blessing story shows that family inheritance and blessing remain sources of conflict.",
    "refs": "Genesis 27:36; Hebrews 12:16"
  },
  "Genesis 25:32": {
    "title": "Esau fears he will die",
    "text": "Esau says he is at the point of death and asks what profit the birthright will do him. His words show that immediate appetite dominates his thinking. The next verse records his oath and the exchange.",
    "refs": "Hebrews 12:16–17"
  },
  "Genesis 25:33": {
    "title": "Esau sells his birthright",
    "text": "Esau swears and sells his birthright to Jacob. The act gives up a significant family privilege for immediate food. The New Testament later uses Esau as a warning against treating sacred privileges lightly.",
    "refs": "Hebrews 12:16"
  },
  "Genesis 25:34": {
    "title": "Esau despises his birthright",
    "text": "Jacob gives Esau bread and pottage; Esau eats, drinks, rises, and leaves. The narrator concludes that Esau despised his birthright. The verse criticizes his disregard for the privilege, while Jacob’s manipulative demand remains part of the wider family conflict.",
    "refs": "Genesis 25:31–33; Hebrews 12:16"
  },
  "Genesis 26:1": {
    "title": "A famine in Isaac’s time",
    "text": "A famine comes besides the earlier famine, and Isaac goes to Abimelech king of the Philistines in Gerar. The situation echoes the earlier famine in Abraham’s story. The next verses give Isaac a specific instruction from the LORD.",
    "refs": "Genesis 12:10; Genesis 26:2"
  },
  "Genesis 26:2": {
    "title": "The LORD appears to Isaac",
    "text": "The LORD appears to Isaac and tells him not to go down to Egypt but to dwell in the land God will show him. The verse identifies the LORD as the one speaking directly to Isaac. The instruction recalls God’s earlier direction to Abraham while addressing Isaac’s own situation.",
    "refs": "Genesis 12:1; Genesis 26:3"
  },
  "Genesis 26:3": {
    "title": "God confirms the oath to Abraham",
    "text": "God tells Isaac to sojourn in the land and promises to be with him and bless him, confirming the oath sworn to Abraham. The covenant promise continues through Isaac. The text presents one LORD acting faithfully across generations.",
    "refs": "Genesis 22:16–18; Genesis 28:13–15"
  },
  "Genesis 26:4": {
    "title": "The stars and the nations blessed",
    "text": "God promises descendants as numerous as the stars and says all nations will be blessed in Isaac’s seed. This repeats the covenant promise and connects the family line with blessing for the nations. The New Testament traces this promise toward Christ and the gospel.",
    "refs": "Genesis 22:17–18; Galatians 3:8, 16"
  },
  "Genesis 26:5": {
    "title": "Abraham obeyed God’s voice",
    "text": "God connects the covenant promise with Abraham’s obedience to His voice, commandments, statutes, and laws. The verse summarizes Abraham’s faithfulness in the narrative. It should be read in the context of the covenant relationship and not used to claim Abraham earned God’s promise by perfect performance.",
    "refs": "Genesis 12:1–4; Genesis 15:6"
  },
  "Genesis 26:6": {
    "title": "Isaac stays in Gerar",
    "text": "Isaac dwells in Gerar as instructed. The brief verse shows his obedience to the command not to go down to Egypt. The following verses show that Isaac nevertheless repeats a pattern of fear seen in Abraham’s life.",
    "refs": "Genesis 26:2–3; Genesis 26:7"
  },
  "Genesis 26:7": {
    "title": "Isaac says Rebekah is his sister",
    "text": "Isaac tells the men of the place that Rebekah is his sister because he fears they may kill him for her. This repeats Abraham’s deception concerning Sarah. The Bible records the failure honestly rather than presenting the patriarchs as flawless examples.",
    "refs": "Genesis 12:13; Genesis 20:2"
  },
  "Genesis 26:8": {
    "title": "Abimelech sees Isaac and Rebekah",
    "text": "After Isaac has been there a long time, Abimelech sees Isaac showing affection toward Rebekah. The action reveals that she is his wife, not his sister. The narrative shows the deception being exposed by ordinary observation.",
    "refs": "Genesis 26:7; Genesis 26:9"
  },
  "Genesis 26:9": {
    "title": "Abimelech confronts Isaac",
    "text": "Abimelech asks why Isaac said Rebekah was his sister, and Isaac admits fear of death. The foreign king again confronts a patriarch’s deception. Scripture’s honest reporting warns that fear can lead believers to mislead others.",
    "refs": "Genesis 20:9–11"
  },
  "Genesis 26:10": {
    "title": "A possible wrong against the people",
    "text": "Abimelech says Isaac might have brought guilt upon the people if someone had taken Rebekah as his wife. The verse shows that deception can place others at risk of wrongdoing. The king’s rebuke exposes the social consequences of Isaac’s fear.",
    "refs": "Genesis 20:3–7; Proverbs 12:22"
  },
  "Genesis 26:11": {
    "title": "Protection for Isaac and Rebekah",
    "text": "Abimelech commands that no one harm Isaac or Rebekah under penalty of death. The king protects them after learning the truth. The account again shows a foreign ruler acting with a sense of justice while the patriarch’s conduct is corrected.",
    "refs": "Genesis 20:6–7"
  },
  "Genesis 26:12": {
    "title": "Isaac sows and reaps abundantly",
    "text": "Isaac sows in the land and receives a hundredfold in the same year because the LORD blesses him. The verse explicitly attributes the harvest to God’s blessing. It describes Isaac’s particular experience and should not be made into a guarantee that every faithful person will receive the same material yield.",
    "refs": "Genesis 26:3–5; Psalm 67:6"
  },
  "Genesis 26:13": {
    "title": "Isaac grows prosperous",
    "text": "Isaac grows great, continues to prosper, and becomes very wealthy. The narrative describes the material result of the blessing in this period. Wealth is a circumstance in the story, not the sole measure of spiritual faithfulness.",
    "refs": "Genesis 26:12; Proverbs 10:22"
  },
  "Genesis 26:14": {
    "title": "The Philistines envy Isaac",
    "text": "Isaac has flocks, herds, and servants, and the Philistines envy him. The verse shows prosperity creating social tension. Envy can turn another person’s success into a source of conflict rather than gratitude.",
    "refs": "Genesis 26:15; Proverbs 14:30"
  },
  "Genesis 26:15": {
    "title": "Wells stopped up",
    "text": "The Philistines stop up the wells dug by Abraham’s servants. The act attacks the family’s access to water and threatens its livelihood. The dispute over wells will become a recurring issue in the chapter.",
    "refs": "Genesis 21:25; Genesis 26:18"
  },
  "Genesis 26:16": {
    "title": "Abimelech asks Isaac to leave",
    "text": "Abimelech tells Isaac to depart because he has become much mightier than the local people. The verse records a political decision prompted by the growing tension. Isaac’s prosperity does not prevent hostility from those around him.",
    "refs": "Genesis 26:14–17"
  },
  "Genesis 26:17": {
    "title": "Isaac camps in the valley",
    "text": "Isaac moves away and camps in the valley of Gerar. He responds to the order by relocating rather than immediately fighting. The next verses describe his efforts to reopen the wells associated with Abraham.",
    "refs": "Genesis 26:16; Genesis 26:18"
  },
  "Genesis 26:18": {
    "title": "Isaac reopens Abraham’s wells",
    "text": "Isaac digs again the wells dug in Abraham’s days, which the Philistines had stopped up, and restores their names. The act preserves family history and recovers necessary water sources. The narrative emphasizes continuity between Abraham’s experience and Isaac’s.",
    "refs": "Genesis 21:25–31; Genesis 26:15"
  },
  "Genesis 26:19": {
    "title": "A well of springing water",
    "text": "Isaac’s servants dig in the valley and find a well of springing water. The discovery brings hope but soon leads to a dispute. The story shows the practical importance of water in the land and the tensions surrounding its control.",
    "refs": "Genesis 26:20"
  },
  "Genesis 26:20": {
    "title": "Esek, the well of contention",
    "text": "The herdsmen of Gerar contend with Isaac’s herdsmen over the well, and Isaac names it Esek because of the dispute. The name preserves the conflict in the narrative. Isaac does not insist on fighting over this well; he moves on and digs again.",
    "refs": "Genesis 26:21–22"
  },
  "Genesis 26:21": {
    "title": "Sitnah, another disputed well",
    "text": "Isaac’s servants dig another well, and the herdsmen contend over that one too. Isaac names it Sitnah, associated with opposition. The repeated conflict shows that the problem is persistent, but Isaac continues seeking a peaceful place.",
    "refs": "Genesis 26:20; Genesis 26:22"
  },
  "Genesis 26:22": {
    "title": "Rehoboth and room to flourish",
    "text": "Isaac moves again and digs a well over which there is no dispute, naming it Rehoboth because the LORD has made room for them to be fruitful. Isaac interprets the relief as God’s provision. The verse emphasizes patience and peace rather than victory through retaliation.",
    "refs": "Psalm 18:19; Romans 12:18"
  },
  "Genesis 26:23": {
    "title": "Isaac goes to Beersheba",
    "text": "Isaac travels from there to Beersheba. The place is associated with earlier events in Abraham’s life and will become the setting for God’s reassurance to Isaac. The narrative links the generations through shared locations.",
    "refs": "Genesis 21:31–33; Genesis 26:24"
  },
  "Genesis 26:24": {
    "title": "The LORD appears and reassures Isaac",
    "text": "The LORD appears to Isaac at night and tells him not to fear, for He is the God of Abraham and will bless him and multiply his seed for Abraham’s sake. The verse directly identifies the one LORD as the God of Abraham. The covenant promise continues through Isaac by God’s faithfulness.",
    "refs": "Genesis 15:1; Genesis 17:7"
  },
  "Genesis 26:25": {
    "title": "Isaac builds an altar",
    "text": "Isaac builds an altar, calls on the name of the LORD, pitches his tent, and his servants dig a well. Worship and ordinary work appear together in the verse. Isaac responds to God’s promise through worship and continues to establish his household.",
    "refs": "Genesis 12:7–8; Genesis 21:33"
  },
  "Genesis 26:26": {
    "title": "Abimelech visits Isaac",
    "text": "Abimelech comes from Gerar with friends and Phichol, the captain of his army. The visit begins a new agreement after earlier tension. The following verses explain that Abimelech recognizes the LORD’s presence with Isaac.",
    "refs": "Genesis 21:22; Genesis 26:28"
  },
  "Genesis 26:27": {
    "title": "Isaac asks why they came",
    "text": "Isaac asks why Abimelech’s party has come when they had previously sent him away. His question names the apparent contradiction between past rejection and present visit. The dialogue allows both sides to clarify their intentions.",
    "refs": "Genesis 26:16; Genesis 26:28"
  },
  "Genesis 26:28": {
    "title": "They see the LORD is with Isaac",
    "text": "Abimelech’s party says they clearly see that the LORD is with Isaac and proposes an oath and covenant. The statement attributes Isaac’s success to the LORD. The passage speaks of the one LORD’s presence and blessing, not multiple Gods.",
    "refs": "Genesis 21:22; Genesis 26:24"
  },
  "Genesis 26:29": {
    "title": "A covenant of peace",
    "text": "Abimelech asks that neither side harm the other and refers to having sent Isaac away in peace. The account records a negotiated peace despite earlier conflict. The request is followed by a meal and an oath that formalize the agreement.",
    "refs": "Genesis 21:23–24; Romans 12:18"
  },
  "Genesis 26:30": {
    "title": "A feast is made",
    "text": "Isaac prepares a feast for the visitors, and they eat and drink. The meal accompanies the peace agreement. As in other Genesis encounters, hospitality plays a practical role in settling relations.",
    "refs": "Genesis 18:5–8; Genesis 26:31"
  },
  "Genesis 26:31": {
    "title": "They swear to one another",
    "text": "The parties rise early and swear to one another, then depart in peace. The oath formalizes their agreement. The narrative emphasizes the value of keeping peace through clear commitments.",
    "refs": "Genesis 21:31–32; Joshua 9:15"
  },
  "Genesis 26:32": {
    "title": "The servants report a well",
    "text": "Isaac’s servants report that they have found water. The news arrives on the same day as the covenant’s completion. The provision of water reinforces the theme of God making room for Isaac to live in the land.",
    "refs": "Genesis 26:22; Genesis 26:25"
  },
  "Genesis 26:33": {
    "title": "The well is called Shebah",
    "text": "Isaac names the well Shebah, and the city is called Beersheba. The name connects this episode with Abraham’s earlier covenant and well at Beersheba. The repeated place-name links the generations and their dealings with the LORD.",
    "refs": "Genesis 21:31; Genesis 26:23"
  },
  "Genesis 26:34": {
    "title": "Esau marries Hittite women",
    "text": "Esau marries Judith and Bashemath, daughters of Hittites, when he is forty. The marriages create grief for Isaac and Rebekah in the next verse. The narrative connects family choices with the covenant household’s concerns.",
    "refs": "Genesis 24:3–4; Genesis 26:35"
  },
  "Genesis 26:35": {
    "title": "Esau’s marriages grieve his parents",
    "text": "Esau’s wives are a grief of mind to Isaac and Rebekah. The verse records family sorrow over the marriages. The issue belongs to this family’s covenant context and should be explained through the wider narrative rather than generalized as ethnic prejudice.",
    "refs": "Genesis 27:46; Genesis 28:1–2"
  },
  "Genesis 27:1": {
    "title": "Isaac’s failing sight",
    "text": "Isaac’s physical blindness frames the chapter’s theme of limited human perception. The account shows how family members act from incomplete understanding and competing desires.",
    "refs": [
      "Genesis 27:27–29"
    ]
  },
  "Genesis 27:2": {
    "title": "The uncertainty of life",
    "text": "Isaac recognizes that his death may be near, but the narrative does not say that he knows the exact time. His concern leads him to arrange a blessing for Esau.",
    "refs": [
      "Genesis 27:27–29"
    ]
  },
  "Genesis 27:3": {
    "title": "Prepare the hunt",
    "text": "Isaac asks Esau to hunt and prepare food. The request connects the family blessing with Isaac’s personal appetite and preference.",
    "refs": [
      "Genesis 25:27–28"
    ]
  },
  "Genesis 27:4": {
    "title": "A blessing requested",
    "text": "Isaac intends to bless Esau before he dies. God’s earlier word to Rebekah had said that the elder would serve the younger, creating tension between the divine promise and the family’s plans.",
    "refs": [
      "Genesis 25:23"
    ]
  },
  "Genesis 27:5": {
    "title": "Rebekah overhears",
    "text": "Rebekah hears Isaac’s plan and begins arranging for Jacob to receive the blessing. The text records her actions without presenting deception as a righteous example.",
    "refs": [
      "Genesis 25:23"
    ]
  },
  "Genesis 27:6": {
    "title": "Rebekah tells Jacob",
    "text": "Rebekah repeats Isaac’s words to Jacob. Her knowledge of the promise does not make every method she chooses automatically approved by God.",
    "refs": [
      "Genesis 25:23"
    ]
  },
  "Genesis 27:7": {
    "title": "The words of the blessing",
    "text": "Isaac’s intended blessing includes prosperity and family leadership. In this narrative, a patriarchal blessing carries serious weight within the family’s future.",
    "refs": [
      "Genesis 27:27–29"
    ]
  },
  "Genesis 27:8": {
    "title": "Obey my voice",
    "text": "Rebekah directs Jacob to follow her instructions. The chapter shows how parental favoritism and manipulation have become deeply woven into this household.",
    "refs": [
      "Genesis 25:28"
    ]
  },
  "Genesis 27:9": {
    "title": "Two young goats",
    "text": "Rebekah proposes using two goats to prepare food resembling Isaac’s favorite meal. The plan depends on disguising Jacob’s identity rather than speaking truthfully.",
    "refs": [
      "Genesis 27:14–17"
    ]
  },
  "Genesis 27:10": {
    "title": "Bring it to Isaac",
    "text": "Rebekah intends for Jacob to present the food and receive the blessing. The story distinguishes the promised outcome from the dishonest means used to pursue it.",
    "refs": [
      "Genesis 27:18–29"
    ]
  },
  "Genesis 27:11": {
    "title": "Jacob names the problem",
    "text": "Jacob points out that Esau is hairy and he is smooth. His concern is exposure, not a refusal to participate in the deception.",
    "refs": [
      "Genesis 27:15–16"
    ]
  },
  "Genesis 27:12": {
    "title": "Fear of being discovered",
    "text": "Jacob worries that Isaac will recognize the deception and curse him instead of blessing him. His words reveal that he understands the moral and practical danger of the plan.",
    "refs": [
      "Genesis 27:21–24"
    ]
  },
  "Genesis 27:13": {
    "title": "Rebekah accepts the risk",
    "text": "Rebekah says the curse should fall on her and again tells Jacob to obey. Her confidence does not remove the wrongness or consequences of deception.",
    "refs": [
      "Genesis 27:18–29"
    ]
  },
  "Genesis 27:14": {
    "title": "The plan is carried out",
    "text": "Jacob brings the goats, and Rebekah prepares the food. The narrative reports the action plainly rather than asking readers to treat it as a model of faithful conduct.",
    "refs": [
      "Genesis 27:15–17"
    ]
  },
  "Genesis 27:15": {
    "title": "Esau’s clothing",
    "text": "Rebekah dresses Jacob in Esau’s best garments. The disguise uses smell and touch as well as words to mislead Isaac.",
    "refs": [
      "Genesis 27:22–27"
    ]
  },
  "Genesis 27:16": {
    "title": "Goatskins as a disguise",
    "text": "Rebekah covers Jacob’s hands and neck with goatskins. The elaborate disguise shows how deliberate the deception has become.",
    "refs": [
      "Genesis 27:21–23"
    ]
  },
  "Genesis 27:17": {
    "title": "Food and bread",
    "text": "Rebekah gives Jacob the prepared meal. The meal becomes part of a false presentation intended to secure the blessing.",
    "refs": [
      "Genesis 27:18–29"
    ]
  },
  "Genesis 27:18": {
    "title": "Jacob approaches Isaac",
    "text": "Jacob calls himself Isaac’s son and claims to be Esau. The false identification is central to the conflict that follows.",
    "refs": [
      "Genesis 27:19"
    ]
  },
  "Genesis 27:19": {
    "title": "A direct falsehood",
    "text": "Jacob claims that he has done what Isaac asked and urges him to eat and bless him. The account does not conceal that Jacob lies to his father.",
    "refs": [
      "Genesis 27:18–24"
    ]
  },
  "Genesis 27:20": {
    "title": "Invoking the LORD",
    "text": "When Isaac asks how the hunt succeeded so quickly, Jacob says the LORD brought it to him. Jacob uses God’s name to support a deceptive claim, a serious misuse of religious language.",
    "refs": [
      "Exodus 20:7"
    ]
  },
  "Genesis 27:21": {
    "title": "Isaac tests the voice",
    "text": "Isaac asks Jacob to come near so he can feel him. Isaac senses uncertainty because the voice sounds like Jacob even though the disguise suggests Esau.",
    "refs": [
      "Genesis 27:22"
    ]
  },
  "Genesis 27:22": {
    "title": "Voice and hands",
    "text": "Isaac identifies the voice as Jacob’s but the hands as Esau’s. The scene emphasizes the limits of relying on outward evidence alone.",
    "refs": [
      "1 Samuel 16:7"
    ]
  },
  "Genesis 27:23": {
    "title": "Isaac does not recognize him",
    "text": "Isaac fails to identify Jacob because the hands feel hairy. The narrator makes clear that the deception succeeds through the disguise.",
    "refs": [
      "Genesis 27:15–16"
    ]
  },
  "Genesis 27:24": {
    "title": "The question of identity",
    "text": "Isaac asks again whether Jacob is Esau, and Jacob answers falsely. Repeated questioning makes the deception more deliberate, not less serious.",
    "refs": [
      "Genesis 27:18–20"
    ]
  },
  "Genesis 27:25": {
    "title": "The meal is accepted",
    "text": "Isaac eats and drinks what Jacob brings. The meal prepares the way for the blessing, while Isaac remains unaware of the true identity of the son before him.",
    "refs": [
      "Genesis 27:27–29"
    ]
  },
  "Genesis 27:26": {
    "title": "A kiss before the blessing",
    "text": "Isaac asks Jacob to come near and kiss him. This ordinary family gesture also allows Isaac to smell the garments used in the disguise.",
    "refs": [
      "Genesis 27:27"
    ]
  },
  "Genesis 27:27": {
    "title": "The smell of the field",
    "text": "Isaac smells Esau’s garments and believes the disguise. The field imagery introduces the blessing’s agricultural abundance and echoes Esau’s outdoor life.",
    "refs": [
      "Genesis 27:28–29"
    ]
  },
  "Genesis 27:28": {
    "title": "Dew, earth, grain, and wine",
    "text": "Isaac blesses Jacob with agricultural plenty. These words describe material prosperity in the covenant setting; they are not a guarantee that every faithful person will be wealthy.",
    "refs": [
      "Deuteronomy 7:13"
    ]
  },
  "Genesis 27:29": {
    "title": "Rule and family blessing",
    "text": "Isaac’s words place Jacob in a position of authority among peoples and his brothers. The blessing echoes God’s earlier promise concerning Abraham’s family, yet the deception in this chapter remains part of the story’s painful human setting.",
    "refs": [
      "Genesis 12:3",
      "Genesis 25:23"
    ]
  },
  "Genesis 27:30": {
    "title": "Jacob leaves; Esau arrives",
    "text": "Jacob has scarcely left when Esau returns. The close timing exposes the deception and brings its consequences into the open.",
    "refs": [
      "Genesis 27:31–35"
    ]
  },
  "Genesis 27:31": {
    "title": "Esau brings his meal",
    "text": "Esau prepares food and asks his father to eat and bless him. He expects to receive the blessing Isaac had promised him.",
    "refs": [
      "Genesis 27:4"
    ]
  },
  "Genesis 27:32": {
    "title": "Isaac asks who he is",
    "text": "Isaac asks Esau to identify himself. The question reveals that the father now recognizes the grave mistake made through the disguise.",
    "refs": [
      "Genesis 27:18–24"
    ]
  },
  "Genesis 27:33": {
    "title": "Isaac trembles greatly",
    "text": "Isaac reacts with intense trembling when he realizes what happened. He says Jacob has received the blessing and does not simply repeat the ceremony for Esau.",
    "refs": [
      "Hebrews 11:20"
    ]
  },
  "Genesis 27:34": {
    "title": "Esau cries out",
    "text": "Esau responds with a great and bitter cry and begs for a blessing. The scene records the anguish caused by the family’s rivalry and deception.",
    "refs": [
      "Genesis 27:38"
    ]
  },
  "Genesis 27:35": {
    "title": "The deceit is named",
    "text": "Isaac says Jacob came with deceit and took the blessing. The biblical account openly names the deception rather than excusing it.",
    "refs": [
      "Genesis 27:18–24"
    ]
  },
  "Genesis 27:36": {
    "title": "Esau’s accusation",
    "text": "Esau points to Jacob’s name and earlier actions as evidence of rivalry. The chapter presents a fractured family in which each person has contributed to the conflict.",
    "refs": [
      "Genesis 25:29–34"
    ]
  },
  "Genesis 27:37": {
    "title": "The blessing cannot simply be repeated",
    "text": "Isaac explains that Jacob has been set over Esau and asks what remains to give him. The text portrays the blessing as consequential and binding within this family’s world.",
    "refs": [
      "Genesis 27:28–29"
    ]
  },
  "Genesis 27:38": {
    "title": "Esau weeps for a blessing",
    "text": "Esau asks whether Isaac has only one blessing and weeps aloud. His grief is real, though the earlier account also describes his disregard for his birthright.",
    "refs": [
      "Genesis 25:29–34",
      "Hebrews 12:16–17"
    ]
  },
  "Genesis 27:39": {
    "title": "A different future foretold",
    "text": "Isaac’s words describe a life marked by the earth’s resources and the sword. This is a prophetic description of Esau’s line, not a general teaching that violence is righteous.",
    "refs": [
      "Genesis 36:1–8"
    ]
  },
  "Genesis 27:40": {
    "title": "Serving and breaking free",
    "text": "Isaac says Esau will serve his brother but eventually break his yoke. The verse anticipates conflict and shifting political relationships between their descendants.",
    "refs": [
      "2 Kings 8:20–22"
    ]
  },
  "Genesis 27:41": {
    "title": "Esau’s hatred",
    "text": "Esau resolves to kill Jacob after Isaac dies. His bitterness shows how the stolen blessing deepens the family’s danger rather than bringing peace.",
    "refs": [
      "Genesis 4:5–8"
    ]
  },
  "Genesis 27:42": {
    "title": "Rebekah hears the threat",
    "text": "Rebekah learns of Esau’s plan and sends for Jacob. The deception now has immediate consequences for Jacob’s safety and the family’s future.",
    "refs": [
      "Genesis 27:43–45"
    ]
  },
  "Genesis 27:43": {
    "title": "Flee to Laban",
    "text": "Rebekah tells Jacob to flee to her brother Laban in Haran. Jacob must leave the household and the land because of the conflict his actions helped create.",
    "refs": [
      "Genesis 28:1–5"
    ]
  },
  "Genesis 27:44": {
    "title": "Stay a little while",
    "text": "Rebekah expects Jacob to remain with Laban briefly until Esau’s anger subsides. The following events show that this separation lasts far longer than the plan suggests.",
    "refs": [
      "Genesis 31:38–41"
    ]
  },
  "Genesis 27:45": {
    "title": "Rebekah fears losing both sons",
    "text": "Rebekah fears that Esau may kill Jacob and that she could lose both sons in one day. The chapter closes this part of the story with grief and fear rather than triumph.",
    "refs": [
      "Genesis 27:41–43"
    ]
  },
  "Genesis 27:46": {
    "title": "A reason given to Isaac",
    "text": "Rebekah complains about the Hittite women and says Jacob’s marriage to one would make life unbearable. This prepares the way for Isaac to send Jacob to find a wife among their relatives.",
    "refs": [
      "Genesis 26:34–35",
      "Genesis 28:1–2"
    ]
  },
  "Genesis 28:1": {
    "title": "Isaac blesses Jacob openly",
    "text": "Isaac now knowingly blesses Jacob and commands him not to marry a Canaanite woman. The blessing is no longer obtained through disguise; Isaac deliberately sends Jacob forward.",
    "refs": [
      "Genesis 27:27–29"
    ]
  },
  "Genesis 28:2": {
    "title": "Go to Padan-aram",
    "text": "Isaac directs Jacob to Bethuel’s family and to take a wife from Laban’s daughters. The instruction continues the family’s concern that marriage should remain within their kinship and covenant setting.",
    "refs": [
      "Genesis 24:3–4"
    ]
  },
  "Genesis 28:3": {
    "title": "God Almighty bless thee",
    "text": "Isaac invokes God Almighty, El Shaddai, asking for fruitfulness and a multitude of descendants. The language recalls the covenant blessing given to Abraham and Isaac.",
    "refs": [
      "Genesis 17:1–6",
      "Genesis 26:3–4"
    ]
  },
  "Genesis 28:4": {
    "title": "The blessing of Abraham",
    "text": "Isaac asks that Jacob receive Abraham’s blessing and possess the land where he is a stranger. The covenant promise continues through Jacob’s line because of God’s purpose, not because Jacob’s deception was itself righteous.",
    "refs": [
      "Genesis 12:1–3",
      "Genesis 17:7–8"
    ]
  },
  "Genesis 28:5": {
    "title": "Jacob departs for Haran",
    "text": "Jacob leaves for Padan-aram and Laban. The family history moves into a new stage in which Jacob will experience deception and hardship himself.",
    "refs": [
      "Genesis 29:20–27"
    ]
  },
  "Genesis 28:6": {
    "title": "Esau observes the marriage decision",
    "text": "Esau sees that Isaac has blessed Jacob and sent him away to find a wife from their relatives. He recognizes that his parents disapprove of Canaanite marriages.",
    "refs": [
      "Genesis 26:34–35"
    ]
  },
  "Genesis 28:7": {
    "title": "Jacob obeys his parents",
    "text": "Jacob follows Isaac and Rebekah’s instruction and travels toward Padan-aram. This contrasts with the earlier deception: in this matter he acts in accordance with their stated direction.",
    "refs": [
      "Genesis 28:1–5"
    ]
  },
  "Genesis 28:8": {
    "title": "Esau understands his parents’ displeasure",
    "text": "Esau realizes that the Canaanite women are displeasing to Isaac. The verse describes his recognition of family expectations, not necessarily a full change of heart.",
    "refs": [
      "Genesis 26:34–35"
    ]
  },
  "Genesis 28:9": {
    "title": "Esau marries into Ishmael’s family",
    "text": "Esau takes another wife from Ishmael’s family. The text reports the choice as a response to the family situation, but does not say it reverses the earlier conflict or restores the birthright.",
    "refs": [
      "Genesis 25:12–18",
      "Genesis 27:36"
    ]
  },
  "Genesis 28:10": {
    "title": "Jacob leaves Beersheba",
    "text": "Jacob travels from Beersheba toward Haran. His journey begins a period of vulnerability away from home, during which God will reaffirm the covenant promise.",
    "refs": [
      "Genesis 28:15"
    ]
  },
  "Genesis 28:11": {
    "title": "A stone for a pillow",
    "text": "Jacob stops for the night, uses a stone for a pillow, and lies down. The simple setting underscores that this revelation comes to a traveler without outward grandeur.",
    "refs": [
      "Genesis 28:16–17"
    ]
  },
  "Genesis 28:12": {
    "title": "The ladder and the angels",
    "text": "Jacob dreams of a ladder or stairway reaching from earth to heaven, with angels ascending and descending. The image portrays communication between heaven and earth under God’s authority; it does not by itself define multiple divine persons.",
    "refs": [
      "John 1:51"
    ]
  },
  "Genesis 28:13": {
    "title": "The LORD identifies Himself",
    "text": "The LORD stands above or beside the scene and identifies Himself as the God of Abraham and Isaac. The speaker claims the covenant identity and promises the land to Jacob and his descendants.",
    "refs": [
      "Exodus 3:6",
      "Genesis 26:3–4"
    ]
  },
  "Genesis 28:14": {
    "title": "Descendants and blessing to the nations",
    "text": "God promises Jacob descendants like the dust of the earth and says all families of the earth will be blessed through him and his seed. The promise continues the covenant first given to Abraham and later understood in the wider biblical story as reaching the nations through Christ.",
    "refs": [
      "Genesis 12:3",
      "Galatians 3:8, 16"
    ]
  },
  "Genesis 28:15": {
    "title": "God promises His presence",
    "text": "God promises to be with Jacob, keep him wherever he goes, bring him back to the land, and not leave him until His word is fulfilled. The assurance rests on God’s faithfulness, not Jacob’s perfection.",
    "refs": [
      "Deuteronomy 31:6",
      "Hebrews 13:5"
    ]
  },
  "Genesis 28:16": {
    "title": "The LORD was in this place",
    "text": "Jacob awakens and recognizes that the LORD was present though he had not realized it. The verse emphasizes God’s presence and Jacob’s newly awakened awareness, not that God had been absent before the dream.",
    "refs": [
      "Psalm 139:7–10"
    ]
  },
  "Genesis 28:17": {
    "title": "The house of God and gate of heaven",
    "text": "Jacob responds with awe and calls the place dreadful in the sense of awesome or fear-inspiring. His description reflects the holiness of the encounter and the significance of God’s revelation.",
    "refs": [
      "Exodus 3:5"
    ]
  },
  "Genesis 28:18": {
    "title": "The stone becomes a pillar",
    "text": "Jacob sets up the stone as a memorial and pours oil on it. The act marks the place where he received the promise; the verse does not establish a general command to worship stones or objects.",
    "refs": [
      "Genesis 31:13"
    ]
  },
  "Genesis 28:19": {
    "title": "Bethel, the house of God",
    "text": "Jacob names the place Bethel, though it had formerly been called Luz. The name preserves the memory of the encounter and the promise given there.",
    "refs": [
      "Genesis 35:6–7"
    ]
  },
  "Genesis 28:20": {
    "title": "Jacob makes a vow",
    "text": "Jacob vows that if God will be with him, keep him, provide food and clothing, and bring him home safely, the LORD will be his God. The wording reflects Jacob’s developing faith and should be read alongside God’s prior promise in verse 15.",
    "refs": [
      "Genesis 28:15"
    ]
  },
  "Genesis 28:21": {
    "title": "The LORD will be my God",
    "text": "Jacob connects safe return with his commitment to the LORD. His vow shows a response to God’s revelation, though the passage does not require readers to conclude that God’s covenant promise depended on Jacob bargaining for it.",
    "refs": [
      "Genesis 28:13–15"
    ]
  },
  "Genesis 28:22": {
    "title": "A pillar and a tenth",
    "text": "Jacob declares that the stone will be God’s house and promises to give God a tenth of what He provides. This is Jacob’s personal vow in the narrative; later biblical teaching about giving should be studied in its own covenant context.",
    "refs": [
      "Genesis 14:20",
      "Leviticus 27:30"
    ]
  },
  "Genesis 29:1": {
    "title": "Jacob reaches the eastern land",
    "text": "Jacob continues his journey and arrives in the region of the people of the east. The narrative moves from the vision at Bethel to the practical events through which Jacob’s family will grow.",
    "refs": [
      "Genesis 28:10–15"
    ]
  },
  "Genesis 29:2": {
    "title": "A well and flocks",
    "text": "Jacob sees a well with flocks gathered nearby. The scene introduces the shepherding community and sets up his meeting with Rachel.",
    "refs": [
      "Genesis 24:11–15"
    ]
  },
  "Genesis 29:3": {
    "title": "The custom at the well",
    "text": "The shepherds explain that they wait until the flocks are gathered before rolling away the stone. Their local practice provides the setting for Jacob’s conversation.",
    "refs": [
      "Genesis 29:7–8"
    ]
  },
  "Genesis 29:4": {
    "title": "Jacob asks about their home",
    "text": "Jacob asks the shepherds where they are from, and they answer that they are from Haran. His question confirms that he has reached the region he was seeking.",
    "refs": [
      "Genesis 28:2"
    ]
  },
  "Genesis 29:5": {
    "title": "They know Laban",
    "text": "Jacob asks whether they know Laban, the son of Nahor’s family. The answer links Jacob’s journey to the relatives his parents directed him to find.",
    "refs": [
      "Genesis 24:29"
    ]
  },
  "Genesis 29:6": {
    "title": "Rachel is approaching",
    "text": "The shepherds tell Jacob that Laban’s daughter Rachel is coming with the sheep. God’s providence unfolds through ordinary encounters, though the text does not describe every detail as a separate miracle.",
    "refs": [
      "Genesis 24:12–27"
    ]
  },
  "Genesis 29:7": {
    "title": "Jacob urges them to water the flock",
    "text": "Jacob points out that it is still daytime and suggests watering the sheep before they lie down. His words show his practical knowledge of the work of shepherds.",
    "refs": [
      "Genesis 31:38–40"
    ]
  },
  "Genesis 29:8": {
    "title": "The stone must be moved together",
    "text": "The shepherds explain that they cannot water the flocks until all have gathered and the stone is rolled away. Their answer clarifies the custom Jacob has observed.",
    "refs": [
      "Genesis 29:2–3"
    ]
  },
  "Genesis 29:9": {
    "title": "Rachel comes with her father’s sheep",
    "text": "Rachel arrives while the conversation continues. She is identified as a shepherdess, and the family connection soon becomes clear.",
    "refs": [
      "Genesis 29:10"
    ]
  },
  "Genesis 29:10": {
    "title": "Jacob helps Rachel",
    "text": "When Jacob sees Rachel and Laban’s flock, he rolls away the stone and waters the sheep. His action is an act of assistance and marks the beginning of their relationship.",
    "refs": [
      "Genesis 24:17–20"
    ]
  },
  "Genesis 29:11": {
    "title": "Jacob weeps and kisses Rachel",
    "text": "Jacob weeps aloud and kisses Rachel in greeting, then tells her that he is her father’s relative. The emotional response reflects the relief and significance of reaching his mother’s family.",
    "refs": [
      "Genesis 28:15"
    ]
  },
  "Genesis 29:12": {
    "title": "Rachel runs to tell Laban",
    "text": "Rachel reports Jacob’s family connection, and Laban comes to meet him. The story parallels earlier family encounters in which a traveler is welcomed by relatives.",
    "refs": [
      "Genesis 24:29–31"
    ]
  },
  "Genesis 29:13": {
    "title": "Laban welcomes Jacob",
    "text": "Laban embraces Jacob, brings him home, and hears his account. The warm welcome later becomes complicated by Laban’s own deceptive treatment of Jacob.",
    "refs": [
      "Genesis 29:25",
      "Genesis 31:7"
    ]
  },
  "Genesis 29:14": {
    "title": "A month in the household",
    "text": "Laban acknowledges that Jacob is his relative and lets him stay for a month. The family relationship becomes the basis for the employment arrangement that follows.",
    "refs": [
      "Genesis 29:15"
    ]
  },
  "Genesis 29:15": {
    "title": "Work and wages",
    "text": "Laban asks Jacob whether he should serve without wages because they are relatives. The question introduces the issue of fair compensation and the terms of Jacob’s work.",
    "refs": [
      "Genesis 31:7"
    ]
  },
  "Genesis 29:16": {
    "title": "Leah and Rachel",
    "text": "Laban has two daughters, Leah and Rachel. Their contrasting descriptions introduce the sisters and the family conflict that develops around marriage and favoritism.",
    "refs": [
      "Genesis 29:17–30"
    ]
  },
  "Genesis 29:17": {
    "title": "The sisters’ descriptions",
    "text": "The verse describes Leah’s eyes and Rachel’s appearance. These descriptions are part of the narrator’s account and should not be used to judge a person’s worth by physical beauty.",
    "refs": [
      "1 Samuel 16:7"
    ]
  },
  "Genesis 29:18": {
    "title": "Jacob loves Rachel",
    "text": "Jacob offers seven years of service because he loves Rachel. The passage presents his willingness to work as the basis of the marriage agreement.",
    "refs": [
      "Genesis 29:20"
    ]
  },
  "Genesis 29:19": {
    "title": "Laban agrees",
    "text": "Laban says it is better to give Rachel to Jacob than to another man and invites him to stay. The agreement sounds straightforward, but Laban later changes the terms through deception.",
    "refs": [
      "Genesis 29:25–27"
    ]
  },
  "Genesis 29:20": {
    "title": "Seven years seem like days",
    "text": "Jacob’s love makes the seven years seem short to him. The verse expresses his devotion without implying that love makes the later deception harmless.",
    "refs": [
      "Genesis 29:18"
    ]
  },
  "Genesis 29:21": {
    "title": "Jacob asks for his wife",
    "text": "After the agreed period, Jacob asks Laban to give him Rachel so they may marry. He believes he has fulfilled the terms of their agreement.",
    "refs": [
      "Genesis 29:18–20"
    ]
  },
  "Genesis 29:22": {
    "title": "The wedding feast",
    "text": "Laban gathers the people of the place and holds a feast. The public celebration sets the stage for the deception that follows that night.",
    "refs": [
      "Genesis 29:23–25"
    ]
  },
  "Genesis 29:23": {
    "title": "Leah is brought to Jacob",
    "text": "Laban brings Leah to Jacob, and Jacob unknowingly lies with her. The narrative reports the deception directly, creating a painful reversal of Jacob’s own earlier deceit.",
    "refs": [
      "Genesis 27:18–29"
    ]
  },
  "Genesis 29:24": {
    "title": "Zilpah given to Leah",
    "text": "Laban gives his servant Zilpah to Leah. This detail becomes relevant to the later account of the children born in Jacob’s household.",
    "refs": [
      "Genesis 30:9–13"
    ]
  },
  "Genesis 29:25": {
    "title": "Jacob discovers the deception",
    "text": "In the morning Jacob realizes that Laban has given him Leah instead of Rachel. Jacob’s angry question confronts him with a deception resembling the one he used against Isaac.",
    "refs": [
      "Genesis 27:18–29"
    ]
  },
  "Genesis 29:26": {
    "title": "The local custom explained",
    "text": "Laban claims that the younger daughter cannot be married before the elder. The text records his explanation, but it does not say that this custom justified his failure to disclose the arrangement beforehand.",
    "refs": [
      "Genesis 29:21–25"
    ]
  },
  "Genesis 29:27": {
    "title": "Another seven years",
    "text": "Laban tells Jacob to complete Leah’s wedding week and promises Rachel in return for another seven years of service. Jacob is placed in a difficult arrangement, and Laban benefits from his labor.",
    "refs": [
      "Genesis 31:41"
    ]
  },
  "Genesis 29:28": {
    "title": "Jacob marries Rachel",
    "text": "Jacob agrees and receives Rachel as wife after the wedding week. The narrative describes a household arrangement shaped by Laban’s deception and the customs of the time.",
    "refs": [
      "Genesis 29:25–27"
    ]
  },
  "Genesis 29:29": {
    "title": "Bilhah given to Rachel",
    "text": "Laban gives Bilhah to Rachel as her servant. Bilhah later bears children to Jacob within the household’s complicated struggle over fertility.",
    "refs": [
      "Genesis 30:3–8"
    ]
  },
  "Genesis 29:30": {
    "title": "Jacob’s love and divided household",
    "text": "Jacob loves Rachel more than Leah and serves Laban another seven years. The favoritism repeats a painful pattern already present in Isaac and Rebekah’s family.",
    "refs": [
      "Genesis 25:28",
      "Genesis 27:1–17"
    ]
  },
  "Genesis 29:31": {
    "title": "The LORD sees Leah’s affliction",
    "text": "The LORD sees that Leah is less loved and enables her to conceive, while Rachel remains barren at this point. God’s attention to Leah’s distress is explicit, though the verse does not say that her worth depends on childbearing.",
    "refs": [
      "Psalm 34:18"
    ]
  },
  "Genesis 29:32": {
    "title": "Reuben is born",
    "text": "Leah names her first son Reuben and connects the name with the LORD’s seeing her affliction and her hope of being loved. Her words reveal the emotional pain within the marriage.",
    "refs": [
      "Genesis 35:23"
    ]
  },
  "Genesis 29:33": {
    "title": "Simeon is born",
    "text": "Leah names her second son Simeon because she believes the LORD has heard that she is unloved. The verse portrays God as attentive to her suffering.",
    "refs": [
      "Exodus 3:7"
    ]
  },
  "Genesis 29:34": {
    "title": "Levi is born",
    "text": "Leah names her third son Levi and hopes her husband will become attached to her. Her words show that the birth of children has not resolved the relationship’s lack of affection.",
    "refs": [
      "Genesis 49:5–7"
    ]
  },
  "Genesis 29:35": {
    "title": "Judah is born",
    "text": "Leah names her fourth son Judah and says she will praise the LORD. Judah’s line later becomes significant in Israel’s history and in the New Testament’s account of Jesus’ ancestry.",
    "refs": [
      "Genesis 49:8–10",
      "Matthew 1:2–3"
    ]
  },
  "Genesis 30:1": {
    "title": "Rachel’s anguish over barrenness",
    "text": "Rachel envies Leah and asks Jacob for children, expressing her distress intensely. The chapter presents infertility as a source of deep family pain, not as proof that God has rejected someone.",
    "refs": [
      "1 Samuel 1:10–11"
    ]
  },
  "Genesis 30:2": {
    "title": "Jacob points to God’s sovereignty",
    "text": "Jacob responds that he is not in God’s place, who has withheld children from Rachel. His words acknowledge that fertility is beyond his control, though his anger does not ease Rachel’s suffering.",
    "refs": [
      "Genesis 29:31"
    ]
  },
  "Genesis 30:3": {
    "title": "Rachel offers Bilhah",
    "text": "Rachel gives Bilhah to Jacob so she may have children through her servant. This reflects a custom in the ancient household, but the resulting competition brings further strain.",
    "refs": [
      "Genesis 16:1–4"
    ]
  },
  "Genesis 30:4": {
    "title": "Bilhah becomes Jacob’s wife",
    "text": "Rachel gives Bilhah to Jacob, and he goes in to her. The account records the household practice without presenting it as a universal command for marriage.",
    "refs": [
      "Genesis 30:3"
    ]
  },
  "Genesis 30:5": {
    "title": "Dan is born",
    "text": "Bilhah bears Jacob a son. The child’s birth becomes part of the rivalry between Leah and Rachel over status and children.",
    "refs": [
      "Genesis 30:6"
    ]
  },
  "Genesis 30:6": {
    "title": "Rachel names Dan",
    "text": "Rachel names the child Dan and says God has judged her and heard her voice. Her words show how she interprets the birth within her distress and hope.",
    "refs": [
      "Genesis 30:1–2"
    ]
  },
  "Genesis 30:7": {
    "title": "Bilhah conceives again",
    "text": "Bilhah bears a second son to Jacob. The family grows, but the narrative’s pattern of rivalry continues.",
    "refs": [
      "Genesis 30:8"
    ]
  },
  "Genesis 30:8": {
    "title": "Naphtali and the struggle",
    "text": "Rachel names the child Naphtali and describes her struggle with her sister. Her words reveal that the competition between the sisters has become central to the household.",
    "refs": [
      "Genesis 29:31–35"
    ]
  },
  "Genesis 30:9": {
    "title": "Leah gives Zilpah to Jacob",
    "text": "When Leah stops bearing children for a time, she gives Zilpah to Jacob. The household’s efforts to secure children through servants intensify the competition rather than bringing peace.",
    "refs": [
      "Genesis 30:3–4"
    ]
  },
  "Genesis 30:10": {
    "title": "Zilpah bears a son",
    "text": "Zilpah bears Jacob a son. The verse continues the account of the children born through the two sisters’ servants.",
    "refs": [
      "Genesis 30:11–13"
    ]
  },
  "Genesis 30:11": {
    "title": "Gad is born",
    "text": "Leah names the child Gad, a name associated with good fortune or a troop. The naming reflects Leah’s interpretation of the event and the family’s hopes.",
    "refs": [
      "Genesis 35:26"
    ]
  },
  "Genesis 30:12": {
    "title": "Zilpah bears another son",
    "text": "Zilpah bears Jacob a second son. The growing family later becomes the foundation for the tribes of Israel.",
    "refs": [
      "Genesis 35:23–26"
    ]
  },
  "Genesis 30:13": {
    "title": "Asher and Leah’s happiness",
    "text": "Leah names the child Asher and says the daughters will call her blessed. Her words express joy, while the broader narrative still shows tension and competition in the household.",
    "refs": [
      "Genesis 49:20"
    ]
  },
  "Genesis 30:14": {
    "title": "Mandrakes in the field",
    "text": "Reuben finds mandrakes and brings them to Leah. The plant was associated with fertility in the ancient world, but the narrative does not teach that it can guarantee conception.",
    "refs": [
      "Song of Solomon 7:13"
    ]
  },
  "Genesis 30:15": {
    "title": "The sisters bargain",
    "text": "Rachel asks for mandrakes, and Leah answers bitterly about Rachel taking Jacob’s affection. Their exchange exposes resentment and the way affection has become a contested resource.",
    "refs": [
      "Genesis 29:30–31"
    ]
  },
  "Genesis 30:16": {
    "title": "Leah meets Jacob",
    "text": "Leah tells Jacob she has hired him with the mandrakes, and he goes in to her that night. The scene depicts a troubled marriage shaped by bargaining and rivalry.",
    "refs": [
      "Genesis 30:14–15"
    ]
  },
  "Genesis 30:17": {
    "title": "God hears Leah",
    "text": "God hears Leah, and she conceives again. The narrative attributes the conception to God’s action rather than to the mandrakes Rachel desired.",
    "refs": [
      "Genesis 29:31–35"
    ]
  },
  "Genesis 30:18": {
    "title": "Issachar is born",
    "text": "Leah names her son Issachar and connects the name with the arrangement she made. Her explanation reflects the complicated human negotiations surrounding the births.",
    "refs": [
      "Genesis 35:23"
    ]
  },
  "Genesis 30:19": {
    "title": "Leah conceives again",
    "text": "Leah bears Jacob a sixth son. The account records the growth of Jacob’s family and the developing tribal ancestry of Israel.",
    "refs": [
      "Genesis 35:23"
    ]
  },
  "Genesis 30:20": {
    "title": "Zebulun and Leah’s hope",
    "text": "Leah names the child Zebulun and hopes Jacob will honor her because she has borne him six sons. Her hope reveals that the struggle for her husband’s affection remains unresolved.",
    "refs": [
      "Genesis 49:13"
    ]
  },
  "Genesis 30:21": {
    "title": "Dinah is born",
    "text": "Leah later bears a daughter named Dinah. The verse briefly records her birth before the narrative turns back to Jacob’s departure and the conflict involving Laban.",
    "refs": [
      "Genesis 34:1"
    ]
  },
  "Genesis 30:22": {
    "title": "God remembers Rachel",
    "text": "God remembers Rachel, hears her, and opens her womb. “Remembered” describes God acting faithfully toward her; it does not mean that He had literally forgotten her.",
    "refs": [
      "Genesis 8:1",
      "1 Samuel 1:19"
    ]
  },
  "Genesis 30:23": {
    "title": "Rachel’s reproach removed",
    "text": "Rachel conceives and bears a son, saying God has taken away her reproach. The verse presents the birth as an answer to her long distress, without teaching that childlessness is shameful in God’s sight.",
    "refs": [
      "Luke 1:25"
    ]
  },
  "Genesis 30:24": {
    "title": "Joseph’s name and prayer",
    "text": "Rachel names her son Joseph and asks that the LORD add another son. Joseph’s name expresses gratitude and continued hope, and his later story becomes central to the survival of Jacob’s family.",
    "refs": [
      "Genesis 37:2–4"
    ]
  },
  "Genesis 30:25": {
    "title": "Jacob asks to return home",
    "text": "After Joseph’s birth, Jacob asks Laban to let him return to his own place and country. His request begins the transition from years of service toward the promised homeland.",
    "refs": [
      "Genesis 28:15"
    ]
  },
  "Genesis 30:26": {
    "title": "Jacob names his years of service",
    "text": "Jacob asks to take his wives and children, for whom he served Laban. He reminds Laban that his labor has built the household and that he now seeks to provide for his own family.",
    "refs": [
      "Genesis 29:18–30"
    ]
  },
  "Genesis 30:27": {
    "title": "Laban acknowledges God’s blessing",
    "text": "Laban says he has learned by experience that the LORD has blessed him because of Jacob. Even a person outside Jacob’s immediate household recognizes that God’s favor has accompanied Jacob’s work.",
    "refs": [
      "Genesis 30:30"
    ]
  },
  "Genesis 30:28": {
    "title": "Laban offers wages",
    "text": "Laban asks Jacob to name his wages. The negotiation follows years in which Laban changed the terms of their agreement, so the request must be read in that history.",
    "refs": [
      "Genesis 31:7"
    ]
  },
  "Genesis 30:29": {
    "title": "Jacob describes his service",
    "text": "Jacob explains how he has cared for Laban’s livestock and how the flock has fared under his supervision. He presents the record of his work as the basis for fair compensation.",
    "refs": [
      "Genesis 31:38–40"
    ]
  },
  "Genesis 30:30": {
    "title": "The LORD has blessed Laban",
    "text": "Jacob notes that Laban’s possessions grew during his service and says the LORD blessed Laban through him. The verse emphasizes God’s providence in work and provision.",
    "refs": [
      "Genesis 12:3"
    ]
  },
  "Genesis 30:31": {
    "title": "Jacob proposes a wage",
    "text": "Jacob says he will continue tending the flock if Laban agrees to a specific arrangement. He seeks a measurable wage rather than another vague promise.",
    "refs": [
      "Genesis 30:32–33"
    ]
  },
  "Genesis 30:32": {
    "title": "Marked animals as wages",
    "text": "Jacob proposes receiving the speckled, spotted, and dark-colored animals as his wages. The agreement makes the division visible and gives both men a way to identify Jacob’s portion.",
    "refs": [
      "Genesis 30:33"
    ]
  },
  "Genesis 30:33": {
    "title": "A transparent agreement",
    "text": "Jacob says his honesty can be checked by examining the animals. The verse highlights accountability in a setting where trust between Jacob and Laban has been repeatedly damaged.",
    "refs": [
      "Genesis 31:7"
    ]
  },
  "Genesis 30:34": {
    "title": "Laban agrees",
    "text": "Laban accepts the proposed arrangement. The following verses reveal that he still acts in ways that complicate the agreement.",
    "refs": [
      "Genesis 30:35–36"
    ]
  },
  "Genesis 30:35": {
    "title": "Laban removes the marked animals",
    "text": "Laban separates many of the animals that would qualify as Jacob’s wages and gives them to his sons. His action undermines the fairness of the agreement he just accepted.",
    "refs": [
      "Genesis 31:7"
    ]
  },
  "Genesis 30:36": {
    "title": "Distance between the flocks",
    "text": "Laban places a three-day journey between his flock and Jacob’s care. The arrangement limits Jacob’s access to the animals and shows the continuing distrust between them.",
    "refs": [
      "Genesis 31:41"
    ]
  },
  "Genesis 30:37": {
    "title": "Jacob uses rods",
    "text": "Jacob takes fresh rods and peels them to expose white streaks. The passage describes an ancient husbandry practice; it should not be turned into a universal biological rule or a magical technique.",
    "refs": [
      "Genesis 30:38–43"
    ]
  },
  "Genesis 30:38": {
    "title": "The rods at the watering troughs",
    "text": "Jacob places the rods where the animals mate while they drink. The narrative describes his method, while the later account credits God with intervening in the dispute over wages.",
    "refs": [
      "Genesis 31:10–12"
    ]
  },
  "Genesis 30:39": {
    "title": "The animals produce marked young",
    "text": "The flock brings forth streaked, speckled, and spotted young. The story reports the outcome but does not require readers to conclude that the rods themselves caused it.",
    "refs": [
      "Genesis 31:10–12"
    ]
  },
  "Genesis 30:40": {
    "title": "Jacob separates the flocks",
    "text": "Jacob separates the animals and manages the flocks so that his portion is distinct. The verse records his practical work in caring for the growing herd.",
    "refs": [
      "Genesis 30:32–33"
    ]
  },
  "Genesis 30:41": {
    "title": "Selective breeding practices",
    "text": "Jacob places the rods before the stronger animals when they mate. The text details his strategy but later reveals that God’s intervention, not a guaranteed effect of the rods, is central to the outcome.",
    "refs": [
      "Genesis 31:10–12"
    ]
  },
  "Genesis 30:42": {
    "title": "The weaker animals excluded",
    "text": "Jacob does not use the same method with the weaker animals, so Laban’s portion is weaker and Jacob’s stronger. The account describes how Jacob’s wealth increases amid a contested wage arrangement.",
    "refs": [
      "Genesis 31:7–9"
    ]
  },
  "Genesis 30:43": {
    "title": "Jacob’s household and wealth grow",
    "text": "Jacob becomes very prosperous, with large flocks, servants, camels, and donkeys. The next chapter explains Jacob’s understanding that God saw Laban’s unfairness and protected him.",
    "refs": [
      "Genesis 31:7–12"
    ]
  },
  "Genesis 31:1": {
    "title": "Laban’s sons grow resentful",
    "text": "Jacob hears that Laban’s sons accuse him of taking their father’s wealth. The family relationship has deteriorated, and Jacob recognizes that his position is changing.",
    "refs": [
      "Genesis 30:43"
    ]
  },
  "Genesis 31:2": {
    "title": "Laban’s attitude changes",
    "text": "Jacob notices that Laban no longer treats him as before. The change confirms that Jacob’s growing household has become a source of tension.",
    "refs": [
      "Genesis 30:27–30"
    ]
  },
  "Genesis 31:3": {
    "title": "The LORD commands Jacob to return",
    "text": "The LORD tells Jacob to return to his fathers’ land and promises to be with him. God’s direction recalls the promise given at Bethel and frames the journey home.",
    "refs": [
      "Genesis 28:13–15"
    ]
  },
  "Genesis 31:4": {
    "title": "Jacob calls Rachel and Leah",
    "text": "Jacob asks Rachel and Leah to meet him in the field where his flock is. He discusses the family’s future away from Laban’s household.",
    "refs": [
      "Genesis 31:14–16"
    ]
  },
  "Genesis 31:5": {
    "title": "God has been with Jacob",
    "text": "Jacob says that the God of his father has been with him despite Laban’s changed attitude. The account presents God’s presence as a source of help amid unfair treatment.",
    "refs": [
      "Genesis 28:15"
    ]
  },
  "Genesis 31:6": {
    "title": "Jacob’s hard work",
    "text": "Jacob says he served their father with all his strength. He appeals to the years of labor that supported Laban’s household.",
    "refs": [
      "Genesis 30:29–30"
    ]
  },
  "Genesis 31:7": {
    "title": "Laban changed the wages",
    "text": "Jacob says Laban changed his wages repeatedly, but God did not allow Laban to harm him. The text emphasizes God’s protection in the face of exploitation.",
    "refs": [
      "Genesis 30:28–43"
    ]
  },
  "Genesis 31:8": {
    "title": "The flock’s markings",
    "text": "Jacob explains that Laban’s changing wage terms did not prevent the flock from producing animals that became Jacob’s wages. The details recall their agreement, while verse 12 attributes the outcome to God’s oversight.",
    "refs": [
      "Genesis 30:32–43"
    ]
  },
  "Genesis 31:9": {
    "title": "God transferred the livestock",
    "text": "Jacob says God took livestock from Laban and gave it to him. The statement interprets Jacob’s increase as God’s response to the unfair arrangement.",
    "refs": [
      "Genesis 30:43"
    ]
  },
  "Genesis 31:10": {
    "title": "Jacob’s dream about the animals",
    "text": "Jacob recounts seeing the animals in a dream during breeding season. The dream becomes part of his explanation of how God directed the outcome.",
    "refs": [
      "Genesis 31:11–12"
    ]
  },
  "Genesis 31:11": {
    "title": "The angel of God speaks",
    "text": "Jacob says the angel of God called him by name in the dream. The passage presents an angelic messenger delivering God’s message; the title alone should not be used to assert more than the text states.",
    "refs": [
      "Genesis 31:13"
    ]
  },
  "Genesis 31:12": {
    "title": "God sees Laban’s treatment",
    "text": "The speaker tells Jacob that God has seen what Laban is doing and the marked animals. The emphasis is on divine awareness and protection, not on rods acting as magic.",
    "refs": [
      "Genesis 31:7–9"
    ]
  },
  "Genesis 31:13": {
    "title": "The God of Bethel",
    "text": "The speaker identifies Himself with the God who appeared at Bethel, where Jacob anointed the pillar and made a vow. The message connects Jacob’s departure with the earlier revelation and promise.",
    "refs": [
      "Genesis 28:18–22"
    ]
  },
  "Genesis 31:14": {
    "title": "Rachel and Leah answer",
    "text": "Rachel and Leah ask whether any inheritance remains for them in their father’s house. They recognize that Laban’s actions have treated them as outsiders rather than secure members of his household.",
    "refs": [
      "Genesis 31:15"
    ]
  },
  "Genesis 31:15": {
    "title": "Their father treated them as strangers",
    "text": "The sisters say their father sold them and used up the money associated with them. Their words describe a family arrangement in which they believe they have been deprived of a fair share.",
    "refs": [
      "Genesis 29:18–30"
    ]
  },
  "Genesis 31:16": {
    "title": "They support Jacob’s departure",
    "text": "Rachel and Leah acknowledge that the wealth God took from their father belongs to them and their children. They agree that Jacob should follow what God has told him.",
    "refs": [
      "Genesis 31:3"
    ]
  },
  "Genesis 31:17": {
    "title": "Jacob prepares to leave",
    "text": "Jacob places his children and wives on camels and prepares for the journey. The departure involves his whole household, not merely his personal escape.",
    "refs": [
      "Genesis 32:1–2"
    ]
  },
  "Genesis 31:18": {
    "title": "Jacob carries his possessions away",
    "text": "Jacob drives his livestock and takes the possessions he acquired in Padan-aram toward Isaac in Canaan. The return moves the family toward the land promised to Abraham’s descendants.",
    "refs": [
      "Genesis 28:13–15"
    ]
  },
  "Genesis 31:19": {
    "title": "Rachel takes the household images",
    "text": "Rachel steals her father’s teraphim while Laban is away shearing sheep. The text reports the theft without endorsing it or fully explaining Rachel’s motive.",
    "refs": [
      "Genesis 31:30–35"
    ]
  },
  "Genesis 31:20": {
    "title": "Jacob leaves without telling Laban",
    "text": "Jacob departs secretly and does not tell Laban he is fleeing. Fear and distrust shape the escape after years of conflict over wages and treatment.",
    "refs": [
      "Genesis 31:31"
    ]
  },
  "Genesis 31:21": {
    "title": "The Euphrates crossing",
    "text": "Jacob crosses the river and heads toward the hill country of Gilead. His route takes him away from Laban’s territory and toward Canaan.",
    "refs": [
      "Genesis 31:23"
    ]
  },
  "Genesis 31:22": {
    "title": "Laban learns of the flight",
    "text": "On the third day Laban is told that Jacob has left. The delay gives Jacob a head start, but Laban pursues him.",
    "refs": [
      "Genesis 31:23"
    ]
  },
  "Genesis 31:23": {
    "title": "Laban pursues Jacob",
    "text": "Laban gathers relatives and follows Jacob for seven days before catching up in Gilead. The pursuit threatens to turn the family dispute into a confrontation.",
    "refs": [
      "Genesis 31:24"
    ]
  },
  "Genesis 31:24": {
    "title": "God warns Laban in a dream",
    "text": "God comes to Laban in a dream and warns him not to speak to Jacob either good or bad in a threatening sense. The warning places limits on Laban’s power to harm Jacob.",
    "refs": [
      "Genesis 31:29"
    ]
  },
  "Genesis 31:25": {
    "title": "The households meet in Gilead",
    "text": "Laban catches up and camps near Jacob. The two households are now face to face, setting the stage for their dispute.",
    "refs": [
      "Genesis 31:26–30"
    ]
  },
  "Genesis 31:26": {
    "title": "Laban accuses Jacob",
    "text": "Laban asks why Jacob secretly carried away his daughters as if they were captives. His accusation overlooks the years of conflict that drove Jacob to leave without notice.",
    "refs": [
      "Genesis 31:20–21"
    ]
  },
  "Genesis 31:27": {
    "title": "Laban claims he would have celebrated",
    "text": "Laban says Jacob should have told him so they could have held a farewell feast. The claim contrasts with the threat and pursuit that follow, and the narrative leaves readers to assess his reliability in light of his conduct.",
    "refs": [
      "Genesis 31:24, 29"
    ]
  },
  "Genesis 31:28": {
    "title": "Laban says he was denied a farewell",
    "text": "Laban complains that he was not allowed to kiss his daughters and grandchildren goodbye. His words focus on his own hurt while the deeper dispute over fairness remains unresolved.",
    "refs": [
      "Genesis 31:14–16"
    ]
  },
  "Genesis 31:29": {
    "title": "Laban acknowledges God’s warning",
    "text": "Laban says he has power to harm Jacob but that the God of Jacob’s father warned him. His statement confirms that divine intervention restrains him from acting on his threat.",
    "refs": [
      "Genesis 31:24"
    ]
  },
  "Genesis 31:30": {
    "title": "The household images become an issue",
    "text": "Laban says Jacob left because he longed for his father’s house, then asks why his gods were stolen. The irony is that the household images he calls gods have been taken from him.",
    "refs": [
      "Genesis 31:19"
    ]
  },
  "Genesis 31:31": {
    "title": "Jacob explains his fear",
    "text": "Jacob says he feared Laban might take his daughters by force, which is why he left secretly. His explanation identifies fear as the reason for his departure, though it does not excuse Rachel’s theft.",
    "refs": [
      "Genesis 31:20"
    ]
  },
  "Genesis 31:32": {
    "title": "Jacob’s challenge about the images",
    "text": "Jacob says whoever stole Laban’s gods should not live and invites a search. Jacob does not know Rachel has taken them, so his severe statement creates danger within his own household.",
    "refs": [
      "Genesis 31:19, 34"
    ]
  },
  "Genesis 31:33": {
    "title": "Laban searches the tents",
    "text": "Laban searches Jacob’s, Leah’s, and the servants’ tents but does not find the images. The search raises tension because Rachel has hidden them.",
    "refs": [
      "Genesis 31:34–35"
    ]
  },
  "Genesis 31:34": {
    "title": "Rachel hides the images",
    "text": "Rachel places the household images in a camel’s furniture and sits on them. The narrative reports the concealment plainly, without presenting it as an example of faithful conduct.",
    "refs": [
      "Genesis 31:19"
    ]
  },
  "Genesis 31:35": {
    "title": "Rachel gives an excuse",
    "text": "Rachel tells Laban she cannot rise because of her monthly condition, and he does not find the images. Her lie completes the concealment, but the text does not commend it.",
    "refs": [
      "Genesis 31:34"
    ]
  },
  "Genesis 31:36": {
    "title": "Jacob becomes angry",
    "text": "Jacob confronts Laban and demands to know his wrongdoing. After the search fails, Jacob challenges the accusation and the long history of unfair treatment.",
    "refs": [
      "Genesis 31:7"
    ]
  },
  "Genesis 31:37": {
    "title": "The search produces no evidence",
    "text": "Jacob asks Laban to display anything belonging to him and let their relatives judge. The challenge moves the argument from accusation toward a review of the evidence.",
    "refs": [
      "Genesis 31:32–35"
    ]
  },
  "Genesis 31:38": {
    "title": "Twenty years of care",
    "text": "Jacob says the ewes and female goats did not miscarry under his care and that he did not eat the rams. He emphasizes the careful work he performed for Laban’s flocks.",
    "refs": [
      "Genesis 30:29"
    ]
  },
  "Genesis 31:39": {
    "title": "Jacob bore the losses",
    "text": "Jacob says he did not bring torn animals to Laban but personally bore the losses, whether stolen by day or night. He describes an unusually demanding standard of responsibility for the flock.",
    "refs": [
      "Exodus 22:10–13"
    ]
  },
  "Genesis 31:40": {
    "title": "Hard conditions of service",
    "text": "Jacob recalls heat by day, frost by night, and sleeplessness. His account makes clear that his prosperity came after difficult years of labor.",
    "refs": [
      "Genesis 31:6"
    ]
  },
  "Genesis 31:41": {
    "title": "Laban changed the agreement repeatedly",
    "text": "Jacob summarizes twenty years of service, including fourteen years for Laban’s daughters and six for the flock. He says Laban changed his wages ten times, describing a pattern of exploitation.",
    "refs": [
      "Genesis 29:18–30",
      "Genesis 30:28"
    ]
  },
  "Genesis 31:42": {
    "title": "God saw Jacob’s affliction",
    "text": "Jacob says that without the God of Abraham and the Fear of Isaac, Laban would have sent him away empty-handed. God saw Jacob’s labor and rebuked Laban, according to Jacob’s testimony.",
    "refs": [
      "Genesis 31:24"
    ]
  },
  "Genesis 31:43": {
    "title": "Laban claims the family and flocks",
    "text": "Laban responds that the daughters, children, and flocks are his. His claim underscores the central dispute over ownership and authority, despite Jacob’s years of labor.",
    "refs": [
      "Genesis 31:14–16"
    ]
  },
  "Genesis 31:44": {
    "title": "A covenant between them",
    "text": "Laban proposes a covenant between himself and Jacob. The agreement aims to set a boundary on their conflict and establish a witness between them.",
    "refs": [
      "Genesis 31:48–53"
    ]
  },
  "Genesis 31:45": {
    "title": "Jacob sets up a pillar",
    "text": "Jacob takes a stone and sets it up as a pillar. The pillar becomes a visible marker of the covenant made between the two men.",
    "refs": [
      "Genesis 28:18"
    ]
  },
  "Genesis 31:46": {
    "title": "Stones gathered as a heap",
    "text": "Jacob tells his relatives to gather stones, and they make a heap and eat beside it. The meal accompanies the public marking of their agreement.",
    "refs": [
      "Genesis 31:47–48"
    ]
  },
  "Genesis 31:47": {
    "title": "Two names for the heap",
    "text": "Laban names the heap in Aramaic, and Jacob gives it a Hebrew name, both associated with a heap of witness. The different names reflect their languages while marking the same boundary agreement.",
    "refs": [
      "Genesis 31:48"
    ]
  },
  "Genesis 31:48": {
    "title": "The heap as a witness",
    "text": "Laban declares the heap a witness between them. The monument stands as a reminder of their agreement and the limits they have set.",
    "refs": [
      "Genesis 31:44"
    ]
  },
  "Genesis 31:49": {
    "title": "Mizpah and God’s oversight",
    "text": "Laban invokes the LORD to watch between them when they are apart. In context, this is a solemn boundary statement between men who distrust each other, not merely a sentimental farewell.",
    "refs": [
      "Genesis 31:52–53"
    ]
  },
  "Genesis 31:50": {
    "title": "A warning concerning the daughters",
    "text": "Laban warns Jacob not to mistreat his daughters or take other wives. The warning is striking in light of Laban’s own role in arranging Jacob’s marriages deceptively.",
    "refs": [
      "Genesis 29:23–30"
    ]
  },
  "Genesis 31:51": {
    "title": "The pillar and heap",
    "text": "Laban points to the pillar and heap as the boundary markers between them. The visible stones give their covenant a lasting public sign.",
    "refs": [
      "Genesis 31:45–48"
    ]
  },
  "Genesis 31:52": {
    "title": "A boundary against harm",
    "text": "Laban says neither party will pass the markers to harm the other. The covenant seeks to prevent future aggression rather than restore trust or affection.",
    "refs": [
      "Genesis 31:44"
    ]
  },
  "Genesis 31:53": {
    "title": "God as judge between them",
    "text": "Laban invokes the God of Abraham and Nahor’s family, while Jacob swears by the Fear of his father Isaac. The verse records family religious language and Jacob’s particular reverence for God; it should not be read as a full doctrinal formula.",
    "refs": [
      "Genesis 31:42"
    ]
  },
  "Genesis 31:54": {
    "title": "Jacob offers a sacrifice",
    "text": "Jacob offers a sacrifice on the mountain and invites his relatives to eat. The meal follows the covenant and marks a pause in the hostility between the households.",
    "refs": [
      "Genesis 26:30"
    ]
  },
  "Genesis 31:55": {
    "title": "Laban departs",
    "text": "Laban rises early, kisses his daughters and grandchildren, blesses them, and returns home. Jacob continues his journey, having left Laban’s control and moved toward the land God promised him.",
    "refs": [
      "Genesis 32:1–2"
    ]
  },
  "Genesis 32:1": {
    "title": "Angels meet Jacob",
    "text": "As Jacob continues his journey, angels of God meet him. Their appearance reminds the reader that God’s protection accompanies Jacob as he returns to Canaan.",
    "refs": [
      "Genesis 28:12–15"
    ]
  },
  "Genesis 32:2": {
    "title": "Mahanaim",
    "text": "Jacob names the place Mahanaim, meaning a camp or two camps, in response to the encounter. The name marks the meeting as significant before Jacob faces Esau.",
    "refs": [
      "Genesis 32:1"
    ]
  },
  "Genesis 32:3": {
    "title": "Jacob sends messengers",
    "text": "Jacob sends messengers ahead to Esau in the land of Seir. He seeks to approach his brother carefully after the threat that forced him to flee years earlier.",
    "refs": [
      "Genesis 27:41–45"
    ]
  },
  "Genesis 32:4": {
    "title": "Jacob’s respectful message",
    "text": "Jacob instructs the messengers to call Esau lord and himself a servant. His language is conciliatory and seeks to lower the tension between them.",
    "refs": [
      "Genesis 33:3"
    ]
  },
  "Genesis 32:5": {
    "title": "Jacob explains his possessions",
    "text": "Jacob tells Esau that he has livestock and servants and hopes to find favor. He presents his message as a peaceful notice rather than a challenge.",
    "refs": [
      "Genesis 33:8–11"
    ]
  },
  "Genesis 32:6": {
    "title": "Esau approaches with four hundred men",
    "text": "The messengers report that Esau is coming with four hundred men. Given Esau’s earlier threat, Jacob has reason to fear that the meeting could become violent.",
    "refs": [
      "Genesis 27:41"
    ]
  },
  "Genesis 32:7": {
    "title": "Jacob divides the company",
    "text": "Jacob becomes greatly afraid and divides his people and livestock into two groups. He prepares for the possibility of attack while trying to preserve part of his household.",
    "refs": [
      "Genesis 32:8"
    ]
  },
  "Genesis 32:8": {
    "title": "A plan for survival",
    "text": "Jacob reasons that if one group is attacked, the other may escape. The verse shows practical planning alongside his dependence on God.",
    "refs": [
      "Genesis 32:9–12"
    ]
  },
  "Genesis 32:9": {
    "title": "Jacob prays to the God of his fathers",
    "text": "Jacob calls on the LORD, the God of Abraham and Isaac, and recalls God’s command to return home. His prayer is rooted in God’s promise rather than in a claim of personal merit.",
    "refs": [
      "Genesis 28:13–15"
    ]
  },
  "Genesis 32:10": {
    "title": "Jacob confesses his unworthiness",
    "text": "Jacob says he is unworthy of the mercies and truth God has shown him. He remembers crossing the Jordan with only his staff and now having become two companies, giving thanks for God’s faithfulness.",
    "refs": [
      "Genesis 31:3"
    ]
  },
  "Genesis 32:11": {
    "title": "Deliver me from Esau",
    "text": "Jacob asks God to deliver him because he fears Esau will attack mothers and children. His prayer names the danger directly and asks for protection for his whole family.",
    "refs": [
      "Genesis 27:41"
    ]
  },
  "Genesis 32:12": {
    "title": "Jacob recalls God’s promise",
    "text": "Jacob reminds God of the promise that his descendants would become numerous. He appeals to the word God has spoken, showing faith that rests on divine faithfulness.",
    "refs": [
      "Genesis 28:14–15"
    ]
  },
  "Genesis 32:13": {
    "title": "Jacob prepares a gift",
    "text": "Jacob selects a gift from his possessions for Esau. He uses a practical act of reconciliation while continuing to seek God’s help.",
    "refs": [
      "Proverbs 18:16"
    ]
  },
  "Genesis 32:14": {
    "title": "The animals counted",
    "text": "The gift includes large numbers of goats, sheep, camels, cattle, and donkeys. The detailed list emphasizes the size of Jacob’s wealth and the generosity of the intended offering.",
    "refs": [
      "Genesis 30:43"
    ]
  },
  "Genesis 32:15": {
    "title": "The gift’s full scale",
    "text": "The number and types of animals are specified, including nursing camels and their colts. Jacob’s gift is substantial and intended to communicate goodwill.",
    "refs": [
      "Genesis 32:20"
    ]
  },
  "Genesis 32:16": {
    "title": "Separate droves",
    "text": "Jacob divides the animals into droves and places servants over them. The order allows each group to arrive separately and reinforces the impression of a carefully planned gift.",
    "refs": [
      "Genesis 32:17–20"
    ]
  },
  "Genesis 32:17": {
    "title": "Instructions to the first servant",
    "text": "Jacob tells the first servant what to say when Esau asks who owns the animals and where they are going. He prepares each encounter to present the gift as an expression of respect.",
    "refs": [
      "Genesis 32:18"
    ]
  },
  "Genesis 32:18": {
    "title": "A gift from Jacob",
    "text": "The servant is to say the animals belong to Jacob and are sent as a gift to Esau, who is coming behind. The message is designed to soften Esau’s anger before the brothers meet.",
    "refs": [
      "Genesis 32:20"
    ]
  },
  "Genesis 32:19": {
    "title": "The same message repeated",
    "text": "Jacob gives the same instructions to the second and following servants. Repetition ensures that the meaning of the gift is clear at each stage.",
    "refs": [
      "Genesis 32:17–18"
    ]
  },
  "Genesis 32:20": {
    "title": "Seeking to appease Esau",
    "text": "Jacob hopes the gift will appease Esau before they meet face to face. The text shows Jacob acting to seek peace, though the outcome remains in God’s hands.",
    "refs": [
      "Proverbs 21:14"
    ]
  },
  "Genesis 32:21": {
    "title": "Jacob remains behind",
    "text": "The gift goes ahead while Jacob stays that night with the company. He has made preparations, but the fear and uncertainty of meeting Esau remain.",
    "refs": [
      "Genesis 32:6–12"
    ]
  },
  "Genesis 32:22": {
    "title": "The family crosses the ford",
    "text": "Jacob takes his wives, servants, and eleven sons across the ford of Jabbok. The crossing marks a turning point immediately before Jacob’s solitary night encounter.",
    "refs": [
      "Genesis 35:23–26"
    ]
  },
  "Genesis 32:23": {
    "title": "Jacob sends his household across",
    "text": "Jacob sends his family and possessions over the stream. He remains alone, creating the setting for the mysterious struggle that follows.",
    "refs": [
      "Genesis 32:24"
    ]
  },
  "Genesis 32:24": {
    "title": "A man wrestles with Jacob",
    "text": "A man wrestles with Jacob until daybreak. The text presents a mysterious encounter; its identity is clarified within the passage but should be explained by following the text’s own wording.",
    "refs": [
      "Genesis 32:28–30"
    ]
  },
  "Genesis 32:25": {
    "title": "Jacob’s hip is touched",
    "text": "The man sees that he does not prevail against Jacob and touches Jacob’s hip, putting it out of joint. The injury reveals the encounter’s extraordinary character and leaves Jacob changed.",
    "refs": [
      "Genesis 32:31"
    ]
  },
  "Genesis 32:26": {
    "title": "Jacob clings for a blessing",
    "text": "The man tells Jacob to let him go because day is breaking, but Jacob refuses unless he is blessed. Jacob’s persistence shows his desperate desire for God’s favor before meeting Esau.",
    "refs": [
      "Hosea 12:3–5"
    ]
  },
  "Genesis 32:27": {
    "title": "Jacob is asked his name",
    "text": "The man asks Jacob his name. This question prepares for the renaming that will mark a new stage in Jacob’s identity and history.",
    "refs": [
      "Genesis 27:18–19"
    ]
  },
  "Genesis 32:28": {
    "title": "Israel, the name given to Jacob",
    "text": "Jacob is told that his name will be Israel because he has struggled with God and with men and has prevailed. The name marks a transformed identity, though it does not mean Jacob has become equal to God.",
    "refs": [
      "Genesis 35:10"
    ]
  },
  "Genesis 32:29": {
    "title": "Jacob asks the man’s name",
    "text": "Jacob asks the man’s name, but receives no direct answer; instead, he is blessed. The passage preserves mystery around the encounter rather than offering a complete explanation of every detail.",
    "refs": [
      "Judges 13:17–18"
    ]
  },
  "Genesis 32:30": {
    "title": "Peniel: seeing God",
    "text": "Jacob names the place Peniel because he says he has seen God face to face and his life has been preserved. The passage uses the language of a divine encounter; it does not mean that God’s infinite nature is limited to a visible body.",
    "refs": [
      "Exodus 33:20",
      "John 1:18"
    ]
  },
  "Genesis 32:31": {
    "title": "Jacob limps into the sunrise",
    "text": "The sun rises as Jacob passes Peniel, and he limps because of his hip. The physical mark remains as a reminder of the night’s encounter and Jacob’s dependence.",
    "refs": [
      "Genesis 32:25"
    ]
  },
  "Genesis 32:32": {
    "title": "The custom concerning the hip",
    "text": "The narrator explains a custom among the children of Israel concerning the sinew of the hip. The verse connects Israel’s later communal practice with the remembered event in Jacob’s life.",
    "refs": [
      "Genesis 32:25"
    ]
  },
  "Genesis 33:1": {
    "title": "Esau approaches with his men",
    "text": "Jacob sees Esau approaching with four hundred men and arranges his family in groups. The long-feared meeting is now immediate.",
    "refs": [
      "Genesis 32:6–8"
    ]
  },
  "Genesis 33:2": {
    "title": "Jacob arranges his family",
    "text": "Jacob places the servants and their children first, Leah and her children next, and Rachel and Joseph last. The order reveals his continuing favoritism, even as he prepares to meet Esau.",
    "refs": [
      "Genesis 29:30"
    ]
  },
  "Genesis 33:3": {
    "title": "Jacob bows before Esau",
    "text": "Jacob goes ahead of his family and bows seven times as he approaches Esau. His posture expresses humility and a desire for reconciliation.",
    "refs": [
      "Genesis 32:4–5"
    ]
  },
  "Genesis 33:4": {
    "title": "Esau embraces Jacob",
    "text": "Esau runs to meet Jacob, embraces him, falls on his neck, kisses him, and they weep. The feared violence gives way to an unexpected scene of reconciliation.",
    "refs": [
      "Genesis 27:41",
      "Proverbs 16:7"
    ]
  },
  "Genesis 33:5": {
    "title": "Esau asks about the family",
    "text": "Esau sees the women and children and asks who they are. Jacob answers that they are the children God has graciously given him, acknowledging God as the source of his family.",
    "refs": [
      "Psalm 127:3"
    ]
  },
  "Genesis 33:6": {
    "title": "The servants bow",
    "text": "The handmaids and their children approach and bow before Esau. The family’s greeting reflects the social hierarchy and Jacob’s careful effort to show respect.",
    "refs": [
      "Genesis 33:2–3"
    ]
  },
  "Genesis 33:7": {
    "title": "Leah’s family and Rachel’s family",
    "text": "Leah and her children, then Rachel and Joseph, approach and bow. The narrative records the whole family’s meeting with Esau after years of separation.",
    "refs": [
      "Genesis 29:30"
    ]
  },
  "Genesis 33:8": {
    "title": "Esau asks about the droves",
    "text": "Esau asks the purpose of the groups of animals that met him on the road. Jacob explains that they were sent to find favor with his brother.",
    "refs": [
      "Genesis 32:13–20"
    ]
  },
  "Genesis 33:9": {
    "title": "Esau says he has enough",
    "text": "Esau says he has plenty and asks Jacob to keep what he has. His response initially declines the gift and indicates that he is not approaching Jacob as an enemy.",
    "refs": [
      "Genesis 33:4"
    ]
  },
  "Genesis 33:10": {
    "title": "Jacob sees favor in Esau’s face",
    "text": "Jacob urges Esau to accept the gift and compares seeing Esau’s face to seeing God’s face, because Esau has received him favorably. This is a comparison expressing relief and favor, not a claim that Esau is God.",
    "refs": [
      "Genesis 32:30"
    ]
  },
  "Genesis 33:11": {
    "title": "The gift is accepted",
    "text": "Jacob asks Esau to accept his blessing, saying God has dealt graciously with him and that he has enough. Esau finally accepts, completing a significant act of reconciliation.",
    "refs": [
      "Genesis 32:13–20"
    ]
  },
  "Genesis 33:12": {
    "title": "Esau offers to travel together",
    "text": "Esau proposes that they travel together. Jacob’s response will show that he does not accept this arrangement, despite their peaceful meeting.",
    "refs": [
      "Genesis 33:13–14"
    ]
  },
  "Genesis 33:13": {
    "title": "Jacob considers the children and flocks",
    "text": "Jacob explains that the children are tender and the livestock with young must be driven gently. His concern for the household’s limits provides his reason for traveling more slowly.",
    "refs": [
      "Genesis 31:17–18"
    ]
  },
  "Genesis 33:14": {
    "title": "Jacob asks to follow at his pace",
    "text": "Jacob says he will travel slowly toward Seir, matching the pace of the children and animals. He does not promise to travel directly with Esau’s company.",
    "refs": [
      "Genesis 33:12–13"
    ]
  },
  "Genesis 33:15": {
    "title": "Esau offers an escort",
    "text": "Esau offers to leave some of his men with Jacob. Jacob asks why he needs such favor and declines the offer, maintaining distance after the reconciliation.",
    "refs": [
      "Genesis 33:16"
    ]
  },
  "Genesis 33:16": {
    "title": "Esau returns to Seir",
    "text": "Esau returns that day toward Seir. The brothers part peacefully, but the text does not say that Jacob joins Esau’s route.",
    "refs": [
      "Genesis 33:14–15"
    ]
  },
  "Genesis 33:17": {
    "title": "Jacob settles at Succoth",
    "text": "Jacob travels to Succoth, builds a house, and makes shelters for his livestock. The place name is associated with the shelters he made.",
    "refs": [
      "Joshua 13:27"
    ]
  },
  "Genesis 33:18": {
    "title": "Jacob arrives near Shechem",
    "text": "Jacob arrives safely at the city of Shechem in Canaan and camps before it. His return fulfills the broad direction God gave him to come back to his homeland.",
    "refs": [
      "Genesis 31:3"
    ]
  },
  "Genesis 33:19": {
    "title": "Land purchased from Hamor’s family",
    "text": "Jacob buys the parcel where he pitches his tent from the sons of Hamor. The purchase establishes a specific foothold in the land, distinct from the larger covenant promise.",
    "refs": [
      "Genesis 23:16–20"
    ]
  },
  "Genesis 33:20": {
    "title": "An altar named El-elohe-Israel",
    "text": "Jacob builds an altar and names it El-elohe-Israel, acknowledging God as the God of Israel. The name links Jacob’s new identity with worship of the one God who has preserved him.",
    "refs": [
      "Genesis 32:28",
      "Deuteronomy 6:4"
    ]
  },
  "Genesis 34:1": {
    "title": "Dinah visits the women of the land",
    "text": "Dinah goes out to see the daughters of the land. The verse introduces the events that follow; it does not say she caused the violence committed against her.",
    "refs": [
      "Genesis 34:2"
    ]
  },
  "Genesis 34:2": {
    "title": "Shechem violates Dinah",
    "text": "Shechem sees Dinah, takes her, lies with her, and humbles her. The narrative reports sexual violence and must not be read as making Dinah responsible for Shechem’s actions.",
    "refs": [
      "Deuteronomy 22:25–27"
    ]
  },
  "Genesis 34:3": {
    "title": "Shechem’s attachment",
    "text": "Shechem becomes attached to Dinah and speaks tenderly to her. His feelings after the assault do not erase the wrong he has done.",
    "refs": [
      "Genesis 34:2"
    ]
  },
  "Genesis 34:4": {
    "title": "Shechem asks for marriage",
    "text": "Shechem tells his father Hamor to obtain Dinah as his wife. The request comes after the violation and does not itself repair the harm.",
    "refs": [
      "Genesis 34:2"
    ]
  },
  "Genesis 34:5": {
    "title": "Jacob hears the news",
    "text": "Jacob hears that Dinah has been defiled while his sons are away with the livestock. He waits until they return before responding.",
    "refs": [
      "Genesis 34:7"
    ]
  },
  "Genesis 34:6": {
    "title": "Hamor approaches Jacob",
    "text": "Hamor, Shechem’s father, comes to speak with Jacob. The family conflict becomes a negotiation between the men involved.",
    "refs": [
      "Genesis 34:8–12"
    ]
  },
  "Genesis 34:7": {
    "title": "Jacob’s sons are grieved and angry",
    "text": "Jacob’s sons hear what happened and are grieved and very angry because Shechem committed a disgraceful act in Israel. Their anger is directed at the violation, though their later revenge will also be condemned by the narrative’s events.",
    "refs": [
      "Genesis 34:25–31"
    ]
  },
  "Genesis 34:8": {
    "title": "Hamor proposes an arrangement",
    "text": "Hamor asks that Dinah be given to Shechem and proposes a family alliance. His proposal treats marriage as a way to settle the conflict, but it does not adequately address the violence done to Dinah.",
    "refs": [
      "Genesis 34:11–12"
    ]
  },
  "Genesis 34:9": {
    "title": "Intermarriage proposed",
    "text": "Hamor proposes intermarriage and social ties between the two peoples. The proposal has economic and political implications as well as family implications.",
    "refs": [
      "Genesis 34:10"
    ]
  },
  "Genesis 34:10": {
    "title": "Trade and property offered",
    "text": "Hamor says the families may live, trade, and acquire property in the land. The offer frames the conflict as an opportunity for wider integration.",
    "refs": [
      "Genesis 34:21–23"
    ]
  },
  "Genesis 34:11": {
    "title": "Shechem offers compensation",
    "text": "Shechem says he will give whatever is asked for Dinah. Money and gifts cannot undo the assault, and the text records his offer without declaring the harm resolved.",
    "refs": [
      "Exodus 22:16–17"
    ]
  },
  "Genesis 34:12": {
    "title": "A bride-price offered",
    "text": "Shechem offers a large bride-price and gift if he may marry Dinah. The negotiation emphasizes the customs of the setting, but it does not replace justice for the violence.",
    "refs": [
      "Genesis 34:11"
    ]
  },
  "Genesis 34:13": {
    "title": "Jacob’s sons answer deceitfully",
    "text": "Jacob’s sons respond with deceit because Shechem defiled their sister. The narrative identifies their answer as deceitful, preparing the reader to judge the revenge that follows rather than treating it as God’s command.",
    "refs": [
      "Genesis 34:25–31"
    ]
  },
  "Genesis 34:14": {
    "title": "The covenant condition",
    "text": "The brothers say they cannot give their sister to an uncircumcised man because it would be a reproach to them. Their stated religious condition becomes a trap rather than an honest proposal.",
    "refs": [
      "Genesis 17:10–14"
    ]
  },
  "Genesis 34:15": {
    "title": "Circumcision demanded",
    "text": "They say they will agree only if every male in Shechem’s community is circumcised. Circumcision was the sign of God’s covenant with Abraham, but using it deceptively for a violent plan profanes the sign’s meaning.",
    "refs": [
      "Genesis 17:11"
    ]
  },
  "Genesis 34:16": {
    "title": "A proposed united people",
    "text": "The brothers promise to give their daughters and take the other people’s daughters, and to live as one people. Their words conceal their intention, so this proposed unity is not a truthful covenant.",
    "refs": [
      "Genesis 34:13"
    ]
  },
  "Genesis 34:17": {
    "title": "A threat if they refuse",
    "text": "The brothers say they will take Dinah and leave if the men do not accept circumcision. The condition is presented as negotiation, while their hidden purpose is revenge.",
    "refs": [
      "Genesis 34:25"
    ]
  },
  "Genesis 34:18": {
    "title": "Hamor and Shechem agree",
    "text": "The proposal pleases Hamor and Shechem. Their acceptance sets the stage for the community-wide circumcision demanded by Jacob’s sons.",
    "refs": [
      "Genesis 34:19"
    ]
  },
  "Genesis 34:19": {
    "title": "Shechem acts quickly",
    "text": "Shechem does not delay because he desires Dinah and is influential in his father’s household. The verse describes his eagerness and status, not moral approval of his actions.",
    "refs": [
      "Genesis 34:2–4"
    ]
  },
  "Genesis 34:20": {
    "title": "Hamor speaks at the city gate",
    "text": "Hamor and Shechem address the men of their city at the gate, a public place for community decisions. They present the proposed alliance to the wider population.",
    "refs": [
      "Genesis 34:24"
    ]
  },
  "Genesis 34:21": {
    "title": "The city hears the proposal",
    "text": "Hamor says Jacob’s family is peaceful and can live and trade in the land. His account omits the brothers’ hidden plan and portrays the arrangement as beneficial.",
    "refs": [
      "Genesis 34:10"
    ]
  },
  "Genesis 34:22": {
    "title": "One condition for unity",
    "text": "Hamor says the men will become one people if every male is circumcised. The community is being asked to accept a covenant sign without understanding the deceit behind the demand.",
    "refs": [
      "Genesis 17:10–14"
    ]
  },
  "Genesis 34:23": {
    "title": "Hamor appeals to profit",
    "text": "Hamor asks whether their livestock and possessions will not become theirs. The appeal to material gain helps persuade the men to accept the arrangement.",
    "refs": [
      "Genesis 34:24"
    ]
  },
  "Genesis 34:24": {
    "title": "The men are circumcised",
    "text": "The men of the city agree and every male is circumcised. The text records their compliance, which leaves them vulnerable to the attack planned by Jacob’s sons.",
    "refs": [
      "Genesis 34:25"
    ]
  },
  "Genesis 34:25": {
    "title": "Simeon and Levi attack",
    "text": "On the third day, when the men are in pain, Simeon and Levi take their swords and kill the males of the city. Their act is violent revenge, not a command from God, and the later rebuke of Jacob’s sons makes the moral danger clear.",
    "refs": [
      "Genesis 49:5–7"
    ]
  },
  "Genesis 34:26": {
    "title": "Hamor and Shechem are killed",
    "text": "Simeon and Levi kill Hamor and Shechem and take Dinah from Shechem’s house. The rescue of Dinah is joined to the killing of the city’s men, an escalation beyond a just response to Shechem’s crime.",
    "refs": [
      "Genesis 34:25"
    ]
  },
  "Genesis 34:27": {
    "title": "The sons plunder the city",
    "text": "Jacob’s other sons come upon the slain and plunder the city because their sister had been defiled. The narrative records collective retaliation and its consequences, not a righteous model for resolving sexual violence.",
    "refs": [
      "Genesis 34:30"
    ]
  },
  "Genesis 34:28": {
    "title": "Livestock and property taken",
    "text": "The brothers take the flocks, herds, donkeys, and everything in the city and field. Their retaliation expands into seizure of property.",
    "refs": [
      "Genesis 34:29"
    ]
  },
  "Genesis 34:29": {
    "title": "People and possessions carried off",
    "text": "The sons take wealth, children, and wives as captives and plunder the houses. The violence has now harmed an entire community beyond the original offender.",
    "refs": [
      "Genesis 34:25–28"
    ]
  },
  "Genesis 34:30": {
    "title": "Jacob rebukes Simeon and Levi",
    "text": "Jacob warns that their actions have made him odious to the inhabitants of the land and may bring destruction on his household. His immediate concern is the family’s survival, while the later blessing explicitly condemns their cruelty.",
    "refs": [
      "Genesis 49:5–7"
    ]
  },
  "Genesis 34:31": {
    "title": "The brothers defend their anger",
    "text": "Simeon and Levi ask whether Shechem should have treated their sister as a harlot. Their question expresses outrage at Dinah’s violation, but their grievance does not justify the indiscriminate slaughter and plunder they carried out.",
    "refs": [
      "Genesis 49:5–7"
    ]
  },
  "Genesis 35:1": {
    "title": "God tells Jacob to go to Bethel",
    "text": "God commands Jacob to arise, go to Bethel, and build an altar to the God who appeared when he fled from Esau. The command brings Jacob back to the place associated with God’s promise and protection.",
    "refs": [
      "Genesis 28:12–22"
    ]
  },
  "Genesis 35:2": {
    "title": "Jacob calls for household cleansing",
    "text": "Jacob tells his household to put away foreign gods, purify themselves, and change their garments. The household must turn away from idols before going to worship the LORD.",
    "refs": [
      "Joshua 24:23"
    ]
  },
  "Genesis 35:3": {
    "title": "Jacob remembers God’s answer",
    "text": "Jacob says they will go to Bethel, where he will build an altar to God who answered him in distress and was with him on his journey. His worship is grounded in God’s past help.",
    "refs": [
      "Genesis 28:15"
    ]
  },
  "Genesis 35:4": {
    "title": "Foreign gods and earrings surrendered",
    "text": "The household gives Jacob foreign gods and earrings, which he hides under an oak near Shechem. The action marks a concrete renunciation of objects associated with other worship; the verse does not teach that every earring is an idol.",
    "refs": [
      "Genesis 31:19"
    ]
  },
  "Genesis 35:5": {
    "title": "God protects their journey",
    "text": "As Jacob’s household travels, a terror from God falls on the surrounding cities, and they do not pursue Jacob’s sons. The narrative attributes their safety to God’s intervention.",
    "refs": [
      "Genesis 34:30"
    ]
  },
  "Genesis 35:6": {
    "title": "Jacob arrives at Luz, or Bethel",
    "text": "Jacob and the people with him arrive at Luz in Canaan, identified as Bethel. The journey reaches the place where God first gave Jacob the covenant promise in a dream.",
    "refs": [
      "Genesis 28:19"
    ]
  },
  "Genesis 35:7": {
    "title": "An altar built at Bethel",
    "text": "Jacob builds an altar and names the place El-beth-el because God had revealed Himself there when Jacob fled from his brother. The name memorializes God’s self-revelation and care.",
    "refs": [
      "Genesis 28:12–17"
    ]
  },
  "Genesis 35:8": {
    "title": "Deborah dies",
    "text": "Rebekah’s nurse Deborah dies and is buried beneath an oak near Bethel. The verse records a family loss and preserves the name of the place associated with her burial.",
    "refs": [
      "Genesis 24:59"
    ]
  },
  "Genesis 35:9": {
    "title": "God appears again and blesses Jacob",
    "text": "God appears to Jacob again after his return from Padan-aram and blesses him. The repeated appearance confirms that the God who met Jacob on the road remains faithful at Bethel.",
    "refs": [
      "Genesis 28:13–15"
    ]
  },
  "Genesis 35:10": {
    "title": "Jacob is named Israel",
    "text": "God tells Jacob that his name is Jacob no longer but Israel. The renaming confirms the identity first announced during the struggle at Peniel.",
    "refs": [
      "Genesis 32:28"
    ]
  },
  "Genesis 35:11": {
    "title": "God Almighty speaks covenant blessing",
    "text": "God identifies Himself as God Almighty and promises fruitfulness, nations, and kings from Jacob’s line. The promise continues the covenant with Abraham and Isaac and establishes Jacob’s descendants as a people through whom God’s purposes will unfold.",
    "refs": [
      "Genesis 17:1–6",
      "Genesis 28:3–4"
    ]
  },
  "Genesis 35:12": {
    "title": "The promised land reaffirmed",
    "text": "God promises Jacob the land given to Abraham and Isaac and to Jacob’s descendants after him. The covenant promise is reaffirmed by God Himself.",
    "refs": [
      "Genesis 28:13"
    ]
  },
  "Genesis 35:13": {
    "title": "God goes up from the place",
    "text": "God goes up from the place where He spoke with Jacob. The language describes the conclusion of the divine encounter; it should not be used to limit God’s presence to one physical location.",
    "refs": [
      "1 Kings 8:27"
    ]
  },
  "Genesis 35:14": {
    "title": "Jacob sets up a memorial",
    "text": "Jacob sets up a stone pillar, pours a drink offering and oil on it. The act marks the place of the revelation and expresses worship in the custom of that period.",
    "refs": [
      "Genesis 28:18"
    ]
  },
  "Genesis 35:15": {
    "title": "Jacob names the place Bethel",
    "text": "Jacob again names the place Bethel, the house of God. The repeated name preserves the significance of God’s promise and Jacob’s response.",
    "refs": [
      "Genesis 28:19"
    ]
  },
  "Genesis 35:16": {
    "title": "Rachel’s labor begins",
    "text": "Jacob’s household travels from Bethel, and Rachel goes into hard labor near Ephrath. The narrative shifts from the reaffirmed covenant to a painful family event.",
    "refs": [
      "Genesis 48:7"
    ]
  },
  "Genesis 35:17": {
    "title": "The midwife encourages Rachel",
    "text": "As Rachel’s labor becomes difficult, the midwife tells her not to fear because she has another son. The words offer hope during a dangerous birth.",
    "refs": [
      "Genesis 30:24"
    ]
  },
  "Genesis 35:18": {
    "title": "Rachel names Benjamin",
    "text": "As Rachel dies, she names her son Ben-oni, while Jacob calls him Benjamin. The two names preserve grief and the father’s chosen name, and the text treats Rachel’s death with solemnity.",
    "refs": [
      "Genesis 48:7"
    ]
  },
  "Genesis 35:19": {
    "title": "Rachel is buried near Ephrath",
    "text": "Rachel dies and is buried on the way to Ephrath, identified as Bethlehem. Her burial place becomes a remembered landmark in Israel’s story.",
    "refs": [
      "1 Samuel 10:2"
    ]
  },
  "Genesis 35:20": {
    "title": "Rachel’s pillar",
    "text": "Jacob sets up a pillar over Rachel’s grave, which the narrator says remained known. The memorial preserves her memory; the text does not command worship of the monument.",
    "refs": [
      "Genesis 48:7"
    ]
  },
  "Genesis 35:21": {
    "title": "Israel journeys beyond Migdal-eder",
    "text": "Israel moves on and pitches his tent beyond Migdal-eder. The narrative continues tracking the family’s movements through the land.",
    "refs": [
      "Micah 4:8"
    ]
  },
  "Genesis 35:22": {
    "title": "Reuben’s sin and Israel’s sons",
    "text": "The text reports that Reuben lies with Bilhah, his father’s concubine, and Israel hears of it. This serious violation later affects Reuben’s standing among his brothers; the verse records the sin without excusing it.",
    "refs": [
      "Genesis 49:3–4"
    ]
  },
  "Genesis 35:23": {
    "title": "The sons born to Leah",
    "text": "The text lists Reuben, Simeon, Levi, Judah, Issachar, and Zebulun as Leah’s sons. The list begins the formal record of Jacob’s sons who become ancestors of Israel’s tribes.",
    "refs": [
      "Genesis 29:32–35",
      "Genesis 30:18–20"
    ]
  },
  "Genesis 35:24": {
    "title": "The sons born to Rachel",
    "text": "Joseph and Benjamin are named as Rachel’s sons. Their births and family positions are important in the later narratives of Jacob’s household.",
    "refs": [
      "Genesis 30:22–24",
      "Genesis 35:18"
    ]
  },
  "Genesis 35:25": {
    "title": "The sons born to Bilhah",
    "text": "Dan and Naphtali are listed as sons of Bilhah, Rachel’s servant. The record includes the children born through the household arrangement described earlier.",
    "refs": [
      "Genesis 30:5–8"
    ]
  },
  "Genesis 35:26": {
    "title": "The sons born to Zilpah",
    "text": "Gad and Asher are listed as sons of Zilpah, Leah’s servant. Together with the other names, the list records the twelve sons who form the tribal ancestry of Israel.",
    "refs": [
      "Genesis 30:10–13"
    ]
  },
  "Genesis 35:27": {
    "title": "Jacob returns to Isaac",
    "text": "Jacob comes to Isaac at Mamre, near Hebron, where Abraham and Isaac had sojourned. The family story circles back to Isaac’s household after Jacob’s long absence.",
    "refs": [
      "Genesis 13:18",
      "Genesis 26:6"
    ]
  },
  "Genesis 35:28": {
    "title": "Isaac’s age",
    "text": "Isaac’s lifespan is given as one hundred and eighty years. The verse closes a major life span in the patriarchal narrative.",
    "refs": [
      "Genesis 25:7"
    ]
  },
  "Genesis 35:29": {
    "title": "Isaac dies and is buried",
    "text": "Isaac dies old and full of days, and Esau and Jacob bury him. The brothers act together in their father’s burial, a quiet sign of family duty after their earlier estrangement.",
    "refs": [
      "Genesis 33:4"
    ]
  },
  "Genesis 36:1": {
    "title": "The generations of Esau",
    "text": "The chapter begins the account of Esau, also called Edom. This genealogy traces the line of Jacob’s brother and the people associated with him.",
    "refs": [
      "Genesis 25:30"
    ]
  },
  "Genesis 36:2": {
    "title": "Esau’s wives and family origins",
    "text": "The text lists Esau’s wives and their family backgrounds. The names and genealogical details preserve the historical framework of Edom’s ancestry.",
    "refs": [
      "Genesis 26:34–35"
    ]
  },
  "Genesis 36:3": {
    "title": "Bashemath and Ishmael’s family",
    "text": "Bashemath is identified as Ishmael’s daughter and sister of Nebajoth. The genealogy connects Esau’s household with the wider family of Abraham through Ishmael.",
    "refs": [
      "Genesis 25:13"
    ]
  },
  "Genesis 36:4": {
    "title": "Esau’s sons are born",
    "text": "The text names Eliphaz and Reuel as sons born to Esau. These sons become important figures in the genealogy of Edom.",
    "refs": [
      "Genesis 36:10"
    ]
  },
  "Genesis 36:5": {
    "title": "More sons of Esau",
    "text": "Jeush, Jaalam, and Korah are listed as sons of Esau. The list shows the growth of Esau’s household and the branches of his descendants.",
    "refs": [
      "Genesis 36:14"
    ]
  },
  "Genesis 36:6": {
    "title": "Esau moves away from Jacob",
    "text": "Esau takes his wives, children, servants, livestock, and possessions and moves away from Jacob because their property is too great for them to dwell together. The separation resembles the earlier separation of Abraham and Lot due to their possessions.",
    "refs": [
      "Genesis 13:5–12"
    ]
  },
  "Genesis 36:7": {
    "title": "Their possessions are too great",
    "text": "The land cannot sustain both brothers’ large households and herds in the same area. The verse explains the practical reason for their separation, not a spiritual ranking between them.",
    "refs": [
      "Genesis 13:6"
    ]
  },
  "Genesis 36:8": {
    "title": "Esau settles in Seir",
    "text": "Esau, also called Edom, dwells in the hill country of Seir. This establishes the geographic association between Esau and Edom.",
    "refs": [
      "Genesis 32:3"
    ]
  },
  "Genesis 36:9": {
    "title": "Esau’s descendants in Seir",
    "text": "The genealogy turns to Esau’s descendants in the hill country of Seir. The record connects family lines with the land where they settled.",
    "refs": [
      "Genesis 36:8"
    ]
  },
  "Genesis 36:10": {
    "title": "The sons of Eliphaz and Reuel",
    "text": "The chapter begins listing the descendants of Esau’s sons. These names establish the family branches that later appear among Edomite clans.",
    "refs": [
      "Genesis 36:11–13"
    ]
  },
  "Genesis 36:11": {
    "title": "The sons of Eliphaz",
    "text": "Teman, Omar, Zepho, Gatam, and Kenaz are listed as sons of Eliphaz. The names preserve the ancestral lines of the Edomite clans.",
    "refs": [
      "Genesis 36:15"
    ]
  },
  "Genesis 36:12": {
    "title": "Amalek’s ancestry",
    "text": "Timna, a concubine of Eliphaz, bears Amalek. The verse records Amalek’s place in Esau’s line; later biblical passages describe conflict involving Amalek and Israel.",
    "refs": [
      "Exodus 17:8–16"
    ]
  },
  "Genesis 36:13": {
    "title": "The sons of Reuel",
    "text": "Nahath, Zerah, Shammah, and Mizzah are listed as sons of Reuel. The genealogy documents the branches of Esau’s descendants.",
    "refs": [
      "Genesis 36:17"
    ]
  },
  "Genesis 36:14": {
    "title": "The sons through Oholibamah",
    "text": "The verse lists the sons born to Esau through Oholibamah, daughter of Anah. The names continue the genealogy of Esau’s family.",
    "refs": [
      "Genesis 36:5"
    ]
  },
  "Genesis 36:15": {
    "title": "Chiefs among Esau’s descendants",
    "text": "The text begins listing chiefs from the sons of Eliphaz. The genealogy records social and clan leadership among the Edomites.",
    "refs": [
      "Genesis 36:40"
    ]
  },
  "Genesis 36:16": {
    "title": "More chiefs of Eliphaz’s line",
    "text": "Korah and other named descendants are included among the chiefs. The names document the clans that formed within Esau’s line.",
    "refs": [
      "Genesis 36:11–12"
    ]
  },
  "Genesis 36:17": {
    "title": "Chiefs of Reuel’s line",
    "text": "The descendants of Reuel are listed as chiefs. The record shows that the family branches developed into organized clans.",
    "refs": [
      "Genesis 36:13"
    ]
  },
  "Genesis 36:18": {
    "title": "Chiefs from Oholibamah’s sons",
    "text": "The chiefs descended from Oholibamah’s sons are named. The genealogy records the leadership groups associated with Esau’s household.",
    "refs": [
      "Genesis 36:14"
    ]
  },
  "Genesis 36:19": {
    "title": "Esau is Edom",
    "text": "The passage summarizes these as the sons of Esau, who is Edom, and their chiefs. The name Edom links the genealogy with the people and territory known by that name.",
    "refs": [
      "Genesis 25:30"
    ]
  },
  "Genesis 36:20": {
    "title": "The sons of Seir the Horite",
    "text": "The genealogy shifts to the inhabitants of Seir before Esau’s descendants settled there. This distinction helps trace the region’s earlier families and their relationship to Edom.",
    "refs": [
      "Genesis 36:8"
    ]
  },
  "Genesis 36:21": {
    "title": "Horite chiefs",
    "text": "The verse lists the descendants and chiefs of Seir’s family. The genealogy preserves the earlier inhabitants’ lineages rather than presenting them as sons of Jacob.",
    "refs": [
      "Genesis 36:20"
    ]
  },
  "Genesis 36:22": {
    "title": "Lotan’s family",
    "text": "The sons of Lotan and the name of his sister are recorded. Such details preserve clan relationships in the regional genealogy.",
    "refs": [
      "Genesis 36:29"
    ]
  },
  "Genesis 36:23": {
    "title": "Shobal’s sons",
    "text": "The names of Shobal’s sons are listed as part of the Horite genealogy. The passage is primarily a record of ancestry, not a doctrinal argument.",
    "refs": [
      "Genesis 36:20"
    ]
  },
  "Genesis 36:24": {
    "title": "Anah and the hot springs",
    "text": "The text notes that Anah found the mules or hot springs in the wilderness while feeding his father’s donkeys; the Hebrew term is debated in translation. The verse preserves a traditional detail about Anah’s life.",
    "refs": [
      "Genesis 36:20"
    ]
  },
  "Genesis 36:25": {
    "title": "Anah’s children",
    "text": "The genealogy names Anah’s daughter and son. The family list continues to map the relationships among Seir’s descendants.",
    "refs": [
      "Genesis 36:20"
    ]
  },
  "Genesis 36:26": {
    "title": "Dishon’s sons",
    "text": "The sons of Dishon are named. The details establish another branch within the Horite clans.",
    "refs": [
      "Genesis 36:21"
    ]
  },
  "Genesis 36:27": {
    "title": "Ezer’s sons",
    "text": "The genealogy lists the sons of Ezer. The verse is part of the record of chiefs and families associated with Seir.",
    "refs": [
      "Genesis 36:21"
    ]
  },
  "Genesis 36:28": {
    "title": "Dishan’s sons",
    "text": "The sons of Dishan are named, preserving the family structure of the Horites. The list contributes to the chapter’s account of the region’s inhabitants.",
    "refs": [
      "Genesis 36:20"
    ]
  },
  "Genesis 36:29": {
    "title": "The Horite chiefs listed",
    "text": "The chapter names the chiefs of the Horites, organized by their family lines. This genealogy distinguishes the local clans from Esau’s later Edomite descendants.",
    "refs": [
      "Genesis 36:20–21"
    ]
  },
  "Genesis 36:30": {
    "title": "The chiefs by their districts",
    "text": "The named chiefs are associated with their districts in Seir. The list portrays an organized regional population before the later Edomite kings are introduced.",
    "refs": [
      "Genesis 36:31"
    ]
  },
  "Genesis 36:31": {
    "title": "Kings in Edom before Israel’s kings",
    "text": "The text says these were the kings who reigned in Edom before any king reigned over the children of Israel. This is a historical note contrasting Edom’s kingship with Israel’s later monarchy, not a prediction of a particular king.",
    "refs": [
      "Numbers 20:14"
    ]
  },
  "Genesis 36:32": {
    "title": "Bela reigns in Edom",
    "text": "Bela son of Beor is named as the first king in the list, with Dinhabah as his city. The record shows Edom’s political organization through kings.",
    "refs": [
      "Genesis 36:31"
    ]
  },
  "Genesis 36:33": {
    "title": "Jobab succeeds Bela",
    "text": "After Bela’s death, Jobab from Bozrah reigns in his place. The genealogy records a succession of rulers without explaining each reign’s events.",
    "refs": [
      "Genesis 36:31"
    ]
  },
  "Genesis 36:34": {
    "title": "Husham succeeds Jobab",
    "text": "After Jobab’s death, Husham from the land of Temani becomes king. The verse continues the sequence of Edomite kings.",
    "refs": [
      "Genesis 36:31"
    ]
  },
  "Genesis 36:35": {
    "title": "Hadad’s victory and reign",
    "text": "Hadad son of Bedad becomes king after defeating Midian in the field of Moab. The verse preserves a military event associated with his reign.",
    "refs": [
      "Genesis 36:31"
    ]
  },
  "Genesis 36:36": {
    "title": "Samlah succeeds Hadad",
    "text": "After Hadad’s death, Samlah from Masrekah becomes king. The list continues without offering a detailed narrative of each ruler.",
    "refs": [
      "Genesis 36:31"
    ]
  },
  "Genesis 36:37": {
    "title": "Shaul succeeds Samlah",
    "text": "Shaul from Rehoboth by the river becomes king after Samlah. The precise location of Rehoboth is not certain from this verse alone.",
    "refs": [
      "Genesis 36:31"
    ]
  },
  "Genesis 36:38": {
    "title": "Baal-hanan succeeds Shaul",
    "text": "Baal-hanan son of Achbor becomes king after Shaul’s death. The verse preserves the succession record of Edom’s rulers.",
    "refs": [
      "Genesis 36:31"
    ]
  },
  "Genesis 36:39": {
    "title": "Hadad and his city",
    "text": "The genealogy names Hadad and his wife Mehetabel, along with the city Pau. The details preserve family connections associated with the last king in this list.",
    "refs": [
      "Genesis 36:31"
    ]
  },
  "Genesis 36:40": {
    "title": "Chiefs named by their families",
    "text": "The text begins a list of Edomite chiefs by their names and family groups. The list differs from the earlier sequence of kings and traces clan leadership.",
    "refs": [
      "Genesis 36:15–19"
    ]
  },
  "Genesis 36:41": {
    "title": "More chiefs of Edom",
    "text": "The names of additional chiefs are listed. Their inclusion shows the breadth of the clan organization associated with Esau’s descendants.",
    "refs": [
      "Genesis 36:40"
    ]
  },
  "Genesis 36:42": {
    "title": "Further chiefs listed",
    "text": "The genealogy continues naming chiefs of Edom. These lists preserve the people’s remembered structure and ancestry.",
    "refs": [
      "Genesis 36:40"
    ]
  },
  "Genesis 36:43": {
    "title": "The chiefs and their settlements",
    "text": "The chapter concludes with chiefs identified by their settlements in the land they possessed. The genealogy ends by identifying Esau as the father of Edom’s people.",
    "refs": [
      "Genesis 36:8"
    ]
  },
  "Genesis 37:1": {
    "title": "Jacob dwells in Canaan",
    "text": "Jacob lives in the land where his father had sojourned. The account now focuses on Joseph and the tensions within Jacob’s household.",
    "refs": [
      "Genesis 35:27"
    ]
  },
  "Genesis 37:2": {
    "title": "Joseph’s account of his brothers",
    "text": "Joseph, seventeen years old, tends the flock with his brothers and brings a report about them to Jacob. The verse introduces the family dynamics that lead to Joseph’s suffering.",
    "refs": [
      "Genesis 37:3–4"
    ]
  },
  "Genesis 37:3": {
    "title": "Israel loves Joseph specially",
    "text": "Jacob loves Joseph more than his other sons because Joseph was born in his old age, and he makes him a special coat. The favoritism echoes the divisions in the previous generation and fuels resentment.",
    "refs": [
      "Genesis 25:28",
      "Genesis 29:30"
    ]
  },
  "Genesis 37:4": {
    "title": "His brothers hate him",
    "text": "Joseph’s brothers see their father’s preference and hate Joseph so much they cannot speak peaceably to him. The verse shows how favoritism damages family relationships.",
    "refs": [
      "James 3:16"
    ]
  },
  "Genesis 37:5": {
    "title": "Joseph’s first dream",
    "text": "Joseph dreams and tells his brothers, who hate him even more. The dream becomes a source of conflict, though the narrative later shows that God’s providence works through events beyond the brothers’ intentions.",
    "refs": [
      "Genesis 37:8"
    ]
  },
  "Genesis 37:6": {
    "title": "Joseph invites them to hear",
    "text": "Joseph asks his brothers to hear the dream he has had. The account does not say he understands all the future implications of the dream.",
    "refs": [
      "Genesis 37:9–11"
    ]
  },
  "Genesis 37:7": {
    "title": "The sheaves bow down",
    "text": "Joseph dreams that their sheaves rise and bow to his sheaf. The image points to his future prominence over his brothers, later realized during the famine in Egypt.",
    "refs": [
      "Genesis 42:6"
    ]
  },
  "Genesis 37:8": {
    "title": "The brothers reject the idea",
    "text": "The brothers ask whether Joseph intends to rule over them and hate him further because of his dreams and words. Their reaction intensifies the family conflict.",
    "refs": [
      "Genesis 37:4–5"
    ]
  },
  "Genesis 37:9": {
    "title": "The sun, moon, and stars",
    "text": "Joseph dreams that the sun, moon, and eleven stars bow to him. The symbols extend the dream to his family, and Jacob later questions its meaning while continuing to remember it.",
    "refs": [
      "Genesis 37:10–11"
    ]
  },
  "Genesis 37:10": {
    "title": "Jacob rebukes Joseph",
    "text": "Jacob asks whether he, Joseph’s mother, and his brothers will bow before him. The verse records Jacob’s response to the dream; the imagery is later echoed in Joseph’s rise in Egypt.",
    "refs": [
      "Genesis 42:6"
    ]
  },
  "Genesis 37:11": {
    "title": "Jacob remembers the matter",
    "text": "Joseph’s brothers envy him, while Jacob observes the saying. The contrast shows that Jacob does not dismiss the dream outright, though its meaning is not yet clear.",
    "refs": [
      "Luke 2:19"
    ]
  },
  "Genesis 37:12": {
    "title": "The brothers go to Shechem",
    "text": "Joseph’s brothers take their father’s flock to feed near Shechem. The location connects this episode to the region where the family had previously experienced conflict.",
    "refs": [
      "Genesis 34:25–30"
    ]
  },
  "Genesis 37:13": {
    "title": "Jacob sends Joseph",
    "text": "Jacob asks Joseph to go see whether his brothers and the flock are well. Joseph answers that he is ready to go, unaware of the danger ahead.",
    "refs": [
      "Genesis 37:18"
    ]
  },
  "Genesis 37:14": {
    "title": "Joseph sent from Hebron",
    "text": "Jacob sends Joseph from the valley of Hebron to Shechem and asks him to return with news. The journey becomes the path to Joseph’s betrayal and eventual rise in Egypt.",
    "refs": [
      "Genesis 37:28"
    ]
  },
  "Genesis 37:15": {
    "title": "A man finds Joseph wandering",
    "text": "A man finds Joseph wandering in the field and asks what he is seeking. The encounter redirects Joseph toward his brothers’ location.",
    "refs": [
      "Genesis 37:16–17"
    ]
  },
  "Genesis 37:16": {
    "title": "Joseph asks for his brothers",
    "text": "Joseph says he is looking for his brothers and asks where they are feeding the flock. He continues his assigned task despite the uncertainty of their location.",
    "refs": [
      "Genesis 37:14"
    ]
  },
  "Genesis 37:17": {
    "title": "Joseph is directed to Dothan",
    "text": "The man says the brothers have moved to Dothan. Joseph follows the information and finds them there, bringing him into the situation they will exploit.",
    "refs": [
      "Genesis 37:18"
    ]
  },
  "Genesis 37:18": {
    "title": "The brothers plot against Joseph",
    "text": "The brothers see Joseph from afar and conspire to kill him before he reaches them. Their hatred has grown into a deliberate plan for violence.",
    "refs": [
      "Genesis 37:4–5"
    ]
  },
  "Genesis 37:19": {
    "title": "The dreamer approaches",
    "text": "The brothers mock Joseph as the dreamer. Their words show contempt for his dreams and for the possibility that he might one day rule over them.",
    "refs": [
      "Genesis 37:8"
    ]
  },
  "Genesis 37:20": {
    "title": "They plan to kill and lie",
    "text": "The brothers propose killing Joseph, throwing him into a pit, and claiming a wild animal devoured him. Their plan includes both violence and a deliberate lie to their father.",
    "refs": [
      "Genesis 37:31–33"
    ]
  },
  "Genesis 37:21": {
    "title": "Reuben intervenes",
    "text": "Reuben hears the plan and tries to save Joseph from being killed. He proposes a less immediately violent course, intending to rescue Joseph later.",
    "refs": [
      "Genesis 37:22"
    ]
  },
  "Genesis 37:22": {
    "title": "Do not shed blood",
    "text": "Reuben tells the brothers not to kill Joseph but to cast him into a pit. The narrator explains that Reuben intends to return and rescue him, although the plan still leaves Joseph in danger.",
    "refs": [
      "Genesis 37:29–30"
    ]
  },
  "Genesis 37:23": {
    "title": "Joseph’s coat is taken",
    "text": "When Joseph arrives, his brothers strip off the special coat his father gave him. Their action attacks the visible sign of Jacob’s favoritism.",
    "refs": [
      "Genesis 37:3–4"
    ]
  },
  "Genesis 37:24": {
    "title": "Joseph is thrown into a pit",
    "text": "The brothers cast Joseph into an empty pit with no water. The action exposes his vulnerability and the cruelty of his brothers’ treatment.",
    "refs": [
      "Genesis 42:21"
    ]
  },
  "Genesis 37:25": {
    "title": "The brothers eat as traders approach",
    "text": "The brothers sit down to eat and see a caravan of Ishmaelites coming from Gilead toward Egypt. Their ordinary meal beside the pit contrasts with Joseph’s distress.",
    "refs": [
      "Genesis 37:28"
    ]
  },
  "Genesis 37:26": {
    "title": "Judah proposes selling Joseph",
    "text": "Judah asks what profit there is in killing their brother and hiding his blood. He proposes selling Joseph to the traders, preventing murder but still treating Joseph as property.",
    "refs": [
      "Genesis 37:27–28"
    ]
  },
  "Genesis 37:27": {
    "title": "Joseph sold rather than killed",
    "text": "Judah suggests selling Joseph to the Ishmaelites and not laying hands on him because he is their brother. The decision spares Joseph’s life but remains a grave betrayal.",
    "refs": [
      "Genesis 42:21"
    ]
  },
  "Genesis 37:28": {
    "title": "Joseph is sold into Egypt",
    "text": "The traders draw Joseph from the pit and sell him for twenty pieces of silver, taking him to Egypt. God’s providence will later bring good from this wrong, but the sale itself is the brothers’ sin.",
    "refs": [
      "Genesis 50:20"
    ]
  },
  "Genesis 37:29": {
    "title": "Reuben finds Joseph gone",
    "text": "Reuben returns to the pit and discovers Joseph is missing. He tears his clothes in grief, realizing that his intended rescue has failed.",
    "refs": [
      "Genesis 37:22"
    ]
  },
  "Genesis 37:30": {
    "title": "Reuben fears the consequences",
    "text": "Reuben asks where he can go, distressed over what has happened to Joseph. The verse captures his alarm and his awareness that the family has committed a terrible wrong.",
    "refs": [
      "Genesis 42:22"
    ]
  },
  "Genesis 37:31": {
    "title": "The coat is stained",
    "text": "The brothers kill a goat and dip Joseph’s coat in its blood. They prepare false evidence to make Jacob believe Joseph has been killed by an animal.",
    "refs": [
      "Genesis 37:32–33"
    ]
  },
  "Genesis 37:32": {
    "title": "A deceptive message to Jacob",
    "text": "The brothers send the bloodied coat to Jacob and ask him to identify it. Their message avoids directly stating a lie, but it is designed to mislead their father.",
    "refs": [
      "Genesis 37:33"
    ]
  },
  "Genesis 37:33": {
    "title": "Jacob believes Joseph is dead",
    "text": "Jacob recognizes the coat and concludes that a wild beast has devoured Joseph. He accepts the false account because he has been shown misleading evidence.",
    "refs": [
      "Genesis 37:31–32"
    ]
  },
  "Genesis 37:34": {
    "title": "Jacob mourns deeply",
    "text": "Jacob tears his clothes, puts on sackcloth, and mourns Joseph for many days. The grief shows the human cost of the brothers’ deception.",
    "refs": [
      "Genesis 42:36"
    ]
  },
  "Genesis 37:35": {
    "title": "Jacob refuses comfort",
    "text": "Jacob’s family tries to comfort him, but he continues mourning and says he will go down to the grave grieving for Joseph. The verse describes intense grief, not a denial of God’s faithfulness.",
    "refs": [
      "Genesis 42:38"
    ]
  },
  "Genesis 37:36": {
    "title": "Joseph sold to Potiphar",
    "text": "The Midianites sell Joseph in Egypt to Potiphar, an officer of Pharaoh. Joseph’s circumstances have changed dramatically, but this is the beginning of the path through which he will later preserve his family.",
    "refs": [
      "Genesis 39:1",
      "Genesis 50:20"
    ]
  },
  "Genesis 38:1": {
    "title": "Judah separates from his brothers",
    "text": "Judah leaves his brothers and stays with an Adullamite named Hirah. The narrative temporarily follows Judah’s family line while Joseph is in Egypt.",
    "refs": [
      "Genesis 37:26–28"
    ]
  },
  "Genesis 38:2": {
    "title": "Judah marries a Canaanite woman",
    "text": "Judah sees the daughter of a Canaanite and takes her as wife. The text records the marriage without giving a direct judgment in this verse.",
    "refs": [
      "Genesis 24:3–4"
    ]
  },
  "Genesis 38:3": {
    "title": "Er is born",
    "text": "Judah’s wife conceives and bears a son named Er. The genealogy begins to trace the family through which the later events in this chapter unfold.",
    "refs": [
      "Genesis 38:6"
    ]
  },
  "Genesis 38:4": {
    "title": "Onan is born",
    "text": "Judah’s wife bears another son and names him Onan. The account continues recording Judah’s descendants.",
    "refs": [
      "Genesis 38:8"
    ]
  },
  "Genesis 38:5": {
    "title": "Shelah is born",
    "text": "She bears a third son, Shelah, at Chezib. The birth completes the three sons named before the story turns to Judah’s marriage arrangements for Er.",
    "refs": [
      "Genesis 38:11"
    ]
  },
  "Genesis 38:6": {
    "title": "Tamar becomes Er’s wife",
    "text": "Judah takes a wife for Er, his firstborn, and her name is Tamar. Her role becomes central when Er dies and the family’s obligations toward her are neglected.",
    "refs": [
      "Genesis 38:7–11"
    ]
  },
  "Genesis 38:7": {
    "title": "Er’s wickedness",
    "text": "Er is wicked in the sight of the LORD, and the LORD puts him to death. The verse gives no detailed description of his wrongdoing, so readers should not invent one.",
    "refs": [
      "Genesis 38:8"
    ]
  },
  "Genesis 38:8": {
    "title": "Onan’s duty toward Tamar",
    "text": "Judah tells Onan to marry his brother’s widow and raise offspring for his brother. This reflects the family duty later formalized in Israel’s levirate marriage law.",
    "refs": [
      "Deuteronomy 25:5–6"
    ]
  },
  "Genesis 38:9": {
    "title": "Onan refuses to provide an heir",
    "text": "Onan knows the offspring will not be counted as his and deliberately prevents conception while still taking Tamar as a wife. His sin in the passage is bound up with refusing the family duty while exploiting the relationship.",
    "refs": [
      "Genesis 38:8"
    ]
  },
  "Genesis 38:10": {
    "title": "The LORD judges Onan",
    "text": "The LORD puts Onan to death because of what he did. The text identifies God’s judgment but does not give permission to generalize this event into a rule about every circumstance of contraception.",
    "refs": [
      "Genesis 38:9"
    ]
  },
  "Genesis 38:11": {
    "title": "Judah sends Tamar away",
    "text": "Judah tells Tamar to live as a widow in her father’s house until Shelah grows up, while fearing Shelah may also die. Tamar returns to her father’s house, but Judah does not fulfill the expectation he has created.",
    "refs": [
      "Genesis 38:14"
    ]
  },
  "Genesis 38:12": {
    "title": "Judah’s wife dies",
    "text": "After a time, Judah’s wife dies, and after his mourning he travels to Timnah with Hirah to oversee the shearing of his sheep. The change in circumstances leads to Tamar’s plan.",
    "refs": [
      "Genesis 38:13"
    ]
  },
  "Genesis 38:13": {
    "title": "Tamar hears Judah is traveling",
    "text": "Tamar is told that Judah is going to Timnah to shear his sheep. She recognizes an opportunity to address the failure to give her Shelah as promised.",
    "refs": [
      "Genesis 38:14"
    ]
  },
  "Genesis 38:14": {
    "title": "Tamar removes her widow’s garments",
    "text": "Tamar covers herself and sits by the road because she sees that Shelah has grown and she has not been given to him. The verse presents her action as a response to Judah’s failure, though the ensuing deception remains complex.",
    "refs": [
      "Genesis 38:11"
    ]
  },
  "Genesis 38:15": {
    "title": "Judah mistakes Tamar for a harlot",
    "text": "Judah sees Tamar with her face covered and assumes she is a prostitute. His assumption reveals how he interprets what he sees without knowing her identity.",
    "refs": [
      "Genesis 38:16"
    ]
  },
  "Genesis 38:16": {
    "title": "Judah negotiates with Tamar",
    "text": "Judah turns aside to her and offers payment for sex, not knowing she is his daughter-in-law. The narrative exposes Judah’s hypocrisy and his failure to recognize Tamar.",
    "refs": [
      "Genesis 38:26"
    ]
  },
  "Genesis 38:17": {
    "title": "Judah promises a young goat",
    "text": "Judah says he will send a young goat from the flock, and Tamar asks for a pledge until it arrives. The exchange establishes evidence that will later identify the father of her children.",
    "refs": [
      "Genesis 38:18"
    ]
  },
  "Genesis 38:18": {
    "title": "The pledge is given",
    "text": "Judah gives Tamar his seal, cord, and staff as pledges. These personal objects will later make his identity unmistakable.",
    "refs": [
      "Genesis 38:25"
    ]
  },
  "Genesis 38:19": {
    "title": "Tamar returns to widow’s clothing",
    "text": "Tamar leaves, removes her covering, and puts her widow’s garments back on. She returns to her public status as a widow while keeping the pledges.",
    "refs": [
      "Genesis 38:14"
    ]
  },
  "Genesis 38:20": {
    "title": "Judah sends the promised goat",
    "text": "Judah sends the young goat through Hirah to recover the pledge, but Tamar cannot be found. The failed search sets up the public revelation of the pledge.",
    "refs": [
      "Genesis 38:21–23"
    ]
  },
  "Genesis 38:21": {
    "title": "The local people know no prostitute",
    "text": "Hirah asks the men of the place where the woman by the road is, but they say no such prostitute was there. The search cannot locate Tamar or recover Judah’s pledge.",
    "refs": [
      "Genesis 38:20"
    ]
  },
  "Genesis 38:22": {
    "title": "Hirah reports the failure",
    "text": "Hirah returns to Judah and says he could not find the woman and that the local men denied she was there. The evidence remains with Tamar.",
    "refs": [
      "Genesis 38:18"
    ]
  },
  "Genesis 38:23": {
    "title": "Judah says to let her keep the pledge",
    "text": "Judah says to let her keep the items so they will not be shamed, adding that he tried to send the goat. He is more concerned with avoiding public embarrassment than with uncovering what happened.",
    "refs": [
      "Genesis 38:25–26"
    ]
  },
  "Genesis 38:24": {
    "title": "Tamar is accused",
    "text": "About three months later, Judah is told that Tamar has played the harlot and is pregnant. Judah orders her to be brought out and burned, a harsh judgment that he will soon have to reconsider.",
    "refs": [
      "Genesis 38:25"
    ]
  },
  "Genesis 38:25": {
    "title": "Tamar produces the pledge",
    "text": "As Tamar is brought out, she sends Judah’s seal, cord, and staff and asks him to identify their owner. The evidence forces Judah to confront his own involvement.",
    "refs": [
      "Genesis 38:18"
    ]
  },
  "Genesis 38:26": {
    "title": "Judah admits he was wrong",
    "text": "Judah recognizes the items and admits Tamar is more righteous than he is because he did not give her to Shelah. His confession marks a moral turning point in the story.",
    "refs": [
      "Genesis 38:11"
    ]
  },
  "Genesis 38:27": {
    "title": "Twins are found in Tamar’s womb",
    "text": "When Tamar gives birth, it is discovered that she is carrying twins. The unusual birth scene leads to a struggle over which child will emerge first.",
    "refs": [
      "Genesis 25:24–26"
    ]
  },
  "Genesis 38:28": {
    "title": "The scarlet thread",
    "text": "A hand comes out first, and the midwife ties a scarlet thread on it to identify the firstborn. The marker sets up the surprising reversal in the birth order.",
    "refs": [
      "Genesis 38:29"
    ]
  },
  "Genesis 38:29": {
    "title": "Perez breaks through",
    "text": "The hand withdraws and the other child comes out first, so he is named Perez, meaning breach or breaking forth. The name preserves the unexpected order of the twins’ birth.",
    "refs": [
      "Ruth 4:18–22"
    ]
  },
  "Genesis 38:30": {
    "title": "Zerah is born after Perez",
    "text": "The child with the scarlet thread comes out and is named Zerah. The chapter closes with the twins’ names, and the line of Perez later becomes significant in the genealogy of David and Jesus.",
    "refs": [
      "Ruth 4:18–22",
      "Matthew 1:3"
    ]
  },
  "Genesis 39:1": {
    "title": "Joseph is brought to Egypt",
    "text": "Joseph is taken to Egypt and sold to Potiphar, an officer of Pharaoh. The account follows Joseph from betrayal into slavery, where God’s presence will sustain him.",
    "refs": [
      "Genesis 37:36"
    ]
  },
  "Genesis 39:2": {
    "title": "The LORD is with Joseph",
    "text": "The LORD is with Joseph, and he prospers in Potiphar’s house. His circumstances are unjust, but the text emphasizes that God has not abandoned him.",
    "refs": [
      "Genesis 28:15"
    ]
  },
  "Genesis 39:3": {
    "title": "Potiphar sees God’s favor",
    "text": "Potiphar observes that the LORD is with Joseph and makes his work prosper. Joseph’s conduct makes God’s help visible to someone outside his family.",
    "refs": [
      "Genesis 30:27"
    ]
  },
  "Genesis 39:4": {
    "title": "Joseph receives responsibility",
    "text": "Joseph finds favor with Potiphar, who makes him overseer of the house and entrusts his possessions to him. Joseph serves faithfully even in an unjust situation.",
    "refs": [
      "Luke 16:10"
    ]
  },
  "Genesis 39:5": {
    "title": "God blesses Potiphar’s household",
    "text": "The LORD blesses the Egyptian’s house because of Joseph, including his possessions in the house and field. This echoes the promise that blessing would reach others through Abraham’s family.",
    "refs": [
      "Genesis 12:3"
    ]
  },
  "Genesis 39:6": {
    "title": "Joseph’s trusted stewardship",
    "text": "Potiphar leaves his affairs in Joseph’s care and concerns himself only with his food. Joseph is described as handsome, a detail that introduces the temptation and conflict that follow.",
    "refs": [
      "Genesis 39:7"
    ]
  },
  "Genesis 39:7": {
    "title": "Potiphar’s wife tempts Joseph",
    "text": "Potiphar’s wife asks Joseph to lie with her. The text presents the request as temptation and begins a test of Joseph’s integrity.",
    "refs": [
      "Genesis 39:8–9"
    ]
  },
  "Genesis 39:8": {
    "title": "Joseph refuses",
    "text": "Joseph refuses and explains that Potiphar has trusted him with everything in the house. He recognizes the responsibility he has been given and does not exploit his master’s trust.",
    "refs": [
      "Proverbs 6:32"
    ]
  },
  "Genesis 39:9": {
    "title": "Joseph names the sin against God",
    "text": "Joseph says no one in the house has greater authority than he does except Potiphar, and he asks how he could do this great wickedness and sin against God. His refusal is grounded in faithfulness to God, not merely fear of punishment.",
    "refs": [
      "Psalm 51:4"
    ]
  },
  "Genesis 39:10": {
    "title": "Joseph resists repeated temptation",
    "text": "Potiphar’s wife speaks to Joseph day after day, but he does not listen or lie with her. The verse shows that resisting temptation can require a continued, deliberate refusal.",
    "refs": [
      "Proverbs 1:10"
    ]
  },
  "Genesis 39:11": {
    "title": "Joseph enters the house to work",
    "text": "One day Joseph enters the house to do his work when no other men are inside. The circumstances create a moment of vulnerability that he did not seek.",
    "refs": [
      "Genesis 39:12"
    ]
  },
  "Genesis 39:12": {
    "title": "Joseph flees the temptation",
    "text": "Potiphar’s wife grabs Joseph’s garment and again urges him to lie with her, but he flees and leaves the garment behind. Joseph chooses escape rather than remaining in a dangerous situation.",
    "refs": [
      "2 Timothy 2:22"
    ]
  },
  "Genesis 39:13": {
    "title": "The garment becomes evidence",
    "text": "When the woman sees Joseph has fled and left his garment, she begins to shape a false accusation. The garment, previously a sign of Joseph’s identity in his brothers’ deception, again becomes part of a misleading story.",
    "refs": [
      "Genesis 37:31–33"
    ]
  },
  "Genesis 39:14": {
    "title": "Potiphar’s wife accuses Joseph",
    "text": "She calls the household servants and claims Joseph was brought in to mock them. Her accusation twists the truth and presents Joseph as the aggressor.",
    "refs": [
      "Genesis 39:17–18"
    ]
  },
  "Genesis 39:15": {
    "title": "She repeats the false account",
    "text": "The woman says Joseph left his garment and fled when she cried out. She uses the physical evidence to support a story that reverses what actually happened.",
    "refs": [
      "Genesis 39:12"
    ]
  },
  "Genesis 39:16": {
    "title": "The garment is kept",
    "text": "She lays Joseph’s garment beside her until Potiphar comes home. The retained garment becomes a prop in the accusation.",
    "refs": [
      "Genesis 39:13"
    ]
  },
  "Genesis 39:17": {
    "title": "The accusation is made to Potiphar",
    "text": "Potiphar’s wife repeats her claim that Joseph came to mock the household. Her version omits her own repeated advances and Joseph’s refusal.",
    "refs": [
      "Genesis 39:7–12"
    ]
  },
  "Genesis 39:18": {
    "title": "A false charge repeated",
    "text": "She says she cried out and Joseph left his garment. The repeated account does not make it true; the reader has already been told what really happened.",
    "refs": [
      "Genesis 39:12"
    ]
  },
  "Genesis 39:19": {
    "title": "Potiphar becomes angry",
    "text": "Potiphar hears his wife’s account and becomes angry. The text does not specify the full extent of his belief or his private reasoning, so it is best not to claim more than it says.",
    "refs": [
      "Genesis 39:20"
    ]
  },
  "Genesis 39:20": {
    "title": "Joseph is imprisoned",
    "text": "Potiphar puts Joseph in the prison where the king’s prisoners are kept. Joseph suffers for doing what was right, but God’s presence continues through the next stage of his life.",
    "refs": [
      "Psalm 105:17–19"
    ]
  },
  "Genesis 39:21": {
    "title": "The LORD shows mercy in prison",
    "text": "The LORD is with Joseph, shows him mercy, and gives him favor with the keeper of the prison. Joseph’s circumstances change, but God’s faithful presence remains.",
    "refs": [
      "Genesis 39:2–3"
    ]
  },
  "Genesis 39:22": {
    "title": "Joseph is entrusted with prisoners",
    "text": "The prison keeper places the prisoners under Joseph’s care and allows him to manage their affairs. Joseph continues to serve responsibly even while wrongfully confined.",
    "refs": [
      "Genesis 39:4"
    ]
  },
  "Genesis 39:23": {
    "title": "God makes Joseph’s work prosper",
    "text": "The keeper does not supervise everything Joseph handles because the LORD is with him and makes his work prosper. The repeated statement highlights God’s presence through slavery and imprisonment.",
    "refs": [
      "Genesis 39:2"
    ]
  },
  "Genesis 40:1": {
    "title": "Two royal servants offend Pharaoh",
    "text": "The chief butler and chief baker offend Pharaoh, king of Egypt. Their story brings Joseph into contact with people who will later connect him to Pharaoh.",
    "refs": [
      "Genesis 41:9–14"
    ]
  },
  "Genesis 40:2": {
    "title": "Pharaoh becomes angry",
    "text": "Pharaoh is angry with his two officers. The verse introduces the royal response that leads to their imprisonment.",
    "refs": [
      "Genesis 40:1"
    ]
  },
  "Genesis 40:3": {
    "title": "The officers are confined",
    "text": "Pharaoh places the officers in the prison where Joseph is held, under the captain of the guard. Their arrival creates the setting for Joseph to interpret their dreams.",
    "refs": [
      "Genesis 39:20"
    ]
  },
  "Genesis 40:4": {
    "title": "Joseph serves the officers",
    "text": "The captain of the guard assigns Joseph to attend the two officers, and they remain in custody for a time. Joseph’s faithful service continues even in prison.",
    "refs": [
      "Genesis 39:22–23"
    ]
  },
  "Genesis 40:5": {
    "title": "Both men dream",
    "text": "The butler and baker each dream on the same night, each with a distinct meaning. The dreams are central to the narrative, but their meanings will be revealed by God through Joseph.",
    "refs": [
      "Genesis 40:8"
    ]
  },
  "Genesis 40:6": {
    "title": "Joseph sees their distress",
    "text": "Joseph comes to the officers in the morning and sees that they are troubled. He pays attention to their emotional state rather than ignoring their distress.",
    "refs": [
      "Genesis 40:7"
    ]
  },
  "Genesis 40:7": {
    "title": "Joseph asks what is wrong",
    "text": "Joseph asks Pharaoh’s officers why they look so sad. Even while imprisoned, he shows concern for others and initiates a conversation.",
    "refs": [
      "Philippians 2:4"
    ]
  },
  "Genesis 40:8": {
    "title": "Interpretations belong to God",
    "text": "The men say they have had dreams with no interpreter. Joseph answers that interpretations belong to God and asks them to tell him the dreams. This is an explicit confession that the insight he offers is dependent on God, not personal magic.",
    "refs": [
      "Daniel 2:27–28"
    ]
  },
  "Genesis 40:9": {
    "title": "The butler tells his dream",
    "text": "The chief butler describes a vine before him with three branches. The dream’s imagery begins a sequence that Joseph interprets in the following verses.",
    "refs": [
      "Genesis 40:10–13"
    ]
  },
  "Genesis 40:10": {
    "title": "The vine and grapes",
    "text": "The butler sees the vine bud, blossom, and produce ripe grapes. The sequence of rapid growth forms the basis of Joseph’s interpretation of a quick restoration.",
    "refs": [
      "Genesis 40:12–13"
    ]
  },
  "Genesis 40:11": {
    "title": "The cup in Pharaoh’s hand",
    "text": "The butler says he took the grapes, pressed them into Pharaoh’s cup, and placed the cup in Pharaoh’s hand. The dream imagery reflects the butler’s royal service.",
    "refs": [
      "Genesis 40:13"
    ]
  },
  "Genesis 40:12": {
    "title": "Three branches mean three days",
    "text": "Joseph interprets the three branches as three days. He presents the meaning confidently, as a message he understands through God’s gift.",
    "refs": [
      "Genesis 40:8"
    ]
  },
  "Genesis 40:13": {
    "title": "The butler will be restored",
    "text": "Joseph says that within three days Pharaoh will restore the butler to his office, and he will again put the cup into Pharaoh’s hand. The interpretation predicts a return to the role depicted in the dream.",
    "refs": [
      "Genesis 40:20–21"
    ]
  },
  "Genesis 40:14": {
    "title": "Joseph asks to be remembered",
    "text": "Joseph asks the butler to remember him, show kindness, and mention him to Pharaoh so he can be released. Joseph’s request shows that faith in God does not prevent him from seeking practical help.",
    "refs": [
      "Genesis 40:23"
    ]
  },
  "Genesis 40:15": {
    "title": "Joseph explains his innocence",
    "text": "Joseph says he was stolen from the land of the Hebrews and has done nothing deserving prison in Egypt. His words describe his suffering and his claim that his imprisonment is unjust.",
    "refs": [
      "Genesis 37:28",
      "Genesis 39:20"
    ]
  },
  "Genesis 40:16": {
    "title": "The baker hears the interpretation",
    "text": "The chief baker sees that Joseph’s interpretation of the butler’s dream is favorable and tells his own dream. He hopes for a similar outcome, but the dreams will have different meanings.",
    "refs": [
      "Genesis 40:18–19"
    ]
  },
  "Genesis 40:17": {
    "title": "Baskets of baked food",
    "text": "The baker describes three baskets of white bread on his head, with food for Pharaoh in the top basket, which birds eat. The image sets up a contrasting interpretation to the butler’s dream.",
    "refs": [
      "Genesis 40:18–19"
    ]
  },
  "Genesis 40:18": {
    "title": "Three baskets mean three days",
    "text": "Joseph says the three baskets also represent three days. Similar imagery does not mean the outcomes are identical; Joseph proceeds to give a different interpretation.",
    "refs": [
      "Genesis 40:19"
    ]
  },
  "Genesis 40:19": {
    "title": "The baker will be executed",
    "text": "Joseph says that within three days Pharaoh will lift the baker’s head from him and hang him on a tree, and birds will eat his flesh. The message is severe, but Joseph reports the interpretation rather than changing it to please the listener.",
    "refs": [
      "Genesis 40:20–22"
    ]
  },
  "Genesis 40:20": {
    "title": "Pharaoh’s birthday",
    "text": "On Pharaoh’s birthday, he makes a feast and brings the butler and baker out of prison. The event unfolds exactly on the time frame Joseph described.",
    "refs": [
      "Genesis 40:13, 19"
    ]
  },
  "Genesis 40:21": {
    "title": "The butler is restored",
    "text": "Pharaoh restores the chief butler to his former position, and he again gives Pharaoh the cup. The first interpretation is fulfilled.",
    "refs": [
      "Genesis 40:13"
    ]
  },
  "Genesis 40:22": {
    "title": "The baker is executed",
    "text": "Pharaoh hangs the chief baker, as Joseph had interpreted. The contrasting outcomes confirm the distinct meanings of the two dreams within the narrative.",
    "refs": [
      "Genesis 40:19"
    ]
  },
  "Genesis 40:23": {
    "title": "The butler forgets Joseph",
    "text": "The chief butler does not remember Joseph but forgets him. Joseph remains in prison longer, yet the delay sets the stage for his eventual appearance before Pharaoh.",
    "refs": [
      "Genesis 41:9–14"
    ]
  },
  "Genesis 41:1": {
    "title": "Pharaoh dreams after two years",
    "text": "Two full years pass before Pharaoh dreams of standing by the Nile. Joseph remains forgotten in prison, but the timing of Pharaoh’s dream brings the next change in his life.",
    "refs": [
      "Genesis 40:23"
    ]
  },
  "Genesis 41:2": {
    "title": "Seven healthy cows",
    "text": "Pharaoh sees seven beautiful, fat cows come up from the river and feed in the meadow. The dream’s imagery is tied to Egypt’s agricultural life and the Nile.",
    "refs": [
      "Genesis 41:17–18"
    ]
  },
  "Genesis 41:3": {
    "title": "Seven thin cows appear",
    "text": "Seven other cows, ugly and thin, come up after the first cows. Their contrast signals a troubling reversal within the dream.",
    "refs": [
      "Genesis 41:19"
    ]
  },
  "Genesis 41:4": {
    "title": "The thin cows consume the fat cows",
    "text": "The thin cows eat the seven fat cows, but remain thin. The unusual image leaves Pharaoh troubled and needing an interpretation.",
    "refs": [
      "Genesis 41:21"
    ]
  },
  "Genesis 41:5": {
    "title": "A second dream of grain",
    "text": "Pharaoh sleeps again and dreams of seven full ears of grain growing on one stalk. The second dream repeats the pattern of abundance.",
    "refs": [
      "Genesis 41:22"
    ]
  },
  "Genesis 41:6": {
    "title": "Seven thin ears scorched by wind",
    "text": "Seven thin ears blasted by the east wind grow after the full ears. The image foreshadows hardship following a period of plenty.",
    "refs": [
      "Genesis 41:23"
    ]
  },
  "Genesis 41:7": {
    "title": "The thin ears swallow the full ears",
    "text": "The thin ears consume the full ears, and Pharaoh awakens. The two dreams share a pattern that will be explained as one message.",
    "refs": [
      "Genesis 41:25–32"
    ]
  },
  "Genesis 41:8": {
    "title": "Egypt’s wise men cannot interpret",
    "text": "In the morning Pharaoh is troubled and summons Egypt’s magicians and wise men, but none can interpret the dreams. Human expertise fails to supply the answer Pharaoh needs.",
    "refs": [
      "Daniel 2:1–11"
    ]
  },
  "Genesis 41:9": {
    "title": "The butler remembers Joseph",
    "text": "The chief butler remembers his failures and tells Pharaoh about the young Hebrew imprisoned with him. The forgotten prisoner is brought back to mind at the moment his help is needed.",
    "refs": [
      "Genesis 40:14, 23"
    ]
  },
  "Genesis 41:10": {
    "title": "Pharaoh imprisoned his servants",
    "text": "The butler recalls Pharaoh’s anger and the imprisonment of himself and the chief baker. He sets the context for the dreams Joseph interpreted accurately.",
    "refs": [
      "Genesis 40:1–5"
    ]
  },
  "Genesis 41:11": {
    "title": "Each man dreamed",
    "text": "The butler recounts that he and the baker dreamed on the same night, each with a distinct meaning. Their experience gives Pharaoh a reason to hear Joseph’s ability.",
    "refs": [
      "Genesis 40:5"
    ]
  },
  "Genesis 41:12": {
    "title": "A Hebrew servant interprets",
    "text": "The butler remembers a Hebrew young man, servant to the captain of the guard, who interpreted their dreams. Joseph’s background is stated plainly, while the narrative shows God’s gift at work beyond Egypt’s official experts.",
    "refs": [
      "Genesis 40:8"
    ]
  },
  "Genesis 41:13": {
    "title": "The dreams came true",
    "text": "The butler says the events occurred as Joseph interpreted: he was restored and the baker was executed. The accuracy of the earlier interpretations supports bringing Joseph before Pharaoh.",
    "refs": [
      "Genesis 40:20–22"
    ]
  },
  "Genesis 41:14": {
    "title": "Joseph is brought from prison",
    "text": "Pharaoh sends for Joseph, who is quickly brought out, shaved, and given clean clothes before entering the royal presence. His sudden change in circumstance follows years of suffering and waiting.",
    "refs": [
      "Psalm 105:17–20"
    ]
  },
  "Genesis 41:15": {
    "title": "Pharaoh asks Joseph to interpret",
    "text": "Pharaoh says he has heard Joseph can understand a dream when he hears it. Joseph is given the opportunity to explain the dreams before the king.",
    "refs": [
      "Genesis 41:25"
    ]
  },
  "Genesis 41:16": {
    "title": "Joseph gives God the credit",
    "text": "Joseph answers that the interpretation is not from himself but that God will give Pharaoh an answer of peace. He refuses to present himself as the source of supernatural insight.",
    "refs": [
      "Genesis 40:8",
      "Daniel 2:27–28"
    ]
  },
  "Genesis 41:17": {
    "title": "Pharaoh recounts the dream",
    "text": "Pharaoh describes standing by the river and seeing the cows emerge. The repetition of the dream establishes the details Joseph will interpret.",
    "refs": [
      "Genesis 41:1–4"
    ]
  },
  "Genesis 41:18": {
    "title": "The fat cows feed",
    "text": "Pharaoh recalls the seven healthy cows feeding in the meadow. The detail represents the coming years of abundance in Joseph’s interpretation.",
    "refs": [
      "Genesis 41:29"
    ]
  },
  "Genesis 41:19": {
    "title": "The ugly cows",
    "text": "Pharaoh describes seven thin, ugly cows unlike any he had seen in Egypt. Their extreme condition signals an exceptional period of famine.",
    "refs": [
      "Genesis 41:30"
    ]
  },
  "Genesis 41:20": {
    "title": "The thin cows eat the fat cows",
    "text": "The thin cows consume the healthy cows. The image conveys how severe scarcity will overwhelm the memory of earlier abundance.",
    "refs": [
      "Genesis 41:30–31"
    ]
  },
  "Genesis 41:21": {
    "title": "The cows remain thin",
    "text": "After consuming the fat cows, the thin cows look no better. The dream emphasizes the severity of the famine rather than a temporary shortage.",
    "refs": [
      "Genesis 41:31"
    ]
  },
  "Genesis 41:22": {
    "title": "The full ears of grain",
    "text": "Pharaoh recounts the second dream with seven full ears growing on one stalk. The dream repeats the theme of abundant food before scarcity.",
    "refs": [
      "Genesis 41:26"
    ]
  },
  "Genesis 41:23": {
    "title": "The thin ears are blasted",
    "text": "Pharaoh describes seven thin ears, withered and scorched by the east wind. The imagery reinforces the coming loss of agricultural production.",
    "refs": [
      "Genesis 41:27"
    ]
  },
  "Genesis 41:24": {
    "title": "The wise men fail again",
    "text": "Pharaoh says the thin ears swallowed the good ears, but none of the wise men could explain it. Joseph’s interpretation will make clear that the two dreams communicate the same warning.",
    "refs": [
      "Genesis 41:8"
    ]
  },
  "Genesis 41:25": {
    "title": "One message from God",
    "text": "Joseph says Pharaoh’s dreams have one meaning and that God has shown Pharaoh what He is about to do. Joseph explicitly identifies God as the source of the warning.",
    "refs": [
      "Amos 3:7"
    ]
  },
  "Genesis 41:26": {
    "title": "Seven years of abundance",
    "text": "Joseph explains that the seven good cows and seven good ears represent seven years. The repeated number confirms the unified meaning of the two dreams.",
    "refs": [
      "Genesis 41:29"
    ]
  },
  "Genesis 41:27": {
    "title": "Seven years of famine",
    "text": "The seven thin cows and seven empty ears represent seven years of famine. The east wind image belongs to the dream’s agricultural symbolism.",
    "refs": [
      "Genesis 41:30"
    ]
  },
  "Genesis 41:28": {
    "title": "God has revealed what He will do",
    "text": "Joseph repeats that God has shown Pharaoh what is coming. The interpretation is presented as divine disclosure, not Joseph’s guesswork.",
    "refs": [
      "Genesis 41:25"
    ]
  },
  "Genesis 41:29": {
    "title": "Great plenty throughout Egypt",
    "text": "Joseph predicts seven years of great abundance throughout Egypt. The coming years will provide an opportunity to prepare for the famine.",
    "refs": [
      "Genesis 41:47"
    ]
  },
  "Genesis 41:30": {
    "title": "Famine follows the plenty",
    "text": "Joseph says seven years of famine will follow, and the abundance will be forgotten. The warning explains why preparation during good years is essential.",
    "refs": [
      "Proverbs 6:6–8"
    ]
  },
  "Genesis 41:31": {
    "title": "The famine will be severe",
    "text": "The famine will be so severe that the earlier plenty will not be remembered. Joseph emphasizes the seriousness of the coming crisis.",
    "refs": [
      "Genesis 41:30"
    ]
  },
  "Genesis 41:32": {
    "title": "The doubled dream confirms certainty",
    "text": "Joseph says the dream was doubled because the matter is established by God and will soon happen. The doubling confirms the certainty of the warning within the narrative.",
    "refs": [
      "Genesis 41:25"
    ]
  },
  "Genesis 41:33": {
    "title": "Pharaoh should appoint a wise man",
    "text": "Joseph advises Pharaoh to choose a discerning and wise man to oversee Egypt. He moves from interpretation to practical planning rather than stopping at prediction.",
    "refs": [
      "Proverbs 24:3–4"
    ]
  },
  "Genesis 41:34": {
    "title": "Officials should be appointed",
    "text": "Joseph advises appointing officers to collect a fifth of the produce during the seven plentiful years. The plan is an administrative proposal for storing food before the famine.",
    "refs": [
      "Genesis 41:48"
    ]
  },
  "Genesis 41:35": {
    "title": "Store food in the cities",
    "text": "Joseph recommends gathering food during the good years and keeping it under Pharaoh’s authority. Preparation will protect the nation when the harvest fails.",
    "refs": [
      "Proverbs 21:20"
    ]
  },
  "Genesis 41:36": {
    "title": "A reserve for the famine",
    "text": "The stored food will serve as a reserve for the seven famine years so Egypt will not perish. Joseph’s advice joins divine warning with responsible action.",
    "refs": [
      "Genesis 41:48–49"
    ]
  },
  "Genesis 41:37": {
    "title": "Pharaoh and his servants approve",
    "text": "Pharaoh and his servants consider Joseph’s proposal good. The plan is accepted as wise and practical in response to the warning.",
    "refs": [
      "Genesis 41:33–36"
    ]
  },
  "Genesis 41:38": {
    "title": "A man with God’s Spirit",
    "text": "Pharaoh asks whether they can find anyone like Joseph, in whom is the Spirit of God. The verse describes Pharaoh’s recognition of divine wisdom in Joseph; it is not a full technical explanation of the Spirit’s nature.",
    "refs": [
      "Numbers 27:18"
    ]
  },
  "Genesis 41:39": {
    "title": "Joseph is uniquely discerning",
    "text": "Pharaoh acknowledges that God has shown Joseph all this and says none is as discerning and wise as he is. Joseph’s gift is publicly recognized, but its source is credited to God.",
    "refs": [
      "Genesis 41:16"
    ]
  },
  "Genesis 41:40": {
    "title": "Joseph placed over Pharaoh’s house",
    "text": "Pharaoh appoints Joseph over his house and says the people will be ruled according to his word, with Pharaoh retaining the throne. Joseph moves from prison to a position of extraordinary authority.",
    "refs": [
      "Psalm 105:21–22"
    ]
  },
  "Genesis 41:41": {
    "title": "Ruler over all Egypt",
    "text": "Pharaoh declares Joseph ruler over all the land of Egypt. The rise fulfills the direction of Joseph’s earlier dreams, though the path to it involved betrayal and suffering.",
    "refs": [
      "Genesis 37:7–9"
    ]
  },
  "Genesis 41:42": {
    "title": "Pharaoh gives Joseph royal honors",
    "text": "Pharaoh gives Joseph his signet ring, fine linen, a gold chain, and a place in the royal administration. The visible honors mark Joseph’s new official status.",
    "refs": [
      "Esther 8:2"
    ]
  },
  "Genesis 41:43": {
    "title": "The people bow before Joseph",
    "text": "Joseph rides in Pharaoh’s second chariot, and people are commanded to bow before him. The narrative brings the brothers’ earlier dreams of bowing closer to fulfillment.",
    "refs": [
      "Genesis 37:7–8"
    ]
  },
  "Genesis 41:44": {
    "title": "Joseph’s authority confirmed",
    "text": "Pharaoh says no man will lift hand or foot in Egypt without Joseph’s authority. The statement emphasizes the breadth of Joseph’s delegated power under Pharaoh.",
    "refs": [
      "Genesis 41:40"
    ]
  },
  "Genesis 41:45": {
    "title": "Joseph receives an Egyptian name and wife",
    "text": "Pharaoh calls Joseph Zaphnath-paaneah and gives him Asenath as wife. Joseph’s new position integrates him into Egypt’s administration, while the narrative continues to trace God’s work through his life.",
    "refs": [
      "Genesis 41:50"
    ]
  },
  "Genesis 41:46": {
    "title": "Joseph is thirty years old",
    "text": "Joseph is thirty when he stands before Pharaoh and begins his service across Egypt. He has passed through slavery and imprisonment before receiving this responsibility.",
    "refs": [
      "Genesis 37:2",
      "Luke 3:23"
    ]
  },
  "Genesis 41:47": {
    "title": "The land produces abundantly",
    "text": "During the seven plentiful years, the earth produces in abundance. The harvest confirms the interpretation and makes the storage plan possible.",
    "refs": [
      "Genesis 41:29"
    ]
  },
  "Genesis 41:48": {
    "title": "Food stored in the cities",
    "text": "Joseph gathers food and stores it in the cities, placing each city’s nearby produce in its own storehouse. The organized collection prepares Egypt for the coming famine.",
    "refs": [
      "Genesis 41:34–36"
    ]
  },
  "Genesis 41:49": {
    "title": "Grain beyond counting",
    "text": "Joseph stores so much grain that it becomes like the sand of the sea, beyond measure. The abundance of the reserve matches the extraordinary harvest years.",
    "refs": [
      "Genesis 41:47"
    ]
  },
  "Genesis 41:50": {
    "title": "Manasseh and Ephraim are born",
    "text": "Before the famine, Asenath bears Joseph two sons. Their births establish Joseph’s family in Egypt and introduce names that will matter in Israel’s tribal history.",
    "refs": [
      "Genesis 48:5"
    ]
  },
  "Genesis 41:51": {
    "title": "Manasseh and forgotten hardship",
    "text": "Joseph names the firstborn Manasseh because God has made him forget his toil and his father’s house. This expresses relief and healing, not necessarily that Joseph has erased his family from his heart.",
    "refs": [
      "Genesis 45:4–5"
    ]
  },
  "Genesis 41:52": {
    "title": "Ephraim and fruitfulness",
    "text": "Joseph names his second son Ephraim because God has made him fruitful in the land of his affliction. Joseph recognizes God’s provision even in a foreign land where he suffered.",
    "refs": [
      "Genesis 49:22"
    ]
  },
  "Genesis 41:53": {
    "title": "The seven plentiful years end",
    "text": "The seven years of abundance in Egypt come to an end, just as Joseph had interpreted. The time of preparation is over and the predicted famine begins.",
    "refs": [
      "Genesis 41:29"
    ]
  },
  "Genesis 41:54": {
    "title": "Famine begins across the lands",
    "text": "The famine begins as Joseph said, but Egypt has bread because of the stored grain. The contrast demonstrates the value of the preparation Joseph directed.",
    "refs": [
      "Genesis 41:35–36"
    ]
  },
  "Genesis 41:55": {
    "title": "The Egyptians appeal to Pharaoh",
    "text": "When the people cry to Pharaoh for bread, he directs them to Joseph and tells them to do what Joseph says. Joseph’s delegated authority now becomes essential to survival.",
    "refs": [
      "Genesis 41:40"
    ]
  },
  "Genesis 41:56": {
    "title": "Joseph opens the storehouses",
    "text": "As the famine spreads, Joseph opens the storehouses and sells grain to the Egyptians. The crisis reaches the whole land, but the prepared reserves provide food.",
    "refs": [
      "Genesis 41:48–49"
    ]
  },
  "Genesis 41:57": {
    "title": "Nations come to Egypt for grain",
    "text": "People from other countries come to Egypt to buy grain because the famine is severe throughout the earth. The crisis will bring Joseph’s own brothers to Egypt and advance the preservation of Jacob’s family.",
    "refs": [
      "Genesis 42:1–6"
    ]
  },
  "Genesis 42:1": {
    "title": "Jacob hears Egypt has grain",
    "text": "Jacob learns that there is grain in Egypt and asks his sons why they look at one another instead of acting. His words prompt the family to seek food during the famine.",
    "refs": [
      "Genesis 41:56–57"
    ]
  },
  "Genesis 42:2": {
    "title": "Jacob sends his sons to buy food",
    "text": "Jacob tells his sons to go to Egypt and buy grain so the family can live rather than die. The famine forces the brothers to travel to the land where Joseph now holds authority.",
    "refs": [
      "Genesis 41:55"
    ]
  },
  "Genesis 42:3": {
    "title": "Ten brothers go to Egypt",
    "text": "Ten of Joseph’s brothers travel to Egypt to buy grain. Benjamin stays behind with Jacob, setting up a key part of Joseph’s test of his brothers.",
    "refs": [
      "Genesis 42:4"
    ]
  },
  "Genesis 42:4": {
    "title": "Jacob protects Benjamin",
    "text": "Jacob does not send Benjamin with the others because he fears harm may come to him. His special concern reflects the family’s unresolved grief over Joseph.",
    "refs": [
      "Genesis 37:33–35"
    ]
  },
  "Genesis 42:5": {
    "title": "Canaan’s families seek grain",
    "text": "The sons of Israel come among others who travel to Egypt because famine has reached Canaan. The journey is part of the means by which the family will be reunited.",
    "refs": [
      "Genesis 41:57"
    ]
  },
  "Genesis 42:6": {
    "title": "Joseph’s brothers bow before him",
    "text": "Joseph, governor of the land, sells grain to the people, and his brothers bow before him. The earlier dreams begin to be fulfilled, although the brothers do not recognize Joseph.",
    "refs": [
      "Genesis 37:7–8"
    ]
  },
  "Genesis 42:7": {
    "title": "Joseph recognizes them but hides himself",
    "text": "Joseph recognizes his brothers and speaks roughly to them, accusing them of being spies. He does not reveal his identity, and the narrative will show him testing whether their character has changed.",
    "refs": [
      "Genesis 42:9"
    ]
  },
  "Genesis 42:8": {
    "title": "They do not recognize Joseph",
    "text": "Joseph recognizes his brothers, but they do not recognize him. Years have passed, and Joseph’s Egyptian position and appearance make recognition unlikely.",
    "refs": [
      "Genesis 41:45–46"
    ]
  },
  "Genesis 42:9": {
    "title": "Joseph remembers his dreams",
    "text": "Joseph remembers the dreams he had about his brothers and accuses them of spying. The remembered dreams help frame the moment, but his strategy also tests their honesty and concern for Benjamin.",
    "refs": [
      "Genesis 37:5–9"
    ]
  },
  "Genesis 42:10": {
    "title": "The brothers deny spying",
    "text": "The brothers say they have come to buy food and are not spies. Their explanation is true about their immediate purpose, but Joseph continues to question them.",
    "refs": [
      "Genesis 42:11"
    ]
  },
  "Genesis 42:11": {
    "title": "They claim to be honest men",
    "text": "The brothers say they are all one man’s sons and honest men. The reader knows they have hidden the truth about Joseph, so their claim is tested by their past conduct.",
    "refs": [
      "Genesis 37:18–28"
    ]
  },
  "Genesis 42:12": {
    "title": "Joseph repeats the accusation",
    "text": "Joseph insists that they came to spy on the land. The interrogation pressures the brothers to explain their family circumstances more fully.",
    "refs": [
      "Genesis 42:13"
    ]
  },
  "Genesis 42:13": {
    "title": "They explain their family",
    "text": "The brothers say they are twelve brothers, sons of one man in Canaan; the youngest is with their father and one is no more. Their words unknowingly refer to Joseph and Benjamin.",
    "refs": [
      "Genesis 35:24"
    ]
  },
  "Genesis 42:14": {
    "title": "Joseph holds to his test",
    "text": "Joseph says his accusation stands and continues testing their account. The narrative does not present this as a general model for dealing with strangers, but as part of this family reckoning.",
    "refs": [
      "Genesis 42:15–20"
    ]
  },
  "Genesis 42:15": {
    "title": "An oath-like test concerning Benjamin",
    "text": "Joseph says the brothers will not leave unless their youngest brother comes. He sets a condition that will expose whether they are willing to return for Benjamin.",
    "refs": [
      "Genesis 42:20"
    ]
  },
  "Genesis 42:16": {
    "title": "One brother sent to fetch Benjamin",
    "text": "Joseph says one brother will go bring Benjamin while the others remain confined. The test places the brothers under pressure to demonstrate whether their story is true.",
    "refs": [
      "Genesis 42:19–20"
    ]
  },
  "Genesis 42:17": {
    "title": "Three days in custody",
    "text": "Joseph puts them all together in prison for three days. The confinement gives the brothers time to face the crisis and consider their options.",
    "refs": [
      "Genesis 42:18"
    ]
  },
  "Genesis 42:18": {
    "title": "Joseph speaks of fearing God",
    "text": "On the third day, Joseph says he fears God and offers a way for them to live. His statement introduces a measure of mercy within the test and invokes reverence for God as a moral standard.",
    "refs": [
      "Leviticus 19:14"
    ]
  },
  "Genesis 42:19": {
    "title": "One brother remains confined",
    "text": "Joseph says one brother will remain in custody while the others take grain home to relieve their families’ hunger. The arrangement combines accountability with provision for their household.",
    "refs": [
      "Genesis 42:20"
    ]
  },
  "Genesis 42:20": {
    "title": "Bring the youngest brother",
    "text": "Joseph requires the brothers to bring Benjamin so their words may be verified and they will not die. The brothers agree, though they do not yet know Joseph’s identity.",
    "refs": [
      "Genesis 43:3–5"
    ]
  },
  "Genesis 42:21": {
    "title": "The brothers recall Joseph’s distress",
    "text": "The brothers recognize that they are suffering because of what they did to Joseph and remember his distress when he pleaded with them. Their conscience connects the present danger with their past cruelty.",
    "refs": [
      "Genesis 37:23–28"
    ]
  },
  "Genesis 42:22": {
    "title": "Reuben reminds them of his warning",
    "text": "Reuben says he told them not to sin against the boy, but they did not listen; now his blood is required. His words recall his earlier attempt to save Joseph and the brothers’ responsibility for the sale.",
    "refs": [
      "Genesis 37:21–22"
    ]
  },
  "Genesis 42:23": {
    "title": "Joseph understands their words",
    "text": "The brothers do not know Joseph understands them because an interpreter is used. Joseph hears their confession without revealing himself.",
    "refs": [
      "Genesis 42:24"
    ]
  },
  "Genesis 42:24": {
    "title": "Joseph weeps and binds Simeon",
    "text": "Joseph turns away and weeps, then returns and takes Simeon to bind him before the others. His tears reveal that his stern treatment does not mean he is emotionally unmoved.",
    "refs": [
      "Genesis 43:30"
    ]
  },
  "Genesis 42:25": {
    "title": "Grain and money returned",
    "text": "Joseph orders the brothers’ sacks filled with grain, their money returned, and provisions given for the journey. His actions provide food while setting up a new test when they discover the money.",
    "refs": [
      "Genesis 42:27–28"
    ]
  },
  "Genesis 42:26": {
    "title": "The brothers depart with grain",
    "text": "The brothers load the grain on their donkeys and leave. They have food for the family, but Simeon remains behind and Benjamin must still be brought to Egypt.",
    "refs": [
      "Genesis 42:19–20"
    ]
  },
  "Genesis 42:27": {
    "title": "One brother finds his money",
    "text": "At the lodging place, one brother opens his sack to feed his donkey and finds his money at the sack’s mouth. The discovery creates fear because they do not know why the money was returned.",
    "refs": [
      "Genesis 42:28"
    ]
  },
  "Genesis 42:28": {
    "title": "The brothers fear God’s hand",
    "text": "The brother tells the others that his money has been restored, and their hearts fail as they wonder what God has done to them. Their fear shows how vulnerable they feel after the accusation and confinement.",
    "refs": [
      "Genesis 42:21–22"
    ]
  },
  "Genesis 42:29": {
    "title": "They report to Jacob",
    "text": "The brothers return to Canaan and tell Jacob what happened in Egypt. Their report explains the ruler’s questions and the condition that Benjamin must come.",
    "refs": [
      "Genesis 42:13–20"
    ]
  },
  "Genesis 42:30": {
    "title": "The ruler speaks roughly",
    "text": "They tell Jacob that the ruler spoke roughly and accused them of spying. The brothers recount the treatment they received without knowing the ruler is Joseph.",
    "refs": [
      "Genesis 42:7–12"
    ]
  },
  "Genesis 42:31": {
    "title": "They insist they are honest",
    "text": "The brothers repeat that they told the ruler they were honest men. Their insistence contrasts with the unresolved deceit in their family history.",
    "refs": [
      "Genesis 42:11"
    ]
  },
  "Genesis 42:32": {
    "title": "They recount their family details",
    "text": "They tell Jacob they are twelve brothers, one is no more, and the youngest is with their father. This summary repeats the facts that led Joseph to demand Benjamin’s presence.",
    "refs": [
      "Genesis 42:13"
    ]
  },
  "Genesis 42:33": {
    "title": "The ruler’s condition",
    "text": "The brothers say the ruler required one brother to remain and sent the others home with grain. They must bring Benjamin to prove their account and secure the release of the confined brother.",
    "refs": [
      "Genesis 42:19–20"
    ]
  },
  "Genesis 42:34": {
    "title": "Benjamin is required to confirm their words",
    "text": "The ruler said they must bring their youngest brother so he would know they were not spies and could release their brother. The condition forces Jacob to consider risking Benjamin’s safety.",
    "refs": [
      "Genesis 43:3–5"
    ]
  },
  "Genesis 42:35": {
    "title": "Money found in every sack",
    "text": "As the brothers empty their sacks, each finds his money bundle. The discovery frightens the family and complicates their ability to explain the events in Egypt.",
    "refs": [
      "Genesis 42:27–28"
    ]
  },
  "Genesis 42:36": {
    "title": "Jacob grieves over his sons",
    "text": "Jacob says Joseph is gone, Simeon is gone, and now they want to take Benjamin. He feels that everything is against him, expressing grief without knowing the larger story unfolding.",
    "refs": [
      "Genesis 37:33–35"
    ]
  },
  "Genesis 42:37": {
    "title": "Reuben offers his own sons as pledge",
    "text": "Reuben offers Jacob the lives of his two sons if he fails to bring Benjamin back. His offer is extreme and cannot truly replace Benjamin, showing the desperation of the moment.",
    "refs": [
      "Genesis 43:8–9"
    ]
  },
  "Genesis 42:38": {
    "title": "Jacob refuses to send Benjamin",
    "text": "Jacob says Benjamin will not go because Joseph is dead and he fears harm will bring him down to the grave in sorrow. His grief and fear prevent the family from returning immediately to Egypt.",
    "refs": [
      "Genesis 43:1–2"
    ]
  },
  "Genesis 43:1": {
    "title": "The famine remains severe",
    "text": "The famine continues to press the family, and the grain brought from Egypt is not enough for the long term. Jacob’s household must decide whether to return to Egypt.",
    "refs": [
      "Genesis 42:2"
    ]
  },
  "Genesis 43:2": {
    "title": "Jacob orders another journey",
    "text": "After the family has eaten the grain from Egypt, Jacob tells his sons to return and buy a little more food. The need for survival forces the issue of Benjamin’s journey.",
    "refs": [
      "Genesis 42:38"
    ]
  },
  "Genesis 43:3": {
    "title": "Judah reminds Jacob of the condition",
    "text": "Judah says the Egyptian ruler warned them not to appear unless Benjamin came with them. The condition is firm, and the brothers cannot obtain more grain without facing it.",
    "refs": [
      "Genesis 42:20"
    ]
  },
  "Genesis 43:4": {
    "title": "Judah offers to go with Benjamin",
    "text": "Judah says they will go down if Jacob sends Benjamin. The brothers are prepared to return, but Jacob must accept the risk of sending his youngest son.",
    "refs": [
      "Genesis 43:8"
    ]
  },
  "Genesis 43:5": {
    "title": "Without Benjamin they cannot appear",
    "text": "Judah repeats that they cannot see the ruler unless Benjamin is with them. The narrative makes clear that the family’s path forward depends on Jacob’s decision.",
    "refs": [
      "Genesis 42:34"
    ]
  },
  "Genesis 43:6": {
    "title": "Jacob questions their honesty",
    "text": "Jacob asks why they told the ruler they had another brother. His question comes from fear and frustration, while the brothers had answered the ruler’s questions about their family.",
    "refs": [
      "Genesis 42:13"
    ]
  },
  "Genesis 43:7": {
    "title": "The brothers explain the questioning",
    "text": "They say the ruler asked directly about their family and they answered honestly, not knowing he would demand Benjamin. Their explanation shows how the earlier conversation led to the present crisis.",
    "refs": [
      "Genesis 42:13–20"
    ]
  },
  "Genesis 43:8": {
    "title": "Judah accepts responsibility",
    "text": "Judah urges Jacob to send the boy with him so the family may live and not die. He frames the journey as necessary for the survival of the children and household.",
    "refs": [
      "Genesis 42:2"
    ]
  },
  "Genesis 43:9": {
    "title": "Judah pledges himself for Benjamin",
    "text": "Judah promises to be surety for Benjamin and says Jacob may hold him responsible if he fails to bring him back. His willingness to take responsibility contrasts with his earlier role in selling Joseph.",
    "refs": [
      "Genesis 37:26–28",
      "Genesis 44:32–34"
    ]
  },
  "Genesis 43:10": {
    "title": "The delay has cost time",
    "text": "Judah says that if they had not delayed, they could have returned twice. The famine makes postponement costly, and Jacob must now choose between risk and hunger.",
    "refs": [
      "Genesis 43:1–2"
    ]
  },
  "Genesis 43:11": {
    "title": "Jacob prepares a gift",
    "text": "Jacob tells his sons to take a gift of the land’s best produce and double money. He seeks favor from the ruler through customary hospitality and careful preparation.",
    "refs": [
      "Proverbs 18:16"
    ]
  },
  "Genesis 43:12": {
    "title": "Take double money",
    "text": "Jacob instructs the brothers to return the money found in their sacks as well as money for new grain. He wants to correct the apparent mistake and avoid any suspicion of dishonesty.",
    "refs": [
      "Genesis 42:25–28"
    ]
  },
  "Genesis 43:13": {
    "title": "Take Benjamin and return",
    "text": "Jacob tells them to take Benjamin and go back to the man. The family finally moves forward with the condition that had prevented their return.",
    "refs": [
      "Genesis 43:8–9"
    ]
  },
  "Genesis 43:14": {
    "title": "Jacob prays for mercy",
    "text": "Jacob asks God Almighty to grant mercy before the ruler so that Simeon and Benjamin may return. He acknowledges that the outcome is beyond his control and entrusts his sons to God.",
    "refs": [
      "Genesis 17:1",
      "Genesis 42:36"
    ]
  },
  "Genesis 43:15": {
    "title": "The brothers return to Egypt",
    "text": "The brothers take the gift, double money, and Benjamin and stand before Joseph. The moment brings Joseph’s plan to its next stage.",
    "refs": [
      "Genesis 42:20"
    ]
  },
  "Genesis 43:16": {
    "title": "Joseph orders a meal",
    "text": "When Joseph sees Benjamin, he tells his steward to bring the men to his house and prepare a meal. The brothers are invited into a situation they do not understand and initially fear.",
    "refs": [
      "Genesis 43:18"
    ]
  },
  "Genesis 43:17": {
    "title": "Joseph’s steward obeys",
    "text": "The steward does as Joseph commands and brings the men to Joseph’s house. Joseph’s household is arranged to receive them, though the brothers interpret the invitation with suspicion.",
    "refs": [
      "Genesis 43:18"
    ]
  },
  "Genesis 43:18": {
    "title": "The brothers fear the money",
    "text": "The brothers fear they are being brought in because of the returned money and expect to be accused, seized, and made servants. Their fear reflects the uncertainty of their previous dealings with Egypt.",
    "refs": [
      "Genesis 42:27–28"
    ]
  },
  "Genesis 43:19": {
    "title": "They speak to the steward",
    "text": "The brothers approach the steward at the entrance and explain the money found in their sacks. They try to clarify the situation before any accusation is made.",
    "refs": [
      "Genesis 43:20–22"
    ]
  },
  "Genesis 43:20": {
    "title": "They explain the first journey",
    "text": "They tell the steward they came to buy food previously and returned home after their grain was purchased. They are trying to demonstrate that they have not deliberately withheld payment.",
    "refs": [
      "Genesis 42:25"
    ]
  },
  "Genesis 43:21": {
    "title": "The money was in their sacks",
    "text": "The brothers say that at the lodging place they found their money in full weight in their sacks and have brought it back. Their account emphasizes that they are returning the unexplained money rather than keeping it.",
    "refs": [
      "Genesis 42:27–28"
    ]
  },
  "Genesis 43:22": {
    "title": "They bring money for more grain",
    "text": "They say they have brought additional money to buy food and do not know who put the other money in their sacks. Their explanation is consistent with the reader’s knowledge that Joseph’s steward returned it by order.",
    "refs": [
      "Genesis 42:25"
    ]
  },
  "Genesis 43:23": {
    "title": "The steward reassures them",
    "text": "The steward tells them not to fear, says their God and their father’s God gave them treasure, and brings Simeon out. His words offer reassurance, although the narrative does not say he knows all the circumstances behind the returned money.",
    "refs": [
      "Genesis 42:24"
    ]
  },
  "Genesis 43:24": {
    "title": "The brothers are treated hospitably",
    "text": "The steward brings the men into the house, gives them water to wash their feet, and feeds their donkeys. The hospitality contrasts with their fear that they will be seized as servants.",
    "refs": [
      "Genesis 18:4"
    ]
  },
  "Genesis 43:25": {
    "title": "They prepare the gift",
    "text": "The brothers prepare the gift for Joseph’s arrival at noon, having heard that they will eat there. They seek to approach the ruler respectfully.",
    "refs": [
      "Genesis 43:11"
    ]
  },
  "Genesis 43:26": {
    "title": "They bow before Joseph",
    "text": "When Joseph comes home, they bring the gift and bow before him. The act echoes the dreams Joseph had told them years earlier.",
    "refs": [
      "Genesis 37:7–9"
    ]
  },
  "Genesis 43:27": {
    "title": "Joseph asks after their father",
    "text": "Joseph asks whether their elderly father is well and still alive. His question shows concern for Jacob while he continues to conceal his identity.",
    "refs": [
      "Genesis 42:13"
    ]
  },
  "Genesis 43:28": {
    "title": "The brothers bow again",
    "text": "The brothers say Jacob is well and bow again. The repeated bowing further echoes Joseph’s dreams, while the brothers remain unaware of the connection.",
    "refs": [
      "Genesis 37:9–10"
    ]
  },
  "Genesis 43:29": {
    "title": "Joseph sees Benjamin",
    "text": "Joseph sees Benjamin, his mother’s son, and asks whether he is the younger brother they mentioned. He addresses Benjamin with a blessing, revealing a deep emotional connection.",
    "refs": [
      "Genesis 35:18"
    ]
  },
  "Genesis 43:30": {
    "title": "Joseph weeps privately",
    "text": "Joseph’s emotions overcome him at the sight of Benjamin, and he leaves to weep in private. His tears reveal the affection beneath the stern role he has maintained.",
    "refs": [
      "Genesis 42:24"
    ]
  },
  "Genesis 43:31": {
    "title": "Joseph composes himself",
    "text": "Joseph washes his face, returns, and orders the meal served. He manages his emotions before continuing the test of his brothers.",
    "refs": [
      "Genesis 43:30"
    ]
  },
  "Genesis 43:32": {
    "title": "Separate tables at the meal",
    "text": "Joseph eats separately, the Egyptians separately, and the brothers separately because Egyptians did not eat with Hebrews. The verse describes a cultural boundary in the setting and helps explain the unusual seating.",
    "refs": [
      "Genesis 46:34"
    ]
  },
  "Genesis 43:33": {
    "title": "The brothers sit by age",
    "text": "The brothers are seated from oldest to youngest, and they marvel at one another. The order suggests knowledge Joseph has not explained, adding to their confusion.",
    "refs": [
      "Genesis 42:13"
    ]
  },
  "Genesis 43:34": {
    "title": "Benjamin receives extra portions",
    "text": "Joseph sends portions from his table to the brothers, and Benjamin receives five times as much. The meal tests whether the brothers will resent the youngest as they once resented Joseph.",
    "refs": [
      "Genesis 37:3–4"
    ]
  },
  "Genesis 44:1": {
    "title": "Joseph orders the sacks filled",
    "text": "Joseph tells his steward to fill the men’s sacks with food and return each man’s money. The arrangement repeats the earlier return of their money and prepares a final test.",
    "refs": [
      "Genesis 43:16"
    ]
  },
  "Genesis 44:2": {
    "title": "The silver cup in Benjamin’s sack",
    "text": "Joseph orders his silver cup placed in Benjamin’s sack along with the money. This is a deliberate test devised by Joseph, not a real theft committed by Benjamin.",
    "refs": [
      "Genesis 44:12"
    ]
  },
  "Genesis 44:3": {
    "title": "The brothers leave at dawn",
    "text": "At daybreak, the brothers are sent away with their donkeys. They leave believing the visit has ended peacefully, unaware of the test ahead.",
    "refs": [
      "Genesis 44:4"
    ]
  },
  "Genesis 44:4": {
    "title": "Joseph sends the steward after them",
    "text": "Joseph tells his steward to pursue the men and ask why they repaid good with evil. The accusation is part of the test that will reveal how the brothers respond to danger involving Benjamin.",
    "refs": [
      "Genesis 44:5"
    ]
  },
  "Genesis 44:5": {
    "title": "The cup used for divination",
    "text": "The steward refers to Joseph’s cup as one used for divination. This is part of the narrative’s setup and does not endorse divination as a practice for God’s people.",
    "refs": [
      "Deuteronomy 18:10–12"
    ]
  },
  "Genesis 44:6": {
    "title": "The steward repeats the accusation",
    "text": "The steward catches up and says the words Joseph instructed him to say. The brothers are confronted with a serious charge despite believing they have acted honestly.",
    "refs": [
      "Genesis 44:4–5"
    ]
  },
  "Genesis 44:7": {
    "title": "The brothers deny wrongdoing",
    "text": "The brothers ask why the steward speaks this way and insist they would not steal silver or gold. Their confidence comes from their belief that they have returned the money found in their sacks.",
    "refs": [
      "Genesis 43:21–22"
    ]
  },
  "Genesis 44:8": {
    "title": "They cite the returned money",
    "text": "They remind the steward that they returned money found in their sacks from Canaan, asking why they would steal silver or gold from the master’s house. Their argument is reasonable from what they know, though the planted cup is hidden from them.",
    "refs": [
      "Genesis 43:21"
    ]
  },
  "Genesis 44:9": {
    "title": "A severe pledge offered",
    "text": "The brothers say whoever has the cup may die and the rest will become servants. Their statement is rash, and the search will expose that the cup is in Benjamin’s sack.",
    "refs": [
      "Genesis 44:12"
    ]
  },
  "Genesis 44:10": {
    "title": "The steward narrows the penalty",
    "text": "The steward says the one found with the cup will be a servant, while the others will be blameless. The stated penalty is less severe than the brothers proposed, but it still threatens the family.",
    "refs": [
      "Genesis 44:17"
    ]
  },
  "Genesis 44:11": {
    "title": "The sacks are opened",
    "text": "Each brother quickly lowers his sack to the ground and opens it. The search proceeds from the oldest to the youngest, building suspense.",
    "refs": [
      "Genesis 44:12"
    ]
  },
  "Genesis 44:12": {
    "title": "The cup is found with Benjamin",
    "text": "The steward searches the sacks and finds the cup in Benjamin’s sack. The brothers are shocked because they do not know that Joseph arranged the test.",
    "refs": [
      "Genesis 44:2"
    ]
  },
  "Genesis 44:13": {
    "title": "The brothers tear their clothes",
    "text": "The brothers tear their clothes, load their donkeys, and return to the city. Their reaction shows solidarity with Benjamin rather than abandoning him as they once abandoned Joseph.",
    "refs": [
      "Genesis 37:23–28"
    ]
  },
  "Genesis 44:14": {
    "title": "Judah and his brothers return",
    "text": "Judah and his brothers enter Joseph’s house and fall before him. The scene brings the brothers back into Joseph’s presence under the threat of losing Benjamin.",
    "refs": [
      "Genesis 43:26"
    ]
  },
  "Genesis 44:15": {
    "title": "Joseph asks about their act",
    "text": "Joseph asks what they have done and says such a man as he can surely discover things. His statement maintains the role of the powerful Egyptian ruler in the test.",
    "refs": [
      "Genesis 44:5"
    ]
  },
  "Genesis 44:16": {
    "title": "Judah confesses helplessness",
    "text": "Judah asks what they can say and how they can clear themselves, saying God has found out their iniquity. He does not claim they stole the cup; instead, he speaks as a guilty man whose past sins have caught up with him.",
    "refs": [
      "Genesis 42:21–22"
    ]
  },
  "Genesis 44:17": {
    "title": "Joseph demands Benjamin remain",
    "text": "Joseph says only the man with the cup will remain as his servant, and the rest may return in peace to their father. The condition tests whether the brothers will leave Benjamin behind to save themselves.",
    "refs": [
      "Genesis 44:33–34"
    ]
  },
  "Genesis 44:18": {
    "title": "Judah approaches Joseph",
    "text": "Judah asks permission to speak and pleads that Joseph not be angry. His speech begins a deeply personal appeal on behalf of their father and Benjamin.",
    "refs": [
      "Genesis 44:30–31"
    ]
  },
  "Genesis 44:19": {
    "title": "Joseph had asked about their family",
    "text": "Judah recalls that Joseph asked whether they had a father or brother. The speech retraces the questions that led to Benjamin being brought to Egypt.",
    "refs": [
      "Genesis 43:7"
    ]
  },
  "Genesis 44:20": {
    "title": "They describe the youngest brother",
    "text": "Judah says they have an old father and a younger brother born in his father’s old age, whose brother is dead and who is the only son of his mother left. Judah is referring to Joseph as dead in the family’s belief, while Joseph hears the depth of Jacob’s attachment to Benjamin.",
    "refs": [
      "Genesis 42:13"
    ]
  },
  "Genesis 44:21": {
    "title": "Joseph required Benjamin’s presence",
    "text": "Judah recalls that Joseph told them to bring Benjamin so he could see him. The demand created the present crisis and put Jacob’s beloved youngest son at risk.",
    "refs": [
      "Genesis 42:20"
    ]
  },
  "Genesis 44:22": {
    "title": "Jacob feared losing Benjamin",
    "text": "Judah says they told Joseph that the boy could not leave his father, or his father would die. The family had already warned how deeply Jacob’s life was bound to Benjamin’s safety.",
    "refs": [
      "Genesis 42:38"
    ]
  },
  "Genesis 44:23": {
    "title": "The ruler’s condition repeated",
    "text": "Judah recalls Joseph’s insistence that they would not see his face again unless Benjamin came with them. This condition made the second journey unavoidable.",
    "refs": [
      "Genesis 43:3–5"
    ]
  },
  "Genesis 44:24": {
    "title": "They report to their father",
    "text": "Judah says they returned to their father and told him the ruler’s words. The family’s decision to bring Benjamin was made under the pressure of famine.",
    "refs": [
      "Genesis 43:1–2"
    ]
  },
  "Genesis 44:25": {
    "title": "Jacob asks them to buy more food",
    "text": "Judah recalls Jacob’s instruction to return to Egypt to buy a little food. The family cannot survive without the grain Joseph controls.",
    "refs": [
      "Genesis 43:2"
    ]
  },
  "Genesis 44:26": {
    "title": "They could not go without Benjamin",
    "text": "Judah repeats that they could not go unless Benjamin accompanied them, because the ruler would not see them otherwise. The brothers are now bound to Benjamin’s fate.",
    "refs": [
      "Genesis 43:5"
    ]
  },
  "Genesis 44:27": {
    "title": "Jacob’s two sons by Rachel",
    "text": "Judah recounts Jacob’s statement that his wife bore him two sons. The speech emphasizes how special Rachel’s sons are to Jacob and why losing Benjamin would devastate him.",
    "refs": [
      "Genesis 35:24"
    ]
  },
  "Genesis 44:28": {
    "title": "One son believed lost",
    "text": "Judah says one son went away and Jacob believed he had been torn in pieces, and he has not seen him since. Joseph hears the family’s belief about his fate directly from Judah.",
    "refs": [
      "Genesis 37:33–35"
    ]
  },
  "Genesis 44:29": {
    "title": "Jacob fears Benjamin’s death",
    "text": "Judah says that if Benjamin is taken and harmed, Jacob will go down to the grave in sorrow. The warning underscores the emotional stakes of the demand to leave Benjamin in Egypt.",
    "refs": [
      "Genesis 42:38"
    ]
  },
  "Genesis 44:30": {
    "title": "Judah sees Benjamin’s place in Jacob’s heart",
    "text": "Judah says he cannot return to his father without the boy because Jacob’s life is bound up with Benjamin’s. His concern now centers on his father’s grief rather than his own safety.",
    "refs": [
      "Genesis 44:31"
    ]
  },
  "Genesis 44:31": {
    "title": "Jacob would die in sorrow",
    "text": "Judah explains that if Jacob sees Benjamin missing, he will die of grief, and the brothers will bring their father down in sorrow. The speech shows that Judah now feels responsible for protecting both Benjamin and Jacob.",
    "refs": [
      "Genesis 42:36"
    ]
  },
  "Genesis 44:32": {
    "title": "Judah had pledged himself",
    "text": "Judah reminds Joseph that he personally became surety for Benjamin before their father. His pledge is not an empty phrase; he is prepared to accept the consequences himself.",
    "refs": [
      "Genesis 43:9"
    ]
  },
  "Genesis 44:33": {
    "title": "Judah offers to stay as a servant",
    "text": "Judah asks to remain in Benjamin’s place and let Benjamin return with the brothers. This is a striking reversal from Judah’s earlier proposal to sell Joseph rather than kill him.",
    "refs": [
      "Genesis 37:26–28"
    ]
  },
  "Genesis 44:34": {
    "title": "Judah cannot bear to see Jacob’s grief",
    "text": "Judah says he cannot return to his father without Benjamin and witness the disaster that would come upon him. His plea reveals a changed willingness to sacrifice himself for his family.",
    "refs": [
      "Genesis 44:18–33"
    ]
  },
  "Genesis 45:1": {
    "title": "Joseph reveals himself",
    "text": "Joseph can no longer restrain himself and orders everyone except his brothers out. He reveals his identity in private, and the moment begins the family’s restoration.",
    "refs": [
      "Genesis 45:3"
    ]
  },
  "Genesis 45:2": {
    "title": "Joseph weeps aloud",
    "text": "Joseph weeps so loudly that the Egyptians and Pharaoh’s household hear. His grief and affection break through the role he has maintained during the tests.",
    "refs": [
      "Genesis 43:30"
    ]
  },
  "Genesis 45:3": {
    "title": "Joseph asks about his father",
    "text": "Joseph tells his brothers he is Joseph and asks whether his father is still alive. The brothers are so troubled they cannot answer him, overwhelmed by the revelation.",
    "refs": [
      "Genesis 42:13"
    ]
  },
  "Genesis 45:4": {
    "title": "Joseph calls them near",
    "text": "Joseph asks his brothers to come close and identifies himself as the brother they sold into Egypt. He does not conceal their wrongdoing, but he moves toward reconciliation rather than revenge.",
    "refs": [
      "Genesis 37:28"
    ]
  },
  "Genesis 45:5": {
    "title": "God sent Joseph ahead to preserve life",
    "text": "Joseph tells them not to be grieved or angry with themselves for selling him, because God sent him ahead to preserve life. He interprets God’s providence as bringing rescue through their evil act, not as making their betrayal good.",
    "refs": [
      "Genesis 50:20"
    ]
  },
  "Genesis 45:6": {
    "title": "Two years of famine have passed",
    "text": "Joseph says the famine has lasted two years and five more years remain without plowing or harvest. The family must act quickly to survive the continuing crisis.",
    "refs": [
      "Genesis 41:30"
    ]
  },
  "Genesis 45:7": {
    "title": "God preserves a remnant",
    "text": "Joseph says God sent him ahead to preserve a remnant and keep the family alive. The verse connects the family’s survival with God’s larger covenant purpose.",
    "refs": [
      "Genesis 12:2–3"
    ]
  },
  "Genesis 45:8": {
    "title": "God made Joseph a ruler in Egypt",
    "text": "Joseph says it was God who sent him, making him a father to Pharaoh, lord of Pharaoh’s house, and ruler over Egypt. His explanation emphasizes providence while not excusing the brothers’ earlier sin.",
    "refs": [
      "Genesis 41:40–44"
    ]
  },
  "Genesis 45:9": {
    "title": "Jacob is told to come quickly",
    "text": "Joseph tells his brothers to hurry to his father and report that Joseph is alive and ruler in Egypt. He wants Jacob to come before the famine causes further suffering.",
    "refs": [
      "Genesis 45:13"
    ]
  },
  "Genesis 45:10": {
    "title": "A place in Goshen",
    "text": "Joseph offers Jacob and the family a place in Goshen, where they can live near him with their children and livestock. The offer provides a practical refuge during the famine.",
    "refs": [
      "Genesis 46:28–34"
    ]
  },
  "Genesis 45:11": {
    "title": "Joseph promises to provide",
    "text": "Joseph promises to nourish his family through the remaining famine years so that they and their households will not come to poverty. His authority becomes a means of preserving the family.",
    "refs": [
      "Genesis 47:12"
    ]
  },
  "Genesis 45:12": {
    "title": "The brothers see Joseph is speaking",
    "text": "Joseph says the brothers and Benjamin can see that he himself is speaking to them. The personal revelation confirms that this is not merely a message from an Egyptian official.",
    "refs": [
      "Genesis 45:3"
    ]
  },
  "Genesis 45:13": {
    "title": "Tell Jacob of Joseph’s honor",
    "text": "Joseph instructs his brothers to tell Jacob about his glory in Egypt and everything they have seen, then bring him quickly. The invitation is both practical and an emotional assurance that Joseph is alive.",
    "refs": [
      "Genesis 45:9"
    ]
  },
  "Genesis 45:14": {
    "title": "Joseph embraces Benjamin",
    "text": "Joseph falls on Benjamin’s neck and weeps, and Benjamin weeps on his neck. The brothers share a reunion after years of separation and uncertainty.",
    "refs": [
      "Genesis 43:29–30"
    ]
  },
  "Genesis 45:15": {
    "title": "Joseph kisses his brothers",
    "text": "Joseph kisses all his brothers and weeps over them, after which they speak with him. The affection marks a change from fear and silence to renewed relationship.",
    "refs": [
      "Genesis 50:17"
    ]
  },
  "Genesis 45:16": {
    "title": "Pharaoh’s household hears the news",
    "text": "The report that Joseph’s brothers have come pleases Pharaoh and his servants. Joseph’s family reunion is welcomed at the highest level of Egypt’s government.",
    "refs": [
      "Genesis 45:17–20"
    ]
  },
  "Genesis 45:17": {
    "title": "Pharaoh tells them to return",
    "text": "Pharaoh tells Joseph to load their animals and return to Canaan. The royal order confirms that the family is welcome to settle in Egypt during the famine.",
    "refs": [
      "Genesis 45:18"
    ]
  },
  "Genesis 45:18": {
    "title": "The best of Egypt offered",
    "text": "Pharaoh tells the family to bring their father and households to Egypt, where they will eat the fat of the land. The offer gives the family safety and provision during the famine.",
    "refs": [
      "Genesis 47:6"
    ]
  },
  "Genesis 45:19": {
    "title": "Wagons for the children and women",
    "text": "Pharaoh instructs them to take wagons from Egypt for their children and wives and bring their father. The practical help makes the long journey possible for the whole household.",
    "refs": [
      "Genesis 46:5"
    ]
  },
  "Genesis 45:20": {
    "title": "Do not worry about possessions",
    "text": "Pharaoh tells the brothers not to regard their belongings as essential because the best of Egypt is available to them. The invitation promises provision rather than requiring them to preserve everything from Canaan.",
    "refs": [
      "Genesis 45:18"
    ]
  },
  "Genesis 45:21": {
    "title": "The brothers receive wagons and supplies",
    "text": "The sons of Israel do as instructed, and Joseph provides wagons and provisions for the journey. The family is now being moved toward safety through the provisions of Egypt’s ruler.",
    "refs": [
      "Genesis 45:19"
    ]
  },
  "Genesis 45:22": {
    "title": "Clothing and silver for the brothers",
    "text": "Joseph gives each brother changes of clothing, while Benjamin receives three hundred pieces of silver and five changes of clothing. The gifts are generous, and the text does not say that Joseph’s favor toward Benjamin creates the old rivalry again.",
    "refs": [
      "Genesis 43:34"
    ]
  },
  "Genesis 45:23": {
    "title": "Gifts for Jacob",
    "text": "Joseph sends donkeys loaded with Egyptian goods and food for Jacob’s journey. He provides for his father’s needs before the family arrives.",
    "refs": [
      "Genesis 45:11"
    ]
  },
  "Genesis 45:24": {
    "title": "Joseph warns them not to quarrel",
    "text": "Joseph sends his brothers away and tells them not to fall out by the way. He knows the revelation of their past could provoke blame and conflict as they travel home.",
    "refs": [
      "Genesis 42:21–22"
    ]
  },
  "Genesis 45:25": {
    "title": "The brothers return to Canaan",
    "text": "The brothers leave Egypt and come to Jacob in Canaan. They carry news that will overturn the grief Jacob has carried for years.",
    "refs": [
      "Genesis 37:33–35"
    ]
  },
  "Genesis 45:26": {
    "title": "Jacob struggles to believe",
    "text": "The brothers tell Jacob that Joseph is alive and ruler over Egypt, but Jacob’s heart faints because he cannot believe them. The news is too astonishing after years of mourning.",
    "refs": [
      "Genesis 37:34–35"
    ]
  },
  "Genesis 45:27": {
    "title": "Jacob sees the wagons and revives",
    "text": "When the brothers repeat Joseph’s words and Jacob sees the wagons Joseph sent, his spirit revives. The evidence helps him accept that Joseph truly lives and wants him to come.",
    "refs": [
      "Genesis 45:19"
    ]
  },
  "Genesis 45:28": {
    "title": "Jacob longs to see Joseph",
    "text": "Israel declares that Joseph his son is still alive and says he will go see him before he dies. The family’s long separation is about to end.",
    "refs": [
      "Genesis 46:29"
    ]
  },
  "Genesis 46:1": {
    "title": "Israel offers sacrifices at Beersheba",
    "text": "Israel travels with all he has and offers sacrifices to the God of his father Isaac at Beersheba. Before entering Egypt, he worships the God who has guided his family.",
    "refs": [
      "Genesis 21:33",
      "Genesis 26:23–25"
    ]
  },
  "Genesis 46:2": {
    "title": "God speaks to Israel in a vision",
    "text": "God calls Jacob by name in a night vision, and Jacob answers, “Here am I.” The encounter echoes earlier divine calls and prepares Jacob for the move to Egypt.",
    "refs": [
      "Genesis 31:11"
    ]
  },
  "Genesis 46:3": {
    "title": "God promises to make Israel a great nation",
    "text": "God identifies Himself as the God of Jacob’s father and tells him not to fear going down to Egypt, promising to make him a great nation there. The promise reassures Jacob that the move will not end the covenant family.",
    "refs": [
      "Genesis 12:2",
      "Genesis 28:13–15"
    ]
  },
  "Genesis 46:4": {
    "title": "God promises to go down and bring them up",
    "text": "God says He will go with Jacob into Egypt and will surely bring him up again, and Joseph will close Jacob’s eyes at his death. The promise includes God’s presence in Egypt and the eventual return of Jacob’s descendants to the promised land.",
    "refs": [
      "Genesis 15:13–16"
    ]
  },
  "Genesis 46:5": {
    "title": "Jacob travels with his family",
    "text": "Jacob’s sons carry their father, children, and wives in the wagons Pharaoh sent. The family begins the move into Egypt with practical assistance from Joseph.",
    "refs": [
      "Genesis 45:19"
    ]
  },
  "Genesis 46:6": {
    "title": "The family brings its possessions",
    "text": "Jacob and his descendants take their livestock and possessions acquired in Canaan and come to Egypt. The migration is a whole-household movement during famine.",
    "refs": [
      "Genesis 45:10–11"
    ]
  },
  "Genesis 46:7": {
    "title": "Jacob’s descendants go with him",
    "text": "The verse summarizes that Jacob brings his sons, daughters, grandsons, and granddaughters into Egypt. The list emphasizes that the covenant family enters Egypt as an extended household.",
    "refs": [
      "Genesis 46:26–27"
    ]
  },
  "Genesis 46:8": {
    "title": "Israel’s family names begin",
    "text": "The text begins listing the names of the children of Israel who came into Egypt. The genealogy records the family’s identity at the moment it relocates.",
    "refs": [
      "Exodus 1:1–5"
    ]
  },
  "Genesis 46:9": {
    "title": "Reuben’s descendants",
    "text": "The sons and grandson of Reuben are listed. The genealogy preserves the branches of Israel’s firstborn son.",
    "refs": [
      "Genesis 35:23"
    ]
  },
  "Genesis 46:10": {
    "title": "Simeon’s descendants",
    "text": "The sons of Simeon are named, including the family lines associated with Canaanite women. The list is a record of Israel’s household rather than a moral evaluation of each name.",
    "refs": [
      "Genesis 29:33"
    ]
  },
  "Genesis 46:11": {
    "title": "Levi’s descendants",
    "text": "The sons of Levi are named: Gershon, Kohath, and Merari. These lines later become significant in the organization of Israel’s priestly and Levitical service.",
    "refs": [
      "Exodus 6:16"
    ]
  },
  "Genesis 46:12": {
    "title": "Judah’s family line",
    "text": "Judah’s sons and grandsons are listed, including Perez and Zerah. The genealogy preserves the line that will later lead to David and, according to the New Testament, Jesus.",
    "refs": [
      "Ruth 4:18–22",
      "Matthew 1:3"
    ]
  },
  "Genesis 46:13": {
    "title": "Issachar’s sons",
    "text": "The sons of Issachar are named. The list records another branch of Jacob’s family entering Egypt.",
    "refs": [
      "Genesis 30:18"
    ]
  },
  "Genesis 46:14": {
    "title": "Zebulun’s sons",
    "text": "The sons of Zebulun are named. The genealogy continues to record the family lines of Leah’s sons.",
    "refs": [
      "Genesis 30:20"
    ]
  },
  "Genesis 46:15": {
    "title": "Leah’s descendants summarized",
    "text": "The verse summarizes Leah’s descendants born to Jacob in Padan-aram, including Dinah, and gives a total for her line. The count follows the family list in the passage.",
    "refs": [
      "Genesis 29:31–35",
      "Genesis 30:18–21"
    ]
  },
  "Genesis 46:16": {
    "title": "Gad’s descendants",
    "text": "The sons of Gad are named. Their listing contributes to the total record of Israel’s descendants in Egypt.",
    "refs": [
      "Genesis 30:11"
    ]
  },
  "Genesis 46:17": {
    "title": "Asher’s descendants",
    "text": "The sons and daughter of Asher are listed. The verse records the family branch associated with Leah’s servant Zilpah.",
    "refs": [
      "Genesis 30:13"
    ]
  },
  "Genesis 46:18": {
    "title": "Zilpah’s descendants summarized",
    "text": "The text summarizes the descendants born to Jacob through Zilpah and records their number. This is part of the passage’s accounting of the family that entered Egypt.",
    "refs": [
      "Genesis 30:9–13"
    ]
  },
  "Genesis 46:19": {
    "title": "Rachel’s sons",
    "text": "Joseph and Benjamin are named as Rachel’s sons. Their family line is central to the events that brought Jacob’s household to Egypt.",
    "refs": [
      "Genesis 35:24"
    ]
  },
  "Genesis 46:20": {
    "title": "Joseph’s sons in Egypt",
    "text": "Manasseh and Ephraim are born to Joseph in Egypt through Asenath. They are included in Israel’s family before the wider household settles there.",
    "refs": [
      "Genesis 41:50–52"
    ]
  },
  "Genesis 46:21": {
    "title": "Benjamin’s descendants",
    "text": "The sons of Benjamin are listed. The genealogy records the growth of Rachel’s youngest son’s family line.",
    "refs": [
      "Genesis 35:18"
    ]
  },
  "Genesis 46:22": {
    "title": "Rachel’s descendants summarized",
    "text": "The verse summarizes the descendants born to Jacob through Rachel. The list documents the household branches that traveled into Egypt.",
    "refs": [
      "Genesis 46:19–21"
    ]
  },
  "Genesis 46:23": {
    "title": "Dan’s son",
    "text": "Hushim is listed as the son of Dan. The verse is a brief genealogical entry preserving Dan’s family line.",
    "refs": [
      "Genesis 30:6"
    ]
  },
  "Genesis 46:24": {
    "title": "Naphtali’s descendants",
    "text": "The sons of Naphtali are named. The list continues the record of Jacob’s descendants through Bilhah.",
    "refs": [
      "Genesis 30:8"
    ]
  },
  "Genesis 46:25": {
    "title": "Bilhah’s descendants summarized",
    "text": "The verse summarizes the descendants born to Jacob through Bilhah and gives their number. The passage organizes the family count by mothers and their lines.",
    "refs": [
      "Genesis 30:3–8"
    ]
  },
  "Genesis 46:26": {
    "title": "Those who came with Jacob",
    "text": "The text counts the persons belonging to Jacob who came into Egypt, excluding the wives of his sons. The total reflects the genealogical accounting used in this passage.",
    "refs": [
      "Genesis 46:27"
    ]
  },
  "Genesis 46:27": {
    "title": "Seventy persons in Jacob’s household",
    "text": "The verse gives the total of Jacob’s household in Egypt as seventy persons, including Joseph and his sons already in Egypt. The number marks the small beginning of the family that will later grow into a people in Egypt.",
    "refs": [
      "Exodus 1:5",
      "Deuteronomy 10:22"
    ]
  },
  "Genesis 46:28": {
    "title": "Judah sent ahead to Joseph",
    "text": "Jacob sends Judah ahead to direct the way to Goshen, and the family comes to that region. Judah’s role in the journey foreshadows his growing responsibility within the family.",
    "refs": [
      "Genesis 43:8–9"
    ]
  },
  "Genesis 46:29": {
    "title": "Joseph reunites with Jacob",
    "text": "Joseph prepares his chariot and goes to Goshen to meet his father. When they meet, Joseph falls on Jacob’s neck and weeps for a long time, bringing the long separation to an emotional end.",
    "refs": [
      "Genesis 45:14–15"
    ]
  },
  "Genesis 46:30": {
    "title": "Jacob can die in peace",
    "text": "Jacob tells Joseph he can now die after seeing Joseph’s face and knowing he is alive. The statement expresses profound relief after years of believing his son had been killed.",
    "refs": [
      "Genesis 37:33–35"
    ]
  },
  "Genesis 46:31": {
    "title": "Joseph prepares to speak to Pharaoh",
    "text": "Joseph tells his brothers and his father’s household that he will report their arrival to Pharaoh. He begins arranging the family’s settlement and public status in Egypt.",
    "refs": [
      "Genesis 47:1"
    ]
  },
  "Genesis 46:32": {
    "title": "The family’s occupation is explained",
    "text": "Joseph says his family are keepers of livestock and have brought their flocks and herds. Their occupation is relevant to the Egyptian setting and to where Pharaoh will allow them to settle.",
    "refs": [
      "Genesis 47:3–4"
    ]
  },
  "Genesis 46:33": {
    "title": "Pharaoh asks their occupation",
    "text": "Joseph says Pharaoh will ask what their occupation is. He prepares the family to answer clearly when they appear before the king.",
    "refs": [
      "Genesis 47:3"
    ]
  },
  "Genesis 46:34": {
    "title": "Goshen offered to shepherds",
    "text": "Joseph instructs them to say they have been keepers of livestock from their youth, so they may dwell in Goshen. The passage explains that shepherds were an abomination or detestable to Egyptians, which helps explain why Goshen is a suitable separate region for Jacob’s family.",
    "refs": [
      "Genesis 47:1–6"
    ]
  },
  "Genesis 47:1": {
    "title": "Joseph reports his family’s arrival",
    "text": "Joseph tells Pharaoh that his father and brothers have arrived from Canaan with their flocks and possessions and are in Goshen. He brings the family’s needs before the king.",
    "refs": [
      "Genesis 46:31–34"
    ]
  },
  "Genesis 47:2": {
    "title": "Five brothers appear before Pharaoh",
    "text": "Joseph presents five of his brothers to Pharaoh. The meeting establishes the family’s presence in Egypt and leads to Pharaoh’s questions about their occupation.",
    "refs": [
      "Genesis 47:3"
    ]
  },
  "Genesis 47:3": {
    "title": "The brothers identify their occupation",
    "text": "Pharaoh asks the brothers what their occupation is, and they answer that they are shepherds. Their answer follows Joseph’s preparation for this meeting.",
    "refs": [
      "Genesis 46:33–34"
    ]
  },
  "Genesis 47:4": {
    "title": "The family asks to dwell in Goshen",
    "text": "The brothers explain that famine has made pasture scarce in Canaan and ask permission to live in Goshen. Their request is for a place to keep their flocks and survive the famine.",
    "refs": [
      "Genesis 45:10"
    ]
  },
  "Genesis 47:5": {
    "title": "Pharaoh speaks to Joseph",
    "text": "Pharaoh tells Joseph that his father and brothers have come to him. The king’s response prepares the way for the family’s settlement.",
    "refs": [
      "Genesis 47:6"
    ]
  },
  "Genesis 47:6": {
    "title": "The best of the land is offered",
    "text": "Pharaoh offers the family the land of Egypt and permits them to dwell in Goshen. He also invites Joseph to appoint capable men over the royal livestock, extending trust to Joseph’s relatives.",
    "refs": [
      "Genesis 45:18"
    ]
  },
  "Genesis 47:7": {
    "title": "Jacob blesses Pharaoh",
    "text": "Joseph brings Jacob before Pharaoh, and Jacob blesses the king. The aged patriarch stands before the ruler of Egypt, and the blessing suggests that Jacob approaches him with the authority of faith rather than merely as a dependent.",
    "refs": [
      "Hebrews 7:7"
    ]
  },
  "Genesis 47:8": {
    "title": "Pharaoh asks Jacob’s age",
    "text": "Pharaoh asks Jacob how old he is. The question introduces Jacob’s reflection on the years of his life.",
    "refs": [
      "Genesis 47:9"
    ]
  },
  "Genesis 47:9": {
    "title": "Jacob describes his difficult years",
    "text": "Jacob says his years have been few and evil compared with those of his fathers. His life has included hardship, yet God has preserved him and brought him to see Joseph again.",
    "refs": [
      "Genesis 28:15",
      "Genesis 46:30"
    ]
  },
  "Genesis 47:10": {
    "title": "Jacob blesses Pharaoh again",
    "text": "Jacob blesses Pharaoh and departs from his presence. The repeated blessing frames the meeting with goodwill.",
    "refs": [
      "Genesis 47:7"
    ]
  },
  "Genesis 47:11": {
    "title": "The family settles in Rameses",
    "text": "Joseph settles his father and brothers in the best part of the land, in the region of Rameses, as Pharaoh commanded. The family receives a place to live during the famine.",
    "refs": [
      "Genesis 45:18"
    ]
  },
  "Genesis 47:12": {
    "title": "Joseph provides food for the family",
    "text": "Joseph supplies food for his father, brothers, and the whole household according to their dependents. His position becomes the means through which God preserves Jacob’s family.",
    "refs": [
      "Genesis 45:11"
    ]
  },
  "Genesis 47:13": {
    "title": "The famine grows severe",
    "text": "There is no bread throughout the land because the famine is severe, and Egypt and Canaan languish. The crisis affects the whole region, making stored grain essential for survival.",
    "refs": [
      "Genesis 41:30"
    ]
  },
  "Genesis 47:14": {
    "title": "Joseph gathers the money",
    "text": "Joseph collects the money in Egypt and Canaan in exchange for grain and brings it into Pharaoh’s house. The verse describes the economic centralization that occurs as people buy food during famine.",
    "refs": [
      "Genesis 41:48–49"
    ]
  },
  "Genesis 47:15": {
    "title": "The people run out of money",
    "text": "When the money in Egypt and Canaan is spent, the people come to Joseph asking for bread. They fear death from hunger and have no payment left.",
    "refs": [
      "Genesis 47:13–14"
    ]
  },
  "Genesis 47:16": {
    "title": "Livestock exchanged for food",
    "text": "Joseph tells the people to bring their livestock in exchange for food. This allows them to survive when money is exhausted, while their animals become part of Pharaoh’s holdings.",
    "refs": [
      "Genesis 47:17"
    ]
  },
  "Genesis 47:17": {
    "title": "The animals exchanged for provisions",
    "text": "The people bring horses, flocks, herds, and donkeys, and Joseph provides food for them through that year. The passage records the increasingly desperate measures used during the famine.",
    "refs": [
      "Genesis 47:16"
    ]
  },
  "Genesis 47:18": {
    "title": "The next year brings further need",
    "text": "At the end of the year, the people return and admit that their money and livestock are gone. They have only themselves and their land left to offer for food.",
    "refs": [
      "Genesis 47:19"
    ]
  },
  "Genesis 47:19": {
    "title": "The people offer land and labor",
    "text": "The people ask Joseph not to let them die and offer their land in exchange for food and seed. Joseph’s policies preserve their lives but also transfer their land to Pharaoh.",
    "refs": [
      "Genesis 47:20"
    ]
  },
  "Genesis 47:20": {
    "title": "Joseph acquires Egypt’s land for Pharaoh",
    "text": "Joseph buys the land of Egypt for Pharaoh as the famine grows severe, and the land becomes Pharaoh’s possession. The verse describes the political-economic result of the crisis without presenting every policy detail as a universal command.",
    "refs": [
      "Genesis 47:19"
    ]
  },
  "Genesis 47:21": {
    "title": "The population is relocated",
    "text": "Joseph moves the people into cities in the land, according to the verse’s account of his administration. The relocation is part of the system used to manage the famine and food supply.",
    "refs": [
      "Genesis 47:23"
    ]
  },
  "Genesis 47:22": {
    "title": "The priests’ land is exempted",
    "text": "The land belonging to the priests is not bought because they receive an allowance from Pharaoh. The verse describes a distinct arrangement for Egypt’s priestly class.",
    "refs": [
      "Genesis 47:26"
    ]
  },
  "Genesis 47:23": {
    "title": "Joseph provides seed",
    "text": "Joseph gives the people seed to sow the land, now held for Pharaoh. The provision allows cultivation to resume and offers a path toward future harvests.",
    "refs": [
      "Genesis 47:24"
    ]
  },
  "Genesis 47:24": {
    "title": "A fifth to Pharaoh",
    "text": "Joseph establishes that one fifth of the harvest will go to Pharaoh and four fifths will remain for seed and food. The verse records the tax arrangement in Egypt that followed the famine crisis.",
    "refs": [
      "Genesis 47:26"
    ]
  },
  "Genesis 47:25": {
    "title": "The people thank Joseph",
    "text": "The people say Joseph has saved their lives and ask to find favor in Pharaoh’s sight. Their words acknowledge the immediate relief his policy provided during famine.",
    "refs": [
      "Genesis 47:19"
    ]
  },
  "Genesis 47:26": {
    "title": "The fifth becomes a law",
    "text": "Joseph makes the one-fifth share a law concerning Egypt’s land, with the priests’ land excepted. The narrator records the arrangement as a lasting Egyptian policy, not a command for Israel’s later covenant law.",
    "refs": [
      "Genesis 47:22–24"
    ]
  },
  "Genesis 47:27": {
    "title": "Israel prospers in Goshen",
    "text": "Israel dwells in Egypt in Goshen, acquires possessions, and becomes fruitful and numerous. Even while Egypt suffers famine, Jacob’s household grows under God’s preservation.",
    "refs": [
      "Genesis 1:28",
      "Genesis 46:3"
    ]
  },
  "Genesis 47:28": {
    "title": "Jacob lives seventeen years in Egypt",
    "text": "Jacob lives in Egypt seventeen years, and his full lifespan is one hundred and forty-seven years. The verse prepares for his final instructions and death.",
    "refs": [
      "Genesis 47:9"
    ]
  },
  "Genesis 47:29": {
    "title": "Jacob asks Joseph for a pledge",
    "text": "As Jacob’s death approaches, he asks Joseph to place a hand under his thigh and promise not to bury him in Egypt. He wants to be buried with his fathers in Canaan, showing his continuing attachment to God’s promised land.",
    "refs": [
      "Genesis 49:29–30"
    ]
  },
  "Genesis 47:30": {
    "title": "Jacob requests burial with his fathers",
    "text": "Jacob asks Joseph to carry him out of Egypt and bury him in the burial place of his fathers. Joseph agrees, and Jacob’s request expresses faith that Egypt is not the final home of the covenant family.",
    "refs": [
      "Genesis 50:13"
    ]
  },
  "Genesis 47:31": {
    "title": "Joseph swears to Jacob",
    "text": "Jacob asks Joseph to swear, and Joseph does so. Israel bows at the head of his bed, a final gesture of gratitude or worshipful reverence as the promise is secured.",
    "refs": [
      "Hebrews 11:21"
    ]
  },
  "Genesis 48:1": {
    "title": "Joseph brings his sons to Jacob",
    "text": "Joseph is told that his father is ill, so he takes Manasseh and Ephraim to visit him. The visit becomes an occasion for Jacob to bless the next generation.",
    "refs": [
      "Genesis 41:50–52"
    ]
  },
  "Genesis 48:2": {
    "title": "Jacob strengthens himself to sit up",
    "text": "Jacob is told Joseph has arrived and Israel gathers his strength to sit on the bed. The scene emphasizes the importance of this final family meeting.",
    "refs": [
      "Genesis 48:1"
    ]
  },
  "Genesis 48:3": {
    "title": "God Almighty appeared at Luz",
    "text": "Jacob recalls that God Almighty appeared to him at Luz in Canaan and blessed him. He roots his words to Joseph’s sons in God’s earlier revelation and promise.",
    "refs": [
      "Genesis 35:9–12"
    ]
  },
  "Genesis 48:4": {
    "title": "God’s promise of descendants and land",
    "text": "Jacob recalls God’s promise to make him fruitful, multiply him, and give the land to his descendants. His blessing passes on the covenant hope that God had given to Abraham, Isaac, and Jacob.",
    "refs": [
      "Genesis 28:13–14"
    ]
  },
  "Genesis 48:5": {
    "title": "Ephraim and Manasseh counted as Jacob’s",
    "text": "Jacob says Ephraim and Manasseh will be his, like Reuben and Simeon. By adopting Joseph’s sons into his own tribal family, Jacob gives them a place among Israel’s inheritance lines.",
    "refs": [
      "Joshua 14:4"
    ]
  },
  "Genesis 48:6": {
    "title": "Other children remain Joseph’s",
    "text": "Any children Joseph has after Ephraim and Manasseh will be counted under their brothers’ names for inheritance. Jacob establishes the status of these two sons as the principal heirs within Joseph’s line.",
    "refs": [
      "Genesis 48:5"
    ]
  },
  "Genesis 48:7": {
    "title": "Jacob remembers Rachel’s death",
    "text": "Jacob recalls Rachel’s death on the way from Padan and her burial near Ephrath, now called Bethlehem. This personal memory briefly interrupts the blessing and recalls the sorrow in his family history.",
    "refs": [
      "Genesis 35:16–20"
    ]
  },
  "Genesis 48:8": {
    "title": "Jacob asks who the boys are",
    "text": "Jacob sees Joseph’s sons and asks who they are. The question leads Joseph to present them formally for their grandfather’s blessing.",
    "refs": [
      "Genesis 48:9"
    ]
  },
  "Genesis 48:9": {
    "title": "Joseph presents his sons",
    "text": "Joseph explains that these are the sons God gave him in Egypt, and Jacob asks that they be brought near so he may bless them. Joseph acknowledges God as the giver of his children despite his years of suffering abroad.",
    "refs": [
      "Genesis 41:50–52"
    ]
  },
  "Genesis 48:10": {
    "title": "Jacob embraces his grandsons",
    "text": "Jacob’s eyes are dim with age, and Joseph brings the boys near. Jacob kisses and embraces them, showing affection before pronouncing the blessing.",
    "refs": [
      "Genesis 27:1"
    ]
  },
  "Genesis 48:11": {
    "title": "Jacob never expected to see Joseph again",
    "text": "Jacob says he did not expect to see Joseph’s face, yet God has also let him see Joseph’s children. His words acknowledge God’s surprising restoration after years of grief.",
    "refs": [
      "Genesis 37:33–35"
    ]
  },
  "Genesis 48:12": {
    "title": "Joseph bows before Jacob",
    "text": "Joseph brings the boys away from Jacob’s knees and bows with his face to the earth. The gesture marks respect before the blessing is given.",
    "refs": [
      "Genesis 47:31"
    ]
  },
  "Genesis 48:13": {
    "title": "Joseph positions the boys",
    "text": "Joseph places Ephraim at his right hand toward Jacob’s left, and Manasseh at his left hand toward Jacob’s right. Joseph arranges them according to the customary order for the firstborn blessing.",
    "refs": [
      "Genesis 48:14"
    ]
  },
  "Genesis 48:14": {
    "title": "Jacob crosses his hands",
    "text": "Israel crosses his hands, placing his right hand on Ephraim, the younger, and his left on Manasseh, the firstborn. The action is deliberate and signals a reversal of customary birth order.",
    "refs": [
      "Genesis 48:19"
    ]
  },
  "Genesis 48:15": {
    "title": "Jacob blesses Joseph through God’s care",
    "text": "Jacob blesses Joseph and invokes the God before whom Abraham and Isaac walked and the God who shepherded him all his life. He remembers God as faithful guide and provider across generations.",
    "refs": [
      "Psalm 23:1"
    ]
  },
  "Genesis 48:16": {
    "title": "The angel who redeemed Jacob",
    "text": "Jacob asks the Angel who redeemed him from all evil to bless the boys, and he names them within the family of Abraham and Isaac. The language refers to God’s redeeming care expressed through His messenger; the verse alone should not be made to settle every question about divine identity.",
    "refs": [
      "Genesis 31:11–13",
      "Genesis 32:24–30"
    ]
  },
  "Genesis 48:17": {
    "title": "Joseph objects to the crossed hands",
    "text": "Joseph sees that Jacob has placed his right hand on Ephraim and tries to move it to Manasseh. He assumes the customary firstborn order should govern the blessing.",
    "refs": [
      "Genesis 48:14"
    ]
  },
  "Genesis 48:18": {
    "title": "Joseph points to the firstborn",
    "text": "Joseph tells his father that Manasseh is the firstborn and asks that Jacob place his right hand on him. Joseph’s objection reflects the normal expectation of birth order.",
    "refs": [
      "Genesis 48:14"
    ]
  },
  "Genesis 48:19": {
    "title": "Jacob insists Ephraim will be greater",
    "text": "Jacob refuses and says he knows what he is doing: Manasseh will become a people, but Ephraim will be greater. The blessing reverses the expected order, as had happened earlier in the patriarchal family.",
    "refs": [
      "Genesis 25:23"
    ]
  },
  "Genesis 48:20": {
    "title": "Israel blesses the boys by name",
    "text": "Jacob blesses them and says Israel will use their names in a blessing, placing Ephraim before Manasseh. The verse explains the lasting significance of the blessing and the tribes’ names.",
    "refs": [
      "Numbers 2:18–21"
    ]
  },
  "Genesis 48:21": {
    "title": "Jacob expects God to bring them back",
    "text": "Jacob tells Joseph he is dying but God will be with them and bring them again to the land of their fathers. The promise looks beyond Egypt toward the promised inheritance.",
    "refs": [
      "Genesis 46:3–4"
    ]
  },
  "Genesis 48:22": {
    "title": "Joseph receives an extra portion",
    "text": "Jacob gives Joseph one portion above his brothers, which he took from the Amorite with his sword and bow. The verse is difficult in its historical details, but it clearly assigns Joseph a special inheritance within the family.",
    "refs": [
      "Joshua 24:32"
    ]
  },
  "Genesis 49:1": {
    "title": "Jacob gathers his sons",
    "text": "Jacob calls his sons together to tell them what will happen in days to come. His final words include blessings, rebukes, and prophetic statements about the tribes descending from them.",
    "refs": [
      "Deuteronomy 33:1"
    ]
  },
  "Genesis 49:2": {
    "title": "Israel calls for his sons to listen",
    "text": "Jacob asks his sons to gather and hear him, identifying himself as Israel. The words that follow address the future of the family as a whole.",
    "refs": [
      "Genesis 49:1"
    ]
  },
  "Genesis 49:3": {
    "title": "Reuben’s dignity as firstborn",
    "text": "Jacob calls Reuben his firstborn, his might, and the beginning of his strength. The verse acknowledges Reuben’s natural place as firstborn before explaining why he will not retain preeminence.",
    "refs": [
      "Genesis 35:22"
    ]
  },
  "Genesis 49:4": {
    "title": "Reuben loses preeminence",
    "text": "Jacob describes Reuben as unstable as water and recalls his violation of his father’s bed. Because of this act, Reuben will not excel; the statement connects moral conduct with consequences for leadership in the family.",
    "refs": [
      "Genesis 35:22",
      "1 Chronicles 5:1"
    ]
  },
  "Genesis 49:5": {
    "title": "Simeon and Levi are linked in violence",
    "text": "Jacob calls Simeon and Levi brethren whose instruments are instruments of cruelty. The rebuke recalls their violent revenge at Shechem and does not present it as a righteous model.",
    "refs": [
      "Genesis 34:25–30"
    ]
  },
  "Genesis 49:6": {
    "title": "Jacob rejects their counsel and anger",
    "text": "Jacob says his soul will not enter their secret counsel and his honor will not be united with their assembly, because they killed men in anger and hamstrung oxen. He condemns the violence that marked their response at Shechem.",
    "refs": [
      "Genesis 34:25"
    ]
  },
  "Genesis 49:7": {
    "title": "Their anger brings dispersion",
    "text": "Jacob curses their fierce anger and says Simeon and Levi will be divided in Jacob and scattered in Israel. The prophecy anticipates their different tribal settlements and the consequences of their violence.",
    "refs": [
      "Joshua 19:1",
      "Joshua 21:1–8"
    ]
  },
  "Genesis 49:8": {
    "title": "Judah will receive praise",
    "text": "Jacob says Judah’s brothers will praise him and his hand will be on the neck of his enemies. The blessing portrays Judah as a tribe with future strength and leadership.",
    "refs": [
      "1 Chronicles 5:2"
    ]
  },
  "Genesis 49:9": {
    "title": "Judah as a lion",
    "text": "Judah is compared to a lion that crouches and lies down after prey. The image conveys strength, authority, and the expectation of lasting leadership.",
    "refs": [
      "Numbers 24:9"
    ]
  },
  "Genesis 49:10": {
    "title": "The ruler from Judah",
    "text": "Jacob says the sceptre will not depart from Judah nor a lawgiver from between his feet until Shiloh comes, and the people will gather to him. This is a major messianic passage in Christian interpretation; the precise meaning of “Shiloh” is debated, while later Scripture associates royal and messianic hope with Judah’s line.",
    "refs": [
      "2 Samuel 7:12–16",
      "Revelation 5:5"
    ]
  },
  "Genesis 49:11": {
    "title": "Abundance pictured through vine and wine",
    "text": "Jacob describes Judah tying his foal to a vine and washing garments in wine. The imagery evokes extraordinary abundance and is part of the poetic blessing rather than a literal instruction.",
    "refs": [
      "Isaiah 63:1–3"
    ]
  },
  "Genesis 49:12": {
    "title": "Eyes and teeth as images of plenty",
    "text": "The description of eyes dark with wine and teeth white with milk uses bodily imagery to portray abundance and prosperity. It continues the poetic picture of Judah’s future fruitfulness.",
    "refs": [
      "Deuteronomy 33:13–17"
    ]
  },
  "Genesis 49:13": {
    "title": "Zebulun near the sea",
    "text": "Jacob says Zebulun will dwell by the haven of the sea and be a haven for ships. The statement anticipates a location and role associated with trade and coastal access, though tribal boundaries in later texts require careful comparison.",
    "refs": [
      "Joshua 19:10–16"
    ]
  },
  "Genesis 49:14": {
    "title": "Issachar as a strong donkey",
    "text": "Issachar is compared to a strong donkey lying between burdens. The image suggests strength and labor, and the following verse describes his response to a pleasant resting place.",
    "refs": [
      "Deuteronomy 33:18"
    ]
  },
  "Genesis 49:15": {
    "title": "Issachar chooses rest and service",
    "text": "Jacob says Issachar sees a good resting place and pleasant land, yet bends his shoulder to bear and becomes a servant under tribute. The poem portrays a tribe willing to accept labor and subjection for the sake of its land.",
    "refs": [
      "Joshua 19:17–23"
    ]
  },
  "Genesis 49:16": {
    "title": "Dan will judge his people",
    "text": "Jacob says Dan will judge his people as one of the tribes of Israel. The name Dan is linked with judgment, and the saying anticipates the tribe’s role within Israel.",
    "refs": [
      "Judges 13:2"
    ]
  },
  "Genesis 49:17": {
    "title": "Dan as a serpent by the road",
    "text": "Dan is compared to a serpent that bites a horse’s heels and causes its rider to fall. The image suggests a smaller force using unexpected tactics; it is poetic imagery, not a command for deceit.",
    "refs": [
      "Judges 18:27–29"
    ]
  },
  "Genesis 49:18": {
    "title": "Jacob declares hope in God’s salvation",
    "text": "Jacob pauses to say, “I have waited for thy salvation, O LORD.” This brief prayer anchors the surrounding tribal sayings in dependence on the LORD’s deliverance.",
    "refs": [
      "Psalm 25:5"
    ]
  },
  "Genesis 49:19": {
    "title": "Gad will face attack and counterattack",
    "text": "Jacob says troops will overcome Gad, but Gad will overcome at the last. The saying anticipates conflict and resilience in the tribe’s history.",
    "refs": [
      "Deuteronomy 33:20–21"
    ]
  },
  "Genesis 49:20": {
    "title": "Asher’s food will be rich",
    "text": "Jacob says Asher’s bread will be fat and he will yield royal dainties. The blessing pictures fertile land and food fit for a king’s table.",
    "refs": [
      "Deuteronomy 33:24"
    ]
  },
  "Genesis 49:21": {
    "title": "Naphtali as a hind set free",
    "text": "Naphtali is compared to a hind let loose and associated with goodly words. The poetic image suggests freedom and grace, though the exact reference of the phrase is uncertain.",
    "refs": [
      "Deuteronomy 33:23"
    ]
  },
  "Genesis 49:22": {
    "title": "Joseph as a fruitful bough",
    "text": "Joseph is compared to a fruitful branch by a well, whose branches run over the wall. The image celebrates Joseph’s fruitfulness and the growth of his descendants despite hardship.",
    "refs": [
      "Genesis 41:52"
    ]
  },
  "Genesis 49:23": {
    "title": "Joseph faced fierce opposition",
    "text": "Archers bitterly grieved and shot at Joseph and hated him. The imagery recalls the opposition he endured from his brothers and later suffering, while the blessing moves toward God’s sustaining help.",
    "refs": [
      "Genesis 37:18–28"
    ]
  },
  "Genesis 49:24": {
    "title": "Joseph’s strength comes from God",
    "text": "Joseph’s bow remains strong, and his arms are strengthened by the hands of the mighty God of Jacob, described as the Shepherd and Stone of Israel. The verse explicitly credits God as the source of Joseph’s endurance and stability.",
    "refs": [
      "Psalm 23:1",
      "Isaiah 28:16"
    ]
  },
  "Genesis 49:25": {
    "title": "Blessings from God Almighty",
    "text": "Jacob speaks of blessings from the God of his father and God Almighty, including blessings from heaven, the deep, the breasts, and the womb. The poetic language describes comprehensive provision and fruitfulness from God.",
    "refs": [
      "Genesis 17:1–6"
    ]
  },
  "Genesis 49:26": {
    "title": "Joseph receives a distinguished blessing",
    "text": "Jacob says Joseph’s blessings exceed those of his ancestors and will rest on his head as the one separated from his brothers. The verse gives Joseph an unusually rich blessing after his years of suffering and service.",
    "refs": [
      "Deuteronomy 33:13–17"
    ]
  },
  "Genesis 49:27": {
    "title": "Benjamin as a ravening wolf",
    "text": "Benjamin is compared to a wolf that devours prey and divides spoil. The image depicts fierce strength in battle and is poetic description, not an endorsement of cruelty.",
    "refs": [
      "Judges 20:14–16"
    ]
  },
  "Genesis 49:28": {
    "title": "The twelve tribes are blessed",
    "text": "Jacob’s sons are named as the twelve tribes of Israel, and each receives a blessing appropriate to him. The blessings differ in form and content, showing that the future of the tribes will not be identical.",
    "refs": [
      "Deuteronomy 33:1–29"
    ]
  },
  "Genesis 49:29": {
    "title": "Jacob gives burial instructions",
    "text": "Jacob commands his sons to bury him with his fathers in the cave in the field of Ephron the Hittite. His instructions show his continuing faith in the family’s connection to the promised land.",
    "refs": [
      "Genesis 47:29–30"
    ]
  },
  "Genesis 49:30": {
    "title": "The cave at Machpelah",
    "text": "Jacob identifies the cave purchased by Abraham from Ephron as the burial place for his family. The land purchase is a concrete family possession within the larger promise of Canaan.",
    "refs": [
      "Genesis 23:16–20"
    ]
  },
  "Genesis 49:31": {
    "title": "The patriarchs buried there",
    "text": "Jacob recalls that Abraham, Sarah, Isaac, Rebekah, and Leah were buried in the cave. He situates his own burial within the family history of faith and promise.",
    "refs": [
      "Genesis 23:19",
      "Genesis 35:29"
    ]
  },
  "Genesis 49:32": {
    "title": "The field and cave were purchased",
    "text": "Jacob notes that the field and cave were purchased from the sons of Heth. The detail establishes the burial place as a legally acquired family possession.",
    "refs": [
      "Genesis 23:17–20"
    ]
  },
  "Genesis 49:33": {
    "title": "Jacob dies after his instructions",
    "text": "After finishing his commands, Jacob gathers his feet into the bed, breathes his last, and is gathered to his people. His death closes the patriarchal life while the covenant promises continue through his descendants.",
    "refs": [
      "Genesis 25:8",
      "Genesis 50:13"
    ]
  },
  "Genesis 50:1": {
    "title": "Joseph mourns his father",
    "text": "Joseph falls on Jacob’s face, weeps over him, and kisses him. His grief shows the affection between father and son after their reunion in Egypt.",
    "refs": [
      "Genesis 46:29–30"
    ]
  },
  "Genesis 50:2": {
    "title": "Jacob is embalmed",
    "text": "Joseph commands his servants, the physicians, to embalm Jacob. This reflects Egyptian burial customs and prepares the body for the journey to Canaan.",
    "refs": [
      "Genesis 50:3"
    ]
  },
  "Genesis 50:3": {
    "title": "The mourning period lasts seventy days",
    "text": "The Egyptians mourn Jacob for seventy days. The public mourning reflects the respect shown to Joseph’s father and the significance of Joseph’s position in Egypt.",
    "refs": [
      "Genesis 50:7"
    ]
  },
  "Genesis 50:4": {
    "title": "Joseph asks Pharaoh’s household",
    "text": "After the mourning period, Joseph speaks to Pharaoh’s household and asks them to convey his request to Pharaoh. He approaches the king through the proper channels before leaving Egypt.",
    "refs": [
      "Genesis 50:5"
    ]
  },
  "Genesis 50:5": {
    "title": "Joseph repeats Jacob’s burial oath",
    "text": "Joseph says his father made him swear to bury him in the tomb he prepared in Canaan, and asks permission to go bury him and return. The request honors Jacob’s final command and the family’s connection to the promised land.",
    "refs": [
      "Genesis 47:29–30"
    ]
  },
  "Genesis 50:6": {
    "title": "Pharaoh grants permission",
    "text": "Pharaoh tells Joseph to go and bury his father as he swore. The king honors Joseph’s request and allows the journey to proceed.",
    "refs": [
      "Genesis 50:5"
    ]
  },
  "Genesis 50:7": {
    "title": "Egyptian officials accompany Joseph",
    "text": "Joseph goes to bury his father, accompanied by Pharaoh’s servants, elders, and the elders of Egypt. The large delegation reflects the respect accorded to Joseph and his father.",
    "refs": [
      "Genesis 50:3"
    ]
  },
  "Genesis 50:8": {
    "title": "The household remains in Egypt",
    "text": "Joseph’s household, his brothers, and his father’s household travel, while their children and livestock remain in Goshen. The arrangements allow the funeral journey while preserving the family’s settlement in Egypt.",
    "refs": [
      "Genesis 46:5–7"
    ]
  },
  "Genesis 50:9": {
    "title": "A great company travels",
    "text": "Chariots and horsemen accompany the procession, making it very great. The funeral journey is a major public event rather than a private family burial.",
    "refs": [
      "Genesis 50:7"
    ]
  },
  "Genesis 50:10": {
    "title": "Mourning at the threshing floor",
    "text": "The procession reaches the threshing floor of Atad beyond the Jordan and mourns greatly for seven days. The location and ritual mark the solemnity of Jacob’s burial.",
    "refs": [
      "Genesis 50:11"
    ]
  },
  "Genesis 50:11": {
    "title": "Abel-mizraim is named",
    "text": "The Canaanites observe the mourning and name the place Abel-mizraim because of the great lamentation by the Egyptians. The name preserves the memory of the funeral procession and its public impact.",
    "refs": [
      "Genesis 50:10"
    ]
  },
  "Genesis 50:12": {
    "title": "Jacob’s sons obey him",
    "text": "Jacob’s sons do as he commanded them. Their actions fulfill his final request and honor his wishes concerning burial.",
    "refs": [
      "Genesis 49:29–32"
    ]
  },
  "Genesis 50:13": {
    "title": "Jacob is buried in Machpelah",
    "text": "The sons carry Jacob to Canaan and bury him in the cave of Machpelah, the field Abraham purchased from Ephron. The burial returns Jacob’s body to the family’s burial place in the promised land.",
    "refs": [
      "Genesis 23:16–20"
    ]
  },
  "Genesis 50:14": {
    "title": "Joseph returns to Egypt",
    "text": "After burying his father, Joseph returns to Egypt with his brothers and all who accompanied him. The family’s life in Egypt continues after Jacob’s death.",
    "refs": [
      "Genesis 46:5–7"
    ]
  },
  "Genesis 50:15": {
    "title": "Joseph’s brothers fear revenge",
    "text": "After Jacob dies, Joseph’s brothers fear he may hate them and repay them for their evil. Their fear shows that the old guilt remains even after Joseph’s reconciliation with them.",
    "refs": [
      "Genesis 45:4–5"
    ]
  },
  "Genesis 50:16": {
    "title": "The brothers send a message",
    "text": "The brothers send Joseph a message saying their father instructed him to forgive their transgression. The text does not independently confirm that Jacob gave this instruction; it records the message the brothers send in their fear.",
    "refs": [
      "Genesis 50:17"
    ]
  },
  "Genesis 50:17": {
    "title": "Joseph weeps at their plea",
    "text": "The brothers ask Joseph to forgive the servants of their father’s God, and Joseph weeps when they speak to him. His tears show the emotional pain caused by their continued suspicion after he had already shown mercy.",
    "refs": [
      "Genesis 45:14–15"
    ]
  },
  "Genesis 50:18": {
    "title": "The brothers bow before Joseph",
    "text": "Joseph’s brothers come and fall before him, offering themselves as his servants. Their posture echoes Joseph’s dreams and reveals their fear of his authority.",
    "refs": [
      "Genesis 37:7–9"
    ]
  },
  "Genesis 50:19": {
    "title": "Joseph refuses to take God’s place",
    "text": "Joseph asks whether he is in the place of God. He refuses to claim ultimate judgment for himself and recognizes that vengeance belongs to God.",
    "refs": [
      "Deuteronomy 32:35",
      "Romans 12:19"
    ]
  },
  "Genesis 50:20": {
    "title": "God brings good from human evil",
    "text": "Joseph says his brothers intended evil against him, but God meant it for good to preserve many lives. The verse does not call their betrayal good; it declares that God’s providence overruled their evil for a saving purpose.",
    "refs": [
      "Genesis 45:5–8",
      "Romans 8:28"
    ]
  },
  "Genesis 50:21": {
    "title": "Joseph comforts and provides for them",
    "text": "Joseph tells his brothers not to fear and promises to nourish them and their children. He answers their fear with kindness and practical provision.",
    "refs": [
      "Genesis 47:12"
    ]
  },
  "Genesis 50:22": {
    "title": "Joseph lives to one hundred and ten",
    "text": "Joseph dwells in Egypt with his father’s household and lives to the age of one hundred and ten. The verse records the length of his life and the continuing growth of the family in Egypt.",
    "refs": [
      "Joshua 24:32"
    ]
  },
  "Genesis 50:23": {
    "title": "Joseph sees the third generation",
    "text": "Joseph sees Ephraim’s children to the third generation, and the children of Machir, Manasseh’s son, are brought up on Joseph’s knees. The verse portrays Joseph living to see the family branches grow.",
    "refs": [
      "Genesis 41:50–52"
    ]
  },
  "Genesis 50:24": {
    "title": "Joseph trusts God’s promise of visitation",
    "text": "Joseph tells his brothers he is dying but says God will surely visit them and bring them out of Egypt to the land promised to Abraham, Isaac, and Jacob. His faith looks beyond his own lifetime to God’s covenant faithfulness.",
    "refs": [
      "Genesis 15:13–16",
      "Exodus 3:16–17"
    ]
  },
  "Genesis 50:25": {
    "title": "Joseph makes Israel swear about his bones",
    "text": "Joseph makes the children of Israel swear that they will carry his bones out of Egypt when God visits them. His request expresses faith that Egypt is not the final home of Israel.",
    "refs": [
      "Exodus 13:19"
    ]
  },
  "Genesis 50:26": {
    "title": "Joseph dies and is placed in a coffin",
    "text": "Joseph dies at one hundred and ten, is embalmed, and is placed in a coffin in Egypt. Genesis ends with Joseph’s body still in Egypt, awaiting the future exodus and fulfillment of God’s promise.",
    "refs": [
      "Joshua 24:32",
      "Hebrews 11:22"
    ]
  },
  "Genesis 5:1": {
    "title": "The book of Adam’s generations",
    "text": "The chapter begins the record of Adam’s descendants and recalls that God made mankind in His likeness. The genealogy connects the creation account to the family line that continues through Noah.",
    "refs": [
      "Genesis 1:26–28"
    ]
  },
  "Genesis 5:2": {
    "title": "Male and female created and blessed",
    "text": "God created them male and female, blessed them, and called their name Adam in the day they were created. The verse summarizes humanity’s origin and shared human identity before listing the generations.",
    "refs": [
      "Genesis 1:27"
    ]
  },
  "Genesis 5:3": {
    "title": "Seth born in Adam’s likeness",
    "text": "Adam fathers Seth in his own likeness and image. The wording echoes humanity’s creation in God’s image while describing the transmission of human life through generations.",
    "refs": [
      "Genesis 1:26",
      "Genesis 4:25"
    ]
  },
  "Genesis 5:4": {
    "title": "Adam’s other sons and daughters",
    "text": "Adam lives many years after Seth’s birth and has other sons and daughters. The genealogy names Seth as the line being traced without claiming that he was Adam’s only child.",
    "refs": [
      "Genesis 4:25"
    ]
  },
  "Genesis 5:5": {
    "title": "Adam dies",
    "text": "Adam lives nine hundred and thirty years and dies. The repeated formula of death begins to mark the genealogy and reminds readers of mortality after the entrance of sin into the human story.",
    "refs": [
      "Genesis 2:17",
      "Romans 5:12"
    ]
  },
  "Genesis 5:6": {
    "title": "Seth fathers Enos",
    "text": "Seth fathers Enos at the age of one hundred and five. The genealogy continues the line through which the account will proceed toward Noah.",
    "refs": [
      "Genesis 4:26"
    ]
  },
  "Genesis 5:7": {
    "title": "Seth’s descendants",
    "text": "Seth lives after Enos’s birth and fathers other sons and daughters. The verse records the continuation and growth of the family line.",
    "refs": [
      "Genesis 5:4"
    ]
  },
  "Genesis 5:8": {
    "title": "Seth dies",
    "text": "Seth’s lifespan is given as nine hundred and twelve years, and he dies. The repeated wording emphasizes that even the early generations of humanity are subject to death.",
    "refs": [
      "Genesis 5:5"
    ]
  },
  "Genesis 5:9": {
    "title": "Enos fathers Cainan",
    "text": "Enos fathers Cainan at ninety years old. The genealogy advances to another generation in Adam’s family line.",
    "refs": [
      "Luke 3:38"
    ]
  },
  "Genesis 5:10": {
    "title": "Enos’s descendants",
    "text": "Enos lives after Cainan’s birth and fathers other sons and daughters. The account emphasizes the continued growth of humanity across generations.",
    "refs": [
      "Genesis 5:7"
    ]
  },
  "Genesis 5:11": {
    "title": "Enos dies",
    "text": "Enos lives nine hundred and five years and dies. The repeated death formula keeps mortality in view throughout the genealogy.",
    "refs": [
      "Genesis 5:8"
    ]
  },
  "Genesis 5:12": {
    "title": "Cainan fathers Mahalaleel",
    "text": "Cainan fathers Mahalaleel at seventy years old. The genealogy continues without pausing to narrate the individual events of each person’s life.",
    "refs": [
      "Luke 3:37"
    ]
  },
  "Genesis 5:13": {
    "title": "Cainan’s descendants",
    "text": "Cainan lives after Mahalaleel’s birth and fathers other sons and daughters. The record highlights family continuity through the generations.",
    "refs": [
      "Genesis 5:10"
    ]
  },
  "Genesis 5:14": {
    "title": "Cainan dies",
    "text": "Cainan lives nine hundred and ten years and dies. The formula continues the chapter’s pattern and contrasts with the later account of Enoch’s unusual departure from life.",
    "refs": [
      "Genesis 5:24"
    ]
  },
  "Genesis 5:15": {
    "title": "Mahalaleel fathers Jared",
    "text": "Mahalaleel fathers Jared at sixty-five years old. The line moves toward Enoch and eventually Noah.",
    "refs": [
      "Genesis 5:18"
    ]
  },
  "Genesis 5:16": {
    "title": "Mahalaleel’s descendants",
    "text": "Mahalaleel lives after Jared’s birth and fathers other sons and daughters. The genealogy records the ordinary passage of generations rather than a detailed biography.",
    "refs": [
      "Genesis 5:10"
    ]
  },
  "Genesis 5:17": {
    "title": "Mahalaleel dies",
    "text": "Mahalaleel lives eight hundred and ninety-five years and dies. The chapter’s repeated account of death reinforces the consequences of humanity’s fallen condition.",
    "refs": [
      "Romans 5:12"
    ]
  },
  "Genesis 5:18": {
    "title": "Jared fathers Enoch",
    "text": "Jared fathers Enoch at one hundred and sixty-two years old. Enoch’s life will stand out from the repeated pattern that surrounds the other names in the genealogy.",
    "refs": [
      "Genesis 5:21–24"
    ]
  },
  "Genesis 5:19": {
    "title": "Jared’s descendants",
    "text": "Jared lives after Enoch’s birth and fathers other sons and daughters. The verse preserves the continuation of the family line.",
    "refs": [
      "Genesis 5:16"
    ]
  },
  "Genesis 5:20": {
    "title": "Jared dies",
    "text": "Jared lives nine hundred and sixty-two years and dies. His lifespan is among the longest recorded in the genealogy, yet the same death formula applies.",
    "refs": [
      "Genesis 5:17"
    ]
  },
  "Genesis 5:21": {
    "title": "Enoch fathers Methuselah",
    "text": "Enoch fathers Methuselah at sixty-five years old. The account then emphasizes Enoch’s walk with God, distinguishing his description from the surrounding entries.",
    "refs": [
      "Genesis 5:22"
    ]
  },
  "Genesis 5:22": {
    "title": "Enoch walks with God",
    "text": "Enoch walks with God after Methuselah’s birth for three hundred years and fathers other sons and daughters. The phrase describes an enduring relationship of faithfulness to God.",
    "refs": [
      "Genesis 6:9"
    ]
  },
  "Genesis 5:23": {
    "title": "Enoch’s lifespan",
    "text": "Enoch’s total lifespan is three hundred and sixty-five years, shorter than the other ages listed in this chapter. The next verse explains his unusual end.",
    "refs": [
      "Genesis 5:24"
    ]
  },
  "Genesis 5:24": {
    "title": "Enoch is taken by God",
    "text": "Enoch walks with God, and then he is not found because God takes him. The verse is distinct from the repeated statement that each other named patriarch died; Hebrews later connects Enoch’s life with faith.",
    "refs": [
      "Hebrews 11:5"
    ]
  },
  "Genesis 5:25": {
    "title": "Methuselah fathers Lamech",
    "text": "Methuselah fathers Lamech at one hundred and eighty-seven years old. The genealogy continues toward Noah’s generation and the flood narrative.",
    "refs": [
      "Genesis 5:28–29"
    ]
  },
  "Genesis 5:26": {
    "title": "Methuselah’s descendants",
    "text": "Methuselah lives after Lamech’s birth and fathers other sons and daughters. The verse continues the family record with the same structure used for earlier generations.",
    "refs": [
      "Genesis 5:22"
    ]
  },
  "Genesis 5:27": {
    "title": "Methuselah dies",
    "text": "Methuselah lives nine hundred and sixty-nine years, the longest lifespan stated in the Bible, and dies. Despite the extraordinary number of years, the genealogy still places his life under the recurring reality of death.",
    "refs": [
      "Genesis 5:5"
    ]
  },
  "Genesis 5:28": {
    "title": "Lamech fathers a son",
    "text": "Lamech fathers a son at one hundred and eighty-two years old. His words at the naming of the child will express hope for relief from the curse on the ground.",
    "refs": [
      "Genesis 5:29"
    ]
  },
  "Genesis 5:29": {
    "title": "Noah and the hope of comfort",
    "text": "Lamech names his son Noah and says he will comfort them concerning their work and the toil of their hands because of the cursed ground. His statement expresses hope for relief; the later story shows Noah’s role in preservation through the flood.",
    "refs": [
      "Genesis 3:17–19",
      "Genesis 6:8"
    ]
  },
  "Genesis 5:30": {
    "title": "Lamech’s descendants",
    "text": "Lamech lives after Noah’s birth and fathers other sons and daughters. The genealogy continues to record the family that precedes the flood.",
    "refs": [
      "Genesis 5:28"
    ]
  },
  "Genesis 5:31": {
    "title": "Lamech dies",
    "text": "Lamech lives seven hundred and seventy-seven years and dies. The repeated formula closes his entry before the chapter focuses on Noah and his sons.",
    "refs": [
      "Genesis 5:29"
    ]
  },
  "Genesis 5:32": {
    "title": "Noah fathers Shem, Ham, and Japheth",
    "text": "At five hundred years old, Noah fathers Shem, Ham, and Japheth. Their names introduce the family through which humanity will continue after the flood.",
    "refs": [
      "Genesis 6:9–10"
    ]
  },
  "Exodus 1:1": {
    "title": "Israel’s sons in Egypt",
    "text": "The names connect Exodus directly to Jacob’s family at the end of Genesis. Israel’s descendants are the same covenant family, now living in Egypt. Exodus continues the story of God’s promises rather than beginning an unrelated account.",
    "refs": [
      "Genesis 46:8–27"
    ]
  },
  "Exodus 1:2": {
    "title": "The sons of Israel",
    "text": "Reuben, Simeon, Levi, and Judah are listed first among Jacob’s sons. Levi’s inclusion leads into the family line from which Moses and Aaron will come.",
    "refs": [
      "Genesis 29:32–35",
      "Exodus 6:16–20"
    ]
  },
  "Exodus 1:3": {
    "title": "The sons of Israel",
    "text": "Issachar, Zebulun, and Benjamin are named as part of the family that entered Egypt. The list emphasizes the historical continuity of Israel’s tribes.",
    "refs": [
      "Genesis 35:16–18",
      "Genesis 46:8"
    ]
  },
  "Exodus 1:4": {
    "title": "The sons of Israel",
    "text": "Dan, Naphtali, Gad, and Asher complete this part of the list. Together, the names establish the family whose growth fulfills God’s earlier promise to Abraham.",
    "refs": [
      "Genesis 12:2",
      "Genesis 46:23–25"
    ]
  },
  "Exodus 1:5": {
    "title": "Seventy souls",
    "text": "The family entered Egypt in a small number compared with the nation Israel would become. The KJV follows the traditional count of seventy, while Acts 7:14 uses seventy-five in Stephen’s account, reflecting a different textual counting tradition.",
    "refs": [
      "Genesis 46:26–27",
      "Acts 7:14"
    ]
  },
  "Exodus 1:6": {
    "title": "Joseph and his generation die",
    "text": "Joseph’s death marks a change of era. The protection associated with Joseph’s place in Egypt will not prevent later rulers from oppressing Israel.",
    "refs": [
      "Genesis 50:22–26"
    ]
  },
  "Exodus 1:7": {
    "title": "Israel multiplies greatly",
    "text": "Israel becomes fruitful, multiplies, and fills the land. This language echoes God’s creation blessing and His promise to multiply Abraham’s descendants. The growth is presented as God’s covenant promise advancing even in a foreign land.",
    "refs": [
      "Genesis 1:28",
      "Genesis 12:2",
      "Genesis 15:5"
    ]
  },
  "Exodus 1:8": {
    "title": "A new king arises",
    "text": "The new king does not regard Joseph’s service or the earlier history favorably. Political power changes, but God’s covenant with Israel has not changed.",
    "refs": [
      "Genesis 41:39–45",
      "Genesis 15:13–14"
    ]
  },
  "Exodus 1:9": {
    "title": "Israel is viewed as a threat",
    "text": "Pharaoh describes Israel as more numerous and powerful than he wishes. His fear becomes the stated reason for oppressive policy, showing how rulers can turn insecurity into injustice.",
    "refs": [
      "Exodus 1:12",
      "Acts 7:17–19"
    ]
  },
  "Exodus 1:10": {
    "title": "Pharaoh plans to control Israel",
    "text": "Pharaoh proposes dealing shrewdly with Israel to prevent its growth and possible alliance with enemies. The passage exposes the reasoning used to justify oppression; it does not commend Pharaoh’s plan.",
    "refs": [
      "Psalm 105:24–25"
    ]
  },
  "Exodus 1:11": {
    "title": "Taskmasters and oppression",
    "text": "The Egyptians impose hard labor and use forced work to weaken Israel. The store cities named here show that Israel’s suffering is concrete and political, not merely symbolic.",
    "refs": [
      "Exodus 5:6–14",
      "Acts 7:18–19"
    ]
  },
  "Exodus 1:12": {
    "title": "Oppression fails to stop growth",
    "text": "The more Israel is afflicted, the more it multiplies. The Egyptians become distressed by this, but their hostility cannot cancel God’s stated purpose for Abraham’s descendants.",
    "refs": [
      "Genesis 15:5",
      "Exodus 1:7"
    ]
  },
  "Exodus 1:13": {
    "title": "Cruel bondage",
    "text": "The Egyptians make Israel serve with rigor. Scripture names the cruelty plainly, establishing the injustice from which God will deliver His people.",
    "refs": [
      "Exodus 2:23–25",
      "Exodus 3:7–8"
    ]
  },
  "Exodus 1:14": {
    "title": "Bitter service",
    "text": "The text describes hard labor in mortar, brick, and field work. The detailed wording preserves the severity of Israel’s bondage and prepares for God’s response to their cries.",
    "refs": [
      "Exodus 5:7–9",
      "Deuteronomy 26:6–8"
    ]
  },
  "Exodus 1:15": {
    "title": "The Hebrew midwives",
    "text": "Pharaoh turns from forced labor to a plan aimed at Hebrew newborn sons. Shiphrah and Puah are introduced as women placed in a position where obedience to God’s moral will will be tested.",
    "refs": [
      "Exodus 1:17"
    ]
  },
  "Exodus 1:16": {
    "title": "Pharaoh’s murderous order",
    "text": "Pharaoh secretly orders the midwives to kill Hebrew boys at birth. The command reveals the cruelty of the regime and the threat facing Israel’s next generation.",
    "refs": [
      "Acts 7:19",
      "Hebrews 11:23"
    ]
  },
  "Exodus 1:17": {
    "title": "The midwives fear God",
    "text": "The midwives refuse to obey Pharaoh’s murderous command because they fear God. Their action demonstrates that human authority is not absolute when it demands evil.",
    "refs": [
      "Daniel 3:16–18",
      "Acts 5:29",
      "Hebrews 11:23"
    ]
  },
  "Exodus 1:18": {
    "title": "Pharaoh questions the midwives",
    "text": "Pharaoh challenges the women because the Hebrew boys remain alive. His question confirms that the midwives’ refusal has frustrated his plan.",
    "refs": [
      "Exodus 1:16–17"
    ]
  },
  "Exodus 1:19": {
    "title": "The midwives answer Pharaoh",
    "text": "The midwives explain that Hebrew women give birth before they arrive. The narrative reports their answer but does not pause to provide a general rule about every detail of their speech; the clear emphasis is that they did not carry out Pharaoh’s killing order.",
    "refs": [
      "Exodus 1:17"
    ]
  },
  "Exodus 1:20": {
    "title": "God deals well with the midwives",
    "text": "God’s favor rests on the midwives, and Israel continues to grow. The account contrasts God’s blessing with Pharaoh’s violence.",
    "refs": [
      "Exodus 1:7",
      "Psalm 33:18–19"
    ]
  },
  "Exodus 1:21": {
    "title": "God establishes the midwives’ houses",
    "text": "Because the midwives fear God, He gives them families or household standing. The text connects their reverence and courageous refusal with divine favor without claiming that every faithful person will receive the same earthly outcome.",
    "refs": [
      "Psalm 112:1–2"
    ]
  },
  "Exodus 1:22": {
    "title": "Pharaoh commands the people",
    "text": "Pharaoh broadens the murderous policy by ordering that every Hebrew son be cast into the river. This threat directly sets the stage for Moses’ birth and rescue.",
    "refs": [
      "Exodus 2:1–10",
      "Acts 7:19–21"
    ]
  },
  "Exodus 2:1": {
    "title": "A Levite family",
    "text": "A man and woman from the tribe of Levi marry. The narrative introduces Moses’ parents without yet naming them; Exodus 6:20 later identifies them as Amram and Jochebed.",
    "refs": [
      "Exodus 6:16–20",
      "Numbers 26:59"
    ]
  },
  "Exodus 2:2": {
    "title": "Moses is born and hidden",
    "text": "The mother sees that the child is good and hides him for three months. Hebrews 11:23 remembers the parents’ faith and their refusal to be ruled by the king’s command.",
    "refs": [
      "Acts 7:20",
      "Hebrews 11:23"
    ]
  },
  "Exodus 2:3": {
    "title": "The child is placed in an ark",
    "text": "When hiding him is no longer possible, the mother places Moses in a papyrus basket sealed against water and sets it among the reeds. The word translated “ark” recalls the term used for Noah’s vessel, though the scale and purpose differ.",
    "refs": [
      "Genesis 6:14",
      "Hebrews 11:23"
    ]
  },
  "Exodus 2:4": {
    "title": "His sister watches",
    "text": "Moses’ sister remains nearby to see what will happen. Her watchfulness prepares for her practical role in bringing the child’s mother into Pharaoh’s household story.",
    "refs": [
      "Exodus 15:20",
      "Numbers 26:59"
    ]
  },
  "Exodus 2:5": {
    "title": "Pharaoh’s daughter finds Moses",
    "text": "Pharaoh’s daughter comes to the river, sees the basket, and sends a servant to retrieve it. The rescue comes from within Pharaoh’s own household, overturning the purpose of his decree.",
    "refs": [
      "Exodus 1:22",
      "Acts 7:21"
    ]
  },
  "Exodus 2:6": {
    "title": "Compassion for the Hebrew child",
    "text": "The princess recognizes that the child is Hebrew and feels compassion, despite the royal order against Hebrew boys. The narrative highlights a human response that counters the cruelty of Pharaoh’s policy.",
    "refs": [
      "Exodus 1:22",
      "Deuteronomy 10:18"
    ]
  },
  "Exodus 2:7": {
    "title": "Moses’ sister offers help",
    "text": "The girl asks whether she should find a Hebrew nurse for the child. Her question is a courageous and timely intervention within a dangerous situation.",
    "refs": [
      "Exodus 2:4"
    ]
  },
  "Exodus 2:8": {
    "title": "Moses’ mother is called",
    "text": "Pharaoh’s daughter tells the girl to go, and the child’s own mother is brought. The threatened child is returned to his mother for care through the very household that issued the decree.",
    "refs": [
      "Exodus 2:3–7"
    ]
  },
  "Exodus 2:9": {
    "title": "The mother is paid to nurse him",
    "text": "Moses’ mother receives wages to nurse her own son. The account shows providential reversal: the child survives, and his mother is supported while caring for him.",
    "refs": [
      "Psalm 9:9–10",
      "Romans 8:28"
    ]
  },
  "Exodus 2:10": {
    "title": "Moses receives his name",
    "text": "When the child grows, he is brought to Pharaoh’s daughter and becomes her son. She names him Moses because she drew him out of the water; the explanation in the text is associated with the Hebrew verb for drawing out.",
    "refs": [
      "Acts 7:21–22",
      "Hebrews 11:24–26"
    ]
  },
  "Exodus 2:11": {
    "title": "Moses sees his people’s burdens",
    "text": "As an adult, Moses goes out to his Hebrew brethren and sees their forced labor. Acts 7:23 says he was about forty when he visited his people, giving a later detail about his age.",
    "refs": [
      "Acts 7:23"
    ]
  },
  "Exodus 2:12": {
    "title": "Moses kills the Egyptian",
    "text": "Moses looks around, kills an Egyptian who was striking a Hebrew, and hides the body. The text records his act but does not present this killing as a divine command or an example to imitate; his later flight follows.",
    "refs": [
      "Acts 7:24–29",
      "Hebrews 11:24–26"
    ]
  },
  "Exodus 2:13": {
    "title": "Moses confronts a Hebrew dispute",
    "text": "The next day Moses sees two Hebrews fighting and challenges the one in the wrong. His concern for justice is evident, although the previous day’s violence shows that he has not yet learned how God will deliver Israel.",
    "refs": [
      "Acts 7:26"
    ]
  },
  "Exodus 2:14": {
    "title": "Moses’ action is exposed",
    "text": "The man asks who made Moses a ruler and judge and refers to the Egyptian’s death. Moses fears that his deed is known. Acts 7 later describes Moses as supposing his people would understand that God would deliver them through him, but they did not understand.",
    "refs": [
      "Acts 7:25–29"
    ]
  },
  "Exodus 2:15": {
    "title": "Moses flees to Midian",
    "text": "Pharaoh seeks to kill Moses, so Moses flees and sits by a well in Midian. His life in the palace ends, and a long period of preparation in the wilderness begins.",
    "refs": [
      "Acts 7:29",
      "Hebrews 11:27"
    ]
  },
  "Exodus 2:16": {
    "title": "The daughters of the priest of Midian",
    "text": "A priest of Midian has seven daughters who come to draw water for their father’s flock. The setting at a well introduces the people and place through which Moses will find refuge.",
    "refs": [
      "Genesis 24:10–20",
      "Genesis 29:1–10"
    ]
  },
  "Exodus 2:17": {
    "title": "Moses helps the women",
    "text": "Shepherds drive the women away, but Moses rises to help them and waters their flock. His intervention resembles other biblical well scenes where a meeting leads to a new household relationship, without making the events identical.",
    "refs": [
      "Genesis 29:10",
      "Exodus 2:19"
    ]
  },
  "Exodus 2:18": {
    "title": "The daughters return to Reuel",
    "text": "Their father Reuel asks why they have returned so early. The question leads them to tell him about the Egyptian who helped them.",
    "refs": [
      "Exodus 3:1",
      "Exodus 18:1"
    ]
  },
  "Exodus 2:19": {
    "title": "Moses is described as an Egyptian",
    "text": "The women explain that an Egyptian rescued them from the shepherds and drew water for them. Moses’ appearance and background lead them to describe him this way; the verse does not mean he has ceased to be Hebrew.",
    "refs": [
      "Exodus 2:11"
    ]
  },
  "Exodus 2:20": {
    "title": "Moses is invited to eat",
    "text": "Reuel asks why they left the man behind and tells them to call him. Hospitality opens the way for Moses to remain with the family rather than continue as a fugitive alone.",
    "refs": [
      "Genesis 18:1–8",
      "Hebrews 13:2"
    ]
  },
  "Exodus 2:21": {
    "title": "Moses dwells with the family",
    "text": "Moses agrees to live with the man, who gives him Zipporah as a wife. Moses begins a family life in Midian during the years before God sends him back to Egypt.",
    "refs": [
      "Exodus 18:2–4"
    ]
  },
  "Exodus 2:22": {
    "title": "Gershom and the feeling of exile",
    "text": "Zipporah bears a son named Gershom, a name connected in the verse with Moses’ status as a stranger in a foreign land. Moses has found a home, yet he remains away from his people and their suffering.",
    "refs": [
      "Acts 7:29",
      "Exodus 18:3"
    ]
  },
  "Exodus 2:23": {
    "title": "Israel cries under bondage",
    "text": "After many days the king of Egypt dies, but Israel’s suffering continues. Their cry rises because of bondage; a change of ruler alone has not brought deliverance.",
    "refs": [
      "Exodus 1:14",
      "Exodus 3:7"
    ]
  },
  "Exodus 2:24": {
    "title": "God remembers His covenant",
    "text": "God hears Israel’s groaning and remembers His covenant with Abraham, Isaac, and Jacob. “Remembered” does not mean God had forgotten; it describes His turning to act faithfully according to the covenant He had established.",
    "refs": [
      "Genesis 15:13–14",
      "Genesis 17:7",
      "Leviticus 26:42"
    ]
  },
  "Exodus 2:25": {
    "title": "God sees and knows",
    "text": "God looks upon Israel and knows their condition. The verse prepares for His call to Moses in chapter 3. In Oneness understanding, this is the one God acting in faithful relationship with His people; the verse itself emphasizes His awareness and covenant concern, not a technical explanation of the Godhead.",
    "refs": [
      "Exodus 3:7–10",
      "Deuteronomy 4:7"
    ]
  },
  "Exodus 3:1": {
    "title": "Moses shepherds in Midian",
    "text": "Moses keeps the flock of Jethro, his father-in-law, and leads it to Horeb, called the mountain of God. The former prince is now a shepherd, and the wilderness becomes the setting for God’s call. Scripture does not say that the location itself makes Moses holy; the significance comes from God’s presence and word.",
    "refs": [
      "Exodus 2:15–21",
      "Exodus 3:5"
    ]
  },
  "Exodus 3:2": {
    "title": "The angel of the LORD appears",
    "text": "The angel of the LORD appears to Moses in a flame within a bush that burns without being consumed. In Scripture, an angel is a messenger; the passage soon says the LORD Himself calls from the bush. Oneness readers often understand this as God making His presence known through His messenger, but the wording should be read in the flow of the passage rather than assuming every mention of an angel has the same precise meaning.",
    "refs": [
      "Exodus 3:4",
      "Genesis 16:7–13"
    ]
  },
  "Exodus 3:3": {
    "title": "Moses turns aside to look",
    "text": "Moses decides to investigate why the bush is not consumed. The narrative shows him paying attention before he hears the call. The miracle draws him toward the place where God will speak.",
    "refs": [
      "Exodus 3:2–4"
    ]
  },
  "Exodus 3:4": {
    "title": "God calls Moses by name",
    "text": "The LORD sees Moses turn aside and calls, “Moses, Moses.” Moses answers, “Here am I.” God’s call is personal and purposeful; He knows whom He addresses and summons Moses to hear His command.",
    "refs": [
      "Genesis 22:11",
      "1 Samuel 3:10",
      "Acts 7:30–34"
    ]
  },
  "Exodus 3:5": {
    "title": "Holy ground",
    "text": "Moses must not come closer casually; he is told to remove his shoes because the place is holy. The ground is holy because of God’s presence, not because it has independent power. The instruction teaches reverence before the holy God.",
    "refs": [
      "Joshua 5:15",
      "Psalm 99:5"
    ]
  },
  "Exodus 3:6": {
    "title": "The God of the fathers",
    "text": "God identifies Himself as the God of Abraham, Isaac, and Jacob. Moses hides his face because he is afraid to look upon God. The declaration connects this encounter to the covenant promises in Genesis and identifies the speaker as the same God who dealt with the patriarchs.",
    "refs": [
      "Genesis 17:7",
      "Genesis 28:13",
      "Matthew 22:31–32"
    ]
  },
  "Exodus 3:7": {
    "title": "God sees Israel’s affliction",
    "text": "The LORD says He has surely seen the affliction of His people and heard their cry. God’s awareness is not distant observation; the next verses reveal His intention to act. The text presents Israel as belonging to Him even while they are enslaved in Egypt.",
    "refs": [
      "Exodus 2:23–25",
      "Psalm 34:17"
    ]
  },
  "Exodus 3:8": {
    "title": "God comes down to deliver",
    "text": "God says He has come down to deliver Israel from Egypt and bring them into a good and spacious land. “Come down” describes God’s intervention in human history; it does not require the idea that the Spirit of God had been confined to one place. The promise of land continues the covenant made with Abraham.",
    "refs": [
      "Genesis 15:18–21",
      "Exodus 6:6–8"
    ]
  },
  "Exodus 3:9": {
    "title": "Israel’s cry reaches God",
    "text": "God repeats that Israel’s cry has come to Him and that He has seen the oppression. The repetition stresses that deliverance is not an impulsive human project: God knows the injustice and is now revealing His plan.",
    "refs": [
      "Exodus 2:23–25"
    ]
  },
  "Exodus 3:10": {
    "title": "Moses is sent to Pharaoh",
    "text": "God sends Moses to Pharaoh to bring Israel out of Egypt. The One who promises deliverance chooses a human servant to carry His message and lead the people. Being sent by God does not make Moses equal to God; he is the commissioned servant.",
    "refs": [
      "Exodus 4:10–12",
      "Acts 7:34"
    ]
  },
  "Exodus 3:11": {
    "title": "Moses asks, Who am I?",
    "text": "Moses questions his own suitability for confronting Pharaoh. God’s answer does not praise Moses’ independent ability; it points to God’s presence with him. The mission rests on God’s faithfulness rather than Moses’ status.",
    "refs": [
      "Exodus 3:12",
      "Judges 6:15–16"
    ]
  },
  "Exodus 3:12": {
    "title": "God promises to be with Moses",
    "text": "God answers, “Certainly I will be with thee,” and gives a sign connected with Israel worshipping at this mountain after deliverance. The sign will be recognized in its fulfillment. God’s presence, not Moses’ confidence, is the foundation of the commission.",
    "refs": [
      "Exodus 19:1–6",
      "Matthew 28:20"
    ]
  },
  "Exodus 3:13": {
    "title": "Moses asks God’s name",
    "text": "Moses asks what he should say if Israel asks the name of the God who sent him. In the ancient biblical setting, a name can identify the one speaking and the character or authority associated with that name. Moses needs a clear answer to present God’s commission faithfully.",
    "refs": [
      "Exodus 6:2–3"
    ]
  },
  "Exodus 3:14": {
    "title": "I AM THAT I AM",
    "text": "God answers, “I AM THAT I AM,” and tells Moses to say, “I AM hath sent me unto you.” The Hebrew expression is commonly understood as emphasizing God’s being or self-existence, and it is closely related to the divine name YHWH revealed in the next verse. In Oneness teaching, this passage identifies the one who sends Moses as the self-existent God of Israel; it does not describe a second God.",
    "refs": [
      "Exodus 3:15",
      "Isaiah 43:10–11",
      "John 8:58"
    ]
  },
  "Exodus 3:15": {
    "title": "The name of the LORD",
    "text": "God tells Moses to say that the LORD, the God of Abraham, Isaac, and Jacob, has sent him, and calls this His name for ever. The KJV prints LORD where the Hebrew text has the divine name YHWH. God ties the name to His covenant faithfulness across generations.",
    "refs": [
      "Genesis 12:1–3",
      "Psalm 135:13",
      "Isaiah 42:8"
    ]
  },
  "Exodus 3:16": {
    "title": "Gather Israel’s elders",
    "text": "Moses is instructed to gather Israel’s elders and tell them that the LORD has appeared to him and has seen what is done to them in Egypt. The elders are witnesses and representatives of the people; the message assures Israel that God has not ignored their suffering.",
    "refs": [
      "Exodus 4:29–31"
    ]
  },
  "Exodus 3:17": {
    "title": "The promise of a good land",
    "text": "God promises to bring Israel out of Egypt into a land described as flowing with milk and honey. This is a picture of fruitfulness and provision, and it confirms the earlier covenant promise rather than replacing it.",
    "refs": [
      "Genesis 15:18–21",
      "Deuteronomy 8:7–10"
    ]
  },
  "Exodus 3:18": {
    "title": "Israel and Pharaoh are addressed",
    "text": "The elders are to approach Pharaoh and ask permission for a journey into the wilderness to sacrifice to the LORD. This is the initial request God directs them to make; the larger narrative shows Pharaoh’s repeated refusal and the conflict that follows.",
    "refs": [
      "Exodus 5:1–3"
    ]
  },
  "Exodus 3:19": {
    "title": "Pharaoh will not let Israel go easily",
    "text": "God tells Moses beforehand that Egypt’s king will not release Israel except under compulsion. The warning prepares Moses for resistance and shows that Pharaoh’s refusal will not surprise God.",
    "refs": [
      "Exodus 5:2",
      "Exodus 7:3–5"
    ]
  },
  "Exodus 3:20": {
    "title": "God will act with wonders",
    "text": "God promises to stretch out His hand and strike Egypt with wonders, after which Pharaoh will let Israel go. The “hand” is a biblical expression for power and action; it is not a statement that God is limited to a human body.",
    "refs": [
      "Exodus 7:3–5",
      "Deuteronomy 4:34"
    ]
  },
  "Exodus 3:21": {
    "title": "Israel will find favor",
    "text": "God says He will give Israel favor in the Egyptians’ sight so that they will not leave empty-handed. The promised departure includes provision after years of exploitation; the text presents this as God’s action, not as Israel stealing by private initiative.",
    "refs": [
      "Exodus 11:2–3",
      "Exodus 12:35–36"
    ]
  },
  "Exodus 3:22": {
    "title": "Jewelry and clothing from Egypt",
    "text": "Israelite women are to ask Egyptian neighbors for silver, gold, and clothing for their sons and daughters. The following chapter reports that the Egyptians grant the request. This provision marks a reversal of Israel’s impoverished bondage and prepares for the journey out of Egypt.",
    "refs": [
      "Exodus 11:2–3",
      "Exodus 12:35–36"
    ]
  },
  "Exodus 4:1": {
    "title": "Moses fears they will not believe",
    "text": "Moses worries that Israel will not believe or listen to him. God has given him a message, but Moses still fears rejection. The signs that follow are given to authenticate the commission, not to make Moses the source of divine power.",
    "refs": [
      "Exodus 3:13–18"
    ]
  },
  "Exodus 4:2": {
    "title": "The rod in Moses’ hand",
    "text": "God asks Moses what he has in his hand, and Moses answers that it is a rod. The ordinary object will become a sign through God’s command; its power does not come from the wood itself.",
    "refs": [
      "Exodus 4:17",
      "Exodus 4:20"
    ]
  },
  "Exodus 4:3": {
    "title": "The rod becomes a serpent",
    "text": "Moses casts down the rod and it becomes a serpent, causing him to flee. This sign demonstrates God’s power and confronts Moses with the reality of the commission he has received.",
    "refs": [
      "Exodus 7:8–12"
    ]
  },
  "Exodus 4:4": {
    "title": "Moses takes the serpent by the tail",
    "text": "God tells Moses to take the serpent by the tail, and it becomes a rod again. Moses obeys despite the danger. The sign is under God’s direction and confirms that Moses is not acting by his own magical ability.",
    "refs": [
      "Exodus 4:2–5"
    ]
  },
  "Exodus 4:5": {
    "title": "The God of the fathers has appeared",
    "text": "God states that the sign is given so Israel may believe that the LORD, the God of their fathers, has appeared to Moses. The sign supports the message that the covenant God is acting now, in their generation.",
    "refs": [
      "Exodus 3:6",
      "Exodus 4:30–31"
    ]
  },
  "Exodus 4:6": {
    "title": "Moses’ hand becomes leprous",
    "text": "God tells Moses to put his hand into his bosom; when he withdraws it, it is diseased and white as snow. The sign shows that God has authority over the human body and can bring about what He commands.",
    "refs": [
      "Numbers 12:10–13",
      "2 Kings 5:14"
    ]
  },
  "Exodus 4:7": {
    "title": "The hand is restored",
    "text": "Moses puts his hand back and it is restored. The paired sign demonstrates not only power to afflict but also power to heal and restore.",
    "refs": [
      "Exodus 4:6–8"
    ]
  },
  "Exodus 4:8": {
    "title": "A second sign if needed",
    "text": "God says that if the people do not believe the first sign, they may believe the second. The signs are intended to support the testimony that God has sent Moses, not to replace the spoken message.",
    "refs": [
      "Exodus 4:30–31"
    ]
  },
  "Exodus 4:9": {
    "title": "Water from the river becomes blood",
    "text": "If the people still do not believe, Moses is to pour river water on dry land, where it will become blood. The sign anticipates the first plague and demonstrates God’s authority over Egypt’s river and life systems.",
    "refs": [
      "Exodus 7:14–21"
    ]
  },
  "Exodus 4:10": {
    "title": "Moses says he is slow of speech",
    "text": "Moses says he is not eloquent and describes himself as slow of speech and tongue. Scripture records his reluctance candidly. God’s calling does not depend on a servant possessing every natural strength.",
    "refs": [
      "Jeremiah 1:6–9",
      "2 Corinthians 12:9"
    ]
  },
  "Exodus 4:11": {
    "title": "God made the mouth",
    "text": "The LORD asks who made the human mouth and who makes a person able or unable to speak, hear, see, or be blind. The point is God’s sovereignty as Creator and His ability to equip His servant; the verse should not be used carelessly to blame people for disability.",
    "refs": [
      "Psalm 94:9",
      "John 9:1–3"
    ]
  },
  "Exodus 4:12": {
    "title": "God promises to teach Moses",
    "text": "God tells Moses to go and promises to be with his mouth and teach him what to say. The answer addresses Moses’ concern directly: God will guide the message and the speaking of His appointed servant.",
    "refs": [
      "Matthew 10:19–20",
      "Luke 12:11–12"
    ]
  },
  "Exodus 4:13": {
    "title": "Moses asks God to send someone else",
    "text": "Moses still asks God to send another person. His hesitation has become resistance to the commission. The narrative does not hide the weakness of a chosen servant, and the next verse shows God’s anger while still providing help.",
    "refs": [
      "Exodus 4:14–16"
    ]
  },
  "Exodus 4:14": {
    "title": "Aaron will meet Moses",
    "text": "The LORD’s anger is kindled, yet He tells Moses that Aaron the Levite can speak well and is already coming to meet him. God accommodates Moses’ weakness without withdrawing the calling; Aaron will assist, but Moses remains responsible for carrying out God’s instructions.",
    "refs": [
      "Exodus 4:15–16",
      "Exodus 7:1–2"
    ]
  },
  "Exodus 4:15": {
    "title": "God will teach both brothers",
    "text": "Moses is to speak to Aaron and put the words in his mouth; God promises to be with both their mouths and teach them what to do. The arrangement is a shared human ministry under God’s direction, not two competing sources of revelation.",
    "refs": [
      "Exodus 4:12",
      "Exodus 4:16"
    ]
  },
  "Exodus 4:16": {
    "title": "Moses as God to Aaron",
    "text": "Aaron will speak to the people for Moses, and Moses will be to Aaron “instead of God.” This is a role of delegated authority: Moses receives God’s message and Aaron communicates it. The wording does not make Moses divine by nature; it compares their roles in delivering the message.",
    "refs": [
      "Exodus 7:1–2"
    ]
  },
  "Exodus 4:17": {
    "title": "The rod of signs",
    "text": "God tells Moses to take the rod with which he will perform signs. The rod is an instrument in God’s hand; the source of the signs is the LORD who commissioned Moses.",
    "refs": [
      "Exodus 4:2–5",
      "Exodus 7:9"
    ]
  },
  "Exodus 4:18": {
    "title": "Moses asks to return to Egypt",
    "text": "Moses asks Jethro for permission to return to his brethren and see whether they are still alive. He does not yet tell Jethro every detail of the divine commission, but he begins the journey back toward Egypt.",
    "refs": [
      "Exodus 2:23",
      "Exodus 3:10"
    ]
  },
  "Exodus 4:19": {
    "title": "The men seeking Moses are dead",
    "text": "The LORD tells Moses in Midian that the men who sought his life are dead. This removes the specific danger that caused Moses to flee and confirms that the time has come to return.",
    "refs": [
      "Exodus 2:15",
      "Matthew 2:19–20"
    ]
  },
  "Exodus 4:20": {
    "title": "Moses returns with his family",
    "text": "Moses takes his wife and sons, sets them on a donkey, and returns to Egypt with the rod of God in his hand. The ordinary rod is now called the rod of God because it is associated with the commission and signs God has given.",
    "refs": [
      "Exodus 4:17",
      "Exodus 18:2–4"
    ]
  },
  "Exodus 4:21": {
    "title": "Pharaoh’s heart will be hardened",
    "text": "God tells Moses that He will do wonders, but Pharaoh’s heart will be hardened and he will not let the people go. Exodus describes both Pharaoh’s own stubbornness and God’s judicial hardening in the unfolding story; these statements should be read together rather than reducing the account to only one side.",
    "refs": [
      "Exodus 7:3–5",
      "Exodus 8:15",
      "Exodus 9:34–35"
    ]
  },
  "Exodus 4:22": {
    "title": "Israel is God’s firstborn son",
    "text": "Moses is to tell Pharaoh that the LORD calls Israel His son, even His firstborn. This is covenant language for Israel’s special relationship and status among the nations; it is not a claim that Israel is God by nature.",
    "refs": [
      "Hosea 11:1",
      "Jeremiah 31:9"
    ]
  },
  "Exodus 4:23": {
    "title": "Let My son go",
    "text": "God commands Pharaoh to release Israel so they may serve Him, and warns that Pharaoh’s refusal will bring the death of his own firstborn. The conflict is about worship and God’s claim upon His people, and it foreshadows the final plague.",
    "refs": [
      "Exodus 12:29–32"
    ]
  },
  "Exodus 4:24": {
    "title": "A difficult encounter on the journey",
    "text": "At a lodging place, the LORD meets Moses and seeks to kill him. The passage is terse and difficult; the next verses connect the danger to circumcision. The text should not be made more certain than it is about every detail of the encounter.",
    "refs": [
      "Exodus 4:25–26",
      "Genesis 17:10–14"
    ]
  },
  "Exodus 4:25": {
    "title": "Zipporah circumcises her son",
    "text": "Zipporah takes a sharp stone and circumcises her son, touching Moses’ feet with the foreskin and calling him a bloody husband. The action responds to the covenant issue raised in the preceding verses. The details and the phrase “bloody husband” have been interpreted in different ways, so a careful study should acknowledge the passage’s difficulty.",
    "refs": [
      "Genesis 17:10–14",
      "Joshua 5:2–9"
    ]
  },
  "Exodus 4:26": {
    "title": "The danger passes",
    "text": "The LORD lets Moses alone after the circumcision, and Zipporah refers to the circumcision. The passage stresses the seriousness of the covenant sign, even for the family of the man called to lead Israel.",
    "refs": [
      "Genesis 17:14"
    ]
  },
  "Exodus 4:27": {
    "title": "Aaron meets Moses at the mountain",
    "text": "The LORD tells Aaron to go into the wilderness to meet Moses. Aaron obeys, meets him at the mountain of God, and kisses him. Their reunion brings the two brothers together for the work God has assigned.",
    "refs": [
      "Exodus 3:1",
      "Exodus 4:14–16"
    ]
  },
  "Exodus 4:28": {
    "title": "Moses tells Aaron God’s words",
    "text": "Moses reports to Aaron all the words the LORD sent him to speak and the signs he commanded him to perform. The mission is grounded in God’s message, not in a plan the brothers invented themselves.",
    "refs": [
      "Exodus 3:10–18",
      "Exodus 4:1–9"
    ]
  },
  "Exodus 4:29": {
    "title": "The elders are gathered",
    "text": "Moses and Aaron go to Egypt and gather the elders of Israel. The promised public presentation of God’s message now begins.",
    "refs": [
      "Exodus 3:16"
    ]
  },
  "Exodus 4:30": {
    "title": "Aaron speaks and signs are performed",
    "text": "Aaron tells the elders the words the LORD spoke to Moses, and Moses performs the signs before the people. The message and signs work together to confirm that Moses has been commissioned by Israel’s God.",
    "refs": [
      "Exodus 4:1–9"
    ]
  },
  "Exodus 4:31": {
    "title": "Israel believes and worships",
    "text": "The people believe when they hear that the LORD has visited them and seen their affliction, and they bow their heads and worship. Their response follows the news that God knows their suffering and is beginning to act; it is the first public reception of Moses’ mission.",
    "refs": [
      "Exodus 2:24–25",
      "Exodus 3:7–10"
    ]
  },
  "Exodus 5:1": {
    "title": "Let My people go",
    "text": "Moses and Aaron deliver God’s demand that Pharaoh release Israel for a feast in the wilderness. The command establishes that Israel belongs to the LORD and is to worship Him, not remain Pharaoh’s property.",
    "refs": [
      "Exodus 3:18",
      "Exodus 4:22–23"
    ]
  },
  "Exodus 5:2": {
    "title": "Who is the LORD?",
    "text": "Pharaoh rejects the LORD’s authority and says he will not let Israel go. His question is defiance, not a neutral request for information. The conflict will reveal who truly rules: Pharaoh or the God of Israel.",
    "refs": [
      "Exodus 3:14–15",
      "Exodus 7:5"
    ]
  },
  "Exodus 5:3": {
    "title": "A request to sacrifice",
    "text": "Moses and Aaron explain that the God of the Hebrews has met with them and ask for a three-day journey to sacrifice, warning of judgment if they refuse. Pharaoh has not yet accepted God’s authority, and the request becomes the opening of a larger confrontation.",
    "refs": [
      "Exodus 3:18",
      "Exodus 10:25–26"
    ]
  },
  "Exodus 5:4": {
    "title": "Pharaoh sends them back to work",
    "text": "Pharaoh asks why Moses and Aaron distract the people from their burdens and orders them back to their tasks. He treats worship as an obstacle to production and refuses to recognize Israel’s claim to serve God.",
    "refs": [
      "Exodus 1:11–14"
    ]
  },
  "Exodus 5:5": {
    "title": "The people are numerous",
    "text": "Pharaoh points to the large population of Israel and accuses Moses and Aaron of making the people rest from their burdens. His words reveal that he values forced labor over their freedom.",
    "refs": [
      "Exodus 1:7–12"
    ]
  },
  "Exodus 5:6": {
    "title": "Taskmasters receive new orders",
    "text": "Pharaoh orders the taskmasters and officers to change how Israel’s work is managed. The oppression becomes more severe immediately after Moses’ first demand.",
    "refs": [
      "Exodus 1:11",
      "Exodus 5:9"
    ]
  },
  "Exodus 5:7": {
    "title": "No straw supplied",
    "text": "Israel is told to gather straw for brickmaking rather than receiving it from the Egyptians. The same required output remains, while the laborers must now perform additional work to obtain materials.",
    "refs": [
      "Exodus 5:8–9"
    ]
  },
  "Exodus 5:8": {
    "title": "The same quota demanded",
    "text": "Pharaoh requires the same number of bricks and calls the people idle. The accusation is unjust because the labor requirement is unchanged while the means of meeting it are made harder.",
    "refs": [
      "Exodus 5:17–18"
    ]
  },
  "Exodus 5:9": {
    "title": "Oppression meant to silence hope",
    "text": "Pharaoh commands that heavier labor keep the people occupied so they will not heed what he calls vain words. The ruler tries to crush hope by exhausting the people, but the narrative will show that his plan cannot stop God’s deliverance.",
    "refs": [
      "Exodus 5:1–2",
      "Exodus 6:6–8"
    ]
  },
  "Exodus 5:10": {
    "title": "The taskmasters announce the order",
    "text": "The taskmasters and officers tell the people that Pharaoh will no longer provide straw. The king’s policy is passed down through the machinery of administration, spreading responsibility for oppression through the system.",
    "refs": [
      "Exodus 5:6–7"
    ]
  },
  "Exodus 5:11": {
    "title": "Israel must find its own straw",
    "text": "The laborers are told to gather straw wherever they can find it, but their quota will not be reduced. The demand makes the injustice measurable and unavoidable.",
    "refs": [
      "Exodus 5:8",
      "Exodus 5:13"
    ]
  },
  "Exodus 5:12": {
    "title": "Scattered through Egypt",
    "text": "The people spread throughout Egypt to gather stubble for straw. Their work becomes more difficult because they must search for materials in addition to making bricks.",
    "refs": [
      "Exodus 5:7–8"
    ]
  },
  "Exodus 5:13": {
    "title": "The daily quota remains",
    "text": "The taskmasters insist that the daily work be completed as when straw was supplied. The officers enforce Pharaoh’s unreasonable policy without relief for the people.",
    "refs": [
      "Exodus 5:14"
    ]
  },
  "Exodus 5:14": {
    "title": "Israelite officers are beaten",
    "text": "The Israelite officers are beaten because the brick quota is not met. They suffer punishment for a demand they cannot fairly fulfill, showing how Pharaoh’s policy turns administrative failure into violence.",
    "refs": [
      "Exodus 5:15–16"
    ]
  },
  "Exodus 5:15": {
    "title": "The officers appeal to Pharaoh",
    "text": "The Israelite officers cry out to Pharaoh and ask why he treats his servants this way. They appeal to the king who controls the system, but he will not grant justice.",
    "refs": [
      "Exodus 5:16–18"
    ]
  },
  "Exodus 5:16": {
    "title": "The officers explain the injustice",
    "text": "They say no straw is supplied, yet they are ordered to make bricks and are beaten. Their statement exposes the contradiction at the heart of Pharaoh’s demand.",
    "refs": [
      "Exodus 5:7–8"
    ]
  },
  "Exodus 5:17": {
    "title": "Pharaoh calls them idle",
    "text": "Pharaoh repeats the accusation of idleness and refuses to recognize the people’s real suffering. He interprets their desire to worship as evidence of laziness rather than honoring their request.",
    "refs": [
      "Exodus 5:1–2",
      "Exodus 5:9"
    ]
  },
  "Exodus 5:18": {
    "title": "The work remains unchanged",
    "text": "Pharaoh orders the people back to work and refuses to provide straw while maintaining the brick quota. His response confirms that the appeal for fair treatment has failed.",
    "refs": [
      "Exodus 5:7–8"
    ]
  },
  "Exodus 5:19": {
    "title": "The officers see their trouble",
    "text": "The Israelite officers realize they are in serious trouble when told their daily quota will not be reduced. Their distress reflects the consequences of Moses’ initial appeal, and it sets up their confrontation with him and Aaron.",
    "refs": [
      "Exodus 5:20–21"
    ]
  },
  "Exodus 5:20": {
    "title": "They meet Moses and Aaron",
    "text": "The officers encounter Moses and Aaron as they leave Pharaoh. The meeting turns the people’s frustration toward the leaders who had brought the message of deliverance.",
    "refs": [
      "Exodus 5:1–3"
    ]
  },
  "Exodus 5:21": {
    "title": "The officers blame the leaders",
    "text": "They accuse Moses and Aaron of making Israel offensive to Pharaoh and putting a sword in the Egyptians’ hands. Their words show how worsening conditions can make a promise of rescue seem dangerous before the rescue arrives.",
    "refs": [
      "Exodus 6:9"
    ]
  },
  "Exodus 5:22": {
    "title": "Moses returns to the LORD",
    "text": "Moses asks the LORD why He has brought trouble upon the people and why He sent him. He speaks honestly from the pain of the failed first attempt; the text records his lament rather than condemning him for bringing the problem to God.",
    "refs": [
      "Exodus 3:10",
      "Psalm 13:1–2"
    ]
  },
  "Exodus 5:23": {
    "title": "Moses asks why deliverance has not begun",
    "text": "Moses says that since he spoke to Pharaoh, Pharaoh has treated the people worse and God has not delivered them. The chapter ends with an unresolved question, preparing for God’s renewed promise in chapter 6.",
    "refs": [
      "Exodus 6:1–8"
    ]
  },
  "Exodus 6:1": {
    "title": "God promises a mighty release",
    "text": "The LORD answers that Pharaoh will let Israel go because of God’s strong hand and will even drive them out. The setback does not cancel the promise; it sets the stage for God to reveal His power more fully.",
    "refs": [
      "Exodus 3:19–20",
      "Exodus 12:31–33"
    ]
  },
  "Exodus 6:2": {
    "title": "I am the LORD",
    "text": "God speaks to Moses and identifies Himself as the LORD. The repeated divine name anchors the coming assurance in the identity and authority of the covenant God.",
    "refs": [
      "Exodus 3:14–15",
      "Exodus 6:6"
    ]
  },
  "Exodus 6:3": {
    "title": "God Almighty and the name YHWH",
    "text": "God says He appeared to Abraham, Isaac, and Jacob as God Almighty, but by His name YHWH He was not known to them in the same way. The patriarchs did use the name LORD in Genesis, so the statement is often understood as a distinction in the fuller experience or revelation of God’s name and covenant action, not simply that the name’s syllables had never been heard. God is the same covenant God, now about to act in a new way.",
    "refs": [
      "Genesis 17:1",
      "Genesis 28:13",
      "Exodus 3:14–15"
    ]
  },
  "Exodus 6:4": {
    "title": "The covenant land",
    "text": "God recalls establishing His covenant to give the patriarchs the land of Canaan, where they lived as strangers. Israel’s current bondage does not erase the promise tied to that land.",
    "refs": [
      "Genesis 15:18–21",
      "Genesis 17:8"
    ]
  },
  "Exodus 6:5": {
    "title": "God hears Israel’s groaning",
    "text": "God says He has heard the groaning of Israel and remembered His covenant. As in Exodus 2:24, remembering means acting faithfully on the covenant, not recovering forgotten information.",
    "refs": [
      "Exodus 2:24–25",
      "Psalm 105:8"
    ]
  },
  "Exodus 6:6": {
    "title": "Seven promises of deliverance begin",
    "text": "God promises to bring Israel out from under Egypt’s burdens, deliver them from bondage, redeem them with an outstretched arm and great judgments. The language of redemption becomes central to Israel’s identity and later biblical teaching about salvation.",
    "refs": [
      "Deuteronomy 7:8",
      "Isaiah 63:9",
      "Luke 1:68"
    ]
  },
  "Exodus 6:7": {
    "title": "Israel will know the LORD",
    "text": "God promises to take Israel as His people and be their God, so they will know that He is the LORD who brought them out of Egypt. Knowledge here includes recognizing God through His saving acts and covenant relationship, not merely knowing a title.",
    "refs": [
      "Exodus 7:5",
      "Exodus 14:30–31"
    ]
  },
  "Exodus 6:8": {
    "title": "The land promised to the fathers",
    "text": "God promises to bring Israel into the land He swore to give Abraham, Isaac, and Jacob. He declares, “I am the LORD,” grounding the future fulfillment in His own faithfulness.",
    "refs": [
      "Genesis 15:18",
      "Genesis 26:3",
      "Genesis 28:13"
    ]
  },
  "Exodus 6:9": {
    "title": "The people cannot hear Moses",
    "text": "Moses tells Israel God’s promise, but they do not listen because of anguish of spirit and cruel bondage. Their inability to receive the message is portrayed with compassion for their suffering, not as proof that God’s promise has failed.",
    "refs": [
      "Exodus 5:21–23"
    ]
  },
  "Exodus 6:10": {
    "title": "God speaks again to Moses",
    "text": "The LORD commands Moses to go back to Pharaoh. The command continues despite Israel’s discouragement and Pharaoh’s resistance.",
    "refs": [
      "Exodus 3:10",
      "Exodus 6:1"
    ]
  },
  "Exodus 6:11": {
    "title": "Demand Israel’s release again",
    "text": "Moses is ordered to tell Pharaoh to send Israel out of his land. God does not revise the goal because Pharaoh has refused the first request.",
    "refs": [
      "Exodus 5:1",
      "Exodus 7:2"
    ]
  },
  "Exodus 6:12": {
    "title": "Moses questions his ability to speak",
    "text": "Moses points out that Israel has not listened to him and asks how Pharaoh will listen, since he is of uncircumcised lips. His concern repeats the issue of speech, but God’s commission remains in force.",
    "refs": [
      "Exodus 4:10–12"
    ]
  },
  "Exodus 6:13": {
    "title": "God commissions Moses and Aaron",
    "text": "The LORD gives Moses and Aaron a charge concerning Israel and Pharaoh. The narrative underscores that their mission is authorized by God, not by their own ambitions.",
    "refs": [
      "Exodus 3:10",
      "Exodus 4:14–16"
    ]
  },
  "Exodus 6:14": {
    "title": "Reuben’s family line",
    "text": "The genealogy begins with Reuben, Israel’s firstborn, and names his sons. The list situates Moses and Aaron within Israel’s actual family history rather than presenting them as detached legendary figures.",
    "refs": [
      "Genesis 46:9"
    ]
  },
  "Exodus 6:15": {
    "title": "Simeon’s family line",
    "text": "The sons of Simeon are named, continuing the record of Israel’s tribes. The genealogy provides the family framework for the account that follows.",
    "refs": [
      "Genesis 46:10"
    ]
  },
  "Exodus 6:16": {
    "title": "Levi’s sons and generations",
    "text": "The passage lists Levi’s sons and gives his lifespan. The genealogy now moves toward the tribe and family from which Moses and Aaron descend.",
    "refs": [
      "Genesis 29:34",
      "Numbers 3:17"
    ]
  },
  "Exodus 6:17": {
    "title": "The sons of Gershon",
    "text": "The sons of Gershon and their families are named. The details establish the Levitical family lines that will have duties in Israel’s worship and tabernacle service.",
    "refs": [
      "Numbers 3:18–26"
    ]
  },
  "Exodus 6:18": {
    "title": "The sons of Kohath",
    "text": "Kohath’s descendants are named, including Amram’s family line. This branch of Levi’s family will include Moses and Aaron.",
    "refs": [
      "Numbers 3:27–32"
    ]
  },
  "Exodus 6:19": {
    "title": "The sons of Merari",
    "text": "Merari’s sons are listed, completing the three main branches of Levi’s descendants. The genealogy prepares for later descriptions of the Levites’ service.",
    "refs": [
      "Numbers 3:33–37"
    ]
  },
  "Exodus 6:20": {
    "title": "Amram, Jochebed, Moses, and Aaron",
    "text": "Amram marries Jochebed, his father’s sister according to the KJV wording, and she bears Aaron and Moses. Later Israelite law prohibits certain close-kin unions, but the narrative is reporting an earlier generation rather than issuing a command for such marriages.",
    "refs": [
      "Exodus 2:1–2",
      "Numbers 26:59",
      "Leviticus 18:12"
    ]
  },
  "Exodus 6:21": {
    "title": "Korah’s family line",
    "text": "The sons of Izhar, including Korah, are named. Korah’s later rebellion will be described in Numbers, so this genealogy also establishes relationships important to the wilderness story.",
    "refs": [
      "Numbers 16:1–3"
    ]
  },
  "Exodus 6:22": {
    "title": "Uzziel’s family line",
    "text": "The sons of Uzziel are listed as part of Levi’s wider family. The genealogy records the people and relationships that frame Israel’s later priestly and Levitical service.",
    "refs": [
      "Leviticus 10:4"
    ]
  },
  "Exodus 6:23": {
    "title": "Aaron’s family",
    "text": "Aaron marries Elisheba, and the verse names their sons, including Eleazar and Ithamar. Eleazar will become high priest after Aaron, linking the genealogy to the future priesthood.",
    "refs": [
      "Numbers 20:25–28",
      "Numbers 26:60"
    ]
  },
  "Exodus 6:24": {
    "title": "Korah’s sons and descendants",
    "text": "The sons of Korah are listed. Later biblical books refer to descendants of Korah in connection with temple service and psalms, even though Korah himself rebelled.",
    "refs": [
      "Numbers 16:1–3",
      "1 Chronicles 6:31–38"
    ]
  },
  "Exodus 6:25": {
    "title": "Eleazar’s family and Phinehas",
    "text": "Eleazar’s marriage and son Phinehas are noted. Phinehas becomes significant in Numbers, and the verse completes the genealogy’s focus on Aaron’s priestly descendants.",
    "refs": [
      "Numbers 25:7–13"
    ]
  },
  "Exodus 6:26": {
    "title": "The same Moses and Aaron",
    "text": "The text identifies the Moses and Aaron named in this genealogy as the ones to whom the LORD said to bring Israel out of Egypt by their hosts. The family record is tied directly to the mission already narrated.",
    "refs": [
      "Exodus 3:10",
      "Exodus 6:13"
    ]
  },
  "Exodus 6:27": {
    "title": "Moses and Aaron before Pharaoh",
    "text": "The verse again identifies Moses and Aaron as the men who spoke to Pharaoh about bringing Israel out. The repetition reinforces the continuity between the genealogy and the historical narrative.",
    "refs": [
      "Exodus 5:1",
      "Exodus 7:1–2"
    ]
  },
  "Exodus 6:28": {
    "title": "The LORD speaks in Egypt",
    "text": "The narrative returns to the moment when the LORD spoke to Moses in Egypt. The genealogy has interrupted the action to establish the family credentials of the leaders.",
    "refs": [
      "Exodus 6:10–13"
    ]
  },
  "Exodus 6:29": {
    "title": "God’s command to Moses",
    "text": "The LORD tells Moses that He is the LORD and commands him to speak to Pharaoh all that He says. God’s identity and authority remain the basis for Moses’ assignment.",
    "refs": [
      "Exodus 3:14–15",
      "Exodus 6:2"
    ]
  },
  "Exodus 6:30": {
    "title": "Moses repeats his concern",
    "text": "Moses again says he is of uncircumcised lips and questions why Pharaoh should listen. The next chapter answers by explaining the roles God assigns to Moses and Aaron and by continuing the signs before Pharaoh.",
    "refs": [
      "Exodus 4:10–16",
      "Exodus 7:1–2"
    ]
  },
  "Exodus 7:1": {
    "title": "Moses as God to Pharaoh",
    "text": "God tells Moses that He has made him “a god to Pharaoh,” while Aaron will be his prophet. This is language of delegated authority: Moses represents God’s message before Pharaoh, and Aaron speaks for Moses. It does not teach that Moses is the one true God by nature.",
    "refs": [
      "Exodus 4:16",
      "Exodus 7:2"
    ]
  },
  "Exodus 7:2": {
    "title": "Speak all God commands",
    "text": "Moses must speak what God commands, and Aaron must communicate the message to Pharaoh. Their roles are distinct, but both act under the authority of the one LORD who sends them.",
    "refs": [
      "Exodus 4:15–16",
      "Deuteronomy 18:18"
    ]
  },
  "Exodus 7:3": {
    "title": "Pharaoh’s heart hardened",
    "text": "God says He will harden Pharaoh’s heart and multiply signs and wonders in Egypt. Later verses also describe Pharaoh hardening his own heart. The account presents God’s judgment and Pharaoh’s culpable resistance together.",
    "refs": [
      "Exodus 4:21",
      "Exodus 8:15",
      "Exodus 9:34–35"
    ]
  },
  "Exodus 7:4": {
    "title": "Judgments against Egypt",
    "text": "Pharaoh will not listen, so God will lay His hand upon Egypt and bring Israel out by great judgments. The plagues are not random disasters in the narrative; they confront Egypt’s power and demonstrate the LORD’s authority.",
    "refs": [
      "Exodus 12:12",
      "Numbers 33:4"
    ]
  },
  "Exodus 7:5": {
    "title": "Egypt will know the LORD",
    "text": "When God stretches out His hand against Egypt and brings Israel out, the Egyptians will know that He is the LORD. The purpose of the signs includes revelation: God makes His identity known through His saving and judging acts.",
    "refs": [
      "Exodus 6:7",
      "Exodus 14:4"
    ]
  },
  "Exodus 7:6": {
    "title": "Moses and Aaron obey",
    "text": "Moses and Aaron do as the LORD commands. Their obedience contrasts with Pharaoh’s resistance and shows the response God expects from those He commissions.",
    "refs": [
      "Exodus 4:28–30"
    ]
  },
  "Exodus 7:7": {
    "title": "Their ages are recorded",
    "text": "Moses is eighty and Aaron eighty-three when they speak to Pharaoh. Their ages underline that God calls them to this task after years of life and preparation, not in their youth.",
    "refs": [
      "Acts 7:23, 30"
    ]
  },
  "Exodus 7:8": {
    "title": "God speaks about a sign",
    "text": "The LORD tells Moses and Aaron what Pharaoh may demand and how they are to respond. The coming sign is performed according to God’s prior instruction.",
    "refs": [
      "Exodus 4:1–9"
    ]
  },
  "Exodus 7:9": {
    "title": "The rod becomes a serpent",
    "text": "Moses is to tell Aaron to cast down the rod before Pharaoh, where it becomes a serpent. The sign repeats the earlier confirmation before the royal court and shows that the confrontation is directed by God.",
    "refs": [
      "Exodus 4:2–5"
    ]
  },
  "Exodus 7:10": {
    "title": "The sign is performed before Pharaoh",
    "text": "Moses and Aaron do as commanded, and Aaron casts down the rod before Pharaoh and his servants; it becomes a serpent. The narrative emphasizes obedience and the public nature of the sign.",
    "refs": [
      "Exodus 7:8–9"
    ]
  },
  "Exodus 7:11": {
    "title": "Egyptian wise men imitate the sign",
    "text": "Pharaoh calls wise men, sorcerers, and magicians, who imitate the sign by their secret arts. The passage does not explain every mechanism behind their acts; it contrasts their imitation with God’s superior power in the next verse.",
    "refs": [
      "2 Timothy 3:8–9"
    ]
  },
  "Exodus 7:12": {
    "title": "Aaron’s rod swallows theirs",
    "text": "The rods of the magicians become serpents, but Aaron’s rod swallows theirs. The sign shows that Egypt’s practitioners cannot rival the authority accompanying God’s commission.",
    "refs": [
      "Exodus 8:18–19",
      "Exodus 9:11"
    ]
  },
  "Exodus 7:13": {
    "title": "Pharaoh’s heart remains hard",
    "text": "Pharaoh does not listen, as the LORD had said. A sign alone does not force him into faithful obedience; his resistance continues and the judgments will escalate.",
    "refs": [
      "Exodus 7:3–5"
    ]
  },
  "Exodus 7:14": {
    "title": "Pharaoh refuses to release Israel",
    "text": "The LORD says Pharaoh’s heart is hardened and he refuses to let the people go. The first plague begins with this refusal as its immediate context.",
    "refs": [
      "Exodus 5:2",
      "Exodus 7:16"
    ]
  },
  "Exodus 7:15": {
    "title": "Moses meets Pharaoh at the river",
    "text": "Moses is told to meet Pharaoh by the water in the morning and bring the rod that became a serpent. The river is central to Egypt’s life and will become the setting for the first plague.",
    "refs": [
      "Exodus 2:3–5"
    ]
  },
  "Exodus 7:16": {
    "title": "The demand to let Israel serve God",
    "text": "Moses is to repeat that the LORD, God of the Hebrews, sent him to demand that Israel be released to serve Him in the wilderness. Pharaoh’s refusal to listen will now be answered by a sign of judgment.",
    "refs": [
      "Exodus 5:1–3"
    ]
  },
  "Exodus 7:17": {
    "title": "The river becomes blood",
    "text": "God says that by striking the river with the rod, its water will become blood, so Pharaoh will know that He is the LORD. The sign directly challenges the river’s role as a source of life and provision in Egypt.",
    "refs": [
      "Exodus 7:5",
      "Psalm 105:29"
    ]
  },
  "Exodus 7:18": {
    "title": "Fish die and the river stinks",
    "text": "The fish will die, the river will smell, and the Egyptians will struggle to drink its water. The judgment affects food, water, and daily life, making Pharaoh’s refusal costly to the whole land.",
    "refs": [
      "Exodus 7:21"
    ]
  },
  "Exodus 7:19": {
    "title": "The waters throughout Egypt struck",
    "text": "Aaron is commanded to stretch his rod over Egypt’s waters, including streams, pools, and vessels of wood and stone, and they will become blood. The breadth of the command underscores the scope of the sign.",
    "refs": [
      "Exodus 7:20–21"
    ]
  },
  "Exodus 7:20": {
    "title": "The river is struck",
    "text": "Moses and Aaron obey, and the water is turned to blood before Pharaoh and his servants. The event is presented as the LORD’s judgment carried out through His commissioned servants.",
    "refs": [
      "Exodus 7:17–19"
    ]
  },
  "Exodus 7:21": {
    "title": "The water is undrinkable",
    "text": "The fish die and the river stinks, and the Egyptians cannot drink its water. The consequences are physical and widespread, not merely a private sign witnessed by the king.",
    "refs": [
      "Psalm 78:44"
    ]
  },
  "Exodus 7:22": {
    "title": "The magicians imitate the sign",
    "text": "Egypt’s magicians do likewise by their secret arts, and Pharaoh’s heart remains hard. Their imitation does not remove the plague or solve the crisis; it becomes another reason Pharaoh refuses to listen.",
    "refs": [
      "Exodus 7:11–13"
    ]
  },
  "Exodus 7:23": {
    "title": "Pharaoh turns away",
    "text": "Pharaoh returns to his house and does not set his heart to the sign. The text portrays deliberate disregard even after a public warning.",
    "refs": [
      "Exodus 7:14"
    ]
  },
  "Exodus 7:24": {
    "title": "Egyptians dig for water",
    "text": "The Egyptians dig around the river for drinking water because they cannot drink the river water. The plague brings practical hardship to ordinary people as well as confronting Pharaoh.",
    "refs": [
      "Exodus 7:18–21"
    ]
  },
  "Exodus 7:25": {
    "title": "Seven days pass",
    "text": "Seven days pass after the LORD strikes the river. The time marker closes the first plague account and prepares for the next judgment.",
    "refs": [
      "Exodus 8:1"
    ]
  },
  "Exodus 8:1": {
    "title": "Let My people go",
    "text": "The LORD again commands Pharaoh to release Israel so they can serve Him. The repeated demand makes clear that the plagues are connected to Pharaoh’s refusal to obey God’s word.",
    "refs": [
      "Exodus 5:1",
      "Exodus 7:16"
    ]
  },
  "Exodus 8:2": {
    "title": "Frogs are threatened",
    "text": "God warns that if Pharaoh refuses, frogs will swarm through the land. The judgment will enter homes and everyday spaces, removing the separation between royal policy and ordinary Egyptian life.",
    "refs": [
      "Psalm 78:45",
      "Psalm 105:30"
    ]
  },
  "Exodus 8:3": {
    "title": "Frogs enter houses and beds",
    "text": "Frogs will come into houses, bedrooms, beds, ovens, and kneading bowls. The detail emphasizes how thoroughly the plague disrupts domestic life.",
    "refs": [
      "Exodus 8:2"
    ]
  },
  "Exodus 8:4": {
    "title": "Frogs cover the people",
    "text": "Frogs will come upon Pharaoh, his people, and his servants. The judgment is not confined to the royal palace; it spreads throughout Egyptian society.",
    "refs": [
      "Exodus 8:2–3"
    ]
  },
  "Exodus 8:5": {
    "title": "Aaron stretches out his hand",
    "text": "The LORD tells Moses to command Aaron to stretch his rod over the waters and bring frogs upon Egypt. As in the first plague, the sign happens through obedient human agents under God’s command.",
    "refs": [
      "Exodus 7:19–20"
    ]
  },
  "Exodus 8:6": {
    "title": "Frogs cover Egypt",
    "text": "Aaron stretches his hand over Egypt’s waters, and frogs come up and cover the land. The narrative attributes the event to the LORD’s command and Aaron’s obedience.",
    "refs": [
      "Exodus 8:5"
    ]
  },
  "Exodus 8:7": {
    "title": "The magicians imitate the frogs",
    "text": "The magicians also bring up frogs by their secret arts. Their imitation adds to the plague rather than relieving it, revealing the limits of their response.",
    "refs": [
      "Exodus 7:11–12"
    ]
  },
  "Exodus 8:8": {
    "title": "Pharaoh asks Moses to pray",
    "text": "Pharaoh calls Moses and Aaron and asks them to entreat the LORD to remove the frogs, promising to let Israel sacrifice. His request recognizes the LORD’s power, though the later narrative shows that his promises are unreliable.",
    "refs": [
      "Exodus 8:15"
    ]
  },
  "Exodus 8:9": {
    "title": "Moses asks Pharaoh to choose the time",
    "text": "Moses tells Pharaoh to set the time when he should pray for the frogs to be removed, so Pharaoh may know there is none like the LORD their God. The timing makes the coming relief a sign of God’s authority, not a coincidence.",
    "refs": [
      "Exodus 8:10"
    ]
  },
  "Exodus 8:10": {
    "title": "There is none like the LORD",
    "text": "Pharaoh says the frogs should be removed tomorrow, and Moses answers that it will be as Pharaoh has said, so he may know there is none like the LORD. The statement affirms the unique supremacy of Israel’s God over all rival powers.",
    "refs": [
      "Deuteronomy 4:35",
      "Isaiah 45:5–6"
    ]
  },
  "Exodus 8:11": {
    "title": "The frogs die, but Pharaoh relents",
    "text": "The frogs will leave the houses and remain in the river, and Moses goes out and cries to the LORD. When the frogs die, Pharaoh’s temporary relief will expose whether his promise was sincere.",
    "refs": [
      "Exodus 8:12–15"
    ]
  },
  "Exodus 8:12": {
    "title": "Moses cries to the LORD",
    "text": "Moses cries to the LORD concerning the frogs, acting as an intercessor in response to Pharaoh’s request. The power to remove the plague belongs to God, not to Moses.",
    "refs": [
      "Exodus 8:8–10"
    ]
  },
  "Exodus 8:13": {
    "title": "The frogs are removed",
    "text": "The LORD does according to Moses’ word, and the frogs die in the houses, villages, and fields. The response demonstrates that Moses’ prayer is answered by God’s action.",
    "refs": [
      "Exodus 8:12"
    ]
  },
  "Exodus 8:14": {
    "title": "The frogs are gathered in heaps",
    "text": "The Egyptians gather the dead frogs into heaps, and the land stinks. The removal itself leaves a reminder of the judgment and its consequences.",
    "refs": [
      "Exodus 8:13"
    ]
  },
  "Exodus 8:15": {
    "title": "Pharaoh hardens his heart",
    "text": "When Pharaoh sees relief, he hardens his heart and refuses to listen, as the LORD had said. His promise to release Israel lasts only while he is under pressure, revealing the difference between seeking relief and submitting to God.",
    "refs": [
      "Exodus 7:13",
      "Exodus 8:8"
    ]
  },
  "Exodus 8:16": {
    "title": "Lice from the dust",
    "text": "The LORD tells Moses to have Aaron strike the dust, which becomes lice throughout Egypt. The plague begins without the extended warning scene of the first two plagues and shows that God’s judgments continue despite Pharaoh’s refusal.",
    "refs": [
      "Psalm 105:31"
    ]
  },
  "Exodus 8:17": {
    "title": "The dust becomes lice",
    "text": "Aaron strikes the dust, and lice come upon people and animals. The sign reaches the bodies of Egyptians and their livestock, expanding the suffering caused by Pharaoh’s resistance.",
    "refs": [
      "Exodus 8:16"
    ]
  },
  "Exodus 8:18": {
    "title": "The magicians cannot imitate it",
    "text": "The magicians try to bring forth lice but cannot. Their failure marks a limit to their imitation of the signs and prepares for their admission in the next verse.",
    "refs": [
      "Exodus 7:11–12"
    ]
  },
  "Exodus 8:19": {
    "title": "The finger of God",
    "text": "The magicians tell Pharaoh, “This is the finger of God,” yet Pharaoh’s heart remains hard. Their words acknowledge a power beyond their own arts, but recognition from the magicians does not produce obedience from the king.",
    "refs": [
      "Luke 11:20"
    ]
  },
  "Exodus 8:20": {
    "title": "Pharaoh is warned by the river",
    "text": "The LORD tells Moses to rise early and meet Pharaoh by the river, repeating the command to release Israel. The recurring morning encounter shows that Pharaoh is repeatedly confronted with God’s demand.",
    "refs": [
      "Exodus 7:15–16"
    ]
  },
  "Exodus 8:21": {
    "title": "Flies will fill Egypt",
    "text": "God warns that swarms of flies will enter Pharaoh’s house and the houses of his servants and fill the land. The plague will again make the consequences of the king’s refusal unavoidable.",
    "refs": [
      "Psalm 78:45"
    ]
  },
  "Exodus 8:22": {
    "title": "Goshen is set apart",
    "text": "God says He will set apart the land of Goshen, where Israel dwells, so swarms will not be there. This distinction shows that the plagues are directed judgments and that God knows how to protect His people.",
    "refs": [
      "Exodus 9:4",
      "Exodus 9:26"
    ]
  },
  "Exodus 8:23": {
    "title": "A distinction between the peoples",
    "text": "God declares that He will put a division between His people and Pharaoh’s people, with the sign occurring the next day. The distinction supports the message that the LORD is active in Egypt and has authority over the plague.",
    "refs": [
      "Exodus 9:4",
      "Exodus 11:7"
    ]
  },
  "Exodus 8:24": {
    "title": "The land is corrupted by flies",
    "text": "The LORD sends a grievous swarm into Pharaoh’s house and throughout Egypt, and the land is corrupted. The plague disrupts daily life and demonstrates that Pharaoh cannot control the consequences of his refusal.",
    "refs": [
      "Psalm 78:45"
    ]
  },
  "Exodus 8:25": {
    "title": "Pharaoh offers sacrifice within Egypt",
    "text": "Pharaoh calls Moses and Aaron and says Israel may sacrifice to God within the land. This is a partial concession, not the freedom God commanded; Pharaoh still tries to control how and where Israel may worship.",
    "refs": [
      "Exodus 3:18",
      "Exodus 8:27"
    ]
  },
  "Exodus 8:26": {
    "title": "Moses refuses the compromise",
    "text": "Moses explains that sacrificing the Egyptians’ sacred concerns in their sight could provoke them to stone Israel. He insists on following God’s instruction rather than accepting Pharaoh’s attempt to redefine the terms of worship.",
    "refs": [
      "Exodus 3:18"
    ]
  },
  "Exodus 8:27": {
    "title": "A three-day journey as commanded",
    "text": "Moses says Israel must journey three days into the wilderness and sacrifice as the LORD commands. God’s word, rather than Pharaoh’s convenience, determines the required act of worship.",
    "refs": [
      "Exodus 5:3"
    ]
  },
  "Exodus 8:28": {
    "title": "Pharaoh permits a limited journey",
    "text": "Pharaoh agrees to let Israel go into the wilderness but says they must not go very far, and he asks Moses to pray for him. His conditions reveal that he still wants to retain control over Israel’s movement.",
    "refs": [
      "Exodus 8:25",
      "Exodus 8:29"
    ]
  },
  "Exodus 8:29": {
    "title": "Moses warns Pharaoh not to deceive",
    "text": "Moses agrees to pray for the flies to leave but warns Pharaoh not to deal deceitfully again by refusing to let the people go. The warning recalls Pharaoh’s earlier broken promise after the frogs were removed.",
    "refs": [
      "Exodus 8:8–15"
    ]
  },
  "Exodus 8:30": {
    "title": "Moses prays to the LORD",
    "text": "Moses leaves Pharaoh and entreats the LORD. Once more, relief comes through God’s action in answer to prayer, not through the king’s power.",
    "refs": [
      "Exodus 8:29"
    ]
  },
  "Exodus 8:31": {
    "title": "The flies are removed",
    "text": "The LORD does according to Moses’ word and removes the swarms, leaving none. The complete removal confirms the authority of the God whose demand Pharaoh has resisted.",
    "refs": [
      "Exodus 8:22–24"
    ]
  },
  "Exodus 8:32": {
    "title": "Pharaoh hardens his heart again",
    "text": "Even after the swarms are removed, Pharaoh hardens his heart and does not let Israel go. The chapter closes by showing that repeated mercy and warning have not yet brought the king to obedience.",
    "refs": [
      "Exodus 8:15",
      "Exodus 9:7"
    ]
  },
  "Exodus 9:1": {
    "title": "Release God’s people",
    "text": "The LORD again commands Pharaoh to let Israel go so they may serve Him. The repeated demand shows that the plagues answer Pharaoh’s continued refusal to acknowledge God’s claim upon Israel.",
    "refs": [
      "Exodus 5:1",
      "Exodus 8:1"
    ]
  },
  "Exodus 9:2": {
    "title": "Refusal brings further judgment",
    "text": "God warns that if Pharaoh continues to hold Israel, the next judgment will follow. Pharaoh is given the demand plainly, and his response remains a matter of responsibility.",
    "refs": [
      "Exodus 7:14"
    ]
  },
  "Exodus 9:3": {
    "title": "A plague upon the livestock",
    "text": "The LORD’s hand will bring a severe pestilence upon Egypt’s horses, cattle, camels, oxen, and sheep. The judgment affects the nation’s economic strength and daily livelihood.",
    "refs": [
      "Exodus 9:6",
      "Psalm 78:50"
    ]
  },
  "Exodus 9:4": {
    "title": "Israel’s livestock distinguished",
    "text": "God promises to distinguish between Israel’s livestock and Egypt’s, so none belonging to Israel will die. The distinction demonstrates the LORD’s rule over the plague and His care for the people He has claimed.",
    "refs": [
      "Exodus 8:22–23"
    ]
  },
  "Exodus 9:5": {
    "title": "The appointed time",
    "text": "The LORD appoints the next day for the plague. The specified timing makes the event a declared judgment rather than an unexplained misfortune.",
    "refs": [
      "Exodus 9:18"
    ]
  },
  "Exodus 9:6": {
    "title": "Egypt’s livestock die",
    "text": "The next day the LORD carries out His word, and Egyptian livestock die while Israel’s livestock remain unharmed. The fulfillment confirms the warning given through Moses.",
    "refs": [
      "Exodus 9:3–5"
    ]
  },
  "Exodus 9:7": {
    "title": "Pharaoh investigates but refuses",
    "text": "Pharaoh sends to learn whether Israel’s livestock have been spared and finds that they have, yet he does not let the people go. Evidence of God’s distinction does not soften his resistance.",
    "refs": [
      "Exodus 8:31–32"
    ]
  },
  "Exodus 9:8": {
    "title": "Ashes before Pharaoh",
    "text": "The LORD tells Moses and Aaron to take handfuls of furnace ashes. Moses is to scatter them before Pharaoh, and the ashes will become a plague of boils.",
    "refs": [
      "Exodus 9:10"
    ]
  },
  "Exodus 9:9": {
    "title": "Boils throughout Egypt",
    "text": "The ashes become fine dust that causes boils and blains on people and animals throughout Egypt. The plague reaches bodies directly and demonstrates that the LORD’s judgments are not limited to crops or water.",
    "refs": [
      "Deuteronomy 28:27"
    ]
  },
  "Exodus 9:10": {
    "title": "The boils appear",
    "text": "Moses and Aaron take ashes and Moses scatters them toward heaven; boils break out on people and animals. The text emphasizes the fulfillment of God’s command through Moses’ action.",
    "refs": [
      "Exodus 9:8–9"
    ]
  },
  "Exodus 9:11": {
    "title": "The magicians cannot stand",
    "text": "The magicians cannot stand before Moses because of the boils, which affect them along with other Egyptians. Their earlier attempts to imitate signs have given way to helplessness before the LORD’s power.",
    "refs": [
      "Exodus 7:11–12",
      "Exodus 8:18–19"
    ]
  },
  "Exodus 9:12": {
    "title": "Pharaoh’s heart remains hard",
    "text": "The LORD hardens Pharaoh’s heart, and Pharaoh does not listen, as the LORD had spoken to Moses. The narrative continues to portray Pharaoh’s resistance within the unfolding judgment against Egypt.",
    "refs": [
      "Exodus 7:3",
      "Exodus 8:15"
    ]
  },
  "Exodus 9:13": {
    "title": "Rise early and confront Pharaoh",
    "text": "Moses is told to rise early, stand before Pharaoh, and repeat the demand to let Israel go. The confrontation continues because Pharaoh’s refusal has not changed.",
    "refs": [
      "Exodus 8:20"
    ]
  },
  "Exodus 9:14": {
    "title": "Judgments to make God’s power known",
    "text": "God says He will send His plagues upon Pharaoh and his servants so Pharaoh may know that none is like Him in all the earth. The judgments reveal God’s unmatched authority; they are not merely demonstrations for spectacle.",
    "refs": [
      "Exodus 8:10",
      "Exodus 9:16"
    ]
  },
  "Exodus 9:15": {
    "title": "Egypt could have been struck already",
    "text": "God says He could have stretched out His hand and struck Egypt so that Pharaoh and his people were cut off. This statement highlights God’s restraint and the progressive unfolding of judgment.",
    "refs": [
      "Exodus 9:16"
    ]
  },
  "Exodus 9:16": {
    "title": "Pharaoh remains for God’s purpose",
    "text": "God says He has raised Pharaoh up to show His power and make His name known throughout the earth. The verse explains the public purpose of the confrontation; it should be read with the account’s repeated descriptions of Pharaoh’s own stubbornness and choices.",
    "refs": [
      "Romans 9:17",
      "Exodus 7:3–5"
    ]
  },
  "Exodus 9:17": {
    "title": "Pharaoh exalts himself against Israel",
    "text": "God charges Pharaoh with continuing to exalt himself against His people by refusing to let them go. The conflict is not simply political; Pharaoh is resisting the LORD’s authority.",
    "refs": [
      "Exodus 5:2"
    ]
  },
  "Exodus 9:18": {
    "title": "A great hail at an appointed time",
    "text": "God announces a hailstorm unlike any previously seen in Egypt. The specified time gives Pharaoh and his servants an opportunity to heed the warning.",
    "refs": [
      "Exodus 9:20–21"
    ]
  },
  "Exodus 9:19": {
    "title": "Bring people and livestock inside",
    "text": "The Egyptians are warned to shelter their livestock and servants from the coming hail. The warning offers a practical opportunity to respond to God’s word before the judgment arrives.",
    "refs": [
      "Exodus 9:20"
    ]
  },
  "Exodus 9:20": {
    "title": "Some Egyptians fear the word",
    "text": "Pharaoh’s servants who fear the LORD’s word bring their servants and livestock into their houses. Their response shows that some Egyptians begin to take God’s warning seriously.",
    "refs": [
      "Exodus 9:21"
    ]
  },
  "Exodus 9:21": {
    "title": "Others disregard the warning",
    "text": "Those who do not regard the LORD’s word leave their servants and livestock in the field. The contrast between the two responses shows the consequences of either heeding or dismissing the warning.",
    "refs": [
      "Exodus 9:19–20"
    ]
  },
  "Exodus 9:22": {
    "title": "Moses stretches his hand toward heaven",
    "text": "The LORD commands Moses to stretch his hand toward heaven so hail will fall across Egypt. The action is performed by Moses at God’s command, while the power and authority belong to the LORD.",
    "refs": [
      "Exodus 9:23"
    ]
  },
  "Exodus 9:23": {
    "title": "Thunder, hail, and fire",
    "text": "Moses stretches out his rod, and the LORD sends thunder, hail, and fire running along the ground. The text attributes the storm to God’s direct judgment.",
    "refs": [
      "Psalm 78:47–48"
    ]
  },
  "Exodus 9:24": {
    "title": "An unprecedented storm",
    "text": "The hail and fire are described as exceptionally severe throughout Egypt. The unusual force of the storm underscores the seriousness of Pharaoh’s refusal.",
    "refs": [
      "Exodus 9:18"
    ]
  },
  "Exodus 9:25": {
    "title": "The hail strikes the land",
    "text": "The storm destroys plants and trees in the field and strikes people and animals left exposed. The judgment has broad agricultural and human consequences.",
    "refs": [
      "Psalm 105:32–33"
    ]
  },
  "Exodus 9:26": {
    "title": "Goshen is spared",
    "text": "Hail does not fall in the land of Goshen where Israel lives. The repeated distinction demonstrates that the LORD can judge Egypt while preserving Israel.",
    "refs": [
      "Exodus 8:22",
      "Exodus 9:4"
    ]
  },
  "Exodus 9:27": {
    "title": "Pharaoh admits wrongdoing",
    "text": "Pharaoh calls Moses and Aaron and says he has sinned, while acknowledging that the LORD is righteous and he and his people are wicked. The confession is made under pressure; the following verses show that it does not produce lasting repentance.",
    "refs": [
      "Exodus 9:28–35"
    ]
  },
  "Exodus 9:28": {
    "title": "Pray for the storm to stop",
    "text": "Pharaoh asks Moses to entreat the LORD because the thunder and hail are enough, promising to let Israel go. The promise must be measured by Pharaoh’s actions after the crisis passes.",
    "refs": [
      "Exodus 8:8–15"
    ]
  },
  "Exodus 9:29": {
    "title": "The earth belongs to the LORD",
    "text": "Moses says he will spread his hands to the LORD and the storm will cease, so Pharaoh may know that the earth belongs to the LORD. This is a declaration of God’s universal sovereignty, not merely authority within Israel.",
    "refs": [
      "Psalm 24:1",
      "Psalm 83:18"
    ]
  },
  "Exodus 9:30": {
    "title": "Moses knows Pharaoh does not yet fear God",
    "text": "Moses says he knows Pharaoh and his servants do not yet fear the LORD God. Their verbal admission has not become genuine submission; the next events confirm Moses’ assessment.",
    "refs": [
      "Exodus 9:27"
    ]
  },
  "Exodus 9:31": {
    "title": "Flax and barley are damaged",
    "text": "The text notes that flax and barley are struck because they were at particular stages of growth. This detail records the storm’s agricultural impact and helps distinguish what was destroyed from what survived.",
    "refs": [
      "Exodus 9:32"
    ]
  },
  "Exodus 9:32": {
    "title": "Wheat and rye survive",
    "text": "Wheat and rye are not struck because they were not yet grown. The detail shows the account’s concern for specific, observable consequences rather than describing the destruction vaguely.",
    "refs": [
      "Exodus 9:31"
    ]
  },
  "Exodus 9:33": {
    "title": "The storm stops at Moses’ prayer",
    "text": "Moses leaves Pharaoh, spreads his hands to the LORD, and the thunder, hail, and rain cease. The stopping of the storm answers the word Moses had spoken and displays God’s control over it.",
    "refs": [
      "Exodus 9:29"
    ]
  },
  "Exodus 9:34": {
    "title": "Pharaoh sins again",
    "text": "When Pharaoh sees the storm has ceased, he sins again and hardens his heart, along with his servants. His earlier confession and promise were temporary responses to danger, not lasting obedience.",
    "refs": [
      "Exodus 8:15",
      "Exodus 9:27"
    ]
  },
  "Exodus 9:35": {
    "title": "The word is fulfilled",
    "text": "Pharaoh’s heart remains hard, and he refuses to let Israel go, as the LORD had spoken through Moses. The chapter closes by confirming the pattern of warning, judgment, temporary response, and renewed refusal.",
    "refs": [
      "Exodus 7:3–5"
    ]
  },
  "Exodus 10:1": {
    "title": "Signs for future generations",
    "text": "The LORD tells Moses to go to Pharaoh because He has hardened Pharaoh’s heart and the hearts of his servants, so that His signs may be shown among them. The signs will also be retold to later generations as testimony to the LORD’s acts.",
    "refs": [
      "Exodus 10:2",
      "Psalm 78:5–7"
    ]
  },
  "Exodus 10:2": {
    "title": "Tell children what God did",
    "text": "Israel is to tell its children and grandchildren how God dealt with Egypt and performed signs, so they may know that He is the LORD. The Exodus becomes a foundational testimony passed from one generation to the next.",
    "refs": [
      "Deuteronomy 6:20–25",
      "Psalm 105:1–5"
    ]
  },
  "Exodus 10:3": {
    "title": "How long will Pharaoh refuse?",
    "text": "Moses and Aaron ask Pharaoh how long he will refuse to humble himself before the LORD. The demand is not simply for political compromise; Pharaoh is called to submit to the one who rules over him.",
    "refs": [
      "Proverbs 29:1"
    ]
  },
  "Exodus 10:4": {
    "title": "Locusts are threatened",
    "text": "God warns that if Pharaoh refuses to release Israel, locusts will come the next day. The next plague will attack the crops left after the hail.",
    "refs": [
      "Exodus 9:31–32"
    ]
  },
  "Exodus 10:5": {
    "title": "Locusts cover the land",
    "text": "The locusts will cover the land so thoroughly that the ground cannot be seen and will eat what remains after the hail. The plague threatens Egypt’s food supply after earlier devastation.",
    "refs": [
      "Joel 1:4"
    ]
  },
  "Exodus 10:6": {
    "title": "Locusts fill the houses",
    "text": "The locusts will fill Pharaoh’s houses and those of his servants and Egyptians, an unprecedented invasion in the memory of their ancestors. Moses then turns and leaves, having delivered the warning.",
    "refs": [
      "Exodus 8:3"
    ]
  },
  "Exodus 10:7": {
    "title": "Pharaoh’s servants urge release",
    "text": "Pharaoh’s servants ask how long he will remain a snare to Egypt and urge him to let Israel go. They recognize that Egypt is being ruined by his refusal, even while Pharaoh resists.",
    "refs": [
      "Exodus 9:20"
    ]
  },
  "Exodus 10:8": {
    "title": "Moses and Aaron are brought back",
    "text": "Pharaoh brings Moses and Aaron back and asks who will go. His question begins a negotiation, but God’s demand is for Israel to serve Him as He commands.",
    "refs": [
      "Exodus 5:1"
    ]
  },
  "Exodus 10:9": {
    "title": "All Israel will go to worship",
    "text": "Moses answers that young and old, sons and daughters, flocks and herds must go because Israel has a feast to the LORD. Worship is a community responsibility involving the whole people, not only selected workers.",
    "refs": [
      "Exodus 3:18",
      "Deuteronomy 31:12"
    ]
  },
  "Exodus 10:10": {
    "title": "Pharaoh offers a sarcastic warning",
    "text": "Pharaoh responds sarcastically, implying that the LORD would need to be with them if he let their families go. He tries to undermine Moses’ request while maintaining control over who may leave.",
    "refs": [
      "Exodus 10:11"
    ]
  },
  "Exodus 10:11": {
    "title": "Only the men may go",
    "text": "Pharaoh offers to let only the men go, but Moses and Aaron are driven from his presence. This restricted offer conflicts with God’s command for the people to worship together.",
    "refs": [
      "Exodus 10:9"
    ]
  },
  "Exodus 10:12": {
    "title": "Moses stretches out his hand",
    "text": "The LORD tells Moses to stretch his hand over Egypt so the locusts will come and eat what the hail left. The judgment follows God’s announced word.",
    "refs": [
      "Exodus 10:4–6"
    ]
  },
  "Exodus 10:13": {
    "title": "An east wind brings locusts",
    "text": "Moses stretches out his rod, and the LORD brings an east wind that carries locusts into Egypt. The narrative identifies God as the one directing the event, even through a natural means such as wind.",
    "refs": [
      "Psalm 78:46",
      "Psalm 105:34"
    ]
  },
  "Exodus 10:14": {
    "title": "The locusts cover Egypt",
    "text": "The locusts spread throughout Egypt in an unprecedented swarm. The scale of the plague confirms the warning Moses delivered.",
    "refs": [
      "Exodus 10:5–6"
    ]
  },
  "Exodus 10:15": {
    "title": "The land is darkened and crops eaten",
    "text": "The locusts cover the ground and consume the remaining plants and fruit left after the hail. Egypt’s food supply is devastated by the continued refusal to obey God.",
    "refs": [
      "Exodus 9:31–32"
    ]
  },
  "Exodus 10:16": {
    "title": "Pharaoh quickly confesses",
    "text": "Pharaoh hastily calls Moses and Aaron and says he has sinned against the LORD and against them. His urgency reflects the severity of the plague, but confession under pressure still needs to be tested by subsequent conduct.",
    "refs": [
      "Exodus 9:27"
    ]
  },
  "Exodus 10:17": {
    "title": "Pray for this death to be removed",
    "text": "Pharaoh asks Moses to forgive his sin this once and entreat the LORD to remove the deadly plague. His plea focuses on relief; the narrative will again show whether he follows through on his promise.",
    "refs": [
      "Exodus 10:18–20"
    ]
  },
  "Exodus 10:18": {
    "title": "Moses entreats the LORD",
    "text": "Moses leaves Pharaoh and prays to the LORD. As with earlier plagues, Moses serves as an intercessor, while God alone controls the plague’s removal.",
    "refs": [
      "Exodus 8:12–13"
    ]
  },
  "Exodus 10:19": {
    "title": "A west wind removes the locusts",
    "text": "The LORD turns a mighty west wind that carries the locusts into the Red Sea, leaving none in Egypt. The precise description underscores that the plague’s end is as fully directed as its beginning.",
    "refs": [
      "Exodus 10:13–15"
    ]
  },
  "Exodus 10:20": {
    "title": "Pharaoh’s heart remains hardened",
    "text": "The LORD hardens Pharaoh’s heart, and he does not let Israel go. The removal of the locusts again brings no lasting change in Pharaoh’s behavior.",
    "refs": [
      "Exodus 10:16–19"
    ]
  },
  "Exodus 10:21": {
    "title": "Darkness over Egypt",
    "text": "The LORD commands Moses to stretch his hand toward heaven, bringing darkness over Egypt that can be felt. The plague is a direct challenge to Egypt’s confidence in its powers and its sources of light.",
    "refs": [
      "Psalm 105:28"
    ]
  },
  "Exodus 10:22": {
    "title": "Three days of darkness",
    "text": "Moses stretches out his hand, and thick darkness covers Egypt for three days. The description stresses the severity and duration of the judgment.",
    "refs": [
      "Exodus 10:21"
    ]
  },
  "Exodus 10:23": {
    "title": "Light remains with Israel",
    "text": "Egyptians cannot see one another or leave their places for three days, but Israel has light in its dwellings. The distinction again demonstrates the LORD’s power to judge Egypt while preserving His people.",
    "refs": [
      "Exodus 8:22",
      "Exodus 9:26"
    ]
  },
  "Exodus 10:24": {
    "title": "Pharaoh offers another compromise",
    "text": "Pharaoh says the people may go to serve the LORD but must leave their flocks and herds behind. The offer still withholds what is needed for the worship God commanded.",
    "refs": [
      "Exodus 10:9"
    ]
  },
  "Exodus 10:25": {
    "title": "Moses insists on sacrifices",
    "text": "Moses says Pharaoh must also provide sacrifices and burnt offerings for Israel to sacrifice to the LORD. He is not asking Pharaoh to invent worship but explaining that the people must obey God’s instructions.",
    "refs": [
      "Exodus 3:18",
      "Exodus 5:3"
    ]
  },
  "Exodus 10:26": {
    "title": "Not a hoof left behind",
    "text": "Moses says Israel’s livestock must go because they do not know what they will need to serve the LORD until they arrive. The statement emphasizes complete departure and complete obedience to God’s direction.",
    "refs": [
      "Exodus 12:32"
    ]
  },
  "Exodus 10:27": {
    "title": "Pharaoh’s heart is hardened again",
    "text": "The LORD hardens Pharaoh’s heart, and Pharaoh refuses to let Israel go. The final warning before the last plague will follow this refusal.",
    "refs": [
      "Exodus 11:1"
    ]
  },
  "Exodus 10:28": {
    "title": "Pharaoh threatens Moses",
    "text": "Pharaoh orders Moses to leave and warns him never to see his face again, threatening death if he does. Pharaoh’s defiance escalates, but he cannot cancel the LORD’s announced purpose.",
    "refs": [
      "Exodus 11:4–8"
    ]
  },
  "Exodus 10:29": {
    "title": "Moses agrees not to return",
    "text": "Moses says Pharaoh has spoken rightly and that he will see his face no more. The statement closes this confrontation; Moses has delivered the warnings God commanded, and the next chapter announces the final plague.",
    "refs": [
      "Exodus 11:1–8"
    ]
  },
  "Exodus 11:1": {
    "title": "One more plague",
    "text": "The LORD tells Moses that one more plague will come upon Pharaoh and Egypt, after which Pharaoh will send Israel away and even drive them out. God announces the outcome before the final judgment, showing that Pharaoh’s power cannot prevent the promised deliverance.",
    "refs": [
      "Exodus 3:19–20",
      "Exodus 12:31–33"
    ]
  },
  "Exodus 11:2": {
    "title": "Ask for silver and gold",
    "text": "Moses is told that Israelite men and women should ask their Egyptian neighbors for silver and gold articles. This prepares for the departure with provision after years of forced labor; Exodus later says the Egyptians grant the requests.",
    "refs": [
      "Exodus 3:21–22",
      "Exodus 12:35–36"
    ]
  },
  "Exodus 11:3": {
    "title": "Moses is respected in Egypt",
    "text": "The LORD gives Israel favor in the Egyptians’ sight, and Moses is regarded as great by Pharaoh’s servants and the people. The contrast with Pharaoh’s hostility shows that the king’s view does not represent every Egyptian’s response.",
    "refs": [
      "Exodus 3:21",
      "Exodus 12:36"
    ]
  },
  "Exodus 11:4": {
    "title": "The LORD announces the final judgment",
    "text": "Moses declares that at about midnight the LORD will go out into the midst of Egypt. The wording presents the judgment as God’s own act, not merely a human uprising or an unexplained disaster.",
    "refs": [
      "Exodus 12:12",
      "Exodus 12:29"
    ]
  },
  "Exodus 11:5": {
    "title": "The firstborn will die",
    "text": "The firstborn throughout Egypt, from Pharaoh’s household to the lowest servant and even among livestock, will die. The severity of the judgment answers Pharaoh’s earlier decree against Hebrew sons, though the text presents this as divine judgment rather than a general license for human vengeance.",
    "refs": [
      "Exodus 1:22",
      "Exodus 4:22–23"
    ]
  },
  "Exodus 11:6": {
    "title": "A great cry in Egypt",
    "text": "A great cry will rise throughout Egypt, unlike any before or after it. The prediction emphasizes the widespread grief that will follow the final plague.",
    "refs": [
      "Exodus 12:30"
    ]
  },
  "Exodus 11:7": {
    "title": "Israel is distinguished",
    "text": "No dog will move its tongue against Israel’s people or livestock, so Egypt will know that the LORD distinguishes Israel from Egypt. The expression emphasizes a remarkable peace and protection for Israel during judgment.",
    "refs": [
      "Exodus 8:22–23",
      "Exodus 9:4"
    ]
  },
  "Exodus 11:8": {
    "title": "Pharaoh’s servants will urge departure",
    "text": "Moses says Pharaoh’s servants will bow and urge him and the people to leave, after which Moses departs in anger. The anger follows the repeated refusal and the announced judgment; Moses is not portrayed as acting without God’s instructions.",
    "refs": [
      "Exodus 10:28–29",
      "Exodus 12:31–33"
    ]
  },
  "Exodus 11:9": {
    "title": "Pharaoh will not listen",
    "text": "The LORD says Pharaoh will not listen so that God’s wonders may be multiplied in Egypt. The statement fits the account’s repeated pattern of Pharaoh’s resistance and God’s public revelation through judgment.",
    "refs": [
      "Exodus 7:3–5",
      "Exodus 10:1–2"
    ]
  },
  "Exodus 11:10": {
    "title": "The signs before Pharaoh",
    "text": "Moses and Aaron have performed the signs, but Pharaoh has not let Israel go because the LORD has hardened his heart as described in the narrative. The verse summarizes the conflict and prepares for the final plague and departure.",
    "refs": [
      "Exodus 7:13",
      "Exodus 10:27"
    ]
  },
  "Exodus 12:1": {
    "title": "A new beginning in Egypt",
    "text": "The LORD speaks to Moses and Aaron in Egypt, giving instructions that will shape Israel’s calendar and worship. The deliverance is not only an escape from slavery; it becomes a defining event in Israel’s life with God.",
    "refs": [
      "Exodus 12:14",
      "Deuteronomy 16:1"
    ]
  },
  "Exodus 12:2": {
    "title": "The first month",
    "text": "God declares this month the beginning of months for Israel. The calendar is organized around the deliverance, so Israel’s national memory and worship will continually recall what the LORD has done.",
    "refs": [
      "Exodus 13:4",
      "Deuteronomy 16:1"
    ]
  },
  "Exodus 12:3": {
    "title": "Each household takes a lamb",
    "text": "Israel is instructed to take a lamb for each household on the tenth day of the month. The household-based instruction makes the observance communal and domestic, with neighbors joining when a household is too small.",
    "refs": [
      "Exodus 12:4"
    ]
  },
  "Exodus 12:4": {
    "title": "Share according to the household",
    "text": "A household too small for one lamb is to share with its neighbor according to the number of people and what each can eat. The provision aims for an appropriate meal rather than waste or exclusion.",
    "refs": [
      "Exodus 12:3",
      "Exodus 12:10"
    ]
  },
  "Exodus 12:5": {
    "title": "A male without blemish",
    "text": "The lamb must be a male of the first year and without blemish, taken from the sheep or goats. The animal is to meet the stated requirements for this sacred meal; later Christian interpretation sees Passover imagery fulfilled in Jesus, while the immediate instruction concerns Israel’s deliverance from Egypt.",
    "refs": [
      "Leviticus 22:20–22",
      "1 Corinthians 5:7",
      "1 Peter 1:19"
    ]
  },
  "Exodus 12:6": {
    "title": "Kept until the fourteenth day",
    "text": "The lamb is kept until the fourteenth day, when the congregation kills it at evening. The shared timing joins the households in one national observance of the LORD’s deliverance.",
    "refs": [
      "Exodus 12:18"
    ]
  },
  "Exodus 12:7": {
    "title": "Blood on the doorposts",
    "text": "The Israelites are to put some blood on the two side posts and upper doorpost of the houses where they eat. The blood serves as the appointed sign for the judgment that is coming; the text’s emphasis is on obeying God’s instruction and trusting His stated promise.",
    "refs": [
      "Exodus 12:13",
      "Hebrews 11:28"
    ]
  },
  "Exodus 12:8": {
    "title": "Roasted lamb, unleavened bread, and bitter herbs",
    "text": "The meal is to include roasted lamb, unleavened bread, and bitter herbs. The meal’s features preserve the memory of deliverance under urgent circumstances and the bitterness of bondage.",
    "refs": [
      "Exodus 12:11",
      "Deuteronomy 16:3"
    ]
  },
  "Exodus 12:9": {
    "title": "Do not eat it raw or boiled",
    "text": "The lamb must not be eaten raw or boiled in water, but roasted with fire, including its head, legs, and inner parts. The instructions specify the form of the Passover meal and are to be followed as given.",
    "refs": [
      "Exodus 12:8"
    ]
  },
  "Exodus 12:10": {
    "title": "Nothing left until morning",
    "text": "Any portion remaining until morning is to be burned. The command prevents the meal from being treated casually or preserved contrary to the prescribed observance.",
    "refs": [
      "Exodus 12:4",
      "Exodus 12:46"
    ]
  },
  "Exodus 12:11": {
    "title": "Eat ready to depart",
    "text": "Israel is to eat dressed for travel, with shoes on, staff in hand, and in haste. The meal is called the LORD’s passover and is eaten in expectation of immediate departure from bondage.",
    "refs": [
      "Exodus 12:31–33",
      "Deuteronomy 16:3"
    ]
  },
  "Exodus 12:12": {
    "title": "The LORD judges Egypt’s gods",
    "text": "God says He will pass through Egypt, strike the firstborn, and execute judgment against the gods of Egypt, declaring, “I am the LORD.” The plague reveals the impotence of Egypt’s religious powers before the one true God.",
    "refs": [
      "Numbers 33:4",
      "Isaiah 19:1"
    ]
  },
  "Exodus 12:13": {
    "title": "The blood as a sign",
    "text": "The blood will be a sign on the houses, and when the LORD sees it He will pass over them; the plague will not destroy them. The protection is based on God’s promise and Israel’s obedience to His command, not on the blood having independent magical power.",
    "refs": [
      "Exodus 12:7",
      "Hebrews 11:28"
    ]
  },
  "Exodus 12:14": {
    "title": "A memorial day",
    "text": "The day is to be remembered as a feast to the LORD throughout Israel’s generations. The deliverance becomes a lasting testimony to God’s saving action.",
    "refs": [
      "Exodus 13:8–10",
      "Deuteronomy 16:1–3"
    ]
  },
  "Exodus 12:15": {
    "title": "Seven days without leaven",
    "text": "Israel must eat unleavened bread for seven days and remove leaven from the houses. The seriousness of the command is expressed by the penalty for eating leaven during the appointed feast.",
    "refs": [
      "Exodus 13:6–7",
      "1 Corinthians 5:7–8"
    ]
  },
  "Exodus 12:16": {
    "title": "Holy assemblies",
    "text": "The first and seventh days are to be holy assemblies, with no ordinary work except preparing what each person needs to eat. Worship and rest are built into the observance while practical food needs are allowed.",
    "refs": [
      "Leviticus 23:7–8"
    ]
  },
  "Exodus 12:17": {
    "title": "The Feast of Unleavened Bread",
    "text": "God commands Israel to keep the Feast of Unleavened Bread because on that day He brought their hosts out of Egypt. The observance remembers a historical deliverance that God Himself accomplished.",
    "refs": [
      "Exodus 13:3–10"
    ]
  },
  "Exodus 12:18": {
    "title": "Unleavened bread from evening to evening",
    "text": "The dates for eating unleavened bread are specified from the evening of the fourteenth day through the evening of the twenty-first. The timing makes the observance clear and orderly for the community.",
    "refs": [
      "Exodus 12:6",
      "Leviticus 23:5–6"
    ]
  },
  "Exodus 12:19": {
    "title": "Leaven removed from every home",
    "text": "For seven days no leaven is to be found in the houses, and the same serious penalty is stated for native-born and stranger alike. The command makes the observance apply across the community rather than only to one family group.",
    "refs": [
      "Exodus 12:15"
    ]
  },
  "Exodus 12:20": {
    "title": "No leaven anywhere",
    "text": "God repeats that Israel must eat unleavened bread wherever they dwell. Repetition underlines the centrality of this practice in remembering the departure from Egypt.",
    "refs": [
      "Exodus 12:17–19"
    ]
  },
  "Exodus 12:21": {
    "title": "The elders are instructed",
    "text": "Moses calls Israel’s elders and tells them to select and kill the Passover lambs. The instructions are passed through recognized community leaders so the households can act together.",
    "refs": [
      "Exodus 12:3–6"
    ]
  },
  "Exodus 12:22": {
    "title": "Hyssop and the blood",
    "text": "The people are to use a bunch of hyssop to apply the blood to the doorposts and stay inside until morning. The clear instruction to remain inside is part of the appointed means of protection that night.",
    "refs": [
      "Exodus 12:7",
      "Psalm 51:7"
    ]
  },
  "Exodus 12:23": {
    "title": "The LORD protects the marked houses",
    "text": "The LORD will pass through to strike Egypt, but when He sees the blood on the doorposts He will pass over the entrance and not allow the destroyer to enter the house. The verse describes judgment and protection under God’s direction; it does not present the destroyer as an independent power equal to God.",
    "refs": [
      "Exodus 12:12–13"
    ]
  },
  "Exodus 12:24": {
    "title": "Keep the ordinance",
    "text": "Israel is commanded to observe this practice as a lasting ordinance for themselves and their children. The memorial is meant to carry the story of deliverance beyond the generation that experienced it.",
    "refs": [
      "Exodus 12:14",
      "Exodus 12:26–27"
    ]
  },
  "Exodus 12:25": {
    "title": "The promised land observance",
    "text": "When Israel enters the land the LORD promised, they are to keep the service. The observance is connected to both the historical exodus and the future fulfillment of God’s land promise.",
    "refs": [
      "Genesis 15:18",
      "Exodus 3:8"
    ]
  },
  "Exodus 12:26": {
    "title": "Children ask what it means",
    "text": "God anticipates that children will ask about the meaning of the service. The question creates an opportunity for parents to explain God’s saving work rather than leaving the ritual unexplained.",
    "refs": [
      "Deuteronomy 6:20–25"
    ]
  },
  "Exodus 12:27": {
    "title": "The Passover sacrifice and worship",
    "text": "Israel is to explain that the Passover sacrifice recalls how the LORD passed over Israel’s houses while striking Egypt. The people bow their heads and worship, responding to the promise with reverence and obedience.",
    "refs": [
      "Exodus 12:13",
      "Hebrews 11:28"
    ]
  },
  "Exodus 12:28": {
    "title": "Israel obeys the command",
    "text": "The Israelites go and do what the LORD commanded Moses and Aaron. The account highlights their obedience before the judgment takes place.",
    "refs": [
      "Exodus 12:21–27"
    ]
  },
  "Exodus 12:29": {
    "title": "The firstborn die",
    "text": "At midnight the LORD strikes the firstborn throughout Egypt, from Pharaoh’s household to the captive and the firstborn of livestock. This is the climactic judgment announced in chapter 11 and the turning point that forces Pharaoh to release Israel.",
    "refs": [
      "Exodus 11:4–6"
    ]
  },
  "Exodus 12:30": {
    "title": "A great cry in Egypt",
    "text": "Pharaoh, his servants, and the Egyptians rise in the night, and there is a great cry because every house has death. The predicted grief becomes reality, and the land that inflicted suffering on Israel now experiences profound loss.",
    "refs": [
      "Exodus 11:6"
    ]
  },
  "Exodus 12:31": {
    "title": "Pharaoh sends Israel away",
    "text": "Pharaoh calls Moses and Aaron by night and tells them to rise and leave with Israel. He now yields to the demand he had repeatedly refused, though the narrative will still show further pursuit after the departure.",
    "refs": [
      "Exodus 3:19–20",
      "Exodus 14:5–8"
    ]
  },
  "Exodus 12:32": {
    "title": "Take the flocks and bless me",
    "text": "Pharaoh tells Israel to take their flocks and herds and asks Moses to bless him also. The demand for full departure is finally accepted, and Pharaoh seeks blessing from the God whose authority he had denied.",
    "refs": [
      "Exodus 10:24–26"
    ]
  },
  "Exodus 12:33": {
    "title": "The Egyptians urge Israel to leave",
    "text": "The Egyptians press Israel to leave quickly, fearing that they will all die. The urgency is a direct result of the final plague and the accumulated judgments.",
    "refs": [
      "Exodus 11:1",
      "Exodus 12:29–30"
    ]
  },
  "Exodus 12:34": {
    "title": "Dough before it is leavened",
    "text": "The Israelites carry their dough before it is leavened, with kneading bowls wrapped in their clothing. This practical detail explains why unleavened bread becomes associated with the hurried departure.",
    "refs": [
      "Exodus 12:39"
    ]
  },
  "Exodus 12:35": {
    "title": "Israel asks for silver and gold",
    "text": "The Israelites do as Moses instructed and ask the Egyptians for silver, gold, and clothing. The request follows God’s prior promise that Israel would not leave empty-handed.",
    "refs": [
      "Exodus 3:21–22",
      "Exodus 11:2"
    ]
  },
  "Exodus 12:36": {
    "title": "The Egyptians grant their requests",
    "text": "The LORD gives Israel favor, and the Egyptians give what they ask for; thus Israel receives goods from Egypt. The narrative presents this as God’s fulfillment of His promise after Israel’s years of oppression.",
    "refs": [
      "Genesis 15:14",
      "Exodus 3:21"
    ]
  },
  "Exodus 12:37": {
    "title": "Israel journeys from Rameses",
    "text": "Israel travels from Rameses to Succoth, with about six hundred thousand men on foot besides children. The count emphasizes the remarkable growth of the family that entered Egypt, though the exact total population is not specified by this number alone.",
    "refs": [
      "Exodus 1:7",
      "Numbers 33:3–5"
    ]
  },
  "Exodus 12:38": {
    "title": "A mixed multitude travels too",
    "text": "A mixed multitude goes with Israel, along with flocks and herds. The departing company includes more than ethnic Israelites, showing that others also leave Egypt with them.",
    "refs": [
      "Numbers 11:4"
    ]
  },
  "Exodus 12:39": {
    "title": "Unleavened cakes for the journey",
    "text": "Israel bakes unleavened cakes because they were driven from Egypt and could not delay or prepare provisions. The text connects unleavened bread to the haste of departure as well as the memorial feast.",
    "refs": [
      "Exodus 12:34"
    ]
  },
  "Exodus 12:40": {
    "title": "The years of sojourning",
    "text": "The KJV states that the sojourning of the children of Israel was four hundred and thirty years. Other biblical passages describe the period in related ways, and interpreters discuss how the years are counted; this verse should be read alongside Genesis 15:13 and Galatians 3:17 rather than isolated from them.",
    "refs": [
      "Genesis 15:13",
      "Galatians 3:17"
    ]
  },
  "Exodus 12:41": {
    "title": "The appointed day arrives",
    "text": "At the end of the four hundred and thirty years, Israel’s hosts go out of Egypt on the same day. The exact timing emphasizes the fulfillment of God’s promise according to His appointed purpose.",
    "refs": [
      "Genesis 15:13–14"
    ]
  },
  "Exodus 12:42": {
    "title": "A night of watching",
    "text": "This night is to be kept as a solemn observance because the LORD brought Israel out of Egypt. The night becomes a memorial of God’s watchful deliverance and Israel’s continuing obligation to remember it.",
    "refs": [
      "Exodus 12:14",
      "Deuteronomy 16:1"
    ]
  },
  "Exodus 12:43": {
    "title": "Who may eat the Passover",
    "text": "The LORD gives further rules about who may participate in the Passover meal. The feast is a covenant ordinance with defined conditions, not an ordinary meal open without regard to its meaning.",
    "refs": [
      "Exodus 12:48–49"
    ]
  },
  "Exodus 12:44": {
    "title": "A purchased servant and circumcision",
    "text": "A purchased servant may eat the Passover after being circumcised. Participation is tied to the covenant sign, showing that household status alone does not determine access to the observance.",
    "refs": [
      "Genesis 17:10–14"
    ]
  },
  "Exodus 12:45": {
    "title": "Certain outsiders excluded",
    "text": "A foreigner and hired servant are not to eat the Passover under these instructions. The restriction belongs to the specific covenant ordinance and should be read with the provision for a stranger who joins the covenant community in verse 48.",
    "refs": [
      "Exodus 12:48"
    ]
  },
  "Exodus 12:46": {
    "title": "The lamb is eaten in one house",
    "text": "The Passover meal is to be eaten in the house; no meat is to be carried outside, and no bone is to be broken. The instructions preserve the integrity of the prescribed meal. John 19:36 later connects the unbroken bones of Jesus with Scripture, applying Passover imagery to His death.",
    "refs": [
      "Numbers 9:12",
      "John 19:36"
    ]
  },
  "Exodus 12:47": {
    "title": "All Israel keeps the Passover",
    "text": "The whole congregation of Israel is instructed to keep the Passover. It is a national memorial of the deliverance that made Israel a free people under God.",
    "refs": [
      "Exodus 12:14"
    ]
  },
  "Exodus 12:48": {
    "title": "A stranger who joins the covenant",
    "text": "A stranger who wishes to keep the Passover must have the males of his household circumcised; then he may participate as one born in the land. The law also states that no uncircumcised male may eat it, while the following verse establishes one rule for native and stranger.",
    "refs": [
      "Genesis 17:10–14",
      "Exodus 12:49"
    ]
  },
  "Exodus 12:49": {
    "title": "One law for native and stranger",
    "text": "The same law applies to the native-born and the stranger living among Israel. Within this ordinance, covenant requirements are not to be changed based on a person’s origin.",
    "refs": [
      "Leviticus 24:22",
      "Numbers 15:15–16"
    ]
  },
  "Exodus 12:50": {
    "title": "Israel obeys the LORD",
    "text": "The children of Israel do as the LORD commanded Moses and Aaron. The summary underscores obedience as the response to the deliverance they have received.",
    "refs": [
      "Exodus 12:28"
    ]
  },
  "Exodus 12:51": {
    "title": "The LORD brings Israel out",
    "text": "On that very day the LORD brings Israel out of Egypt by their hosts. The exodus is attributed to God’s action: Moses leads, Israel follows, but the LORD is the deliverer.",
    "refs": [
      "Exodus 6:6–8",
      "Deuteronomy 5:15"
    ]
  },
  "Exodus 13:1": {
    "title": "Sanctify the firstborn",
    "text": "The LORD commands that every firstborn male among Israel’s people and livestock be set apart to Him. This command remembers that Israel’s firstborn were spared during the final plague and recognizes that life belongs to God.",
    "refs": [
      "Exodus 12:12–13",
      "Exodus 13:11–15"
    ]
  },
  "Exodus 13:2": {
    "title": "The firstborn belongs to the LORD",
    "text": "God claims every firstborn as holy to Him, whether human or animal. The command is rooted in the deliverance from Egypt and will be explained further as a memorial of that rescue.",
    "refs": [
      "Numbers 3:13",
      "Luke 2:22–23"
    ]
  },
  "Exodus 13:3": {
    "title": "Remember the day of departure",
    "text": "Moses tells the people to remember the day they left Egypt, the house of bondage, because the LORD brought them out with a strong hand. They must eat no leavened bread, linking the feast to the hurried departure.",
    "refs": [
      "Exodus 12:34",
      "Deuteronomy 16:3"
    ]
  },
  "Exodus 13:4": {
    "title": "The month Abib",
    "text": "Israel leaves in the month Abib. The date anchors the event in Israel’s calendar and is associated with the beginning of the spring harvest season.",
    "refs": [
      "Exodus 12:2",
      "Deuteronomy 16:1"
    ]
  },
  "Exodus 13:5": {
    "title": "Remember the promised land",
    "text": "When God brings Israel into the land promised to the patriarchs, they are to keep this service in that land. The deliverance from Egypt and the gift of Canaan are linked parts of the covenant promise.",
    "refs": [
      "Genesis 15:18–21",
      "Exodus 3:8"
    ]
  },
  "Exodus 13:6": {
    "title": "Seven days of unleavened bread",
    "text": "For seven days Israel is to eat unleavened bread, and the seventh day is a feast to the LORD. The annual observance gives the community a repeated way to remember God’s deliverance.",
    "refs": [
      "Exodus 12:15–17"
    ]
  },
  "Exodus 13:7": {
    "title": "No leaven in the territory",
    "text": "Unleavened bread is to be eaten for seven days, and no leaven or leavened bread is to be found among Israel. The thorough removal of leaven makes the memorial practice visible in every household.",
    "refs": [
      "Exodus 12:19–20"
    ]
  },
  "Exodus 13:8": {
    "title": "Explain the feast to your child",
    "text": "Parents are to explain that the feast is kept because of what the LORD did for them when they came out of Egypt. The ritual is meant to teach the next generation the history and meaning of God’s saving work.",
    "refs": [
      "Exodus 12:26–27",
      "Deuteronomy 6:20–25"
    ]
  },
  "Exodus 13:9": {
    "title": "A memorial on hand and forehead",
    "text": "The observance is described as a sign on the hand and a memorial between the eyes, so the LORD’s law may be in the mouth. The language emphasizes constant remembrance and obedience; later Jewish practice also developed physical tefillin from related passages.",
    "refs": [
      "Deuteronomy 6:6–8",
      "Deuteronomy 11:18"
    ]
  },
  "Exodus 13:10": {
    "title": "Keep the ordinance each year",
    "text": "Israel is to keep this ordinance at its appointed time every year. Repeated observance keeps the exodus central in Israel’s worship and identity.",
    "refs": [
      "Exodus 12:14"
    ]
  },
  "Exodus 13:11": {
    "title": "The firstborn in Canaan",
    "text": "When the LORD brings Israel into the land promised to the fathers, they are to observe the firstborn ordinance. The command looks ahead to settlement in the promised land.",
    "refs": [
      "Exodus 13:5"
    ]
  },
  "Exodus 13:12": {
    "title": "Set apart the firstborn males",
    "text": "Every firstborn male that opens the womb is to be set apart to the LORD. The command includes livestock and establishes the principle that the firstborn belongs to God.",
    "refs": [
      "Exodus 13:2"
    ]
  },
  "Exodus 13:13": {
    "title": "Redeem the firstborn donkey and son",
    "text": "A firstborn donkey may be redeemed with a lamb, or its neck is to be broken; every firstborn son is to be redeemed. The distinction shows that the firstborn claim is honored through the means God prescribes, not by sacrificing human children.",
    "refs": [
      "Numbers 18:15–16",
      "Luke 2:22–24"
    ]
  },
  "Exodus 13:14": {
    "title": "Tell the next generation why",
    "text": "When a child asks about the ordinance, the parent is to explain that the LORD brought Israel out of Egypt with a strong hand. The question-and-answer pattern turns family life into a place where God’s acts are remembered and taught.",
    "refs": [
      "Exodus 12:26–27",
      "Deuteronomy 6:20–25"
    ]
  },
  "Exodus 13:15": {
    "title": "Pharaoh’s refusal and the firstborn",
    "text": "Moses explains that Pharaoh hardened himself and would not let Israel go, so the LORD slew Egypt’s firstborn; therefore Israel sacrifices firstborn males of the flock and redeems its sons. The observance remembers both judgment and deliverance.",
    "refs": [
      "Exodus 12:29–32",
      "Exodus 4:22–23"
    ]
  },
  "Exodus 13:16": {
    "title": "The sign of deliverance",
    "text": "The ordinance is again described as a sign on the hand and between the eyes because the LORD brought Israel out of Egypt with a strong hand. The repeated language stresses that Israel’s actions and memory should be shaped by God’s saving work.",
    "refs": [
      "Exodus 13:9",
      "Deuteronomy 6:8"
    ]
  },
  "Exodus 13:17": {
    "title": "God leads away from the Philistine route",
    "text": "God does not lead Israel by the shorter road through Philistine territory, because the people might face war and return to Egypt. The detour is described as God’s wise care for a people not yet ready for that confrontation.",
    "refs": [
      "Exodus 14:11–12",
      "Deuteronomy 8:2"
    ]
  },
  "Exodus 13:18": {
    "title": "Israel goes toward the wilderness",
    "text": "God leads Israel around by the wilderness toward the Red Sea, and the people go up armed or prepared for travel. The route places them where God will soon demonstrate His power over Pharaoh’s pursuing army.",
    "refs": [
      "Exodus 14:1–4"
    ]
  },
  "Exodus 13:19": {
    "title": "Joseph’s bones are carried",
    "text": "Moses takes Joseph’s bones with Israel, honoring Joseph’s oath that his remains would be carried out when God visited His people. The action connects the exodus with Joseph’s faith in the covenant promise.",
    "refs": [
      "Genesis 50:24–25",
      "Joshua 24:32",
      "Hebrews 11:22"
    ]
  },
  "Exodus 13:20": {
    "title": "They camp at Etham",
    "text": "Israel journeys from Succoth and camps at Etham on the edge of the wilderness. The route is narrated as a sequence of real places in the people’s journey.",
    "refs": [
      "Exodus 12:37"
    ]
  },
  "Exodus 13:21": {
    "title": "The LORD leads by cloud and fire",
    "text": "The LORD goes before Israel in a pillar of cloud by day and a pillar of fire by night, giving guidance and light. The text describes visible signs of God’s presence and leadership; it does not say that God’s Spirit is confined to the pillar.",
    "refs": [
      "Exodus 14:19–20",
      "Numbers 9:15–23"
    ]
  },
  "Exodus 13:22": {
    "title": "The pillar does not depart",
    "text": "The pillar of cloud by day and fire by night does not depart from before the people. The repeated presence of the sign reassures Israel that God continues to guide them on their journey.",
    "refs": [
      "Exodus 40:36–38"
    ]
  },
  "Exodus 14:1": {
    "title": "God directs the next camp",
    "text": "The LORD speaks to Moses and gives instructions for where Israel is to camp. Their route is not random; God directs the location where the next major confrontation will take place.",
    "refs": [
      "Exodus 14:2–4"
    ]
  },
  "Exodus 14:2": {
    "title": "Camp by the sea",
    "text": "Israel is told to camp by the sea near Pi-hahiroth, between Migdol and the sea, opposite Baal-zephon. These place names establish the setting for the crossing and the Egyptian pursuit.",
    "refs": [
      "Exodus 14:9"
    ]
  },
  "Exodus 14:3": {
    "title": "Pharaoh thinks Israel is trapped",
    "text": "God says Pharaoh will think Israel is confused and trapped in the wilderness. Pharaoh’s interpretation of Israel’s position will lead him to pursue, but God already knows what He intends to do.",
    "refs": [
      "Exodus 14:4"
    ]
  },
  "Exodus 14:4": {
    "title": "God will be honored over Pharaoh",
    "text": "God says He will harden Pharaoh’s heart so he pursues Israel, and He will gain honor over Pharaoh and his army. The outcome will make Egypt know that the LORD is God. The passage’s account of hardening should be read alongside Pharaoh’s repeated choices to resist God.",
    "refs": [
      "Exodus 7:3–5",
      "Exodus 14:17–18"
    ]
  },
  "Exodus 14:5": {
    "title": "Egypt regrets Israel’s departure",
    "text": "Pharaoh and his servants learn that Israel has fled and regret allowing the people to leave. Their change of mind shows that Pharaoh’s release was not a willing surrender to God’s authority.",
    "refs": [
      "Exodus 12:31–33"
    ]
  },
  "Exodus 14:6": {
    "title": "Pharaoh prepares his chariot",
    "text": "Pharaoh makes ready his chariot and takes his people with him. The Egyptian state mobilizes its military power to reverse the release it had been forced to grant.",
    "refs": [
      "Exodus 14:7"
    ]
  },
  "Exodus 14:7": {
    "title": "Six hundred chosen chariots",
    "text": "Pharaoh takes six hundred chosen chariots along with other chariots and captains. The detail highlights the strength of the force pursuing Israel and sets up the contrast with God’s deliverance.",
    "refs": [
      "Exodus 14:9"
    ]
  },
  "Exodus 14:8": {
    "title": "Israel leaves with confidence",
    "text": "The LORD hardens Pharaoh’s heart, and the Egyptians pursue Israel while the Israelites go out with a high hand. The expression portrays Israel’s departure as confident and public, even though danger soon appears.",
    "refs": [
      "Numbers 33:3"
    ]
  },
  "Exodus 14:9": {
    "title": "The Egyptian army catches up",
    "text": "The Egyptians pursue and overtake Israel while they camp by the sea. From a human perspective, Israel now appears trapped between the army and the water.",
    "refs": [
      "Exodus 14:2–3"
    ]
  },
  "Exodus 14:10": {
    "title": "Israel fears and cries to the LORD",
    "text": "When Israel sees the Egyptians approaching, they are afraid and cry to the LORD. Their fear is understandable, but the crisis will expose whether they trust the God who has already delivered them from Egypt.",
    "refs": [
      "Psalm 106:7–8"
    ]
  },
  "Exodus 14:11": {
    "title": "Israel complains to Moses",
    "text": "The people ask whether there were no graves in Egypt and accuse Moses of bringing them into the wilderness to die. Their words express panic and forgetfulness under pressure; the narrative does not present their complaint as faithful confidence.",
    "refs": [
      "Exodus 5:21",
      "Psalm 106:7"
    ]
  },
  "Exodus 14:12": {
    "title": "They preferred bondage to danger",
    "text": "Israel says it would have been better to serve Egypt than die in the wilderness. Their response reveals how fear can make slavery seem safer than following God into an uncertain future.",
    "refs": [
      "Exodus 6:9",
      "Numbers 14:3–4"
    ]
  },
  "Exodus 14:13": {
    "title": "Stand still and see salvation",
    "text": "Moses tells the people not to fear, to stand still, and to see the salvation the LORD will accomplish. He promises that the Egyptians they see will not be seen again in the same way. The confidence rests on God’s action, not Israel’s military strength.",
    "refs": [
      "2 Chronicles 20:17",
      "Psalm 46:10"
    ]
  },
  "Exodus 14:14": {
    "title": "The LORD will fight for Israel",
    "text": "Moses says the LORD will fight for Israel while they hold their peace. This promise is specific to the crisis God has revealed to Moses; it is not a general command never to act, since the next verse tells Israel to go forward.",
    "refs": [
      "Deuteronomy 1:30",
      "Nehemiah 4:20"
    ]
  },
  "Exodus 14:15": {
    "title": "Tell Israel to go forward",
    "text": "The LORD asks Moses why he cries to Him and tells him to command Israel to go forward. Faith in God’s deliverance includes obeying the next instruction God gives, not remaining passive when He commands action.",
    "refs": [
      "Exodus 14:13–16"
    ]
  },
  "Exodus 14:16": {
    "title": "Moses stretches out his rod",
    "text": "Moses is told to lift his rod and stretch his hand over the sea to divide it, so Israel can cross on dry ground. The rod is an instrument used under God’s command; the power belongs to the LORD.",
    "refs": [
      "Exodus 4:17",
      "Exodus 14:21"
    ]
  },
  "Exodus 14:17": {
    "title": "Egypt pursues into the sea",
    "text": "God says the Egyptians will follow Israel into the sea and that He will be honored over Pharaoh and his army. The pursuit becomes the setting for the decisive judgment against Egypt’s military power.",
    "refs": [
      "Exodus 14:4"
    ]
  },
  "Exodus 14:18": {
    "title": "Egypt will know the LORD",
    "text": "When God gains honor over Pharaoh and his chariots, the Egyptians will know that He is the LORD. The central outcome is the public revelation of God’s authority over the empire that defied Him.",
    "refs": [
      "Exodus 7:5",
      "Exodus 14:4"
    ]
  },
  "Exodus 14:19": {
    "title": "The angel and the pillar move",
    "text": "The angel of God and the pillar of cloud move from before Israel to behind them, coming between Israel and Egypt. God’s presence protects Israel and obstructs the pursuing army; the text does not require identifying the angel as a separate God.",
    "refs": [
      "Exodus 13:21–22",
      "Psalm 34:7"
    ]
  },
  "Exodus 14:20": {
    "title": "Darkness for Egypt, light for Israel",
    "text": "The cloud brings darkness to one side and light to the other, so the armies cannot approach each other all night. The same divine presence that guides Israel also stands as a barrier against Egypt.",
    "refs": [
      "Exodus 13:21–22"
    ]
  },
  "Exodus 14:21": {
    "title": "The sea divides by a strong wind",
    "text": "Moses stretches out his hand, and the LORD drives the sea back with a strong east wind through the night, making the waters dry land. The account identifies the LORD as the one who brings about the crossing, using the wind as His means.",
    "refs": [
      "Psalm 77:16–20",
      "Psalm 106:9"
    ]
  },
  "Exodus 14:22": {
    "title": "Israel crosses on dry ground",
    "text": "The Israelites go into the sea on dry ground, with waters as a wall on their right and left. The narrative presents the crossing as a miraculous deliverance, not merely a safe passage around the water.",
    "refs": [
      "1 Corinthians 10:1–2",
      "Hebrews 11:29"
    ]
  },
  "Exodus 14:23": {
    "title": "The Egyptians follow",
    "text": "Pharaoh’s horses, chariots, and horsemen pursue Israel into the sea. The Egyptians enter the path that God has opened for Israel, setting the stage for their judgment.",
    "refs": [
      "Exodus 14:17"
    ]
  },
  "Exodus 14:24": {
    "title": "The LORD troubles the Egyptian army",
    "text": "In the morning watch the LORD looks toward the Egyptian host through the pillar of fire and cloud and troubles them. The language depicts God actively intervening against the pursuing force.",
    "refs": [
      "Exodus 14:25"
    ]
  },
  "Exodus 14:25": {
    "title": "The chariot wheels fail",
    "text": "God takes off the chariot wheels or makes their movement difficult, and the Egyptians recognize that the LORD fights for Israel. Their attempt to retreat comes after they recognize the power they had opposed.",
    "refs": [
      "Exodus 14:14"
    ]
  },
  "Exodus 14:26": {
    "title": "The sea returns over Egypt",
    "text": "The LORD tells Moses to stretch out his hand so the waters return over the Egyptians and their chariots. The same God who opened the path now brings the waters back at His appointed time.",
    "refs": [
      "Exodus 14:21–22"
    ]
  },
  "Exodus 14:27": {
    "title": "The Egyptians are overwhelmed",
    "text": "Moses stretches out his hand, and the sea returns to its strength as morning comes; the Egyptians flee into it. The narrative attributes the outcome to the LORD’s action through the sea.",
    "refs": [
      "Exodus 15:4–5"
    ]
  },
  "Exodus 14:28": {
    "title": "The army is covered by the sea",
    "text": "The returning waters cover Pharaoh’s chariots, horsemen, and the army that followed Israel, and none remains. The verse describes the destruction of the pursuing force, not the destruction of Israel.",
    "refs": [
      "Exodus 14:23–27"
    ]
  },
  "Exodus 14:29": {
    "title": "Israel walks on dry ground",
    "text": "Israel passes through the sea on dry ground, with waters on both sides. The repeated detail emphasizes the contrast between Israel’s protected crossing and Egypt’s destruction.",
    "refs": [
      "Exodus 14:22"
    ]
  },
  "Exodus 14:30": {
    "title": "The LORD saves Israel that day",
    "text": "The LORD saves Israel from the Egyptians, and Israel sees the Egyptians dead on the shore. The chapter identifies God, not Moses or Israel’s strength, as the deliverer.",
    "refs": [
      "Exodus 15:1–2"
    ]
  },
  "Exodus 14:31": {
    "title": "Israel believes the LORD and Moses",
    "text": "Israel sees the great work of the LORD, fears Him, and believes the LORD and His servant Moses. Their faith follows the deliverance they have witnessed; Moses is honored as God’s servant, not as the source of salvation.",
    "refs": [
      "Exodus 4:31",
      "Psalm 106:12",
      "Hebrews 11:29"
    ]
  },
  "Exodus 15:1": {
    "title": "Moses and Israel sing to the LORD",
    "text": "Moses and Israel sing after the LORD has delivered them from Pharaoh’s army. The song gives the credit for victory to God, not to Israel’s strength, and begins a public testimony of His saving power.",
    "refs": [
      "Exodus 14:30–31",
      "Psalm 106:12"
    ]
  },
  "Exodus 15:2": {
    "title": "The LORD is strength and salvation",
    "text": "Israel declares that the LORD is their strength, song, and salvation, and that they will prepare Him a habitation. God is praised as the one who personally delivered them; the verse’s language later appears in other songs of salvation.",
    "refs": [
      "Psalm 118:14",
      "Isaiah 12:2"
    ]
  },
  "Exodus 15:3": {
    "title": "The LORD is a man of war",
    "text": "The song describes the LORD as a warrior who defeats the army that pursued His people. The image is poetic language for God’s victory in this specific judgment, not a command for believers to imitate violence in God’s name.",
    "refs": [
      "Deuteronomy 1:30",
      "Psalm 24:8"
    ]
  },
  "Exodus 15:4": {
    "title": "Pharaoh’s chariots cast into the sea",
    "text": "The song recalls Pharaoh’s chariots and army being thrown into the sea, with his captains drowned. It interprets the crossing as God’s decisive defeat of the power that enslaved Israel.",
    "refs": [
      "Exodus 14:26–28"
    ]
  },
  "Exodus 15:5": {
    "title": "The depths cover the army",
    "text": "The Egyptians sink like a stone into the depths. The imagery celebrates the finality of the deliverance and the collapse of Pharaoh’s pursuit.",
    "refs": [
      "Exodus 14:28"
    ]
  },
  "Exodus 15:6": {
    "title": "God’s right hand is glorious",
    "text": "The song praises the LORD’s right hand as glorious in power and able to shatter the enemy. “Right hand” is a biblical expression of strength and action; it does not require imagining God as a physical being limited to a human form.",
    "refs": [
      "Psalm 118:15–16",
      "Isaiah 41:10"
    ]
  },
  "Exodus 15:7": {
    "title": "God overthrows His adversaries",
    "text": "The LORD’s greatness overthrows those who rise against Him, and His anger consumes them like stubble. The poetry celebrates God’s judgment of the army that pursued Israel after repeated warnings.",
    "refs": [
      "Exodus 14:4",
      "Psalm 2:1–5"
    ]
  },
  "Exodus 15:8": {
    "title": "The waters stand like a heap",
    "text": "The song describes the waters gathering and standing as the depths congeal in the heart of the sea. This poetic retelling magnifies the miracle described in the narrative of the crossing.",
    "refs": [
      "Exodus 14:21–22",
      "Psalm 78:13"
    ]
  },
  "Exodus 15:9": {
    "title": "The enemy’s boast fails",
    "text": "The enemy had planned to pursue, overtake, divide the spoil, and destroy, but those intentions were defeated. The verse contrasts human arrogance with God’s power to rescue His people.",
    "refs": [
      "Exodus 14:5–9"
    ]
  },
  "Exodus 15:10": {
    "title": "The sea overwhelms the enemy",
    "text": "The LORD blows with His wind and the sea covers the Egyptians, who sink like lead in mighty waters. The song attributes the outcome to God’s command and power.",
    "refs": [
      "Exodus 14:27–28"
    ]
  },
  "Exodus 15:11": {
    "title": "None is like the LORD",
    "text": "The song asks who is like the LORD among the gods, majestic in holiness and doing wonders. The question is rhetorical: no rival power compares with Israel’s God. This supports the Bible’s testimony to the uniqueness of the one true God.",
    "refs": [
      "Deuteronomy 3:24",
      "Psalm 86:8–10",
      "Isaiah 46:9"
    ]
  },
  "Exodus 15:12": {
    "title": "The earth swallows the enemy",
    "text": "The LORD stretches out His right hand and the earth swallows the Egyptians. The song poetically describes the total defeat of the pursuing army and continues to credit God as the deliverer.",
    "refs": [
      "Exodus 14:26–28"
    ]
  },
  "Exodus 15:13": {
    "title": "God leads the redeemed",
    "text": "The LORD in mercy leads the people He has redeemed and guides them toward His holy habitation. Redemption here means rescue from bondage, and the journey continues toward worship in God’s presence.",
    "refs": [
      "Exodus 6:6–8",
      "Psalm 77:15"
    ]
  },
  "Exodus 15:14": {
    "title": "The nations hear and tremble",
    "text": "The peoples hear of the exodus and tremble; the account presents God’s deliverance as a witness beyond Israel. The nations will learn that the LORD is not merely a local deity but the God whose acts affect kingdoms.",
    "refs": [
      "Joshua 2:9–11",
      "Joshua 5:1"
    ]
  },
  "Exodus 15:15": {
    "title": "Canaan’s leaders are afraid",
    "text": "The chiefs of Edom and the mighty men of Moab tremble, and Canaan’s inhabitants melt away. The song anticipates the fear that God’s acts will bring upon the peoples along Israel’s route.",
    "refs": [
      "Numbers 22:3",
      "Deuteronomy 2:25"
    ]
  },
  "Exodus 15:16": {
    "title": "Fear until Israel passes through",
    "text": "Terror and dread fall on Israel’s enemies until God’s people pass over. The song asks the LORD to lead the people He has purchased, portraying their safety as dependent on His power.",
    "refs": [
      "Deuteronomy 2:25",
      "Joshua 2:9–11"
    ]
  },
  "Exodus 15:17": {
    "title": "God plants His people on His mountain",
    "text": "The song looks ahead to God bringing Israel into the place He has prepared, the sanctuary established by His hands. The verse anticipates the land and worship that lie ahead; it is a poetic hope rather than a claim that Israel has already reached the destination.",
    "refs": [
      "Deuteronomy 12:5",
      "Psalm 78:54"
    ]
  },
  "Exodus 15:18": {
    "title": "The LORD reigns forever",
    "text": "The song declares that the LORD shall reign for ever and ever. Pharaoh’s empire has fallen, but God’s reign is not temporary or dependent on earthly political power.",
    "refs": [
      "Psalm 10:16",
      "Revelation 11:15"
    ]
  },
  "Exodus 15:19": {
    "title": "The song retells the crossing",
    "text": "The verse summarizes how Pharaoh’s horses entered the sea and the LORD brought the waters back while Israel walked on dry ground. The summary anchors the song in the deliverance just witnessed.",
    "refs": [
      "Exodus 14:22–29"
    ]
  },
  "Exodus 15:20": {
    "title": "Miriam leads the women",
    "text": "Miriam, identified as a prophetess and Aaron’s sister, takes a timbrel, and the women follow her with timbrels and dances. The passage shows women participating publicly in celebrating God’s deliverance.",
    "refs": [
      "Numbers 12:1–2",
      "Micah 6:4"
    ]
  },
  "Exodus 15:21": {
    "title": "Miriam repeats the victory song",
    "text": "Miriam answers the women with a refrain praising the LORD for triumphing gloriously over horse and rider. The refrain echoes the central theme of Moses’ song: God alone won the victory.",
    "refs": [
      "Exodus 15:1"
    ]
  },
  "Exodus 15:22": {
    "title": "Three days without water",
    "text": "Moses leads Israel from the Red Sea into the wilderness of Shur, where they travel three days without finding water. Deliverance from Egypt is followed by wilderness testing, where the people must learn to trust God for daily needs.",
    "refs": [
      "Deuteronomy 8:2–3"
    ]
  },
  "Exodus 15:23": {
    "title": "The waters of Marah are bitter",
    "text": "At Marah the people cannot drink the water because it is bitter, and the place receives its name from that condition. The crisis tests whether Israel will bring its need to God or turn to complaint.",
    "refs": [
      "Numbers 33:8"
    ]
  },
  "Exodus 15:24": {
    "title": "The people murmur against Moses",
    "text": "The people complain to Moses, asking what they will drink. Moses is the immediate leader they address, but the larger story will show that their need must be brought before the LORD.",
    "refs": [
      "Exodus 16:2–3"
    ]
  },
  "Exodus 15:25": {
    "title": "God makes the water sweet",
    "text": "Moses cries to the LORD, who shows him a tree or piece of wood; when Moses casts it into the waters, they become sweet. The text presents the change as God’s answer, not as a magical property of the wood. God also gives Israel an ordinance and a test.",
    "refs": [
      "Exodus 17:1–7"
    ]
  },
  "Exodus 15:26": {
    "title": "Listen and obey the LORD",
    "text": "God calls Israel to diligently heed His voice, do what is right, and keep His commandments, promising protection from the diseases brought upon Egypt. The promise is given within Israel’s covenant setting and should be read as part of that relationship, not as a guarantee that every faithful person in every age will never become ill.",
    "refs": [
      "Deuteronomy 7:12–15",
      "Psalm 103:2–3"
    ]
  },
  "Exodus 15:27": {
    "title": "Elim’s springs and palm trees",
    "text": "Israel comes to Elim, where there are twelve wells of water and seventy palm trees, and camps by the waters. After the bitter waters, this place provides rest and abundance, showing that the journey includes provision as well as testing.",
    "refs": [
      "Numbers 33:9"
    ]
  },
  "Exodus 16:1": {
    "title": "Israel enters the wilderness of Sin",
    "text": "Israel travels from Elim to the wilderness of Sin between Elim and Sinai. The date is recorded, and the next test will concern food as the people continue toward the mountain where God will establish His covenant with them.",
    "refs": [
      "Exodus 19:1–2"
    ]
  },
  "Exodus 16:2": {
    "title": "The congregation murmurs",
    "text": "The whole congregation murmurs against Moses and Aaron in the wilderness. Their complaint is directed at the leaders, but it reflects a struggle to trust God’s provision after leaving Egypt.",
    "refs": [
      "Exodus 15:24"
    ]
  },
  "Exodus 16:3": {
    "title": "Israel longs for Egypt’s food",
    "text": "The people say they would rather have died in Egypt where they ate meat and bread than face hunger in the wilderness. Their memory of Egypt is selective: they recall food but overlook the bondage from which God delivered them.",
    "refs": [
      "Exodus 1:13–14",
      "Numbers 11:4–6"
    ]
  },
  "Exodus 16:4": {
    "title": "Bread from heaven as a test",
    "text": "The LORD promises to rain bread from heaven and instructs the people to gather a daily portion. The provision will test whether Israel walks according to God’s instruction and learns daily dependence on Him.",
    "refs": [
      "Deuteronomy 8:3",
      "John 6:31–35"
    ]
  },
  "Exodus 16:5": {
    "title": "A double portion on the sixth day",
    "text": "On the sixth day the people are to prepare twice as much as they gather on ordinary days. The provision anticipates the Sabbath rest that God will teach them to observe.",
    "refs": [
      "Exodus 16:22–30"
    ]
  },
  "Exodus 16:6": {
    "title": "The LORD brought Israel out",
    "text": "Moses and Aaron tell Israel that by evening they will know the LORD brought them out of Egypt. The provision is meant to deepen their recognition of God as deliverer, not simply satisfy hunger.",
    "refs": [
      "Exodus 6:6–8"
    ]
  },
  "Exodus 16:7": {
    "title": "God hears the murmuring",
    "text": "Moses says Israel will see the glory of the LORD because He has heard their murmuring. He reminds them that their complaint against the leaders is ultimately directed toward the LORD who brought them out.",
    "refs": [
      "Exodus 16:8–10"
    ]
  },
  "Exodus 16:8": {
    "title": "Meat in the evening and bread in the morning",
    "text": "Moses explains that the LORD will give meat in the evening and bread in the morning, because He has heard the people’s complaints. Moses and Aaron are not the source of the provision; the LORD is the one who feeds Israel.",
    "refs": [
      "Psalm 78:24–29"
    ]
  },
  "Exodus 16:9": {
    "title": "Come near before the LORD",
    "text": "Aaron is told to call the congregation to come near before the LORD, who has heard their murmuring. The people are brought before God rather than left to treat their hunger as an argument against His faithfulness.",
    "refs": [
      "Exodus 16:7"
    ]
  },
  "Exodus 16:10": {
    "title": "The glory of the LORD appears",
    "text": "As Aaron speaks, the people look toward the wilderness and the glory of the LORD appears in the cloud. The visible manifestation confirms that God is present and has heard them; it does not mean His being is confined to the cloud.",
    "refs": [
      "Exodus 13:21–22",
      "Exodus 40:34–38"
    ]
  },
  "Exodus 16:11": {
    "title": "The LORD speaks to Moses",
    "text": "The LORD tells Moses that He has heard the murmuring of Israel. The repeated statement assures the people that their need is known, while also exposing their failure to trust.",
    "refs": [
      "Exodus 16:7–8"
    ]
  },
  "Exodus 16:12": {
    "title": "God promises meat and bread",
    "text": "God says Israel will eat meat at evening and be filled with bread in the morning, and will know that He is the LORD their God. Provision is connected with revelation: through daily care, Israel is to learn who their deliverer is.",
    "refs": [
      "Exodus 6:7",
      "Psalm 105:40"
    ]
  },
  "Exodus 16:13": {
    "title": "Quail in the evening",
    "text": "Quail come up in the evening and cover the camp, while dew lies around it. The narrative describes the arrival of the food God promised.",
    "refs": [
      "Numbers 11:31–32"
    ]
  },
  "Exodus 16:14": {
    "title": "A small round thing appears",
    "text": "When the dew lifts, a small round substance lies upon the ground. Israel has not seen it before, and the next verses explain how it is to be gathered and used.",
    "refs": [
      "Exodus 16:15"
    ]
  },
  "Exodus 16:15": {
    "title": "What is it?",
    "text": "The people ask one another what the substance is, and Moses explains that it is the bread the LORD has given them. The name manna is connected with their question, and the provision is identified as God’s gift.",
    "refs": [
      "Deuteronomy 8:3",
      "John 6:31–35"
    ]
  },
  "Exodus 16:16": {
    "title": "Gather according to need",
    "text": "Each person is to gather according to the number in the household, an omer for each person. The instruction makes the daily provision equitable and practical.",
    "refs": [
      "Exodus 16:18"
    ]
  },
  "Exodus 16:17": {
    "title": "Some gather more and some less",
    "text": "The Israelites gather manna in different amounts. The next verse shows that the outcome is measured according to God’s instruction and each household’s need.",
    "refs": [
      "Exodus 16:18"
    ]
  },
  "Exodus 16:18": {
    "title": "Enough for every household",
    "text": "When they measure the manna, those who gathered much have nothing over and those who gathered little have no lack. Paul later uses this passage to teach a principle of sharing so that abundance can meet another’s need.",
    "refs": [
      "2 Corinthians 8:13–15"
    ]
  },
  "Exodus 16:19": {
    "title": "Do not keep it until morning",
    "text": "Moses commands the people not to leave any manna until morning. The command tests whether they will trust God for the next day’s provision rather than hoard what He has supplied for the present day.",
    "refs": [
      "Matthew 6:11"
    ]
  },
  "Exodus 16:20": {
    "title": "Manna kept overnight spoils",
    "text": "Some disobey and keep manna until morning; it breeds worms and stinks, and Moses is angry. The result demonstrates that the daily instructions were to be obeyed rather than replaced with each person’s preferred plan.",
    "refs": [
      "Exodus 16:19"
    ]
  },
  "Exodus 16:21": {
    "title": "Gather each morning",
    "text": "The people gather manna every morning according to what they can eat, and it melts when the sun grows hot. The provision follows a daily rhythm that teaches dependence and timely obedience.",
    "refs": [
      "Exodus 16:4"
    ]
  },
  "Exodus 16:22": {
    "title": "A double portion on the sixth day",
    "text": "On the sixth day the people gather twice as much, two omers per person, and the rulers report it to Moses. This special amount prepares them for the Sabbath and is not a contradiction of the ordinary daily limit.",
    "refs": [
      "Exodus 16:5"
    ]
  },
  "Exodus 16:23": {
    "title": "Tomorrow is the Sabbath rest",
    "text": "Moses says tomorrow is a holy Sabbath to the LORD, and the people are to bake or boil what they need and keep the remainder for morning. The Sabbath is introduced as a day of rest under God’s instruction.",
    "refs": [
      "Genesis 2:2–3",
      "Exodus 20:8–11"
    ]
  },
  "Exodus 16:24": {
    "title": "The manna does not spoil",
    "text": "The people keep the manna until morning as Moses commanded, and it neither stinks nor contains worms. The exception confirms that God has given a special provision for the Sabbath.",
    "refs": [
      "Exodus 16:20"
    ]
  },
  "Exodus 16:25": {
    "title": "Eat what was gathered yesterday",
    "text": "Moses tells the people to eat the manna that day because it is the Sabbath and no new manna will be found in the field. They are to honor the day by resting from gathering.",
    "refs": [
      "Exodus 16:26"
    ]
  },
  "Exodus 16:26": {
    "title": "No manna on the seventh day",
    "text": "Manna is to be gathered for six days, but none appears on the seventh, the Sabbath. The rhythm establishes a weekly pattern of work and rest before the formal commandments at Sinai.",
    "refs": [
      "Exodus 20:8–11"
    ]
  },
  "Exodus 16:27": {
    "title": "Some search on the Sabbath",
    "text": "Some people go out to gather manna on the seventh day but find none. Their action ignores the instruction and reveals how difficult obedience can be even after clear provision.",
    "refs": [
      "Exodus 16:23–26"
    ]
  },
  "Exodus 16:28": {
    "title": "How long will you refuse My commandments?",
    "text": "The LORD rebukes the people for refusing to keep His commandments and laws. The Sabbath instruction is not a casual suggestion; it is part of learning to live under God’s covenant direction.",
    "refs": [
      "Exodus 16:4–5"
    ]
  },
  "Exodus 16:29": {
    "title": "The LORD gives the Sabbath",
    "text": "God reminds Israel that He has given them the Sabbath and therefore supplies a double portion on the sixth day. Each person is to remain in place on the seventh day. The rest is a gift and a command.",
    "refs": [
      "Mark 2:27"
    ]
  },
  "Exodus 16:30": {
    "title": "The people rest on the seventh day",
    "text": "The people rest on the seventh day as commanded. The narrative records the Sabbath practice before Israel receives the covenant law at Sinai.",
    "refs": [
      "Exodus 20:8–11"
    ]
  },
  "Exodus 16:31": {
    "title": "The manna’s appearance and taste",
    "text": "The house of Israel names the food manna; it is like coriander seed, white, and tastes like wafers with honey. The details identify the food that sustained Israel in the wilderness.",
    "refs": [
      "Numbers 11:7–9"
    ]
  },
  "Exodus 16:32": {
    "title": "Keep an omer for future generations",
    "text": "Moses commands that an omer of manna be kept so future generations can see the bread God gave Israel in the wilderness. The preserved sample will serve as a material witness to God’s provision.",
    "refs": [
      "Exodus 16:33–34",
      "Hebrews 9:4"
    ]
  },
  "Exodus 16:33": {
    "title": "Place manna before the LORD",
    "text": "Aaron is told to put the manna in a vessel and lay it before the LORD for preservation through Israel’s generations. The action turns the food into a memorial of divine provision.",
    "refs": [
      "Exodus 16:32",
      "Exodus 16:34"
    ]
  },
  "Exodus 16:34": {
    "title": "Manna is kept as commanded",
    "text": "Aaron places the manna before the testimony as the LORD commanded Moses. The verse records obedience to the instruction to preserve the memorial.",
    "refs": [
      "Exodus 16:32–33"
    ]
  },
  "Exodus 16:35": {
    "title": "Israel eats manna for forty years",
    "text": "Israel eats manna until they come to an inhabited land, continuing through their wilderness journey until reaching Canaan’s borders. God’s provision lasts for the whole period of need.",
    "refs": [
      "Deuteronomy 8:2–4",
      "Joshua 5:12"
    ]
  },
  "Exodus 16:36": {
    "title": "The omer measurement",
    "text": "The verse explains the omer as a tenth part of an ephah. This practical measure clarifies the amount of manna gathered and preserved.",
    "refs": [
      "Exodus 16:16"
    ]
  },
  "Exodus 17:1": {
    "title": "Israel camps at Rephidim",
    "text": "Israel travels by stages as the LORD commands and camps at Rephidim, where there is no water. The people face another test of trust after God has already provided food in the wilderness.",
    "refs": [
      "Exodus 16:4",
      "Numbers 33:12–14"
    ]
  },
  "Exodus 17:2": {
    "title": "The people contend with Moses",
    "text": "The people quarrel with Moses and demand water. Moses asks why they test the LORD, identifying the deeper issue: they are treating their need as evidence that God is not caring for them.",
    "refs": [
      "Exodus 15:24",
      "Deuteronomy 6:16"
    ]
  },
  "Exodus 17:3": {
    "title": "The people complain of thirst",
    "text": "The people thirst and murmur against Moses, asking why he brought them out of Egypt to die of thirst with their children and livestock. Their words repeat the fear-driven complaint heard earlier, even after God’s provision.",
    "refs": [
      "Exodus 14:11–12",
      "Exodus 16:2–3"
    ]
  },
  "Exodus 17:4": {
    "title": "Moses cries to the LORD",
    "text": "Moses cries to the LORD and asks what he should do, because the people are nearly ready to stone him. The leader brings the crisis to God instead of responding with violence or pretending he can supply water himself.",
    "refs": [
      "Exodus 15:25",
      "Numbers 20:6"
    ]
  },
  "Exodus 17:5": {
    "title": "Moses takes the elders and rod",
    "text": "God tells Moses to pass before the people with elders of Israel and take the rod used at the Nile. The elders witness what God is about to do, and the rod recalls earlier signs of God’s power in Egypt.",
    "refs": [
      "Exodus 7:20",
      "Exodus 14:16"
    ]
  },
  "Exodus 17:6": {
    "title": "Water from the rock at Horeb",
    "text": "God says He will stand before Moses on the rock at Horeb; Moses is to strike it, and water will come out for the people. The provision is attributed to God’s presence and command. Paul later uses the rock in a spiritual application, but the immediate event is God supplying water in the wilderness.",
    "refs": [
      "Numbers 20:8–11",
      "1 Corinthians 10:4"
    ]
  },
  "Exodus 17:7": {
    "title": "Massah and Meribah",
    "text": "Moses names the place Massah and Meribah because Israel tested the LORD and asked whether He was among them. The names preserve the memory of their quarrel and warning against demanding proof of God’s presence on their own terms.",
    "refs": [
      "Deuteronomy 6:16",
      "Psalm 95:8–9"
    ]
  },
  "Exodus 17:8": {
    "title": "Amalek attacks Israel",
    "text": "Amalek comes and fights Israel at Rephidim. The newly delivered people now face an armed enemy, and the account shows that God’s care includes help in conflict as well as provision for hunger and thirst.",
    "refs": [
      "Deuteronomy 25:17–18"
    ]
  },
  "Exodus 17:9": {
    "title": "Joshua is sent to fight",
    "text": "Moses tells Joshua to choose men and fight Amalek while Moses stands on the hill with the rod of God in his hand. Joshua acts in the field while Moses intercedes above; both activities are part of the response to the attack.",
    "refs": [
      "Exodus 17:11–13"
    ]
  },
  "Exodus 17:10": {
    "title": "Moses, Aaron, and Hur go up the hill",
    "text": "Joshua fights as Moses, Aaron, and Hur ascend the hill. The scene prepares for the visible relationship between Moses’ raised hands and the battle’s outcome.",
    "refs": [
      "Exodus 24:14"
    ]
  },
  "Exodus 17:11": {
    "title": "Raised hands and Israel’s victory",
    "text": "When Moses holds up his hand, Israel prevails; when he lets it down, Amalek prevails. The narrative portrays dependence on God during the battle, not a magical power in Moses’ arm.",
    "refs": [
      "Psalm 28:2",
      "1 Timothy 2:8"
    ]
  },
  "Exodus 17:12": {
    "title": "Aaron and Hur support Moses",
    "text": "Moses’ hands grow heavy, so Aaron and Hur seat him on a stone and support his hands until sunset. The victory involves shared service; even the leader needs help to continue faithfully.",
    "refs": [
      "Ecclesiastes 4:9–10"
    ]
  },
  "Exodus 17:13": {
    "title": "Joshua defeats Amalek",
    "text": "Joshua defeats Amalek and his people with the sword. The verse records the military outcome while the surrounding narrative attributes Israel’s success to God’s help.",
    "refs": [
      "Exodus 17:11–12"
    ]
  },
  "Exodus 17:14": {
    "title": "Write the event as a memorial",
    "text": "The LORD tells Moses to write the event in a book and rehearse it to Joshua, promising to blot out Amalek’s remembrance from under heaven. The written record preserves God’s judgment and teaches future leadership to remember the battle.",
    "refs": [
      "Deuteronomy 25:17–19"
    ]
  },
  "Exodus 17:15": {
    "title": "The LORD is my banner",
    "text": "Moses builds an altar and names it Jehovah-nissi, meaning the LORD is my banner. A banner gathers and identifies a people; the name declares that Israel’s victory and identity are under the LORD’s leadership.",
    "refs": [
      "Psalm 20:5",
      "Isaiah 11:10"
    ]
  },
  "Exodus 17:16": {
    "title": "The LORD’s conflict with Amalek",
    "text": "Moses declares that the LORD has sworn to have war with Amalek from generation to generation. The statement concerns the specific conflict in Israel’s covenant history and should not be used as a blanket justification for hostility toward people today.",
    "refs": [
      "Deuteronomy 25:17–19"
    ]
  },
  "Exodus 18:1": {
    "title": "Jethro hears what God has done",
    "text": "Jethro, Moses’ father-in-law and priest of Midian, hears of all that God has done for Moses and Israel. The report of the exodus reaches beyond Egypt and Israel’s camp.",
    "refs": [
      "Exodus 2:16–22",
      "Exodus 15:14"
    ]
  },
  "Exodus 18:2": {
    "title": "Zipporah returns to Moses",
    "text": "Jethro brings Zipporah, Moses’ wife, after Moses had sent her away. The verse resumes the family story that was interrupted by Moses’ mission to Egypt.",
    "refs": [
      "Exodus 4:20"
    ]
  },
  "Exodus 18:3": {
    "title": "Gershom’s name recalls exile",
    "text": "Moses’ son Gershom is named again, with the explanation that Moses had been a stranger in a foreign land. The name preserves the memory of Moses’ life away from Egypt before his calling.",
    "refs": [
      "Exodus 2:22"
    ]
  },
  "Exodus 18:4": {
    "title": "Eliezer remembers God’s help",
    "text": "Moses’ other son is named Eliezer because the God of his father helped him and delivered him from Pharaoh’s sword. The name is a testimony that Moses’ survival and mission depend on God’s help.",
    "refs": [
      "Exodus 2:15",
      "Exodus 4:19"
    ]
  },
  "Exodus 18:5": {
    "title": "Jethro comes to the wilderness",
    "text": "Jethro comes to Moses at the mountain of God with Moses’ wife and sons. The family reunion takes place where God has led Israel and where the covenant will soon be given.",
    "refs": [
      "Exodus 3:1",
      "Exodus 19:1–2"
    ]
  },
  "Exodus 18:6": {
    "title": "Jethro sends word to Moses",
    "text": "Jethro tells Moses that he is coming with his wife and sons. The announcement allows Moses to meet his family and receive his father-in-law.",
    "refs": [
      "Exodus 18:2–5"
    ]
  },
  "Exodus 18:7": {
    "title": "Moses welcomes Jethro",
    "text": "Moses goes out to meet Jethro, bows, kisses him, and asks after his welfare; they enter the tent. The scene shows respect and family affection in the midst of Israel’s journey.",
    "refs": [
      "Genesis 29:13"
    ]
  },
  "Exodus 18:8": {
    "title": "Moses recounts God’s deliverance",
    "text": "Moses tells Jethro what the LORD did to Pharaoh and Egypt for Israel’s sake, as well as the hardships along the way and how God delivered them. The testimony includes both trials and rescue, not only the triumph at the sea.",
    "refs": [
      "Exodus 14:30–31",
      "Psalm 107:2"
    ]
  },
  "Exodus 18:9": {
    "title": "Jethro rejoices in God’s goodness",
    "text": "Jethro rejoices over all the good the LORD has done for Israel and delivered them from Egypt. Hearing the testimony leads him to recognize the goodness of God’s acts.",
    "refs": [
      "Psalm 126:2–3"
    ]
  },
  "Exodus 18:10": {
    "title": "Blessed be the LORD",
    "text": "Jethro blesses the LORD who delivered Israel from Pharaoh and Egypt. The response acknowledges that the LORD, not a human ruler, is the true rescuer.",
    "refs": [
      "Exodus 15:1–2"
    ]
  },
  "Exodus 18:11": {
    "title": "The LORD is greater than all gods",
    "text": "Jethro says he now knows that the LORD is greater than all gods, based on what happened when Egypt acted arrogantly against Israel. The statement affirms the LORD’s supremacy; it does not establish that other gods are real divine beings equal to Him.",
    "refs": [
      "Deuteronomy 10:17",
      "Psalm 96:4–5"
    ]
  },
  "Exodus 18:12": {
    "title": "Jethro offers sacrifice and eats with Israel’s elders",
    "text": "Jethro brings a burnt offering and sacrifices to God, and Aaron and Israel’s elders eat with him before God. The meal expresses fellowship and worship after Jethro has heard the testimony of deliverance.",
    "refs": [
      "Genesis 31:54"
    ]
  },
  "Exodus 18:13": {
    "title": "Moses judges the people all day",
    "text": "The next day Moses sits to judge disputes, and the people stand around him from morning until evening. The scene reveals the heavy administrative burden of leading a large community.",
    "refs": [
      "Deuteronomy 1:9–12"
    ]
  },
  "Exodus 18:14": {
    "title": "Jethro asks why Moses works alone",
    "text": "Jethro asks why Moses sits alone while the people wait all day. His question opens a practical discussion about leadership and the need to share responsibilities.",
    "refs": [
      "Numbers 11:14–17"
    ]
  },
  "Exodus 18:15": {
    "title": "The people come to inquire of God",
    "text": "Moses explains that the people come to him to inquire of God. His judicial role includes helping the people seek God’s direction in matters they cannot resolve themselves.",
    "refs": [
      "Deuteronomy 17:8–11"
    ]
  },
  "Exodus 18:16": {
    "title": "Moses teaches God’s statutes",
    "text": "When disputes arise, Moses judges between people and makes known God’s statutes and laws. The work is not only settling arguments; it also teaches the community how to live under God’s instruction.",
    "refs": [
      "Leviticus 24:22"
    ]
  },
  "Exodus 18:17": {
    "title": "Jethro says the arrangement is not good",
    "text": "Jethro tells Moses that the way he is working is not good. Even a faithful leader can use an unsustainable method, and receiving wise counsel can improve the work without diminishing the calling.",
    "refs": [
      "Proverbs 11:14"
    ]
  },
  "Exodus 18:18": {
    "title": "The burden is too heavy",
    "text": "Jethro warns that Moses and the people will wear themselves out because the task is too heavy for one person. The text recognizes human limits and the practical need for shared responsibility.",
    "refs": [
      "Numbers 11:14"
    ]
  },
  "Exodus 18:19": {
    "title": "Jethro advises Moses to represent the people before God",
    "text": "Jethro advises Moses to continue representing the people before God and bringing their difficult matters to Him. His counsel does not remove Moses’ unique role in receiving God’s instruction; it makes the daily work more manageable.",
    "refs": [
      "Exodus 18:20–22"
    ]
  },
  "Exodus 18:20": {
    "title": "Teach the people the way to walk",
    "text": "Moses is to teach the people God’s statutes and laws and show them the way they should walk and the work they should do. Leadership includes instruction that equips people to handle ordinary responsibilities rightly.",
    "refs": [
      "Deuteronomy 6:6–9"
    ]
  },
  "Exodus 18:21": {
    "title": "Choose capable and trustworthy leaders",
    "text": "Jethro advises Moses to select able men who fear God, love truth, and hate covetousness, and appoint them over groups of people. The qualifications emphasize character and justice, not merely status or popularity.",
    "refs": [
      "Deuteronomy 1:13",
      "Acts 6:3"
    ]
  },
  "Exodus 18:22": {
    "title": "Delegate ordinary cases",
    "text": "The appointed leaders are to judge ordinary matters, while bringing the difficult cases to Moses. Delegation makes leadership more sustainable while preserving a way to resolve complex disputes.",
    "refs": [
      "Deuteronomy 1:16–17"
    ]
  },
  "Exodus 18:23": {
    "title": "Counsel that may endure",
    "text": "Jethro says that if God commands Moses to follow this arrangement, Moses will endure and the people will go to their place in peace. The advice is offered with humility: the final authority belongs to God, and the arrangement’s success depends on His approval.",
    "refs": [
      "Proverbs 15:22"
    ]
  },
  "Exodus 18:24": {
    "title": "Moses listens to Jethro",
    "text": "Moses listens to his father-in-law and does all that he has said. The narrative presents Moses as willing to receive sound counsel rather than insisting that he alone can decide every matter.",
    "refs": [
      "Proverbs 12:15"
    ]
  },
  "Exodus 18:25": {
    "title": "Moses appoints leaders",
    "text": "Moses chooses capable men from Israel and makes them heads over groups of thousands, hundreds, fifties, and tens. The structure distributes responsibility throughout the community.",
    "refs": [
      "Deuteronomy 1:15"
    ]
  },
  "Exodus 18:26": {
    "title": "Leaders judge the people",
    "text": "The appointed leaders judge the people at all times, bringing hard cases to Moses while handling smaller matters themselves. The arrangement provides access to justice without requiring every dispute to wait for Moses.",
    "refs": [
      "Exodus 18:22"
    ]
  },
  "Exodus 18:27": {
    "title": "Jethro returns to his land",
    "text": "Moses lets Jethro depart, and Jethro returns to his own land. The visit has provided family reunion, shared worship, and practical counsel for Israel’s leadership.",
    "refs": [
      "Exodus 18:1–12"
    ]
  },
  "Exodus 19:1": {
    "title": "Israel arrives at Sinai",
    "text": "In the third month after leaving Egypt, Israel comes to the wilderness of Sinai. The journey from slavery has brought the people to the mountain where God will establish the covenant that shapes their life as His people.",
    "refs": [
      "Exodus 3:12",
      "Exodus 12:37"
    ]
  },
  "Exodus 19:2": {
    "title": "Israel camps before the mountain",
    "text": "Israel camps before Mount Sinai. The physical location sets the stage for the LORD’s words, the covenant, and the commandments that follow.",
    "refs": [
      "Exodus 3:1",
      "Exodus 19:10–11"
    ]
  },
  "Exodus 19:3": {
    "title": "Moses goes up to God",
    "text": "Moses ascends the mountain, and the LORD calls to him from it. God gives Moses words to deliver to the house of Jacob and the children of Israel, establishing Moses as the messenger of the covenant instruction.",
    "refs": [
      "Exodus 3:4–10",
      "Deuteronomy 5:5"
    ]
  },
  "Exodus 19:4": {
    "title": "God carried Israel on eagles’ wings",
    "text": "The LORD reminds Israel that they saw what He did to Egypt and how He brought them to Himself. The picture of eagles’ wings expresses powerful, protective deliverance; Israel’s covenant relationship begins with God’s saving action, not their achievement.",
    "refs": [
      "Deuteronomy 32:11–12",
      "Isaiah 63:9"
    ]
  },
  "Exodus 19:5": {
    "title": "A treasured possession if Israel obeys",
    "text": "God says that if Israel will obey His voice and keep His covenant, they will be His peculiar treasure among all peoples, because all the earth is His. Israel’s special calling does not mean God lacks authority over other nations; the whole earth belongs to Him.",
    "refs": [
      "Deuteronomy 7:6–8",
      "1 Peter 2:9"
    ]
  },
  "Exodus 19:6": {
    "title": "A kingdom of priests and holy nation",
    "text": "Israel is called to be a kingdom of priests and a holy nation. Their special status carries responsibility to belong to God and represent His holiness among the nations; the verse is addressed to Israel at Sinai in its immediate setting.",
    "refs": [
      "Isaiah 61:6",
      "1 Peter 2:9"
    ]
  },
  "Exodus 19:7": {
    "title": "Moses tells the elders",
    "text": "Moses calls the elders and lays before them the words the LORD commanded. The leaders are given the message so the whole community can respond to the covenant offer.",
    "refs": [
      "Exodus 19:3–6"
    ]
  },
  "Exodus 19:8": {
    "title": "The people agree to obey",
    "text": "The people answer together that they will do all the LORD has spoken, and Moses reports their words to God. Their agreement expresses willingness to enter the covenant; later history will show the need for ongoing faithfulness.",
    "refs": [
      "Exodus 24:3",
      "Joshua 24:24"
    ]
  },
  "Exodus 19:9": {
    "title": "God speaks in a thick cloud",
    "text": "The LORD says He will come to Moses in a thick cloud so the people may hear Him speak and believe Moses. The cloud is a sign of God’s presence and revelation, not a limit on His being. The people are being prepared to hear the covenant words.",
    "refs": [
      "Exodus 13:21–22",
      "Deuteronomy 4:11–12"
    ]
  },
  "Exodus 19:10": {
    "title": "Prepare the people",
    "text": "The LORD tells Moses to sanctify the people and have them wash their clothes. The preparation expresses the seriousness of approaching God’s revealed presence and hearing His covenant word.",
    "refs": [
      "Leviticus 11:44–45"
    ]
  },
  "Exodus 19:11": {
    "title": "Ready for the third day",
    "text": "The people are to be ready for the third day, when the LORD will descend upon Mount Sinai in the sight of all. The language describes a public manifestation of God’s presence for the covenant event.",
    "refs": [
      "Exodus 19:16–20"
    ]
  },
  "Exodus 19:12": {
    "title": "A boundary around the mountain",
    "text": "Moses must set boundaries around the mountain and warn the people not to touch it. The restriction teaches that God’s holiness is not to be approached carelessly and that the people must obey His explicit command.",
    "refs": [
      "Hebrews 12:18–21"
    ]
  },
  "Exodus 19:13": {
    "title": "No one may cross the boundary",
    "text": "The penalty for touching the mountain is severe, and the people must wait until the appointed signal before approaching. The rule belongs to this particular Sinai manifestation and should not be turned into a general instruction about all mountains.",
    "refs": [
      "Exodus 19:12",
      "Exodus 19:16"
    ]
  },
  "Exodus 19:14": {
    "title": "Moses sanctifies the people",
    "text": "Moses descends and sanctifies the people, and they wash their clothes. The community prepares itself as instructed for the solemn encounter.",
    "refs": [
      "Exodus 19:10"
    ]
  },
  "Exodus 19:15": {
    "title": "Prepare for the third day",
    "text": "Moses tells the people to be ready for the third day and to abstain from marital relations during the preparation. The instruction marks the occasion as a period of special consecration.",
    "refs": [
      "Leviticus 15:16–18"
    ]
  },
  "Exodus 19:16": {
    "title": "Thunder, lightning, and the trumpet",
    "text": "On the third day there are thunderings, lightning, a thick cloud, and a loud trumpet, and the people tremble. The signs communicate the awe and seriousness of God’s appearance at Sinai.",
    "refs": [
      "Hebrews 12:18–21"
    ]
  },
  "Exodus 19:17": {
    "title": "The people stand at the mountain",
    "text": "Moses brings the people out of the camp to meet God, and they stand at the foot of the mountain. Their position reflects the boundary established for the encounter.",
    "refs": [
      "Exodus 19:12–13"
    ]
  },
  "Exodus 19:18": {
    "title": "Sinai is covered with smoke",
    "text": "Mount Sinai is covered with smoke because the LORD descends upon it in fire; the mountain trembles. The description uses visible signs to communicate the overwhelming reality of the divine presence.",
    "refs": [
      "Deuteronomy 4:11–12"
    ]
  },
  "Exodus 19:19": {
    "title": "God answers Moses by a voice",
    "text": "As the trumpet grows louder, Moses speaks and God answers him by a voice. The passage emphasizes that the encounter includes actual communication, not merely an inward feeling or symbolic ritual.",
    "refs": [
      "Deuteronomy 5:4–5"
    ]
  },
  "Exodus 19:20": {
    "title": "The LORD descends and calls Moses up",
    "text": "The LORD descends upon the top of Sinai and calls Moses to the top, and Moses goes up. The narrative describes God’s manifest presence at the mountain while maintaining that He is the one who speaks and directs the encounter.",
    "refs": [
      "Exodus 24:12"
    ]
  },
  "Exodus 19:21": {
    "title": "Warn the people not to break through",
    "text": "God tells Moses to go down and warn the people not to break through to gaze, lest many perish. Curiosity does not override the explicit boundary God has set for this holy occasion.",
    "refs": [
      "Exodus 19:12–13"
    ]
  },
  "Exodus 19:22": {
    "title": "The priests must sanctify themselves",
    "text": "Even the priests who approach the LORD must sanctify themselves, lest the LORD break forth upon them. The instruction stresses that religious office does not exempt anyone from reverence and obedience.",
    "refs": [
      "Leviticus 10:1–3"
    ]
  },
  "Exodus 19:23": {
    "title": "Moses recalls the boundary",
    "text": "Moses says the people cannot come up Mount Sinai because God has already commanded a boundary and declared the mountain holy. The exchange shows Moses seeking to follow the earlier instruction carefully.",
    "refs": [
      "Exodus 19:12"
    ]
  },
  "Exodus 19:24": {
    "title": "Moses and Aaron may come up",
    "text": "The LORD tells Moses to go down and return with Aaron, but the priests and people must not break through. The access is granted according to God’s command, not by human initiative.",
    "refs": [
      "Exodus 19:22",
      "Exodus 24:1–2"
    ]
  },
  "Exodus 19:25": {
    "title": "Moses warns the people",
    "text": "Moses goes down to the people and tells them what God has said. The chapter closes with the boundary in place as Israel prepares to hear the commandments.",
    "refs": [
      "Exodus 20:1–2"
    ]
  },
  "Exodus 20:1": {
    "title": "God speaks all these words",
    "text": "God speaks the commandments that follow. Their authority comes from the LORD Himself, who has already delivered Israel from Egypt and now gives them covenant instruction.",
    "refs": [
      "Deuteronomy 5:4–5"
    ]
  },
  "Exodus 20:2": {
    "title": "The LORD who brought Israel out",
    "text": "God identifies Himself as the LORD their God who brought them out of Egypt, out of the house of bondage. The commandments begin with deliverance: Israel is called to obey the God who rescued them, not earn rescue through law-keeping.",
    "refs": [
      "Exodus 6:6–8",
      "Deuteronomy 5:6"
    ]
  },
  "Exodus 20:3": {
    "title": "No other gods before the LORD",
    "text": "Israel must have no other gods before the LORD. The command demands exclusive worship and allegiance to the one God who delivered them; it does not invite Israel to divide devotion among rival deities.",
    "refs": [
      "Deuteronomy 6:4–5",
      "Isaiah 45:5–6"
    ]
  },
  "Exodus 20:4": {
    "title": "No graven image",
    "text": "Israel is forbidden to make a carved image or likeness of anything in heaven, earth, or water as an object of worship. God cannot be reduced to an idol made by human hands, and worship must follow His revelation rather than human invention.",
    "refs": [
      "Deuteronomy 4:15–19",
      "Isaiah 40:18"
    ]
  },
  "Exodus 20:5": {
    "title": "Do not bow to images",
    "text": "Israel must not bow down to idols or serve them, because the LORD is a jealous God who calls for exclusive covenant loyalty. The language of visiting iniquity across generations concerns the consequences of entrenched family and community sin; the following verse also affirms mercy to those who love God and keep His commandments.",
    "refs": [
      "Exodus 34:6–7",
      "Deuteronomy 7:9–10"
    ]
  },
  "Exodus 20:6": {
    "title": "Mercy to those who love God",
    "text": "The LORD shows mercy to thousands of generations of those who love Him and keep His commandments. The verse balances the warning of judgment with a strong promise of covenant mercy.",
    "refs": [
      "Deuteronomy 7:9",
      "Psalm 103:17–18"
    ]
  },
  "Exodus 20:7": {
    "title": "Do not take God’s name in vain",
    "text": "Israel must not misuse the name of the LORD, and God will not hold guiltless the one who does so. The command includes treating God’s name and authority with reverence, not merely avoiding a particular phrase.",
    "refs": [
      "Leviticus 19:12",
      "Matthew 5:33–37"
    ]
  },
  "Exodus 20:8": {
    "title": "Remember the Sabbath",
    "text": "Israel is commanded to remember the Sabbath day and keep it holy. Sabbath observance is part of Israel’s covenant life and calls the people to set apart time for rest and worship.",
    "refs": [
      "Genesis 2:2–3",
      "Deuteronomy 5:12–15"
    ]
  },
  "Exodus 20:9": {
    "title": "Six days for labor",
    "text": "The people are to labor and do their work during six days. The command recognizes ordinary work as part of life while placing it within a rhythm that includes sacred rest.",
    "refs": [
      "Exodus 16:26"
    ]
  },
  "Exodus 20:10": {
    "title": "The seventh day is Sabbath",
    "text": "The seventh day is a Sabbath to the LORD, and household members, servants, livestock, and the stranger within the gates are to rest. The command extends rest beyond the head of household to those under his care.",
    "refs": [
      "Deuteronomy 5:14"
    ]
  },
  "Exodus 20:11": {
    "title": "Creation grounds the Sabbath",
    "text": "God made heaven, earth, sea, and all that is in them in six days and rested the seventh; therefore He blessed the Sabbath. The command connects Israel’s weekly rest with the Creator’s pattern, while Deuteronomy also emphasizes deliverance from slavery.",
    "refs": [
      "Genesis 2:2–3",
      "Deuteronomy 5:15"
    ]
  },
  "Exodus 20:12": {
    "title": "Honor father and mother",
    "text": "Israel is commanded to honor father and mother, with a promise of long life in the land the LORD gives. The command gives family relationships a central place in covenant faithfulness.",
    "refs": [
      "Deuteronomy 5:16",
      "Ephesians 6:1–3"
    ]
  },
  "Exodus 20:13": {
    "title": "Do not murder",
    "text": "The command forbids murder. It protects human life and is not identical to a blanket statement about every use of the Hebrew verb in all legal or military contexts; the command’s moral force is that human life must not be unlawfully taken.",
    "refs": [
      "Genesis 9:6",
      "Matthew 5:21–22"
    ]
  },
  "Exodus 20:14": {
    "title": "Do not commit adultery",
    "text": "The command forbids adultery and protects the faithfulness of marriage. Scripture treats sexual conduct as morally significant rather than merely private preference.",
    "refs": [
      "Leviticus 20:10",
      "Matthew 5:27–28"
    ]
  },
  "Exodus 20:15": {
    "title": "Do not steal",
    "text": "The command forbids taking what belongs to another. It supports honest dealings and respect for a neighbor’s property.",
    "refs": [
      "Leviticus 19:11",
      "Ephesians 4:28"
    ]
  },
  "Exodus 20:16": {
    "title": "Do not bear false witness",
    "text": "Israel must not give false testimony against a neighbor. The immediate legal wording protects justice in court, and the principle also condemns deceitful speech that harms another person.",
    "refs": [
      "Deuteronomy 19:16–19",
      "Proverbs 12:17"
    ]
  },
  "Exodus 20:17": {
    "title": "Do not covet",
    "text": "The command forbids coveting a neighbor’s house, spouse, servants, animals, or anything belonging to the neighbor. Unlike commands focused on outward actions, this one reaches desire and teaches that covenant obedience includes the heart.",
    "refs": [
      "Deuteronomy 5:21",
      "Romans 7:7"
    ]
  },
  "Exodus 20:18": {
    "title": "The people fear the signs",
    "text": "The people see thunder, lightning, trumpet, and smoke and stand at a distance trembling. Their reaction shows the overwhelming effect of the Sinai manifestation.",
    "refs": [
      "Exodus 19:16–18"
    ]
  },
  "Exodus 20:19": {
    "title": "Moses as mediator",
    "text": "The people ask Moses to speak with them rather than have God speak directly, fearing they will die. Moses’ role as mediator becomes prominent, while the text still identifies the LORD as the source of the commandments.",
    "refs": [
      "Deuteronomy 5:5",
      "Galatians 3:19"
    ]
  },
  "Exodus 20:20": {
    "title": "Fear God, do not sin",
    "text": "Moses tells the people not to fear in the sense of panic, for God has come to test them so that His fear may remain before them and they do not sin. Reverent fear is meant to lead to obedience, not hopeless terror.",
    "refs": [
      "Proverbs 1:7",
      "Deuteronomy 6:2"
    ]
  },
  "Exodus 20:21": {
    "title": "Moses draws near to the thick darkness",
    "text": "The people stand far away while Moses approaches the thick darkness where God is. The contrast marks Moses’ assigned role as mediator in this covenant encounter.",
    "refs": [
      "Exodus 19:20",
      "Hebrews 12:18–24"
    ]
  },
  "Exodus 21:1": {
    "title": "Judgments for Israel",
    "text": "After the Ten Commandments, God gives judgments for the community’s civil life. These laws apply covenant principles to disputes, servants, injuries, and property; they must be read in their ancient legal setting rather than treated as though every provision were a direct rule for modern civil law.",
    "refs": [
      "Exodus 20:1–17"
    ]
  },
  "Exodus 21:2": {
    "title": "A Hebrew servant’s release",
    "text": "A Hebrew servant is to serve six years and be released in the seventh without payment. The law places a limit on servitude and prevents the servant from being held indefinitely under this provision.",
    "refs": [
      "Deuteronomy 15:12–15"
    ]
  },
  "Exodus 21:3": {
    "title": "Release according to his household status",
    "text": "If the servant entered alone, he leaves alone; if he had a wife, she leaves with him. The rule addresses the household status under which the service began.",
    "refs": [
      "Exodus 21:2"
    ]
  },
  "Exodus 21:4": {
    "title": "A wife given by the master",
    "text": "If the master gives the servant a wife and she bears children, the wife and children remain under the master’s household status when the man is released. This ancient legal provision reflects a social system different from modern law; it should be studied honestly in its historical context rather than hidden or presented as a universal ideal.",
    "refs": [
      "Exodus 21:2–3"
    ]
  },
  "Exodus 21:5": {
    "title": "A servant chooses to remain",
    "text": "If the servant openly declares that he loves his master, wife, and children and does not want to leave, the law provides a formal process for remaining. The text describes a voluntary declaration under the legal conditions of that society.",
    "refs": [
      "Deuteronomy 15:16–17"
    ]
  },
  "Exodus 21:6": {
    "title": "A formal act of lifelong service",
    "text": "The master brings the servant before the judges and marks the commitment at the door or doorpost. This is a specific ancient legal procedure for the servant who chooses to remain; it is not a general instruction to harm people or deny their dignity.",
    "refs": [
      "Deuteronomy 15:17"
    ]
  },
  "Exodus 21:7": {
    "title": "A daughter sold as a servant",
    "text": "The verse addresses a father selling his daughter as a maidservant and gives conditions different from those for male servants. This reflects ancient household and marriage arrangements; careful interpretation must acknowledge the social context and the protections or limitations the law places within it.",
    "refs": [
      "Exodus 21:8–11"
    ]
  },
  "Exodus 21:8": {
    "title": "Protections for a woman in the household",
    "text": "If the woman does not please the master who selected her, the law provides for redemption and forbids selling her to a foreign people. The passage sets restrictions on the master’s treatment of her, though its ancient social framework differs greatly from modern assumptions about freedom and marriage.",
    "refs": [
      "Exodus 21:7–11"
    ]
  },
  "Exodus 21:9": {
    "title": "A daughter treated as a daughter",
    "text": "If the woman is designated for the master’s son, she is to be treated according to the rights of daughters. The law gives her a recognized status in the household rather than treating her simply as property without obligations toward her.",
    "refs": [
      "Exodus 21:10–11"
    ]
  },
  "Exodus 21:10": {
    "title": "Food, clothing, and marital duty",
    "text": "If the master takes another wife, he must not diminish the first woman’s food, clothing, or marital rights. The provision sets concrete obligations intended to protect her from being deprived when the household arrangement changes.",
    "refs": [
      "Exodus 21:11"
    ]
  },
  "Exodus 21:11": {
    "title": "Freedom if obligations are denied",
    "text": "If the three stated obligations are not fulfilled, the woman is to go out without payment. The rule creates a remedy within the ancient system when the master fails to meet his responsibilities.",
    "refs": [
      "Exodus 21:10"
    ]
  },
  "Exodus 21:12": {
    "title": "A penalty for killing",
    "text": "The law prescribes death for one who strikes another person so that the person dies. This is a legal rule against murder, continuing the protection of human life established in the commandments.",
    "refs": [
      "Genesis 9:6",
      "Exodus 20:13"
    ]
  },
  "Exodus 21:13": {
    "title": "Unintentional killing and refuge",
    "text": "If a person did not lie in wait but God allowed the event to happen, a place of refuge is provided. The distinction between intentional murder and accidental killing is important to biblical law and is developed further in the cities of refuge.",
    "refs": [
      "Numbers 35:9–15",
      "Deuteronomy 19:4–6"
    ]
  },
  "Exodus 21:14": {
    "title": "Intentional murder",
    "text": "A person who acts presumptuously to kill a neighbor by deceit is to be taken even from the altar for punishment. Sacred space does not provide immunity for deliberate murder; justice cannot be evaded by claiming religious protection.",
    "refs": [
      "1 Kings 2:28–34"
    ]
  },
  "Exodus 21:15": {
    "title": "Violence against parents",
    "text": "The law prescribes severe punishment for striking one’s father or mother. It treats violence against parents as a serious violation of family order and the command to honor them.",
    "refs": [
      "Exodus 20:12",
      "Deuteronomy 5:16"
    ]
  },
  "Exodus 21:16": {
    "title": "Kidnapping a person",
    "text": "The law prescribes death for kidnapping a person and selling or retaining that person. Human beings are not to be abducted and trafficked for gain; the rule directly condemns such exploitation.",
    "refs": [
      "Deuteronomy 24:7",
      "1 Timothy 1:9–10"
    ]
  },
  "Exodus 21:17": {
    "title": "Cursing father or mother",
    "text": "The law gives a severe penalty for cursing one’s father or mother. It emphasizes the seriousness of contempt and abuse within the family, though modern application must distinguish the ancient judicial penalty from the enduring moral principle of honoring parents.",
    "refs": [
      "Exodus 20:12",
      "Leviticus 20:9"
    ]
  },
  "Exodus 21:18": {
    "title": "Injury during a fight",
    "text": "If two people fight and one injures the other with a stone or fist but the injured person recovers, the aggressor is responsible for the loss of time and medical expenses. The law connects liability to the actual harm caused.",
    "refs": [
      "Deuteronomy 19:21"
    ]
  },
  "Exodus 21:19": {
    "title": "Compensation for recovery and lost work",
    "text": "If the injured person can rise and walk with a staff, the person who caused the injury must pay for lost time and ensure compensation for healing. The passage seeks restitution for the injury rather than treating violence as a matter without consequence.",
    "refs": [
      "Exodus 21:18"
    ]
  },
  "Exodus 21:20": {
    "title": "A servant beaten by a master",
    "text": "The law addresses a master who strikes a male or female servant with a rod. If the servant dies under the blow, the master is subject to punishment; the provision recognizes the servant’s life as legally significant, even within an unequal ancient system.",
    "refs": [
      "Exodus 21:26–27"
    ]
  },
  "Exodus 21:21": {
    "title": "A distinction in the ancient legal code",
    "text": "The verse distinguishes a servant who survives for a day or two, using the legal reasoning that the servant is the master’s money. This reflects the harsh social structure of the ancient world and should not be mistaken for a declaration that a person’s life has no value; nearby laws impose penalties for severe injury.",
    "refs": [
      "Exodus 21:20",
      "Exodus 21:26–27"
    ]
  },
  "Exodus 21:22": {
    "title": "Injury to a pregnant woman",
    "text": "The law addresses men fighting who injure a pregnant woman and cause premature birth or other harm. It distinguishes outcomes and sets a legal process for determining liability; translations and interpretations of the precise outcome in this verse differ.",
    "refs": [
      "Deuteronomy 19:15–21"
    ]
  },
  "Exodus 21:23": {
    "title": "Life for life",
    "text": "If serious harm follows, the law states the principle of life for life and corresponding penalties. This is a judicial proportionality rule intended to limit punishment to the harm caused, not a private license for personal revenge.",
    "refs": [
      "Leviticus 24:19–20",
      "Matthew 5:38–42"
    ]
  },
  "Exodus 21:24": {
    "title": "Eye for eye and tooth for tooth",
    "text": "The law lists injuries and corresponding penalties. In its legal context, the principle limits retaliation so punishment corresponds to the injury; it is not permission for individuals to take vengeance into their own hands.",
    "refs": [
      "Leviticus 24:20",
      "Deuteronomy 19:21"
    ]
  },
  "Exodus 21:25": {
    "title": "Burning for burning, wound for wound",
    "text": "The list continues with burning, wound, and stripe. The repeated pattern emphasizes proportionate accountability for injury.",
    "refs": [
      "Exodus 21:23–24"
    ]
  },
  "Exodus 21:26": {
    "title": "Injury to a servant’s eye",
    "text": "If a master destroys the eye of a male or female servant, the servant must be released as compensation. The law imposes a concrete cost on the master for a serious injury, recognizing a right to freedom in this case.",
    "refs": [
      "Exodus 21:20–21"
    ]
  },
  "Exodus 21:27": {
    "title": "Injury to a servant’s tooth",
    "text": "If a master knocks out a servant’s tooth, the servant is to be released. The rule again limits a master’s power and provides a remedy for physical injury.",
    "refs": [
      "Exodus 21:26"
    ]
  },
  "Exodus 21:28": {
    "title": "An ox that kills a person",
    "text": "If an ox gores a man or woman and the person dies, the ox is to be stoned and its meat not eaten, while the owner is not automatically put to death. The law distinguishes the animal’s danger from the owner’s level of responsibility.",
    "refs": [
      "Genesis 9:5–6"
    ]
  },
  "Exodus 21:29": {
    "title": "A known dangerous ox",
    "text": "If the ox has previously gored and the owner was warned but failed to restrain it, both the ox and the owner face consequences if a person is killed. The prior warning establishes the owner’s responsibility for knowingly allowing a danger to continue.",
    "refs": [
      "Deuteronomy 22:8"
    ]
  },
  "Exodus 21:30": {
    "title": "A ransom may be imposed",
    "text": "If a ransom is required, the owner may pay the sum imposed for the person’s life. The verse describes a legal remedy in this case and should not be generalized into a rule that every offense can be purchased away.",
    "refs": [
      "Numbers 35:31–32"
    ]
  },
  "Exodus 21:31": {
    "title": "The same rule for a son or daughter",
    "text": "If the ox kills a son or daughter, the same legal rule applies. The law does not value a child’s life less because of age or sex.",
    "refs": [
      "Exodus 21:28–30"
    ]
  },
  "Exodus 21:32": {
    "title": "An ox kills a servant",
    "text": "If the ox kills a male or female servant, the owner must pay the stated amount to the servant’s master and the ox is stoned. The law specifies compensation in the ancient social structure while still holding the dangerous animal to account.",
    "refs": [
      "Exodus 21:28"
    ]
  },
  "Exodus 21:33": {
    "title": "An uncovered pit causes injury",
    "text": "If someone opens a pit or digs one and leaves it uncovered, creating danger for an animal, the person is responsible for the loss. The law establishes responsibility for hazards a person creates on their property.",
    "refs": [
      "Deuteronomy 22:8"
    ]
  },
  "Exodus 21:34": {
    "title": "Compensation for a fallen animal",
    "text": "The owner of the pit must compensate the animal’s owner and may keep the dead animal. The provision gives a clear remedy for loss caused by negligence.",
    "refs": [
      "Exodus 21:33"
    ]
  },
  "Exodus 21:35": {
    "title": "One ox kills another",
    "text": "If one person’s ox kills another’s, the live ox is sold and the proceeds and dead animal are divided. The law shares the loss between owners when the case does not specify the heightened responsibility described in the next verse.",
    "refs": [
      "Exodus 21:36"
    ]
  },
  "Exodus 21:36": {
    "title": "A known dangerous ox",
    "text": "If the ox was known to gore and its owner failed to keep it in, the owner must repay ox for ox and keep the dead animal. Prior knowledge increases responsibility, a principle that appears throughout laws of negligence.",
    "refs": [
      "Exodus 21:29"
    ]
  },
  "Exodus 22:1": {
    "title": "Restitution for stolen livestock",
    "text": "The law sets restitution when someone steals an ox or sheep and kills or sells it. The greater repayment reflects the seriousness of theft and the loss caused to the victim.",
    "refs": [
      "2 Samuel 12:6",
      "Proverbs 6:30–31"
    ]
  },
  "Exodus 22:2": {
    "title": "A thief caught breaking in",
    "text": "The law considers a case where a thief is struck while breaking in at night and dies. The following verse distinguishes the situation after sunrise; the rules are part of ancient Israel’s legal framework for defending a home and assessing culpability.",
    "refs": [
      "Exodus 22:3"
    ]
  },
  "Exodus 22:3": {
    "title": "Restitution after sunrise",
    "text": "If the sun has risen, the defender is liable in the case described, and a thief who cannot repay is sold for the theft. The distinction reflects the legal assessment of danger and the use of restitution in that society; it should not be treated as a universal modern self-defense statute.",
    "refs": [
      "Exodus 22:2",
      "Leviticus 6:4–5"
    ]
  },
  "Exodus 22:4": {
    "title": "Restitution for recovered livestock",
    "text": "If stolen livestock is found alive in the thief’s possession, the thief must repay double. The law requires restitution even when the animal has not been killed or sold.",
    "refs": [
      "Exodus 22:1"
    ]
  },
  "Exodus 22:5": {
    "title": "Damage caused by grazing animals",
    "text": "If someone lets livestock graze in another person’s field or vineyard, restitution must come from the best of the offender’s own field or vineyard. The law holds a person responsible for allowing their animals to damage another’s property.",
    "refs": [
      "Exodus 21:33–34"
    ]
  },
  "Exodus 22:6": {
    "title": "Fire damage and negligence",
    "text": "If a fire spreads from thorns and burns another person’s grain, standing crop, or field, the person who started the fire must make restitution. The law assigns responsibility for foreseeable damage caused by fire.",
    "refs": [
      "Proverbs 6:27–29"
    ]
  },
  "Exodus 22:7": {
    "title": "Property entrusted to a neighbor",
    "text": "If money or goods are entrusted to a neighbor and stolen from the neighbor’s house, the case is to be examined. If the thief is found, restitution is required; the law protects property held in trust.",
    "refs": [
      "Leviticus 6:2–5"
    ]
  },
  "Exodus 22:8": {
    "title": "A disputed claim before the judges",
    "text": "If the thief is not found, the householder must appear before the judges to determine whether he has taken the neighbor’s property. The process requires examination rather than automatically accepting an accusation.",
    "refs": [
      "Deuteronomy 19:15–19"
    ]
  },
  "Exodus 22:9": {
    "title": "Disputes over ownership",
    "text": "In disputes involving an ox, donkey, sheep, garment, or other lost property, the case comes before the judges, and the one found guilty must pay double. The law provides a public process for settling contested claims.",
    "refs": [
      "Exodus 22:8"
    ]
  },
  "Exodus 22:10": {
    "title": "An animal entrusted to another",
    "text": "If an animal entrusted to a neighbor dies, is hurt, or is driven away without witnesses, the case is to be settled under the stated procedure. The law recognizes that not every loss proves wrongdoing and calls for a fair determination.",
    "refs": [
      "Exodus 22:11"
    ]
  },
  "Exodus 22:11": {
    "title": "An oath before the LORD",
    "text": "An oath before the LORD settles the matter between the parties when the animal’s loss cannot otherwise be explained under this law. The oath invokes God’s authority, so it is not to be used lightly or falsely.",
    "refs": [
      "Leviticus 19:12",
      "Hebrews 6:16"
    ]
  },
  "Exodus 22:12": {
    "title": "Restitution for a stolen animal",
    "text": "If the animal was stolen from the person entrusted with it, that person must make restitution to the owner. The rule distinguishes theft from a loss for which the caretaker was not shown to be responsible.",
    "refs": [
      "Exodus 22:10–11"
    ]
  },
  "Exodus 22:13": {
    "title": "Evidence of an animal torn by beasts",
    "text": "If the animal was torn by beasts, the caretaker is to bring evidence and is not required to repay the torn animal. The rule requires evidence and distinguishes unavoidable loss from theft.",
    "refs": [
      "Genesis 31:39"
    ]
  },
  "Exodus 22:14": {
    "title": "Borrowed property is damaged",
    "text": "If a person borrows an animal or item and it is injured or dies while the owner is absent, the borrower must make restitution. The next verse distinguishes a hired animal, for which payment terms differ.",
    "refs": [
      "Exodus 22:15"
    ]
  },
  "Exodus 22:15": {
    "title": "A hired animal and agreed payment",
    "text": "If the owner is present, or the animal was hired, the law sets different responsibility according to the arrangement. The principle is that agreements and circumstances matter when determining liability.",
    "refs": [
      "Leviticus 19:13"
    ]
  },
  "Exodus 22:16": {
    "title": "Seduction and marriage obligations",
    "text": "If a man seduces an unmarried virgin and lies with her, he must pay the bride-price and take her as wife, subject to the father’s decision in the next verse. This is an ancient legal provision concerning marriage and family obligations; it should be read with its following limitation and not mistaken for a modern legal framework.",
    "refs": [
      "Deuteronomy 22:28–29"
    ]
  },
  "Exodus 22:17": {
    "title": "The father may refuse the marriage",
    "text": "If the father refuses to give her in marriage, the man must still pay the money equivalent to the bride-price. The law ensures the man cannot avoid the financial responsibility stated in the previous verse simply because the marriage does not occur.",
    "refs": [
      "Exodus 22:16"
    ]
  },
  "Exodus 22:18": {
    "title": "A prohibition of sorcery",
    "text": "The law prohibits a sorceress from being allowed to live under Israel’s covenant legal system. The verse reflects the ancient law’s severe treatment of sorcery; it is not a direction for private individuals to harm others, and its civil penalty belongs to that historical covenant code.",
    "refs": [
      "Leviticus 20:27",
      "Deuteronomy 18:10–12"
    ]
  },
  "Exodus 22:19": {
    "title": "Sexual relations with an animal",
    "text": "The law prescribes death for a person who lies with an animal. The prohibition marks this act as incompatible with Israel’s covenant standards for sexual conduct.",
    "refs": [
      "Leviticus 18:23"
    ]
  },
  "Exodus 22:20": {
    "title": "Idolatrous sacrifice forbidden",
    "text": "The law condemns sacrificing to any god other than the LORD. Israel is called to exclusive worship of the one God who brought them out of Egypt.",
    "refs": [
      "Exodus 20:3",
      "Deuteronomy 6:4–5"
    ]
  },
  "Exodus 22:21": {
    "title": "Do not oppress the stranger",
    "text": "Israel must not wrong or oppress a stranger, remembering that they themselves were strangers in Egypt. Their experience of bondage is meant to cultivate justice and compassion toward vulnerable outsiders.",
    "refs": [
      "Leviticus 19:33–34",
      "Deuteronomy 10:18–19"
    ]
  },
  "Exodus 22:22": {
    "title": "Do not afflict widows or orphans",
    "text": "God forbids mistreating widows and fatherless children. The law gives special attention to people who may lack the social protection of a household head.",
    "refs": [
      "Deuteronomy 24:17",
      "James 1:27"
    ]
  },
  "Exodus 22:23": {
    "title": "God hears the cry of the vulnerable",
    "text": "If Israel afflicts widows or orphans and they cry to God, He says He will surely hear them. The warning shows that religious identity does not shield the oppressor from God’s judgment.",
    "refs": [
      "Psalm 10:17–18",
      "Isaiah 1:17"
    ]
  },
  "Exodus 22:24": {
    "title": "Judgment for oppression",
    "text": "God warns that His anger will be kindled and that the oppressors’ own families will suffer the consequences of war and loss. The severe warning underscores the seriousness of exploiting vulnerable people.",
    "refs": [
      "Deuteronomy 27:19"
    ]
  },
  "Exodus 22:25": {
    "title": "Do not exploit the poor through interest",
    "text": "If someone lends to a poor person among Israel, the lender must not act as a harsh creditor or charge interest under the stated rule. The law restrains profiting from another Israelite’s desperation.",
    "refs": [
      "Leviticus 25:35–37",
      "Deuteronomy 23:19–20"
    ]
  },
  "Exodus 22:26": {
    "title": "Return a pledged garment by sunset",
    "text": "If a neighbor’s garment is taken as a pledge, it must be returned before sunset because it is the person’s covering and warmth. The law places human need above retaining collateral overnight.",
    "refs": [
      "Deuteronomy 24:12–13"
    ]
  },
  "Exodus 22:27": {
    "title": "God hears the poor person",
    "text": "God says that when the poor person cries to Him, He will hear, because He is gracious. The verse grounds compassion in God’s own character and warns against treating poverty as permission to mistreat someone.",
    "refs": [
      "Exodus 34:6",
      "Psalm 86:15"
    ]
  },
  "Exodus 22:28": {
    "title": "Do not revile God or rulers",
    "text": "The law forbids reviling God and cursing the ruler of the people. It calls for respect in covenant and public life; it does not mean every ruler is morally right or beyond accountability before God.",
    "refs": [
      "Acts 23:5",
      "Romans 13:1–7"
    ]
  },
  "Exodus 22:29": {
    "title": "Offerings and firstborn",
    "text": "Israel must not delay the offerings from its harvest and produce and must give the firstborn sons to God according to His instruction. The command places worship and gratitude at the center of the community’s life.",
    "refs": [
      "Exodus 13:2",
      "Proverbs 3:9"
    ]
  },
  "Exodus 22:30": {
    "title": "Firstborn livestock on the eighth day",
    "text": "The firstborn of oxen and sheep are to remain with the mother for seven days and be given on the eighth day. The timing is part of the prescribed offering practice.",
    "refs": [
      "Leviticus 22:27"
    ]
  },
  "Exodus 22:31": {
    "title": "A holy people and clean food practices",
    "text": "Israel is called to be holy to the LORD and is instructed not to eat flesh torn by beasts but to cast it to the dogs. The command belongs to Israel’s covenant holiness and food regulations, emphasizing distinction in ordinary life as well as worship.",
    "refs": [
      "Leviticus 11:44–45",
      "Deuteronomy 14:21"
    ]
  },
  "Exodus 23:1": {
    "title": "Do not spread a false report",
    "text": "Israel must not spread a false report or join the wicked in giving malicious testimony. The command protects truth and justice in the community.",
    "refs": [
      "Exodus 20:16",
      "Leviticus 19:16"
    ]
  },
  "Exodus 23:2": {
    "title": "Do not follow a crowd into evil",
    "text": "The people must not follow a multitude to do evil or distort justice because many people are doing so. Truth and right judgment must not be surrendered to group pressure.",
    "refs": [
      "Deuteronomy 16:19",
      "Proverbs 1:10"
    ]
  },
  "Exodus 23:3": {
    "title": "Do not favor the poor unjustly",
    "text": "The law says not to favor a poor person in a lawsuit merely because of poverty. Justice requires impartiality: compassion for the vulnerable must not become dishonest judgment.",
    "refs": [
      "Leviticus 19:15",
      "James 2:1–9"
    ]
  },
  "Exodus 23:4": {
    "title": "Return an enemy’s wandering animal",
    "text": "If an Israelite finds an enemy’s ox or donkey wandering, the animal must be returned. The law requires practical good even toward an adversary.",
    "refs": [
      "Deuteronomy 22:1–4",
      "Matthew 5:44"
    ]
  },
  "Exodus 23:5": {
    "title": "Help an enemy’s burdened animal",
    "text": "If an enemy’s donkey has fallen under its burden, the Israelite must help it rather than ignore the situation. The command teaches that justice and mercy can require action even when relationships are hostile.",
    "refs": [
      "Deuteronomy 22:4",
      "Proverbs 25:21"
    ]
  },
  "Exodus 23:6": {
    "title": "Do not pervert justice for the poor",
    "text": "The people must not deny justice to a poor person in a lawsuit. The verse balances the earlier warning against favoritism by requiring a fair judgment regardless of wealth or poverty.",
    "refs": [
      "Exodus 23:3",
      "Leviticus 19:15"
    ]
  },
  "Exodus 23:7": {
    "title": "Keep away from false accusation",
    "text": "Israel must keep far from a false matter and must not condemn the innocent or righteous. God declares that He will not justify the wicked; judicial decisions must not knowingly punish the innocent.",
    "refs": [
      "Proverbs 17:15",
      "Deuteronomy 25:1"
    ]
  },
  "Exodus 23:8": {
    "title": "Do not take a bribe",
    "text": "A bribe blinds those who see clearly and twists the words of the righteous. The command condemns corruption because money can distort judgment and deprive people of justice.",
    "refs": [
      "Deuteronomy 16:19",
      "Proverbs 17:23"
    ]
  },
  "Exodus 23:9": {
    "title": "Remember the stranger’s experience",
    "text": "Israel must not oppress a stranger because they know the heart of a stranger, having been strangers in Egypt. Their own history of suffering is to make them more just and compassionate, not more oppressive.",
    "refs": [
      "Exodus 22:21",
      "Leviticus 19:33–34"
    ]
  },
  "Exodus 23:10": {
    "title": "Six years of sowing",
    "text": "Israel may sow and gather produce for six years. The law now applies a pattern of work and rest to the land itself.",
    "refs": [
      "Leviticus 25:3–4"
    ]
  },
  "Exodus 23:11": {
    "title": "The land rests in the seventh year",
    "text": "In the seventh year the land is to rest and lie fallow, so the poor may eat from it and what remains may feed the beasts. The practice limits ordinary exploitation of the land and provides for vulnerable people and animals.",
    "refs": [
      "Leviticus 25:4–7",
      "Deuteronomy 15:1–2"
    ]
  },
  "Exodus 23:12": {
    "title": "Sabbath rest for people and animals",
    "text": "The people are to work six days and rest on the seventh, so their ox and donkey may rest and the son of the servant and the stranger may be refreshed. Sabbath rest is presented as a benefit extending to those with the least power.",
    "refs": [
      "Exodus 20:8–11",
      "Deuteronomy 5:14"
    ]
  },
  "Exodus 23:13": {
    "title": "Do not invoke other gods",
    "text": "Israel must be careful to do all God has said and not even make the names of other gods part of their worship. The command guards the community against idolatry and the practices associated with it.",
    "refs": [
      "Joshua 23:7",
      "Psalm 16:4"
    ]
  },
  "Exodus 23:14": {
    "title": "Three annual feasts",
    "text": "Israel is commanded to keep three annual feasts to the LORD. The feasts gather the people around remembrance, worship, and gratitude for God’s provision.",
    "refs": [
      "Deuteronomy 16:16"
    ]
  },
  "Exodus 23:15": {
    "title": "The Feast of Unleavened Bread",
    "text": "Israel must keep the Feast of Unleavened Bread at the appointed time in Abib, remembering that they came out of Egypt. No one is to appear before the LORD empty-handed; worship is linked to remembering deliverance and bringing offerings.",
    "refs": [
      "Exodus 12:14–20",
      "Deuteronomy 16:1–3"
    ]
  },
  "Exodus 23:16": {
    "title": "Harvest and ingathering feasts",
    "text": "Israel is to keep the Feast of Harvest with the firstfruits of labor and the Feast of Ingathering at the end of the year. These observances express gratitude for God’s provision through the agricultural seasons.",
    "refs": [
      "Leviticus 23:15–22",
      "Leviticus 23:33–43"
    ]
  },
  "Exodus 23:17": {
    "title": "Appear before the LORD three times",
    "text": "All the males are to appear before the Lord GOD at the three annual feasts. The command emphasizes communal worship and the centrality of the LORD in Israel’s calendar.",
    "refs": [
      "Deuteronomy 16:16"
    ]
  },
  "Exodus 23:18": {
    "title": "Offerings handled as commanded",
    "text": "The blood of God’s sacrifice is not to be offered with leavened bread, and the fat of the feast is not to remain until morning. The instructions preserve the distinct requirements of Israel’s sacrificial worship.",
    "refs": [
      "Exodus 12:8–10",
      "Leviticus 7:15"
    ]
  },
  "Exodus 23:19": {
    "title": "Bring the firstfruits to God",
    "text": "The first of the firstfruits of the land is to be brought to the house of the LORD. The prohibition against boiling a kid in its mother’s milk is also stated; the precise rationale is not explained here, so interpretation should not be claimed as certain.",
    "refs": [
      "Deuteronomy 26:1–11",
      "Proverbs 3:9"
    ]
  },
  "Exodus 23:20": {
    "title": "An angel goes before Israel",
    "text": "God promises to send an angel before Israel to guard them on the way and bring them to the prepared place. The angel is God’s messenger and agent; the verse itself does not require the conclusion that the messenger is a separate divine person.",
    "refs": [
      "Exodus 14:19",
      "Exodus 32:34"
    ]
  },
  "Exodus 23:21": {
    "title": "Hear the messenger’s voice",
    "text": "Israel must beware of the messenger and obey his voice, because God’s name is in him and he will not pardon rebellion. The passage describes a messenger bearing God’s authority; it should be interpreted within its context rather than using one phrase alone to settle every question about divine identity.",
    "refs": [
      "Exodus 23:20",
      "Exodus 32:34–35"
    ]
  },
  "Exodus 23:22": {
    "title": "God will oppose Israel’s enemies",
    "text": "If Israel obeys the messenger and does all God speaks, God will be an enemy to Israel’s enemies and an adversary to their adversaries. The promise is covenantal and tied to Israel’s obedience under the guidance God provides.",
    "refs": [
      "Deuteronomy 28:1–7"
    ]
  },
  "Exodus 23:23": {
    "title": "The messenger leads into the land",
    "text": "The messenger will go before Israel to bring them to the peoples of Canaan, whom God will cut off. The verse anticipates the conquest and the specific judgment described in the covenant narrative.",
    "refs": [
      "Deuteronomy 7:1–5"
    ]
  },
  "Exodus 23:24": {
    "title": "Reject Canaanite worship",
    "text": "Israel must not bow to the nations’ gods or imitate their practices, but must overthrow their idols. The command protects Israel’s exclusive worship of the LORD and warns against absorbing the religious customs of the land.",
    "refs": [
      "Deuteronomy 12:2–4"
    ]
  },
  "Exodus 23:25": {
    "title": "Serve the LORD and receive provision",
    "text": "Israel is to serve the LORD, who promises blessing on their bread and water and removal of sickness. These are covenant promises to Israel in this setting; they should not be turned into a guarantee that every faithful person today will always be free from illness.",
    "refs": [
      "Deuteronomy 7:12–15"
    ]
  },
  "Exodus 23:26": {
    "title": "Life and fruitfulness in the land",
    "text": "God promises that there will be no miscarriage or barrenness in the land and that Israel’s days will be fulfilled. The statement describes the covenant blessing associated with Israel’s life in the promised land.",
    "refs": [
      "Deuteronomy 7:14"
    ]
  },
  "Exodus 23:27": {
    "title": "God sends fear before Israel",
    "text": "God promises to send His fear before Israel and confuse the peoples they encounter. The language describes God’s intervention as Israel enters the land, not a general command for believers to frighten others.",
    "refs": [
      "Deuteronomy 2:25",
      "Joshua 2:9–11"
    ]
  },
  "Exodus 23:28": {
    "title": "Hornets before Israel",
    "text": "God says He will send hornets before Israel to drive out certain peoples. The text presents this as part of God’s promised assistance; interpretations of whether the expression is literal or figurative vary.",
    "refs": [
      "Deuteronomy 7:20",
      "Joshua 24:12"
    ]
  },
  "Exodus 23:29": {
    "title": "The nations are not removed all at once",
    "text": "God says He will not drive the nations out in one year, lest the land become desolate and wild animals multiply. The gradual process is explained as practical care for the land and the people who will inhabit it.",
    "refs": [
      "Deuteronomy 7:22"
    ]
  },
  "Exodus 23:30": {
    "title": "Israel grows into the land",
    "text": "God will drive out the nations little by little until Israel increases and possesses the land. The promise describes a gradual process rather than an instant change.",
    "refs": [
      "Joshua 13:1"
    ]
  },
  "Exodus 23:31": {
    "title": "Borders of the promised land",
    "text": "God describes Israel’s borders from the Red Sea toward the sea of the Philistines and from the wilderness to the river, and promises to deliver the inhabitants into Israel’s hand. The borders express the land promise in the covenant; later biblical history records the complex process of settlement.",
    "refs": [
      "Genesis 15:18",
      "Deuteronomy 11:24"
    ]
  },
  "Exodus 23:32": {
    "title": "No covenant with the nations’ gods",
    "text": "Israel must make no covenant with the peoples or their gods. The command warns against political or religious agreements that would compromise Israel’s covenant loyalty to the LORD.",
    "refs": [
      "Deuteronomy 7:2–4"
    ]
  },
  "Exodus 23:33": {
    "title": "Do not let idolatry become a snare",
    "text": "The nations must not dwell in a way that leads Israel to sin against God, because serving their gods would become a snare. The warning identifies idolatry as a spiritual and communal danger within Israel’s covenant life.",
    "refs": [
      "Judges 2:1–3",
      "Psalm 106:34–39"
    ]
  },
  "Exodus 24:1": {
    "title": "Moses, Aaron, and the elders called up",
    "text": "God tells Moses to come up with Aaron, Nadab, Abihu, and seventy elders, while they worship from a distance. The approach is structured by God’s instruction, with Moses having a distinct role in drawing nearer.",
    "refs": [
      "Exodus 19:24"
    ]
  },
  "Exodus 24:2": {
    "title": "Moses alone draws near",
    "text": "Moses alone is to come near the LORD, while the others and the people remain at a distance. The arrangement distinguishes Moses’ mediating role in the covenant ceremony without suggesting that he is divine.",
    "refs": [
      "Deuteronomy 5:5"
    ]
  },
  "Exodus 24:3": {
    "title": "The people accept the words",
    "text": "Moses tells the people the LORD’s words and judgments, and they answer that they will do them. Their response echoes the earlier covenant commitment and prepares for the formal ceremony.",
    "refs": [
      "Exodus 19:8"
    ]
  },
  "Exodus 24:4": {
    "title": "Moses writes God’s words",
    "text": "Moses writes the words of the LORD and builds an altar with twelve pillars for Israel’s twelve tribes. The written record and twelve pillars mark the covenant as a public act involving the whole nation.",
    "refs": [
      "Exodus 20:1–17",
      "Joshua 4:4–7"
    ]
  },
  "Exodus 24:5": {
    "title": "Young men offer sacrifices",
    "text": "Young men of Israel offer burnt offerings and peace offerings of oxen to the LORD. The sacrifices accompany the covenant ceremony and express worship and fellowship.",
    "refs": [
      "Exodus 20:24"
    ]
  },
  "Exodus 24:6": {
    "title": "Blood is divided",
    "text": "Moses puts half the blood in basins and sprinkles the other half on the altar. The blood is central to the covenant ceremony, signifying the solemnity of the agreement before God.",
    "refs": [
      "Hebrews 9:18–22"
    ]
  },
  "Exodus 24:7": {
    "title": "The book of the covenant is read",
    "text": "Moses reads the book of the covenant to the people, who again promise to obey all that the LORD has said. The reading makes the terms public before the covenant is confirmed with blood.",
    "refs": [
      "Deuteronomy 31:9–13"
    ]
  },
  "Exodus 24:8": {
    "title": "The blood of the covenant",
    "text": "Moses sprinkles the blood on the people and declares it the blood of the covenant the LORD has made with them according to His words. The New Testament later uses covenant-blood language in explaining Jesus’ death, but the immediate event is the covenant at Sinai.",
    "refs": [
      "Matthew 26:28",
      "Hebrews 9:19–22"
    ]
  },
  "Exodus 24:9": {
    "title": "The leaders ascend the mountain",
    "text": "Moses, Aaron, Nadab, Abihu, and seventy elders go up. The group’s ascent follows the covenant ceremony and leads into the description of their encounter with God.",
    "refs": [
      "Exodus 24:1–2"
    ]
  },
  "Exodus 24:10": {
    "title": "They see the God of Israel",
    "text": "The leaders see a manifestation described as beneath His feet, like a pavement of sapphire stone, clear as heaven. The passage describes a remarkable vision of God’s glory; it does not give a complete physical description of God or imply that the infinite Spirit is confined to a body.",
    "refs": [
      "Ezekiel 1:26–28",
      "John 1:18"
    ]
  },
  "Exodus 24:11": {
    "title": "God does not lay His hand on the leaders",
    "text": "God does not harm the nobles of Israel; they behold God and eat and drink. The text emphasizes their preservation during an extraordinary encounter and their fellowship in the covenant meal.",
    "refs": [
      "Genesis 32:30"
    ]
  },
  "Exodus 24:12": {
    "title": "Stone tablets for instruction",
    "text": "The LORD calls Moses up the mountain to receive stone tablets containing the law and commandments written for Israel’s instruction. The tablets signify the covenant words are given by God, not invented by Moses.",
    "refs": [
      "Exodus 31:18",
      "Deuteronomy 9:9–11"
    ]
  },
  "Exodus 24:13": {
    "title": "Joshua accompanies Moses",
    "text": "Moses rises with Joshua, his servant, and goes up the mountain of God. Joshua’s presence anticipates his later leadership and shows his close service to Moses.",
    "refs": [
      "Exodus 17:9–14",
      "Joshua 1:1–2"
    ]
  },
  "Exodus 24:14": {
    "title": "The elders remain and wait",
    "text": "Moses tells the elders to wait for them and says Aaron and Hur are available to judge disputes. Even during Moses’ absence, arrangements are made for the people’s practical needs.",
    "refs": [
      "Exodus 18:21–26"
    ]
  },
  "Exodus 24:15": {
    "title": "The cloud covers the mountain",
    "text": "Moses goes up, and the cloud covers the mountain. The cloud continues the biblical imagery of God’s manifest presence at Sinai.",
    "refs": [
      "Exodus 19:9",
      "Exodus 19:18"
    ]
  },
  "Exodus 24:16": {
    "title": "The glory rests on Sinai",
    "text": "The glory of the LORD rests on the mountain for six days, and on the seventh day God calls to Moses from the cloud. The timing links the encounter with a period of waiting before Moses receives the next instruction.",
    "refs": [
      "Exodus 40:34–35"
    ]
  },
  "Exodus 24:17": {
    "title": "The glory appears like a consuming fire",
    "text": "To the Israelites below, the glory of the LORD looks like a consuming fire on the mountain’s top. The description conveys awe and holiness through visible imagery.",
    "refs": [
      "Deuteronomy 4:24",
      "Hebrews 12:29"
    ]
  },
  "Exodus 24:18": {
    "title": "Moses remains forty days and nights",
    "text": "Moses enters the cloud and remains on the mountain forty days and nights. The extended period prepares for the instructions about the tabernacle and the covenant worship of Israel.",
    "refs": [
      "Exodus 34:28",
      "Deuteronomy 9:9"
    ]
  },
  "Exodus 25:1": {
    "title": "An offering for the sanctuary",
    "text": "The LORD tells Moses to receive an offering from those whose hearts move them to give. The materials will be used to build the sanctuary, and the voluntary language emphasizes willing participation in the work of worship.",
    "refs": [
      "Exodus 35:4–9"
    ]
  },
  "Exodus 25:2": {
    "title": "Give from a willing heart",
    "text": "The people are asked to give willingly from the heart. The passage presents generosity as a response to God’s purpose rather than merely a forced contribution.",
    "refs": [
      "2 Corinthians 9:7"
    ]
  },
  "Exodus 25:3": {
    "title": "Materials for the tabernacle",
    "text": "Gold, silver, brass, and other materials are listed for the sanctuary. The variety of materials shows that the worship space will be carefully prepared according to God’s instructions.",
    "refs": [
      "Exodus 35:5–9"
    ]
  },
  "Exodus 25:4": {
    "title": "Blue, purple, scarlet, and fine linen",
    "text": "Colored yarns and fine linen are included among the materials. The text specifies the actual resources needed for the curtains and sacred furnishings that follow.",
    "refs": [
      "Exodus 26:1"
    ]
  },
  "Exodus 25:5": {
    "title": "Skins, wood, and oil",
    "text": "Ram skins, other durable skins, acacia wood, and oil are listed. These materials serve practical purposes in the tabernacle’s structure, covering, and lighting.",
    "refs": [
      "Exodus 26:14",
      "Exodus 27:20"
    ]
  },
  "Exodus 25:6": {
    "title": "Spices and stones",
    "text": "Oil, incense spices, and precious stones are requested for the sanctuary and priestly garments. The materials show that both worship and priestly service require careful preparation.",
    "refs": [
      "Exodus 30:23–25",
      "Exodus 28:9–12"
    ]
  },
  "Exodus 25:7": {
    "title": "Stones for the priestly garments",
    "text": "Onyx and other stones are requested for the ephod and breastplate. These stones will be associated with the names of Israel’s tribes, representing the people in priestly service.",
    "refs": [
      "Exodus 28:9–21"
    ]
  },
  "Exodus 25:8": {
    "title": "Make a sanctuary for God",
    "text": "God commands Israel to make Him a sanctuary so He may dwell among them. This does not mean the omnipresent God is contained by a building; the sanctuary is the appointed place of His covenant presence among Israel.",
    "refs": [
      "1 Kings 8:27",
      "Acts 7:48–50"
    ]
  },
  "Exodus 25:9": {
    "title": "Follow the pattern shown",
    "text": "The tabernacle and its furnishings must be made according to the pattern God shows Moses. The details are governed by divine instruction rather than human invention.",
    "refs": [
      "Exodus 25:40",
      "Hebrews 8:5"
    ]
  },
  "Exodus 25:10": {
    "title": "The ark of acacia wood",
    "text": "God gives dimensions for an ark made of acacia wood. It will be a central object in the Most Holy Place and associated with the covenant testimony.",
    "refs": [
      "Exodus 26:33–34"
    ]
  },
  "Exodus 25:11": {
    "title": "Gold covers the ark",
    "text": "The ark is to be overlaid with pure gold inside and outside, with a gold crown around it. The precious covering reflects the sacred role assigned to the ark in Israel’s worship.",
    "refs": [
      "Exodus 37:1–2"
    ]
  },
  "Exodus 25:12": {
    "title": "Four rings for carrying",
    "text": "Four gold rings are to be cast for the ark’s four feet. The rings allow it to be carried according to the instructions that follow, rather than handled casually.",
    "refs": [
      "Exodus 25:13–15"
    ]
  },
  "Exodus 25:13": {
    "title": "Staves made of acacia wood",
    "text": "Staves are made and overlaid with gold to carry the ark. The instructions provide a way to transport the sacred object while maintaining its prescribed handling.",
    "refs": [
      "Numbers 4:15"
    ]
  },
  "Exodus 25:14": {
    "title": "The staves go through the rings",
    "text": "The staves are inserted through the rings at the sides of the ark. The carrying arrangement is part of the exact pattern God has given.",
    "refs": [
      "Exodus 25:12–13"
    ]
  },
  "Exodus 25:15": {
    "title": "The staves remain in the rings",
    "text": "The staves are not to be removed from the rings of the ark. The instruction preserves the prescribed means of carrying it whenever it must be moved.",
    "refs": [
      "1 Kings 8:8"
    ]
  },
  "Exodus 25:16": {
    "title": "The testimony placed in the ark",
    "text": "Moses is to put the testimony that God will give him into the ark. The ark’s purpose is closely tied to God’s covenant words, not to an image of God.",
    "refs": [
      "Exodus 31:18",
      "Deuteronomy 10:1–5"
    ]
  },
  "Exodus 25:17": {
    "title": "The mercy seat",
    "text": "A mercy seat of pure gold is to be made for the ark. It will be the appointed place associated with atonement and God’s meeting with Israel, as the following verses explain.",
    "refs": [
      "Leviticus 16:14–16",
      "Hebrews 9:5"
    ]
  },
  "Exodus 25:18": {
    "title": "Two cherubim of gold",
    "text": "Two cherubim are to be made of hammered gold at the ends of the mercy seat. They are part of the sanctuary’s symbolic design and are not presented as objects for Israel to worship.",
    "refs": [
      "Exodus 25:20"
    ]
  },
  "Exodus 25:19": {
    "title": "The cherubim are one piece with the mercy seat",
    "text": "The cherubim are made from the ends of the mercy seat. The detailed construction follows the pattern God has given Moses.",
    "refs": [
      "Exodus 37:7–8"
    ]
  },
  "Exodus 25:20": {
    "title": "The cherubim face the mercy seat",
    "text": "The cherubim spread their wings above and face one another, looking toward the mercy seat. Their posture frames the place where God will speak with Moses.",
    "refs": [
      "Exodus 25:22"
    ]
  },
  "Exodus 25:21": {
    "title": "The testimony is placed inside",
    "text": "The mercy seat is set on the ark, and the testimony is placed inside. The covenant word is central, with the mercy seat above it as the appointed place of meeting.",
    "refs": [
      "Exodus 25:16–17"
    ]
  },
  "Exodus 25:22": {
    "title": "God meets Moses above the mercy seat",
    "text": "God says He will meet Moses there and speak from above the mercy seat, between the cherubim, concerning His commands for Israel. This is a chosen place of revelation; it does not imply that God’s whole being is confined to the ark or sanctuary.",
    "refs": [
      "Numbers 7:89",
      "Leviticus 16:2"
    ]
  },
  "Exodus 25:23": {
    "title": "A table of acacia wood",
    "text": "God gives dimensions for a table of acacia wood. It will hold the bread set before the LORD and be part of the sanctuary’s regular worship.",
    "refs": [
      "Exodus 37:10"
    ]
  },
  "Exodus 25:24": {
    "title": "The table is overlaid with gold",
    "text": "The table is to be overlaid with pure gold and have a gold border. Its materials and design follow the instructions for the sanctuary furnishings.",
    "refs": [
      "Exodus 37:11"
    ]
  },
  "Exodus 25:25": {
    "title": "A border and gold rim",
    "text": "A handbreadth border and gold rim are added around the table. The detail describes the table’s construction and the care given to the sacred furnishings.",
    "refs": [
      "Exodus 37:12"
    ]
  },
  "Exodus 25:26": {
    "title": "Four gold rings for the table",
    "text": "Four gold rings are made for the table’s four corners. These rings will hold the staves used to carry it.",
    "refs": [
      "Exodus 25:27"
    ]
  },
  "Exodus 25:27": {
    "title": "Rings near the border",
    "text": "The rings are placed near the border as holders for the staves. The carrying method is integrated into the table’s design.",
    "refs": [
      "Exodus 25:26–28"
    ]
  },
  "Exodus 25:28": {
    "title": "Staves to carry the table",
    "text": "The staves are made of acacia wood and overlaid with gold so the table can be carried. The instructions maintain the pattern for transport of the sanctuary furnishings.",
    "refs": [
      "Numbers 4:7–8"
    ]
  },
  "Exodus 25:29": {
    "title": "Dishes, spoons, and bowls",
    "text": "The table’s dishes, spoons, covers, and bowls are to be made of pure gold for the offerings associated with it. The utensils are included in the sacred service rather than treated as ordinary household items.",
    "refs": [
      "Exodus 37:16"
    ]
  },
  "Exodus 25:30": {
    "title": "Bread continually before the LORD",
    "text": "The showbread is to be set on the table continually before God. The bread represents an ongoing offering and remembrance of Israel’s dependence on the LORD for provision.",
    "refs": [
      "Leviticus 24:5–9"
    ]
  },
  "Exodus 25:31": {
    "title": "A lampstand of pure gold",
    "text": "The lampstand is to be made of hammered pure gold, including its shaft, branches, bowls, knops, and flowers. The design is given in detail and will provide light within the sanctuary.",
    "refs": [
      "Exodus 37:17–18"
    ]
  },
  "Exodus 25:32": {
    "title": "Six branches from the lampstand",
    "text": "Six branches extend from the sides of the central shaft, three on each side. The arrangement is part of the specified form of the lampstand.",
    "refs": [
      "Exodus 25:33–36"
    ]
  },
  "Exodus 25:33": {
    "title": "Decorative cups on the branches",
    "text": "Each branch has cups shaped like almond blossoms, with knops and flowers. The repeated design makes the branches visually unified with the central shaft.",
    "refs": [
      "Exodus 25:31"
    ]
  },
  "Exodus 25:34": {
    "title": "Almond-shaped decorations on the shaft",
    "text": "The central shaft also has almond-shaped cups, knops, and flowers. The lampstand’s design is carefully coordinated rather than assembled from unrelated parts.",
    "refs": [
      "Exodus 25:31–33"
    ]
  },
  "Exodus 25:35": {
    "title": "Knops beneath the branches",
    "text": "A knop is placed beneath each pair of branches extending from the central shaft. The verse continues the detailed pattern for the lampstand’s construction.",
    "refs": [
      "Exodus 25:32"
    ]
  },
  "Exodus 25:36": {
    "title": "The lampstand is one work",
    "text": "The knops and branches are made as one piece of pure hammered gold. The unity of the structure is part of the instruction given to Moses.",
    "refs": [
      "Exodus 37:22"
    ]
  },
  "Exodus 25:37": {
    "title": "Seven lamps give light",
    "text": "Seven lamps are to be made and arranged to give light in front of the lampstand. The lamps serve the sanctuary’s practical lighting and worship function.",
    "refs": [
      "Exodus 27:20–21"
    ]
  },
  "Exodus 25:38": {
    "title": "Tongs and snuff dishes",
    "text": "The tongs and snuff dishes are also made of pure gold. Even the tools for maintaining the lamps are included in the sanctuary’s prescribed furnishings.",
    "refs": [
      "Exodus 37:23"
    ]
  },
  "Exodus 25:39": {
    "title": "A talent of pure gold",
    "text": "The lampstand and its utensils are to be made from a talent of pure gold. The specified quantity underlines the material and workmanship required.",
    "refs": [
      "Exodus 37:24"
    ]
  },
  "Exodus 25:40": {
    "title": "Make it according to the pattern",
    "text": "Moses is warned to make everything according to the pattern shown on the mountain. The verse emphasizes obedience to God’s revealed design, and Hebrews later uses the tabernacle pattern in discussing earthly worship and heavenly realities.",
    "refs": [
      "Exodus 25:9",
      "Hebrews 8:5"
    ]
  },
  "Exodus 26:1": {
    "title": "Ten curtains for the tabernacle",
    "text": "The tabernacle curtains are made from fine linen with blue, purple, and scarlet yarn and cherubim woven into them. The detailed design marks the sanctuary as a specially appointed place of worship.",
    "refs": [
      "Exodus 25:4"
    ]
  },
  "Exodus 26:2": {
    "title": "Curtain dimensions",
    "text": "The length and width of each curtain are specified. Exact dimensions ensure that the pieces fit together as one covering for the tabernacle.",
    "refs": [
      "Exodus 26:1"
    ]
  },
  "Exodus 26:3": {
    "title": "Curtains joined in sets",
    "text": "Five curtains are joined to one another in each of two sets. The structure is built from connected sections that form a complete covering.",
    "refs": [
      "Exodus 26:1–2"
    ]
  },
  "Exodus 26:4": {
    "title": "Loops of blue on the curtains",
    "text": "Loops of blue are made along the edge of each set so the curtains can be joined. The detail prepares for the clasps that connect the sections.",
    "refs": [
      "Exodus 26:5–6"
    ]
  },
  "Exodus 26:5": {
    "title": "Fifty loops on each set",
    "text": "The loops are placed opposite one another, fifty on each curtain set. The matching arrangement allows the sections to be fastened together evenly.",
    "refs": [
      "Exodus 26:4"
    ]
  },
  "Exodus 26:6": {
    "title": "Gold clasps join the curtains",
    "text": "Fifty gold clasps connect the loops so the tabernacle becomes one whole. The repeated image of joining sections into one structure reflects the practical unity of the sanctuary.",
    "refs": [
      "Exodus 36:13"
    ]
  },
  "Exodus 26:7": {
    "title": "Curtains of goats’ hair",
    "text": "Eleven curtains of goats’ hair are made for a tent over the tabernacle. This second covering adds protection above the fine inner curtains.",
    "refs": [
      "Exodus 26:14"
    ]
  },
  "Exodus 26:8": {
    "title": "Dimensions of the goats’ hair curtains",
    "text": "The dimensions of the goats’ hair curtains are specified. Their measurements are coordinated with the inner covering and the structure they will protect.",
    "refs": [
      "Exodus 26:7"
    ]
  },
  "Exodus 26:9": {
    "title": "Join the curtains into two sets",
    "text": "Six curtains are joined in one set and five in another, with the sixth folded at the front. The arrangement provides the required shape and coverage for the tent.",
    "refs": [
      "Exodus 26:7–8"
    ]
  },
  "Exodus 26:10": {
    "title": "Loops along the curtain edges",
    "text": "Fifty loops are made along the edge of the curtain set, with another fifty on the joining edge. The loops prepare the coverings to be connected by clasps.",
    "refs": [
      "Exodus 26:11"
    ]
  },
  "Exodus 26:11": {
    "title": "Bronze clasps connect the covering",
    "text": "Fifty bronze clasps are made and put through the loops to join the tent covering into one. The outer covering is connected securely according to the prescribed design.",
    "refs": [
      "Exodus 26:10"
    ]
  },
  "Exodus 26:12": {
    "title": "The extra curtain hangs at the back",
    "text": "The surplus portion of the tent curtains hangs over the rear of the tabernacle. The instruction accounts for the extra length so the covering protects the structure.",
    "refs": [
      "Exodus 26:9"
    ]
  },
  "Exodus 26:13": {
    "title": "The covering extends over the sides",
    "text": "The extra length hangs over both sides of the tabernacle to cover it. The covering’s dimensions are designed to protect the sanctuary’s sides.",
    "refs": [
      "Exodus 26:12"
    ]
  },
  "Exodus 26:14": {
    "title": "Two additional coverings",
    "text": "A covering of ram skins dyed red and another covering of durable skins are made over the tent. These outer layers protect the tabernacle from the elements.",
    "refs": [
      "Exodus 25:5"
    ]
  },
  "Exodus 26:15": {
    "title": "Boards for the tabernacle",
    "text": "The boards are made of acacia wood and stand upright. They form the structural framework that supports the curtains and coverings.",
    "refs": [
      "Exodus 26:18–25"
    ]
  },
  "Exodus 26:16": {
    "title": "The boards’ dimensions",
    "text": "Each board has a specified length and width. The measurements ensure a consistent framework for the tabernacle.",
    "refs": [
      "Exodus 26:15"
    ]
  },
  "Exodus 26:17": {
    "title": "Two tenons on each board",
    "text": "Each board has two tenons set in order, allowing it to fit into the supporting sockets. The construction details describe how the framework is assembled.",
    "refs": [
      "Exodus 26:19"
    ]
  },
  "Exodus 26:18": {
    "title": "Boards for the south side",
    "text": "Twenty boards are assigned to the south side of the tabernacle. The structure is measured and assembled side by side according to the plan.",
    "refs": [
      "Exodus 26:20"
    ]
  },
  "Exodus 26:19": {
    "title": "Silver sockets beneath the boards",
    "text": "Forty silver sockets are made for the twenty boards, two sockets beneath each board. The sockets support the upright boards securely.",
    "refs": [
      "Exodus 26:17"
    ]
  },
  "Exodus 26:20": {
    "title": "Boards for the north side",
    "text": "Twenty boards are specified for the north side. The symmetry helps form a stable rectangular sanctuary.",
    "refs": [
      "Exodus 26:18"
    ]
  },
  "Exodus 26:21": {
    "title": "Forty silver sockets",
    "text": "The north side also has forty silver sockets, two under each board. The repeated measurements make the two long sides structurally consistent.",
    "refs": [
      "Exodus 26:19"
    ]
  },
  "Exodus 26:22": {
    "title": "Boards for the west side",
    "text": "Six boards are made for the west side of the tabernacle. The end wall uses a different number of boards because of the structure’s dimensions.",
    "refs": [
      "Exodus 26:23–25"
    ]
  },
  "Exodus 26:23": {
    "title": "Corner boards",
    "text": "Two boards are made for the corners at the rear. The corner pieces help secure the shape of the framework.",
    "refs": [
      "Exodus 26:22"
    ]
  },
  "Exodus 26:24": {
    "title": "The corner boards are joined",
    "text": "The corner boards are joined together from below and above by a ring. The precise arrangement reinforces the structure at its corners.",
    "refs": [
      "Exodus 26:23"
    ]
  },
  "Exodus 26:25": {
    "title": "Eight boards and sixteen sockets",
    "text": "The west side has eight boards and sixteen silver sockets, two beneath each board. The verse completes the basic board-and-socket count for the framework.",
    "refs": [
      "Exodus 26:22–24"
    ]
  },
  "Exodus 26:26": {
    "title": "Bars of acacia wood",
    "text": "Bars are made to hold the boards together. The bars strengthen the framework and keep the boards aligned.",
    "refs": [
      "Exodus 26:27–29"
    ]
  },
  "Exodus 26:27": {
    "title": "Bars for the west side",
    "text": "Bars are specified for the west side and for the sides of the tabernacle. The arrangement gives lateral support to the upright boards.",
    "refs": [
      "Exodus 26:26"
    ]
  },
  "Exodus 26:28": {
    "title": "The middle bar runs through the boards",
    "text": "The middle bar extends from end to end at the center of the boards. It helps bind the framework into a unified structure.",
    "refs": [
      "Exodus 26:26"
    ]
  },
  "Exodus 26:29": {
    "title": "Gold-covered boards and rings",
    "text": "The boards and rings are overlaid with gold, and the bars are also overlaid with gold. The materials and workmanship follow the sacred pattern given to Moses.",
    "refs": [
      "Exodus 25:9"
    ]
  },
  "Exodus 26:30": {
    "title": "Set up the tabernacle by the pattern",
    "text": "Moses must erect the tabernacle according to the pattern shown on the mountain. The repeated instruction stresses that worship is shaped by God’s direction, not simply human taste.",
    "refs": [
      "Exodus 25:40"
    ]
  },
  "Exodus 26:31": {
    "title": "The veil between holy places",
    "text": "A veil of fine linen with blue, purple, scarlet, and cherubim is made to divide the holy place from the most holy. The veil marks a boundary within the sanctuary and regulates access.",
    "refs": [
      "Exodus 26:33",
      "Hebrews 9:3"
    ]
  },
  "Exodus 26:32": {
    "title": "The veil’s pillars and sockets",
    "text": "The veil hangs from four gold-covered acacia pillars set in silver sockets. The structure supports the barrier that divides the sanctuary spaces.",
    "refs": [
      "Exodus 26:31"
    ]
  },
  "Exodus 26:33": {
    "title": "The ark behind the veil",
    "text": "The veil is hung beneath the clasps, and the ark of the testimony is placed behind it in the most holy place. The layout defines the innermost sanctuary where the covenant ark is kept.",
    "refs": [
      "Exodus 25:16–22",
      "Hebrews 9:3–5"
    ]
  },
  "Exodus 26:34": {
    "title": "The mercy seat placed on the ark",
    "text": "The mercy seat is set upon the ark of the testimony in the most holy place. The arrangement follows the instructions given in chapter 25.",
    "refs": [
      "Exodus 25:17–22"
    ]
  },
  "Exodus 26:35": {
    "title": "The table and lampstand outside the veil",
    "text": "The table is placed on the north side and the lampstand opposite it on the south side, outside the veil. The furnishings are arranged according to the prescribed plan for the holy place.",
    "refs": [
      "Exodus 25:23–40"
    ]
  },
  "Exodus 26:36": {
    "title": "A screen for the tent entrance",
    "text": "A screen of embroidered fabric is made for the tabernacle entrance. It distinguishes the entrance while matching the sanctuary’s colors and materials.",
    "refs": [
      "Exodus 26:1"
    ]
  },
  "Exodus 26:37": {
    "title": "Five pillars for the entrance screen",
    "text": "Five acacia pillars are made for the screen and overlaid with gold, with bronze sockets. The entrance structure completes the tabernacle’s framework according to God’s instruction.",
    "refs": [
      "Exodus 27:16"
    ]
  },
  "Exodus 27:1": {
    "title": "The altar of burnt offering",
    "text": "The altar is made of acacia wood with specified dimensions and horns at its corners. It is the place for burnt offerings in the courtyard, and its design follows God’s instruction for Israel’s worship.",
    "refs": [
      "Exodus 38:1–2"
    ]
  },
  "Exodus 27:2": {
    "title": "Horns and bronze covering",
    "text": "The altar’s horns are made as one piece with it, and the whole altar is overlaid with bronze. The construction details distinguish this courtyard altar from the gold furnishings inside the sanctuary.",
    "refs": [
      "Leviticus 4:7"
    ]
  },
  "Exodus 27:3": {
    "title": "Utensils for the altar",
    "text": "Pans, shovels, basins, forks, and firepans are made for the altar, all of bronze. The utensils support the regular handling of sacrifices and ashes.",
    "refs": [
      "Exodus 38:3"
    ]
  },
  "Exodus 27:4": {
    "title": "A bronze network",
    "text": "A grating of bronze netting is made with four rings at its corners. The structure is part of the altar’s design and helps support the fire and offerings.",
    "refs": [
      "Exodus 38:4"
    ]
  },
  "Exodus 27:5": {
    "title": "The grating is set beneath the altar ledge",
    "text": "The bronze grating is placed under the altar’s ledge, reaching halfway up the altar. The measurements ensure that the altar is assembled as instructed.",
    "refs": [
      "Exodus 27:4"
    ]
  },
  "Exodus 27:6": {
    "title": "Staves for carrying the altar",
    "text": "Acacia wood staves are made and overlaid with bronze so the altar can be carried. The portable design suits Israel’s journey through the wilderness.",
    "refs": [
      "Numbers 4:13–14"
    ]
  },
  "Exodus 27:7": {
    "title": "The staves pass through the rings",
    "text": "The staves are inserted through the rings on the sides of the altar for carrying. The altar is to be transported according to the prescribed arrangement.",
    "refs": [
      "Exodus 27:6"
    ]
  },
  "Exodus 27:8": {
    "title": "The altar is hollow and made by the pattern",
    "text": "The altar is made hollow with boards, according to the pattern shown on the mountain. This repeated emphasis confirms that its construction follows divine instruction.",
    "refs": [
      "Exodus 25:9",
      "Exodus 26:30"
    ]
  },
  "Exodus 27:9": {
    "title": "The south side of the courtyard",
    "text": "The courtyard is enclosed with fine linen hangings on the south side, with specified length. The courtyard creates a defined area around the tabernacle for Israel’s worship.",
    "refs": [
      "Exodus 38:9"
    ]
  },
  "Exodus 27:10": {
    "title": "Pillars and sockets on the south",
    "text": "The hangings are supported by twenty pillars and bronze sockets, with silver hooks and bands. The materials and measurements are given so the enclosure can be built securely.",
    "refs": [
      "Exodus 38:10"
    ]
  },
  "Exodus 27:11": {
    "title": "The north side of the courtyard",
    "text": "The north side has hangings and pillars matching the south side. The symmetry forms a consistent rectangular enclosure.",
    "refs": [
      "Exodus 27:9–10"
    ]
  },
  "Exodus 27:12": {
    "title": "The west side of the courtyard",
    "text": "The west end has hangings of the specified length and ten pillars with their sockets. The shorter end uses fewer pillars than the long sides.",
    "refs": [
      "Exodus 38:12"
    ]
  },
  "Exodus 27:13": {
    "title": "The east side of the courtyard",
    "text": "The east side is the same width as the courtyard. This verse establishes the dimensions of the entrance end before describing the gate.",
    "refs": [
      "Exodus 27:14–16"
    ]
  },
  "Exodus 27:14": {
    "title": "Hangings on one side of the entrance",
    "text": "The entrance side has hangings of fifteen cubits supported by three pillars and sockets. The gate is centered between two matching sections.",
    "refs": [
      "Exodus 27:15"
    ]
  },
  "Exodus 27:15": {
    "title": "Hangings on the other side",
    "text": "The other side of the entrance has the same measurements and supports. The matching arrangement keeps the gate centered in the courtyard’s eastern side.",
    "refs": [
      "Exodus 27:14"
    ]
  },
  "Exodus 27:16": {
    "title": "The gate screen",
    "text": "The courtyard gate has a twenty-cubit screen made of embroidered blue, purple, and scarlet fabric and fine linen, supported by four pillars. The entrance is clearly marked and matches the tabernacle’s sacred design.",
    "refs": [
      "Exodus 38:18"
    ]
  },
  "Exodus 27:17": {
    "title": "Silver fittings for the pillars",
    "text": "The pillars around the courtyard have silver bands, hooks, and bronze sockets. The verse summarizes the fittings that secure the linen enclosure.",
    "refs": [
      "Exodus 27:10"
    ]
  },
  "Exodus 27:18": {
    "title": "The courtyard’s dimensions",
    "text": "The courtyard’s length, width, and height of its linen hangings are specified. These measurements define the outer worship space around the tabernacle.",
    "refs": [
      "Exodus 38:9–20"
    ]
  },
  "Exodus 27:19": {
    "title": "Bronze utensils and tent pins",
    "text": "The utensils used in the tabernacle service and the pins for the tent and courtyard are made of bronze. Even practical fittings are included in the instructions for the sanctuary.",
    "refs": [
      "Exodus 38:20"
    ]
  },
  "Exodus 27:20": {
    "title": "Pure olive oil for the lamps",
    "text": "Israel is to bring pure beaten olive oil so the lamps may burn continually. The command makes the people responsible for providing what is needed for the sanctuary’s regular light.",
    "refs": [
      "Leviticus 24:1–4"
    ]
  },
  "Exodus 27:21": {
    "title": "Aaron and his sons maintain the lamps",
    "text": "Aaron and his sons are to keep the lamps burning from evening to morning before the LORD, outside the veil of the testimony. The regular service is an enduring ordinance for Israel’s generations and is carried out in the place God appointed.",
    "refs": [
      "Exodus 25:37",
      "Leviticus 24:2–4"
    ]
  },
  "Exodus 28:1": {
    "title": "Aaron and his sons appointed for priesthood",
    "text": "God tells Moses to bring Aaron and his sons near to serve as priests. Their appointment is for a defined sacred office within Israel’s covenant worship, and it is given by God rather than claimed by personal ambition.",
    "refs": [
      "Leviticus 8:1–13",
      "Hebrews 5:4"
    ]
  },
  "Exodus 28:2": {
    "title": "Holy garments for glory and beauty",
    "text": "Moses is to make holy garments for Aaron for glory and beauty. The garments visibly distinguish the priestly office and express the seriousness of representing Israel in worship.",
    "refs": [
      "Exodus 28:40"
    ]
  },
  "Exodus 28:3": {
    "title": "Skilled workers make the garments",
    "text": "God says He has filled skilled workers with a spirit of wisdom to make Aaron’s garments for his consecration. Skill and craftsmanship are presented as gifts that can be used in service to God.",
    "refs": [
      "Exodus 31:1–6"
    ]
  },
  "Exodus 28:4": {
    "title": "The garments named",
    "text": "The breastplate, ephod, robe, embroidered coat, turban, and sash are listed. The following verses explain their construction and function in priestly service.",
    "refs": [
      "Exodus 28:6–39"
    ]
  },
  "Exodus 28:5": {
    "title": "Gold and colored materials",
    "text": "The workers use gold, blue, purple, scarlet, and fine linen. These are the materials specified for the priestly garments, connecting them visually with the tabernacle’s design.",
    "refs": [
      "Exodus 25:4"
    ]
  },
  "Exodus 28:6": {
    "title": "The ephod’s materials and workmanship",
    "text": "The ephod is made of gold and colored yarns with fine linen, using skillful work. It is a distinctive garment that will carry the stones representing Israel’s tribes.",
    "refs": [
      "Exodus 28:9–12"
    ]
  },
  "Exodus 28:7": {
    "title": "Shoulder pieces joined together",
    "text": "The ephod has two shoulder pieces joined at its edges. These pieces support the stones described next and help the garment sit securely on the priest.",
    "refs": [
      "Exodus 28:9–12"
    ]
  },
  "Exodus 28:8": {
    "title": "The ephod’s woven band",
    "text": "The skillfully woven band is made of the same materials as the ephod. The garment’s construction is coordinated so the band and body form one designed piece.",
    "refs": [
      "Exodus 39:5"
    ]
  },
  "Exodus 28:9": {
    "title": "Two onyx stones engraved with names",
    "text": "Two onyx stones are engraved with the names of Israel’s sons. The priest carries the names of the tribes on his shoulders, symbolizing representation of the people before God.",
    "refs": [
      "Exodus 28:12"
    ]
  },
  "Exodus 28:10": {
    "title": "Names in birth order",
    "text": "Six names are engraved on one stone and six on the other, according to birth order. The arrangement includes the whole family of Israel in the priestly memorial.",
    "refs": [
      "Genesis 29:31–30:24"
    ]
  },
  "Exodus 28:11": {
    "title": "Engraving like a seal",
    "text": "The stones are engraved with the names as a skilled engraver cuts a seal, then set in gold settings. The precious stones are treated as memorial objects within the priestly garment.",
    "refs": [
      "Exodus 28:9–12"
    ]
  },
  "Exodus 28:12": {
    "title": "The names on Aaron’s shoulders",
    "text": "The stones are placed on the ephod’s shoulder pieces as memorial stones for Israel’s sons, and Aaron bears their names before the LORD. The image emphasizes representative priestly service rather than a separate divine being.",
    "refs": [
      "Exodus 28:29"
    ]
  },
  "Exodus 28:13": {
    "title": "Gold settings",
    "text": "Gold settings are made for the stones. They hold the engraved memorial stones securely in place on the ephod.",
    "refs": [
      "Exodus 28:11"
    ]
  },
  "Exodus 28:14": {
    "title": "Chains of pure gold",
    "text": "Two chains of pure gold, twisted like cords, are made for the settings. The chains connect the stones and breastplate according to the design that follows.",
    "refs": [
      "Exodus 28:22–25"
    ]
  },
  "Exodus 28:15": {
    "title": "The breastplate of judgment",
    "text": "The breastplate is made with skillful work from the same colored materials and gold. It is called the breastplate of judgment because it is associated with the priest’s representative service and the means of seeking God’s judgment.",
    "refs": [
      "Exodus 28:29–30"
    ]
  },
  "Exodus 28:16": {
    "title": "A square, doubled breastplate",
    "text": "The breastplate is square and doubled, with specified dimensions. The doubled fabric forms a pocket-like structure for the items associated with the breastplate.",
    "refs": [
      "Exodus 28:30"
    ]
  },
  "Exodus 28:17": {
    "title": "Four rows of stones begin",
    "text": "The breastplate is set with precious stones in the first row: sardius, topaz, and carbuncle. Each stone is associated with one of Israel’s tribes in the list that follows.",
    "refs": [
      "Exodus 28:21"
    ]
  },
  "Exodus 28:18": {
    "title": "The second row of stones",
    "text": "The second row includes an emerald, sapphire, and diamond according to the KJV wording. The precise modern identification of some ancient gemstone names is debated, but the text’s intent is a carefully arranged set of precious stones.",
    "refs": [
      "Exodus 28:17–20"
    ]
  },
  "Exodus 28:19": {
    "title": "The third row of stones",
    "text": "The third row includes ligure, agate, and amethyst in the KJV. The ancient gemstone identifications are not all certain, so the safest reading preserves the biblical names without forcing modern mineral equivalents.",
    "refs": [
      "Exodus 28:17–20"
    ]
  },
  "Exodus 28:20": {
    "title": "The fourth row and gold settings",
    "text": "The fourth row lists beryl, onyx, and jasper, each set in gold. Together the rows form the breastplate’s complete set of twelve stones.",
    "refs": [
      "Exodus 28:21"
    ]
  },
  "Exodus 28:21": {
    "title": "Twelve stones for twelve tribes",
    "text": "Each stone is engraved with one of the names of Israel’s sons, one name for each stone. The breastplate visibly represents all twelve tribes before God.",
    "refs": [
      "Exodus 28:29"
    ]
  },
  "Exodus 28:22": {
    "title": "Chains attached to the breastplate",
    "text": "Chains of pure gold, twisted like cords, are made for the breastplate. They connect the breastplate to the ephod’s gold settings.",
    "refs": [
      "Exodus 28:14"
    ]
  },
  "Exodus 28:23": {
    "title": "Gold rings on the breastplate",
    "text": "Two gold rings are made for the breastplate’s upper corners. The rings provide the attachment points for the chains.",
    "refs": [
      "Exodus 28:24"
    ]
  },
  "Exodus 28:24": {
    "title": "Chains through the rings",
    "text": "The two gold chains are attached to the rings on the breastplate. The details specify how the breastplate is secured to the garment.",
    "refs": [
      "Exodus 28:22–23"
    ]
  },
  "Exodus 28:25": {
    "title": "Chains attached to the ephod",
    "text": "The other ends of the chains are attached to the gold settings on the shoulder pieces. This connection joins the breastplate securely to the ephod.",
    "refs": [
      "Exodus 28:6–8"
    ]
  },
  "Exodus 28:26": {
    "title": "Two lower gold rings",
    "text": "Two more gold rings are made for the lower corners of the breastplate on the inner side. They provide further points for securing the breastplate.",
    "refs": [
      "Exodus 28:27"
    ]
  },
  "Exodus 28:27": {
    "title": "Rings opposite the ephod’s band",
    "text": "Two gold rings are made on the ephod’s shoulder pieces near the band, opposite the lower rings of the breastplate. Their position allows the pieces to be tied together securely.",
    "refs": [
      "Exodus 28:26–28"
    ]
  },
  "Exodus 28:28": {
    "title": "A blue cord secures the breastplate",
    "text": "A blue lace connects the breastplate rings to the ephod rings so the breastplate stays above the band and does not come loose. The instruction ensures that the breastplate remains properly attached during priestly service.",
    "refs": [
      "Exodus 39:21"
    ]
  },
  "Exodus 28:29": {
    "title": "Aaron bears Israel’s names over his heart",
    "text": "Aaron bears the names of Israel’s sons on the breastplate over his heart when he enters the holy place, as a continual memorial before the LORD. The imagery emphasizes that the priest represents the people with care and responsibility.",
    "refs": [
      "Exodus 28:12"
    ]
  },
  "Exodus 28:30": {
    "title": "Urim and Thummim",
    "text": "The Urim and Thummim are placed in the breastplate, and Aaron bears the judgment of Israel over his heart before the LORD. Scripture does not fully describe their physical form or exact method of use, so explanations beyond the text should be identified as proposals rather than certainties.",
    "refs": [
      "Numbers 27:21",
      "1 Samuel 28:6"
    ]
  },
  "Exodus 28:31": {
    "title": "The robe of the ephod",
    "text": "The robe is made entirely of blue. Its construction is described separately from the ephod and breastplate, with the hem details following.",
    "refs": [
      "Exodus 28:33"
    ]
  },
  "Exodus 28:32": {
    "title": "A reinforced opening for the head",
    "text": "The robe has an opening in the middle with a woven binding so it will not tear. The design is practical as well as ceremonial, protecting the garment from damage.",
    "refs": [
      "Exodus 39:23"
    ]
  },
  "Exodus 28:33": {
    "title": "Pomegranates and bells",
    "text": "Blue, purple, and scarlet pomegranates are placed around the robe’s hem, alternating with gold bells. The decorations are part of the prescribed priestly garment and have a practical sound function in the next verse.",
    "refs": [
      "Exodus 28:34"
    ]
  },
  "Exodus 28:34": {
    "title": "Alternating bells and pomegranates",
    "text": "The hem alternates gold bells and pomegranates. The pattern makes the robe’s lower edge consistent around the garment.",
    "refs": [
      "Exodus 28:33"
    ]
  },
  "Exodus 28:35": {
    "title": "The bells sound during priestly service",
    "text": "Aaron must wear the robe when ministering, and its sound is heard as he enters and leaves the holy place so he does not die. The text gives the bells a role within the prescribed sacred service; the warning stresses that priestly approach must follow God’s instructions.",
    "refs": [
      "Leviticus 16:2–4"
    ]
  },
  "Exodus 28:36": {
    "title": "A plate of pure gold",
    "text": "A plate of pure gold is made and engraved with “HOLINESS TO THE LORD.” The inscription makes the theme of holiness visible on the high priest’s headgear.",
    "refs": [
      "Exodus 39:30"
    ]
  },
  "Exodus 28:37": {
    "title": "The gold plate is attached with blue lace",
    "text": "The plate is fastened to the front of the turban with a blue lace. Its placement keeps the inscription visible as part of the high priest’s official garments.",
    "refs": [
      "Exodus 28:36"
    ]
  },
  "Exodus 28:38": {
    "title": "Aaron bears the people’s holy gifts",
    "text": "The plate remains on Aaron’s forehead, and he bears the iniquity associated with the holy things Israel consecrates. The verse shows that even offerings dedicated to God require priestly mediation according to the sanctuary’s instructions.",
    "refs": [
      "Leviticus 22:15–16"
    ]
  },
  "Exodus 28:39": {
    "title": "The coat, turban, and sash",
    "text": "The coat is woven of fine linen, the turban is made of fine linen, and the sash is embroidered. These items complete part of the priestly clothing described in the chapter.",
    "refs": [
      "Exodus 39:27–29"
    ]
  },
  "Exodus 28:40": {
    "title": "Garments for Aaron’s sons",
    "text": "Moses is to make coats, sashes, and bonnets for Aaron’s sons for glory and beauty. Their garments distinguish their priestly service while following the same principle of sacred preparation.",
    "refs": [
      "Exodus 28:2"
    ]
  },
  "Exodus 28:41": {
    "title": "Anoint, consecrate, and sanctify",
    "text": "Moses is to put the garments on Aaron and his sons, anoint them, and consecrate them for priestly service. Their authority to minister comes through God’s appointment and the prescribed consecration, not self-appointment.",
    "refs": [
      "Leviticus 8:1–13"
    ]
  },
  "Exodus 28:42": {
    "title": "Linen breeches for modesty",
    "text": "Linen breeches are to cover the priests from the waist to the thighs. The instruction protects modesty in service at the altar and in the sanctuary.",
    "refs": [
      "Exodus 20:26"
    ]
  },
  "Exodus 28:43": {
    "title": "A lasting ordinance for priestly service",
    "text": "Aaron and his sons must wear these garments when entering the tent of meeting or approaching the altar, lest they bear iniquity and die. The chapter closes by emphasizing the seriousness of priestly service and the need to obey God’s instructions.",
    "refs": [
      "Leviticus 8:35",
      "Hebrews 5:4"
    ]
  },
  "Exodus 29:1": {
    "title": "Consecrating Aaron and his sons",
    "text": "God gives instructions for consecrating Aaron and his sons to serve as priests. The ceremony sets them apart for a specific office in Israel’s worship; their ministry is established by God’s appointment, not personal claim.",
    "refs": [
      "Exodus 28:41",
      "Leviticus 8:1–13"
    ]
  },
  "Exodus 29:2": {
    "title": "Unleavened bread for the ceremony",
    "text": "Unleavened bread, cakes mixed with oil, and wafers anointed with oil are prepared from fine flour. The offerings follow the detailed instructions for the priestly consecration.",
    "refs": [
      "Exodus 12:15",
      "Leviticus 8:26"
    ]
  },
  "Exodus 29:3": {
    "title": "Place the bread in a basket",
    "text": "The bread is placed in a basket and brought with a bullock and two rams. These items are part of the prescribed offerings for the consecration ceremony.",
    "refs": [
      "Leviticus 8:2"
    ]
  },
  "Exodus 29:4": {
    "title": "Wash Aaron and his sons",
    "text": "Aaron and his sons are brought to the door of the tent of meeting and washed with water. The washing signifies preparation for sacred service within Israel’s covenant worship.",
    "refs": [
      "Leviticus 8:6",
      "Hebrews 10:22"
    ]
  },
  "Exodus 29:5": {
    "title": "Put on the priestly garments",
    "text": "Moses is to put the garments on Aaron in the order God specifies: the coat, robe, ephod, breastplate, and skillfully woven band. The garments visibly mark Aaron’s office as high priest.",
    "refs": [
      "Exodus 28:4–8"
    ]
  },
  "Exodus 29:6": {
    "title": "The holy crown on the turban",
    "text": "Moses places the turban on Aaron’s head and the holy crown upon it. The gold plate’s inscription, “HOLINESS TO THE LORD,” marks the priest’s service as belonging to God.",
    "refs": [
      "Exodus 28:36–38"
    ]
  },
  "Exodus 29:7": {
    "title": "Anointing oil poured on Aaron",
    "text": "Moses takes the anointing oil and pours it on Aaron’s head. The act consecrates Aaron for the high-priestly office according to God’s command.",
    "refs": [
      "Leviticus 8:12",
      "Psalm 133:2"
    ]
  },
  "Exodus 29:8": {
    "title": "Garments for Aaron’s sons",
    "text": "Aaron’s sons are brought forward and clothed in their coats. Their garments distinguish their priestly role within the same consecration ceremony.",
    "refs": [
      "Exodus 28:40"
    ]
  },
  "Exodus 29:9": {
    "title": "Priestly office by a lasting ordinance",
    "text": "The sons receive sashes and bonnets, and the priesthood is given to Aaron and his descendants by a perpetual statute. The phrase describes the continuing priestly arrangement under Israel’s covenant, later developed through the history of Israel’s worship.",
    "refs": [
      "Numbers 18:7",
      "Hebrews 7:11–12"
    ]
  },
  "Exodus 29:10": {
    "title": "The bullock before the tent",
    "text": "The bullock is brought before the tent of meeting, and Aaron and his sons lay their hands on its head. The action identifies the animal with the offering being presented in the consecration rite.",
    "refs": [
      "Leviticus 4:4"
    ]
  },
  "Exodus 29:11": {
    "title": "The bullock is killed before the LORD",
    "text": "The bullock is killed at the door of the tent of meeting as the LORD commands. The ceremony includes sacrifice as part of the prescribed consecration of the priests.",
    "refs": [
      "Leviticus 8:15"
    ]
  },
  "Exodus 29:12": {
    "title": "Blood on the altar’s horns",
    "text": "Some blood from the bullock is placed on the horns of the altar, and the rest is poured at its base. The blood ritual marks the altar as part of the sacrificial service and is connected with purification and atonement in Israel’s worship.",
    "refs": [
      "Leviticus 4:7",
      "Hebrews 9:22"
    ]
  },
  "Exodus 29:13": {
    "title": "Fat and organs offered",
    "text": "The fat covering the inward parts, the caul over the liver, and the kidneys with their fat are burned on the altar. These are the specified portions for the offering.",
    "refs": [
      "Leviticus 3:3–5"
    ]
  },
  "Exodus 29:14": {
    "title": "The remaining parts burned outside the camp",
    "text": "The bullock’s flesh, skin, and dung are burned outside the camp as a sin offering. The disposal distinguishes these parts from the portions offered on the altar.",
    "refs": [
      "Leviticus 4:11–12",
      "Hebrews 13:11–13"
    ]
  },
  "Exodus 29:15": {
    "title": "Hands laid on the first ram",
    "text": "Aaron and his sons lay their hands on the head of the first ram. The gesture identifies the animal with the offering presented on their behalf.",
    "refs": [
      "Exodus 29:10"
    ]
  },
  "Exodus 29:16": {
    "title": "The ram is killed and its blood applied",
    "text": "The ram is killed, and its blood is sprinkled around the altar. The offering follows the sacrificial procedure commanded for the consecration ceremony.",
    "refs": [
      "Leviticus 8:19"
    ]
  },
  "Exodus 29:17": {
    "title": "The ram is divided into parts",
    "text": "The ram is cut into pieces, its inward parts and legs are washed, and the parts are arranged with the head. The washing and arrangement are specific steps in the offering ritual.",
    "refs": [
      "Leviticus 1:6–9"
    ]
  },
  "Exodus 29:18": {
    "title": "A burnt offering to the LORD",
    "text": "The whole ram is burned on the altar as a burnt offering, described as a sweet savour to the LORD. The offering is wholly given to God according to the ritual’s instructions.",
    "refs": [
      "Leviticus 1:9",
      "Ephesians 5:2"
    ]
  },
  "Exodus 29:19": {
    "title": "The second ram",
    "text": "Aaron and his sons lay their hands on the head of the second ram. This ram is used in the special consecration rite described in the following verses.",
    "refs": [
      "Exodus 29:20–22"
    ]
  },
  "Exodus 29:20": {
    "title": "Blood on ear, thumb, and toe",
    "text": "The ram is killed, and blood is placed on the right ear, thumb of the right hand, and great toe of the right foot of Aaron and his sons. The ritual marks their hearing, work, and walk as set apart for service; the text does not give a separate symbolic explanation for each body part.",
    "refs": [
      "Leviticus 8:23–24"
    ]
  },
  "Exodus 29:21": {
    "title": "Blood and anointing oil sprinkled",
    "text": "Blood from the altar and anointing oil are sprinkled on Aaron, his garments, and his sons and their garments. The rite marks the priests and their clothing as consecrated for the service God has appointed.",
    "refs": [
      "Leviticus 8:30"
    ]
  },
  "Exodus 29:22": {
    "title": "The ram of consecration",
    "text": "The fat, tail, organs, kidneys, and right shoulder of the ram are taken as the consecration offering. The specified portions are reserved for the ritual that follows.",
    "refs": [
      "Leviticus 8:25"
    ]
  },
  "Exodus 29:23": {
    "title": "One loaf and cakes from the basket",
    "text": "One loaf of bread, one cake of oiled bread, and one wafer are taken from the basket of unleavened bread before the LORD. The bread accompanies the ram in the consecration ceremony.",
    "refs": [
      "Exodus 29:2–3"
    ]
  },
  "Exodus 29:24": {
    "title": "The portions are placed in the priests’ hands",
    "text": "The bread and portions of the ram are placed in the hands of Aaron and his sons and waved before the LORD. The gesture presents them as an offering to God.",
    "refs": [
      "Leviticus 8:27"
    ]
  },
  "Exodus 29:25": {
    "title": "The offering is burned on the altar",
    "text": "The portions are taken from the priests’ hands and burned on the altar with the burnt offering. The rite is described as a sweet savour to the LORD and is part of their consecration.",
    "refs": [
      "Exodus 29:18"
    ]
  },
  "Exodus 29:26": {
    "title": "Moses’ portion from the ram",
    "text": "Moses takes the breast of the ram of consecration and waves it as a wave offering before the LORD; it becomes Moses’ portion. The verse assigns a specific part of the offering to the officiating leader.",
    "refs": [
      "Leviticus 8:29"
    ]
  },
  "Exodus 29:27": {
    "title": "The breast and shoulder are set apart",
    "text": "The breast of the wave offering and shoulder of the heave offering are sanctified from the ram of consecration. The instructions establish these portions as holy parts of the priestly offerings.",
    "refs": [
      "Leviticus 7:31–34"
    ]
  },
  "Exodus 29:28": {
    "title": "A lasting portion for the priests",
    "text": "The breast and shoulder become an ordinance for Aaron and his sons from Israel’s peace offerings. The provision supports the priests through the worship system established in the covenant.",
    "refs": [
      "Leviticus 7:34–36"
    ]
  },
  "Exodus 29:29": {
    "title": "The garments pass to Aaron’s successor",
    "text": "Aaron’s holy garments are to be passed to his sons after him, for use when they are anointed and consecrated. The garments represent an office that continues beyond Aaron’s own lifetime.",
    "refs": [
      "Numbers 20:25–28"
    ]
  },
  "Exodus 29:30": {
    "title": "Seven days before serving",
    "text": "The son who succeeds Aaron is to wear the garments for seven days when he enters the tent of meeting to minister in the holy place. The period marks the formal transition into priestly service.",
    "refs": [
      "Leviticus 8:33–35"
    ]
  },
  "Exodus 29:31": {
    "title": "Boil the ram in a holy place",
    "text": "The ram of consecration is to be boiled in a holy place. The meat belongs to the consecration ceremony and is handled according to the sacred instructions.",
    "refs": [
      "Leviticus 8:31"
    ]
  },
  "Exodus 29:32": {
    "title": "Aaron and his sons eat at the entrance",
    "text": "Aaron and his sons eat the ram’s flesh and the bread at the door of the tent of meeting. The meal is part of the consecration rite and is restricted to those being consecrated.",
    "refs": [
      "Leviticus 8:31"
    ]
  },
  "Exodus 29:33": {
    "title": "The food belongs to the consecration",
    "text": "They eat the portions by which atonement was made to consecrate and sanctify them, but no unauthorized person may eat because the food is holy. The restriction distinguishes the consecration meal from ordinary food.",
    "refs": [
      "Leviticus 22:10–13"
    ]
  },
  "Exodus 29:34": {
    "title": "Burn leftovers by morning",
    "text": "If any consecration meat or bread remains until morning, it must be burned and not eaten. The command ensures that the holy food is handled only as prescribed.",
    "refs": [
      "Exodus 12:10"
    ]
  },
  "Exodus 29:35": {
    "title": "Seven days of consecration",
    "text": "Moses must do all that God commanded concerning Aaron and his sons, continuing the consecration for seven days. The repetition stresses that the ceremony is a complete period of preparation, not a single moment.",
    "refs": [
      "Leviticus 8:33"
    ]
  },
  "Exodus 29:36": {
    "title": "A bullock each day for sin offering",
    "text": "A bullock is offered daily for a sin offering during the consecration, and the altar is purified and anointed. The altar itself is treated as needing the prescribed consecration before regular use.",
    "refs": [
      "Leviticus 8:15"
    ]
  },
  "Exodus 29:37": {
    "title": "The altar becomes most holy",
    "text": "The altar is to be atoned for and sanctified for seven days; whatever touches it becomes holy under the stated rule. The verse emphasizes the sacred status of the altar within Israel’s sacrificial system.",
    "refs": [
      "Exodus 40:10"
    ]
  },
  "Exodus 29:38": {
    "title": "Two lambs every day",
    "text": "Two lambs of the first year are offered daily on the altar, one in the morning and one at evening. The continual offerings establish a regular rhythm of worship before the LORD.",
    "refs": [
      "Numbers 28:3–4"
    ]
  },
  "Exodus 29:39": {
    "title": "Morning and evening offerings",
    "text": "One lamb is offered in the morning and the other at evening. The regular schedule makes worship a daily practice rather than an occasional event.",
    "refs": [
      "Psalm 141:2"
    ]
  },
  "Exodus 29:40": {
    "title": "Flour, oil, and wine with the lamb",
    "text": "A specified amount of fine flour mixed with beaten oil and a drink offering of wine accompanies the lamb. The verse describes the full prescribed offering rather than the lamb alone.",
    "refs": [
      "Numbers 28:5–7"
    ]
  },
  "Exodus 29:41": {
    "title": "The evening offering",
    "text": "The second lamb is offered at evening with the same grain and drink offerings, as a sweet savour to the LORD. The morning and evening offerings form a continuing daily service.",
    "refs": [
      "Exodus 29:38–40"
    ]
  },
  "Exodus 29:42": {
    "title": "A continual offering at the tent entrance",
    "text": "The burnt offering is to continue through Israel’s generations at the door of the tent of meeting, where God says He will meet with Israel. The offering is connected to the appointed place of covenant meeting.",
    "refs": [
      "Numbers 28:6"
    ]
  },
  "Exodus 29:43": {
    "title": "God’s glory sanctifies the place",
    "text": "God says He will meet with Israel there, and the place will be sanctified by His glory. The sanctuary is holy because God appoints it and makes His presence known there, not because a structure contains the infinite God.",
    "refs": [
      "Exodus 40:34–35"
    ]
  },
  "Exodus 29:44": {
    "title": "The tent and altar are sanctified",
    "text": "God promises to sanctify the tent of meeting and the altar, and Aaron and his sons to minister as priests. Consecration applies to the place of worship and the people appointed to serve there.",
    "refs": [
      "Leviticus 8:10–12"
    ]
  },
  "Exodus 29:45": {
    "title": "God dwells among Israel",
    "text": "The LORD declares that He will dwell among the children of Israel and be their God. The promise expresses covenant presence and relationship; it does not mean God’s being is confined to the tabernacle.",
    "refs": [
      "Leviticus 26:11–12",
      "2 Corinthians 6:16"
    ]
  },
  "Exodus 29:46": {
    "title": "Israel knows the God who brought them out",
    "text": "Israel will know that the LORD is their God, who brought them out of Egypt so He may dwell among them. Deliverance leads to covenant relationship and worship, with the LORD identifying Himself as the one who rescued them.",
    "refs": [
      "Exodus 6:7",
      "Exodus 20:2"
    ]
  },
  "Exodus 30:1": {
    "title": "The altar of incense",
    "text": "God commands an altar of acacia wood for burning incense. This altar is distinct from the bronze altar in the courtyard and is placed within the sanctuary’s regular worship.",
    "refs": [
      "Exodus 30:6",
      "Exodus 37:25"
    ]
  },
  "Exodus 30:2": {
    "title": "The incense altar’s dimensions",
    "text": "The altar is square, two cubits high, with horns made as one piece with it. Its dimensions and design follow the pattern God has given for the sanctuary furnishings.",
    "refs": [
      "Exodus 37:25–26"
    ]
  },
  "Exodus 30:3": {
    "title": "Gold covers the incense altar",
    "text": "The top, sides, and horns are overlaid with pure gold, and a gold crown surrounds it. The materials distinguish the incense altar from the bronze altar in the courtyard.",
    "refs": [
      "Exodus 37:26"
    ]
  },
  "Exodus 30:4": {
    "title": "Two gold rings for carrying",
    "text": "Two gold rings are placed beneath the crown on opposite sides to hold the staves. The altar is designed to be carried as Israel travels.",
    "refs": [
      "Exodus 30:5"
    ]
  },
  "Exodus 30:5": {
    "title": "Gold-covered staves",
    "text": "Staves of acacia wood are overlaid with gold for carrying the altar. The portable design allows the sanctuary furnishings to move with Israel.",
    "refs": [
      "Numbers 4:11"
    ]
  },
  "Exodus 30:6": {
    "title": "Place the altar before the veil",
    "text": "The incense altar is placed before the veil near the ark’s mercy seat, where God says He will meet with Moses. This location ties the daily incense service to the sanctuary’s innermost place of covenant presence.",
    "refs": [
      "Exodus 25:22",
      "Leviticus 16:12–13"
    ]
  },
  "Exodus 30:7": {
    "title": "Aaron burns incense each morning",
    "text": "Aaron burns sweet incense when he dresses the lamps each morning. The incense service accompanies the regular tending of the sanctuary’s light.",
    "refs": [
      "Luke 1:9–10"
    ]
  },
  "Exodus 30:8": {
    "title": "Incense at evening as well",
    "text": "Aaron burns incense at evening when he lights the lamps, continually before the LORD through Israel’s generations. The morning and evening service creates a daily rhythm of worship.",
    "refs": [
      "Psalm 141:2"
    ]
  },
  "Exodus 30:9": {
    "title": "Only the prescribed incense",
    "text": "No strange incense, burnt offering, grain offering, or drink offering is to be placed on this altar. The command keeps its use distinct and prevents unauthorized substitutions in the sanctuary service.",
    "refs": [
      "Leviticus 10:1–3"
    ]
  },
  "Exodus 30:10": {
    "title": "Annual atonement for the altar",
    "text": "Aaron makes atonement on the altar’s horns once a year with the blood of the sin offering. The incense altar is included in the annual atonement rite, and the command is described as most holy to the LORD.",
    "refs": [
      "Leviticus 16:18–19"
    ]
  },
  "Exodus 30:11": {
    "title": "A census and ransom offering",
    "text": "The LORD tells Moses what to do when he counts the children of Israel. The census is to be accompanied by a ransom offering so the counting does not bring a plague upon the people.",
    "refs": [
      "Exodus 30:12"
    ]
  },
  "Exodus 30:12": {
    "title": "Each person gives a ransom",
    "text": "When Israel is numbered, each person gives a ransom for his life to the LORD, so no plague comes during the census. The payment is a prescribed covenant offering, not a general price by which people can purchase forgiveness for every sin.",
    "refs": [
      "Numbers 1:2–3"
    ]
  },
  "Exodus 30:13": {
    "title": "Half a shekel as an offering",
    "text": "Each counted person gives half a shekel according to the sanctuary standard. The same amount applies to each person, establishing equality in this specific offering.",
    "refs": [
      "Exodus 38:25–26"
    ]
  },
  "Exodus 30:14": {
    "title": "Those counted are twenty years and older",
    "text": "Every person twenty years old and upward who is numbered gives the offering. The age identifies the group included in this census requirement.",
    "refs": [
      "Numbers 1:3"
    ]
  },
  "Exodus 30:15": {
    "title": "The rich and poor give equally",
    "text": "The rich must not give more and the poor must not give less than the half shekel. The prescribed amount is the same for all, emphasizing equal standing in this specific act of ransom and support for sanctuary service.",
    "refs": [
      "Exodus 30:13"
    ]
  },
  "Exodus 30:16": {
    "title": "The money supports sanctuary service",
    "text": "Moses is to take the ransom money and use it for the service of the tent of meeting, as a memorial for Israel before the LORD. The offering is connected to the sanctuary’s service and the people’s covenant responsibility.",
    "refs": [
      "Exodus 38:25–28"
    ]
  },
  "Exodus 30:17": {
    "title": "The laver of bronze",
    "text": "The LORD commands a laver and its base to be made of bronze. It will be used by the priests for washing before they minister.",
    "refs": [
      "Exodus 38:8"
    ]
  },
  "Exodus 30:18": {
    "title": "Water for washing",
    "text": "The laver is placed between the tent of meeting and the altar and filled with water. Aaron and his sons will wash their hands and feet there before service.",
    "refs": [
      "Exodus 40:30–32"
    ]
  },
  "Exodus 30:19": {
    "title": "Hands and feet are washed",
    "text": "Aaron and his sons wash their hands and feet at the laver. The washing is a prescribed preparation for the holy service they perform.",
    "refs": [
      "Psalm 26:6"
    ]
  },
  "Exodus 30:20": {
    "title": "Wash before entering or serving",
    "text": "The priests must wash with water before entering the tent or approaching the altar to minister, so they do not die. The command underscores the seriousness of the sanctuary’s holiness and the need to follow God’s instruction.",
    "refs": [
      "Exodus 19:22"
    ]
  },
  "Exodus 30:21": {
    "title": "A lasting ordinance for the priests",
    "text": "The priests must wash their hands and feet as a perpetual statute for Aaron and his descendants. The rule is part of the covenant order for priestly service.",
    "refs": [
      "Exodus 40:31–32"
    ]
  },
  "Exodus 30:22": {
    "title": "A special anointing oil",
    "text": "God gives Moses the ingredients for a holy anointing oil. The oil is specially prepared for consecrating the sanctuary and its furnishings.",
    "refs": [
      "Exodus 30:25"
    ]
  },
  "Exodus 30:23": {
    "title": "Spices for the oil",
    "text": "Myrrh, cinnamon, sweet calamus, and cassia are specified in measured amounts for the oil. The recipe is precise and belongs to the sacred service God has established.",
    "refs": [
      "Exodus 37:29"
    ]
  },
  "Exodus 30:24": {
    "title": "Olive oil and the sanctuary measure",
    "text": "A hin of olive oil is included, and the spices are measured according to the sanctuary standard. The exact amounts distinguish this sacred oil from ordinary mixtures.",
    "refs": [
      "Exodus 30:23"
    ]
  },
  "Exodus 30:25": {
    "title": "A holy anointing oil compound",
    "text": "The ingredients are made into a holy anointing oil by the work of a perfumer. The oil is consecrated for the use God specifies, not for casual or ordinary use.",
    "refs": [
      "Exodus 30:31–33"
    ]
  },
  "Exodus 30:26": {
    "title": "Anoint the tent and ark",
    "text": "The oil is used to anoint the tent of meeting and the ark of the testimony. The act sets the sanctuary and its central covenant object apart for sacred service.",
    "refs": [
      "Exodus 40:9"
    ]
  },
  "Exodus 30:27": {
    "title": "Anoint the table, lampstand, and altars",
    "text": "The table, its vessels, lampstand, utensils, and both altars are to be anointed. The whole set of sanctuary furnishings is consecrated according to God’s command.",
    "refs": [
      "Exodus 40:9–11"
    ]
  },
  "Exodus 30:28": {
    "title": "Anoint the laver and altar utensils",
    "text": "The laver and its base, as well as the altar utensils, are to be anointed. The instruction includes the practical equipment used in the sanctuary’s regular service.",
    "refs": [
      "Exodus 40:11"
    ]
  },
  "Exodus 30:29": {
    "title": "The furnishings become holy",
    "text": "The anointed objects are set apart as holy, and whatever touches them is to be treated according to that sacred status. The language describes consecration within the tabernacle system.",
    "refs": [
      "Exodus 29:37"
    ]
  },
  "Exodus 30:30": {
    "title": "Anoint Aaron and his sons",
    "text": "Aaron and his sons are to be anointed and consecrated to serve as priests. Their office is established by God’s command and the prescribed ceremony.",
    "refs": [
      "Exodus 29:7–9"
    ]
  },
  "Exodus 30:31": {
    "title": "The oil is holy through generations",
    "text": "Israel is told that the anointing oil is holy throughout their generations. The designation is tied to its appointed sanctuary use.",
    "refs": [
      "Exodus 30:25"
    ]
  },
  "Exodus 30:32": {
    "title": "Do not use the formula casually",
    "text": "The oil must not be poured on an ordinary person or duplicated according to the sacred formula. The command protects the distinction between holy use and common use.",
    "refs": [
      "Exodus 30:33"
    ]
  },
  "Exodus 30:33": {
    "title": "Unauthorized use is forbidden",
    "text": "Anyone who makes a similar mixture for ordinary use or puts it on an unauthorized person is to be cut off from the people. The severe rule emphasizes that the holy oil is reserved for the purpose God appointed.",
    "refs": [
      "Exodus 30:32"
    ]
  },
  "Exodus 30:34": {
    "title": "Ingredients for the holy incense",
    "text": "God gives Moses the ingredients for the incense: stacte, onycha, galbanum, and pure frankincense, in equal portions. The recipe is part of the sanctuary’s prescribed worship.",
    "refs": [
      "Exodus 37:29"
    ]
  },
  "Exodus 30:35": {
    "title": "Incense made by a perfumer",
    "text": "The ingredients are made into incense, blended by a perfumer, pure and holy. The incense is prepared with care for its specific sacred use.",
    "refs": [
      "Exodus 30:34"
    ]
  },
  "Exodus 30:36": {
    "title": "Place some incense before the testimony",
    "text": "Some incense is beaten fine and placed before the testimony in the tent of meeting, where God meets Moses. It is most holy under the instructions given for the sanctuary.",
    "refs": [
      "Exodus 25:22"
    ]
  },
  "Exodus 30:37": {
    "title": "Do not make it for ordinary use",
    "text": "The incense may not be made in the same formula for personal use; it is to be regarded as holy to the LORD. The command preserves the distinction between worship and ordinary use of the sacred formula.",
    "refs": [
      "Exodus 30:35"
    ]
  },
  "Exodus 30:38": {
    "title": "Penalty for making incense for personal use",
    "text": "Anyone who makes the same incense to enjoy its fragrance is to be cut off from the people. The chapter ends by emphasizing that sacred things must be used according to God’s appointed purpose.",
    "refs": [
      "Exodus 30:37"
    ]
  },
  "Exodus 31:1": {
    "title": "Bezalel is called by name",
    "text": "The LORD identifies Bezalel son of Uri, from the tribe of Judah, as the person chosen for the work of the sanctuary. God’s detailed instructions include calling specific people to carry them out.",
    "refs": [
      "Exodus 35:30–33"
    ]
  },
  "Exodus 31:2": {
    "title": "God appoints a skilled craftsman",
    "text": "Bezalel is called by name and appointed for the work. His role shows that craftsmanship and practical skill can be part of faithful service to God.",
    "refs": [
      "1 Chronicles 28:19"
    ]
  },
  "Exodus 31:3": {
    "title": "Filled with the Spirit of God",
    "text": "God says He has filled Bezalel with the Spirit of God in wisdom, understanding, knowledge, and workmanship. Here the Spirit’s empowering is specifically connected with skill for sacred craftsmanship; the verse should not be reduced to a claim that the Spirit is merely a human talent.",
    "refs": [
      "Exodus 35:31",
      "Isaiah 11:2"
    ]
  },
  "Exodus 31:4": {
    "title": "Skillful designs in gold and other materials",
    "text": "Bezalel is equipped to devise artistic works in gold, silver, and bronze. The passage presents artistic design as a God-enabled ability used for the sanctuary.",
    "refs": [
      "Exodus 35:32"
    ]
  },
  "Exodus 31:5": {
    "title": "Cutting stones and carving wood",
    "text": "The work includes cutting stones for settings and carving wood, as well as other craftsmanship. The sanctuary requires a range of practical skills, not only preaching or public leadership.",
    "refs": [
      "Exodus 28:9–12"
    ]
  },
  "Exodus 31:6": {
    "title": "Oholiab and other skilled workers",
    "text": "God appoints Oholiab and gives skill to other wise-hearted workers so they can make everything commanded. The work is shared among several people; the Spirit-enabled project is not carried by one craftsman alone.",
    "refs": [
      "Exodus 35:34–35"
    ]
  },
  "Exodus 31:7": {
    "title": "The tent, ark, and mercy seat",
    "text": "The list begins with the tent of meeting, ark of the testimony, mercy seat, and furnishings. The craftsmen are to build the objects according to the pattern God gave Moses.",
    "refs": [
      "Exodus 25:9–22"
    ]
  },
  "Exodus 31:8": {
    "title": "The table and lampstand",
    "text": "The table and its vessels, the pure lampstand and its utensils, and the altar of incense are included in the work. The sacred furnishings are all part of one carefully prescribed sanctuary.",
    "refs": [
      "Exodus 25:23–40",
      "Exodus 30:1–10"
    ]
  },
  "Exodus 31:9": {
    "title": "The altar and laver",
    "text": "The burnt-offering altar and its utensils, the laver and its base, are included. The list covers the main objects used in the courtyard’s sacrificial and washing service.",
    "refs": [
      "Exodus 27:1–8",
      "Exodus 30:17–21"
    ]
  },
  "Exodus 31:10": {
    "title": "The holy garments",
    "text": "The service includes the finely worked garments for Aaron and his sons. Their clothing is part of the sanctuary’s sacred arrangement and must be made according to God’s instructions.",
    "refs": [
      "Exodus 28:1–43"
    ]
  },
  "Exodus 31:11": {
    "title": "Oil and incense made as commanded",
    "text": "The anointing oil and the incense are to be made according to God’s instructions. The chapter reiterates that both the physical sanctuary and its ritual materials are governed by divine direction.",
    "refs": [
      "Exodus 30:22–38"
    ]
  },
  "Exodus 31:12": {
    "title": "The LORD speaks about the Sabbath",
    "text": "The LORD gives Moses a further command concerning the Sabbath. After instructions for building the sanctuary, the text reminds Israel that worship work does not cancel the Sabbath command.",
    "refs": [
      "Exodus 20:8–11"
    ]
  },
  "Exodus 31:13": {
    "title": "The Sabbath is a sign",
    "text": "Israel is to keep God’s Sabbaths as a sign between Him and them throughout their generations, so they may know that the LORD sanctifies them. The sign marks Israel’s covenant relationship and God’s work of setting them apart.",
    "refs": [
      "Ezekiel 20:12",
      "Exodus 20:12"
    ]
  },
  "Exodus 31:14": {
    "title": "Keep the Sabbath holy",
    "text": "The Sabbath is holy to Israel, and the law gives a severe penalty for profaning it. This is part of Israel’s covenant legal order at Sinai; its specific civil penalty should not be transferred carelessly into modern settings.",
    "refs": [
      "Exodus 20:8–11"
    ]
  },
  "Exodus 31:15": {
    "title": "Six days of work, seventh day rest",
    "text": "Six days are appointed for work, but the seventh is a Sabbath of rest, holy to the LORD. The instruction establishes a rhythm of labor and rest even while the tabernacle is being built.",
    "refs": [
      "Genesis 2:2–3"
    ]
  },
  "Exodus 31:16": {
    "title": "Israel keeps the Sabbath through generations",
    "text": "The children of Israel are to observe the Sabbath throughout their generations as a perpetual covenant. The practice serves as a lasting sign within Israel’s covenant life.",
    "refs": [
      "Exodus 31:13"
    ]
  },
  "Exodus 31:17": {
    "title": "God rested on the seventh day",
    "text": "The Sabbath is a sign between the LORD and Israel because God made heaven and earth in six days and rested on the seventh. The language draws on the creation account to ground Israel’s weekly rest in God’s own pattern.",
    "refs": [
      "Genesis 2:2–3",
      "Exodus 20:11"
    ]
  },
  "Exodus 31:18": {
    "title": "The two tables of testimony",
    "text": "God gives Moses two stone tablets written with the finger of God. The expression emphasizes the divine origin and authority of the covenant testimony; it is not a literal anatomy lesson about God’s Spirit.",
    "refs": [
      "Deuteronomy 9:10",
      "Luke 11:20"
    ]
  },
  "Exodus 32:1": {
    "title": "The people demand a visible god",
    "text": "When Moses delays on the mountain, the people gather around Aaron and ask him to make gods to go before them. Their demand reveals impatience and distrust, and it begins a direct violation of the commandments they had just agreed to obey.",
    "refs": [
      "Exodus 20:3–4",
      "Deuteronomy 9:12"
    ]
  },
  "Exodus 32:2": {
    "title": "Aaron asks for gold earrings",
    "text": "Aaron tells the people to remove the gold earrings from their wives, sons, and daughters and bring them to him. The narrative shows Aaron yielding to the crowd rather than firmly upholding the covenant command.",
    "refs": [
      "Exodus 32:1"
    ]
  },
  "Exodus 32:3": {
    "title": "The people give their gold",
    "text": "The people remove their gold earrings and bring them to Aaron. Their willing contribution supplies the material for the idol they have demanded.",
    "refs": [
      "Exodus 32:2–4"
    ]
  },
  "Exodus 32:4": {
    "title": "The golden calf is made",
    "text": "Aaron fashions the gold into a molten calf, and the people declare that this is the god who brought them out of Egypt. The statement is a serious misattribution: the LORD had delivered Israel, and the people now attach His saving act to an image.",
    "refs": [
      "Exodus 20:3–4",
      "Nehemiah 9:18"
    ]
  },
  "Exodus 32:5": {
    "title": "Aaron builds an altar",
    "text": "Aaron sees the calf and builds an altar before it, announcing a feast to the LORD for the next day. By connecting the image with the LORD’s name, the people mix worship language with idolatry; invoking God’s name does not make an unauthorized image acceptable.",
    "refs": [
      "Exodus 20:4–5"
    ]
  },
  "Exodus 32:6": {
    "title": "The people feast and play",
    "text": "The people rise early, offer sacrifices, eat and drink, and rise to play. The account portrays their worship gathering as corrupted by the idol they have made.",
    "refs": [
      "1 Corinthians 10:7"
    ]
  },
  "Exodus 32:7": {
    "title": "God tells Moses what Israel has done",
    "text": "The LORD tells Moses to go down because the people have corrupted themselves. God identifies the wrongdoing plainly and does not treat the golden calf as an innocent cultural variation.",
    "refs": [
      "Deuteronomy 9:12"
    ]
  },
  "Exodus 32:8": {
    "title": "Israel turns aside quickly",
    "text": "God says Israel has quickly departed from the way He commanded, making and worshipping a calf. Their actions directly contradict the covenant words they had accepted.",
    "refs": [
      "Exodus 24:3",
      "Exodus 20:3–5"
    ]
  },
  "Exodus 32:9": {
    "title": "A stiff-necked people",
    "text": "The LORD describes Israel as stiff-necked. The phrase depicts stubborn resistance to God’s direction, not a claim about their physical bodies.",
    "refs": [
      "Exodus 33:3",
      "Deuteronomy 9:6"
    ]
  },
  "Exodus 32:10": {
    "title": "God speaks of judgment",
    "text": "God tells Moses to let Him alone so His anger may be kindled against the people, and He speaks of making a great nation from Moses. The passage presents a severe judgment warning that leads Moses to intercede for Israel.",
    "refs": [
      "Numbers 14:11–20"
    ]
  },
  "Exodus 32:11": {
    "title": "Moses pleads with the LORD",
    "text": "Moses entreats the LORD and appeals to the people whom God brought out of Egypt with great power. His prayer rests on God’s own saving work rather than Israel’s merit.",
    "refs": [
      "Deuteronomy 9:26–29"
    ]
  },
  "Exodus 32:12": {
    "title": "Moses appeals to God’s reputation",
    "text": "Moses asks why the Egyptians should be able to say God brought Israel out to destroy them in the mountains. He appeals to God’s public name and purpose among the nations.",
    "refs": [
      "Numbers 14:13–16"
    ]
  },
  "Exodus 32:13": {
    "title": "Remember Abraham, Isaac, and Israel",
    "text": "Moses asks God to remember the oath made to Abraham, Isaac, and Israel concerning their descendants and the land. The prayer appeals to God’s covenant promise, not to a claim that God has literally forgotten it.",
    "refs": [
      "Genesis 22:16–18",
      "Genesis 26:3–4"
    ]
  },
  "Exodus 32:14": {
    "title": "The LORD relents from the threatened judgment",
    "text": "The text says the LORD repented of the evil He had said He would do to His people. In context, God responds to Moses’ intercession and does not carry out the announced destruction in the form threatened; this language describes a change in the announced course of action, not moral wrongdoing in God.",
    "refs": [
      "Numbers 23:19",
      "Jeremiah 18:7–10"
    ]
  },
  "Exodus 32:15": {
    "title": "Moses descends with the tablets",
    "text": "Moses turns and goes down the mountain with the two tablets of testimony in his hands. The tablets are written on both sides, underscoring their status as the covenant document God has given.",
    "refs": [
      "Exodus 31:18"
    ]
  },
  "Exodus 32:16": {
    "title": "The tablets are God’s work",
    "text": "The tablets and their writing are described as the work of God. The verse emphasizes their divine origin and the authority of the words they contain.",
    "refs": [
      "Exodus 24:12"
    ]
  },
  "Exodus 32:17": {
    "title": "Joshua hears the noise",
    "text": "Joshua hears the noise of the people and thinks it sounds like war in the camp. He has not yet seen the calf and misinterprets the sound.",
    "refs": [
      "Exodus 24:13"
    ]
  },
  "Exodus 32:18": {
    "title": "Moses identifies the sound",
    "text": "Moses says the noise is neither a victory song nor a cry of defeat, but singing. He knows that something is wrong in the camp, and the next verse reveals the idolatry.",
    "refs": [
      "Exodus 32:19"
    ]
  },
  "Exodus 32:19": {
    "title": "Moses breaks the tablets",
    "text": "When Moses sees the calf and dancing, he casts the tablets down and breaks them at the foot of the mountain. The act visibly reflects the people’s breaking of the covenant; the text records Moses’ anger without making every angry act a model for imitation.",
    "refs": [
      "Deuteronomy 9:16–17"
    ]
  },
  "Exodus 32:20": {
    "title": "The calf is destroyed",
    "text": "Moses burns the calf, grinds it to powder, scatters it on the water, and makes Israel drink it. The action demonstrates that the idol is powerless and can be reduced to dust, not that it is a living deity.",
    "refs": [
      "Deuteronomy 9:21"
    ]
  },
  "Exodus 32:21": {
    "title": "Moses questions Aaron",
    "text": "Moses asks Aaron what the people did to him that he brought such a great sin upon them. The question confronts Aaron’s responsibility as the leader who participated in making the calf.",
    "refs": [
      "Exodus 32:2–6"
    ]
  },
  "Exodus 32:22": {
    "title": "Aaron blames the people",
    "text": "Aaron tells Moses not to be angry and says the people are set on evil. His answer shifts attention toward the crowd instead of fully owning his part in the sin.",
    "refs": [
      "Exodus 32:1–4"
    ]
  },
  "Exodus 32:23": {
    "title": "The people asked for gods",
    "text": "Aaron recounts that the people demanded gods to go before them because Moses had delayed. The explanation repeats their demand but does not excuse Aaron’s decision to make the calf.",
    "refs": [
      "Exodus 32:1"
    ]
  },
  "Exodus 32:24": {
    "title": "Aaron’s account of the calf",
    "text": "Aaron says he threw the gold into the fire and the calf came out. His explanation avoids acknowledging the craftsmanship he had used, and the narrative has already stated that he fashioned the calf with a graving tool.",
    "refs": [
      "Exodus 32:4"
    ]
  },
  "Exodus 32:25": {
    "title": "The people are out of control",
    "text": "Moses sees that the people are naked or exposed in the sense described by the KJV wording, because Aaron had allowed them to become a disgrace before their enemies. The verse portrays the community’s loss of restraint and public shame.",
    "refs": [
      "Exodus 32:6"
    ]
  },
  "Exodus 32:26": {
    "title": "Who is on the LORD’s side?",
    "text": "Moses stands at the camp gate and calls for those on the LORD’s side to come to him; the sons of Levi gather to him. The call demands a clear choice after the people have violated the covenant.",
    "refs": [
      "Joshua 24:15"
    ]
  },
  "Exodus 32:27": {
    "title": "A severe judgment in the camp",
    "text": "Moses gives the Levites a command to go through the camp and execute judgment. This is a specific episode of covenant judgment in ancient Israel’s history, not authorization for private violence or for modern believers to punish religious disagreement.",
    "refs": [
      "Deuteronomy 13:6–11"
    ]
  },
  "Exodus 32:28": {
    "title": "The judgment is carried out",
    "text": "The Levites do as Moses commanded, and about three thousand men fall that day. The verse records the severity of the covenant crisis and the consequences of the idolatry; it should not be detached from its unique historical and covenant setting.",
    "refs": [
      "Exodus 32:27"
    ]
  },
  "Exodus 32:29": {
    "title": "The Levites are set apart for service",
    "text": "Moses tells the Levites to consecrate themselves to the LORD because they acted decisively in the crisis. The statement belongs to the episode’s judgment and appointment context and should be read with the later development of the Levitical service.",
    "refs": [
      "Numbers 3:5–13"
    ]
  },
  "Exodus 32:30": {
    "title": "Moses returns to seek atonement",
    "text": "The next day Moses tells the people they have committed a great sin and says he will go up to the LORD to seek atonement. The leader does not minimize the wrongdoing but intercedes for the guilty people.",
    "refs": [
      "Exodus 32:11–14"
    ]
  },
  "Exodus 32:31": {
    "title": "Moses confesses Israel’s sin",
    "text": "Moses returns to the LORD and openly acknowledges that the people have made a golden god. His prayer does not conceal the nature of their offense.",
    "refs": [
      "Exodus 32:4"
    ]
  },
  "Exodus 32:32": {
    "title": "Moses offers himself in intercession",
    "text": "Moses asks God to forgive the people, and if not, to blot him out of the book God has written. This is an intense expression of intercession and solidarity; the text does not say Moses can literally atone for Israel’s sin by his own life.",
    "refs": [
      "Romans 9:3"
    ]
  },
  "Exodus 32:33": {
    "title": "Each person is accountable",
    "text": "The LORD answers that whoever has sinned against Him will be blotted out of His book. The reply stresses personal accountability before God and does not accept Moses as a substitute for the guilty.",
    "refs": [
      "Ezekiel 18:20"
    ]
  },
  "Exodus 32:34": {
    "title": "God’s messenger will lead Israel",
    "text": "God tells Moses to lead the people to the place He has spoken of and says His angel will go before them. God will still address the people’s sin in His appointed time; continued guidance does not mean the offense is ignored.",
    "refs": [
      "Exodus 23:20",
      "Exodus 33:2"
    ]
  },
  "Exodus 32:35": {
    "title": "The LORD sends a plague",
    "text": "The LORD plagues the people because they made the calf Aaron fashioned. The chapter ends by affirming that idolatry has real consequences and that Aaron’s involvement does not remove responsibility from the people.",
    "refs": [
      "Exodus 32:4",
      "Numbers 11:33"
    ]
  },
  "Exodus 33:1": {
    "title": "Continue toward the promised land",
    "text": "The LORD tells Moses to depart with the people toward the land promised to Abraham, Isaac, and Jacob. Despite Israel’s sin, God’s covenant purpose for the journey has not disappeared.",
    "refs": [
      "Genesis 12:7",
      "Exodus 32:34"
    ]
  },
  "Exodus 33:2": {
    "title": "God will send an angel before Israel",
    "text": "God says He will send an angel before Israel and drive out the peoples of Canaan. The promise of guidance continues, though the next verses reveal a serious question about God’s presence among the people.",
    "refs": [
      "Exodus 23:20–23"
    ]
  },
  "Exodus 33:3": {
    "title": "A warning about God’s presence",
    "text": "God calls the people stiff-necked and says He will not go up in their midst lest He consume them on the way. The warning shows the seriousness of Israel’s sin and the tension between God’s holiness and a rebellious people.",
    "refs": [
      "Exodus 32:9–10"
    ]
  },
  "Exodus 33:4": {
    "title": "The people mourn",
    "text": "When the people hear the bad news, they mourn and remove their ornaments. Their response reflects grief and the seriousness of the threatened loss of God’s presence.",
    "refs": [
      "Exodus 32:1–6"
    ]
  },
  "Exodus 33:5": {
    "title": "Remove the ornaments",
    "text": "The LORD tells Israel to remove their ornaments while He considers what to do with them. The instruction calls for humility rather than celebration after the golden calf incident.",
    "refs": [
      "Exodus 32:2–4"
    ]
  },
  "Exodus 33:6": {
    "title": "Israel leaves its ornaments at Horeb",
    "text": "The people strip themselves of ornaments from Mount Horeb onward. The action marks a visible response to God’s rebuke and the gravity of their covenant failure.",
    "refs": [
      "Exodus 33:4–5"
    ]
  },
  "Exodus 33:7": {
    "title": "The tent outside the camp",
    "text": "Moses takes a tent and pitches it outside the camp, calling it the tent of meeting. Those seeking the LORD go out to this tent, a sign of the distance created by the people’s sin and the continuing opportunity to seek God.",
    "refs": [
      "Exodus 25:8",
      "Exodus 29:42–43"
    ]
  },
  "Exodus 33:8": {
    "title": "The people stand at their tent doors",
    "text": "When Moses goes out to the tent, the people rise and stand at their own tent doors, watching him. Their posture shows that they recognize the importance of Moses’ meeting with the LORD.",
    "refs": [
      "Exodus 33:9"
    ]
  },
  "Exodus 33:9": {
    "title": "The pillar of cloud descends",
    "text": "When Moses enters the tent, the pillar of cloud descends and stands at its entrance, and the LORD speaks with Moses. The cloud is a visible sign of God’s presence and communication, not a limit on God’s being.",
    "refs": [
      "Exodus 13:21–22",
      "Numbers 12:5–8"
    ]
  },
  "Exodus 33:10": {
    "title": "The people worship at their tent doors",
    "text": "When the people see the pillar of cloud, they stand and worship at their tent doors. The visible sign prompts reverence as Moses speaks with God.",
    "refs": [
      "Exodus 33:9"
    ]
  },
  "Exodus 33:11": {
    "title": "The LORD speaks to Moses face to face",
    "text": "The LORD speaks with Moses face to face, as a man speaks to his friend, and Joshua remains in the tent. The phrase describes direct, personal communication in contrast to riddles or distant reports; it does not mean Moses comprehended the full essence of the infinite God.",
    "refs": [
      "Numbers 12:6–8",
      "Deuteronomy 34:10"
    ]
  },
  "Exodus 33:12": {
    "title": "Moses asks whom God will send",
    "text": "Moses reminds the LORD that He has told him to lead the people but has not fully disclosed whom He will send with him. Moses appeals to the relationship and favor God has shown him as he seeks clarity for the mission.",
    "refs": [
      "Exodus 3:12"
    ]
  },
  "Exodus 33:13": {
    "title": "Show me Your way",
    "text": "Moses asks God to show him His way so he may know Him and find favor, and to remember that Israel is God’s people. The request seeks deeper knowledge of God’s character and guidance for leading the people.",
    "refs": [
      "Psalm 25:4–5"
    ]
  },
  "Exodus 33:14": {
    "title": "My presence shall go with thee",
    "text": "God promises, “My presence shall go with thee, and I will give thee rest.” The answer directly addresses Moses’ concern: the mission depends on God’s own presence, not merely an angelic escort.",
    "refs": [
      "Deuteronomy 4:37",
      "Matthew 28:20"
    ]
  },
  "Exodus 33:15": {
    "title": "Moses will not go without God’s presence",
    "text": "Moses says that if God’s presence does not go with them, he does not want them to leave that place. Israel’s distinction among the nations depends on God’s presence, not simply on territory or military success.",
    "refs": [
      "Exodus 33:16"
    ]
  },
  "Exodus 33:16": {
    "title": "God’s presence distinguishes Israel",
    "text": "Moses asks how anyone will know that he and the people have found favor unless God goes with them. The LORD’s presence, not Israel’s own greatness, marks them as His people.",
    "refs": [
      "Deuteronomy 4:7–8"
    ]
  },
  "Exodus 33:17": {
    "title": "God grants Moses’ request",
    "text": "The LORD says He will do what Moses has asked because Moses has found favor and is known by name. The language describes a personal relationship and God’s gracious response to Moses’ intercession.",
    "refs": [
      "Exodus 33:12–14"
    ]
  },
  "Exodus 33:18": {
    "title": "Moses asks to see God’s glory",
    "text": "Moses asks the LORD to show him His glory. The request seeks a fuller revelation of God’s presence and character, and the following verses explain both what God will reveal and what Moses cannot see.",
    "refs": [
      "Exodus 24:16–17"
    ]
  },
  "Exodus 33:19": {
    "title": "God proclaims His goodness and mercy",
    "text": "God promises to make His goodness pass before Moses and proclaim His name, showing mercy and compassion according to His sovereign will. The verse connects God’s glory with His character and graciousness, not merely a visible appearance.",
    "refs": [
      "Exodus 34:5–7",
      "Romans 9:15"
    ]
  },
  "Exodus 33:20": {
    "title": "No one sees God’s face and lives",
    "text": "God says Moses cannot see His face, for no man can see Him and live. This qualifies the earlier “face to face” language as personal communication rather than a complete vision of God’s unveiled essence.",
    "refs": [
      "Exodus 33:11",
      "John 1:18",
      "1 Timothy 6:16"
    ]
  },
  "Exodus 33:21": {
    "title": "A place beside God",
    "text": "God tells Moses there is a place beside Him where Moses can stand on the rock. The text describes a special provision for the revelation that follows.",
    "refs": [
      "Exodus 33:22"
    ]
  },
  "Exodus 33:22": {
    "title": "God covers Moses in the cleft",
    "text": "When God’s glory passes, He will put Moses in a cleft of the rock and cover him with His hand until He has passed by. The language describes protective accommodation for a limited human witness to divine glory.",
    "refs": [
      "Exodus 34:5–6"
    ]
  },
  "Exodus 33:23": {
    "title": "Moses sees God’s back",
    "text": "God removes His hand and Moses sees His back, but not His face. The passage uses human imagery to describe a limited manifestation; it does not provide a literal anatomy of God or cancel the Bible’s teaching that God is Spirit.",
    "refs": [
      "John 4:24",
      "John 1:18"
    ]
  },
  "Exodus 34:1": {
    "title": "New stone tablets",
    "text": "The LORD tells Moses to hew two stone tablets like the first, promising to write on them the words that were on the broken tablets. The covenant words remain central even after Israel’s grave sin.",
    "refs": [
      "Exodus 32:19",
      "Deuteronomy 10:1–4"
    ]
  },
  "Exodus 34:2": {
    "title": "Come up in the morning",
    "text": "Moses is told to be ready in the morning and come up Mount Sinai to stand before God. The new meeting follows the covenant crisis and God’s response to Moses’ intercession.",
    "refs": [
      "Exodus 33:18–23"
    ]
  },
  "Exodus 34:3": {
    "title": "No one else may ascend",
    "text": "No person is to come up with Moses, and no livestock may graze near the mountain. The restrictions preserve the boundary around this special encounter with God.",
    "refs": [
      "Exodus 19:12–13"
    ]
  },
  "Exodus 34:4": {
    "title": "Moses obeys and ascends",
    "text": "Moses hews two stone tablets and rises early to ascend Sinai as the LORD commanded. His action prepares for the renewal of the covenant words.",
    "refs": [
      "Exodus 34:1–2"
    ]
  },
  "Exodus 34:5": {
    "title": "The LORD descends in the cloud",
    "text": "The LORD descends in the cloud, stands with Moses, and proclaims the name of the LORD. The focus is on God revealing His name and character after the people’s idolatry.",
    "refs": [
      "Exodus 3:14–15",
      "Exodus 33:19"
    ]
  },
  "Exodus 34:6": {
    "title": "The LORD is merciful and gracious",
    "text": "The LORD proclaims Himself merciful, gracious, longsuffering, abundant in goodness and truth. God’s own description of His character becomes a foundational declaration repeated throughout Scripture.",
    "refs": [
      "Numbers 14:18",
      "Psalm 103:8",
      "Joel 2:13"
    ]
  },
  "Exodus 34:7": {
    "title": "Mercy, forgiveness, and justice",
    "text": "God continues by declaring mercy to thousands, forgiving iniquity, transgression, and sin, yet not simply clearing the guilty and visiting the consequences of iniquity across generations. The verse holds together divine compassion and moral seriousness; it should be read with the wider biblical teaching about personal responsibility and repentance.",
    "refs": [
      "Deuteronomy 24:16",
      "Ezekiel 18:20",
      "Nahum 1:3"
    ]
  },
  "Exodus 34:8": {
    "title": "Moses bows in worship",
    "text": "Moses quickly bows his head and worships after hearing God’s name and character proclaimed. Revelation of who God is leads Moses to reverence.",
    "refs": [
      "Exodus 4:31"
    ]
  },
  "Exodus 34:9": {
    "title": "Moses asks God to go among Israel",
    "text": "Moses asks the LORD to go among the people, even though they are stiff-necked, and to pardon their sin and take them as His inheritance. The prayer appeals to God’s mercy and covenant relationship after Israel’s failure.",
    "refs": [
      "Exodus 33:14–16"
    ]
  },
  "Exodus 34:10": {
    "title": "God renews the covenant",
    "text": "God declares that He will make a covenant and do wonders unlike those seen among the nations. Israel will witness the LORD’s work, and the surrounding peoples will see His power.",
    "refs": [
      "Deuteronomy 4:32–35"
    ]
  },
  "Exodus 34:11": {
    "title": "Obey God’s commands in the land",
    "text": "Israel is commanded to observe what God commands, and He promises to drive out the peoples of the land. The promise is joined to obedience within the covenant arrangement.",
    "refs": [
      "Exodus 23:20–31"
    ]
  },
  "Exodus 34:12": {
    "title": "Do not make a covenant with the inhabitants",
    "text": "Israel must take care not to make a covenant with the peoples of the land, lest their practices become a snare. The warning concerns covenant loyalty and the danger of being drawn into idolatry.",
    "refs": [
      "Deuteronomy 7:2–4"
    ]
  },
  "Exodus 34:13": {
    "title": "Destroy idolatrous objects",
    "text": "Israel is commanded to break down altars, images, and sacred pillars associated with the land’s worship. The instruction is specific to Israel’s covenant entry into Canaan and its prohibition of idolatry; it is not a general mandate for modern believers to destroy other people’s property.",
    "refs": [
      "Deuteronomy 12:2–4"
    ]
  },
  "Exodus 34:14": {
    "title": "The LORD is jealous for His name",
    "text": "God says Israel must not worship another god, for the LORD is jealous and is named Jealous. The language expresses exclusive covenant loyalty: Israel is not to divide worship between the LORD and idols.",
    "refs": [
      "Exodus 20:3–5",
      "Deuteronomy 6:4–5"
    ]
  },
  "Exodus 34:15": {
    "title": "Idolatry and covenant compromise",
    "text": "God warns against making a covenant with the inhabitants who sacrifice to their gods and invite Israel to join. The danger is that social and religious participation will lead Israel away from the LORD.",
    "refs": [
      "Numbers 25:1–3"
    ]
  },
  "Exodus 34:16": {
    "title": "Marriage and idolatrous influence",
    "text": "The warning continues that intermarriage may lead Israel’s sons to worship other gods. In context, the concern is covenant apostasy and idolatry; the verse should not be detached from that setting to justify contempt for people of another ethnicity.",
    "refs": [
      "Deuteronomy 7:3–4"
    ]
  },
  "Exodus 34:17": {
    "title": "Do not make molten gods",
    "text": "Israel is again forbidden to make molten gods. The repetition after the golden calf incident directly addresses the sin that nearly destroyed the covenant relationship.",
    "refs": [
      "Exodus 32:4"
    ]
  },
  "Exodus 34:18": {
    "title": "Keep the Feast of Unleavened Bread",
    "text": "Israel must keep the Feast of Unleavened Bread at the appointed time in Abib, remembering the exodus. The feast remains tied to the deliverance by which God brought Israel out of Egypt.",
    "refs": [
      "Exodus 12:14–20"
    ]
  },
  "Exodus 34:19": {
    "title": "The firstborn belongs to God",
    "text": "God claims all that opens the womb, including the firstborn male livestock. The instruction recalls the firstborn ordinance established after the final plague.",
    "refs": [
      "Exodus 13:1–2"
    ]
  },
  "Exodus 34:20": {
    "title": "Redeem the firstborn and appear before God",
    "text": "A firstborn donkey may be redeemed with a lamb or its neck broken, and firstborn sons must be redeemed; none is to appear before God empty-handed. The command combines the firstborn ordinance with the obligation to bring offerings in worship.",
    "refs": [
      "Exodus 13:13",
      "Exodus 23:15"
    ]
  },
  "Exodus 34:21": {
    "title": "Sabbath during planting and harvest",
    "text": "Israel must rest on the seventh day even during plowing time and harvest. The Sabbath is not to be set aside simply because work is urgent or seasonal.",
    "refs": [
      "Exodus 20:8–11"
    ]
  },
  "Exodus 34:22": {
    "title": "The Feast of Weeks and Ingathering",
    "text": "Israel is to observe the Feast of Weeks at the firstfruits of wheat harvest and the Feast of Ingathering at year’s end. The feasts mark gratitude for God’s provision through the agricultural year.",
    "refs": [
      "Leviticus 23:15–22",
      "Deuteronomy 16:9–15"
    ]
  },
  "Exodus 34:23": {
    "title": "All males appear before the LORD",
    "text": "Three times a year all males are to appear before the Lord GOD, the God of Israel. The command emphasizes regular communal worship before the covenant God.",
    "refs": [
      "Exodus 23:17"
    ]
  },
  "Exodus 34:24": {
    "title": "God protects Israel’s land during the feasts",
    "text": "God promises to drive out nations and enlarge Israel’s borders so no one will covet the land while the men appear before Him three times a year. The promise addresses the practical concern that pilgrimage might leave the land vulnerable.",
    "refs": [
      "Deuteronomy 16:16"
    ]
  },
  "Exodus 34:25": {
    "title": "Sacrificial blood and Passover leftovers",
    "text": "The blood of sacrifice is not to be offered with leaven, and the Passover sacrifice must not remain until morning. The instruction preserves the distinct requirements of Israel’s sacred meals and offerings.",
    "refs": [
      "Exodus 12:10",
      "Exodus 23:18"
    ]
  },
  "Exodus 34:26": {
    "title": "Firstfruits and a prohibition about a kid",
    "text": "Israel is to bring the first of the firstfruits to the LORD’s house, and the verse repeats the command not to boil a kid in its mother’s milk. The firstfruits express gratitude to God; the text does not explain the precise reason for the latter prohibition, so proposed explanations should be treated as interpretations.",
    "refs": [
      "Exodus 23:19",
      "Deuteronomy 26:1–11"
    ]
  },
  "Exodus 34:27": {
    "title": "Write the covenant words",
    "text": "The LORD tells Moses to write these words because according to them He has made a covenant with Israel. The written words preserve the covenant requirements for the community.",
    "refs": [
      "Exodus 24:4",
      "Deuteronomy 31:24–26"
    ]
  },
  "Exodus 34:28": {
    "title": "Forty days and nights with the LORD",
    "text": "Moses remains with the LORD forty days and nights without eating bread or drinking water, and he writes the covenant words on the tablets. Deuteronomy 9:9–10 also describes this period; the passage emphasizes the extraordinary nature of Moses’ encounter and the divine origin of the covenant testimony.",
    "refs": [
      "Deuteronomy 9:9–11"
    ]
  },
  "Exodus 34:29": {
    "title": "Moses’ face shines",
    "text": "When Moses descends with the tablets, he does not know that the skin of his face shines because he has spoken with God. The visible radiance marks the encounter with the LORD and is later discussed by Paul in relation to the old covenant’s glory.",
    "refs": [
      "2 Corinthians 3:7–13"
    ]
  },
  "Exodus 34:30": {
    "title": "Aaron and Israel fear Moses’ face",
    "text": "Aaron and the people are afraid to approach Moses when they see the radiance of his face. Their reaction shows the visible effect of Moses’ encounter with God.",
    "refs": [
      "Exodus 34:29"
    ]
  },
  "Exodus 34:31": {
    "title": "Moses calls the leaders back",
    "text": "Moses calls Aaron and the congregation’s rulers, who return to him, and he speaks with them. The leaders receive the message before Moses addresses the whole community.",
    "refs": [
      "Exodus 34:32"
    ]
  },
  "Exodus 34:32": {
    "title": "Moses gives the commandments",
    "text": "Afterward the people come near, and Moses gives them all that the LORD has spoken on Sinai. The revelation is communicated to the community so they can live according to the covenant.",
    "refs": [
      "Exodus 24:3"
    ]
  },
  "Exodus 34:33": {
    "title": "Moses puts a veil on his face",
    "text": "When Moses finishes speaking, he puts a veil over his face. The veil becomes a significant image in Paul’s later discussion of the glory and limitations of the old covenant, but its immediate function here is to cover the radiance.",
    "refs": [
      "2 Corinthians 3:13"
    ]
  },
  "Exodus 34:34": {
    "title": "Moses removes the veil before the LORD",
    "text": "When Moses enters before the LORD to speak with Him, he removes the veil; when he comes out, he tells Israel what he has been commanded. The pattern distinguishes his direct meeting with God from his public delivery of the message.",
    "refs": [
      "Exodus 33:11"
    ]
  },
  "Exodus 34:35": {
    "title": "Israel sees the shining face",
    "text": "Israel sees the skin of Moses’ face shining, and Moses covers his face again until he goes in to speak with the LORD. The chapter ends with Moses serving as the mediator who receives God’s words and brings them to the people.",
    "refs": [
      "Exodus 34:29–34"
    ]
  },
  "Exodus 35:1": {
    "title": "Moses gathers the congregation",
    "text": "Moses gathers all Israel and repeats the LORD’s commandments. The instructions that follow turn the plans given on Sinai into the community’s actual work of building the sanctuary.",
    "refs": [
      "Exodus 25:1–9"
    ]
  },
  "Exodus 35:2": {
    "title": "Six days to work, seventh to rest",
    "text": "Israel is reminded to work six days and keep the seventh day holy as a Sabbath of rest. Even the work of building the tabernacle must not override the Sabbath command.",
    "refs": [
      "Exodus 20:8–11",
      "Exodus 31:12–17"
    ]
  },
  "Exodus 35:3": {
    "title": "No fire on the Sabbath",
    "text": "The people are told not to kindle a fire in their dwellings on the Sabbath. The instruction applies the Sabbath command to ordinary household activity in Israel’s covenant setting.",
    "refs": [
      "Exodus 16:23"
    ]
  },
  "Exodus 35:4": {
    "title": "An offering for the LORD",
    "text": "Moses tells Israel what the LORD commands concerning a contribution for the sanctuary. The materials are to be given according to the earlier instructions.",
    "refs": [
      "Exodus 25:1–7"
    ]
  },
  "Exodus 35:5": {
    "title": "A willing-hearted offering",
    "text": "Those who are willing are to bring an offering of gold, silver, bronze, and other materials. The work is supported by voluntary generosity, not simply by compulsion.",
    "refs": [
      "Exodus 25:2",
      "2 Corinthians 9:7"
    ]
  },
  "Exodus 35:6": {
    "title": "Colored yarn and fine linen",
    "text": "Blue, purple, scarlet, and fine linen are among the requested materials. These supplies will be used for the curtains and priestly garments.",
    "refs": [
      "Exodus 26:1",
      "Exodus 28:5"
    ]
  },
  "Exodus 35:7": {
    "title": "Skins and acacia wood",
    "text": "Ram skins, durable coverings, and acacia wood are requested for the tabernacle. The materials provide both protection and structure for the portable sanctuary.",
    "refs": [
      "Exodus 25:5"
    ]
  },
  "Exodus 35:8": {
    "title": "Oil and incense spices",
    "text": "Oil for the lamps and spices for anointing oil and incense are listed. Israel’s contribution supports not only the building but also its continuing worship.",
    "refs": [
      "Exodus 27:20",
      "Exodus 30:22–38"
    ]
  },
  "Exodus 35:9": {
    "title": "Stones for priestly service",
    "text": "Onyx stones and other precious stones are requested for the ephod and breastplate. The stones will carry the names of Israel’s tribes in the priestly service.",
    "refs": [
      "Exodus 28:9–21"
    ]
  },
  "Exodus 35:10": {
    "title": "Skilled workers are invited",
    "text": "Everyone who is wise-hearted among the people is to come and make what the LORD commanded. The sanctuary requires the service of many skilled hands.",
    "refs": [
      "Exodus 31:1–6"
    ]
  },
  "Exodus 35:11": {
    "title": "The tabernacle and its coverings",
    "text": "The tent, coverings, boards, bars, pillars, and sockets are listed as work to be made. The detailed list shows that the whole structure is to be assembled according to God’s pattern.",
    "refs": [
      "Exodus 26:1–30"
    ]
  },
  "Exodus 35:12": {
    "title": "The ark and its veil",
    "text": "The ark, staves, mercy seat, and veil are included among the sanctuary work. These objects are central to the covenant testimony and the prescribed approach to God.",
    "refs": [
      "Exodus 25:10–22",
      "Exodus 26:31–34"
    ]
  },
  "Exodus 35:13": {
    "title": "The table and its vessels",
    "text": "The table, staves, utensils, and showbread are listed. Their regular service will express Israel’s ongoing dependence on the LORD.",
    "refs": [
      "Exodus 25:23–30"
    ]
  },
  "Exodus 35:14": {
    "title": "The lampstand and its utensils",
    "text": "The lampstand, lamps, oil, and utensils are to be made. The lampstand provides light in the sanctuary as prescribed by God.",
    "refs": [
      "Exodus 25:31–40"
    ]
  },
  "Exodus 35:15": {
    "title": "The incense altar and anointing oil",
    "text": "The incense altar, anointing oil, incense, and entrance screen are included. These items serve the sanctuary’s worship and mark its entrance and furnishings as holy.",
    "refs": [
      "Exodus 30:1–38"
    ]
  },
  "Exodus 35:16": {
    "title": "The courtyard altar and laver",
    "text": "The burnt-offering altar, bronze grating, utensils, laver, and its base are listed. These objects support sacrifice and washing in the courtyard.",
    "refs": [
      "Exodus 27:1–8",
      "Exodus 30:17–21"
    ]
  },
  "Exodus 35:17": {
    "title": "The courtyard hangings",
    "text": "The hangings, pillars, sockets, and gate screen are to be made for the courtyard. The enclosure gives the sanctuary a defined outer space.",
    "refs": [
      "Exodus 27:9–19"
    ]
  },
  "Exodus 35:18": {
    "title": "Tent and courtyard pins",
    "text": "The pins and cords needed for the tabernacle and courtyard are included. Even small structural fittings are part of the work God has commanded.",
    "refs": [
      "Exodus 27:19"
    ]
  },
  "Exodus 35:19": {
    "title": "The holy garments",
    "text": "The service garments for Aaron and his sons are included in the list. The priests’ clothing is part of the sacred work and is to follow the pattern given to Moses.",
    "refs": [
      "Exodus 28:1–43"
    ]
  },
  "Exodus 35:20": {
    "title": "The people depart from Moses",
    "text": "The congregation leaves Moses after hearing the instructions. The next verses show that many respond by bringing gifts and offering their skills.",
    "refs": [
      "Exodus 35:21–29"
    ]
  },
  "Exodus 35:21": {
    "title": "Hearts stirred to give",
    "text": "Everyone whose heart is stirred and spirit is willing brings an offering for the tabernacle, its service, and the holy garments. The work advances through willing response to God’s purpose.",
    "refs": [
      "Exodus 25:2"
    ]
  },
  "Exodus 35:22": {
    "title": "Men and women bring jewelry",
    "text": "Men and women bring gold jewelry and other items as a freewill offering to the LORD. The text shows participation across the community, with gifts offered willingly.",
    "refs": [
      "Exodus 35:29"
    ]
  },
  "Exodus 35:23": {
    "title": "Materials are brought as needed",
    "text": "Those who have blue, purple, scarlet yarn, fine linen, skins, and other materials bring them. The varied contributions supply the different parts of the sanctuary project.",
    "refs": [
      "Exodus 25:4–7"
    ]
  },
  "Exodus 35:24": {
    "title": "Silver, bronze, and acacia wood",
    "text": "Those with silver or bronze bring it as an offering, and those with acacia wood bring it for the work. The community contributes according to what it has available.",
    "refs": [
      "Exodus 25:3–5"
    ]
  },
  "Exodus 35:25": {
    "title": "Women spin with skill",
    "text": "Wise-hearted women spin yarn with their hands and bring the results. The passage explicitly honors women’s skilled labor as part of the sanctuary’s construction.",
    "refs": [
      "Exodus 35:26"
    ]
  },
  "Exodus 35:26": {
    "title": "Women spin goats’ hair",
    "text": "Women whose hearts stir them to skillfully spin goats’ hair do so. Their craft supplies the material for the tent covering.",
    "refs": [
      "Exodus 26:7"
    ]
  },
  "Exodus 35:27": {
    "title": "Rulers bring precious stones",
    "text": "The rulers bring onyx and other stones for the ephod and breastplate. Their contribution provides the valuable materials needed for the high priest’s garments.",
    "refs": [
      "Exodus 28:9–21"
    ]
  },
  "Exodus 35:28": {
    "title": "Spices and oil are brought",
    "text": "The people bring spices, oil for the light, and ingredients for anointing oil and incense. The materials support both the physical sanctuary and its ritual service.",
    "refs": [
      "Exodus 30:22–38"
    ]
  },
  "Exodus 35:29": {
    "title": "Israel gives a willing offering",
    "text": "The people of Israel, men and women, bring willing offerings to the LORD for the work He commanded through Moses. The repeated emphasis on willingness shows that the sanctuary is built through shared generosity.",
    "refs": [
      "Exodus 35:21–22"
    ]
  },
  "Exodus 35:30": {
    "title": "Bezalel is named by God",
    "text": "Moses tells Israel that the LORD has called Bezalel by name, from the tribe of Judah. The skilled work is not merely human planning; God appoints workers for the task.",
    "refs": [
      "Exodus 31:1–2"
    ]
  },
  "Exodus 35:31": {
    "title": "Filled with the Spirit and wisdom",
    "text": "God fills Bezalel with His Spirit in wisdom, understanding, knowledge, and craftsmanship. This is a clear example of divine empowerment for practical work in service to God.",
    "refs": [
      "Exodus 31:3"
    ]
  },
  "Exodus 35:32": {
    "title": "Artistic work in precious materials",
    "text": "Bezalel can devise artistic designs in gold, silver, and bronze. The passage presents craftsmanship as a God-given skill used for the sanctuary.",
    "refs": [
      "Exodus 31:4"
    ]
  },
  "Exodus 35:33": {
    "title": "Stone setting and wood carving",
    "text": "Bezalel can cut stones, carve wood, and perform other skilled work. The range of abilities needed for the sanctuary is recognized as part of his calling.",
    "refs": [
      "Exodus 31:5"
    ]
  },
  "Exodus 35:34": {
    "title": "Oholiab is also appointed",
    "text": "God gives Bezalel and Oholiab the ability to teach others. The work includes passing on skill, so the project is shared rather than dependent on one expert alone.",
    "refs": [
      "Exodus 31:6"
    ]
  },
  "Exodus 35:35": {
    "title": "Wisdom for many kinds of work",
    "text": "God fills them with wisdom to do engraving, design, embroidery, and weaving in colored materials and fine linen. The chapter honors both design and execution as necessary parts of the sanctuary work.",
    "refs": [
      "Exodus 31:3–6"
    ]
  },
  "Exodus 36:1": {
    "title": "The skilled workers begin the work",
    "text": "Bezalel, Oholiab, and the wise-hearted workers are to make everything the LORD commanded. Their skill is exercised in obedience to God’s pattern rather than independent invention.",
    "refs": [
      "Exodus 31:1–6"
    ]
  },
  "Exodus 36:2": {
    "title": "Moses calls the willing workers",
    "text": "Moses calls Bezalel, Oholiab, and all whose hearts have stirred them to come to the work. The project gathers both appointed craftsmen and willing contributors.",
    "refs": [
      "Exodus 35:10"
    ]
  },
  "Exodus 36:3": {
    "title": "The offerings continue to arrive",
    "text": "The workers receive from Moses the contributions the people have brought, and people continue bringing freewill offerings each morning. The abundance shows how generously Israel has responded.",
    "refs": [
      "Exodus 35:21–29"
    ]
  },
  "Exodus 36:4": {
    "title": "The workers report an abundance",
    "text": "The skilled workers leave their tasks and come to Moses because the people have brought more than enough. The report leads Moses to stop further contributions.",
    "refs": [
      "Exodus 36:5"
    ]
  },
  "Exodus 36:5": {
    "title": "More than enough for the work",
    "text": "The workers tell Moses that the people have brought far more than is needed for the commanded work. Their generosity has exceeded the requirements.",
    "refs": [
      "Exodus 35:21–29"
    ]
  },
  "Exodus 36:6": {
    "title": "Moses stops the offerings",
    "text": "Moses commands that no more offering be brought for the sanctuary, and the people are restrained from giving more. This unusual moment shows that the contribution was sufficient and that the leaders did not exploit the people for endless giving.",
    "refs": [
      "Exodus 36:7"
    ]
  },
  "Exodus 36:7": {
    "title": "Enough material and more",
    "text": "The materials are sufficient for all the work, with some left over. The sanctuary project is supplied through the people’s willing contributions under God’s instruction.",
    "refs": [
      "Exodus 36:3–6"
    ]
  },
  "Exodus 36:8": {
    "title": "The fine inner curtains",
    "text": "The skilled workers make the tabernacle curtains from fine linen with blue, purple, and scarlet yarn, with cherubim woven into them. The actual construction now follows the design described earlier.",
    "refs": [
      "Exodus 26:1"
    ]
  },
  "Exodus 36:9": {
    "title": "Curtain measurements",
    "text": "The curtains are made to the specified lengths and widths. Exact measurements allow the pieces to fit together as planned.",
    "refs": [
      "Exodus 26:2"
    ]
  },
  "Exodus 36:10": {
    "title": "Curtains joined in two sets",
    "text": "The workers join five curtains together in each set. The joined sections form the full inner covering.",
    "refs": [
      "Exodus 26:3"
    ]
  },
  "Exodus 36:11": {
    "title": "Blue loops on the curtain edges",
    "text": "Loops of blue are made along the edge of each curtain set. The loops prepare the sections to be joined by clasps.",
    "refs": [
      "Exodus 26:4"
    ]
  },
  "Exodus 36:12": {
    "title": "Fifty loops on each side",
    "text": "The loops are made to match opposite one another, fifty on each curtain set. The matching arrangement allows the clasps to join the coverings evenly.",
    "refs": [
      "Exodus 26:5"
    ]
  },
  "Exodus 36:13": {
    "title": "Gold clasps make one tabernacle",
    "text": "The workers make fifty gold clasps and join the curtains so the tabernacle becomes one whole. The construction fulfills the design given on the mountain.",
    "refs": [
      "Exodus 26:6"
    ]
  },
  "Exodus 36:14": {
    "title": "The goats’ hair covering",
    "text": "The workers make eleven curtains of goats’ hair for the tent over the tabernacle. This outer covering protects the inner curtains.",
    "refs": [
      "Exodus 26:7"
    ]
  },
  "Exodus 36:15": {
    "title": "The outer curtains’ dimensions",
    "text": "The goats’ hair curtains are made to the specified dimensions. Their size is designed to cover the tabernacle as instructed.",
    "refs": [
      "Exodus 26:8"
    ]
  },
  "Exodus 36:16": {
    "title": "The curtains are joined",
    "text": "The workers join six curtains into one set and five into another. The joined pieces create the required shape of the outer tent covering.",
    "refs": [
      "Exodus 26:9"
    ]
  },
  "Exodus 36:17": {
    "title": "Loops for the outer covering",
    "text": "Fifty loops are made on the edge of one set and fifty on the edge of the other. The loops prepare the outer covering to be fastened together.",
    "refs": [
      "Exodus 26:10"
    ]
  },
  "Exodus 36:18": {
    "title": "Bronze clasps join the tent",
    "text": "Fifty bronze clasps are made to join the tent covering into one. The outer covering is connected according to the prescribed design.",
    "refs": [
      "Exodus 26:11"
    ]
  },
  "Exodus 36:19": {
    "title": "Additional protective coverings",
    "text": "The workers make the ram-skin covering dyed red and the outer covering of durable skins. These layers protect the tent from the weather.",
    "refs": [
      "Exodus 26:14"
    ]
  },
  "Exodus 36:20": {
    "title": "Upright boards of acacia wood",
    "text": "The workers make upright boards of acacia wood for the tabernacle. These form the supporting framework for the curtains and coverings.",
    "refs": [
      "Exodus 26:15"
    ]
  },
  "Exodus 36:21": {
    "title": "Board dimensions",
    "text": "Each board is made to the specified length and width. Consistent dimensions help the structure fit together securely.",
    "refs": [
      "Exodus 26:16"
    ]
  },
  "Exodus 36:22": {
    "title": "Tenons on the boards",
    "text": "Each board has two tenons set in order. These fit into the supporting sockets and hold the framework upright.",
    "refs": [
      "Exodus 26:17"
    ]
  },
  "Exodus 36:23": {
    "title": "Boards for the south side",
    "text": "Twenty boards are made for the south side of the tabernacle. The construction follows the measurements given to Moses.",
    "refs": [
      "Exodus 26:18"
    ]
  },
  "Exodus 36:24": {
    "title": "Silver sockets for the boards",
    "text": "Forty silver sockets are made for the south side, two under each board. The sockets anchor the boards securely.",
    "refs": [
      "Exodus 26:19"
    ]
  },
  "Exodus 36:25": {
    "title": "Boards for the north side",
    "text": "Twenty boards are made for the north side, matching the south side’s arrangement. The symmetry contributes to a stable framework.",
    "refs": [
      "Exodus 26:20"
    ]
  },
  "Exodus 36:26": {
    "title": "Forty sockets on the north side",
    "text": "The north side also receives forty silver sockets, two under each board. The repeated construction follows the plan precisely.",
    "refs": [
      "Exodus 26:21"
    ]
  },
  "Exodus 36:27": {
    "title": "Boards for the west side",
    "text": "Six boards are made for the west or rear side of the tabernacle. The number differs from the long sides because of the structure’s dimensions.",
    "refs": [
      "Exodus 26:22"
    ]
  },
  "Exodus 36:28": {
    "title": "Corner boards",
    "text": "Two boards are made for the corners at the rear. These pieces help stabilize the framework where the sides meet.",
    "refs": [
      "Exodus 26:23"
    ]
  },
  "Exodus 36:29": {
    "title": "The corner boards are joined",
    "text": "The corner boards are joined at the top and bottom by a ring. The special connection reinforces the rear corners of the structure.",
    "refs": [
      "Exodus 26:24"
    ]
  },
  "Exodus 36:30": {
    "title": "Eight boards and sixteen sockets",
    "text": "The west side has eight boards and sixteen sockets, two under each board. The count completes the main board framework.",
    "refs": [
      "Exodus 26:25"
    ]
  },
  "Exodus 36:31": {
    "title": "Bars for the boards",
    "text": "Bars of acacia wood are made to hold the boards together. They strengthen the structure and keep the boards aligned.",
    "refs": [
      "Exodus 26:26"
    ]
  },
  "Exodus 36:32": {
    "title": "Bars for the opposite side",
    "text": "Bars are made for the other side of the tabernacle as instructed. The bars bind the boards into one supporting framework.",
    "refs": [
      "Exodus 26:27"
    ]
  },
  "Exodus 36:33": {
    "title": "The middle bar extends end to end",
    "text": "The middle bar runs through the boards from one end to the other. This central support helps unify the framework.",
    "refs": [
      "Exodus 26:28"
    ]
  },
  "Exodus 36:34": {
    "title": "Boards and bars overlaid with gold",
    "text": "The boards and their rings are overlaid with gold, and the bars are also covered with gold. The construction follows the materials and pattern God prescribed.",
    "refs": [
      "Exodus 26:29"
    ]
  },
  "Exodus 36:35": {
    "title": "The veil is made",
    "text": "The workers make the veil of fine linen with blue, purple, scarlet, and cherubim. The veil separates the holy place from the most holy place.",
    "refs": [
      "Exodus 26:31"
    ]
  },
  "Exodus 36:36": {
    "title": "Pillars for the veil",
    "text": "Four acacia pillars are made for the veil and overlaid with gold, with silver sockets. The pillars support the boundary within the sanctuary.",
    "refs": [
      "Exodus 26:32"
    ]
  },
  "Exodus 36:37": {
    "title": "The entrance screen",
    "text": "The workers make the screen for the tabernacle entrance from embroidered colored fabric and fine linen. The entrance screen matches the sacred design of the sanctuary.",
    "refs": [
      "Exodus 26:36"
    ]
  },
  "Exodus 36:38": {
    "title": "Five pillars for the screen",
    "text": "Five pillars with hooks are made for the entrance screen, and their tops and bands are overlaid with gold while the sockets are bronze. The entrance structure completes the framework described in the plan.",
    "refs": [
      "Exodus 26:37"
    ]
  },
  "Exodus 37:1": {
    "title": "The ark is constructed",
    "text": "Bezalel makes the ark of acacia wood according to the dimensions God gave Moses. The construction now carries out the design for the central covenant object in the sanctuary.",
    "refs": [
      "Exodus 25:10"
    ]
  },
  "Exodus 37:2": {
    "title": "Gold covers the ark",
    "text": "The ark is overlaid with pure gold inside and outside, and a gold crown is made around it. The work follows the pattern specified in the instructions.",
    "refs": [
      "Exodus 25:11"
    ]
  },
  "Exodus 37:3": {
    "title": "Four gold rings",
    "text": "Four gold rings are cast for the ark’s feet. The rings will hold the staves used to carry it.",
    "refs": [
      "Exodus 25:12"
    ]
  },
  "Exodus 37:4": {
    "title": "Staves for carrying the ark",
    "text": "Staves of acacia wood are made and overlaid with gold. The ark is designed to be carried by the appointed means.",
    "refs": [
      "Exodus 25:13–14"
    ]
  },
  "Exodus 37:5": {
    "title": "Staves inserted into the rings",
    "text": "The staves are placed through the rings on the ark’s sides. The construction follows God’s instructions for handling and transport.",
    "refs": [
      "Exodus 25:14–15"
    ]
  },
  "Exodus 37:6": {
    "title": "The mercy seat is made",
    "text": "The mercy seat is made of pure gold with specified dimensions. It is the appointed place associated with God’s meeting with Moses above the ark.",
    "refs": [
      "Exodus 25:17–22"
    ]
  },
  "Exodus 37:7": {
    "title": "Two gold cherubim",
    "text": "Two cherubim are made of hammered gold at the ends of the mercy seat. They are part of the sanctuary design and are not objects of worship.",
    "refs": [
      "Exodus 25:18"
    ]
  },
  "Exodus 37:8": {
    "title": "The cherubim are made with the mercy seat",
    "text": "The cherubim are made at the two ends of the mercy seat as one piece. The work follows the exact design God showed Moses.",
    "refs": [
      "Exodus 25:19"
    ]
  },
  "Exodus 37:9": {
    "title": "Wings over the mercy seat",
    "text": "The cherubim spread their wings above and face one another, looking toward the mercy seat. Their posture frames the place from which God promised to speak.",
    "refs": [
      "Exodus 25:20–22"
    ]
  },
  "Exodus 37:10": {
    "title": "The table is made",
    "text": "Bezalel makes the table of acacia wood with the dimensions God prescribed. The table is part of the holy place’s furnishings.",
    "refs": [
      "Exodus 25:23"
    ]
  },
  "Exodus 37:11": {
    "title": "Gold overlays the table",
    "text": "The table is overlaid with pure gold and given a gold border. The construction follows the instructions given on Sinai.",
    "refs": [
      "Exodus 25:24"
    ]
  },
  "Exodus 37:12": {
    "title": "The table’s rim",
    "text": "A border of a handbreadth and a gold rim are made around the table. These details complete the prescribed edge of the table.",
    "refs": [
      "Exodus 25:25"
    ]
  },
  "Exodus 37:13": {
    "title": "Four gold rings",
    "text": "Four gold rings are cast for the table’s four corners. The rings will hold the carrying staves.",
    "refs": [
      "Exodus 25:26"
    ]
  },
  "Exodus 37:14": {
    "title": "Rings near the border",
    "text": "The rings are placed near the border to hold the staves used to carry the table. Their position is specified in the original pattern.",
    "refs": [
      "Exodus 25:27"
    ]
  },
  "Exodus 37:15": {
    "title": "Gold-covered staves",
    "text": "The table’s staves are made of acacia wood and overlaid with gold. They provide the appointed means of transporting the table.",
    "refs": [
      "Exodus 25:28"
    ]
  },
  "Exodus 37:16": {
    "title": "Gold utensils for the table",
    "text": "The dishes, spoons, bowls, and covers are made of pure gold. These utensils are for the table’s sacred service.",
    "refs": [
      "Exodus 25:29"
    ]
  },
  "Exodus 37:17": {
    "title": "The lampstand is made of pure gold",
    "text": "Bezalel makes the lampstand of hammered pure gold, including its shaft, branches, bowls, knops, and flowers. The lampstand is crafted according to God’s detailed design.",
    "refs": [
      "Exodus 25:31"
    ]
  },
  "Exodus 37:18": {
    "title": "Six branches extend from the shaft",
    "text": "Six branches extend from the lampstand, three on each side. The arrangement creates the prescribed form of the seven-lamp stand.",
    "refs": [
      "Exodus 25:32"
    ]
  },
  "Exodus 37:19": {
    "title": "Almond-shaped cups on the branches",
    "text": "Each branch has almond-shaped cups, knops, and flowers. The repeated decorative form is part of the lampstand’s unified design.",
    "refs": [
      "Exodus 25:33"
    ]
  },
  "Exodus 37:20": {
    "title": "Almond-shaped cups on the central shaft",
    "text": "The central shaft also has almond-shaped cups, knops, and flowers. The shaft and branches share the same pattern.",
    "refs": [
      "Exodus 25:34"
    ]
  },
  "Exodus 37:21": {
    "title": "Knops beneath the branches",
    "text": "A knop is placed beneath each pair of branches. The detail follows the original instructions for the lampstand’s construction.",
    "refs": [
      "Exodus 25:35"
    ]
  },
  "Exodus 37:22": {
    "title": "The lampstand is one piece",
    "text": "The knops and branches are made as one piece with the lampstand, all of pure hammered gold. The single structure fulfills the design shown to Moses.",
    "refs": [
      "Exodus 25:36"
    ]
  },
  "Exodus 37:23": {
    "title": "Seven lamps and tools",
    "text": "The lamps, tongs, and snuff dishes are made of pure gold. The verse includes both the lights and the utensils needed to tend them.",
    "refs": [
      "Exodus 25:37–38"
    ]
  },
  "Exodus 37:24": {
    "title": "A talent of gold",
    "text": "The lampstand and its utensils are made from a talent of pure gold. The amount records the material used in this sacred furnishing.",
    "refs": [
      "Exodus 25:39"
    ]
  },
  "Exodus 37:25": {
    "title": "The incense altar is made",
    "text": "The altar of incense is made of acacia wood with horns formed as one piece. It is a distinct altar for the incense service inside the sanctuary.",
    "refs": [
      "Exodus 30:1–2"
    ]
  },
  "Exodus 37:26": {
    "title": "The incense altar is overlaid with gold",
    "text": "The top, sides, and horns are covered with pure gold, and a gold crown is placed around it. The materials match the design God gave Moses.",
    "refs": [
      "Exodus 30:3"
    ]
  },
  "Exodus 37:27": {
    "title": "Gold rings for carrying the incense altar",
    "text": "Two gold rings are placed beneath the crown on opposite sides to hold the staves. The altar is designed to be carried when the tabernacle moves.",
    "refs": [
      "Exodus 30:4"
    ]
  },
  "Exodus 37:28": {
    "title": "Staves for the incense altar",
    "text": "The staves are made of acacia wood and overlaid with gold. They provide the prescribed means of carrying the altar.",
    "refs": [
      "Exodus 30:5"
    ]
  },
  "Exodus 37:29": {
    "title": "The holy oil and incense are prepared",
    "text": "The holy anointing oil and pure incense are made by a perfumer according to the prescribed recipe. The verse closes the chapter by confirming that the sacred materials are prepared as God commanded.",
    "refs": [
      "Exodus 30:22–38"
    ]
  },
  "Exodus 38:1": {
    "title": "The bronze altar is built",
    "text": "The altar of burnt offering is made of acacia wood with the dimensions God gave Moses. It is the main altar in the courtyard where Israel’s burnt offerings are presented.",
    "refs": [
      "Exodus 27:1"
    ]
  },
  "Exodus 38:2": {
    "title": "The altar’s horns and bronze covering",
    "text": "The horns are made as one piece with the altar, which is overlaid with bronze. The construction follows the pattern for the courtyard altar.",
    "refs": [
      "Exodus 27:2"
    ]
  },
  "Exodus 38:3": {
    "title": "Bronze utensils for the altar",
    "text": "The pans, shovels, basins, forks, and firepans are made of bronze. These utensils are required for the altar’s regular sacrificial service.",
    "refs": [
      "Exodus 27:3"
    ]
  },
  "Exodus 38:4": {
    "title": "The bronze grating",
    "text": "A bronze grating is made for the altar, with rings at its four corners. The grating is part of the altar’s prescribed construction.",
    "refs": [
      "Exodus 27:4"
    ]
  },
  "Exodus 38:5": {
    "title": "Rings for the altar’s carrying poles",
    "text": "Bronze rings are cast to hold the staves. The arrangement makes the altar portable for Israel’s wilderness journey.",
    "refs": [
      "Exodus 27:6–7"
    ]
  },
  "Exodus 38:6": {
    "title": "Bronze-covered staves",
    "text": "Staves of acacia wood are made and overlaid with bronze. They are used to carry the altar according to God’s instructions.",
    "refs": [
      "Exodus 27:6"
    ]
  },
  "Exodus 38:7": {
    "title": "The altar is made hollow",
    "text": "The staves are placed through the rings, and the altar is made hollow with boards. The construction matches the design previously shown to Moses.",
    "refs": [
      "Exodus 27:8"
    ]
  },
  "Exodus 38:8": {
    "title": "The bronze laver and women’s mirrors",
    "text": "The laver and its base are made of bronze from the mirrors of the women who assembled at the entrance of the tent of meeting. The verse records a specific source for the material; it does not explain the women’s exact role beyond this reference.",
    "refs": [
      "Exodus 30:17–21"
    ]
  },
  "Exodus 38:9": {
    "title": "The south courtyard hangings",
    "text": "The courtyard is enclosed with fine linen hangings on the south side. The measurements and supports follow the earlier instructions.",
    "refs": [
      "Exodus 27:9"
    ]
  },
  "Exodus 38:10": {
    "title": "Pillars and sockets for the south side",
    "text": "Twenty pillars and bronze sockets support the hangings, with silver hooks and bands. The details ensure the enclosure is securely built.",
    "refs": [
      "Exodus 27:10"
    ]
  },
  "Exodus 38:11": {
    "title": "The north side hangings",
    "text": "The north side is built with the same hangings, pillars, sockets, hooks, and bands as the south. The matching sides make the courtyard symmetrical.",
    "refs": [
      "Exodus 27:11"
    ]
  },
  "Exodus 38:12": {
    "title": "The west side hangings",
    "text": "The west end has hangings of the specified length and ten pillars with their sockets. The end wall uses fewer pillars than the long sides.",
    "refs": [
      "Exodus 27:12"
    ]
  },
  "Exodus 38:13": {
    "title": "The east side dimensions",
    "text": "The east side of the courtyard is the specified width. The following verses describe the sections and gate at this end.",
    "refs": [
      "Exodus 27:13"
    ]
  },
  "Exodus 38:14": {
    "title": "One side of the gate",
    "text": "One side of the entrance has fifteen cubits of hangings supported by three pillars and sockets. This forms one side of the central gate opening.",
    "refs": [
      "Exodus 27:14"
    ]
  },
  "Exodus 38:15": {
    "title": "The other side of the gate",
    "text": "The other side has matching hangings and supports. The two sections frame the gate symmetrically.",
    "refs": [
      "Exodus 27:15"
    ]
  },
  "Exodus 38:16": {
    "title": "Fine linen around the courtyard",
    "text": "All the hangings around the courtyard are made of fine linen. The completed enclosure follows the dimensions God prescribed.",
    "refs": [
      "Exodus 27:9–18"
    ]
  },
  "Exodus 38:17": {
    "title": "Pillars and sockets completed",
    "text": "The pillars’ sockets are bronze, while their hooks and bands are silver and their tops are overlaid with silver. The materials distinguish the fittings and complete the courtyard supports.",
    "refs": [
      "Exodus 27:10"
    ]
  },
  "Exodus 38:18": {
    "title": "The gate screen",
    "text": "The courtyard gate screen is made of embroidered colored yarn and fine linen, with specified dimensions. The entrance is marked by a screen matching the sanctuary’s sacred colors.",
    "refs": [
      "Exodus 27:16"
    ]
  },
  "Exodus 38:19": {
    "title": "Four pillars for the gate",
    "text": "The gate screen is supported by four pillars with silver hooks and bands and bronze sockets. The entrance structure follows the pattern given earlier.",
    "refs": [
      "Exodus 27:16–17"
    ]
  },
  "Exodus 38:20": {
    "title": "Bronze pins",
    "text": "The pins for the tabernacle and courtyard are made of bronze. These practical fittings secure the portable sanctuary and its enclosure.",
    "refs": [
      "Exodus 27:19"
    ]
  },
  "Exodus 38:21": {
    "title": "The tabernacle’s inventory",
    "text": "The chapter records the account of materials used for the tabernacle of testimony, compiled under the direction of Moses and the Levites. The inventory makes the work accountable and records how the materials were used.",
    "refs": [
      "Exodus 38:24–31"
    ]
  },
  "Exodus 38:22": {
    "title": "Bezalel does what God commanded",
    "text": "Bezalel son of Uri makes all that the LORD commanded Moses. The verse summarizes his faithful execution of the divine instructions.",
    "refs": [
      "Exodus 31:1–5"
    ]
  },
  "Exodus 38:23": {
    "title": "Oholiab works with Bezalel",
    "text": "Oholiab assists as an engraver, designer, and embroiderer in colored materials and fine linen. The work is shared by the skilled workers God appointed.",
    "refs": [
      "Exodus 31:6"
    ]
  },
  "Exodus 38:24": {
    "title": "Gold used for the sanctuary",
    "text": "The gold used for the work is counted according to the sanctuary measure. The inventory begins with the amount of gold contributed and used for the sanctuary.",
    "refs": [
      "Exodus 25:3"
    ]
  },
  "Exodus 38:25": {
    "title": "Silver from the census offering",
    "text": "The silver is counted from the congregation’s census contribution. The amount is recorded so the use of the people’s offering can be accounted for.",
    "refs": [
      "Exodus 30:11–16"
    ]
  },
  "Exodus 38:26": {
    "title": "Each counted person’s contribution",
    "text": "The account specifies the half-shekel contribution from those numbered, twenty years old and upward. The equal amount reflects the uniform requirement given in the census instructions.",
    "refs": [
      "Exodus 30:13–15"
    ]
  },
  "Exodus 38:27": {
    "title": "Silver sockets for the sanctuary",
    "text": "The silver is used to cast sockets for the sanctuary and the veil pillars. The inventory connects the contributed metal with the actual structural work.",
    "refs": [
      "Exodus 26:19–25"
    ]
  },
  "Exodus 38:28": {
    "title": "Silver for hooks and bands",
    "text": "The remaining silver is used for hooks, bands, and overlays on the pillars. The account records how the material was allocated beyond the sockets.",
    "refs": [
      "Exodus 27:10"
    ]
  },
  "Exodus 38:29": {
    "title": "Bronze from the offering",
    "text": "The bronze contributed is counted and recorded. The next verse lists the objects made from it.",
    "refs": [
      "Exodus 25:3"
    ]
  },
  "Exodus 38:30": {
    "title": "Bronze for sockets and altar utensils",
    "text": "Bronze is used for the sockets at the entrance, the bronze altar and its grating, and its utensils. The inventory shows the material’s use in the courtyard structures and sacrificial equipment.",
    "refs": [
      "Exodus 27:1–8"
    ]
  },
  "Exodus 38:31": {
    "title": "Bronze sockets and pins",
    "text": "Bronze is used for the courtyard sockets and the pins of the tabernacle and courtyard. The account closes by listing the practical fittings made from the contributed bronze.",
    "refs": [
      "Exodus 27:19"
    ]
  }
};
